local _, WFJ = ...
WFJ.Data.add("quest", {
  [1] = { "「Chow」クエスト (123)aa", "Kobold Verminを2体倒す。", "Kobold Verminを$N1体倒せ。NEW TEST AGAIN", nil, nil, 0xdb0905c3, 0x314b469d, 0x671a32c1, nil, nil, "...mm" },
  [2] = { "Sharptalon's Claw", "AshenvaleのSplintertree PostにいるSenani ThunderheartにSharptalon's Clawを持って来て下さい。", "強力なhippogryph Sharptalonは殺されました、打ち倒された野獣の鉤爪があなたの勝利の証となります。 Splintertree PostのSenani Thunderheartは、間違いなくこのトロフィーをあなたの行為の証拠と考えたくなるでしょう。", "ええ、偉大なる{class}よ、あなたが来るのを感じていました。狩りについて、また報告してくれることがあるのでしょう？", "実に見事だ、{name}……Sharptalonの爪を手に入れるのは容易ではなかったはずだ！Ashenvale Huntは順調のようだな！\n\nSharptalonは長いこと、その通り道の近くにある伐採キャンプからここSplintertree Postへ向かおうとする労働者たちを脅かしてきた。あの獣を仕留めたのがお前だと知れ渡れば、きっとAshenvale中の焚き火や製材所で、お前の勇敢さをたたえる勇ましい歌がいくつも聞かれることだろう！", 0xd311f9a5, 0x0ed5211e, 0x0d8319c7, 0x4dd41a0e, 0xfc0f918c, "....." },
  [5] = { "腹ぺこJitters", "Chef Grualと話して下さい。", "もう何週間もこのゴーストタウンに隠れっぱなしで、虫の幼虫と雑草しか食べてないんだ！まともな食べ物が欲しい。いい条件で取引するよ。\n\nごちそうを持ってきてくれたら、たっぷり払うよ。\n\nDarkshireのScarlet Raven TavernにいるChef Grualが、とても美味しいDusky Crab Cakesを作るって聞いたんだ……", nil, "Crab Cakeがほしいのかい? まあ作ってあげられないこともないけど……", 0x13753190, 0x3c550677, 0xb656ff77, nil, 0x9ca7596b, "...m." },
  [6] = { "賞金首Garrick Padfoot", "Garrick Padfootを抹殺し、奴の首をNorthshire AbbeyにいるDeputy Willemに渡すんだ。", "Garrick Padfoot…こいつは、この何週間か、ここに住む農民や商人から恐れられている人殺しだ。居場所は既に突き止めている。この修道院から東の橋を越えた辺りに広がる葡萄畑近くの小屋がそうだ。さあ、この外道の首をもってくるのだ！\n\n用心しろよ、{name}。Garrickには常に側近がついているからな。厳しい任務になることは間違いないだろう。", "Garrickの小屋は見つかったか？ついにあの悪党から解放されたのか？", "ハッハッハ！よくやった！お前はこのElwynn地方で素晴らしい働きをしたんだ！さあ、賞金を受け取るんだ！", 0xd9a1ea2f, 0xb35875a3, 0x674275ec, 0xe205dce0, 0x8edda1cf, "....." },
  [7] = { "Koboldキャンプの掃討", "Kobold Verminを10匹殺して、Marshal McBrideへ報告してください。", "{name}、掃討が最初の仕事だ。Koboldの一団が北の森にはびこっている。そこへ行きKoboldを殺してくるのだ。Northshireから彼らを駆逐し、数を減らすのだ。", "狩りの具合はどうだ、{name}？あの害獣どもを見つけて倒したか？", "よくやった！Koboldどもは盗みを働くし、臆病だが数が多くなると脅威なのだ。Stormwindの人々にはこれ以上の脅威が増えるのは困るのだ。\n\n彼らを退治してくれて、感謝しているぞ。", 0x5d10a531, 0xc0a62578, 0x54635c79, 0x4eb51373, 0xb52dae46, "....." },
  [8] = { "Rogueの取引", "Nondescript LetterをTirisfal GladesにいるInnkeeper Reneeに届けてください。", "よう、相棒！ 頭の空っぽなゾンビやクモと人一倍戦ってきた若者に、ひとつ頼まれてくれないか？\n\nBrillに届けなきゃならない手紙がここにあるんだ……Reneeなんとかって名前の宿屋の主人宛てだ。名字なんてどうだっていいさ。\n\nとにかく、そこはこぢんまりとした居心地のいい所で、疫病の犠牲者たちが世の中でなんとかやっていこうとしてる。必要なら、あんたが休むにもいい場所だ。行ってみるといい……行ってくれたら、たっぷり払うぜ。", "はい？はい？何かしら？\n\nforsakenって、本当にものすごい食欲なのよね。くつろいでいって……そう、その疲れた骨を休めてちょうだい。何か必要なら、私の名前はReneeよ。", "おや？手紙だって？素晴らしい知らせだ！Deathknellにいる愛しい年老いた母からの便りを待っていたんだ。まったく聖人のような人でね。元気にしているだろうか。\n\nなんだ？明るすぎるって？信じちゃいないんだろう？\n\nなら、とっとと失せな……どうせ誰からの手紙だろうと、お前には関係ないことだ。ほら！失せろ！\n\n使う金ができたらまた来な……怠け者め。\n\nそのうち、長い一日の冒険を終えて休みに戻ってくるだとか、そんな馬鹿げたことになるんだろうよ。", 0x824c6911, 0xb1b93800, 0x71981765, 0x1ea589a5, 0x6285e1f4, "....." },
  [9] = { "殺戮の地", "Harvest Watcherを２０体殺す。", "ここで何が起こっているか知ってるか！この地方は、かつては平和な農村地域だったさ。でもな、くそったれの賊共がメチャメチャにしやがったんだ！そして、この俺の畑には、Harvest Watcherの奴らがのさばっている。\n\nお前さんが仕事を探してるのなら、Harvest Watcher共を20体殺してくれないか。やり遂げてくれたら、それなりの報酬を払う。ついでに、この仕事を終えたら、近所の畑にもいる奴らも一掃してくれや。", "おお、戻ってきたか！あの畑のHarvest Watcherどもを一掃しようと、せっせと働いてくれていたならいいが。もう20体は倒したか？", "すげえよ、あんた。これが報酬だ。ひょっとすると、またいつかのような平和な時代が来るのかもしれねえな。", 0xe8dc51f9, 0xb1fcb3e9, 0xc49a0580, 0x0e0d21d8, 0x9ce4bf4e, "....." },
  [10] = { "Scrimshankの救出", "Junior Surveyor Scrimshankの安否を確認し、彼もしくは調査器具のどちらか一方をGadgetzanのSenior Surveyor Fizzledowserに引き渡して下さい。", "ああ、これは本当にひどい！一番の助手のJunior Surveyor Scrimshankを、ここから南東の砂漠に送り出したんだ。Gaping Chasmと呼んでいる場所さ。ところが彼が行方不明になってしまってね。最後の報告では、彼のいたあたりにあの奇妙な虫がもっといたそうだ。砂漠の主要な2つの地域に、もう虫がはびこってしまったってことだろうか？\n\nGaping Chasmへ行って、Scrimshankを探してほしいんだ、頼む！それか……せめて彼の測量道具だけでも見つけてくれ。気の毒なあいつの残したものは、もうそれだけかもしれないからね。", "さて、どんな知らせだ？ずいぶん激しい戦いをしてきたようだが……Scrimshankは生きているのか？", "いいゴブリンだったよ、若いScrimshankは。あいつが測量機材で記録できたものによって、あいつの死が無駄にならなかったと願おう。\n\nどうやらこの虫どもには、かなり厄介な状況を抱えているみたいだ。あいつらは身のためにならないほど狡猾だし、これまでの調査からすると、第三者の支配を受けている可能性さえあるって結果が出つつあるんだ! もしそうなら、Gadgetzanだけじゃなく、砂漠全体にとって不吉なことだよ!", 0x3080a35e, 0x42f02dc4, 0x9f6ecdba, 0x028ed454, 0x623328a6, "....." },
  [11] = { "Riverpaw Gnollの賞金首", "8個のPainted Gnoll ArmbandをDeputy Rainerに持ってきてください。", "Gnollという粗野な生き物をElwynn Forestの境界に沿って見ることができます。我々だけで相対するには多すぎる一団が、南のガードタワー近辺にはびこっています。他にもStone Cairn Lakeの近くにいます。\n\nStormwind Armyは彼らを殺す何者でも歓迎します。彼らのPainted Gnoll Armbandをあなたの功績の証として、持ってきてください。", "やあ、{name}。Gnollどもを倒してきたか……？", "忙しかったようだね！ありがとう、{name}。", 0x9b53bb87, 0x8f6713f0, 0x9259d68e, 0x11769f64, 0xc6ac4114, "....." },
  [12] = { "人民軍", "Defias TrapperとDefias Smugglerを各１５人ずつ殺し、Sentinel HillにいるGryan Stoutmantleに報告する。", "People's Militiaの目的はただひとつ。Westfallの地を守り、この一帯に平和を取り戻すことだ。残念ながら、平和の代償は多くの場合、血だ。\n\n私の斥候の一人が、Defias Trappersの一団がこの近くで暴れ回っているという知らせを持ち帰った。NorthwestのJangolode Mineの近くのほか、Molsen FarmやFurlbrow's Pumpkin FarmでもDefias Trapperが目撃されたという報告がある。我々の仲間に加わりたいなら、Defias Trapperを15人とDefias Smugglerを15人倒し、私のところへ戻ってこい。", "どうやら言い方がはっきりしていなかったようだな、志願者よ。The People's Militiaと光に仕える者としての価値を証明するには、Defias Trapperを15体とDefias Smugglerを15体倒し、それを果たしたら私のもとへ戻ってこなければならん。", "よくやった、{name}。偵察隊の人間が、君の勇敢な戦いを目撃していたようだ。これで君の実力が証明されたわけだ。", 0xe151209f, 0x16896ec7, 0x8596ea3e, 0xecfd7c3c, 0x84930ba2, "....." },
  [13] = { "人民軍", "Defias PillagersとDefias Lootersを各１５人ずつ討伐し、Sentinel HillにいるGryan Stoutmantleに報告する。", "悪質な集団であるDefias PillagersはGold Coast QuarryやMoonbrook、そしてAlexston Farmsteadで略奪行為をしている。人民軍はそのような振る舞いは許すわけにはいかない。急いでくれ、{name}よ。 そしてWestfallに希望の光を与えてくれ。\n\nGold Coast Quarryは塔の西、海岸近くにある。次の段階として汚いDefias PillagersとDefias Lootersを１５人ずつ討伐して欲しい。", "話している暇はないぞ、{name}。Defias PillagerどもがWestfallの民から、彼らが享受すべき平和と繁栄を奪っているのだ。少なくともDefias Pillagerを15体とDefias Looterを15体、確実に倒してこい。そうすれば、腐敗はここでは歓迎されないというはっきりとした警告になる。", "これまでの君の勇敢な行いは人民軍にとって価値のあるものとなるだろう。", 0xe151209f, 0x6d788fcc, 0x1eea16a0, 0x687557dd, 0xb859c405, "....." },
  [14] = { "民兵団", "Defias Highwaymenを15体、Defias Pathstalkerを5体、Defias Knuckledusterを5体倒してから、Sentinel Hillにいる自分のところへ戻ってきてほしいとGryan Stoutmantleは言っています。", "Defiasの一部が我々の手を逃れた。私の最も信頼する斥候の報告によれば、そのDefiasどもは田園地帯を荒らし回り、略奪を重ねながらSouthern Westfallにまで入り込んでいるという。奴らはDagger Hillsに潜伏し、次の手を練っていると我々は見ている。People's Militiaの名において、その悪党どもを討て。", "{name}、無駄話をしている場合ではない。まだThe People's Militiaに自らを証明したいのなら、先に伝えたDefiasどもを倒さねばならん。務めを果たしたら私のもとへ戻れ。", "汚れたLordaeronの地を後にした私が故郷に戻ってみると、ここは惨憺たる有様だった。だがWestfallにはまだ希望がある。戦いで示した君の勇気を見れば、君が名誉をもって我らの大義に仕えていることは明らかだ。大いなる誇りをもって、君をThe People's Militiaに迎え入れよう。光が君を照らさんことを。", 0xe151209f, 0x78ad5d7f, 0xab47f493, 0xa480f62a, 0xf947b26e, "....." },
  [15] = { "Echo Ridgeの調査", "Kobold Worker を10匹倒して、Marshal McBride のところに戻って報告してください。", "{name}、密偵からの報告によると Kobold の群れの横行が我々の予想以上のようです。Kobold worker の群れがここから北の Echo Ridge Mine に巣食っています。\n\n鉱山(Mine)に行き、やつらを退治してください。少なくとも10匹はいるようです。10匹倒した後、群れの数がもっと多いようなら戻って私に報告してください。", "鉱山には行ってきたか？報告の準備はできているか？", "我々の鉱山にそんなに多くの Kobold がいたとは由々しき事態です。このままでは良くないことが起きるかもしれません。とりあえず今回の報酬としてこれを受け取って下さい。そして準備が整ったら再度私に話しかけてください。もう一度鉱山に向かってほしいのです・・・。", 0xb43a6289, 0xa368f704, 0x2cb816b5, 0x063df25d, 0xf0b6a1c7, "....." },
  [16] = { "Gerard に飲み物を", nil, nil, "農作業は喉が渇く仕事でね、いつもrefreshing spring waterを探しているんだ。\n\nもし持っているなら、喜んで取引するよ。", "ありがとう、{name}! また交換したかったら来てくれよ。", 0x8a697a25, nil, nil, 0x6a289e06, 0x46e9e47e, ".mm.." },
  [17] = { "Uldaman リエージェント・ラン", "Magenta Fungus Cap 12個をThelsamarのGhak Healtouchに渡して下さい。", "新しく見つかったmagenta fungus capsという植物の話を聞いたんだ。群生していて、Uldamanの発掘現場の奥深くに生えている。他の場所にもあるかもしれないが、今のところ生えていると分かっているのはそこだけだ。錬金術に使えるかどうか研究したくてね、そこで君の出番というわけだ。\n\nmagenta capの群生を見つけて、capsを12個持ってきてくれ。気をつけて、群生を揺らすと毒の胞子を吹き出すかもしれないよ。\n\nこれをやってくれたら、私の自慢の回復のエリクサーをひと瓶こしらえてあげよう！", "錬金術の研究に必要なmagenta fungus capsは手に入れてくれたかい？capsがなければ報酬もなしだよ！", "よくやった、{name}、またしてもその力量を示したな！このキノコの傘は実に興味深い研究対象になるぞ、まことにな！\n\nさて約束通り、私の秘蔵の中でもとりわけ効き目の強い回復薬を味わってくれ……\n\nもし君が腕の立つ錬金術師なら、もう少し取引ができるかもしれん。ともあれ、助力に感謝する！", 0xec9c87f2, 0xf9b7baaa, 0xf40372d4, 0x3dc33ca7, 0x6da9f6fe, "....." },
  [18] = { "盗賊集団", "Northshire Abbeyの外にいるDeputy Willemに、Red Burlap Bandanasを12束渡す。", "最近、Defias Brotherhoodという新手の盗賊一団が、Northshireの東の川沿い辺りをうろついているらしいのだ。\n\n奴らが何を企んでいるかは分からんが、嫌な予感がする！\n\n奴らを殺し、身に着けているバンダナをもってきてほしい。報酬として武器を用意しよう。", "もうあのbandanasは集めてくれたか？", "バンダナを持って戻ってきたようだな。Stormwind軍から感謝の意を表しよう。", 0x2f1eb64e, 0x0376329b, 0x0ff5818f, 0x59c5a6d0, 0x9eec7aad, "....." },
  [19] = { "Tharil'zun", "Tharil'zun's HeadをRedridgeのMarshal Marrisのところへ持って行く。", "Blackrock OutrunnersとRenegadesが、ここからStonewatch Keepまでの間で待ち伏せを仕掛けている。Outrunnersの頭はTharil'zunというオークだ――そいつが狙いだ。Tharil'zunの首を持ってこい！", "Blackrockからのオークの圧力は依然として厳しい。だが、せめてTharil'zunは片付けてくれたのか？", "Tharil'zunは凶暴で狡猾なオークだった。よくやった――奴は簡単には倒れなかっただろう。これが君の報酬だ、{name}。", 0x22ab2f51, 0x7c13c137, 0x8b3cf21c, 0x55e47621, 0x3c4e5d23, "....." },
  [20] = { "Blackrockの脅威", "Battleworn Axeを10個、LakeshireのMarshal Marrisのところへ持って行く。", "Blackrockのオークどもは、Burning Steppesからやって来て北のStonewatch Keepを奪った。奴らはそこを拠点にLakeshireの北の一帯を荒らし回り、住民たちを家畜のように町に閉じ込めている。\n\nLakeshireからこの脅威を取り除く手助けをしてくれ。Blackrockのオークどもを倒し、証拠として奴らのBattleworn Axesを10本持ってくるのだ。\n\nそれに、Blackrockどもは北から我々を脅かしているが、Redridgeの南東の一角にもさらに奴らがいるとの報告が入っている。そこで見つけたなら、そいつらも狩ってくれ。", "オークどもを倒してきたか、{name}？そうなら、証を見せてくれ……", "これで心配しなきゃならないオークがずいぶん減ったよ、ありがとう。", 0xeb0d5482, 0x427516c3, 0xdcc24f55, 0x9b1e452c, 0x1c8fce29, "....." },
  [21] = { "Echo Ridge の掃討戦", "Kobold Laborer を12匹倒して、Northshire Abbey の Marshal McBride のところに戻ってください。", "あなたが前回実施してくれた調査で、Echo Ridge Mine の大掃除が必要なことがわかりました。鉱山(Mine)に戻って Kobold の群れの掃討を手伝ってください。\n\n急いでください、{name}。これ以上 Kobold どもを鉱山に野放しにしておくと、やつらは鉱山を拠点にしてさらに深く Northshire に侵攻してくるでしょう。", "血なまぐさい仕事なのは分かっている、{name}。だがNorthshireの安全には欠かせないのだ。報告の準備はできたか？", "あなたの活躍に敬意を表します。また、Stormwind 軍からも感謝の念を。Kobold はまだ鉱山に残っているようですが、やつらの掃討には別の義勇兵を派遣します。あなたにはもっと重要な任務についてほしいのです。", 0xa7a12dbe, 0x26b99d1f, 0xeb16bc2b, 0xf565255c, 0x019e5401, "....." },
  [22] = { "Goretusk Liver Pie", "Goretusk Liver Pieの調理食材であるGoretusk liver８個をSalma Saldeanに届ける。", "玉ねぎの皮をむいて、ニンニクを細かく刻んで、ローズマリーをつぶして、パイ生地を焼いて、ディルの葉を切って、肉汁を煮たせる、と。あとはGoretusk Liverを８個用意すれば、有名なミートパイができあがるわ！", "私の名物ミートパイに必要なのは、Goretusk Liver 8個だけだよ！", "すばらしい食材よ、{name}！ありがとう。今夜はすばらしいご馳走をFarmer Saldeanと食べることになるわ。あ、これはあなたの分よ。お勤めご苦労様。私がお腹を空かせている{class}さんに、用意していなかったと思った？", 0x8e33704e, 0x0a34a00f, 0xa7490995, 0xe421b346, 0x2f880112, "....." },
  [23] = { "Ursangous's Paw", "Ursangous's PawをAshenvaleのSplintertree PostにいるSenani Thunderheartのところへ持って行って下さい。", "<Ashenvale Huntのこの段階での戦利品は、強大な熊Ursangousのpawだ。pawには小さな四分の一の三日月形の紋章がある。その紋章の意味は謎のままだ。\n\nこの強大な獣を打ち負かし、狩りのこの段階を終えたことを証明するため、pawをSplintertree PostのSenani Thunderheartに届けること。>", "おお、{name}、ちょうど君のことを考えていたところだ！狩りの調子はどうだい？", "それは、Ursangousの前足! 大した腕前だ、{class}。Ursangousは仲間を何人も殺したとされている。前足の三日月模様は間違いなく、Ashenvaleに潜むナイトエルフによって訓練された証。Ursangousはこの地域にいる最も強い熊……だった。こういった生き物を倒すことは、お前の精神力と意志の証拠だ。\n\nお前の先祖も誇らしく思うことだろう!", 0xa9132297, 0xe5f93b0e, 0x8d898f17, 0x060f3631, 0xb2ec6d11, "....." },
  [24] = { "Shadumbra's Head", "Shadumbra's HeadをAshenvaleのSplintertree PostにいるSenani Thunderheartのところへ持って行って下さい。", "かつては素早かったShadumbraも、あなたが勝利を収めた今は静かに横たわっている。倒したnightsaberの頭は、Ashenvale Huntのこの戦いにふさわしい戦利品だ。Splintertree PostのSenani Thunderheartは、Ashenvale Huntのこの部分の功績を認めるために、この戦利品を見たがるだろう。", "またお会いしましたね、{name}！狩りの証を見せに来てくれたのですか？", "Ashenvale Huntにおける{name}の勝利だ！よくやった——あれほど見事な戦いの末に掲げる戦利品として、Shadumbraの頭はふさわしい。\n\nShadumbraの獰猛さは、この駐屯地では広く知られていた。西へ向かう旅、とりわけ徒歩でZoram Strandへ抜けようとする者は、この虎のせいで常に危険にさらされていた。お前のおかげで、その危険は和らいだ。", 0x337fe567, 0xc190c862, 0xf9f1000a, 0x11d924fd, 0xd2710e6b, "....." },
  [25] = { "Stonetalonの足止め", "Talondeep Pathの真東、Splintertree Postの南西にあるMystral Lakeで、１２体のBefouled Water Elementalを片付けてください。\n\nMystral Lakeの東屋でAlliance居留地の様子を偵察してください。\n\nAshenvaleのSplintertree PostにいるMastok Wrilehissのところへ戻ってください。", "もし何か役に立ちたいなら、 Talondeep Pathの状態について何かしたらどうだ？\n\nAshenvaleとStonetalon間の輸送は停止状態にある、なぜなら近づくと動き出し攻撃してくる湖のせいだ・・・つまり道を通る誰もが襲われるってことだ。water elementals を叩くよりもっと有益なのは、Mystral Lake上の東屋を偵察することだ・・・そこはAllianceの居留地がよく見える。\n\nお前は役に立つのだろう？", "もう戻ったのか？向こうの様子はどうだ、君のおかげですっかり片付いたか？", "ああ、Barrensを吹き抜けるつむじ風のように、誰かがあの湖を荒らしたと聞いたぞ。話を聞く限りでは、Allianceの友人どもを見張るための観測地点をあそこに設けられるかもしれん。まあ、それを内密にしておければの話だがな……\n\n結局、お前はなかなか役に立ったようだな。こことStonetalonの間の輸送も楽になるだろう。これを受け取れ——お前が稼いだものだ。", 0xced629b9, 0xaeb13247, 0x827ebbec, 0x1dfb053a, 0x0d2cc7d3, "....." },
  [26] = { "習得のための修行", "Moongladeのvillage of NighthavenにいるDendrite Starblazeと話して下さい。", "{name}、あなたが腕を上げる様子を見守っていると、とても嬉しいのです。力ある自然の庇護者へと大変確実に成長を遂げていますね。\n\n数多ある動物の姿から、あるものを習得する時がきました。それは、Cenariusが授けて下さった変身能力……水を支配し自由に扱う力です。そのために、Moongladeのvillage of Nighthavenへ旅をし、Cenarion CircleのメンバーDendrite Starblazeと話をしなくてはなりません。彼なら、さらなる高みへと導いてくれるでしょう。", nil, "ご機嫌麗しゅう。若き{class}よ。aquatic formを知る時がきたのだな。いつまでも自由に、水の中を動き回ることができるものだ。この姿は役立つ手段であり、恩寵であることが分かるだろう……だが、それを習得する前にやらねばならぬことがある。\n\n乗り越えるべき二つの試練に立ち向かうことになろう。まず始めに、水圧の中で動く能力を試す。次に、aquatic formそのものの特徴を理解する決意を試す。\n\n準備せよ、我らは今、試練の時にある。", 0xab90ac10, 0x127a78ca, 0x21ea754f, nil, 0x058b67b8, "...m." },
  [27] = { "習得のための修行", "Moongladeのvillage of NighthavenにいるDendrite Starblazeと話して下さい。", "{name}、あなたが腕を上げる様子を見守っていると、とても嬉しいのです。力ある自然の庇護者へと大変確実に成長を遂げていますね。\n\n数多ある動物の姿から、あるものを習得する時がきました。それは、Cenariusが授けて下さった変身能力……水を支配し自由に扱う力です。そのために、Moongladeのvillage of Nighthavenへ旅をし、Cenarion CircleのメンバーDendrite Starblazeと話をしなくてはなりません。彼なら、さらなる高みへと導いてくれるでしょう。", nil, "ご機嫌麗しゅう。若き{class}よ。aquatic formを知る時がきたのだな。いつまでも自由に、水の中を動き回ることができるものだ。この姿は役立つ手段であり、恩寵であることが分かるだろう……だが、それを習得する前にやらねばならぬことがある。\n\n乗り越えるべき二つの試練に立ち向かうことになろう。まず始めに、水圧の中で動く能力を試す。次に、aquatic formそのものの特徴を理解する決意を試す。\n\n準備せよ、我らは今、試練の時にある。", 0xab90ac10, 0x127a78ca, 0x21ea754f, nil, 0x058b67b8, "...m." },
  [28] = { "湖の試練", "Lake Elune'araでShrine Baubleを見つけ、Moonglade北西のShrine of Remulosへ持って行って下さい。そこでShrine Baubleを使って下さい。\n\nその後、試練を終えるにはShrine of RemulosのTajarriと話して下さい。", "最初の試練として、Lake Elune'araの水底を調べ、Shrine Baubleを捜し出すのだ。あれは急速に腐食していくゆえ、続いてShrine of Remulosへと迅速に事を運ばなくてはならない。聖地で宝物を使い、あそこにいるTajarriと話すのだ。彼女はMoongladeで最も信頼のおける番人のひとりだ。\n\nこれを終えるための時間は限られている。そして、宝物を捜す他のドルイドとの競争になるだろう。成功するには、精神的肉体的な器用さが重要となる。\n\n幸運を祈る、{name}。", "Trial of the Lakeを終えるには、この祠の境界の内側でShrine Baubleを使わなければなりません。それを行うまで、あなたの試練は未完了のままで、失敗するおそれがあります。", "さてさて。またひとり、{class}が湖の試練を首尾良く終えたようですね!　よくやりましたね。若き友よ、よくやりました。\n\n申し上げたように、私はTajarriといいます。Moonglade、特に聖地の番人を務めることは私の責務であり、名誉でもあります。守護者Remulosは自然と均衡の維持へとCenarion Circleを導いています。彼の聖地はそういった永遠性のあかしとしての役目を果たしているのです。ここで宝物を使うことによって、この場所の重要性への賛同としてCenarion Circle内で機能しています。", 0xee209044, 0x40c0c195, 0x38927bd5, 0x95bbb916, 0x88cadd95, "....." },
  [29] = { "湖の試練", "Lake Elune'araでShrine Baubleを見つけ、Moonglade北西のShrine of Remulosへ持って行って下さい。そこでShrine Baubleを使って下さい。\n\nその後、試練を終えるにはShrine of RemulosのTajarriと話して下さい。", "最初の試練として、Lake Elune'araの水底を調べ、Shrine Baubleを捜し出すのだ。あれは急速に腐食していくゆえ、続いてShrine of Remulosへと迅速に事を運ばなくてはならない。聖地で宝物を使い、あそこにいるTajarriと話すのだ。彼女はMoongladeで最も信頼のおける番人のひとりだ。\n\nこれを終えるための時間は限られている。そして、宝物を捜す他のドルイドとの競争になるだろう。成功するには、精神的肉体的な器用さが重要となる。\n\n幸運を祈る、{name}。", "Trial of the Lakeを終えるには、この祠の境界の内側でShrine Baubleを使わなければなりません。それを行うまで、あなたの試練は未完了のままで、失敗するおそれがあります。", "さてさて。またひとり、{class}が湖の試練を首尾良く終えたようですね!　よくやりましたね。若き友よ、よくやりました。\n\n申し上げたように、私はTajarriといいます。Moonglade、特に聖地の番人を務めることは私の責務であり、名誉でもあります。守護者Remulosは自然と均衡の維持へとCenarion Circleを導いています。彼の聖地はそういった永遠性のあかしとしての役目を果たしているのです。ここで宝物を使うことによって、宝物はCenarion Circle内で聖地の永遠性に対する賛同として役割を果たしています。", 0xee209044, 0x40c0c195, 0x38927bd5, 0x95bbb916, 0x88cadd95, "....." },
  [30] = { "アシカの試練", "Half Pendant of Aquatic AgilityとHalf Pendant of Aquatic Enduranceを見つけて下さい。それがありそうな場所の手がかりを得るため、Moongladeの住人と話して下さい。\n\nペンダントの片割れを組み合わせ、Pendant of the Sea Lionを作って下さい。そうするためには、Shrine of Remulosの近くにいる必要があります。\n\nつなぎ合わせたペンダントをMoongladeのvillage of NighthavenにいるDendrite Starblazeのところへ持って行って下さい。", "第二の試練として、Pendant of the Sea Lionを作る片割れふたつが要ります。半分はなめらかに水の中を泳ぐアシカの敏捷性から力を引き出し、もう半分はアシカの驚くべき持久性から力を引き出します。彼ら水生動物の特性を具現化した姿に違わず、その特徴の両方をドルイドは利用することができるのです。\n\nMoongladeの人たちにペンダントの片割れがどこにあるか聞いて下さい。そしてつなぎ合わせるために、両方ここへ持ってくるのです。出来上がったら、ペンダントをDendrite Starblazeのところへ持って行って下さい。", "私が確かめられるよう、ペンダントは作り上げましたか、{name}？部品のありかを探すのに助けが必要なら、この土地の人々に尋ねてみるとよいでしょう。探しているものが見つかるだけでなく、この素晴らしく神聖な林を探索するきっかけにもなりますよ。", "{name}、アシカの試練は終わった。おめでとう。\n\nペンダントを作るのに求められた課題が示している敏捷性と持久力のふたつは、水の中で動きたいという望みと一致する無くてはならぬものだ。どちらも、一方無くして存在することはできない。そしてどちらも、アシカの特性を受け入れようという意志が無くては行えないのだ。\n\nこの修行をよく覚えておき、aquatic formを得た後も、心のよりどころとしてほしい。", 0x5cc8ed68, 0xdf177053, 0x23c219a5, 0x3520b13e, 0xb90d61f2, "....." },
  [31] = { "Aquatic Form", "Thunder Bluffへ戻り、Turak RunetotemにPendant of the Sea Lionを見せて下さい。", "駆け出しのドルイドが水生動物の姿を身につける前に教わる必要な修行は、すべて終わった。さあ、Thunder BluffのTurak Runetotemのところへ戻りなさい。彼にそのペンダントを見せ、教わるべきものを習得する準備ができていると示すのだ。習得が済めば、水と一体となることができよう。\n\nさらば、若きドルイドよ。再び語り合おう。", "あなたがThunder Bluffへ戻ってくることは知らされていました。ですが、あなたにaquatic formを教える前に、Moongladeで学んだ教えの証を見せてもらわなければなりません。\n\nPendant of the Sea Lionは持っていますか？", "大変見事です、{name}。この進歩をあなたのご先祖も喜んでいることでしょう!　aquatic formを習得する準備ができていますね。これを伝えることができて、私も嬉しいですよ。\n\nまた、二つの試練の功績を認め、この品を差し上げましょう。自然の庇護者、均衡の番人としての装備に加えれば、きっと喜んでいただけると思います。", 0xb41f2b6a, 0x3327253f, 0x19914008, 0xe6d7ebbe, 0xf05b6e02, "....." },
  [32] = { "Silithidの発生", "報告書をOrgrimmarのZilzibin Drumloreのところへ持って行って下さい。", "これが君の報告書だ。この類のことに実用的な知識を持っている人に、これを渡すようにね。\n\nZilzibin Drumloreという名のトロルの学者を知ってる。彼はAzerothの生態系で独特な生物の研究に多くの時間を費やしてきたし、おまけに歴史家なんだ! この脅威がいったい何なのか、どうやって止めるかを理解するのを誰かに助けてもらいたいなら、彼にこの報告書を渡すんだ。得られるすべての助けが必要なんだ。\n\nZilはOrgrimmarのDragの二階にある家に住んでるよ。", "すまないが、君のことは知らない……だが様子からすると、少なくとも私について何か聞いたことはあるようだな。さて、何の用だ？私に何か渡すものがあるのか？", "この報告書……この獣は以前扱ったことがある。これと君とを送ってくるとは、Fizzledowserは賢いな。\n\nこの生物はTanaris砂漠を急速に破壊するだろう。こいつらは我々が直面する脅威の中でも、最も大きな脅威に他ならない。{name}、この名前に慣れてくれ……silithidだ。この昆虫はここではsilithidと呼ばれていて、HordeとAllianceの双方が直面する最大の脅威のひとつなんだ。\n\nもっと前にこいつらを理解するほど賢ければよかったんだが。", 0x50a8e84e, 0x3d49ea7a, 0x31ea3237, 0xb6690bf0, 0xe82cecbc, "....." },
  [33] = { "国境の狼", "Northshire Abbeyの外にいるEagan Peltskinnerに、Tough Wolf Meatを8切れ持ってくる。", "僕はね、あの醜いTimber Wolfが大嫌いなんだ！　でもね、オオカミのステーキは大好きなんだよ…\n\nま、まあ、それはさておき、僕にtough wolf meatを持ってきてくれないかな。お礼に、君にとって何か便利になりそうなものをあげるよ。\n\nTough wolf meatはね、Timber Wolfやそこら辺をうろついているYoung Wolfから獲れるよ。", "やあ、{name}。腹が減ってきたよ……tough wolf meatは手に入ったかい？", "グッジョブ！オオカミ肉を早く料理したくて、ウズウズするよ…\n\nあ、報酬だったね。はいどうぞ！", 0xf2272f07, 0xdf199ead, 0x5ce8cfac, 0xf5cb8e2e, 0x63c80a97, "....." },
  [34] = { "招かれざる客", "Bellygrubを倒してほしいとLakeshireのMartie Jainroseは言っています。証拠としてその牙を彼女のところへ持って行く。", "またしても私の庭が踏み荒らされて、めちゃくちゃにされた。犯人の乱暴者は分かっているんだ。あの忌々しい猪、Marshal MarrisがBellygrubと呼ぶようになったあいつだよ。\n\nこれで来シーズンまで水仙を植え直せない。台無しだ！ あの厄介な猪一頭に、全部台無しにされた！ あの害獣を始末してくれ！ あいつの牙を見せてくれたら、喜んでお礼をするよ。あいつはたいていLakeshireの南西の畑で餌をあさっているけど、時々こっちまでうろついてきて私の庭に入り込むんだ。", "Bellygrubはまだ暴れているのか、それとも、あの厄介者をLakeshireからきっぱり追い払えたのか？", "ついにあの厄介者を葬ってくれたんだね! ありがとう、{name}、本当に助かったよ。今年は庭じゅうに花が満開になるだろう!", 0x5c809bb5, 0xabb3c5cc, 0xd5dec96a, 0x26e466ea, 0x3fd295c2, "....." },
  [35] = { "更なる懸念", "Guard Thomasと話をする。", "murlocの噂が本当ではないかと心配なら、こうするといい――Elwynnの東の橋まで行って、Guard Thomasと話してくれ。彼はこの一週間ずっと橋に配置されていて、あのあたりの状況を知っているはずだ。\n\n彼の報告を持ってきてくれ。", nil, "あいつらは危険だ。Murloc共は、ここ東Elwynnの川辺を生息地としている。なぜ奴らがここを生息域としているかは分からないが、少なくともある程度の知能があり、攻撃的だということは疑いようも無い。", 0xbf37aefc, 0xd1c199f2, 0x0d41f7ae, nil, 0xfbe5b854, "...m." },
  [36] = { "Westfall Stew", "Westfall Stewのレシピを、Salma Saldeanに届ける。", "まさか私達の家から逃げることになるなんて思ってもいなかったわ。この地方は盗賊がやりたい放題していて、ここも安全じゃないの。Farmer Furlbrowが荷馬車を直してくれたら、他所に移動するつもりよ。\n\nそうだ、ちょっと頼まれてくれない？あ、Westfall stewのレシピをさらっと書くから、ちょっとまって。はい、このレシピをあの農場の先にいるSalma Saldeanに渡してくれないかしら。Saldean's farmはこの道を進むと分かれ道があるんだけど、それをちょっと越えたところにあるわ。", "あのVerna Furlbrowがいなくなるのは本当に寂しいよ。ここへ来る途中で、まさか彼女に会ったりはしなかったよね？", "Vernaは本当にかわいい女性だったわ。彼女がWestfallから離れるのは残念だけど、彼女は都会っ子らしいところがあったから、きっとStormwindでの生活のほうが合ってるのかもしれないわね。さて、おしゃべりはここまでにして、Westfall Stewを作るわよ！", 0xb05bfdaf, 0xd3f82a15, 0xce62c0a2, 0xdfbf0990, 0xd01407d2, "....." },
  [37] = { "行方不明のガードを探せ", "川を北に遡り、行方不明のRolfとMalakai両名を捜索せよ。", "数日前に、ここを流れる川辺を調査するように私が送った２名のガード、RolfとMalakaiがまだ戻ってきていないんだ。彼らに何が起こったのかを調査して、上に報告しなければならない。\n\n申し訳ないのだが、この川を北に遡り、二人を探してきてくれないだろうか。あるいは遺体なるものを…。", nil, "死体は細かくバラバラにされていたが、近くに「Footman Malakai Stone」と刻まれた大きなメダルが落ちている。", 0xbd0b84c3, 0xc79cfdb3, 0x96ec21d0, nil, 0xf410e026, "...m." },
  [38] = { "Westfall Stew", "Stringy Vulture Meat３切れ、Goretusk Snout３個、Murloc Eyes３個、Okra３本を集め、Salma Saldeanに渡す。", "Westfall Stewを作るのを手伝って！ 次の材料を持って戻ってきて：\n\nStringy Vulture Meatを$N1個\n\nGoretusk Snoutsを$N2個\n\nMurloc Eyesを$N3個\n\nOkraを$N4個", "次の材料を持って戻ってきておくれ：\n\nStringy Vulture Meat 3個\n\nGoretusk Snout 3個\n\nMurloc Eye 3個\n\nOkra 3個", "そのOkraでこのスープがいい具合にとろみがつくよ！あとはStringy Vulture Meatと、Murloc Eyeを少々、それにあの美味なGoretusk Snoutを加えるだけだ。これで完成！手伝ってくれた礼に、{name}、今日一番のWestfall Stewを持っていってくれ！", 0xb05bfdaf, 0x1fd3a0f2, 0x3d38218e, 0xbc377ac8, 0xe18bc596, "....." },
  [39] = { "Thomasの報告書", "GoldshireにいるMarshal Dughanに報告せよ。", "Marshal Dughanに、MalakaiとRolfの死を伝えてほしい。そして、東ElwynnのMurlocを掃討するには、現在の戦力では厳しいということも伝えてほしいのだ。\n\n私達には余計な戦力はない。だが、Dughanなら、きっと誰かを寄こしてくれるに違いないはずだ。", nil, "なるほど、悪い報告だな。我々の防御網は、すでに各地に分散され、手薄になっている状況にある。RolfとMalakaiを亡くしたことは、更に事態を悪化させることになるだろう。\n\n何らかの手を打たなければ、週末にはこのGoldshireで戦線を張らなくてはならなくなる！", 0x25228270, 0x3f1aa863, 0x2d7986ad, nil, 0xae2657cb, "...m." },
  [40] = { "魚臭い危険", "GoldshireにいるMarshal Dughanと話す。", "{name}、Elwynn Forestに新たな脅威が迫っている！Murloc共が、東Elwynnを流れる小川まで勢力を拡大してきているんだ。魚を脅かし、ボク達の仲間を攻撃してるんだよ！\n\nMarshal Dughanにこの事態がいかに危険かを理解してほしいんだけど、彼はgnollや盗賊のことで頭が一杯で、Murlocが危険だと思ってないんだ。\n\n頼むよ、{name}。Dughanに、東面に軍隊を送るよう説得してほしいんだ！", nil, "確かに、Remyとは話をした。彼はすばらしい商人だが、Murlocに関する報告はまだまだ不足事項が多い。\n\nお前の忠告は肝に銘じておこう。しかし、Murlocの脅威について軍からの報告を受けない限り、東に軍を送る余裕は我々にはないのだ。", 0x02cfe285, 0x67e1f5a8, 0xb8d781bd, nil, 0xf6272f28, "...m." },
  [45] = { "Rolfの手がかりを探せ", "Murlocのキャンプ地を探し、Rolfが死んだ証拠か、もしくは何らかの手がかりを発見せよ。", "一帯をくまなく捜索すると、水かき状の足跡が、Stone Cairn Lakeの岸に沿って東に続いて残っているのを発見した。東方面には、ぼんやりとMurlocのキャンプ地らしきものが見てとれる。\n\n恐らく、Rolfの手がかりはそこにあるだろう…。", nil, "「Footman Rolf Hartford」と刻まれている金属製のメダルを首につけた遺体を発見した。", 0x119e499d, 0x93412d0c, 0xbf0a2396, nil, 0x0692a2fa, "...m." },
  [46] = { "懸賞首Murloc", "東Elwynn橋にいるGuard Thomasに、Torn Murloc Finを８個持っていく。", "Stormwind軍はmurloc lurkerとforagerを討伐した者に、懸賞金を用意した。奴らを殺し、torn murloc finを証拠としてThomasのところへ持って行ってほしい。Stormwind軍からかなりの報酬が出るだろう。\n\nMurloc共は、ここから北に広がるStone Cairn Lakeや、この小川に流れ込む南湖畔辺りをキャンプ地としている。", "狩りの具合はどうだ、{name}？", "ヒレを持ってきたのか？よし！Marshal DughanはElwynn東部のMurlocの状況を案じていてな、事態が収まりつつあると伝えたいんだ。\n\nお前の働きがそれを実現する助けになった。", 0xd7ee6932, 0x320c64a3, 0x05a40606, 0xd84cca78, 0xff08c2c6, "....." },
  [47] = { "Gold Dustの換金", "Elwynn Forest地方にいるKoboldが持っているGold Dustを10個集めて、GoldshireにいるRemy 'Two Times'に渡す。", "この地方にいるKobold共は、時々Gold Dustを運んでいる。私はそれが必要でな。ちょっとばかし持ってきてくれないだろうか。それなりの金額で交換しよう。お得だぞ！\n\nKoboldは南にあるFargodeep Mineや、北東のJasperlode Mineを生息地としているから、すぐに見つかるはずだ。", "しっ！Gold Dustを持ってきてくれたかい……この私に？", "これは見事なGold Dustだな、{name}。よし、換金しよう。あ、あとだな、これは私の仲間からの印だ。きっと役に立つだろう、きっとな…。", 0x6fc1c811, 0x54bcff94, 0xcbdc7c22, 0xfc397987, 0x26e50fd4, "....." },
  [48] = { "甘い琥珀", "Holy Spring WaterをGrimbooze Thunderbrewのところへ持って行って下さい。", "南の地、蔓がねじれ這うところ\n\n深く水をたたえる隠された井戸がある\n\n光の聖なる娘のように清らかな\n\nHoly Spring Waterを今すぐ持ってきておくれ。", "ヒック！ ほっほー！ アンコールをご所望かい？\n\n南の地、蔓がねじれ這うところに\n\n深く水をたたえる隠された泉がある\n\n光の聖なる娘のごとく清らかな\n\nHoly Spring Waterを今すぐ持ってきておくれ。", "ヒック! ホッホー!", 0xcfa75457, 0x4e77cd9b, 0x13610a88, 0xb098103f, 0x677f464a, "....." },
  [49] = { "甘い琥珀", "Grimbooze Thunderbrewは、Sack of BarleyとSack of RyeとSack of Cornを欲しがっています。", "琥珀こそ、わが生涯最長の愛の色\n\n空に残る黄昏の最後の残り火のように\n\nわが愛が生まれるよう、取ってきておくれ\n\nそれぞれ一袋ずつ、barley、rye、そしてcornを。", "アンコール？ああ、いいとも！\n\n琥珀色こそ我が生涯で最も長き愛の色\n\n空に残る黄昏の最後の残り火のように\n\n我が愛が生まれるよう持ってきておくれ\n\nbarley、rye、cornを1袋ずつ。", "ヒック! ホッホ!", 0xcfa75457, 0x95311fad, 0x952da726, 0x2aecfde8, 0x6787a76a, "....." },
  [50] = { "甘い琥珀", "Grimbooze ThunderbrewはTruesilverを欲しがっています。", "混ぜて混ぜて、もろみができるまで\n\nこれは我らだけの秘密の蓄え\n\n蒸留器は頑丈な金属で作らねばならぬ\n\nTruesilverを持ってきておくれ、この歌を終わらせるために。", "アンコールだって？もちろんさ、友よ！\n\n混ぜに混ぜてマッシュを作ろう\n\nこれは我らだけの秘蔵の酒となる\n\n蒸留器は頑丈な金属で作らねばならぬ\n\nこの歌を仕上げるためにTruesilverを持ってきておくれ。", "ヒック! ホッホ!", 0xcfa75457, 0x4e472b5f, 0x915c986b, 0x5199c398, 0x6787a76a, "....." },
  [51] = { "甘い琥珀", "Sycamore BranchをGrimbooze Thunderbrewのところへ持って行って下さい。", "まだ濾してはいないが、蒸留したて\n\n耕されて種を待つ大地のように。\n\n次は炭の山をこしらえよう\n\nsycamoreの枝を届けておくれ、それが次の目標だ。", "アンコール？君のためなら何だってするさ！\n\nまだ濾してはいないが蒸留したて\n\n耕されて種を待つ大地のように。\n\n次は炭の山をこしらえよう\n\nsycamore branchを届けること、それが次の目標だ。", "ヒック! ホッホ!", 0xcfa75457, 0x4d5230ce, 0x29bc75b2, 0x5a875dd3, 0x6787a76a, "....." },
  [52] = { "辺境地帯を守れ", "Prowlerを８匹、Young Forest Bearを５匹狩り、東Elwynn橋にいるGuard Thomasに報告する。", "やあ、{name}。この辺りは辺境地帯でね。かなり危険な野生動物が生息している。厄介なことに、そいつらはここからすぐのところにあるEastvale Logging Campという集落に被害をもたらしているんだ！\n\nなんとかして、その集落の助けになってほしい。", "あの狼と熊はもう倒したか？", "手伝ってくれて本当にありがとう、{name}。森の中の何かが、この動物たちをこんなに大胆にさせているに違いない。\n\nそれが何であれ、そこに留まっていてほしいものだ。", 0x2e116184, 0x03f5e0ac, 0x866a4bcd, 0xfcb3bc90, 0xe7a250d3, "....." },
  [53] = { "甘い琥珀", "Charred Oakの束をGrimbooze Thunderbrewのところへ持って行って下さい。", "赤子の涙のように澄んだ甘美な液体\n\n年月を経て美しく深い琥珀色に変わる\n\nだが、とことん酔っぱらう前に\n\n焦がした樫の樽を作らねばならぬ。", "もちろん、また歌ってやるとも、友よ！\n\n赤子の涙のように澄んだ、甘美なる液体\n\n年月を経て美しく深い琥珀色に変わる\n\nだが、とことん酔いつぶれる前に\n\n焦がした樫の樽をこしらえねばならぬ。", "樽で寝かせて、炭でこして\n\n唇を越えて、魂までまっすぐ染み渡る。\n\nさあ飲もう、君に乾杯\n\nついでに俺にも、Grimbooze Thunderbrew!", 0xcfa75457, 0x2911d99e, 0x90b69e3d, 0xe5239d0c, 0x5368c39a, "....." },
  [54] = { "Goldshireへの報告", "Elwynn ForestのGoldshireにいるMarshal Dughanに、Marshal McBride's Documentsを渡して下さい。", "{name}よ。お前はNorthshireの治安を立派に守っていけることが証明された{class}だ。これからは、Elwynn Forest地方全体を守ってほしい。\n\nそこでだ。次は、GoldshireにいるMarshal Dughanにこの書状を届けてほしい任務があるのだが、やってみないか？Goldshireは、道沿いを南に行き、この地方の門からちょっと過ぎた辺りにある。", "McBrideからの知らせだと？NorthshireはElwynn Forestに比べれば庭のようなものだが、Marshal McBrideが何を報告してきたのか気になるな。\n\nさあ、彼の書類を渡してくれ……", "さて、ここにはお前がStormwind MarshalsのActing Deputy Statusを与えられたと書いてあるな。おめでとう。\n\n幸運を祈る――Elwynnの安全を守るのは楽な仕事じゃない……なにしろ軍の大半は、どの貴族のためだか知らんが、何だか分からんことで手一杯なんだからな！\n\nこの暗い時代に政治の動きを追い続けるのは難しい……", 0xccb7dcaf, 0xc0ef425f, 0xd8bc24db, 0xf6530924, 0xb56df9b4, "....." },
  [55] = { "Morbent Fel", "Morbent's BaneをMorbent Felに使って彼を殺し、Morbent's BaneをSvenのところへ持ち帰って下さい。", "Morbent Felは自分の隠れ家に潜んでいる。Raven Hillの墓地を見下ろす、東の丘の上に建つ家だ。この地での奴の時も、終わりに近づいている……\n\nMorbent's Baneを奴に使え。奴の守りの魔法を無力にしてくれる。\n\n奴を殺せ。奴を殺して、その邪悪から我々を救ってくれ。私の復讐の道具となり、Duskwoodの英雄となれ！", "Morbent Felは倒したのか？！", "Morbent Felは倒された。闇の騎手たちはいまだ野放しだが、望み得ぬと思っていた望みの、ほんの一片が叶ったのだ。\n\nお前は不可能を成し遂げた。その行いはDuskwoodの伝説の中で永遠に語り継がれるだろう。\n\n行け、{name}。そしていつの日か、運命がお前を再び私のもとへ導くかもしれん……", 0x461172d9, 0xee859640, 0xa0025f54, 0x7f970e9e, 0x80e0a20a, "....." },
  [56] = { "夜警", "DarkshireのCommander Althea Ebonlockeは、Skeletal Warrior 8体・Skeletal Mage 6体を殺すよう求めています。", "Night Watchの司令官として、Darkshireの市民を守ることが私の誓った務めだ。Stormwindはここに配置していた衛兵を引き揚げてしまい、我々は自力でやっていくしかなくなった。\n\nこの任務にふさわしいと思うなら、力を貸してくれ！Darkshireのすぐ南にあるTranquil Gardensへ向かい、Skeletal Warriorsを8体とSkeletal Magesを6体倒して、Night Watchを助けてほしい。アンデッドの脅威を食い止めねばならん！", "戻ったか、{name}。The Night Watchの役に立つことを証明したいのなら、Skeletal Warriorsを8体とSkeletal Magesを6体倒してから私のところへ戻ってこい。", "すごいわ、{name}。Darkshireの人々への献身は賞賛されるでしょうね。", 0x50990c24, 0x988ea067, 0xb762390c, 0x426a38c5, 0x00bdfe75, "....." },
  [57] = { "夜警", "DarkshireのCommander Althea Ebonlockeは、Skeletal Fiend 15体・Skeletal Horror 15体を殺すよう求めています。", "{name}、この森にアンデッドがはびこっているという報告を受けてるのよ! 仕事に取りかかってくれるのなら、Raven Hill墓地へ行って穢らわしいSkeletal Fiend 15体とSkeletal Horror 15体を退治してきて。Darkshireの真南にあるTranquil Gardens Cemeteryのあたりにもいるという報告があったわ。アンデッドはDuskwoodから駆逐しなければ!", "Skeletal Fiendを15体とSkeletal Horrorを15体倒したら、私のもとへ戻ってこい、{name}。", "Darkshireの人々は感謝してるわよ。あなたはNight Watchの強力な仲間だってことを証明してくれたわ。", 0x50990c24, 0xb2d050a2, 0xc3805ea3, 0x159417dc, 0xfa65ff23, "....." },
  [58] = { "夜警", "DarkshireのCommander Althea Ebonlockeは、Raven Hill東霊廟内のPlague Spreader 20体を殺すよう求めています。", "Raven Hillの事態はまだ深刻よ。Darkshireの安全はあなたの手にかかってるわ、{name}。町の安全を守る番人の数が足りないのよ。もう一度Raven Hillへ行って、東霊廟のPlague Spreaderを20体一掃してもらいたいの!", "君の助けが必要だ、{name}。北西の墓地へ向かい、東の霊廟からPlague Spreaderを20体一掃してくれ。\n\n任務を終えたら私のもとへ戻ってこい。", "{name}、Darkshireの人々を代表して、そしてNight Watchのリーダーとして、あなたの勇敢さと決意に感謝します。「光」があなたの行く道を照らしますように。", 0x50990c24, 0x1fb37e1e, 0xf156af7a, 0x20d0eab3, 0xe664400d, "....." },
  [59] = { "布製か革製か", "Sara TimberlainにStormwind Armor Markerを渡す。", "お前の知性と勇気を評価し、防具一つを入手するための確約書を書いておいた。これをEastvale Logging CampにいるSara Timberlainに渡すのだ。彼女がお前に合った防具を用意してくれるはずだ。{name}よ、その装備品を身に付け、Elwynnを守るのだ。\n\nEastvale Logging CampはGuard Thomasの持ち場を越えた東にある。", "私はStormwind Armyから、兵たちに布と革の鎧を供給するよう依頼を受けている。\n\n私宛てのmarkerを持っているなら、喜んで何か作ってやろう。", "あら、確約書ね。じゃあ、自分に合いそうな防具をこの中から選んでね。\n\n勇敢な{class}さんに幸運あれ。そしてこの防具が戦いの役に立ちますように。", 0x751bcd47, 0x88cbb6e2, 0xec149fa7, 0xa0219e98, 0xff5c34aa, "....." },
  [60] = { "Koboldのろうそく", "GoldshireにいるWilliam Pestleに、Large Candleを8個持ってくる。", "元気かね！ちょっと時間はあるじゃろか？\n\nワシは兄弟二人で、Stormwindにある薬屋を営んでおるのじゃが、large candleが必要でここに寝泊りしているんじゃよ。それでな、もしよければ手伝ってくれんかの？\n\nKoboldの奴らが持っているlarge candleをとってきてほしいのじゃ。奴らは、このElwynn地方にある鉱山を棲み処としていてな。ここから南のFargodeep mineや、東に位置するJasperlode Mine辺りでうろついているそうなのじゃ。どうじゃい、やってくれんかのお。", "あのろうそくはもう集めたか？", "Kobold狩りは大変じゃったかの？おお、それじゃそのろうそくじゃよ。ありがとさん。これはほんの些細なお礼じゃ。受け取ってくれ。", 0x514933bf, 0xd8ce4567, 0x6cce32c4, 0x77e7ca88, 0x98618684, ".....", nil, nil, 0x1993cf97, nil, nil },
  [61] = { "Stormwindへの配達", "StormwindのTrade DistrictにいるMorgan Pestleに、Williamの荷物を届ける。", "兄弟のMorganが、Stormwindでロウソクを今か今かと待っているのじゃ。ワシにはそこまで行く時間もないし、よければ代わりに届けてくれんかの？礼はあいつがするじゃろ。\n\nこれがロウソクを詰めた荷物じゃ。StormwindのTrade DistrictにあるPestle's Apothecaryという店にMorganがおるはずじゃ。", "おお、兄弟からの荷物だって？素晴らしい！今日は本当に運に恵まれているよ！", "これがお礼じゃ。ひょっひょっひょ、お前さん、店内を見るんじゃ！きっと役に立つポーションなどが見つかるじゃろて。", 0x6a825135, 0xdeec4138, 0xd71ae934, 0x89b01d8f, 0xdf7db746, "....." },
  [62] = { "Fargodeep Mine", "Fargodeep Mineを調査し、GoldshireにいるMarshal Dughanに報告する。", "Northshireの鉱山は問題だらけだ！Elwynn地方のFargodeep Mineも例外ではなく、Koboldの巣窟と化しているという報告を受けている。\n\nFargodeep Mineを調査し、この報告の裏づけをとってきてほしいのだ。問題の鉱山はGoldshireの南に位置し、StonefieldとMaclure homesteadsの間にある。", "何か報告はあるか、{name}？Fargodeep Mineには行ってきたか？", "良くない事態だな。次はドラゴンでも襲ってくるのか！？まあいい。それよりもパトロールを強化しなければな。任務ご苦労だった、{name}。そうだ、ちょっと待っててくれないか。実はもうひとつ頼みたいことがあるんだ。", 0x3a373e5c, 0x068c7c5b, 0x196f6d77, 0x620f4981, 0x902000cc, "....." },
  [63] = { "水の呼び声", "Corrupt Manifestation of Waterを倒し、Silverpine ForestでBrazier of EverfountにCorrupted Manifestation's BracersとRemaining Drops of Purest Waterを乗せて下さい。", "Silverpineの海岸沿い、Sepulcherの西に、疫病で穢された祠がある。そこの精霊たちはもう我らの民に語りかけてこない。その顕現を倒して泉を清めるのは、お前の役目となるだろう。\n\nエレメンタルの腕輪を、Brineの薬の残りの雫と一緒に火鉢に置け。その儀式で、お前が言葉を交わせる清らかな精霊を呼び出せるはずだ。\n\n務めを果たした証を持ってこい。そうすればお前のトーテムを褒美として授けよう。", "火鉢は今も辺りのかすかな光を映し、近づくと炎がわずかに揺らめく。\n\n丘に広がる穢れはここまでは及んでいないようで、足りない材料を除けば、火鉢は清められた水の化身を呼び出す儀式の準備が整っているように見える。", "あなたは火桶に腕輪を置き、Brineの作ってくれた小瓶の残りの水を炎に注いだ。雫は炎にあたってパチパチと音を立てた。あなたはIslenから教わった簡単な呪文を唱え始めた……。", 0x1f0e11aa, 0xaa58c2a7, 0xf6931e98, 0x94ae3991, 0x8260098f, "....." },
  [64] = { "置き忘れた家宝", "ここから西のPumpkin Farmに建つ農家の洋服ダンスから、懐中時計を取ってきて、Farmer Furlbrowに渡す。", "ひどいったらありゃしねえぜ！Vernaは外が騒々しいって俺を起こしてくれたんだが、悪漢共が暴れていやがったんだ。俺達はすぐに逃げたさ。必死だったからな。懐中時計を持っていくのを忘れてしまったんだ。Vernaの父親から、結婚式の日にもらった時計で、盗賊共がもってるかと思うと、気分が悪いぜ。ここから西のパンプキン農場に農家があって、そこの洋服ダンスに入っているはずなんだ。多分すぐわかると思うぜ。みつけてきてくれたら、お礼ははずむぜ！", "私の時計、取り戻せたりはしなかったよな？", "俺の時計だ！いやあ、ありがとな、親切な紳士さんよ！\n\n俺たちは貧乏で、住むところもなくなった農民だが、感謝の気持ちとして、これを受け取ってくれや。", 0xf0e121ad, 0xdbaefd0c, 0xf295ad64, 0xc78af9a9, 0x1ca851f8, ".....", nil, nil, nil, nil, 0xd9a3b24b },
  [65] = { "Defias Brotherhood", "Gryan Stoutmantleは、LakeshireのWileyに話しかけるよう求めています。", "Defias Brotherhoodと自称する人でなし共がWestfallの善良な人々が土地を離れていく原因だ。 君にチンピラ一味に潜入してもらいたい。我々は集団の主導者と彼らの潜伏先を知りたいんだ。 Lakeshireの宿屋にWileyという名前の私が面倒をみてやったrogueがいる。\n\nRedridge MountainsにあるLakeshireに行ってくれ。Elwynnの東だ、そこでできることを見つけてくれ。", nil, "で、 Stoutmantleが君をよこしたんだな? そうだな、彼には借りがある。", 0x2a2224c0, 0x5c71d76f, 0x567bbd13, nil, 0xd8800e68, "...m." },
  [66] = { "Stalvanの伝説", "Darkshire Town HallにいるClerk Daltryを探して下さい。", "昨夜、恐ろしい胸騒ぎが私の血管を駆け巡りました。孫娘のAlyssaがひどい危険にさらされていると感じたのです。カードに問うてみると、テーブルの上から「Death」のカードが私を見上げていました。\n\n暗い忘我の中を長く旅した末に、この恐ろしい謎を解く手がかりを見つけることができました。ある名前が浮かんできたのです。Stalvanという名が。\n\nTown Hallの書記を訪ねて、この人物についてもっと分かることがないか調べてください。私たち皆のことが心配でなりません。", nil, "ああ、それでMadame Evaがあなたを……。", 0xeb6571fb, 0xef91d1ff, 0x44b56c82, nil, 0x4de8a455, "...m." },
  [67] = { "Stalvanの伝説", "Moonbrook Schoolhouseへ行き、Stalvanに関する最新情報をClerk Daltryのもとへ持ち帰って下さい。", "Stalvanだって？町の記録簿を調べてみよう。\n\nStalvan……Stalvan……ええと。ああ、あった！Mr. Stalvan Mistmantleという人の記録がある。最後に記録された住所はMoonbrook Schoolhouseだ。いやはや、ずいぶん古い情報だね！\n\n頼みを聞いてくれないか、友よ？もしMoonbrookへ行くことがあって、この人物について何か新しいことが分かったら教えてくれ。記録はきちんとしておきたいんでね。", nil, "小さな古い木箱は軋みながら開いた……。", 0xeb6571fb, 0x660c738d, 0x277b14bd, nil, 0x45ee8251, "...m." },
  [68] = { "Stalvanの伝説", "Dusty Unsent LetterをClerk Daltryに渡して下さい。", "木箱の中に、Dusty Unsent Letterを見つけた。", "ああ、覚えているよ。Stalvanという男のことを尋ねていた人だね。探していたものは見つかったのかい？", "面白いですね。それじゃ結局この男はMoonbrookにしばらく滞在していたと。この手紙が出されていないのはもっと奇妙ですね。まあそれでも登録は更新しますよ。", 0xeb6571fb, 0x4e15fabb, 0x5b2de8d4, 0x78055707, 0x9c5b8cbb, "....." },
  [69] = { "Stalvanの伝説", "Lion's Pride Innへ行き、Stalvanという名前を聞いたことがある者がいないか確かめて下さい。", "なんてこった! 最初にこれを見逃してたんだ。記録では、Stalvanの最初の住所のすぐ下に別の住所が書かれてたんですが、一部が消えてました。GoldshireのLion's Pride Innへ向かったようです。あそこで調べるといいですよ、{name}さん。", nil, "Stalvan? 確かに聞き覚えがあるな。", 0xeb6571fb, 0x4acc049c, 0xa5734139, nil, 0xe0613a9e, "...m." },
  [70] = { "Stalvanの伝説", "箱からStalvan's Undelivered Letterを手に入れ、StormwindのCanal Districtへ持って行って下さい。", "Stalvanという名前には聞き覚えがある。今思い出したよ。\n\n何年も前の嵐の夜、ある使者がやって来て、一晩の宿を求めた。真夜中の鐘が鳴る頃、その男は恐怖で真っ青な顔をして、叫びながら階段を駆け下りてきた。寝間着のまま、どしゃ降りの中へ消えていったんだ。\n\n慌てていたせいで、男は手紙を二階の箱に置き忘れていった。取りに戻ってくることはなかったよ。Stalvanという男からの手紙が一通残っていて、StormwindのCanal District宛てになっている。自由に持っていってくれ。", "何を持ってるんだ？ちょっと見せてみな……", "こいつを持ってくるなんて、あんた随分図太いな。", 0xeb6571fb, 0xec87b2a9, 0xcf8206e0, 0xad2d2675, 0xf3e822c5, "....." },
  [71] = { "Thomasへ報告せよ", "RolfとMalakaiのメダルを、東Elwynn橋にいるGuard Thomasに持っていく。", "これで両方のメダルが揃ったのだから、橋にいるGuard Thomasのもとへ届けるといい。そうすれば彼も、殺された衛兵たちの運命を知ることができるだろう。", "こんにちは、{name}。RolfとMalakaiの行方は分かりましたか？", "最悪の事態が起こってしまったよ、{name}。もはやMurloc共を放っておくことはできない。", 0xcad5f606, 0xdfec0126, 0xfecbb9ef, 0x8c9b780e, 0xab891fb8, "....." },
  [72] = { "Stalvanの伝説", "まとめられた荷物の中から手掛かりを探して下さい。", "この屋敷の管理人は、私より前はずっと父がやっていた。虐殺の後、血をモップで拭き取ったのも父だ。まあ、それはどうでもいい話だが。\n\nFlintridge家の信託の最後の資金も尽きてしまった。今では一族の最後の家財も競売にかけられるところだ。税金の禿鷹どものせいだよ。どうしてももっと知りたいなら、このがらくたを自由に見ていってくれ。何が見つかるか分からないからな。", nil, "箱の蓋をゆっくりとどけた……。", 0xeb6571fb, 0x119baf0f, 0xf129a3f9, nil, 0xe56b8406, "...m." },
  [74] = { "Stalvanの伝説", "見つけたTorn Journalのページが、次の手がかりを示している。", "箱の中には様々な物が入っていた。かび臭い家財道具、家族の肖像画、狩猟戦利品に古書など。底の方に、陶器の花瓶の下敷きになっているTorn Journal Pageを発見した。", "何を持っているのかね？見えんのだ。目がひどく悪くてな。手に載せておくれ。", "なんとか読めるな。この筆跡で思い出したよ。目が悪くなる前に見たことがある。", 0xeb6571fb, 0x0bc0d882, 0xe3b43f83, 0x20b24ea6, 0x3a5de944, "....." },
  [75] = { "Stalvanの伝説", "Marshal Haggardは二階の箱でFaded Journal Pageを調べるよう求めています。", "この家に越してきたとき、二階の箱に羊皮紙の束が入っていた。来たばかりの頃に一度見たんだが、目がかすんできて諦めてしまったよ。\n\n目がほとんど見えない老いぼれの頼みを聞いて、このStalvanという人物についてもっと知るクエストに役立ちそうなものがないか、二階の箱を調べてくれないか。たしか、あんたの興味を引きそうな色あせた日記のページがあったはずだ。それを持ってきてくれれば、できる限りのことをして手伝うよ。", "私が話したあのページは見つかったかね、{name}？", "あったか!", 0xeb6571fb, 0x74cb8926, 0x33923181, 0x856913a4, 0x3715d975, "....." },
  [76] = { "Jasperlode Mine", "Jasperlode Mineを調査し、GoldshireにいるMarshal Dughanに報告する。", "Fargodeep Mineの調査ご苦労だった。だが、ボヤボヤしてられん。我々はここから遠くに位置するJasperlode Mineも偵察する必要がある。\n\nJasperlode Mineに向かい、Koboldの存在を確認してきてほしい。その鉱山は、この道を東に行き、Tower of Azoraの北にある。", "やあ、{name}。報告はあるか？Jasperlode Mineの偵察は済んだか？", "Jasperlode MineにKoboldだと？くそっ！事態は刻一刻と悪くなっている！\n\n報告ご苦労だった、{name}。だが、良い知らせを持ってきてくれたのならよかったのだがな。", 0x0323d68b, 0xb489dc45, 0xd63cfe6e, 0x3d82a623, 0xf3bd38e1, "....." },
  [77] = { "ねばねばで厄介な状況", "Skulk Rockの放棄されたHorde基地の周りにある木箱から、Hinterlands Honey Rippleのボトルを10本回収して下さい。", "Dran Droffersが探しているripple用初代の梱包資材なら持っているよ。Maltonのがさつな親父のためにrippleを梱包するのは手伝ってあげられるだろう……rippleの追加ボトル2本っていう手数料のためにね。rippleは、Skulk Rock近くの放棄されたHorde基地の中にある木箱に入っている。\n\nこれはきつい仕事になるだろう。すなわち、気味の悪いスライムやウーズが遺跡にへばりついてるだろうからね。噂によると、奴らはある種のウーズのボスに率いられてきたそうだ。とにかく、rippleを調達して梱包のためにここへ戻ってきてくれ。", "ここ我々のキャンプに来てくれたのは、今の仕事に欠かせないrippleのボトルを届けるためだと考えていいんだよね？", "ついにやってくれたか、{name}。rippleを傷つけない配慮をするだけの先見の明が君にあって嬉しいよ。不必要に乱暴に扱われたrippleの香りより悪い物はないからね。\n\n貴重なこの荷に手を加える魔法には、少し時間がかかるだろう。実を言うと、魔法はまったく関係ないけどね。ただ単に、Hinterlands Honey Rippleの空の梱包を持ってるだけだよ。ボトルをその時代の梱包を使って年代物にしてごまかしてるんだ。\n\n前進せよ……偉大なる酒へ向かって!", 0xc40325a3, 0x622bc0af, 0x35a6c99a, 0x7c82b40a, 0xbe8a614e, "....." },
  [78] = { "Stalvanの伝説", "Faded Journal PageをTavernkeep Smittsのところへ持って行って下さい。", "君の役に立ちそうな人間を知っておるぞ。私がStormwind Guardを率いていた頃、我々はDarkshireのScarlet Raven Tavernで飲んでいたものだ。あそこの主人Smittsは地元の伝承に実に詳しい男だ。彼にこのページを見せて、何か知っていることがあるか聞いてみなさい。", "Marshal Haggardに言われて来たって？なぜそれを先に言わない？\n\nああ、懐かしいHaggard。気の毒に、そのうちすっかり目が見えなくなるだろうな。ともかく、持ってきたものを見せてくれ。", "「光」の名にかけて! この筆跡には確実に見覚えがありますよ。", 0xeb6571fb, 0x9665adb8, 0xd11badb8, 0x01f28add, 0x017fe17b, "....." },
  [79] = { "Stalvanの伝説", "泥で汚れたページをCommander Ebonlockeのところへ持って行って下さい。", "私は何年もこのStalvanという人物に関する伝説を追ってるんです。数年前に旅の貴族が殺された時、Haggardさんの調査に同行しました。泥だらけの日記のページを見つけましたが、この森にいる狂った男とその筆跡を結びつけることはできなかったのです。あなたの持っている一連の証拠は彼の犯罪を立証していますよ。すぐCommander Ebonlockeにこれを渡して、突き止めた事実を知らせて下さい!", "いい話なんだろうな、{class}。持ってきたものを見せて、話を聞かせろ。だが光にかけて、手短にな。Darkshireの防衛が私の最優先事項だ。行き止まりの手がかりに費やす時間などない。", "あら{class}、あなた名探偵になれる素質あるわね。", 0xeb6571fb, 0xa2f0228c, 0x74cec9b0, 0xac774803, 0x7a5abbbe, "....." },
  [80] = { "Stalvanの伝説", "Clerk DaltryにBloodstained Journal Pageを見せて下さい。", "あのStalvanという薄気味悪い男には、ずいぶん前から目をつけていたんだ。だが、もしこのページが同じ人物の手で書かれたものなら、奴の罪は疑いの余地なく証明される。\n\n長年Town Registryを管理してきたおかげで、Clerk Daltryは筆跡を見分ける達人になった。このページを見せて、記録簿の署名と筆跡が一致するか確かめてもらってくれ。", "また来たのか、{name}？今度は何を持ってきた？", "なんと! このページの筆跡と登録のサインが一致してますよ。", 0xeb6571fb, 0xde53f421, 0x3946b54a, 0x851ef05a, 0xedad08fb, "....." },
  [81] = { "Rippleの配達", "樽をOrgrimmarのDran Droffersに届けて下さい。", "樽の中に、Dran用の梱包したrippleだけじゃなく、彼が盗んだ別のボトルにも特別な保護を施しておいた。Dranを高く評価しているとは言えないかもしれないけれど、乱暴に扱われたrippleほど悪い物はないからさ。お礼は結構だよ。\n\nさて、あそこの樽をOrgrimmarの店にいるDran Droffersへ届けてくれ。どうか、私の心からの挨拶をMaltonに伝えてくれ。美味しい酒と素晴らしい飲み友達を渇望するなら、我々は彼の訪問を光栄に思うだろうと彼に知らせてほしい。", "何か買いに来たわけでも、何か届けに来たわけでもないなら、時間の無駄だよ！rippleを持ってきたんだろうね！", "それじゃあ、樽の中にある物を見てみようか!\n\nうん、うん、ここに全部あるみたいだな。これはいい仕事をしてくれた手間賃だ。酒場に売るときには、5倍の料金が手に入るんだ! アッハッハ!\n\nこの別のボトルは特別な日のためにとっておく予定だ。シャンパンで割って飲もうと思ってる。こう呼ぶつもりなんだ……champippleとね。", 0xe686bc77, 0x1d634e7b, 0xaac3c2e0, 0x96a41844, 0x187834fb, "....." },
  [82] = { "Noxious Lair調査", "Noxious LairでCentipaar insect parts 5個を手に入れ、GadgetzanのAlchemist Pestlezuggに渡して下さい。", "よし、例の虫についての報告だが……分かっているのは、奴らがかつて今のNoxious Lairのあたりにあった水たまりを干上がらせているってことだ。分かっていないのは、まあ、それ以外の全部だ。\n\nまずは敵の正体を突き止めよう！Noxious Lairへ行って、あの虫どもから部位を取ってきてくれ。そこにいるCentipaarから5つ取って、Alchemist Pestlezuggのところへ持っていき、いじくり回してもらうんだ。あいつが調べれば、奴らの正体が分かるはずだ！", "君がJunior Surveyor {name}だね？急いでくれ、深刻な事態なんだ！Fizzledowserが言っていた虫の部位は持ってきてくれたかい？！", "よくやった——さっそくこれの分析に取りかかるよ！だが最初から言えることがある……これは私がこれまで見てきたどの昆虫の形態とも違う。まるでこの虫どもが外部の力か何かに操られているかのようだ。\n\nすぐにFizzledowserと話してくれ。どうやら、大急ぎで君の助けを必要とする緊急事態があるらしい！確かではないが、Tanarisの砂漠のさらなる虫が絡んでいると思う！", 0x41ebe488, 0x0e73f76a, 0xb0bea364, 0xb087ae77, 0x081b768c, "....." },
  [83] = { "赤い麻製品", "Eastvale Logging CampにいるSara Timberlainに、Red Linen Bandanaを６束持っていく。", "NorthshireをアジトとしているDefiasのギャング集団は、麻製のマスクをつけているの。でも、Elwynn地方にいるヤツラは、質がいい麻を使ったマスクをつけてるのよ。\n\n私に赤い麻製のバンダナを持ってきてくれないかしら。お礼にそれを使ってオシャレな服を編んであげる。\n\nDefiasのヤツラは、Elwynn中にキャンプを設営してるわよ。", "linenが残り少ないんだ、{name}。少し分けてくれないか？", "わあ、素敵な端切れね。ちょっと目が粗いけど。\n\nさあどうぞ!", 0xab13ee46, 0x6ab947a0, 0x2f31ce58, 0x13c355f0, 0xb808f80e, "....." },
  [84] = { "Billyにパイを", "Maclure VineyardsにいるBilly Maclureに、Pork Belly Pieを届ける。", "はい、おまたせ。Billyにこのパイを届けてちょうだい。そして、あの子がパイで喉をつまらせることを私は楽しみにしていると言ってちょうだい！", "うう……腹ぺこだ！パイを持ってきてくれたかい、{name}？", "んんん！うまい！！このパイは絶品だよ！\n\nあれ、だんだん思い出してきたぞ…。", 0x77e92707, 0xb3802d9c, 0x8c11f6b5, 0xa7950cc8, 0x90374641, "....." },
  [85] = { "無くなったネックレス", "Billy Maclureと話す。", "ネックレスを無くしてしまったの。小汚いBilly Maclureが盗ったに違いないわ！あの子はここから東にあるMaclure vineyardsでいつもイタズラばかりしてるから。\n\nネックレスを取り戻してきてほしいのよ。年老いた未亡人を助けると思って、お願い。", nil, "え、ボクがネックレスを盗ったって？盗ってないよ！泥棒じゃないんだよ、ボクは！\n\nそういえば、心当たりがあるようなないような…（ニヤ）。ああ、お腹が空いて思い出せないよお。", 0x1a691c23, 0x3c0d0519, 0xc37d5922, nil, 0xc488cf29, "...m." },
  [86] = { "パイを欲しがるBilly", "Stonefield's FarmにいるAuntie Bernice Stonefieldに、Chunks of Boar Meatを４切れ持っていく。", "パイをくれたら、ネックレスを盗った犯人を教えてあげるよ。でねでね、ここの反対側の農場にいるBerniceおばさんがすんごくオイシー、Pork Belly Pieをつくってくれるんだよ。\n\nこの辺りにいるイノシシの肉を何切れかおばさんとこに持っていって、事情を話せば、パイを焼いてくれるはずだよ。", "そもそも私のネックレスを盗んだ子に食べ物をやるなんて間違っていると思うけど、それで私のものが戻ってくるなら、仕方ない！\n\nboar meatは持ってきてくれた？", "このイノシシの肉は硬いんだけどね、じっくりととろ火で煮ると、美味しいパイをつくることができるのさ。", 0xe258953a, 0x3d1f7b01, 0xb9e0bfdc, 0xd53bb684, 0x6b1f64bc, "....." },
  [87] = { "Goldtooth", "Bernice's Necklaceを、Stonefield Farmにいる\"Auntie\" Bernice Stonefieldに持っていく。", "Fargodeep Mineの近くで遊んでいたときかな、落としちゃ……じゃない、見たんだよ。例のネックレスを。どうやって手に入れたとか聞かないでよ……ボクじゃないんだから！\n\nそれでね、見たんだよ。金の歯が生えた大きなKoboldがネックレスを拾って、鉱山の中に入って行っちゃったのを。そのKoboldを見つけに行けばネックレスも見つかるよ。本当だよ!", "こんにちは、{name}。私のネックレスは見つかった？", "これよこれ！ありがとう、本当にありがとう！\n\nはいこれをあげる。このネックレスは夫のものでね。幸運のネックレスと彼はいつも呼んでいたわ。彼があの戦いでこれを忘れなかったらなあ…。", 0xe78fd7d9, 0xec235807, 0x329228f9, 0x511d94a7, 0x9137e39e, "....." },
  [88] = { "Princessに死を！", "Princessを殺し、首輪をStonefield FarmにいるMa Stonefieldに持っていく。", "Brackwell家には品評会で賞を取った豚、Princessがいるんだ。その雌豚がとんでもなくデカいんだが、あんなになったのはこっちへこっそり忍び込んでうちの野菜を食ってたからなんだ！\n\nだから、あいつがうちの畑に来る前に……Princessには死んでもらう！ やった証拠にあいつの首輪を持ってきてくれたら、手間賃に何かやるよ！\n\nPrincessはたいてい、東のMaclureの農場の向こうにあるBrackwell Pumpkin Patchにいる。腹を空かせてまたここへ戻ってくる前に仕留めてくれ！", "もう彼女を見たか？仕留めたのか？", "本当にありがとう！あのブタは私達の作物を食べて大きくなったのよ！おかげで助かったわ、{name}。\n\nこの装備品の中で、どれがあなたに似合うかしらね？", 0xd0c3b757, 0x87ee4e48, 0xb6b583eb, 0x6ce3847c, 0x8ee1d213, "....." },
  [89] = { "Everstillの橋", "Iron Pikeを5個とIron Rivetを5個、LakeshireのForeman Oslowのところへ持って行く。", "この前のオークの侵攻の時、俺たちは鉄を溶かして弾丸や剣や鎧を作るしかなかった。Stormwindに新しい資材を送ってくれと伝えたんだが、Redridgeのgnollの一団が荷馬車を襲って、Lakeshireの裏の丘へ持ち去っちまった。\n\n今じゃこの橋を建て直すための資材が足りない。iron pikesを5本とiron rivetsを5個持ってきてくれたら、{name}、ちゃんと報酬は出すぞ。\n\nさあ、仕事に取りかかろう！", "この橋は勝手にできあがったりしないぞ！さて、iron pikesとiron rivetsはどこだ？", "よくやった、{name}。この物資は橋の工事に大いに役立つ。この美しい橋もすぐに補強できるだろう。", 0xfbe560d1, 0x5c73aae5, 0xcb575d10, 0xf3038219, 0xf1b96a47, "....." },
  [90] = { "Seasoned Wolf Kabobs", "Lean Wolf Flank 10本を集め、DarkshireのChef Grualのところへ持ち帰って下さい。", "Seasoned Wolf Kabobsはうちの人気料理なんだ！ もちろん、作ってあげるよ。でもその前に材料が要る。Lean Wolf Flanksを$N1個持ってきてくれ。この森には狼がたくさんいるから、Flanksを見つけるのに苦労はしないはずだよ。運のいいことに、ちょうどStormwind Seasoning Herbsの最新の荷が届いたところだから、あとはflanksさえあれば取りかかれるんだ。", "Lean Wolf Flankは10個見つかったか？StormwindのFeliciaからのハーブはどうだ？", "最高だよ、{name}! 評判のご馳走、Seasoned Wolf Kabobを楽しんでくれ!", 0x382c5f99, 0xb8f7846f, 0xe4dd8fa2, 0x00eddfcd, 0x6c901c98, "....." },
  [91] = { "Solomonの掟", "Shadowhide Pendantを10個、Lakeshire Town HallのBailiff Conacherのところへ持って行く。", "Stormwindの敵がRedridgeの東の丘陵に住みついた。この邪悪な悪党はArcaneを用いて、我らの町と民に恐怖と苦しみを広めている。Morganthという名のもとに、奴は悪事を働いているのだ。\n\nMorganthは今やShadowhide Gnoll Clanを操り、己の命令に従わせている。Law of Lakeshireに定められている通り、王国の罪人を助けることは死に値する。\n\nこの卑劣なgnollどもを倒さねばならん！\n\nShadowhide Pendantsを10個私に届けよ。そうすれば報酬を与えよう。", "Shadowhide Pendantを10個私に渡せば、報酬を与えよう。", "{name}、Court of Lakeshireはあなたの正義への献身を認めます。王国の法を執行することで、あなたはこの地の正義を守る一助となりました。", 0x4cdcd468, 0x14f882a1, 0xdf5729ff, 0x236bce06, 0x10ddb922, "....." },
  [92] = { "Redridge Goulash", "LakeshireのChef BreannaはTough Condor Meatを5切れ、Great Goretusk Snoutを5個、Crisp Spider Meatを5人前欲しがっています。", "Redridge Goulashを作ってあげられたら、これ以上嬉しいことはないんだけどね。ただ、ちょっと問題があるんだ。この前のオークの反乱の時に、Stormwindの部隊の旅団全員に食事を出しちゃってね。今じゃ食料棚は空っぽなんだ。でも材料を用意してくれるなら、喜んで作ってあげるよ。\n\nTough Condor Meatを5切れ、Great Goretusk Snoutsを5個、Crisp Spider Meatを5人前持ってきてくれればいい。", "まだTough Condor Meatが5個、Great Goretusk Snoutが5個、Crisp Spider Meatが5人前必要なんだ。", "よくやった、{name}。しかも見事な標本だ! さあ、これがRedridge Goulashという名の美味しいごちそうだ!", 0x3d45e6f7, 0xa292ee13, 0x05480404, 0x61808eeb, 0xd0740ab9, "....." },
  [93] = { "Dusky Crab Cakes", "Gooey Spider Leg 6本を集めてDarkshireのChef Grualに渡して下さい。", "ちょっとした秘密を教えてあげよう。Dusky \"Crab\" Cakesは、本当はspider legsから作ってるんだ！ちょっと気持ち悪いのは分かってるけど、このケーキはピリッとした良い味で、最高のおやつになるんだよ！Gooey Spider Legsを持ってきてくれたら、いくつか作ってあげるよ。\n\nVenom Web Spidersがいい調達先だって聞いたよ。北の、丘陵と川の間に巣を作っているんだ。", "やあ、{name}。Gooey Spider Legはもう手に入れたか？", "ああ、いい脚がひと揃い手に入ったな！秘伝の香辛料で味付けして（見るなよ！）、しばらくフライパンの上で踊らせるとしよう……\n\nそれに、Dusky Crab Cakesは私の得意料理でレシピは教えられないが、ほとんど同じくらい美味い料理のレシピをやろう。", 0x20b89ad4, 0x8efb36e6, 0x27a03112, 0x7c48a403, 0x83bd0d84, "....." },
  [94] = { "見張りの目", "Glyph of AzoraをRedridgeのTower of Ilgalarの近くにあるLion Statueへ持って行く。", "我が宿敵Morganthは、RedridgeのTower of Ilgalarに住む強大な力を持つ残忍なメイジだ。私は奴を偵察する手段、Eye of Azoraを編み出し、今では遠くから奴の姿を見ることができる。\n\nだが奴の思考を探るには……さらなる助けが必要なのだ。\n\nその気があるなら、私のGlyph of AzoraをTower of Ilgalarへ持っていってくれ。塔の近くにあるLion Statueの上にそれを置くのだ。\n\nそれが済めば、Azoraの力がMorganthの今後の企みを映し出してくれるだろう。", "このLion Statueは何十年もここに鎮座し、悪名高きTower of Ilgalarを孤独に見張り続けている。\n\n像の台座にはくぼみがあり、宝石か紋章をはめ込めそうだ……", "Glyph of Azoraを石の上に置いた。それはぴたりと石に貼りつき……そこからTheocritusの実体のない声が聞こえてくる。\n\n感謝するぞ、若き{name}よ。これからはこのGlyphを通して我と話すことができる。今後そなたに頼む仕事もあるやもしれぬ……我が宿敵の思考を探り終えたならばな。", 0x4ce3e4cb, 0xae7ae989, 0x32080b45, 0x5d05e43a, 0x338c1c3b, "....." },
  [95] = { "Svenの復讐", "Sven's Farmへ行き、古い切り株の後ろに何が埋められているのか見つけて下さい。", "以前は南東にある農場のひとつで働いていた……ところが私の留守中に、Deadwind PassのDark Ridersが農場に押し寄せ、家族を惨殺したんだ！\n\n戻ってきたとき、納屋の近くで怪しい人影がこそこそと何かを埋めているのを見た。捕まえる前に逃げられてしまったし、私はDark Ridersを追っている最中だったから、そこに留まるわけにもいかなかった。だから何が隠されたのかは分からずじまいだ。\n\nあの人影が埋めたものを見つけてくれたら、恩に着る。隠し場所は納屋の近くの古い切り株の裏だ。", nil, "土の山がある。何者かが限られた時間で何かを隠す必要があったかのように、急いで寄せ集められている。", 0x09c1ac2f, 0x7218d46f, 0x01da608e, nil, 0xacd152b2, "...m." },
  [96] = { "水の呼び声", "Shard of WaterをBarrensにいるIslen Waterseerのところへ持って行って下さい。", "かけら、取れ。かけら取って、命を与えよ。\n\n命を与えて、理解せよ。水は命と理解せよ……穢れは命を止める。\n\nお前、水の力で命を守り、命を与える。", "戻ってきましたね。素晴らしい！\n\nSilverpineへの旅はどうでしたか？時間はかかりましたか？\n\nあの地で成功したかどうか、私には分かりにくいのです。土地の多くが穢れてしまっているからです。その悪臭が、あなたが成したかもしれないあらゆる善を覆い隠してしまいます。ですが、小さな成功が大きな成功と同じくらい大切なこともあります。あの地の水を清めることは、あなたにとっても、すべてのシャーマンにとっても重要な意味を持っていたのです。", "これが私の求めた証だ。よくやった、{name}。\n\n最初に祝いの言葉を述べ、これを渡せることを嬉しく思う……お前の水のトーテムだ。\n\nうまく使え。そして幸運を祈る。\n\n次の試練はしばらく先になる。だから教えをよく身につけておけ。清き水は傷ついた者に生命を取り戻すだけでなく、他にも多くの効果をもたらす。時間があるときにシャーマンのトレーナーを訪ねるといい。他にも学べる呪文を持っているかもしれん。", 0x1f0e11aa, 0xb068b278, 0x1bc4c72c, 0xb4ccba7c, 0x8edac29b, "....." },
  [97] = { "Stalvanの伝説", "Commander Ebonlockeに知らせて下さい。", "{name}さん、筆跡が一致したと今すぐCommander Ebonlockeに知らせて下さい! 疑惑は正しかったんです!", "何かな、{name}？", "やっぱり! いい仕事してくれたわ、{name}。", 0xeb6571fb, 0xf668237f, 0x89f670d8, 0xabfc0333, 0xe1fbbf40, "....." },
  [98] = { "Stalvanの伝説", "Stalvan Mistmantleを殺し、Madame Evaにファミリーリングを見せて下さい。", "Stalvan Mistmantleは堕落した人生を送ってきた。罪のない犠牲者たちが奴の手で死んだのだ。数え切れない罪を犯してきたことは疑いない。今やその狂人がDarkshireを脅かしている。奴がどんな卑劣な企みを巡らせているか、光のみぞ知るだ。町のすぐ北にある奴の小屋へ向かえ、{class}。そしてStalvanを処刑し、決着をつけるのだ。\n\nそれを済ませたらMadame Evaの家へ行き、奴の一族の指輪を見せてやれ。何しろ、このおぞましい真相にたどり着けたのは彼女の予知のおかげだ。Darkshireがより安全になったのも彼女のおかげなのだ。", "何かな、{name}？", "分かりましたよ、{name}さん。Stalvanの死んだのが。この穢れた森に希望の波が感じられましたから。これでもうDuskwoodは彼の血の餓えから解放されたのですね。あの恐ろしいけだものの餌食となって死んだ人々の思念で、私の喜びは妨げられていたのです。それにしても、あなたは勇敢で頭の良い{class}ですね。", 0xeb6571fb, 0x6cc7a1f9, 0xf2779455, 0xabfc0333, 0x9b99fbec, "....." },
  [99] = { "Arugalの愚行", "Pyrewood Shackleを6個、SepulcherのDalar Dawnweaverのところへ持って行く。", "Arugalの魔法への理解が深まるにつれ、あの哀れな愚か者への軽蔑も増していく。奴のいわゆる治療法についての私の研究は、完成間近だ。\n\nPyrewood Villageで起きている奇妙な現象の原因となっている魔法が何か分かれば、私の知識は完全なものとなる。昼の間、農民たちは人間に見える。だが日が沈むと、町の者たちはMoonrage Worgenに変わるのだ。\n\nArugalが彼らにかけた、魔法のかかった枷からエネルギーを引き出す必要がある。魔法のかかったPyrewood Shacklesを6つ持ってきてくれ、{name}。", "Pyrewood Shacklesはもう手に入れたか、{name}？", "その粘り強さは称賛に値する。君が集めるのを手伝ってくれた知識によって、Arugalは倒れ、奴の無謀な魔法は打ち消されるだろう。君に乾杯だ、{name}。", 0x93f7323d, 0x8d806801, 0x0bdd1c31, 0xfff3d9e5, 0x1cd1fde1, "....." },
  [100] = { "水の呼び声", "Silverpine ForestにいるMinor Manifestation of Waterと話して下さい。", "詠唱を終えると同時に光が弾けた。炎に落ちる水滴の音は静まり、周囲の堕落した霊たちが消え去るとともに、あなたの感覚は圧倒される。", nil, "お前のおかげだ。シャーマンたちのおかげだ。\n\n腐敗は引いていく。だが生命は衰え続ける。生命を守るのはシャーマンの務め。", 0x1f0e11aa, 0x768f3e87, 0x2627182c, nil, 0xa657df1b, "...m." },
  [101] = { "Totem of Infliction", "Ghoul Fang 10個・Skeleton Finger 10本・Vial of Spider Venom 5本をDarkshireのMadame Evaに渡して下さい。", "神秘の穢れが森を蝕んでいく今、身を守る必要があることは否めぬ、{name}。風が我にささやき、近い将来そなたを辛抱強く待ち受ける大いなる危険について語っている。\n\n身を守りたいのなら、高貴なる{class}よ、ghoul fangsを10本、skeleton fingersを10本、そしてクモの毒の小瓶を5つ我のもとへ持ってくるがよい。そなたのためにTotem of Inflictionに魔力を込めてやろう。そなたに暴力を振るおうとする者を傷つけるトーテムだ。", "ghoul fangsを10個、skeleton fingersを10本、spider venomを5瓶持ってきてくれ。そうすれば、お前に暴力を振るおうとする者を傷つけるTotem of Inflictionを付呪してやろう。", "実に賢明ですね、{name}。Totem of InflictionはAzerothや遙か彼方をうろつく邪悪な者から身を守る助けとなるのです。危険が迫っていると感じたら、このトーテムを手に取り魔法のオーラに慰めを見出すのです。勇敢になるのですよ、{class}さん。あなたの未来にはおびただしい血が見えます。ですから、ありったけの勇気が必要となりましょう。", 0x35b94d5e, 0xef7c0c6e, 0x1e1257d7, 0x90276681, 0xfa828321, "....." },
  [102] = { "Westfallの警備", "Gnoll Paw８足を、Sentinel HillにいるCaptain Danuvinに持っていく。", "Stormwind軍は、俺たちを見捨てた。腐敗を広げていく嫌な風が、Westfall中に吹いている。ここは俺たちの故郷であり、ここに残り、暮らしていくことを決めた人達に背中を向けることなどできやしない。俺たちはかつては農民であり、ここを守るために戦い続けなければならないんだ。\n\nお前がまずできる仕事は、Westfallの警備だ。Deadminesの賊共と何らかの関わりがあると噂される下等なGnollを見つけだし、抹殺してきてほしい。そしてGnoll Pawを８足持ってきてほしい。報酬を用意しよう。", "あの卑劣なGnollどもから、前足を8つ集めてきたか？", "素晴らしい働きだ、{name}。People's Militiaのために尽力をつくすお前のような勇猛な冒険者がいれば、Westfallは昔のような、豊沃とした穀倉地帯に戻るかもしれない。お前の並外れた働きぶりを評価した上でのこの報酬を受け取ってほしい。", 0xbdbd8c1d, 0xb285aa6c, 0x08d3c8d8, 0x34967c23, 0xe6d9e3f6, "....." },
  [103] = { "炎の番人", "Flask of Oilを5個、Westfall LighthouseのCaptain Graysonのところへ持って行く。", "Lighthouse Keeperの家族が死んだ夜は恐ろしいものだった。Old Murk-Eyeが襲撃を率いるのを、私はなすすべもなく見ていた。だが済んだことは済んだこと、今気がかりなのはGreat Seaの船乗りたちの命だ。彼らの船は、この海岸の危険な岩場のすぐ近くを通るのだ。炎を見守る者がいなくなり、その役目が私に回ってきた。\n\nHarvest Monstersから油の入ったフラスコを5つ持ってきて、灯火を絶やさないよう手を貸してほしい。", "油がなければ、炎は長くは燃えないぞ、{name}。", "称えよう、勇敢な{class}よ。君の働きのおかげで、Westfall Coastの岩場に灯がともる。灯火が消えずにある限り、多くの命が救われるだろう。\n\n私はまさにこの岸辺で無駄に命を落とした。死後の私の務めは、誰も私と同じ運命をたどらぬよう見届けることだ。", 0x3ef7ad7a, 0xadaf38bb, 0x2c40ca7a, 0xd537b66e, 0x38ec3914, "....." },
  [104] = { "沿岸の脅威", "Old Murk-Eyeの鱗を一枚、Westfall LighthouseのCaptain Graysonのところへ持って行く。", "岩場で命を落とした時、死後の世界に何が待っているのか、私には見当もつかなかった。あの夜Lighthouseが暗かったのは、Old Murk-Eyeが灯台守の家族を追い払ったからだ。家族は戻ってきて再び火を灯したが、Old Murk-Eyeは気の弱いmurlocどもを唆して、もう一度一緒にLighthouseを襲わせた。二度目は家族も運に見放され、私の目の前でなすすべもなく命を落としたのだ。\n\n浜辺でOld Murk-Eyeを見かけたら討ち取り、その鱗を1枚持ってきてくれ。そうすれば報いよう。", "Old Murk-Eyeと呼ばれる脅威を片付けたか？Westfallの海岸線をうろついているのが目撃されている。\n\nあの汚らわしい獣が死んだら、私のもとへ戻ってこい。", "では、あの邪悪な異教徒Murk-Eyeは死んだのだな。よくやった、{name}。君の手で一つの命が葬られたが、おそらくはもっと多くの命が救われた。危険に満ちたGreat Seaも、君の英雄的な働きのおかげで、今夜はほんの少し安全になるだろう。", 0x2f06382c, 0x9bc7f6db, 0xa6201dcb, 0xd389c8ba, 0xf95015fd, "....." },
  [105] = { "ああ、Andorhal", "Araj's Phylactery ShardをWestern PlaguelandsのBulwarkにいるHigh Executor Derringtonのところへ持って行って下さい。", "ついに、Andorhalを攻め、そこを支配するlichを追い出す時が来た！\n\n街の廃墟の中で、そのlich、Araj the Summonerが支配している。奴は街の中心の残骸を囲む大勢のScourgeに守られ、奴に直接付き従う護衛たちも手ごわい。奴とまともに渡り合うには、多くの味方が必要だろう。\n\nArajを倒せ、{name}。その証として、奴のphylacteryの欠片を持ってくるのだ！", "任務はもう与えたはずだ、{name}。任務を果たした証として、lichの魂の器の欠片を持っているか？", "やってくれたな! Araj……あのlichがついに倒されたのだ!\n\n君は今日、Hordeに多大な貢献を果たした、{name}。その勇気と不屈の精神こそ、真の英雄たる者の証だ。どうか、これを受け取ってくれ。君がHordeに歴史に残る勝利をもたらしたことを、皆が見て知るための証として!", 0x2851097e, 0xdc02e3da, 0x0e5ec45c, 0xb6c91f9e, 0xb5703ad6, "....." },
  [106] = { "若者達の恋", "Tommy Joe StonefieldにMaybellからのLove Letterを届ける。", "もう、たえられない！あたしの心は、Tommy Joe Stonefieldのことしか考えられなくなってるのよ。そうはいってもね、家族が許してくれないの。彼に会うことはもちろん、あのかっこいい顔を見ることだってできないのよ！\n\nお願い、この手紙をTommy Joeに渡してくれない？彼は普段は、ここから西にあるStonefield Farmの西を流れる川辺にいるわ。", "何を持ってるって？？Maybellは私の退屈な人生の光なんだ。早く、彼女の手紙を見せてくれ！", "うん！もう彼女と離れ離れになってるのはいやだ。今すぐ会いたいよ！", 0x39bb27e6, 0xaca204cb, 0x455a69fe, 0x8ed56116, 0xaef57c73, "....." },
  [107] = { "Williamとの相談", "Gramma Stonefield's Noteを、William Pestleに渡す。", "William Pestleなら、あの子たちをくっつけることができる薬を持ってるかもしれないわ！\n\nこの手紙をWilliamに渡してちょうだい。彼はGoldshireにあるLion's Pride Innで泊まってるわ。", "\"Gramma\" Stonefieldからの手紙だって？Mildredにはもう何年も会っていないよ！何と書いてあるんだろう……", "その若いもんたちの気持ちはよくわかるのお。ワシにもそんな時があったわい。\n\nよし、一肌脱ごうじゃないか！さて、どうしたものか…。", 0x94227104, 0x6cf2cbc4, 0x613551b1, 0x4d3b404b, 0xd5a99e73, "....." },
  [109] = { "Gryan Stoutmantleへの報告", "Gryan Stoutmantleと話す。彼はWestfall地方中央に位置するSentinel Hillの石塔にいるはずだ。", "{class}、お前はこれまでにかなりの戦いを経験してきたようだな。まだなら、お前はGryan Stoutmantleのところへ行くべきだ。彼はPeople's Militiaという、Westfall地方の農村地域を守っている組織のリーダーだ。きっとお前の力を必要としているはずだ。彼はWestfall地方中央に位置するSentinel Hillの石塔にいる。", nil, "同志が君を寄こしてくれたのかな？非常に助かる。\n\nStormwind Monarchyは我々の大義を見捨ててしまってな。今やこの腐敗した状況を打開するのは我々People's Militiaの責務なんだ。我々に関心があるなら、自由という名の下で君に活躍の場を与えよう。", 0xc82e5075, 0x03f579cf, 0x50233a5c, nil, 0xb444ea08, "...m." },
  [110] = { "昆虫の体の分析", "Gadgetzanに到着したことをAlchemist Pestlezuggに連絡し、昆虫の体の一部に関する分析について問い合わせて下さい。", "しばらくScrimshankの測量道具を調べてみるよ……それに、彼の身の回りの物も整理しないとね。この虫どものせいで失うのはこれが最後じゃない、という嫌な予感が耳の後ろあたりでするんだ。\n\nAlchemist Pestlezuggのところへ顔を出して、送った虫の部位を処理できたか確かめてきてくれないか。できていたら、私のところへ持ってきてほしい。", nil, "ああ、結果はここにある。控えめに言っても……不穏なものだ\n\n虫どもが外部の力に操られているという我々の当初の疑いは、正しいと考えている。もしそうなら、我々が相手にしているのは極めて強大な未知の力であるだけでなく、悪意ある力でもある。この虫どもは純粋な破壊者へと造り変えられている。こんなものは見たことがない。", 0x869683a3, 0xfc5d499e, 0x4377af32, nil, 0x00ee2c5d, "...m." },
  [111] = { "Grammaとの相談", "Gramma Stonefieldと話す。", "お願いします、{name}さん。僕のお婆ちゃんに相談してみてくれませんか？Maybellと一緒になれるいいアイデアをお婆ちゃんは絶対にもっているはずです。\n\nあの人はここの東にある家にいます。", "友達がどんな反応をするか、待ちきれないよ！\n\nきっと思いもしないだろうな", "私達家族の間にある不和は、決してTommy JoeとMaybellに素晴らしい未来を授けることはないでしょうね…。でもね、そんなことであの若者達の恋を踏みにじることなんてできやしないわよ。\n\nそうねえ、何かいい策はないもんかねえ…。", 0x6b3f9d7c, 0xf51e0819, 0x90033b93, 0x96b93e46, 0x2fa7cabf, "....." },
  [112] = { "海草集め", "GoldshireにいるWilliam Pestleに、Crystal Kelp Frondを４枚持っていく。", "Maybellが外に出られるように、透明になれる薬を作ってやろう。これがあれば、うるさい家族に見つからずに、Tommy Joeに会えるじゃろて。だが問題があるんじゃ。これを作るには、crystal kelpが必要でな。\n\ncrystal kelpは通常は海の海草なんじゃが、時々Murloc共がこれを集めていてな。Crystal Lakeに棲むMurlocが確かそんな習性があったはずじゃ。Crystal LakeはGoldshireの東に広がっている湖じゃ。", "crystal kelpは持ってるかい？Maybellはきっと恋人に会いたくてたまらないはずさ……", "おお、集めてきたな。いいぞいいぞ！よし、では薬を作るから待っておれ…。", 0x2bebb48c, 0x3fc93ac6, 0x9e5c1b2e, 0x73f21124, 0xca7123ec, "....." },
  [113] = { "昆虫の体の分析", "GadgetzanのSenior Surveyor Fizzledowserに報告書を届けて下さい。Alchemist Pestlezuggが要求した通り、彼は必ず報告書の写しを渡すはずです。", "Senior Surveyor Fizzledowserにすぐこの報告書を見せなきゃならない。いや、実のところ……字の読める奴は皆この報告書を見るべきだ。我々が直面しているのは重大で深刻な脅威だ。TanarisとGadgetzanだけじゃない、放っておけばKalimdor南部全体が危ない。いやはや、Azeroth全土だってありうる。こいつが収まる気配はまったくないんだ。\n\nFizzledowserに報告書の写しを作ってもらって、君の陣営に自由に配ってくれ。皆がこの脅威を知らなきゃならないんだ！", "さて、Junior Surveyor {name}、Pestlezuggの奴は報告書をもう用意できたか？", "報告書を届けてくれて感謝する、Junior Surveyor {name}。これはGadgetzan Water Companyへの勤勉な働きに対する報酬だ。\n\n本来なら良い金を払うような連中に、我々の貴重な情報を無条件で配ることは普段なら喜ばしくないのだが、Pestlezuggとはもう何年もの付き合いだ。彼が皆に知らせろと勧めるのなら、それでいい。少し待ってくれ、写しを作ってやる。", 0x869683a3, 0xee5fe9a6, 0x5a5a6cc0, 0x30177227, 0x9ab8bc42, "....." },
  [114] = { "愛の逃避行", "Maybell MaclureにInvisibility Liquorを渡す。", "このinvisibility liquorをMaybellに届けるのじゃ。これを飲めば、あの子はTommy Joeに会えるじゃろう。", "Tommy Joeに私の手紙は届けてくれた？彼は何て言ってた？？", "ああ…どうしよう！家族を騙すことになっちゃう…。でも、Tommy Joeへの想いには代えられないわ。\n\nありがとう、{name}。タイミングを見計らって、薬を飲むわ。\n\nそうだ、お礼をしなきゃね。", 0x437cedda, 0x7b2f4392, 0x62549b36, 0x692ffc74, 0xe0cf61c2, "....." },
  [115] = { "闇の魔法", "Midnight Orbを3個、LakeshireのMarshal Marrisのところへ持って行く。", "Blackrockのオークどもは、Redridgeでの攻撃を助けるためにshadowcasterを引き入れた。そして奴らは闇の力を持つ道具――midnight orbs――を持ち込んだのだ。このオーブはRedridgeの守り手たちに痛烈な打撃を与えている。悪魔に汚されたこの品を、戦いから取り除くことが急務だ。\n\n倒したBlackrock shadowcasterからmidnight orbsを見つけて、私に届けてくれ。そうしたら私が処分させよう。あんなものは無いほうがこの世界のためだからな！", "shadowcasterどもとの戦いはどうだ？midnight orbsは見つかったか？", "ありがとう、{name}。これはすぐに廃棄に回しておこう。", 0x904fce2a, 0x60db0353, 0x5b872785, 0x92dca9d4, 0x6e8c3d71, "....." },
  [116] = { "乾いた時代", "LakeshireのBarkeep DanielsはThunderbrew Lagerを一樽、Merlotを一樽、Moonshineを一瓶、Sweet Rumを一袋必要としています。", "すっかり困ったことになってるんだよ、{name}。酒瓶がほとんど空っぽでね。最新の酒の積み荷はとっくに届いているはずなのに来ないんだ。オークの侵攻のせいで散々だよ。\n\n私のために一仕事してくれないか？\n\nWestfallの丘にいるGrimbooze ThunderbrewからThunderbrew Lagerを一樽、StormwindからMerlotを一樽、DarkshireからMoonshineを一瓶、GoldshireからSweet Rumを一袋、受け取ってきてほしいんだ。それを持って帰ってくれたら、ちゃんとお礼はするよ。", "Westfallの丘にいるGrimbooze ThunderbrewからThunderbrew Lagerを一樽、StormwindからMerlotを一樽、DarkshireからMoonshineを一瓶、GoldshireからSweet Rumを革袋一つ、受け取ってきてほしい。持ち帰ってくれたら、報酬が出るよう取り計らおう。", "見事な仕事だ、{name}! こんな上等な酒を揃えるのに、どんな道のりを旅してきたかよく分かってるよ。これでうちのお客もまた喜ぶだろう!\n\nうちの女房はなかなかの裁縫上手でね。君の働きへのお礼に、彼女が作ったこのマントを受け取ってくれ。", 0x1c0c7a25, 0x8d7bd5b0, 0xd5a46db2, 0x61956f46, 0xbe7fa4ea, "....." },
  [117] = { "Thunderbrew", "スペシャルビールを完成させる為にGrimbooze ThunderbrewへHopsを5つ持ってくるんだ。", "急いでおくれ、友よ、足早に\n\nうちの濃いラガーの味が\n\nシチューじゃなくビールらしくなるには\n\n醸造にはホップが要るのさ。", "急げ、友よ、手早く動け\n\n我らの濃いラガーの味が\n\nシチューではなくビールに近づくように\n\n醸造にはホップが必要なのだ。", "ホップとBarley、酵母と麦芽\n\n味蕾はまさに強襲を受ける、\n\n懇願も嘆願も無用\n\nThunderbrew Lagerは樽でやってくるのだから！", 0x06ba24f2, 0xcca1a58d, 0xf52ffef7, 0xf52ffef7, 0xed1e1cbe, "....." },
  [118] = { "靴の値段", "Verner's NoteをGoldshireのSmith Argusのところへ持って行く。", "Stormwind Guardsの装備を整えるのに鉄を使いすぎて、厩舎の馬の蹄鉄を作る分が足りないんだ！\n\nこのメモをGoldshireのBlacksmith Argusに届けてくれ。こっちの事情を説明して、蹄鉄を送ってくれるよう頼んであるんだ。", "何だって？Vernerに言われて来た、だと？なら彼の手紙をよこせ。それと、もっと大きな声で話せ！", "へっ、Vernerの爺さん、靴が要るってのかい!?!", 0x0dd0b1f0, 0x58b93226, 0xff4bd583, 0xf790dafa, 0x3e4e8e76, "....." },
  [119] = { "Vernerのもとへ", "RedridgeのVerner Osgoodのところへ戻り、Crate of Horseshoesを渡す。", "わかった、蹄鉄を50個くれてやろう……\n\nほら、全部箱に詰めて準備万端だ！ Vernerに、取引できて光栄だったと伝えてくれ。それと、この箱に付けたメモを必ず読むように言っといてくれよ！", "よかった、戻ってきたね！靴は手に入った？", "ありがとう、本当に助かるよ。\n\nおや、これは何だ? Argusが木箱にメモを付けてよこしたな……何だと?? Argusが俺に金を払えだって? ふん!\n\nまあ、{name}、手伝ってくれてありがとう。", 0x1296097e, 0x49433401, 0xe1ab4783, 0xa467f765, 0x16236c6c, "....." },
  [120] = { "Stormwindへの使者", "Magistrate Solomonから、StormwindのGeneral Marcus Jonathanへ届けなければならない報告書を預かった。届け終えたら戻ってきてほしいと判事は言っています。", "苦しい時だ、{class}。この町は絶え間ない包囲にさらされている。援軍がなければ、我々は確実に敗北するだろう。今からお前に託す知らせは、何よりも重要なものだ。この報告をStormwindのGeneral Marcus Jonathanへ直ちに届けよ。届け終えたら、良い知らせであれ悪い知らせであれ、すぐに私のもとへ戻ってこい。\n\nさあ、急げ！", "何を持っているのだ？", "楽にしろ、{class}。\n\nMagistrate Solomonは高潔な指導者だ。彼の言葉は私にとって非常に重い。王に助言を仰ぎ、状況をはっきりとお伝えしよう。あの立派な判事に、Stormwind Armyが支援すると伝えてくれ。陛下からお言葉があり次第、援軍を送る。", 0x7fd00169, 0xf2be5934, 0x06176f7a, 0x19bf3607, 0x6d2fb894, "....." },
  [121] = { "Stormwindへの使者", "General Marcus Jonathanからの返書を、LakeshireのMagistrate Solomonのところへ持って行く。", "王からの返事を待つ間に、この手紙をMagistrate Solomonへ届けてほしい。\n\n下がってよいぞ、{class}！", "将軍から知らせはあったのか？援軍はこちらに向かっているのか？", "時間を割いてくれて感謝する、{class}。LakeshireとStormwindへの貢献に対し、この硬貨を報酬として授けよう。\n\nさて、失礼させてもらう。この書簡にはどうにも腑に落ちないところがある。我らの王国で何かがおかしい。これは争いの終わりではなく、始まりなのではないかと危惧している。", 0x7fd00169, 0xa53df32a, 0xf1bab4f4, 0xf8129079, 0x4d427db5, "....." },
  [122] = { "下腹の鱗", "Black Dragon WhelpからUnderbelly Whelp Scaleを6枚集め、RedridgeのVerner Osgoodのところへ持って行く。", "GoldshireのArgusが送ってくれた蹄鉄の代金を払うのに、black dragon whelpのunderbelly scalesが要るんだ。6枚手に入れてくれたら、Argusにいくらか払って……それでも君に何か作ってやれるだけ残る。\n\nblack dragon whelpはよくLakeshireの南を飛び回っているが、あちこちうろつくのが好きでね。とにかく目を光らせて、見かけたら狩るしかないかもしれない。", "早く渡さないと、あの強欲なArgusが鱗を回収しに誰かをよこすに決まってる。あの鱗はもう見つかったか？", "ありがとう! これでArgusへの借金が返せる……", 0x068001c9, 0xd4d12cd6, 0xcda5c273, 0xef1640b6, 0xf521558d, "....." },
  [123] = { "The Collector", "GoldshireにいるMarshal Dughanに、The Collector's Scheduleを渡す。", "このメモ書きは、The Collectorと書かれた人間のスケジュール表だ。メモによると、その人物はElwynn Forestの鉱山から採掘された金の輸送品を受け取る予定と書かれている。\n\nまた、Collectorは東Elwynn地方にあるBrackwell Pumpkin Patchの近くに住んでいるらしい。\n\nこれは重要だ。GoldshireにいるMarshal Dughanに、この件に関して報告する必要がある。", "何だと？！？もう何か月もElwynnの鉱山ではうちの者を働かせていないぞ！\n\nその手紙を見せてみろ……", "ほお……。「Collector」か、聞いたことがあるな。だが、奴が誰のために働いているかは知らん。報告、ご苦労だった。奴の謎を解く助けになりそうだ。", 0x5318a151, 0x3b835957, 0x5a3d01e4, 0xb33d4341, 0x318a1e2f, "....." },
  [124] = { "Gnollsの遠吠え", "Redridge Bruteを10体とRedridge Mysticを8体倒し、Verner Osgoodのところへ戻る。", "オークの襲撃だけでも大変なのに！ 今度はgnollの荒くれ者やまじない師どもが私の厩舎の北の尾根をうろついて、はぐれた馬をさらっていくんだ……\n\nあのgnollどもを追い払ってくれたら、私も馬たちもとても感謝するよ。", "馬たちはまだ怯えているし、夜にはあの忌々しい狼の遠吠えがまだ聞こえる。お願いだ、{name}、あのGnollどもを何とかしてくれ！", "いろいろ手伝ってくれてありがとう、{name}。", 0xe85ed098, 0xa4d31ccd, 0xaddbfb20, 0x1ef3dbfd, 0xac71f116, "....." },
  [125] = { "失われた道具", "Lake Everstillの底から道具箱を取り戻してほしいとLakeshireのForeman Oslowは言っています。", "ここで手を貸してもらえると本当に助かるんだ、{name}。町が包囲されてから、物資がなかなか手に入らなくてね。俺の道具はGoldshireから荷馬車で届く予定だったんだが、橋が吹き飛ばされちまった。道具を船に積んだら、今度はオークどもが投石機で船を撃ちやがった。ついてないことに、俺の道具箱は湖の底まで沈んじまったのさ。\n\n俺の道具箱を取ってきてくれ、{name}。それだけの見返りはするよ。", "私の道具は見つかったかい？", "見事に取り戻してくれたな、{name}! この道具にまた会えるとは思ってもみなかったよ。", 0xc690e293, 0xe17d01d0, 0x00f67f4e, 0xc0af6727, 0xa3088c9c, "....." },
  [126] = { "丘に響く遠吠え", "Yowler's PawをLakeshireのVerner Osgoodのところへ持って行く。", "{name}、gnollどもはまだあそこにいる。Lakeshireの上の丘で狩りをする奴らの吠え声が聞こえるんだ。そしてひときわ大きな叫び声がある――奴らの頭、Yowlerだ。\n\nYowlerを倒して、群れを散り散りにしてやれ！ 証拠に奴の手を持ってこい。\n\nそれと気をつけろ。このgnollが頭なのには理由がある。そこらのMongrelとは違うぞ……", "Yowlerは危険な獣だ、{name}。まだ相手をする準備ができていないなら、それも分かる。", "改めて、手伝ってくれてありがとう。Stormwindの軍はオークの相手で手一杯で、gnollのような地元の脅威からRedridgeを守る兵がいないんだ。", 0x8dfeeed2, 0x12e4af10, 0x3fd1157a, 0x33d0330f, 0x3ba08361, "....." },
  [127] = { "魚を売る", "Spotted Sunfishを10匹、LakeshireのDockmaster Barenのところへ持って行く。", "Lake Everstillはspotted sunfishで有名なんだ。いつだって需要があるし……こっちは在庫が切れかけてるんだよ！\n\n10匹ひとまとめで持ってきてくれたら、いい値で取引するよ。自分で釣れないなら……murlocから奪えばいいかもね！", "sunfishを持ってきてくれたのか、ん？", "取引できて嬉しいぜ、相棒!", 0x8959426d, 0x299dd9a7, 0x595008a9, 0x1c00230f, 0x0c2062ce, "....." },
  [128] = { "Blackrockの賞金首", "Blackrock Championを15体倒せば、LakeshireのGuard Howeが報酬をくれる。", "Blackrock Clanは滅ぼさねばならん。敵が我らの土地に攻め入ったのだ。この山々はStormwindの王の主権のもとにある。情報によれば、氏族の各部隊を率いる者たちはChampionsと呼ばれているそうだ。奴らの野営地は北、Burning Steppesへ続く道のすぐ西にある。\n\nMagistrate Solomonはこの汚らわしい獣どもの死を望んでおられる。Blackrock Championを15体倒し、私のところへ戻ってこい。", "Blackrock Championを15体倒したら戻ってこい。", "Blackrock Clanを相手に勇敢に戦ってくれたようだな、{class}。我らの町への君の貢献は実に大きい。", 0xccdac34a, 0x3dc788d9, 0x3c6954d1, 0x465f09c0, 0x3ae1dc90, "....." },
  [129] = { "ただ飯", "Parkerの弁当をGuard Parkerのところへ持って行く。彼はDarkshireへ続く道を巡回している。", "お願いを聞いてもらえる？ Guard Parkerにお弁当を用意したんだけど、あの人は巡回に出ちゃってて……あの人は大きくて強いStormwindの衛兵だから自分の身は守れるけど、私みたいな町の人間には外はあまりにも危ないの。\n\nだから私の代わりにお弁当を届けてくれたら、ここに戻ってきた時にお昼をごちそうするわ！ ParkerはDuskwoodへ続く道の一帯を巡回しているの。", "Darcyが弁当を届けてくれたって？本当に心の優しい人だ。さて……いただこうか！", "ありがとう、ちょうど腹が減ってたんだ。オークやgnollからLakeshireを守るのは骨の折れる仕事だからな!", 0x88d7e35c, 0xaad7a98b, 0x9db66007, 0x3d1d5d66, 0xe1a276a1, "....." },
  [130] = { "薬草師への訪問", "Redridge HerbalistのMartie Jainroseと話す。", "Darcyのところに戻る前に、僕の代わりに彼女に花を持っていってくれないかな？ Lakeshireの町の西の端にある薬草屋で買えるんだ。\n\nでも花を受け取る時……薬草屋のMartieには、誰からの花か、誰に贈る花か言わないでね……", nil, "花束が要るのかい? 町に来てまだそんなに経ってないだろう……もうここで恋人を見つけたのかい?\n\n詮索すべきじゃないのは分かってるけど、恋の気配があるのはいいものだね……特にこんな物騒な時代にはね。", 0x71fe59f9, 0xa1ba4f91, 0x49da55c6, nil, 0x081a325e, "...m." },
  [131] = { "ラッパズイセンの配達", "Daffodil BouquetをDarcyに渡す。", "はい、あなたの花束よ。Daffodilsを選んでおいたわ。私の一番好きな花なの！", "やあ、また会ったね、{name}。私が届けさせたお昼、Parkerは気に入ってくれたかい？", "まあ、素敵だね! 早く水に活けたいな!\n\nでも……これはMartieの大好きな花じゃないか。Parkerったら、この花束のためにあの嫉妬深い女狐のところへ行かせたんじゃないだろうね? 誰に贈る花か、彼女に言ったりしてないよね? もし言ったなら、彼女が花に毒を盛っていても驚かないよ。\n\nああ、でもあなたのせいじゃないよ。ありがとう、はい、これが食事だよ。", 0xf4e8832d, 0x70089ffd, 0x81de289a, 0xa471da13, 0x046112fa, "....." },
  [132] = { "The Defias Brotherhood", "Wiley's NoteをWestfallのGryan Stoutmantleに渡して下さい。", "これから話すことで、俺は命を落とすかもしれない。Defiasの一味が何か大きなことを企んでいる。最後に聞いた話じゃ、奴らはいろんなgnollやkobold、それにゴブリンとまで手を組んでいるらしい。\n\nこのメモをStoutmantleのところへ持って行ってくれ。この件について俺が知っていることは、そこに全部書いてある。", "おかえり、{name}。Wileyは何と言い訳していた？", "ふん! あの時に悪党を駄目にしておくべきだったな。だがこの情報は非常に重要だ。上出来だぞ。", 0x2a2224c0, 0x790d2fad, 0xda37a6c4, 0xf10ad446, 0x494d4d81, "....." },
  [133] = { "Ghoulの人形", "Ghoul Rib 7本を集めて、掘っ立て小屋の中にいるAbercrombieに渡して下さい。", "町の守りから遠く離れて暮らしてるから、ghoulsや歩く死者に食われてないのが不思議なくらいだよ！実際、つい昨日もBone Chewersの群れがうちの壁を叩いてたんだ！\n\n人形を作りたいんだ。いわばGhouls用の「かかし」さ。そのためにはGhoul Ribsが要る。Flesh Eaters、Bone Chewers、Brain Eaters、Rotted Ones、Plague Spreadersから手に入るよ。\n\nあばら骨を集めてきてくれたら、いくらか金で礼をするよ。", "家の裏をGhoulの群れがうろついている音が聞こえる気がする。早くあの人形を立てないと！ Ghoul Ribsは持ってきてくれた？", "ああ、ありがとうよ。仕掛けにちょうど良さそうだ!", 0x47c35f07, 0x7edccc10, 0x24de59e7, 0xa7553706, 0x54d74c26, "....." },
  [134] = { "泥棒Ogre", "Abercrombie's CrateをAbercrombieに返して下さい。", "数週間前、家から遠く離れたところで薬草を摘んでいたら、ogresの群れに襲われたんだ！私は逃げたが、大事な道具と薬草の入った木箱を置いてこなきゃならなかった。\n\n私を追い払った後、ogresはDuskwood南部のogreの塚へふんぞり返って戻っていった。私の木箱はきっと塚の近くのどこかにあるはずだ。\n\n頼むよ、{name}、あの木箱を取り返してくれ。なくてひどく困ってるんだ。", "私の木箱を持っているのか？ それなら、どうか……早く渡してくれ！", "Necに感謝を……いや、お前にこそ感謝だ、{name}！報酬は十分すぎるほど稼いだな。\n\nアハ！嬉しい！楽しい夜が待っているぞ！！", 0xfbfe2bc3, 0x2e382dde, 0x04be4123, 0xb52cb521, 0x8cc08e89, "....." },
  [135] = { "The Defias Brotherhood", "Wiley's NoteをStormwindのMathias Shawに渡して下さい。", "WileyがStonemasonsについて書いたのは何故なんだろう。多分、筆が滑ったんだな。Defias団はStonemasonsと関係があると考えられるかもしれんぞ。確実に知っている男が一人いる。SI:7のリーダー、Mathias Shawだ。彼にWiley's Noteを見せて、深まる謎について彼が何か追加情報を持っているかどうか調べてほしい。Shawがなかなか見つからなかったら、Old Townの兵舎を探してくれ。", "私に何の用だ？ 私はとても忙しい身なのだ……", "この問題はStoutmantleが思っているよりももっと複雑かもしれない。", 0x2a2224c0, 0x95f26f8f, 0x0882b814, 0x12eeb2a7, 0x48d02edd, "....." },
  [136] = { "Captain Sanderの隠し財宝", "Captain Sanders'の足箱を見つけ、次の手がかりを探す。", "これを読んでるってこたぁ、Ol' Captain Sandersは海の底の墓に眠ってるってわけだ。だから俺のお宝は今やお前のもんだ。手がかりをたどりさえすりゃいい。\n\nまずは俺の足元用の箱を見つけな。今ごろは砂に半分埋もれてるだろうよ。場所はWestern Coast of Westfall、難破船の近くだ。難破船はたくさんあるが、錆びた錨が海岸にあるのは一つきりだ。その錨を見つけりゃ、俺の箱も見つかる！ 次の手がかりはその中を探しな。", nil, "古い衣装箱がゆっくりときしみながら開く。中身は砂と水だけのようだ。いや、待て! 小さなカニが、宝の手がかりをはさみに挟んで這い出してきた!", 0x06bba426, 0x0a7c4cb3, 0xa2d6009c, nil, 0x386945df, "...m." },
  [138] = { "Captain Sanderの隠し財宝", "崩れた煙突の近くにある古い樽を見つけ、次の手がかりを探す。", "宝の手がかりにはこう書かれている。よくやったな、相棒！ 次は真東へ向かえ。崖を東へ登り、道へ向かって東へ進め。道端にある古い煙突の廃墟を探すんだ。そこに古い樽があって、次の手がかりが入ってるぜ。", nil, "よくやった、トレジャーハンター!", 0x06bba426, 0x1440041d, 0xf26acf24, nil, 0x7ca63b45, "...m." },
  [139] = { "Captain Sanderの隠し財宝", "風車の隣にある空の水差しを調べ、次の手がかりを探す。", "樽の中を探ると、羊皮紙がもう一枚見つかった。そこにはこう書かれている。「さて、この樽から北を向け。まっすぐ進み、海辺の崖に立つぽつんとした風車の隣に空っぽの酒瓶が見えるまで歩き続けるんだ。その酒瓶のまわりを探ってみりゃ、お目当てのもんが見つかるかもしれねえぞ。」", nil, "大当たりへの道を進んでいるぞ、宝を探す者よ!", 0x06bba426, 0x7ab5b5af, 0x0b996e82, nil, 0xd8473e97, "...m." },
  [140] = { "Captain Sanderの隠し財宝", "Captain Sanders'の宝箱を見つけて開け、報酬を手に入れる。", "思ったとおり、Old Jugの奥深くにSanderの宝への新たな手がかりがあった。インクはところどころにじみ、紙はウイスキーの匂いがするが、文章の一部は読み取れる。「わしの古いウイスキーの酒瓶を見つけたんなら、宝はもうすぐだ！ 瓶から西を向いて、岸まで歩いて下りろ。水際に着いても、そのまま進め！ わしの宝箱がある島が見つかるまで、まっすぐ西へ泳ぐんだ！」", nil, "古い宝箱の蝶番は錆びついているが、まだ動く。無理やり箱をこじ開け、お宝を手に入れた。\n\nおめでとう!", 0x06bba426, 0x01f557fa, 0xc7539c95, nil, 0x6ef48c97, "...m." },
  [141] = { "The Defias Brotherhood", "Shaw's ReportをWestfallのGryan Stoutmantleに渡して下さい。", "Stonemasons' GuildはEdwin VanCleefという男が率いていた。VanCleefは、First WarでオークたちにStormwindが破壊された後、その再建を担っていた人物だ。どうやらVanCleefとその部下たちは、再建が終わった後の王の扱いに不満を抱いていたらしい。それで一つ二つ説明がつくかもしれんな。\n\nWestfallにいる君の師匠宛てに、もっと詳しい報告を書いておいた。すぐにこれを届けてくれ！", "Master Shawは何か手がかりをくれたか？", "Edwin VanCleef……その名はよく知っている。とても勤勉で才能のある男がそんな悪党に変わるんだと思うと、ひどくがっかりするよ。もっと証拠が無ければ信じられない。", 0x2a2224c0, 0x7a7f1227, 0x42f42474, 0xb9945de0, 0xe1668a3c, "....." },
  [142] = { "The Defias Brotherhood", "WestfallのDefias Messengerを見つけ出し、Stoutmantleにメッセージを渡して下さい。", "Defias団の隠れ家の位置を突き止めなければ。{name}、MoonbrookとGold Coast QuarryとJangolode Mineを結ぶ道でDefias Messengerを見かけたと偵察から報告があった。そいつを捕まえてもらいたい。もし抵抗したら殺して、そいつが運んでいる物を持ってきてくれ。", "{name}、何か情報は集められたか？ 伝令は見つかったか？", "これはVanCleefが指揮を執っているという確かな証拠だ。あとはDefiasの一味がどこに潜んでいるかを知るだけでいい。\n\n君が留守の間に幸運があった。Saldeanの荷馬車を盗もうとしていた盗賊を捕らえたのだ。奴は命と引き換えに隠れ家へ案内すると約束した。その裏切り者を守り、隠れ家を明かさせてほしい。場所が判明したら私のところへ戻ってきてくれ。", 0x2a2224c0, 0x243342aa, 0xf31363c7, 0x484fe496, 0xf9189f7b, "....." },
  [143] = { "Westfallへの使者", "自分の書いた嘆願書をWestfallのGryan Stoutmantleへ届けてほしいとMagistrate Solomonは言っています。", "Stormwind Armyに何かおかしなことが起きている。とうに大軍でここに来ているはずなのだ。だが、我々には時間の猶予などない。Lakeshireの民が、さらなる助けを求める努力もなしに命を捧げていくのを、黙って見ているつもりはない。Westfallで民兵団が結成されつつあると聞いた。\n\nこの嘆願書を彼らの指導者、Gryan Stoutmantleに届けてくれ。王が予備兵を送ってくるまで、Stoutmantleの部下たちがここで支援してくれるかもしれん。", "よく来た、{class}。The People's Militiaに何の用だ？", "良き使者よ、君は主人によく仕えたな。", 0xf6c85306, 0x57b20c17, 0xf7e36946, 0xd03393da, 0x8b9e2f77, "....." },
  [144] = { "Westfallへの使者", "Gryan Stoutmantleの返事を持ってMagistrate Solomonのところへ戻る。", "Magistrate Solomonの手紙は読むのがつらい。だが、彼がWestfallで繰り広げられている戦いを知らないのは明らかだ。知っていれば、Militiaに助けを期待するような真似はしないだろう。Stormwindが我々まで見捨てていなければ、Militiaなど必要なかったのだ。\n\nこの返事をRedridgeにいるお前の上官に届けてくれ、{class}。そして、良き男たちを失って私の心は重いと伝えてほしい。", "People's Militiaはもうすぐ来ると思ってよいのか？ Lord Stoutmantleの知らせは良いものか？", "いやはや、これはまったく良くない。Stoutmantleの状況が、ここLakeshireの我々の状況と変わらないとは知らなかった。Stormwind Armyを民のもとから引き離すほど重要な作戦とは、いったい何なのだ? ふん、声に出して考え込むべきではないな。\n\nさあ、使者よ。町への貢献の対価として、この硬貨を受け取ってくれ。また頼むことがあるかもしれん。", 0xf6c85306, 0x82d09720, 0x39c0aa3b, 0x16225e09, 0x7726c3a3, "....." },
  [145] = { "Darkshireへの使者", "DarkshireのLord Ebonlockeへ手紙を届けてほしいとMagistrate Solomonは言っています。", "再びお前の助けが必要だ。Lord Ebonlockeに手紙を書き、彼の訓練された衛兵たち、Night WatchをLakeshireの防衛のために送ってくれるよう頼んだ。この知らせは速やかに彼のもとへ届かねばならん。細心の注意を払え。EbonlockeはDuskwoodの中心にあるDarkshireの町長だ。道から外れるなよ。", "遠くから旅してきたようだな、{class}。このDarkshireに何の用だ？", "はるばる来てくれてありがとう。これは実に重要な情報だ。", 0x74e46a13, 0xbe30acba, 0x0448bdaa, 0x1745350a, 0x089c2d62, "....." },
  [146] = { "Darkshireへの使者", "Lord Ebonlockeの返書を持ってMagistrate Solomonのところへ戻る。", "Magistrate Solomonを個人的に知らなければ、あの男は気が狂ったと言うところだ。Stormwindが援助を拒むから、Night WatchをLakeshireへ送れだと？ Night Watchが結成されたのは、この忌まわしい魔法がこの地に染み込んだ時にStormwindが我々を見捨てたからだ。もし私のNight Watchを送り出せば、衛兵たちが森の端に着く前に、この町は悪に呑み込まれてしまうだろう。\n\nこの返事の手紙をLakeshireにいるお前の主人へ届けてくれ。", "ああ、戻ったか、使者よ。Night WatchがDarkshireから向かっていると元帥に伝えておこうか？", "光にかけて! Stormwind ArmyがWestfallから撤退しただと。それに衛兵がもはやDarkshireを守っていないというのか? 何か裏切りが横行している。どうしてこんなことに?\n\nおっと、君の働きに報いるのを忘れていた、{class}。この硬貨を受け取ってくれ。では失礼する。Stormwindで何かがおかしい、真相を突き止めねばならん。", 0x74e46a13, 0x83daf12d, 0x98c1d172, 0x465827c6, 0x3452ae00, "....." },
  [147] = { "人狩り", "\"the Collector\" を見つけ出して殺し、Marshal Dughan のところへ Collector's Ring を持ち帰って下さい。", "「Collector」が鉱山から金を奪っているのなら、王国から盗んでいるということだ! 「Collector」に裁きを下し、スケジュールに書かれていた例の指輪を持ってきてくれ。奴が誰のために働いているのか、その指輪が教えてくれるかもしれん……。\n\nスケジュールによれば、「Collector」は Brackwell Pumpkin Patch に潜伏しているらしい。そこを探してみたらいいだろう。", "Collectorは見つかったか？ 奴が誰のために動いているのか分かったか？", "奴を見つけたのか？よくやった、{name}。もうElwynn Minesから「徴収」することはあるまい！\n\nそれに、見つけたこの指輪は興味深い……Stormwindの古いStonemason's Guildの会員指輪だ。なぜ下っ端の盗賊が職人ギルドの指輪を持っている？そしてなぜDefias Thievesが我々の鉱山から金を集めている？\n\n難しい問いだ。いつか答えが得られることを願う。", 0x3fd32b4a, 0xaffbf97d, 0xcaee2d0b, 0x03263e82, 0xe881e64e, "....." },
  [148] = { "Darkshireからの品物", "Madame Evaと話して下さい。", "ああ、哀れな老人はどうしたらいいんだ？Darkshireから品物が要るんだが、村はとても遠いし、わしはもう年寄りで体も弱い……とても行けやしない。\n\nDarkshireへ行って、Ghost Hair Threadを持ってきてくれないか？Darkshireの広場にある家にいるMadame Evaから手に入るよ。", nil, "あら、Ghost Hair Threadが必要ですって? 残念だけど今在庫を切らしてるのよ。でも、あなたのために作って差し上げられるわ……幽霊の髪の毛を手に入れられたらですけどね。", 0x3942c9e4, 0xe153bd5f, 0xf32e36c4, nil, 0xd45d9df9, "...m." },
  [149] = { "Ghost Hair Thread", "Spectral CombをBlind Maryに渡して下さい。", "Darkshireの南の丘にある古い農家には、Blind Maryという哀れで悲しい霊が取り憑いています。\n\nさあ、このSpectral Combを持っていって、Blind Maryに髪をとかすよう頼んでください。それから櫛を持ち帰ってくれれば、糸に必要なGhost Hairをそこから集めましょう。\n\nそれから気をつけてください。今あの家の近くには、闇のものが潜んでいますから……", "<すすり泣き> ああ、お願いだから、私を見ないで! この目は自分の手でえぐり出したというのに、まだあなたの視線を感じる!\n\n私は醜い! 醜いんだ! お願い、目をそらして!!", "これは何？櫛？素敵だわ！それに、こんなに硬くてもつれた恐ろしい髪なのに、するすると通っていく。\n\nああ、鏡さえあれば……", 0xe3bdde6f, 0x528815c6, 0x616f9a53, 0xe0b4c1fb, 0x47317f65, "....." },
  [150] = { "Murlocの密猟者", "Murloc Finを8個、LakeshireのDockmaster Barenのところへ持って行く。", "murlocが厄介なことになってきた。大きな群れの魚人どもがLake Everstillの岸辺に居着いて、手当たり次第に魚を獲っているんだ！ 湖の魚を食い尽くされる前に追い払わないと！\n\nmurlocを狩れ！ 奴らのfinsを8枚持ってきてくれたら、何かやれるかもしれないぞ……", "そのヒレは持っているか？ 急いでくれ、あのmurlocどもを湖から追い払わねばならん！", "よくやった、{name}。あのmurlocどもに手こずらなかったならいいが。\n\n海からこんなに離れたところで奴らを見るのは妙なものだ。何かから逃げてきたのではないだろうか……", 0x812e47f7, 0xbe5f0814, 0xc927bcbc, 0xabeb396e, 0x9a51f356, "....." },
  [151] = { "可哀想なBlanchy", "WestfallにいるVerna FurlbrowがHandfuls of Oatsを8個届けてくれるよう依頼しています。", "可哀想なBlanchy! 仕事をさせすぎてしまったせいで、この子は疲れきってしまったの。農場を発つ前にちゃんと餌はやったのだけれど、馬車が壊れてしまうなんてこと予想もしなかったのよ。この子にHandfuls of oatsを少し持ってきてやってくれたら助かるわ。\n\nWestfallの農場に行けばあるはずよ、そこを乗っ取ってるあの恐ろしい機械をなんとかできればの話だけれど。農場は南西にいくつかあるわ。", "Old Blanchyはもう弱りきっているんだ。あの子にやる燕麦を見つけてくれたかい？", "本当にありがとう、{name}! かわいそうなOld Blanchyもきっと大喜びだよ!", 0x9bfac4dc, 0x7daa1244, 0x1fc2eef2, 0xfc0646d0, 0x51216ba8, "....." },
  [152] = { "危険をはらむ海岸", "Tidehunterを7体、Warriorを7体、Oracleを7体、Coastrunnerを7体倒し、Westfall LighthouseのCaptain Graysonのところへ戻る。", "海岸沿いの難破船には気づいただろう。Great Seaはまさに危険な海だ。Westfallの海岸は安全にしておかねばならん。船乗りたちがうちの浜にたどり着いたとき、無事でいられるようにな。だがMurlocsが厄介なんだ。\n\nTidehuntersを7体、Warriorsを7体、Oraclesを7体、Coastrunnersを7体倒してくれ。そうすれば報酬が出るよう取り計らおう。", "Tidehuntersを7体、Warriorsを7体、Oraclesを7体、Coastrunnersを7体倒してこい。そうすればお前に報酬が渡るよう取り計らおう。", "よくやった、{name}。お前には戦いの才がかなりあるな。お前のおかげでCoast of Westfallはより安全な場所になった。", 0xcdad2308, 0x88ca96a9, 0xbc9bf3cb, 0xf2f2deb7, 0x27f90f2d, "....." },
  [153] = { "Red Leather Bandanas", "Sentinel HillにいるScout Galiaanに、Red Leather Bandanaを15束持っていく。", "Defiasの前線部隊の奴らが、ひっきりなしに変わっていやがるんだ。かなりの時間をかけて奴らの動きを追っていたんだが、その結果、一つの特徴をみつけたんだよ。ほとんどの奴らは、Red Leather Bandanaを着けているってことをな。\n\nそこで頼みたいんだが、俺にそのバンダナを15束持ってきてくれないか？報酬は勿論払うさ。", "red leather bandanaを15枚持ってきてくれれば、たっぷり払うぞ。", "いい仕事してるぜ、{race}さん。きつい仕事だっただろ。それに見合ったものを用意したから、一つ選んでくれ。", 0x91de9f29, 0x15be8c76, 0xdc4ad0de, 0xca1a09c5, 0x9ab69279, "....." },
  [154] = { "櫛の返却", "Ghost Hair CombをDarkshireのMadame Evaに返して下さい。", "いや！！！！！\n\n持っていって、この櫛を私から遠ざけて！\n\n私は化け物よ。もう誰も私を美しいとは思ってくれないわ！", "Blind Maryに会ってきたのを感じます。私のCombをお持ちですか……？", "これでGhost Hair Threadを一巻き作れますよ。それに何房か予備も手に入りました。お礼にいくらかお支払いしますね。", 0x67d027b2, 0x183f2e90, 0x78e5d132, 0x390dbc0c, 0x307b8fa2, "....." },
  [155] = { "The Defias Brotherhood", "Defias Brotherhoodの秘密の隠れ家までDefias Traitorを護衛して下さい。Defias TraitorがVanCleefとその手下が隠れている場所を示したら、その情報をGryan Stoutmantleに報告して下さい。", "で、Stoutmantleは俺を守るのにお前みたいなひょろっとした{race}をよこしたってわけか？まあ、仕方ねえな。仲間も何人か連れてきたほうがいいぞ。\n\n取り決めは分かってるよな？お前が俺の背中を守り、俺がお前をDefiasの隠れ家まで連れていく。だが俺のすぐそばにいろよ。Defiasのギャングは今、俺の首を狙ってるんだ。お前と一緒にいるところを見られたら、奴らは俺を殺しに来るぞ。\n\nお前と、集められるだけの仲間の準備ができたら知らせてくれ。", "私に何の用だ？ 私はとても忙しい身なのだ……", "本当に素晴らしいよ、{name}! VanCleefの奴め、どこに隠れているか分かったからには、もう我々のものになったも同然だ。", 0x2a2224c0, 0x3c4fa4f6, 0xf3c6ce7f, 0xa49dc7ac, 0xd5d9b9c8, "....." },
  [156] = { "Rot Blossom集め", "Rot Blossom 8本を集めてDarkshireのTavernkeep Smittsに渡して下さい。", "rot blossomsを持ってきてくれたら、zombie juiceをひと瓶こしらえてやれるよ。\n\nrot blossomsは妙な場所に生えるんだ。特に、Skeletal HorrorsやSkeletal Fiendsの頭蓋骨の中で見つかるって話だ……俺はそこまで近づいて確かめたことはないけどな！\n\nRaven Hill CemeteryにもTranquil Gardensにも、あの骸骨どもがうようよしてる。rot blossomsを探すついでに、奴らを片付けてくれてもいいだろう。Darkshireの町は感謝するはずだ。", "やあ、{name}。rot blossomはもう持ってきてくれた？", "よし、rot blossomを手に入れたな。Night WatchのAlthea Ebonlockeには、お前がskeletonを狩っていたと伝えておこう。\n\nDarkshireの人々を守り続けることはNight Watchにとって重い務めだ。Duskwoodで魔物の波を食い止める手助けをしてくれる者がいるという知らせは、実にありがたい。", 0x4964f847, 0x04339e2b, 0x9f150c59, 0xd77731e5, 0x03dd4941, "....." },
  [157] = { "糸の配達", "Raven Hill Cemeteryの北にある掘っ立て小屋のAbercrombieにGhost Hair Threadを渡して下さい。", "さあ糸ですよ、{name}さん。これには邪悪な霊の拘束から命のない物体に命を縫い込むことまで、千通りの用途があるのです。", "招かれざる霊を寄せつけないよう、戸口と窓にGhost Hair Threadを張り巡らせなければならない。手に入れてくれた？", "素晴らしい！これで見事に事足りる……\n\nさあ、善き{name}よ、その立派な行いへの支払いとしてこれを受け取ってくれ。", 0x80a7141b, 0x2aed716b, 0x68798fe6, 0x9910144d, 0xd4c4f3eb, "....." },
  [158] = { "Zombie Juice", "Tavernkeep Smittsと話して下さい。", "ある酒がひと瓶欲しいんだ。Zombie Juiceというやつだよ。DarkshireのScarlet Raven TavernにいるTavernkeep Smittsが持っているはずだ。\n\nそれと急いでおくれ、{name}。夜は冷えるし、血管にまた火をつけるには、あの一杯が要るんだ！", nil, "Zombie Juiceが要るんですか? うーん……あれは強い酒ですからね……普段はリクエストを受け付けてないんですよ。", 0xbabab408, 0xefdb9d5e, 0xbb7de0a2, nil, 0xee62c9dd, "...m." },
  [159] = { "ジュース配達", "掘っ立て小屋の中にいるAbercrombieにZombie Juiceを渡して下さい。", "ほら、Zombie Juiceだ……\n\n……それと、こいつの扱いには気をつけな。死人だって起き上がるくらい強いからな！", "寒く暗い夜に体を温めるには、あのZombie Juiceが要るんだ。手に入れてくれたか？", "千の感謝を、{name}。お前の愚か——いや……その優しさが、老いぼれの心を温めてくれる！\n\nさあ受け取れ、友よ。私の感謝のしるしだ。", 0x820ab7e9, 0x7ac1d84f, 0xb9ae7652, 0xbae73c5a, 0xf27a5a51, "....." },
  [160] = { "町長への手紙", "Darkshire町長のEllo EbonlockeにAbercrombie's Letterを渡して下さい。", "この手紙を、Darkshireの町長、Ello Ebonlockeのところへ持って行ってくれ。\n\n彼と私は古い友人でね……これを読んで、君が私のためにしてくれたことを知ったら……きっと私と同じくらい喜ぶはずだ! ハハハハ!", "Abercrombie……？ そんな名前の者は知らんな。そのAbercrombieとかいう男から、私宛ての手紙を預かっていると？\n\nでは、見せてもらおうか……", "<Elloは手紙に目をやる……>\n\nこれは何語だ？古代のもののようだ……私には読めない。", 0xbf2ebcd6, 0x60a07e98, 0xf87484eb, 0xb6aabb3e, 0xa50301f2, "....." },
  [161] = { "迫り来る闇の脅威", "奇妙な臭いのする粉を、Dun Modrにいる爆発物の専門家Ashlan Stonesmirkのところへ持って行ってほしいとChief Engineer Hinderweirは言っています。", "私の疑いが正しければ、これは一種の爆発性の粉だ。我々が何を相手にしているのか正確に知るため、爆発物の専門家に分析してもらわねばならん。Ashlan StonesmirkはDun ModrとThandol Spanを守る連隊に配属されていた。重大で危険な旅に出てもらう必要がある、{name}。\n\nAlgaz Gateを通り、Wetlandsを抜ける道を進み、Dun ModrにいるStonesmirkを訪ねよ。私の忠告を聞け。道から外れず、何があっても立ち止まるな！", "何か言ったか、お若いの？ 耳鳴りのせいでまったく何も聞こえやせん。おや、そこに持っとるのは何だ？", "ああ、Ol' Hinderweirが心配するのは賢明だな。", 0x285fa090, 0x10adbf1b, 0xc80198ee, 0xbcaa84da, 0xdf7a71cc, ".....", nil, nil, nil, 0x60a6efdd, nil },
  [162] = { "Silithidの発生", "Insect Analysis ReportをDarnassusのGracina Spiritmightのところへ持って行って下さい。", "この報告書を、こういうことに実務的な知識を持っている誰かのところへ持っていってほしい。\n\nGracina Spiritmightというナイトエルフの学者を知っている。Azerothの生態系に特有の生き物の研究に長い時間を費やしてきた人で、そのうえ歴史家でもある！この脅威の正体を、そして何より止める方法を突き止める手伝いをしてくれる人が欲しいなら、彼女に報告書を渡してくれ。我々には助けが必要だ。\n\n最後に聞いた話では、彼女はDarnassusにあるTemple of the Moonに住んでいるそうだ。", "旅の方、あなたに平安と静けさがありますように。今日はどうして私を訪ねてきたのですか？", "この報告書……我々ナイトエルフは、ここに記された恐怖を知っています。Fizzledowserがこれを、そしてあなたを私のもとへ送ったのは賢明でした。\n\nこの生き物たちはTanarisの砂漠を瞬く間に食い尽くすでしょう。まさしく、我々すべてが直面しうる最大級の脅威にほかなりません。この名を覚えておきなさい、{name}。silithidです。ここに記された昆虫がsilithidであり、彼らはHordeとAllianceの双方が直面する最大の脅威の一つが操る道具なのです。\n\n以前にそれを見抜けるだけの賢さが我々にあったなら。", 0x50a8e84e, 0x8b05a47f, 0x19213fbe, 0x9b43121a, 0x9cd1da1e, "....." },
  [163] = { "Raven Hill", "Raven Hillに何が棲み着いているのか確かめて下さい。", "Raven Hillで何かがおかしい、{name}。Calorが言うには、誰かが……いや、何かが、あそこの建物に取り憑いているそうだ。2晩続けて影が動くのを見たし、その前の晩には窓のひとつに明かりが見えたと言っている。\n\n君の言うとおりDuskwoodの安全を気にかけているのなら、Raven Hillに取り憑いている怪物の正体を突き止めてくれ。", nil, "違う! 殺さないでくれ! ただの人間だよ……Jittersだよ!! 至るところあいつらがいて……逃げられないんだ! Raven Hillの化け物? そそそそんな馬鹿な。俺は人畜無害のJittersだよ。", 0xcfccf464, 0x22ae4d0b, 0x2349862f, nil, 0x6183fbd0, "...m." },
  [164] = { "Svenへの配達", "Svenに物資を配達して下さい。", "Svenを知っていますか？あの人こそ光の務めを果たしている人です！彼とその仲間たちは、Duskwoodの北西の端に野営地を構えています。\n\n残念ながら人数がとても少ないので、町へ物資を取りに行く人手すら割けないのです。この物資を彼に届けてもらえませんか？", "頑丈そうだな、{class}。我々の戦いに加わりに来たのか？", "これはすごく役に立つよ。Carevin家の人からの援助にはいつも感謝してる。これはちょっとした手間賃だ。", 0x47ecd948, 0x353999cb, 0xebb9fbaa, 0xe4428de9, 0xa502323b, "....." },
  [165] = { "隠者", "Raven Hill墓地の掘っ立て小屋にいる老人を調べて下さい。", "かなり頻繁に物を買いに来ていたお年寄りがいたの。でも、このところ見かけてないわ。私の記憶が確かなら、あの人はRaven Hill墓地を見渡す小屋に住んでいたはずよ。何か起きてないか調べてきた方がいいんじゃないかしら。", nil, "Elaine Carevin？ヘヘ、ああそうだ……もちろん、Carevin家だな。\n\nいや、何も問題はない。ただ、今の私には町へ出るのが難しくてな。道は危険だし、若くもなっていかん。老いぼれのために、いくつか頼まれごとを聞いてくれんか？", 0x424f8542, 0x6e8400ee, 0x94338923, nil, 0x8022318a, "...m." },
  [166] = { "The Defias Brotherhood", "Edwin VanCleefを殺し、その首をGryan Stoutmantleに渡して下さい。", "終えるべき仕事があとひとつ残ってる。Edwin VanCleefを暗殺しなくてはならない。どんな奴であれ死刑宣告をするのは悲しいことだが、VanCleefをきっちり葬ることはWestfallの人々の大義のためだ。それを成し遂げたら、悪党の首を持ってきてくれ。", "Edwin VanCleefの追跡はどうなっている？", "{name}、その勇気は見事だ。People's MilitiaはWestfallの民のための働きに感謝する。VanCleefが死んだことで、Defias Brotherhoodの終わりの始まりが記されたのだ。近いうちに、この麗しい地の平原に再び平和が訪れることを願う。\n\n貴殿に敬礼を！", 0x2a2224c0, 0xaf5696f5, 0xeeda81af, 0xb9d86261, 0x9f2be902, ".....", nil, nil, nil, nil, 0xf7825732 },
  [167] = { "おお兄弟よ……", "Foreman ThistlenettleのExplorers' League BadgeをStormwindのWilder Thistlenettleに渡して下さい。", "わしらはWestfallの広大な鉱山の奥深くにいた。Moonbrookの納屋の下に隠された鉱山だ。あの臭え盗っ人どもがどこから来たのかは見当もつかん。とにかく、坑道が崩れてな。わしは抜け出せたが、他の連中は……その……他の連中からは音沙汰がない。\n\nお前さんなら、あそこでもっとうまくやれそうだ。わしの兄弟を探してくれたらありがたい。あいつはいつもExplorers' League Badgeを持ち歩いていた。本人が見つからなくても、そのバッジさえあれば、少しは心が安らぐだろう。", "私の兄弟の手がかりは何か見つかった？ これだけ時が経っても、まだ望みはあるのだろうか？", "不安が的中していたよ。可哀相に……。でも、謎に結末をもたらしてくれて感謝している。たとえ厳しい結末であったとしても……。", 0xc4d380c0, 0xe0579023, 0xa169aa0b, 0x9c2bb4b4, 0x9c87936b, "....." },
  [168] = { "思い出集め", "Miners' Union Card 4枚を手に入れ、StormwindのWilder Thistlenettleに返して下さい。", "鉱山のトンネルが落盤したあの恐ろしい日に、友人はほとんど死んでしまった。もしMoonbrookの鉱山へ行くことがあったら、どうか友人たちの身元を確認できるようなものを探してほしい。Miners' Union Cardを見つけたら、私のところへ持ってきてくれ。友人の家族があの恐ろしい出来事から何かを解明できるようにするつもりだ。", "昔の同僚たちのMiners' Union Cardsは取り戻せたか？", "集めてくれてありがとう、{name}。君の取り組みは、あの惨事による死者に平穏をもたらすのを助けてくれた。このことをみんなの家族に知らせるよ。", 0x2c56586a, 0xe0ab3ca6, 0x610a9b53, 0x358b3d1b, 0x320f3ed3, "....." },
  [169] = { "指名手配：Gath'Ilzogg", "Gath'Ilzoggを倒し、その首をLakeshireのMagistrate Solomonのところへ持って行って報酬を受け取る。", "指名手配！ Gath'Ilzogg、Stonewatch KeepへのBlackrockの攻撃と、Lakeshireの町への襲撃を率いる首領。\n\nGath'Ilzoggは極めて危険である。報告によれば、奴は最近攻め落とした砦に立てこもり、人類に対するBlackrock氏族のさらなる悪事を企てているという。このオークの蔓延は、いかなる犠牲を払ってでも鎮めねばならない。Gath'Ilzoggの首をMagistrate Solomonのもとへ届けた勇敢なる者には、手厚い報酬が与えられるであろう。", "そこに何を持っている、{race}？", "素晴らしい働きだ、{name}! Gath'Ilzoggはあの野蛮な連中を率いて戦い、罪なき人間を大勢殺した。雪辱は果たされた。これはStormwindの王国のために砦を奪還する第一歩だ!", 0x1fa3cb70, 0xdb0eb6e4, 0x8a4b873e, 0x46dc827d, 0x5c3ce0be, "....." },
  [170] = { "新たな脅威", "Balir Frosthammerは、6匹のRockjaw Troggsと6匹のBurly Rockjaw Troggsを倒して欲しいと思っている。", "手を貸しに来てくれたんだといいんだが、{class}。この前のtroggの襲撃以来、手助けはいくらあっても足りんのだ。\n\n聞いた話じゃ、あの厄介者どもはあちこちの土地に湧いて出ているそうで、Coldridge Valleyも例外じゃないらしい。南東の丘一帯や凍った湖の近くで姿を見かけられている。\n\nそれだけじゃない。ほんの数晩前には、西にある我々のキャンプが襲われて占拠されてしまったんだ！\n\nここは少々人手が足りなくてな、若いの。troggどもを追い返すには腕っぷしの強い者が必要なんだ。", "しぶといチビどもだろう？", "もし、私たちの身に降りかかった厄介ごとが、この国のどこかで起こっていることの現れだとすれば、いやなことだが、これはその最初の一端なのだろうな! 王と評議員会がtroggらの脅威に対して、何らかの措置を講じていることを、私はただ願うばかりだよ。", 0xea33a69d, 0x6b72f6c0, 0xa8fc7352, 0x37fa0bba, 0x09e25d88, ".....", nil, nil, 0x6c85e362, nil, nil },
  [171] = { "Alliance の守り人", "Cathedral DistrictにいるOrphan Matron NightingaleにHuman Orphan Whistleを渡し、預かっている子をStormwindの孤児院へ帰して下さい。", "本当に優しくしてくれたね、{name}。Children's Weekにこんなに楽しく過ごせるなんて、夢にも思わなかったよ。ありがとう。自分に起きたこととかで悲しくなりたくないんだ――両親はいつも、どんな嫌なことが起きても乗り越えなさいって言ってた。あのね、大きくなったら英雄になりたいんだ……あなたみたいな。\n\nこんなこと言うのは悲しいけど、もう家に帰る時間なんだ。戻ろう。寮母さんに、あなたがどんなにすごい人か話してあげるね！", "また会えて嬉しいですよ、{name}。Children's Weekの間、引き受けてくださったお務めは果たしましたか？", "天の祝福がありますように、{name}。あなたはRandisのために、ほとんどの人が考えもしないほどのことをしてくださいました。ありがとう――あなたはAllianceの空に輝く星です。\n\nどうか、時間が許すなら、また私たちに会いに来てください。Randisも喜ぶでしょうし、私もうれしいです。\n\nRandisはあなたととても楽しく過ごしたんですよ、{name}。自分を思い出してもらえるよう、お気に入りのペットを1匹あなたに贈りたいそうです。", 0x7c77ad68, 0x83a21456, 0x0fb0bc39, 0xfd180aa5, 0xe231992f, "....." },
  [172] = { "Children's Week", "Children's Weekの期間中に面倒を見る子供と話すため、Orcish Orphan Whistleを使って下さい。", "この孤児院を手伝って下さるのですか? あなたに恵みあれ、友よ。Children's Weekの援助は、大変貴重なものとなりましょう。\n\nこの笛をお持ち下さい。これは短期間……通常はChildren's Weekの間だけしか使えません。笛を吹くと、面倒を見る承諾をした子供と話すことができるでしょう。もう一度吹くと、子供は帰ります。\n\nぜひ{name}、笛を吹いて子供とお会いになって下さい! その子はあなたにすごく会いたがっていると思いますよ。", nil, "はいよ! 僕の名前はGrunth、あなたが僕の面倒をみてくれるんだよね? 冒険者なんだね、ママとパパみたいな。寮母さんは名誉の戦死だって言うんだ。あなたに会えて嬉しいよ。\n\n一緒にいろんなことをしたいな。やりたいことがいくつかあるんだ。あと、寮母さんが言うには、期間中はきょうだいみたいになってくれって。僕もすっごくそんな風にしてみたい。", 0x70336621, 0x77f9f0a9, 0x427476d3, nil, 0x06358008, "...m.", nil, nil, nil, nil, 0xd6c28757 },
  [173] = { "森のWorgen", "Nightbane Shadow Weaver 6頭を殺して下さい。", "闇は抗いようもなくDuskwoodへ引き寄せられているようだ。Master Carevinの使命は、悪と異端を追い払うことだ。我々の尽力によってこそ、Darkshireの人々は守られている。\n\n自分が我々に加わるにふさわしいと思っているのか？\n\n私もかつては君と同じように考えていた。Watchの怠慢に幻滅して、Master Carevinの下に加わったのだ。自分を証明したいなら、言葉によってではない。\n\nBrightwood Grove（明るい、だと？はっ！）とRotting Orchardで、Nightbane Shadow Weaverのworgen相手に腕を試してみろ。", "{name}、狩りの首尾はどうだ？", "見事だ、{name}。自分の身を守れるだけの力はあるようだな。その腕前にふさわしい、もっと手応えのある試練を見つけてやれるかもしれん。\n\nだが奇妙だ……worgenはまるで何もないところから現れたかのようだった。もっとも、国境を越えて移り住んできた他の奇怪な生き物たちを思えば、数ある懸念の一つにすぎんのだろう。", 0x47dbaa77, 0xdbe54601, 0x0c5c5fbf, 0xc089edc0, 0x3d143d4d, "....." },
  [174] = { "星座を求めて", "DarkshireのViktori Prism'Antrasは、bronze tubeを持ってくるよう求めています。", "ノームの友人のCogが、星を覗き見る装置を作る手伝いをすると約束してくれた。魔法を超えたところに、この森の奇妙な変貌を説明できる真実があるのだ。\n\n腕の立つエンジニアが作ったブロンズの筒を持ってきてくれ。Cogの設計図によれば、それが最初の段階だ。", "bronze tubeを作れる腕のいい技師は、もう見つかったかい？", "完璧だ、{name}。第一歩は完了!", 0xb0b2f53c, 0x95b70dc4, 0x93fe2947, 0x7340ad08, 0xfdd8d8da, "....." },
  [175] = { "星座を求めて", "Maryを探して、Viktoriの計画のために鏡を手放すよう説得して下さい。", "Cogの設計書によると、今度は光を反射するものが必要らしい。いつも手鏡を持ち歩いているんで有名なMaryという名前の女性がいるはずだ。Maryを探し出して、この計画のために鏡を貸してくれるかどうか聞いてくれるね? 彼女は以前Duskwood南部に住んでいたと思ったよ……。", nil, "ええ、手鏡を持っていたわよ。", 0xb0b2f53c, 0x5c290da2, 0xbbc7b806, nil, 0xf80d3335, "...m." },
  [176] = { "お尋ね者: Hogger", "Hoggerを始末し、Huge Gnoll ClawをMarshal Dughanのところへ持って行って下さい。", "指名手配：Hogger\n\n巨大なgnoll、HoggerがElwynnの南西の森をうろついている。これまでの捕縛の試みはすべて力ずくで退けられた。\n\nStormwind Armyはこのgnollに多額の賞金を懸けた。報酬を得るには、賞金ハンターはHoggerを倒した証拠をGoldshireのMarshal Dughanのもとへ届けること。", "ああ、Hoggerには私も部下もずいぶん手を焼いている。あの獣について何か報告があるのか？", "ハッハッハ！！よくやった！誰もあのモンスターを倒せないと思ってたのだ！\n\nよし、これが報酬だ、{name}。本当に感謝する。あのGnollは、Blackrock Spireくらいに頭痛の種となっていたのだ。", 0x9dcd29e7, 0x318a3a3b, 0xab83e5ae, 0xadee0c74, 0xc7de9815, "....." },
  [177] = { "星座を求めて", "Blind Mary's Looking GlassをInsane Ghoulから取り戻し、DarkshireのViktoriに渡して下さい。", "あの手鏡は私の最高の宝物だった……あの出来事までは。あれが起きた後、納屋の後ろに捨てたの。あそこを徘徊してたInsane Ghoulがいたから、多分あいつが拾ったと思う。あの悪魔のようなけだものはTranquil Gardens Cemeteryに住んでるって噂よ。", "星を見る装置の作りかけをCogに見せたら、感心してたよ。反射する装置は見つかったかい？", "最高だ! 完璧に使えるよ。どうもありがとう!", 0xb0b2f53c, 0x7a6c1b09, 0xc5f77146, 0x22ff6d7e, 0x34eef752, "....." },
  [178] = { "Theocritusの回収", "Faded Shadowhide PendantをTheocritus the Mageのところへ持って行く。", "<実体のない声が聞こえる……>\n\n驚くことはない。私はTheocritus、Elwynn ForestにあるTower AzoraのHigh Mageだ。そなたが手にしているペンダントは、Shadowhide Gnollsとその主Morganthとの連絡手段なのだ。\n\n何か月にもわたる研究を経て、私もこのペンダントを通じて連絡できると考えている。この言葉が聞こえているなら、私の呪文は成功したということだ。\n\nこのペンダントを私のもとへ持ってくるのだ。その働きに報いよう。", "ペンダントを通して私が話しかけた、だと？ ふむ……それを渡してくれ、調べてみたい。", "感謝します、{name}。何週間も前にShadowhide Pendantsへあの伝言を送ったのですが、失敗だと思っていました。けれど、かなり遅れたとはいえ、呪文は少なくとも一部のペンダントには届いたようです。\n\nいずれは、ペンダントを通して攻撃を送り、それを身につけたShadowhide Gnollsを動けなくする方法を学びたいと思っています。\n\nですが、それが可能になる前に、まだまだ研究が必要なようです。", 0xd1b6915b, 0xe9f541db, 0x7788c2a9, 0xdac36d0d, 0xd28bd097, "....." },
  [179] = { "ドワーフの道具屋", "Sten Stoutarm は8個のTough Wolf Meatを欲しがってる。", "おや、何かな？手を温めるものが要りそうな様子だね、うん？\n\nいいものがあるよ。素敵な暖かい手袋さ。私は親切な性分だから、ぴったりの手袋を喜んで用意してあげよう。ただし、条件が1つある。\n\nwolf meatを取ってきてほしいんだ。いい取引だろう、うん？wolf meatを持ってきてくれれば、凍傷で指を失わずに済むようにしてあげる。さあ、どうする？", "狼に少々手こずっているのか？ 牙や爪や、その他の尖ったところは避けるのが賢明だぞ、な？", "おぉ！すばらしい！狼の肉はいいよな。おっと、心配するな, {name}, 約束は忘れちゃいないよ。ほら、これがあんたのだ。", 0x26b28f66, 0x458fcb05, 0x26a8c43e, 0x4ab5a842, 0x3fbf9365, "....." },
  [180] = { "指名手配：Lieutenant Fangore", "Lieutenant Fangoreを倒し、その前足を持ってLakeshireのMagistrate Solomonのところへ戻る。", "お尋ね者：Lieutenant Fangore\n\nShadowhide Gnoll Clanの頭として知られ、町と王国の敵Morganthの下で動いている。Magistrate Solomonの命により、Stormwindを裏切ったこの卑劣な者は、死をもって手配されている。その死の証拠として、奴の手をMagistrateに見せよ。", "このCourtにいかなる知らせを持ってきたのだ？", "では、あの邪悪なLieutenant Fangoreは死んだのか? あの汚らわしい化け物がいなくなって清々した。君は実に勇敢だな、{class}。Township of Lakeshireは君の助力に感謝する。", 0x8dd050b7, 0xeaf3268f, 0xeb39ff35, 0xb6305447, 0x338741ad, "....." },
  [181] = { "星座を求めて", "Duskwood南部のogreの丘にいるZzarc'Vulを探し、DarkshireのViktoriに単眼鏡を返して下さい。", "さて、この装置を完成させるのに必要なものはあと1つだけだ。Cogの設計図では、何かしらのレンズが必要とされている。十分な大きさのレンズで私が知っているのは一つだけだが、手に入れるのはとても難しいだろう。\n\nDuskwood南部の塚にZzarc'Vulという名のogreが住んでいる。できるなら、そいつの片眼鏡を持ってきてくれ。それをレンズとして使おう！", "Zzarc'Vulを説得して、実験のためにモノクルを貸してもらえたかい？", "ついに! 天体観望装置の完成だ! ありがとう、{name}。これで研究を続けられるよ……。", 0xb0b2f53c, 0x7425bc28, 0x1a69cde0, 0x9e98b22d, 0x548bc1fc, "....." },
  [182] = { "トロールの洞窟", "Grelin WhitebeardはFrostmane Troll Whelpsを$N1体倒してほしいと言っています。", "私と兄弟のSenirは、トロールがもたらす脅威を調べるために、Dun Moroghの別々の場所へ送られた。Senateはtroggsの相手で手一杯だから、これ以上の厄介事は要らないというわけだ。\n\n見たところ、トロールどもはここColdridge Valleyにはたいした陣地を築いていない――ほとんどは南の洞窟にいる。軍を出すまでもないだろう。腕っぷしの強い者が何人かいれば十分すぎるほどだ。\n\nこの仕事を手伝ってみる気はないか？ 手を貸してくれるなら、報酬を出す権限が私にはある。", "私の知る限り、このトロールどもはFrostmane氏族の出だ。残念だが、それ以上君の役に立ちそうなことはあまり知らないんだ、{name}。", "くそっ！あの光に呪われたトロールどもめ！\n\n<彼は何度か息をつき、少し……落ち着いたようだ。>\n\n夜中に奴らの一団がやってきて、私の日誌を盗んでいった！あの役立たずの弟子など信用すべきでは……", 0xf6bcfb62, 0x7c46af93, 0x4d645eea, 0x76fb86d2, 0xfe9f5262, "....." },
  [183] = { "ボア・ハンター", "Talin Keeneye は12匹のSmall Crag Boarを殺すように求めてきた。", "イノシシ狩りの一日ほどいいものはないよな？\n\nとはいえ、ここColdridge Valleyにはイノシシが多すぎて、楽しみが半減しちまう。わざわざ突進させる必要もない。何もしなくても、みんな怒り狂って準備万端だからな。実際、最近はこのあたりにイノシシが増えすぎて、毎日の狩りが危険になってきたんだ。\n\n手短に言えば、イノシシを何頭か仕留めるのを手伝ってくれたらありがたい。", "狩りの首尾はどうだ？", "よくやったぞ！これでやっとのんびり狩を楽しめるよ、ありがとう, {name}.", 0xd760ac9a, 0xd69ca3ad, 0xc4ab0b64, 0xe02b27bb, 0xc985f25a, "....." },
  [184] = { "Furlbrow's Deed", "Furlbrow's DeedをFarmer Furlbrowのところへ持って行って下さい。", "これはWestfallにある広大な農地の権利書だ。Theodore Furlbrowという人物の署名があり、妻のVernaが連署している。そして権利書の裏には、急いで書きなぐった言葉がある：\n\n「Furlbrowを脅して権利書を手に入れた。自分の土地の権利書を偽造したいときに役立つかもしれないと思ってな。\n\nFurlbrow一家が面倒を起こすことはないだろう。最後に見たときは、壊れた荷馬車を抱えて立ち往生したまま、Westfallから出ていくところだった。」\n\nFurlbrow一家は権利書を返してほしいのではないだろうか……", "うちの農場の権利書を持ってるって？？ そいつはいい知らせだ！ 何日か前にごろつきどもに盗まれてな……もう戻ってこないと思ってたよ！\n\nどうか、渡してくれ。俺たちはWestfallを出ていくところで、当分戻るつもりはないが、もし戻ることになったらその書類が要るんでな……", "本当にありがとう、{name}！言った通り、この辺りはもう真っ当な者が暮らせる土地ではない。だが状況が良くなれば、この権利書のおかげで土地を取り戻せる。\n\n大したものは渡せないが、ほら——これを受け取ってくれ。", 0xfdbbe6bb, 0x11feda88, 0x57a4e970, 0x5eec9a09, 0x4f2a8d57, "....." },
  [185] = { "虎狩り", "Young Stranglethorn Tiger 10頭を狩って下さい。", "私がまだ幼い娘だった頃、父から虎狩りの技を仕込まれたの。\n\n若い虎のほうがずっと追いやすく、仕留めやすいわ。だから、あなたには簡単なところから始めてもらうわね。探検隊のキャンプの近くでよく若い虎が見つかるわ。\n\n追跡の腕を試して、獣を何頭か狩れるかどうかやってみなさい。", "まずは一番若い虎を仕留める腕を証明してもらわないと、{name}、これ以上君を鍛える自信が持てないな。", "よくやった、{name}。次へ進む準備ができたな。", 0x0ade906c, 0x767712d9, 0x073b2105, 0xd2e31413, 0x0aa57703, "....." },
  [186] = { "虎の追跡", "Stranglethorn Tiger 10頭を狩って下さい。", "腕を上げてきたな、{class}。今度は成熟した猫どもでお前の腕を試そう。今回はStranglethorn Tigersを$N1頭仕留めてこい。", "より大きな挑戦を望むなら、まず目の前の務めで実力を示さねばならない。Stranglethorn Tigerを10頭倒したら戻ってこい。", "感心したぞ、{class}。なかなか順調に上達しているな。", 0x0ade906c, 0x2266a59f, 0xe2cc63c5, 0xe191c5a6, 0x25c7eb32, "....." },
  [187] = { "虎狩りの腕", "Nesingwary's ExpeditionのAjeck RouackはElder Stranglethorn Tigersを$N1体倒してほしいと言っています。", "さて、賭け金を上げて、お前の腕を本当に試させてもらおう。Elder Stranglethorn Tigersを$N1頭倒せることを証明してみせろ。それができれば、Master Nesingwaryの前でお前を虎ハンターの達人と認める前の、最後の挑戦に臨む準備が整う。\n\nElder Stranglethorn Tigersは見つけるのが最も難しいだけでなく、倒すのも最も手ごわい。", "君が真の虎狩りの名人かどうかを決める最後の試練を与える前に、Elder Stranglethorn Tigerを10頭倒してもらわねばならない。", "実に見事だ。お前はもうほぼ準備ができていると思うぞ。", 0x0ade906c, 0xdbe4e5bb, 0x325e61e8, 0x90f93828, 0x83fb9c27, "....." },
  [188] = { "虎狩りへの精通", "Sin'Dall を狩り、その前足を持ち帰って下さい。", "これが私が課す最後の挑戦だ。我々は何週間も前から、捕らえどころのない一頭の虎を追っている。我々はその獣をSin'Dallと呼んでいる。これまでどの{race}も成し遂げたことのないことができるか、試してみろ。Sin'Dallを追い詰めて仕留めるんだ。やり遂げた証に、彼女の前足を持ってこい。\n\n彼女を追い詰めるのは容易なことではないぞ。", "Sin'Dallの追跡はどうなっている？", "実に見事だ、まったく！お前こそ真のMaster Tiger Hunterだ、{name}！", 0x0ade906c, 0x114be981, 0x41745fca, 0x8839bd00, 0xe11e588d, "....." },
  [189] = { "Bloodscalpの耳", "15個のBloodscalp Earsを手に入れて、Booty BayのKebokのところへ戻ってください。", "いまいましいトロルめ！　あいつらはジャングルでうちのエージェントたちを皆殺しにしてしまった！　あいつらとの小競り合いのために、すでにうちの精鋭たちも失ってる。コストがかかりすぎだ！ Baron Revilgazになんて説明すればいいんだ？\n\n断固とした行動・・・考えろ、Kebok・・・何もしないで今の地位があるわけじゃぁないんだ・・・そうだ！　なあ、あんた{name}だろ？　手をかしてくれるよな？　金はあるんだ！\n\n取引だ・・・15体のBloodscalp Trollsの耳を持ってきてくれたら、金を払うよ。", "うまくいったのだろうね？ そこらじゅうにいるんだ、あのトロールどもは。汚らわしい悪党め。\n\nおお、そうだ、それで思い出した！ 君の友にも必ず伝えてくれよ、な？ 手助けはいくらあっても足りないんだ！", "おお、素晴らしい、素晴らしい。当面はいくらか助かるよ……\n\n<彼は利益率と経費についてぶつぶつ言いながら、話を途切れさせる……>\n\n何だ？まだいたのか？報酬？ああ、そうだった……もちろんだ、ほら、これを取れ……十分すぎるはずだ。", 0xf70f659e, 0xfaefbe7f, 0xac5f321d, 0xf5fb4ed9, 0x9b73d3bc, "....." },
  [190] = { "豹狩り", "Young Panther 10頭を狩って下さい。", "Hemetが集めたこの腕利きの一団と狩りに加わりたいなら、腕の立つ豹ハンターであることを証明してもらう必要がある。簡単なところから始めるから、心配はいらない。まずは若い豹を10頭仕留めてみせてくれ。\n\n追い詰めるのは、難しさの半分にすぎないがな……", "真の豹ハンターなら、野に出て獲物に忍び寄っているはずだ。目標に本気で取り組め、{class}、さっさと戻るんだ。", "幸先のいいスタートだ、{name}！", 0xf277fe36, 0x0c74a1d2, 0xe2c184ed, 0x29237748, 0x640bf038, "....." },
  [191] = { "豹の追跡", "Panther 10頭を狩って下さい。", "さて、一段上を目指す準備ができたな。こういう大物狩りのハンター連中と付き合うにふさわしいと証明したいなら、豹を10頭仕留められることを示してもらわなきゃならん。\n\nでかいやつらは手ごわいぞ。さっきまで仕留めていた若いのほど楽じゃない。", "豹を10頭倒してこい！ 君の実力を見せてくれ！", "完璧な手際だ、{name}！", 0xf277fe36, 0x8e6629e4, 0x0c221846, 0x49d9f1f9, 0x56bf0c28, "....." },
  [192] = { "豹狩りの腕", "Nesingwary's ExpeditionのSir S. J. ErlgadinはShadowmaw Panthersを$N1体倒してほしいと言っています。", "さあ、ここからが難しいところだ。本物の豹ハンターなら、Stranglethornで最も危険なShadowmaw Pantherを仕留めて腕を示せる。こいつらを10頭倒せることを証明してみせてくれ。\n\n追跡が難しいと思うなら、一頭仕留めようとしてみるまで待つんだな……", "こんなところで何をしているんだ、{name}！ 茂みを這い回ってShadowmaw Pantherを10頭倒そうとしているはずだろう。大物ハンターを気取っていたんじゃなかったのか？", "よくやった、{name}！", 0xf277fe36, 0x6c008cf1, 0x17222a5d, 0x6aa8205b, 0xfb996f09, "....." },
  [193] = { "豹狩りへの精通", "Fang of Bhag'thera を入手して下さい。", "豹ハンターの達人として認められるまで、あと一歩だ。Bhag'theraという名の豹がジャングルをうろついている。今のところ、やつは我々の一行から逃れ続けている。その腕を使って、あの大物Bhag'theraを仕留められるかやってみてくれ。\n\nFang of Bhag'theraを持ってきたら、君は私の敬意を勝ち取ったことになる！", "Bhag'theraはなかなか捕まらない獣かもしれん。狩りの首尾はどうだ？", "じゃあ偉大なる Bhag'thera は死んだのか! 君に乾杯、{name} 。実に偉大な {class} だよ君は!", 0xf277fe36, 0x764ad8cd, 0x00370bd9, 0x4ec55746, 0xd32d274d, "....." },
  [194] = { "Raptor狩り", "Stranglethorn Raptor 10頭を狩って下さい。", "で、君は狩りの腕前が最高だと自負してるのかね? 今すぐ試してやれるぞ。ジャングルに分け入って Stranglethorn raptor 10頭を殺してきてくれ。どれほどの大物ハンターか確かめてやろう。\n\nそれと、raptorがどこで見つかるかは教えんぞ! 獲物を探すのも試練の半分だからな。", "焚き火のまわりで突っ立っていて獲物を仕留めたハンターなど、見たことがないぞ。Stranglethorn Raptorを倒すつもりだったのか、それとも老衰で死ぬのを待っていたのか？", "お見事だ、貴殿！", 0x7997e893, 0x52402212, 0xa23664bd, 0xb904e423, 0xfd97a575, ".....", nil, nil, nil, nil, 0xd64ae991 },
  [195] = { "Raptorの追跡", "Lashtail Raptor 10頭を狩って下さい。", "さあ、挑戦の難度を上げて、お前がついてこられるか見てみよう。ジャングルに入って、あの忌々しいLashtail Raptorsを$N1頭仕留めてこい。お前の実力を見せてもらおうじゃないか！", "真のハンターは獲物に狙いを定めるものだ。友よ、君は焚き火を囲んでおしゃべりするほうが気になっているようだな。さあ行ってLashtailを10頭倒してこい。でないと私が1度の狩りで、このいまいましいジャングルからあいつらを一掃してしまうぞ。", "これでこそ、いつもの暖炉の上にトロフィーの一つや2つを飾れるってもんだ！見事な仕留めっぷりだ、{name}！", 0x7997e893, 0xed0bcded, 0xc6541bb1, 0x28aa8e39, 0x00948fa4, "....." },
  [196] = { "Raptor狩りの腕", "Jungle Stalker 10頭を狩って下さい。", "次の試練をどうこなすか見せてもらおう。この辺りには用心深い種類のraptorがいる。我々はJungle Stalkerと呼んでいる。これまで君が腕試しをしてきた他の種類よりも、追い詰めて仕留めるのがはるかに難しい。Jungle Stalkerを10体倒したら、とっておきの狩り場を教えてやろう。", "ふん！ 何を突っ立っているんだ、{name}！ 真の大物ハンターは、獲物を視界にとらえたら決してあきらめないものだ。Jungle Stalkerどもがこの焚き火まで走ってきて、自分から飛び込んでくれるわけがないだろう。まったく、しょうがない若いのだな。", "ほっほう！！真のraptor退治の達人のお出ましだ！見事だ、貴殿！", 0x7997e893, 0xdf83bb59, 0xca1b1154, 0x9e05c728, 0xb4b1233d, ".....", nil, nil, nil, 0x9daf2f13, 0x9fd531de },
  [197] = { "Raptor狩りへの精通", "Tethis を狩って下さい。", "お前はジャングルでなかなかのやり手ぶりを見せてくれたから、この私でさえ仕留め損なった獰猛なraptorのことを教えてやろう。ここにいるAjeckは、この狡猾なraptorをTethisと呼んでいる。\n\n真の名手だと証明したいなら、Tethisを倒して奴の鉤爪を持ってこい。他のどの大物ハンターも成し遂げたことのない偉業になるだろう。", "Tethisの追跡はどうなっている？ あいつをキャンプまでずっと追っていったのか？", "raptor殺しのマスター {name}!\n\nいい響きじゃないかね?", 0x7997e893, 0x133c2f34, 0x70baae05, 0x5136e8b9, 0x4bcf67ef, "....." },
  [198] = { "Private Thorsenへの補給品", "Miscellaneous Goblin SuppliesをPrivate Thorsenに届けて下さい。", "ふむ。そうだな、実は君に頼めることがある。北にいるLieutenant Dorenとその部下たちが、我々からの定期の補給物資を必要としているんだ。\n\nまだ届けられていないし、トロールどもが襲ってくる中、誰かに運んでもらわねばならん。Dorenの野営地は、DuskwoodからStranglethornへの入り口にある道の北西だ。物資はPrivate Thorsenに渡してくれ。野営地にいなければ、その南を巡回しているはずだ。彼が引き受けてくれる。\n\nいいか、しくじったら弁償してもらうぞ。", "何だ? 何の用だ? ああ、ゴブリンからの物資か。{race}が届けに来るとは妙だな。いつもは自分たちの者を寄越すのに。まあいい……中身には触っていないだろうな? よしよし……我々の鉱山に何かあっては困るからな、そうだとも。", "この地雷があれば、あのけだもののKurzenとその手下から身を守れる。持ってきてくれてありがとう。もっと仕事が必要なら、何かやってもらうことを見つけられるだろう。それに、あのゴブリンどもと関わらずに済むしな、ん?", 0x23fdf43a, 0x99a6ef1b, 0xbc81431a, 0x234bdc46, 0x923184fe, "....." },
  [199] = { "迫り来る闇の脅威", "Chief Engineer Hinderweirのところへ戻り、見つけた手がかりを見せる。", "奇妙な匂いのする粉のサンプルを採取した。", "何か手がかりは見つかったか、{name}？", "控えめに言っても、これは憂慮すべき発見だ!", 0x285fa090, 0xf35c45fc, 0x6aeb4ed8, 0xf6db5556, 0x5a6f77c1, "....." },
  [200] = { "Bookie Herod", "Bookie Herod's Recordsを見つける。", "KurzenがThorsenの秘密を知っているなら、我々の中にスパイがいることになる。秘密がどう漏れたのか突き止めねばならん！\n\nKurzenの野営地にいるThorsenの連絡役は、Bookie Herodだった。HerodはKurzenの兵站士官で、Kurzen's Compoundの運営のことなら何でも知っている。Herodのメモや記録を手に入れられれば、Thorsenがどうやって見破られたのか分かるかもしれない。\n\n我々がまだKurzenの下にいた頃、Bookieの事務所は野営地で唯一の二階建ての家の最上階にあった。彼の記録はおそらくまだそこにあるだろう。", nil, "これはBookie Herodのメモと記録だ。\n\nその中には、野営地内の物資の一覧、Colonel Kurzenからの資材の要請、そしてさまざまな手紙や書簡がある。", 0x2543b951, 0x6c6806ee, 0x627d60e9, nil, 0xcbf8522c, "...m." },
  [201] = { "野営地の調査", "ハンターたちの野営地を見つけ、その場所をBooty BayのKrazekに報告して下さい。", "Lake NazferitiにあるVenture Companyの採掘キャンプの上流に、ハンターの一団が野営を張ったという報告を受けたんだ。普段なら気にもしないところだが、意外なことに、そこのハンターの一人がHemet Nesingwaryだと聞いてね。彼は確かに顔が広い、言ってる意味は分かるだろう。用心するに越したことはないのさ。\n\n{name}、その野営地を調べて、連中が何をしているのか見てきてくれないか？", "どうだ？ キャンプの場所は突き止められたか？", "ふーむ、やはりいつも通り俺の情報は正しかったわけだ。面白い。まあ、奴らが俺たちの事業を邪魔するような脅威になるとは思わんが、もしかすると俺たちの素晴らしい製品を必要としているかもしれんな。ふーむ……", 0x50149282, 0x44943830, 0xe4e522d4, 0x43f8cc3b, 0x755f5a49, "....." },
  [202] = { "Colonel Kurzen", "Kurzen Eliteを$N1体、Kurzen Subchiefsを$N2体倒し、Kurzen's HeadをRebel CampのLieutenant Dorenのところへ持って行って下さい。", "君は何度も実力を示してきた。その機転はKurzen本人にすら匹敵するようだ。君は我々反乱軍の救いとなるかもしれない……Kurzenと渡り合い、打ち勝つことができればな！\n\n奴はStockpileの奥深くから部下を指揮している。その洞窟に入り、護衛たちを突破して、Kurzenとその指揮官たちに立ち向かうのだ。\n\nさらばだ、{name}。私の希望と、部下たちの運命が君とともにある。", "Kurzenとその護衛どもは死んだと期待してもよいのか、{name}？", "報告を信じる勇気はなかったが、あなたは証拠を持ってきてくれた……Kurzenとその幹部たちは倒されたのだと。あなたは我々を救ってくれた!\n\nこのジャングルにはあらゆる脅威が満ちているが、Kurzenほど残酷な知性を持つものはいなかった。奴がいなくなった今、皆もっと安心して息ができる。", 0x042dcb1b, 0x4e83ca81, 0x67023d8c, 0x15539db6, 0xc3144039, "....." },
  [203] = { "第二の反乱", "Kurzen Jungle Fightersを$N1体倒す。\n\nRebel CampのSergeant Yohwaのところへ戻って下さい。", "我々はColonel Kurzen相手に負け戦をしている。奴は優れた戦術家であるばかりか、兵の数でも少なくとも10対1で我々を上回っている！生き延びるには、奴自身の隠密戦術を奴に使い返すしかない。\n\n東にある奴の野営地に入り、部下を倒してくれ。大勢な。そして援軍に囲まれる前に脱出するんだ。", "狩りがうまくいったことを願っているよ、{name}。君の助けがなければ、我々は奴を相手に長くはもたない。", "よくやった。あのJungle Fightersがいなくなれば、野営地への圧力も多少は和らぐだろう。\n\nだが、我々が相手にしている勢力を味わった今でも、まだ我々と運命を共にするつもりか??", 0x920d1eca, 0xd4521968, 0x800609b7, 0x4c689f52, 0xeb48efb4, "....." },
  [204] = { "悪い薬", "Jungle Remediesを$N1個とVenom Fern Extractを$N2個、Rebel CampのSergeant Yohwaのところへ持って行って下さい。", "Kurzenに勝ち目を得るには、奴の治療支援を封じねばならん。奴は周りに大勢のMedicine Menを集めている。そいつらはJungle Remediesで奴の軍を癒し、Venom Fern Extractsで我々の兵に毒を盛るのだ。\n\n我々の仲間を治すためにその治療薬が要るし、自分たちで治療薬を作れるよう研究するために、そのエキスの見本も要る。Kurzen Compoundで両方を探してくれ。治療薬は奴のMedicine Menが持っているはずだし、エキスはおそらく野営地の補給箱のどれかにしまってある。", "治療薬と抽出液を待っているぞ、{name}。", "よくやった、{name}。この薬があれば、もっと多くの仲間が生き延び、戦える状態を保てる。それに抽出液で我々自身の薬も作れるだろう。", 0x7cf8bc27, 0x6c4960fd, 0x8e2d6c1e, 0x840c7917, 0x272e1127, "....." },
  [205] = { "トロールの呪術", "Skullsplitter Fetishesを$N1個、Rebel CampのBrother Nimetzのところへ持って行って下さい。", "君が手に入れた伝承を私が研究している間に、邪悪なトロールの魔術の道具を集めてきてくれ。はるか南にいる第二の部族、Skullsplitterトロールの縄張りに入り、そのWitchdoctorsとMysticsからSkullsplitter Fetishesを手に入れるのだ。", "呪物は持っているか、{name}？ Kurzenの堕落の秘密が隠されているかもしれない……どうしても知りたいのだ！", "ありがとう。この呪物を調べて、Kurzenが悪に堕ちた秘密がそこにあるか確かめよう。", 0xc9df141e, 0xb19c7bf3, 0x2ea3dfd2, 0xbbf5cb3b, 0xd62ab0e4, "....." },
  [206] = { "Mai'Zoth", "Mind's EyeをRebel CampのBrother Nimetzのところへ持って行って下さい。", "Kurzenは死んだかもしれないが……奴を悪へと駆り立てたものはまだ生きている！研究の末、私はこれを突き止めた。Ogre MageのMai'Zothが、Stranglethorn東部の山地にあるOgre Moundに棲んでいる。奴は心を操る魔法を使うと噂されていて、Kurzenを堕落させたのは奴だと私は確信している。\n\nMai'Zothを生かしておけば、奴の悪は他の者にも及び、第二のKurzenを生み出すことにさえなりかねない。\n\n奴を倒し、他者を堕落させるのに使っている遺物、Mind's Eyeを持ってきてくれ。", "あなたに祝福を授けます。Mai'Zothの強さに匹敵するのは、その邪悪さだけです。", "おお! やってくれたか! {name}、あなたは善をなす偉大な力だ。その力が決して衰えぬように!\n\nこのMind's Eyeを調べて、善のために使えるかどうか見極めよう。もし使えないなら……破壊しなければならない。", 0x46e076d1, 0x12f49d70, 0x819be900, 0xa8c6ffae, 0x88fe4518, "....." },
  [207] = { "Kurzenの謎", "$N1枚の石板を見つけ、その伝説をBrother Nimetzのところへ持ち帰って下さい。", "Colonel Kurzenはかつて偉大で高潔な男だった。何が彼を堕落へと落としたのか突き止めねばならん！トロールの魔術に操られているのかもしれない。それを確かめるには、彼らの伝承をいくつか研究する必要がある。\n\nStranglethornのトロールの遺跡には、4枚の石板が隠されている。石板に何が書かれているのか見なければならない！刻まれた文字を書き写し、その写しを私のところへ持ち帰ってくれ。\n\n一つ目の石板はBal'lal Ruins、二つ目はVile Reef、そして三つ目と四つ目はRuins of Zul'Kundaにある。", "{name}！ トロールの伝説は持っているか？ その秘密をどうしても知りたいのだ！", "ありがとう、{name}。この伝承を調べて、トロールとColonel Kurzenに取り憑いた悪との間に何らかのつながりがあるか確かめよう。", 0x58f1d5ac, 0x7339ed19, 0x386d385f, 0x3bd2734a, 0xcec43b09, "....." },
  [208] = { "大物ハンター", "巨大白虎 King Bangalash の首を獲って下さい。", "{name} 、君はこの集団に相応しいハンターだ。君が見せたような武器の腕前は Lordaeron の戦場からこの深いジャングルに至るまで、ほとんどお目にかからなかったよ。\n\n凶暴な Sin'Dall 、狡猾な Bag'thera 、危険な Tethis を君は殺してきたが、最高の獲物はKing Bangalash の首だよ。あの白い虎のためにここにいるんだ……もうかなり長いこと奴に狙いを定めている。Bangalash を殺せば、君の狩りの腕に並ぶ者なしと証明される。", "戻ってきたか、お前さん。King Bangalashのせいで、私も何度も這うようにしてキャンプに戻ったものだ。踏ん張れよ。", "本当によくやった! やったぞ! おめでとう、{name} 。誰も為し得なかったことに成功したんだ。\n\nここにいる偉大なるハンティングメンバーの一員に列して讃えるよ。君の狩りと追跡の技に疑問を持つ者は誰もいない!\n\n君に乾杯を言わせてもらうぞ! 乾杯!", 0xe01b3baa, 0xcc884ebe, 0x2608c0af, 0x8f0a2e38, 0xd00ad370, ".....", nil, nil, nil, 0x3fb62772, nil },
  [209] = { "Skullsplitter Tusks", "Skullsplitter Tusksを$N1個手に入れ、Kebokのところへ持ち帰って下さい。", "South Seasの島々へ虎の牙を輸出し続けられるだけの虎を狩るのは、金もかかるし大変なんだ。幸い、ありふれた角のようなものを、見破られない偽物に変える技術を編み出してね。\n\n驚いたことに、一番よく似ていたのがSkullsplitterトロールのtusksだったんだ。\n\nおっと、何か言う前に聞いてくれよ。買い手が知らなきゃ誰も傷つかない、だろう？毎月の出荷の作業に取りかかれるよう、たくさん持ってきてくれ！", "しぶとい奴らだろう？ で、うまくいったか？ せかしてすまないが、こいつにはずっと悩まされてきたんだ！ で、どうだ？", "おお、よくやった、よくやった! うえっ、もっときれいに拭き取ってくれてもよかったんだけどね、その――まあ、いいさ、いいさ! ありがとう、{name}。君の助けのおかげで、うちの事業は間違いなく生産量も生産性も上がるよ! よしよし、さて、次の話に移ろうか……", 0x542d05be, 0xecd5e33a, 0xb40ef76d, 0xc67f9a51, 0x1f9f523f, "....." },
  [210] = { "Krazekの料理", "Krazek's Crock PotをゴブリンのKrazekのところへ持って行って下さい。", "野営地の料理はほとんど僕がやってるんだ。前は大仕事だったんだけど、Booty Bayのゴブリンの商人から機械仕掛けの調理鍋を買ってからは違った。あの鍋はすごいんだよ！数えきれないほどの時間を省いてくれた……壊れるまではね！\n\nその鍋をゴブリンのところへ持っていって、直してもらってくれないかな？彼の名前はKrazekだよ。", "こんにちは！ 何か持ってきてくれたの？", "ほほう、なるほど、Krazek's Crock Potじゃないか! 見事な代物だが、ときどきバネが壊れたり歯車が外れたりするんだよな。こいつはどこが悪いのか見てみよう……\n\nあった! 蒸気チャージャーは錆びきってるし、ナックルガスケットにはひびが入ってるし、フォビュレーターは歯が欠けてる。こんな状態でカブ一つ煮られたとは驚きだよ!\n\n直せるかって? もちろん直せるさ!\n\nだが代金はもらうぞ。そうとも、何事にも代金ってものがあるのさ……", 0xb238907e, 0x9dec2be2, 0xc74e5a32, 0xe846eee8, 0xfd8491c9, "....." },
  [211] = { "ああ、Andorhal", "Araj's Phylactery ShardをWestern PlaguelandsのChillwind CampにいるCommander Ashlam Valorfistのところへ持って行って下さい。", "ついに、Andorhalを攻め、そこを支配するlichを追い出す時が来た！\n\n街の廃墟の中で、そのlich、Araj the Summonerが支配している。奴は街の中心の残骸を囲む大勢のScourgeに守られ、奴に直接付き従う護衛たちも手ごわい。奴とまともに渡り合うには、多くの味方が必要だろう。\n\nArajを倒せ、{name}。その証として、奴のphylacteryの欠片を持ってくるのだ！", "任務はもう与えたはずだ、{name}。任務を果たした証として、lichの魂の器の欠片を持っているか？", "やってくれたな! Araj……あのlichがついに倒されたのだ!\n\n君は今日、Allianceに多大な貢献を果たした、{name}。その勇気と不屈の精神こそ、真の英雄たる者の証だ。どうか、これを受け取ってくれ。君がAllianceに歴史に残る勝利をもたらしたことを、皆が見て知るための証として!", 0x2851097e, 0x603e3574, 0x0e5ec45c, 0xb6c91f9e, 0xc8c21c5b, "....." },
  [212] = { "冷めた料理", "Cold Eye Basiliskを倒してChilled Basilisk Haunchを手に入れ、Blue RecluseのAngus Sternのところへ持ち帰って下さい。\n\n<このクエストを成功させるには、魂を解放してはならない。>", "私の最も有名な料理の一つが、Chilled Basilisk in Lime Vinaigretteだ。だが問題は……その肉は新鮮なまま保つのが不可能なことでね。しかも今夜、ある貴族の誕生日にその料理を出さねばならんのだ！\n\nだから、仕留めたばかりのCold Eye BasiliskからChilled Basilisk Haunchを急いで持ってきてくれたら、王の宴に値する礼をしよう！\n\nCold Eye BasilisksはStranglethorn北西部の浜辺の砂丘をうろついていることで知られている。だから長い道のりになるぞ。急いでくれ！", "{name}！ あの腿肉は持っているか？ そろそろ下ごしらえを始めないと、宴が台無しになってしまう！", "ああ、これは申し分ない! 本当にどうもありがとう!\n\nさて、失礼するよ。宴会に向けて、この腿肉を切り分けて、漬け込んで、盛り付けなきゃならないんだ。", 0x0f466bd4, 0x755a6eb1, 0x48dfd0b9, 0x2003f762, 0x33a633d9, "....." },
  [213] = { "敵対的買収", "Tumbled Crystalsを$N1個回収し、Booty BayのKebokのところへ持ち帰って下さい。", "今度という今度はやりやがった！貿易王たちが任命した大物どもをGelrizが押しのけてるだけでもひどいってのに、今度はあの一番悪名高い海賊の取り分にまで手を出そうってんだ！\n\nRevilgazは黙っちゃいない。自分のやり方で問題を片付けろって俺に言ったんだ。\n\n俺のやり方？盗みさ。Lake Nazferiti近くのVenture Co.の地質学者たちは、鉱山で見つけてる奇妙な青い水晶にご執心だ。その地質学者どもから石のサンプルを持ってきてくれ。手に入れるのにどうしようが構わないぜ。", "あの石が必要なんだ、{name}。どんな手を使ってもいい！ とにかくやってくれ、詳しいことは聞きたくない！\n\n大事なのは結果だ、{name}。それ以上でも以下でもない。", "興味深い。結晶がこの工程で研磨されているということは、奴らがそれを何らかの燃料か、あるいは別の触媒として使うつもりだとしか考えられない。それ以上のことは私にはよく分からない。サンプルをHead Chemist Gigglefontのところへ送らねばなるまい。", 0xab61fa9d, 0x6a649854, 0xfc4f719f, 0xdd935b3b, 0x1becab01, "....." },
  [214] = { "Red Silk Bandanas", "Sentinel Hill TowerのScout Riellは、Red Silk Bandana 10枚を持ってくるよう求めています。", "Defias GangのトレードマークがRed Bandanasだというのは周知の事実だ。だが、そのバンダナの素材が団員の階級を表していることが分かった。\n\nというわけで、Defiasの高位の団員をできるだけ多く始末してほしい。最も高位の連中は、間違いなくVanCleefの秘密の隠れ家にいるはずだ。終わったら、奴らの死の証としてRed Silk Bandanasを10枚持ってきてくれ。報酬を出そう。幸運を祈る、{name}。", "Defiasの一味から我々の土地を取り戻しているか？ それなら、証拠としてRed Silk Bandanaを10枚見せてくれ。", "よくやりましたね、{name}! People's Militiaを代表して、あなたの功績に敬意を表します。あなたのような勇敢な人たちの助けを借りて、私たちはもうすぐこの土地をみんなの元へ取り戻しますよ。", 0xe3536628, 0x16e9af40, 0xca668909, 0x9de63344, 0xb8efc2a9, "....." },
  [215] = { "ジャングルの秘密", "Rebel CampのLieutenant Dorenと話して下さい。", "助けてくれてありがとう、{name}。どう見えるかは分かっている、だが……説明させてくれ。\n\n私はLieutenant Dorenから、Kurzenの部下に再入隊して彼らを探り、反乱軍にどうしても必要な情報を持ち帰るよう命じられていた。君がここで見たのは、Kurzen's Compoundに潜入する好機だと私が思っていたものだ。私が間違っていた。改めて、助けてくれてありがとう。\n\nこれは極秘任務だったから、誰にも話してはならない。だがDorenと話せば、彼が説明してくれるだろう。", nil, "そうだ、Thorsenが言ったことは本当だ。このことは慎重に扱ってくれ。かつて我ら反乱軍はColonel Kurzenに熱烈な忠誠を誓っていた。だがKurzenの堕落はあまりにひどく、我らの情熱は怒りへとねじ曲げられた。Private ThorsenがKurzenの手下と最近接触していたことが知れたら、ある夜、奴は喉を掻き切られていることになるだろう。\n\n私の知る限り、Thorsenの任務を知っていたのはSergeant Yohwa、Thorsen、そして私だけだ。だが、もう一人いるはずだ。裏切り者が。", 0x7d722133, 0xefc4a05e, 0xd0f9dd79, nil, 0xbe5ebc19, "...m." },
  [216] = { "岩とThistlefurの間に", "Thistlefur Avengersを$N1体とThistlefur Shamanを$N2体倒す。ほとんどはZoram Strandの東、Thistlefur Villageにいる。終わったら、AshenvaleのZoram'gar OutpostにいるKarang Amakkarのところへ戻って下さい。", "Thistlefurのfurbolgどもが我々の拡張を脅かしている！ 東にあるThistlefur Villageが、こことSplintertree Postとの間の道をふさいでいるのだ。Astranaarの村を迂回できる道なのだ。それがなければ、Allianceに余分な拡張路を与えてしまう。\n\n{name}、我々は許してはならん……拡張路の格差を！\n\nThistlefur Villageへ向かい、furbolgどもの数を減らしてこい。この任務には報酬が出るが、それ以上に、Hordeのための務めを果たすことになるのだ！", "Thistlefurに戦いを仕掛けたか？ 我々の拠点の間の道が開ければ、Ashenvale全土を手に入れる見込みは大いに高まる。", "{class}、よくやった。よくやってくれた! これからもfurbolgの数を減らすために兵士を送るつもりだが、少なくとも、Allianceの鉄条網から解放された別の道を頼りにすることができる。HordeのAshenvale征服は今、好調に進んでいる!\n\nこの日の賃金を払おう、英雄。敬意を表する!", 0xd36b69c6, 0xccd08c7a, 0x41a07ec4, 0x6d3e78a5, 0x5109bb8d, "....." },
  [217] = { "王の領土の防衛", "Troggの頭目Grawmugと、その2人の護衛GnasherとBrawlerを倒し、南の見張り塔にいるCaptain Rugelfussに報告する。", "{name}、我々の斥候が今回のTrogg侵攻の首領を突き止めた。Loch Modanのこの獣どもは、Grawmugという族長に従っているようだ。だがGrawmugは厳重に守られている。最精鋭の護衛2匹、GnasherとBrawlerが決して傍を離れんのだ。\n\n腕に覚えがあるなら、{name}、Grawmugとその手下2匹を暗殺する任務をお前に率いてもらいたい。Troggの指導者どもが死ねば、この獣どもを地の底へ押し戻せる見込みも出てくるかもしれん。", "Grawmugと、その2人の護衛GnasherとBrawlerは、まだ生きている。3人とも仕留めるまで、君の任務は終わらない。ドワーフの帝国が君に期待しているのだ、{name}。", "実に見事だ、{name}! 君はLoch Modanに希望をもたらした。Grawmugが死んだ今、この地からTroggsを一掃できる見込みは高まったぞ。", 0xc965c9da, 0xd0adb1a9, 0xd1d3aab4, 0x080d24f4, 0x996b47d7, "....." },
  [218] = { "盗まれた日誌", "Grelin WhitebeardはGrik'nir the Coldを倒し、彼の日誌を取り戻してほしいと言っています。", "私の日誌が！ 奴らが洞窟へ持って行ってしまった。持っていた奴は……皮膚と顔に妙な模様のある、でかい乱暴者だった。それ以上はよく見えなかったんだ。\n\nトロール相手にうまくやってきたようだし、取り戻してきてもらえないか？", "{name}！ うまくいったか？", "素晴らしい、{name}！手帳を取り戻してくれて本当にありがとう。さて、このColdridge Valleyのトロールの状況は抑えられていて、大して心配はいらないようだな。\n\n報告書に最後の仕上げをしたら、それを兄弟のSenirに届けてくれる者が必要になる。", 0x5df25f99, 0x1dd2f28b, 0xfc2a9b7a, 0x224c9107, 0x3df5a70e, "....." },
  [219] = { "戦闘中行方不明", "Redridgeへ戻る道中、Corporal Keeshanを守る。", "ついに、Allianceの友が！\n\n助けて……頼む……\n\n最後に覚えているのは、あの汚らわしいオークどもが我々の連隊を圧倒したことだ。ほとんどの兵が殺された。私は頭に強い一撃を受けて、目の前が真っ暗になった。今はこの洞窟に捕らえられている。助けてくれ、ひどい怪我なんだ。\n\n町へ戻るには助けが要る……頼む……君が最後の望みなんだ……", "何か？", "王国によく尽くしてくれた、{class}。あの恐ろしいBlackrock OrcsからCorporal Keeshanが脱出するのを助けてくれて感謝する。今日の勇敢な行いに対し、報酬を与えよう。", 0xd4ba8881, 0x846a56f1, 0x9fe9b7bf, 0x0c07a888, 0x3364444e, "....." },
  [220] = { "水の呼び声", "Vial of Purest WaterをBarrensにいるIslen Waterseerのところへ持って行って下さい。", "次のトーテムを授ける前に、Islenがもう1つ任務を与えるだろう。私が渡した水の小瓶は、その任務が何であれ必要になるものだ。\n\nさあ行って、彼女を探すがいい。いずれまた会おう。", "また会ったな、{name}。元気そうだな。\n\nこんなに早く戻ってくるとは、どうしたんだ？", "ああ、Brineが創り出し祝福した水の小瓶、しかもお前自身が集めてきたものだな。\n\nこの小瓶の液体は、お前のためのsaptaを作る鍵となる。だが、もう一つの務めにも使われる。\n\nお前のために作るsaptaは、Undercityの南、Silverpine Forestの祠で水の精霊を見るために使うがよい。残った雫は……そうだな、残った雫については、お前に備えができたと思えたときに話そう。\n\nもう一度の旅に備えはできているか、{name}？", 0x1f0e11aa, 0xba2ead60, 0x6f760e93, 0x959ae071, 0x94f993e0, "....." },
  [221] = { "森のWorgen", "Nightbane Dark Runner 12頭を殺して下さい。", "森でShadow Weaversと一緒に、もっと大きなworgenがうろついているのに気づいたかもしれない。我々が知る限り、そのDark Runnersがworgenの大部分を占めている。\n\n巡回の途中で、奴らが町の南西にあるRotting Orchardを制圧しているのも見た。このworgenは、君がこれまで相手にした連中より少々手強いぞ。\n\n用心しろ。", "もう戻ったのか、{name}？ あきらめたと言いに来たのでなければいいが。", "Dark Runnersを相手によく戦ってくれた、{name}。だが奴らの数は尽きることがないようだ。こちらが前進するたびに、隊列を埋めるために新たな者が湧いて出る。\n\n奴らをここへ引き寄せる邪悪な力とは何なのか。なぜ我らの不幸な地を乱しに来たのか……\n\n私はMaster Carevinを信じる。彼ならきっと問題の根本にたどり着くだろう。", 0x47dbaa77, 0x77e86e2a, 0xb1107ac6, 0x33d61b21, 0xc02e7176, "....." },
  [222] = { "森のWorgen", "Nightbane Vile Fang・Nightbane Tainted Oneをそれぞれ8頭殺して下さい。", "これまでの君の功績で、森にはびこる最も手強いworgenに挑む準備ができていると確信した。\n\nここを新たな住処にしたworgenのうち、Vile FangsとTainted Onesが最も危険だと分かっている。奴らは南の洞窟のいくつかの近くや、鉱山の中に居着いている。\n\n遠くからでも、奴らのかがり火の明かりが見えるほどだ……", "恐ろしい獣たちだろう？ だが恐れることはない、{name}。光のために立つ者は決して倒れはしない！", "{name}、正直に言うと、ここまでうまくいくとは思ってなかったんだが、君は明らかに一目置かれるべき{class}だ。実のところ、もし君がMaster Carevinの戦いに正式に加わりたいと望むなら、喜んで推薦状を書いてあげるつもりだ。", 0x47dbaa77, 0xd83d480e, 0x07eb6a76, 0x4a1b2c2d, 0x97850b04, "....." },
  [223] = { "森のWorgen", "Calor's noteをJonathan Carevinに渡して下さい。", "さあ、{name}。この伝言をMaster Carevinに届けてくれ。\n\n<彼は素早く色あせた羊皮紙を取り出し、あなたに差し出した。>\n\n君のような者がもう何人かいれば、Night Watchより数で上回れるだろう！そうなれば、今は我々わずかな者が続けている仕事も、成し遂げられるかもしれん。", "何だ、どうした？ 手短に頼む、急ぎの用があるのだ。", "冷たい応対を許してくれ、{name}。見ての通り、私は極めて多忙な身でな。君がCalorに感銘を与えたことは分かっている——断言するが、それは並大抵のことではない——そして彼が推薦を与えたこともな。\n\n良からぬ輩が暗躍している、{name}。我々は、己を証明した者すべての助けを必要としている。我々は悪魔、アンデッド、そして彼らに手を貸す者たちと戦っているのだ。油断せず、用心し、我々の大義に助力しない者は誰も信用するな。\n\n光のもとに栄光あれ。", 0x47dbaa77, 0x7794d7d0, 0x5a6d3b68, 0x5d4aba8c, 0xa217e173, "....." },
  [224] = { "王の領土の防衛", "Stonesplinter Troggを10体とStonesplinter Scoutを10体倒してほしいと、南の見張り塔のMountaineer Cobbleflintは言っています。", "Lochを守らねばならん、{name}！ 王の兵の多くが遠くの戦場で勇敢に戦っているせいで、我々は本国の守りで手一杯なのだ。Troggどもがあらゆる割れ目から穴を掘って這い上がってくる！ Troggの蔓延はIronforgeにとって最大の脅威だ。この汚らわしい変異体どもを滅ぼさねばならん。\n\n勇敢な冒険者よ、お前の力が必要だ。打って出て、Troggの脅威を叩き潰してくれ。Stonesplinter Troggsを10匹とStonesplinter Scoutsを10匹倒し、報告に戻れ。", "Loch Modanは包囲されているのだ、{name}！ Allianceのために戦える者は皆必要だ。Stonesplinter Troggを10体とStonesplinter Scoutを10体、もう倒したか？", "よくやった、{name}! 戦場で並外れた勇気を見せてくれたな。君のような働きがあれば、Troggsとの戦いに必ず勝てる。King Magniによく尽くしてくれた。\n\nこの手の冒険が性に合うと思うなら、Mountaineer Gravelgawと話してみるといい。隊長は彼を厳しい巡回任務に就けていてな、きっと手助けが欲しいはずだ。塔のすぐ中にいるGravelgawに聞いてみろ。", 0xc965c9da, 0x6d03495e, 0xc3723201, 0x75084503, 0xe35c303e, "....." },
  [225] = { "風化した墓", "DarkshireのSirra Von'Indiと話して下さい。", "風雨にさらされた墓標には、ただこう刻まれている。\n\nMORGAN LADIMORE\n\n<よく調べてみると、墓の上の土が最近掘り返されていて、かなりの量の土が動かされているようだ……>", nil, "Morgan Ladimore？\n\nああ、そうだ、もちろん。彼の身の上は長く悲しい物語だった。私は彼を知っていた。そう、戦に発つ前にな。だがそれが彼を見た最後だ。高潔で善良な男だったが、惨い最期を遂げた。\n\nさあ、私の記憶よりもうまくその話を伝えられるものが、ここにあるはずだ……", 0xc3ec23cc, 0x9f5ae082, 0xf3dd996f, nil, 0xe3b1dce6, "...m." },
  [226] = { "迫る狼", "Starving Dire Wolves 12頭・Rabid Dire Wolves 8頭を殺し、Duskwood西部の境界にあるSven's CampのLarsのところへ戻って下さい。", "Svenと私の前には危険な日々が待っている。東には死霊術師がいるしな。それに、こうして二人きりでここにいるから、食べる物は自分たちで狩らなきゃならない。肉を抱えてキャンプへ戻るたびに、飢えたdire wolvesや狂ったdire wolvesが一口よこせと森から出てくるようだ。言うまでもないが、ここで暮らすのは危険な仕事だ!\n\nだが、その狼どもを少しでも片付けてくれれば、ずいぶん楽になる。奴らはたいていここの北と東、川の近くをうろついている。", "まだ狼狩りをしているのか……？", "よかった。あの群れをかなり減らしてくれたな。狼どもに足元を噛まれずに済めば、Morbent Felへの対処に心を注げる。\n\nさあ、このFlash Bundlesをいくつか持っていけ。町で作られていて、Svenの大義を助けるために大量に寄付されたものだ。", 0xdeb794ec, 0xae5c308b, 0x0b5b5fe6, 0x3371447a, 0x489aecd3, "....." },
  [227] = { "Morgan Ladimore", "DarkshireのCommander Althea Ebonlockeと話して下さい。", "<彼は棚を探し、革装の本を取り出した。>\n\nもっと知りたいなら、Altheaに聞くといい。最近、彼の……厄介事……に対処しているのは彼女だからね。", nil, "Morgan Ladimore？聞いたことが……\n\nああ、Mor'Ladimのことね！あの話は聞いていないの？\n\nじゃあ、手短に話すわ。Mor'Ladimと名乗るさまよえるアンデッドがDuskwoodを徘徊しているの。私たちが集めた情報では、それはあなたが知っているらしいMorgan Ladimoreのアンデッドの体のようね。奴は巡回中のWatchmenを襲い、人々を殺して、あらゆる厄介事を引き起こしているわ。\n\n<彼女はあなたを値踏みする。>\n\nあなたなら十分やれそうね。奴を永久に眠らせてやれるかもしれないわ。", 0x0593d354, 0x1e643160, 0x6cb28bbc, nil, 0xd2e36039, "...m." },
  [228] = { "Mor'Ladim", "Mor'Ladimを殺し、頭蓋骨をDarkshireのCommander Althea Ebonlockeに渡して下さい。", "斥候の話では、Mor'LadimはDuskwoodをさまよっていて、墓地の中を奇妙な曲がりくねった道筋でたどっているらしい。我々は丘の上の家の向こうに彼を埋葬した。どこか分かるか？\n\n私に手伝えることは何もないが、幸運を祈っている。", "奴に手こずっているとしても責めはしないよ、{name}。我々の中でも屈指のWatcherたちが、Mor'Ladimに命を奪われているのだ。", "奴を倒したの？並大抵のことではないわ、{name}！Darkshireの人々とNight Watchを代表して、感謝するわ。\n\nああ……でも、1つだけ小さな問題があるの……", 0x2fb5d726, 0x707df842, 0x40bc3cfa, 0xb35897e7, 0x9f6d1906, "....." },
  [229] = { "生きていた娘", "DarkshireのWatcher Sarah Ladimoreと話して下さい。", "もっと早く話しておくべきだった……\n\nどう言えばいいか……\n\nMorganは家族が皆死んだと思っていたかもしれないが、実は娘のSarah Ladimoreは今Watcherになっているんだ。彼女は父親の死を取り巻く……事情……にずっと心を痛めてきた。この知らせを彼女に伝えに行ってもらえないだろうか。", nil, "はい？父のこと……\n\n<彼女の目が伏せられる。>\n\n私は……あの人のために何かしてあげられたらよかったのに……せめて、あの人がああなる前に話していれば……", 0x2a784eed, 0x8e6bd529, 0x42832c74, nil, 0x17c8873e, "...m." },
  [230] = { "Svenのキャンプ", "Sven's Farmで手に入れた本をSvenに渡して下さい。", "塚を掘り返すと、土に汚れた小さな本が見つかった。\n\nその本には題名がないが……Svenが知りたがりそうな情報が書かれている。", "何を見つけたって？？ どうか、見せてくれ……", "<Svenは本の頁を読み、そして荒々しく閉じる。>\n\n私が見たあの影のような人物は、家族の死の目撃者だったのだ！あの男に問いただしたいことがある……奴が何者か分かりさえすれば！", 0x03adfb1c, 0xb1da24c8, 0x4cc2761b, 0x9d6eaf1e, 0x4f4f7346, "....." },
  [231] = { "娘の愛", "Sarah Ladimoreの指輪をMorgan Ladimoreの墓へ持って行って下さい。", "これを、父のお墓に置いてきてください。もしかしたら……どうにかして、私が元気でいること、そして起きたことについて誰も父を責めていないことが、父に伝わるかもしれないから。\n\n<彼女の目には涙が浮かんでいる。右手から指輪を抜き取ると、それをあなたの手に押しつけた。>\n\nそれと……ありがとう、{name}。", "放っておいてくれ……", "<幽かな声が風に乗って響く……>\n\nこれは……？Sarah？あの子はまだ生きているというのか？肩の重荷が取り除かれた……\n\n{name}。我が剣、Archeusを取るがいい。我が魂が安らぎを得た今、もはや必要のないものだ。これは善をなすために鍛えられた。私はそれを持つに値せぬと証明してしまったが、お前ならばこれを通して光を継いでくれるかもしれん。\n\nLys、我が愛しき人よ……", 0x78f5e66a, 0x84165d28, 0x70f44d6f, 0x2aff9400, 0x130e6acc, "....." },
  [232] = { "Apothecary Zingeのお使い", "この注文書をUndercityのAlessandro Lucaのところへ持って行って下さい。", "Royal Apothecary Societyが君の助力を必要としている。よく聞け。私の計画がうまくいけば、我々二人とも得をするかもしれん。\n\n隣の部屋にいるApothecary Keeverは少々……おかしい……かもしれんが、賢い研究者が追究すれば、彼の研究は実を結ぶ可能性がある。幸い、私がその研究者だ。この発注書を、Blue Moon Odds and Endsの店主Alessandro Lucaのところへ持っていってほしい。彼が検査キットをくれるだろう。受け取ったら私のところへ持ち帰れ。任務の詳細を説明しよう。", "ええ、どのようなご用件でしょう？ Royal Apothecary Societyの用事でいらしたのですか、それとも私の一日を明るくしに来てくださっただけでしょうか？", "ああ、Zingeがキットを必要としているのか？Zingeがその麗しい姿で私を喜ばせてくれないとは、悲しいことだ。\n\nよかろう、キットを用意してやろう。", 0xca9d2e10, 0x33db4467, 0x8f431a21, 0x17aa15eb, 0xb282b25c, "....." },
  [233] = { "Coldridge Valleyの郵便配達", "Talin Keeneye にこの手紙の束を届けてください。", "ふむ、私のために頼みを一つ聞いてくれる気はないだろうね、若いの？ 今日、峠を越えて手紙の束が届いたんだが、それを届けに行く暇がないんだ。\n\n全部Talin Keeneye宛てだ。彼は西へ道を下った先にいる。凍った湖のそばに野営を張っているよ。\n\nどうだい？", "何か？ 私に何か持ってきたのか？", "ありがとう、私はこの手紙を長いあいだ待っていたんだよ...\n\nただ残念なことに、すべての手紙が私宛てというわけではないようだ。この一通はGrelin Whitebeard宛てだな。君が届けるつもりなら、彼はそうは遠くないところにいるぞ。", 0xeea45c41, 0x43673bfd, 0x2f02ac16, 0xc599dffe, 0x2dbb1502, ".....", nil, nil, 0xce85efc5, nil, nil },
  [234] = { "Coldridge Valleyの郵便配達", "Coldridge Valleyにいる Grelin Whitebeardに手紙を配達しろ。", "私の記憶が確かなら、Grelinは南東に道を下ったところで、野営しているはずだ。彼はしきりに郵便を欲しがってたな。", "何かお手伝いできることはありますか？", "おぉ、見事だ。Ironforgeからの伝言を受け取るのは久しぶりだよ。", 0xeea45c41, 0x9842e5d5, 0x570047d8, 0x931ded5d, 0x5b1822e4, "....." },
  [235] = { "Ashenvaleの探索", "AshenvaleのSplintertree PostにいるSenani Thunderheartと話をしてください。", "若き冒険者たちへ! Ashenvaleの荒野が君を待っている!\n\nHordeはBarrensの北の地に強力な駐留軍を配置した。Splintertree PostとZoram Strand Outpost、二つの前哨基地はHordeに栄光をもたらすために戦っている!　自分の力量を示したい者は、そこで指示をあおげ。注意がある。Barrensの真北、Splintertree PostのSenani Thunderheartは、Ashenvaleの大いなる狩りに参加希望の冒険者たちを探している!", nil, "新しい開拓地へようこそ、{name}。Ashenvaleはチャンスにあふれる土地です。ここでは、あなたのような駆け出しの{class}が勇気を示すのに、限りないチャンスを見つけられますよ。この前哨の周りを探してごらんなさい。それと、Hordeの別の前哨がありますから、必ずZoram Strandへ出かけるのですよ。\n\nあなたがここにいるということは、狩りのことをさらに学びに来たのですね。よくお聞きなさい。さて、あなたが知らねばならないことを分かち合えるのを、とても嬉しく思いますよ。", 0x1bf465b8, 0x0a003978, 0x7489a1c6, nil, 0xedbc036b, "...m." },
  [237] = { "王の領土の防衛", "Stonesplinter Skullthumperを10体とStonesplinter Seerを10体倒して報告してほしいと、南の見張り塔にいるMountaineer Gravelgawは言っています。", "Mountaineer Cobbleflintはお前のことを褒めてばかりいたぞ、{race}。だからこそ、極めて重要な任務をお前に託そう。我らのドワーフの同胞がAllianceの前線から戻るまで、侵攻してくるTroggの軍勢に圧力をかけ続けねばならんのだ。\n\n南の丘へ向かい、Stonesplinter Skullthumpersを10匹とStonesplinter Seersを10匹倒せ。お前の攻撃が時間を稼いでくれる。任務を終えたら報告に戻れ。", "時間が要るのだ、{race}。お前の任務はStonesplinter Skullthumperを10体とStonesplinter Seerを10体倒すことだ。援軍が来るまで敵に圧力をかけ続けろ。ぐずぐずしている暇はないぞ。", "見事に任務を果たしてくれたな、{race}。王ご自身もさぞ誇りに思われるだろう。\n\nだが、約束されていた援軍はついに来なかった。どうやらAllianceの前線は、倒れた同胞の血で真紅の海と化しているらしい。その損害の知らせは苦い味を残す。だが、彼らの死を無駄にしてはならん。この厳しい時にこそ団結し、Allianceに栄光を取り戻さねばならんのだ。\n\n配置換えについてはMountaineer Wallbangと話してくれ。今ほど君が必要とされている時はない。", 0xc965c9da, 0xecf18b12, 0xd0c449f5, 0x92de6ab6, 0x3ebcd8dc, "....." },
  [238] = { "Apothecary Zingeのお使い", "UndercityのApothecary ZingeにField Sampling Kitを渡して下さい。", "キットの用意ができたよ、{name}。Apothecary Zingeはきっと一刻も早くこれを欲しがってるだろう。すぐに彼女のところへ持っていって、キットの代金はSocietyのツケにしておくと伝えてくれ。それから、私からの心からのよろしくも伝えておいてくれよ。\n\nほら、突っ立ってないで。しがない運び屋の人生なんてそんなもんだろう？", "ああ、Lucaが不気味だというのは私も同感だ。だがどうでもいい。field sampling kitを渡してくれ。適切な原料を調べられるよう、少し手を加えないといけないのでな。\n\nそれは持っているのだろう？", "よし——私の時間を無駄にしないことを誇りとする者と組めるのは喜ばしい。\n\nこのキットに少し調整を加えたら、君は現場へ出る準備が整う。目下の任務に不可欠なデータを集めるのにこれを使ってもらう。\n\n改造を終えるのはほんの少しの時間で済む。待っている間に、砂漠へ何を持っていきたいか考え始めた方がいいだろう。\n\nそう、砂漠と言ったんだ。", 0xca9d2e10, 0xf271ca3e, 0xb53a6223, 0x65112cbb, 0x8cedceb7, "....." },
  [239] = { "Westbrook Garrisonからの救援要請", "Westbrook Garrisonに行き、Deputy Rainerと話す。", "西の境界線にあるGarrison地区から、gnollや盗賊が勢力を拡大してきているとの伝令が入った。同時に、援軍要請があったのだが、我々には余分な戦力などない！\n\nどうか援軍として、彼らのところに向かってほしい。Westbrook GarrisonにいるDeputy Rainerのところへ急ぎ、力を貸してやってほしいのだ。\n\nGarrisonへは、この道を西に進めば着く。小川にかかる橋を渡ったすぐ先がそうだ。", nil, "Marshall Dughanが君を援軍として寄こしてくれたのか？だが、君は軍の人間じゃない。いや、この際どうでもいい。Dughanがそう判断したんだ、十分だ！\n\n我々の状況は、控えめに言っても、緊張状態にある。手を貸してほしい。", 0xdc5c2624, 0x2e02a498, 0x8d2938bf, nil, 0x3b449a23, "...m." },
  [240] = { "Jittersのもとへ", "JittersのところへDusky Crab Cakesを持ち帰って下さい。", "さあて……Grual風「カニ肉」ハンバーグのできあがり!", "{name}、来てくれたか！ 俺の食い物は持ってきてくれたか？！？", "ああ！ありがとう、{name}。これは実に食べ応えがあったよ！\n\nさあ、これの代金を払わせてくれ！", 0x1c60e6ea, 0xe6ff66e0, 0x74df57a6, 0x49ff2ae7, 0xb54be29c, "....." },
  [243] = { "現場へ", "testing kitの電源を得ることについて、GadgetzanのChief Engineer Bilgewhizzleと話して下さい。", "君にはTanarisの砂漠へ向かい、その地に棲むbasilisk、scorpid、hyenaの組織の性質を調べてもらう。組織のサンプルを手に入れ、携えた検査キットで調べるのだ。サンプルのかなりの部分は不合格になると思っておけ。それぞれの種類につき、合格したサンプルが八つ必要だ。\n\nさらに、この種の改造キットには、Gadgetzanのゴブリンが持っている動力源を使わねばならない。Chief Engineer Bilgewhizzleと話して、キット用に一つ手に入れてこい。\n\n成功したときにだけ戻ってくるのだ。", nil, "ああ、うちの4711-FTZ型動力源だな！普段は水の井戸を動かすのに使っているが、あの下劣な放浪者どものおかげで、今は動力源が有り余っているんだ。\n\nいいとも、君が私に隠しているつもりの、どんな邪悪な科学実験のためだろうと動力源を用意してやる。だがタダじゃないぞ、{race}。Gadgetzanではタダのものなど何もない。", 0x6f543905, 0xc469aa24, 0xfe96494c, nil, 0xf42c86f2, "...m." },
  [244] = { "迫り来るGnoll", "Deputy Feldonに報告する。", "やあ、{class}。私はこの一帯の道の巡回を任されている。今のところ道は安全だが、ここから北と東にgnollの野営地があるのを見たんだ。\n\nLakeshireに、gnollの軍勢が集まっていることを知らせねばならない！ LakeshireにいるDeputy Feldonに報告して、gnollのことを伝えてくれ。そうすれば、Feldonはきっと斥候の手当を出してくれるだろう。\n\nFeldonはたいてい、Lakeshireへ渡る橋の南の辺りを見回っている。", nil, "Redridgeのgnollが、そんなにElwynnの近くにいるだと?? 奴らは我らの故郷へ進攻する構えかもしれん。じきに、包囲される人間はLakeshireの人々だけではなくなるかもしれんぞ!\n\nこれが君の報酬だ。もっとも、君が持ってきたのは悲惨な知らせだがな。しかも最悪の時期に来たものだ、我々にはそれに対処するだけの備えがない。", 0x8c8be2e9, 0x7bc054fc, 0xae1593a2, nil, 0x3e80651e, "...m." },
  [245] = { "八本脚の厄介者", "Pygmy Venom Web Spider 15匹を殺し、DuskwoodのWatcher Doddsに折り返し報告して下さい。", "やあ、{class}。西の境界を占拠したクモどもを見たかもしれないな。あの8本脚の厄介者は我々の手に余るし、司令官もDarkshireからこれほど離れた場所に割ける人手がない。\n\nこんなことを頼むのは気が引けるが、君なら奴らを片付けられそうだ。大した物は約束できないが、あの汚らわしい虫どもを根絶やしにするのを手伝ってくれたら報酬を出そう。\n\nああ、それと忠告だ。できれば奴らの毒は避けたほうがいい。", "蜘蛛を相手にするときは用心したほうがいい。部下を何人かやられたんだ。本当だぞ、毒で体が柔らかくなりはじめた男が、奴らの巣に逆さ吊りにされている光景は、見ていて気持ちのいいものじゃない。\n\nあの虫どもに君が昼飯にされるところは見たくないからな。", "あ! 戻ってきた。しかもそれほど疲れてもないようだな。もちろん、{name}、Night Watchは君の働きに感謝してるさ。それと報酬を約束したからな、これだよ。", 0xd491b1a7, 0x9eafc706, 0x22732e4f, 0xe12e0aee, 0x1c080d20, "....." },
  [246] = { "脅威の見極め", "Redridge Mongrelを10体とRedridge Poacherを6体倒し、LakeshireのDeputy Feldonに報告する。", "割ける人手はないが、お前が報告してくれたgnollどもについては何か手を打たねばならん。\n\nRedridgeの南部でgnollを偵察してくれ。奴らを攻め立て、倒せるだけ倒して、奴らの数と、奴らがどれほどの脅威かの見立てを私に報告するのだ。そのgnollどもは、Redridgeの南の道沿いのあちこちに野営しているはずだ。\n\nStormwind Armyのためにこれを成し遂げてくれ、{name}。そうすれば報酬を与えよう。", "すまないが、{name}、ここはやることが山積みで手が離せないのだ。報告することがないのなら、私は他の用件に取りかからねばならん。", "<Deputy Feldonはあなたの報告に耳を傾ける……>\n\nあそこにはかなりの規模のgnollの軍勢が陣取っていて、君の話からすると手強い連中のようだ。この情報を集めるのは楽ではなかっただろう。\n\nさあ、受け取ってくれ、{name}。君の助力に感謝する。\n\nまだなら、Lakeshireの中にいるMarshal MarrisとMagistrate Solomonと話してくれ。我々の状況はますます切迫している――あの2人もきっと君を必要としているはずだ。", 0xcdd38f62, 0x1de28477, 0x75c1cdab, 0xfd431e78, 0x3a73678c, "....." },
  [247] = { "狩りの完了", nil, nil, nil, "{name}、君はAshenvale Huntを成す3頭の獣をすべて仕留めた。奴らを倒した証拠も十分に持ってきてくれた。君の強さと粘り強さに疑いの余地はない。君の血管にはハンターの血が流れている。称えられるべきだ!\n\nどうか、Ashenvaleで今日Hordeのために成し遂げた偉業への祝いの印として、この装身具を受け取ってくれ。祖先が君を見守らんことを!", 0x14ca8c7a, nil, nil, nil, 0xa17a9acd, ".mmm." },
  [248] = { "さらなる調査", "Stonewatch Keepの傍らにある、崩れていない見張り塔に登る。\n\nGlyph of Azoraを置くのにふさわしい容れ物を見つけて下さい。", "私はTower of Ilgalarを見張ってきました。MorganthがStonewatch Keepのオークたちと対立しているのが分かります。その争いの理由は分かりませんが、この謎を解き明かす手助けをあなたにしてもらえるかもしれません。\n\nもう一つGlyph of Azoraを持って、Stonewatch Keepのそばにある無傷の見張り塔の頂上へ行ってください。\n\nGlyphを置くのにふさわしい物を見つけてください。箱か壺か――glyphが気づかれない場所なら、私の目的にかないます。", "この壺にはかつて悪臭を放つ酒が入っていたが、今では空になり、一対の樽の上で忘れ去られている。", "これはGlyph of Azoraにふさわしい器で、TheocritusがStonewatch Keepの中にいる者たちの心を探ることを可能にする。", 0x6310d65d, 0x375e6926, 0x7c764f66, 0x08216341, 0x02b3cbef, "....." },
  [249] = { "Morganth", "Morganthを倒す。\n\n彼のPendant of ShadowをElwynn ForestのTower of AzoraにいるTheocritusのところへ持って行って下さい。", "長い観察の末、Morganthの計画が分かりました。\n\n彼はScythe of Eluneを探しています……そして、見つけたのかもしれません！もしそうなら、Redridge Mountainsも、そしてStormwindの王国も、じきに彼の闇の力を思い知ることになるでしょう。\n\n私にはMorganthと渡り合う覚悟はできていませんが、今すぐ彼に対処しなければならないのではと恐れています。ですから、あなたにTower of Ilgalarへ入り、Morganthと対決してもらわねばなりません。\n\n彼を倒し、Pendant of Shadowを持ってきてください。これを果たせば、王国はあなたに大きな恩を負うことになるでしょう。", "急いでくれ、{name}。Morganthが力を広げるという私の恐れが現実になる前に！", "よくやってくれました、{name}。ウォーロックのMorganthを倒したことで、Stormwindは重大な危機から救われました。\n\nこの報酬を謹んで差し上げます。平和な時代であれば、あなたに平安を祈るところですが。\n\nですが代わりに、あなたの試練に幸運を、そしてこの先の戦いに勝利を祈りましょう。", 0x64aa5799, 0x879964dd, 0x12522098, 0x0143479a, 0x425a6647, "....." },
  [250] = { "迫り来る闇の脅威", "Damの東側の斜路付近を調べ、Dark Iron Dwarvesが何を企んでいるのかを明かす手がかりをChief Engineer Hinderweirのところへ持って行く。", "ありがたい、Damの安全を気にかけてくれる者がいたとは。まずThandol Spanが破壊され、次にDun Modrが略奪された！ 次にDark Ironの脅威の標的になるのはDamに違いない。ここの警備の大半はAlliance Frontへ配置換えになってしまった。私の一番の検査官もだ。\n\nだからあなたが必要なんだ、{name}。Damの東の傾斜路の辺りを、Dark Iron Sappersが何人かうろついているのを見かけた。その辺りを調べて、手がかりを持ち帰ってくれ。", nil, "怪しげな樽には、奇妙な匂いの粉が入っている。", 0x285fa090, 0xd58cd749, 0x3b5e1a8f, nil, 0xcbe807ee, "...m." },
  [251] = { "Abercrombieの手紙の翻訳", "Letter to ElloをSirra Von'Indiに渡して下さい。", "この手紙をSirra Von'Indiに渡して下さい。彼は言語や古い術に造詣が深いのです。この手紙を翻訳できる者がいるとすれば、それは彼なのです。", "世捨て人のAbercrombieからの手紙だって？ あいつは知らんが、墓地に住んでいるというなら、頭が腐っちまってるのは確かだな！", "<Sirraは手紙の翻訳を始めた……。>", 0x5d4115a2, 0x14115437, 0xcf076a63, 0x22e67061, 0xcc1a43e1, "....." },
  [252] = { "翻訳済みの手紙をElloのもとへ", "Translated LetterをLord Ello Ebonlockeに渡して下さい。", "なんてことだ！この手紙に書かれていることが本当なら、Abercrombieは……口にするのもおぞましいことをしてしまったようだ。\n\n翻訳した手紙をElloのところへ持ち帰ったほうがいい。\n\nそれも急いで。もう破滅が、のしのしとこの町へ向かってきているような気がする……", "おお、手紙は翻訳できたのか？ どうか、見せてくれ……", "<Elloは手紙を読み……そして顔が青ざめる。それからあなたを見る……>\n\nAbercrombieに与えた助けが親切心から出たものであったとしても、あなたの行いはこの町を破滅させてしまった。\n\n<Elloは物思いに沈む……>", 0xe1358fe4, 0x997dc93d, 0x30bdbc4f, 0x303a0cc2, 0xbf52b0c4, "....." },
  [253] = { "死体処理師の花嫁", "Elizaの墓を見つけて下さい。彼女からEmbalmer's Heartを手に入れ、Ello Ebonlockeのところへ戻って下さい。", "Embalmerというのは、この地の子供たちの物語に出てくる名前だ。彼は心優しい錬金術師だったが、妻Elizaの死で気が狂ってしまった。妻を蘇らせるため、闇の魔法を使って自分の心臓を死んだ妻の胸に収めたのだ。\n\nそれでElizaは蘇った……だが同時に人間の肉への飢えという呪いがかかり、Embalmerは彼女を埋めておくしかなくなった。\n\n彼の心臓こそ彼の力だ。妻の墓を見つけ、彼の心臓を取り戻して、まだ脈打っているうちに私のところへ持ってこい。そうすれば彼の力は打ち砕かれる。", "Elizaの墓はもう見つけたか？ Embalmer's heartは持っているか？", "やり遂げたのだな！その心臓に宿る魔力はEmbalmerの邪悪に対する守りとなり、Darkshireの町を覆う強力な加護となるだろう。\n\nあなたは我々の民のために偉大なことを成した、{name}。その名は我々の年代記に永遠に残るだろう。", 0xe86145e0, 0x23727411, 0x572b08ce, 0xa3411c44, 0x7066ca1d, "....." },
  [254] = { "土掘り", nil, nil, nil, "あなたは墓の上の緩んだ土を掘り進め……棺の残骸を見つける。\n\n棺の中からは、鉤爪のような指が引っ掻く震えと、腐った歯を噛み鳴らす音が感じられる……\n\n棺を開けてEmbalmerの心臓を取り出すか？", 0x75e151d5, nil, nil, nil, 0x1f58c444, ".mmm." },
  [255] = { "傭兵", "ThelsamarのMagistrate Bluntnoseに雇われ、Mo'grosh Ogreを4体、Mo'grosh Bruteを4体、Mo'grosh Enforcerを4体倒す。", "2か月待ってIronforgeからようやく届いた知らせが、自衛のために兵を一握り回してやるというもので、しかも到着までさらに2か月だと！ 町が無防備なままなのも困るが、発掘現場とダム――あのダムだぞ！――まで攻撃にさらされているんだ。\n\nどうやら他に手はないようだ。傭兵を雇うしかない。\n\nお前はどうだ？ 見込みのありそうな奴だな、{class}。ogreの一団が湖の北東に野営地を構えた。仲間を何人か集めて、この町への脅威を取り除く手伝いをしてもらえないか？", "うまくいったか？", "おお、これは素晴らしい知らせだ! 君の働きには、私もThelsamarの人々も大いに感謝している。さらに言えば、ogreの問題を片付けられれば、あの光に焼かれるべきtroggsどもに注力できるようになる。", 0x68e67e79, 0xd9633fd2, 0x6eaa85fa, 0x580fb5c3, 0x89841e1a, "....." },
  [256] = { "指名手配：Chok'sul", "Chok'sulを倒し、その首をThelsamarのMagistrate Bluntnoseのところへ持って行く。", "Thelsamarの治安判事の命により：\n\nThelsamarの町、Stonewrought Dam、そして発掘現場への攻撃を率い、指揮していると目されるオーガ、Chok'sulを、いかなる手段を用いてでも討ち取るべし。\n\nChok'sulの死の証拠を治安判事のもとへ持参した者には、金銭による報奨が与えられる。\n\nChok'sulが最後に目撃されたのは、Loch Modan北東部のオーガの野営地である。", "何か？ 私にできることはあるか？", "うえっ! 何だそれは? なんでそんなものを持ってきて……\n\nくそっ――! まさか? いやはや、光に焼かれてもかまわん、あれはあの忌々しいogreの首じゃないか? こいつは大した獲物だ! さあ、報酬だ。私とThelsamarの人々からの感謝も一緒にな。", 0xd76c7e39, 0xf939ce2f, 0x8fcfd75f, 0x74cd0668, 0x2b1ae6f2, "....." },
  [257] = { "ハンターの自慢", "Mountain Buzzardを6体倒し、15分以内にFarstrider LodgeのDaryl the Younglingのところへ戻る。", "Daryl the Boldと知恵比べできるとでも思ってるのか、ええ？ そうは思えないな！ もちろん、挑戦するのは大歓迎だよ。お前の力じゃ手に負えないはずの課題を出してやるから、立ち向かえなくてもあまり気を落とすなよ。\n\nbuzzardの群れがここLoch Modanに巣を作っている。あの獣どもを何羽か仕留めてみたらどうだ？ そうだな、15分以内に俺の課題をやり遂げたら、俺の弓か銃をくれてやるよ。\n\n<彼は見下すようにあなたをじろじろと眺める。>\n\nどうせ失うものなんてたいしてなさそうだしな。", "うまくいかなかったのか？ そう落ち込むな、{name}……\n\n誰もが私になれるわけじゃないんだから。", "何? 成功だと?\n\n私から言わせてもらうが、{name}ama、思い上がってはいけないよ。つまりだね、ひげも生えそろわない弓持ちの小僧でも、あんな……小さな獲物なら仕留められたさ。それに、ハゲワシを殺すのをあまり楽しんでいないといいがね? 絶滅してもらっては困るからね。\n\nさて、ええと……Daryl the Boldが約束を守らなかったなどと言われるわけにはいかないな。", 0x0a7320b6, 0x5b163583, 0x5ce8605c, 0xe9d625da, 0x867e7877, "....." },
  [258] = { "ハンターの挑戦", "Elder Mountain Boarを5体倒し、12分以内にFarstrider LodgeのDaryl the Younglingのところへ戻る。", "{name}ath、だったか？ 最初の試験をやり遂げて得意満面なのが見て取れるぞ、ん？ 前にも言ったが、あんなのは大した手柄じゃない。\n\n猪狩りに挑戦してみるといい。言っておくが、これはColdridge Valleyの猪狩りとは訳が違うから、せいぜい気をつけることだ。今回はたった12分しかやらないぞ。\n\n失敗しても気にするな。成功したら、俺の着ているシャツだってくれてやるさ！\n\n俺の有名な傷跡をどうやって負ったか、話したことはあったか？ ない？ あれは2年前のことだ……", "この世界に来て間もない者に見せつけられたら、自分を哀れに思うのも無理はない。気にすることはないさ、{name}ァ。\n\nん? 名前を間違えたかな?", "少々くたびれているようだね。きっとイノシシに手こずったのだろう? 心配はいらない、君の苦労のことは内緒にしておくよ。口さがない連中に責め立てられなくても、君にとってはさぞ大変だっただろうからね。\n\nおや! イノシシを倒せたのかい? 私は……いや、その……つまりだね、驚いてなんかいないさ! 子供でもできる――賭け?\n\n何の賭けだって?", 0xc117168c, 0xf6f7aed2, 0x53a3b2ac, 0x73714f0b, 0x6757139d, "....." },
  [261] = { "Scarletの道を下って", "Undead Ravagersを$N1体倒し、Nijel's PointのBrother Antonのところへ戻って下さい。", "率直に言おう。我々はScourgeと戦争をしている。それは我らの民を堕落させ、我らの地を蝕む悪だ。我々を呑み込み、この世界を闇へ引きずり込む前に止めねばならない。我らScarlet Crusadeは、身も魂も懸けてScourgeと戦うと誓ったのだ。\n\n我々と共にあるなら、勇気を奮い起こして忠誠を示せ。南のValley of Bonesにいる、Desolaceのアンデッドの破壊者どもを滅ぼすのだ。\n\nこれを果たせば、Crusadeは君を迎え入れるだろう。", "Scourgeは日を追うごとに力を増している。本当にその進撃を食い止めたいのなら、それを私に示してみせよ。", "君は決意のほどを示した。Scarlet Crusadeは君を称える。\n\n正義の殺戮を恐れぬのなら、君の道は我らと共にあるのかもしれん……", 0xaeca3093, 0x205551e6, 0xdc7cbe13, 0x256387b8, 0x2d30e832, "....." },
  [262] = { "黒い人影", "Sven's farmで見つけた本をDarkshireの住民に見せて下さい。", "家族が殺された夜に見た、あの影に潜んでいた者が誰なのか、どうしても知らねばならない！\n\n頼む、{name}、君は機転が利くところを見せてくれた。どうかあの人影を見つけてくれ。奴の抱えている秘密を知らねばならないんだ！\n\n君がまだ知らない手がかりは持っていないが、ほら、私の農場で見つけた本を持っていってくれ。町の誰かが、この本と持ち主を結びつけられるかもしれない。", "あなたが探している影の人物の持ち物があるなら、見せてください。その持ち主について何かを占えるかもしれません。", "ふむ……最近誰かがこの本に触れている。復讐に駆られた者だ。だがそこに残された痕跡は、少なくとも元の持ち主の痕跡は、薄い。\n\nだがこれだけは言える。この本の元の持ち主はDarkshireの生まれではない。", 0x314895c6, 0x43340f49, 0x13c0ea44, 0x383fb720, 0x6233a5dd, "....." },
  [263] = { "王の領土の防衛", "Stonesplinter Shamanを10体とStonesplinter Bonesnapperを10体倒してほしいと、南の見張り塔にいるMountaineer Wallbangは言っています。", "Mountaineersから聞いたが、お前はなかなか勇敢で有能だそうだな、{name}。この辺りにはお前のような{race}が必要なんだ。Troggの問題は一向に良くならない。予備兵は前線に呼ばれて、ここにいるのは我々だけだ。だが、こうして熟練の{class}が来てくれたんだ、お前の腕前を見せてもらおう。\n\n出かけて、Stonesplinter Shamanを10匹とStonesplinter Bonesnappersを10匹倒してこい。評判通りの腕かどうか見せてもらうぞ、Trogg-Slayer。", "もう戻ったのか? はっきり言わなかったかもしれんが、Stonesplinter Shamanを10体とStonesplinter Bonesnappersを10体倒してほしいんだ、{name}。さあ、やっつけてこい、Trogg-Slayer!", "{name}、君を一目見た瞬間から、Ironforgeの誇りとなる者だと分かっていた。King Magniによく尽くしてくれたな。王国への忠実な助け手であることを証明した今、隊長に話して、より重要な任務を任せてもらえるか確かめてみるといい。\n\n君に敬礼する、{name}。", 0xc965c9da, 0x4a79e4d2, 0x0a04bb9f, 0xe5f1b1fc, 0xfc0b08bb, "....." },
  [264] = { "死が二人を分かつまで", "Clarice's Pendant を Silverpine にある Yuriv の墓へ置いてきて下さい。", "汚らわしいクズめ！ あのくだらない聖戦のために私を置いて行ったのよ。「光こそ、アンデッドがもたらす脅威に対して我々が持つ最も大切なもの」だからって。\n\nじゃあ、子供たちはどうなるの？！ 私はどうなるのよ？！ 毎晩毎晩、私は辛抱強くあの人を待っていた……いつだってあのいまいましい務めの次だった！\n\nさあ、「正義」がもたらすものを見るがいいわ、{name}！ あの人は死んで、私はあの人が止めようとしていたまさにそのものを抱えているのよ！\n\nこのガラクタを持って行って、Sepulcherにあるあの人の墓に置いてきて。もうこんなものとは関わりたくないの……あの人ともね！", "石は触れると冷たいが、明らかに荒らされている。辺りにはごみが散らばり、棺の上の浮き彫りには傷や裂け目が刻まれ、墓の周りの草木は墓所を覆い始めている。\n\nここに眠る者を気にかける者は誰もいない。疫病の犠牲者なら、なおさらだ。", "価値のないペンダントを墓に置いた。ペンダントにあしらわれた宝石は、明らかにくすんでいた。\n\n立ち去ろうとして見下ろすと、ペンダントは棺に彫られた彫像の手の上に死んだように横たわっていた。Sepulcher を吹き抜ける冷たく強い風が、物思いに耽る自分を現実に引き戻した。一瞬、すべてが静寂に包まれた。", 0xa73209cc, 0xbb2445eb, 0xdadc8728, 0x4b0ea1a7, 0xf1fedc56, "....." },
  [265] = { "捜索続行", "人影に関する手掛かりを他の住人が持っているかどうか調べて下さい。", "本をお返しします、{name}。探索の幸運を祈っています。町の他の人たちにも聞いてみれば、もっと手がかりをもらえるかもしれませんよ。\n\nそれから、もう1つ手がかりを。この本の著者はDarkshireにとってよそ者ですが、本そのものはここで買われたものです。", "学者やメイジ、あるいは日記をつけたい人になら、白紙の本を売ることもあるよ。\n\nここ数か月の間に本を売った相手は、みんなよく覚えているよ……", "ああ、そうだ。この本は一月前に怪しげな人物に売った。名前は言わなかったが、神経質でそわそわした男で、いつも背後を気にしていた。\n\nそれが助けになるといいが……", 0x15f6b643, 0xfc327109, 0xbf55c340, 0x1c3e5d22, 0x7f698a5e, "....." },
  [266] = { "宿での聞き込み", "宿で人影についての手掛かりを尋ねて下さい。", "本をお返しします。聞き込みがうまくいくといいですね。\n\n宿屋まで探す範囲を広げてみるといいかもしれません。探している人物が町で過ごしていたなら、誰かがそこで見かけている可能性が高いですから。", "Scarlet Ravenもかつてほど繁盛してはいないが、それでも旅人は立ち寄るよ。\n\n探している人物の特徴を教えてくれれば、思い出せるかもしれないね。", "ああ、この本は覚えているよ。持ち主は数日部屋を借りて、夜は酒場で書き物をして過ごしていた。\n\n何かに追われていると呟きながら、慌ただしく町を出ていった。最後に見たときは、新しい隠れ場所を探して町の西へ向かっていたよ。\n\n西へ向かって最初に見つかる場所はRaven Hillだね……", 0x4736a4dc, 0xbe6a7054, 0x6d658e06, 0xe05a3817, 0x7f159659, "....." },
  [267] = { "Troggの脅威", "Trogg Stone Teethを8個、南の見張り塔にいるCaptain Rugelfussのところへ持って行く。", "{class}、ドワーフの地に迫るTroggの脅威を知っているかどうかは分からんが、Ironforge ReserveがAlliance Frontへ召集されたせいで、この地の安全を守るのに必要な防衛戦力のほんの一部しか残っていないのだ。私の連隊はここのGateの見張りを任されていて、侵攻を恐れて持ち場を離れるわけにはいかん。\n\nだが丘に潜むあの忌々しいTroggどもに圧力をかける必要がある。やる気があるなら、Troggどもに攻撃を仕掛けてくれ。証拠としてTrogg Stone Teethを8個持ち帰るのだ。", "Trogg Stone Teethを8個見せてくれるか? まだなら、やるべき仕事が残っているぞ、{name}。", "実に感心したぞ、{name}。我らの土地を守ってくれたことで、お前はドワーフの民に大きな恩を施した。King Magni Bronzebeardご自身もきっと誇りに思われるだろう!", 0x5feba290, 0x14a4d831, 0xc4e3d0e9, 0xfb5e59d0, 0xe9c8efe3, "....." },
  [268] = { "Svenのもとへ", "SvenのところへJitters' completed journalを持ち帰って下さい。", "あんたが見つけた本は、半分しか書けてなかったんだ。あそこへ逃げたとき、Svenの農場に置いてくるしかなくて……\n\nほら。書き終えた俺の日記をSvenのところへ持っていってくれ。彼の農場で何があったか、もっと詳しく書いてある。\n\nこの数週間、この日記だけが話し相手だったけど、手放すことでSvenと顔を合わせて奴の怒りを受けずに済むなら、喜んで渡すよ！", "Shadowy Figureの正体は分かったか?", "日記でいろいろなことが分かったよ。Dark ridersと戦うしかない! Duskwoodであいつらを見たことがあるんだ。それと、Forlorn Roweにいる魔法使いMorbent Felと話をしてるとこもな。", 0xb5e4d4a7, 0xddfbac78, 0xa746e876, 0x34bcef3e, 0x11d4dc98, "....." },
  [269] = { "知識を求めて", "Jitters' Completed JournalをStormwindのBishop Farthingに渡して下さい。", "Stormwindの街へ行き、Cathedral of LightにいるBishop Farthingと話してくれ。彼にJittersの日記を渡し、Morbent Felと対決するつもりだと伝えるんだ。\n\nStormwindはDarkshireを見捨てたが、Farthingは心優しく、とても賢い人だ。我々を救う君のクエストを手伝ってくれるかもしれない。\n\n君の使命は危険だが、急いでくれ、{name}。時が経つごとに、Duskwoodの影はますます暗くなっていく。", "休みなさい、同胞よ。あなたが遠くから旅してきたこと、そして重い荷を背負っていることが分かります。あなたに暗い影を落としているものが何なのか、話してくれませんか?", "<日誌を読み、あなたの意志を聞いた後で……>\n\n邪悪な汚れが、すでに苦しめられているDuskwoodに足がかりを得てしまった。それに立ち向かうあなたのような英雄がいることを、光に感謝する。\n\nだがまずは来たる試練に備えねばならない……Necromancer Morbent Felは途方もなく強力で、物理的な攻撃から身を守るために闇の魔法を自らにかけている。奴を倒すつもりなら、その守りを打ち破る武器が必要になる。", 0xa17403e8, 0xe615de8a, 0xc211aa79, 0x0ed6c310, 0xce1c3c43, ".....", nil, nil, nil, 0x36e5648e, nil },
  [270] = { "沈没船", "WetlandsのMenethil Harborへ行き、Glorin Steelbrowと話して下さい。", "数年前、ドワーフの王国Ironforgeの北に広がる沼地、Wetlandsの海岸沿いにKul'Tirasの第三艦隊が沈みました。あの船にはLightforge Ironが積まれていたのです。\n\n聖なる真理で敵を討つ武器を作るため、あの金属は私たちにとって貴重なものなのです。Morbent Felに立ち向かうつもりならば、そういった武器が必要でしょう。\n\nMenethil Harborへ行き、ドワーフの同志Glorin Steelbrowと話をしてきて下さい。失われた金属を見つけるのであれば、どこを探せばよいかは彼が知っています。", nil, "Lightforge Ironは貴重な金属ですが、あなたの探索はひどく困難なようですね。遠くからよく来て下さいました、同志よ。運が良ければ、求めている物はすぐ見つかるでしょう!\n\n金属を手に入れたら、Duskwoodにいるというそのネクロマンサーと対抗する武器を作る職人を紹介しましょう。", 0xb30a2ab9, 0xb61b8cec, 0x14f1ea19, nil, 0xd5d90125, "...m.", nil, nil, nil, nil, 0x62417845 },
  [271] = { "Vyrinの復讐", "Ol' Sootyを倒し、その成果をFarstrider LodgeのDaryl the Younglingに見せる。", "あの勇ましいお方にちょっとした仕返しをしてやる気はないかね？ 悔しいが、Darylにもそれなりの腕はあるんだ。\n\n一年前、Farstrider Lodgeは一頭の大きな熊を狙っていたんだが、ハンターたちは誰一人として仕留められなかった。そこでDarylが自分で挑んでみようと思い立ったわけだ。その結果得たものといえば、目の上のあの醜い傷跡だけさ。\n\nその熊を倒してくれれば、さすがのDarylも一度くらいは言葉を失うだろうよ。\n\nその熊、Ol' Sootyは、Thelsamarの上の丘にあるねぐらのあたりにいるはずだ。", "やあ、{name}! もう戻ったのか? また狩りに出ていたんだろう? うまくいかないことがあっても気にするな、長い目で見ればそれで上達するんだから!\n\n……どうせ、これ以上下手にはなりようがないしな……", "え……これは何だ? 見たところ、熊の頭のようだな。\n\n<彼は無意識のうちに傷跡を指でなぞる。>\n\nいやはや、ずいぶん面白い獲物を仕留めたもんだな。まさか、あの時の熊ってことはないだろうが……\n\n<彼の言葉は途切れ、目に見えて震え始める。>\n\nおい、それをどけてくれ、どけてくれ! その気味の悪いものをここから持ち出してくれ!", 0xeb8bf51a, 0x9c0267f5, 0x0f0813b8, 0xce498672, 0x84cbe4fe, "....." },
  [272] = { "アシカの試練", "Half Pendant of Aquatic AgilityとHalf Pendant of Aquatic Enduranceを見つけて下さい。それがありそうな場所の手がかりを得るため、Moongladeの住人と話して下さい。\n\nペンダントの片割れを組み合わせ、Pendant of the Sea Lionを作って下さい。そうするためには、Shrine of Remulosの近くにいる必要があります。\n\nつなぎ合わせたペンダントをMoongladeのvillage of NighthavenにいるDendrite Starblazeのところへ持って行って下さい。", "第二の試練として、Pendant of the Sea Lionを作る片割れふたつが要ります。半分はなめらかに水の中を泳ぐアシカの敏捷性から力を引き出し、もう半分はアシカの驚くべき持久性から力を引き出します。彼ら水生動物の特性を具現化した姿に違わず、その特徴の両方をドルイドは利用することができるのです。\n\nMoongladeの人たちにペンダントの片割れがどこにあるか聞いて下さい。そしてつなぎ合わせるために、両方ここへ持ってくるのです。出来上がったら、ペンダントをDendrite Starblazeのところへ持って行って下さい。", "私が確かめられるよう、ペンダントは作り上げましたか、{name}？部品のありかを探すのに助けが必要なら、この土地の人々に尋ねてみるとよいでしょう。探しているものが見つかるだけでなく、この素晴らしく神聖な林を探索するきっかけにもなりますよ。", "{name}、アシカの試練は終わった。おめでとう。\n\nペンダントを作るのに求められた課題が示している敏捷性と持久力のふたつは、水の中で動きたいという望みと一致する無くてはならぬものだ。どちらも、一方無くして存在することはできない。そしてどちらも、アシカの特性を受け入れようという意志が無くては行えないのだ。\n\nこの修行をよく覚えておき、aquatic formを得た後も、心のよりどころとしてほしい。", 0x5cc8ed68, 0xdf177053, 0x23c219a5, 0x3520b13e, 0xb90d61f2, "....." },
  [273] = { "発掘現場への補給", "Huldarと話してください。", "でも、まだ手遅れじゃない。Huldarを探しに行ってくれるなら大歓迎だ。そう遠くへは行っていないはずだ。MiranとSaeanは力持ちだが、あの樽を背負っていてはそう速くは動けんからな。\n\n連中はいつもの道で現場へ向かっている。町を南へ出て、Lochの湾曲に沿って進むんだ。\n\nもう着いてしまっていなければ、見つけるのに苦労はしないだろう。", nil, "ふん、配達を止めるにはDark Ironの待ち伏せ程度では足りんな！\n\nだがSaeanか……奴が連中の共鳴者の一人だとは思いもしなかった。もう一年近く一緒に働いてきたのに……兆しを見逃していたのかもしれん。\n\nまあ、それは後で考えよう。", 0xff211d45, 0x48ac2cba, 0xa385adaf, nil, 0xd8cf8be4, "...m." },
  [274] = { "迫り来る闇の脅威", "Chief Engineer Hinderweirのところへ戻って新たな発見を知らせてほしいとAshlan Stonesmirkは言っています。", "こいつはただの発破用の火薬じゃねえ。この小さな銀色の結晶を見てみな。それにこの独特の匂い！ こりゃどう見てもSeaforium Powderだ。Seaforium自体は大して害はねえ。だが一度濡れたら、Ironforgeを山ごと吹き飛ばしかねねえんだ。\n\nその化学反応は、4つの材料を混ぜれば止められる。lurkerの毒、砕いたMo'Groshの結晶、crocoliskの涙、それとこの解除用のコロイドだ。さあ、手遅れになる前にHinderweirに伝えてくれ！", "Ashlanから何を持ってきたのだ?", "disarming colloidだって? Seaforium用の? なんということだ!", 0x285fa090, 0xff4b9027, 0xae733e3d, 0x9e72d87b, 0x6bbfd674, "....." },
  [275] = { "大地の水ぶくれ", "Fen Creepersを$N1体倒し、WetlandsのRethiel the Greenwardenのところへ戻って下さい。", "なぜかは分かりませんが、Wetlandsの中で膿み腐れが広がっています。Fen Creepersが現れたのです。彼らはこの地にできた病んだ熱ぶくれです。熱を下げるには、彼らを退治して沼地へ還してやらねばなりません。\n\nFen CreepersはWetlandsの水路の間をよろめき歩いています。", "Wetlandsは今も涙を流し、Fen Creepersは今も荒れ狂っている。務めを果たしたら戻ってくるがよい。", "そなたの働きによってこの地は癒やされた。その礼として、我はそなたに恵みを授けよう。", 0x98ec1fa6, 0x4f711ba6, 0x588d9f5d, 0x987a7155, 0xd673054a, "....." },
  [276] = { "踏み荒らす足", "Mosshide Gnollを15体とMosshide Mongrelを10体倒し、WetlandsのRethiel the Greenwardenのところへ戻る。", "Mosshide Gnollsは長年Wetlandsで平和に暮らしてきましたが、今やその数が増えています。彼らの足は湿地の茂みや花を踏み潰し、その汚れた斧は火を焚くために木を切りすぎているのです。\n\n彼らはもはや大地と調和していません。Wetlandsが生き延びるためには、Gnollsを減らさねばなりません。\n\nMosshide Gnollsを15匹、Mosshide Mongrelsを10匹倒してください。南の、Algazのドワーフの門の近くで彼らを狩るのです。それが済んだら、私のもとへ戻ってきてください。", "そなたの務めはまだ終わっておらぬぞ、若き{class}よ。", "Gnollsの数を減らしたことで、そなたはWetlandsの健やかさを守った。そなたの種族への我が信頼はかつて揺らいだこともあったが、{race}よ、それもいずれ取り戻せるかもしれぬ。", 0xc2e1895b, 0xefe8bed1, 0x1e6b39f8, 0x5811b98d, 0xd1151a2d, "....." },
  [277] = { "火の禁忌", "Crude Flintsを$N1個、Rethiel the Greenwardenのところへ持って行って下さい。", "MosshidesがWetlandsの木々を切り倒し、その木の肉を燃やして暖を取っている。この痛みにはもう耐えられない！\n\nMosshidesから、火を起こすのに使う道具、crude flintsを奪ってくれ。flintsは、小柄なMosshide gnollsとMosshide mongrelsを除く、すべてのMosshidesが持っている。", "Gnollsの火起こしの道具は手に入れたか?", "……感謝する。この火打ち石は砕いて海へ投げ入れよう。二度と生ける木を焼くために使われることのないようにな。", 0xf9fd95dd, 0x07df69ca, 0x0d5db968, 0x4c8714a1, 0xf8f39043, "....." },
  [278] = { "迫り来る闇の脅威", "Lurker Venom、Mo'grosh Crystal、Crocolisk Tearを集めてほしいとChief Engineer Hinderweirは言っています。", "すぐに解除用の材料を集め始めてくれ、{name}。Lurker VenomはLoch Modanにいる土着の蜘蛛から手に入る。Crocolisk tearsもここLochで手に入る。だがMo'Grosh crystalを手に入れるのはとても難しいだろう。北東のogreどもが採掘しているが、その結晶は非常に希少な品なんだ。\n\nDark Ironの攻撃を食い止める備えをしておかねばならん！ 必要な品を集めたら戻ってきてくれ。私が混合物を用意しよう。", "必要な品は揃ったか? 一刻を争うんだ!!", "ちょうどいいところに来た、{name}!", 0x285fa090, 0x7dcc9e32, 0xda78b8d7, 0x6ba64689, 0x4c641a56, "....." },
  [279] = { "深みからの爪", "Bluegill Murlocを12体倒す。\n\nGobblerを倒してその首を手に入れる。\n\nGobbler's HeadをMenethil HarborのKarl Boranのところへ持って行く。", "Murlocsが深い海から這い出てきて、海岸沿いに村を作っている。奴らは我々の漁師や商人に嫌がらせをしており、止めなければならない。\n\nそうしたMurlocsの1匹、Gobblerは、他のBluegill Murlocsとともにこそこそと動き回り、道沿いの商人を襲っては、いつも近くのMurlocの小屋という安全な場所へ引き揚げていく。商人たちが危険にさらされている。彼らの安全を確保するためなら金を払おう。\n\nGobblerはここから北の川の入り江をうろついている。奴を見つけ、その仲間を倒し、奴の首を持ってきてくれ。", "GobblerとあのMurlocsを始末するまで、我々の商人たちは安全ではない。", "ああ、よくやった、{name}。\n\nMerchant Marinesとの契約を果たした報酬として、これを受け取ってくれ。", 0xb2853dd5, 0xf105a28f, 0x413ad26f, 0xf4549fd2, 0x3b289c36, "....." },
  [280] = { "迫り来る闇の脅威", "ダムの底まで泳いで潜り、火薬樽を見つけてDisarming Mixtureを混ぜ入れ、爆発を防いでほしいとChief Engineer Hinderweirは言っています。", "今日の早い時間に、Dark Iron Insurgentsが大きな樽を持ってDamへ泳いでいくのを見かけたんだ。止めに入れるMountaineersは一人もいなかった！ 奴らはDamの土台にSeaforiumを仕掛けたんじゃないかと心配だ。いつ爆発してもおかしくない！ この材料を全部混ぜてDisarming Mixtureにしよう。よし、できた。\n\nさあ、手遅れになる前にこの混合物を持っていって、樽の中にかき混ぜて入れてくれ！ 急いで！", "樽の蓋がゆっくりと回って外れた。", "Disarming Mixtureが染み込むと、樽がかすかにシュウシュウと泡立つ。", 0x285fa090, 0x49e1c755, 0xcabe6c09, 0x1bf6801c, 0x3e97c160, "....." },
  [281] = { "品物の奪還", "海岸沿いのMurlocの野営地で木箱や樽を調べる。", "少し前、商船Blind PrincessがMurlocsに襲われた。船は無事に逃れたが、積荷の多くがあの生き物たちに船の外へ引きずり出されてしまった。その中には、Terenas Menethilのとても貴重な小像もあった。我々はその小像を取り戻したい。\n\n海岸にあるMurlocの住処を探して、木箱や樽など、失われた積荷の手がかりを見つけてくれ。Menethil Statuetteを見つけて、私のところへ持ち帰ってほしい。", nil, "この木箱は爪で引っかいた跡と、水に濡れて傷んだ跡に覆われている。こじ開けると、湿って腐った藁が出てくる。まるで何か価値のあるものが箱にしまわれていたかのようだ。藁の中を探ると……\n\n……赤い色の瓶がひと抱え見つかる。", 0x20e23136, 0x92703920, 0xae0acc9a, nil, 0x1db70c6a, "...m." },
  [282] = { "Senirの所見", "Mountaineer Thalosと話せ。", "報告書は弟子に持たせて兄弟のSenirに送るつもりだったが、もっと……信頼できる者の手に預けたほうがずっと安心できる。もちろん、君さえよければだが？\n\nふむ……Kharanosへ行くにはトンネルを通らねばならんな。\n\nトンネルを抜ける前にMountaineer Thalosと話しておけ。今あそこはtroggsだらけだ。\n\n道なりにAnvilmarまで戻って、そのまま東へトンネルまで進め。Thalosはその近くに配置されている。", "やあ! 気をつけろ、{name}。Dun Moroghへのトンネルにはtroggsがはびこっていて、通るのは危険だ。\n\nDun Moroghに急ぎの用がないのなら、トンネルが安全になるまでAnvilmarに留まってもらわねばならん。", "ふむ、そうか、Whitebeardが大事な用でお前をDun Moroghへ送るというのなら、俺が止めるわけにもいくまいな？\n\nせめて助言と道順くらいは教えさせてくれ。", 0x034f6959, 0x04633807, 0xa94e25b2, 0xfbfd2fad, 0xe36152d6, "....." },
  [283] = { "迫り来る闇の脅威", "Disarming Mixtureは効いたようだ。Chief Engineer Hinderweirのところへ戻って朗報を伝える。", "樽がかすかにシュウシュウと音を立てる。", nil, "本当にありがとう、{name}!! Stonewrought Damを救ってくれた! 君の助けがなければ、Dark Ironのテロリストどもがきっとこの偉大な建造物を破壊していただろう。君は王国とAllianceの誇りだ、勇敢な{class}よ。\n\nダムは再び安全になった……少なくとも当面は……。", 0x285fa090, 0x59adb22f, 0x5529aef7, nil, 0x6249196b, "...m." },
  [284] = { "捜索は続く", "Menethil Statuetteを探す。", "このMurlocの住処の一群をくまなく探したが、Menethil Statuetteの痕跡は見つからない。\n\n北と北東の近くにある二つの住処のどちらかに、もっと手がかりがあるかもしれない。", nil, "この樽はほとんど手つかずだ。こじ開けると……\n\n……チーズの刺激臭が襲ってくる。少し湿っているが、まだおいしい!", 0xf8a6514c, 0x2fa34187, 0xc6d42d7d, nil, 0xf8bf63bc, "...m." },
  [285] = { "さらなる小屋の捜索", "Murlocの小屋でMenethil Statuetteを探し続ける。", "このMurlocの住処の一群を念入りに調べたが、何も見つからない。\n\n……だが、次に見つける手がかりこそ実を結ぶはずだと確信している。\n\n北にある住処のどれかに、Menethil Statuetteがあるに違いない！", nil, "この樽は泥と草の中に半分埋もれている……", 0x37a342ab, 0xe542c0b8, 0x164b5557, nil, 0xc166ecf6, "...m." },
  [286] = { "小像を返す", "Menethil StatuetteをKarl Boranのところへ持って行って下さい。", "泥の中から樽を引き出して開けると、上等な藁に包まれた銀色の小像が見つかった。ハンマーを振り上げた、長い髪の若いパラディンをかたどっている。\n\nこれがMenethil Statuetteに違いない！Menethil HarborのKarl Boranのところへ持ち帰らなければ。", "statuetteは持っているか?", "Blind Princessの船長は、この貴重な積み荷が回収されたと聞けば安心するだろう。君はこの働きに対する報酬を十分に稼いだ。\n\n君のような頼りになる者に会えるのはありがたい。特にこんな苦しい時代にはな。", 0x6359787c, 0xe755db7e, 0x468c1b10, 0xc8e24594, 0xee837828, "....." },
  [287] = { "Frostmane Hold", "KharanosにいるSenir Whitebeardの為に、Frostmane Holdを探索し,Frostmane Headhunterを5匹殺せ。", "私の報告書が遅れていて、助けを借りたいんだ、{name}。私はトロルが潜む場所をようやく見つけたんだが、トロルの数が多すぎて、中に入るのがためらわれる。\n\n私が必要としているのは・・洞窟に入り、中を探索し、トロルを何匹か殺してから、ここへ戻って来る事だ。\n\nKharanosを出たら北へ向かえ、橋についたら、凍った川を西へ、Iceflow Lakeに着くだろう。Brewnall Villageが西の岸に見えたら、砦は村の南西にある。", "見つからないだって? 私の道案内はとても分かりやすかったはずだ! 時間がないんだ、急いでくれ! 洞窟を見つけるまで戻ってくるな!", "おお、{name}！場所を見つけるのに大して苦労はしないと思っていたよ。私の道案内は見事なものだからね……\n\nでは、報告書を仕上げてしまおう。\n\n<彼は紙を取り出し、しばらく何か書きつける。>\n\nよし！さて、ははは、これは確かに妙なことになったな……{name}、最後にもう一つだけ頼みを聞いてもらえないだろうか？", 0xef0caa5c, 0x7d5b3c3e, 0x6aadc3c6, 0x81548c58, 0x832ea7a7, "....." },
  [288] = { "第三艦隊", "First Mate FitzsimmonsにFlagon of Meadを一杯おごって下さい。", "わしはかつて、Kul Tiras Third Fleetの戦列艦、Wave MistressのFirst Mateだった。The Doomed Fleet。呪われた艦隊だ。最後の航海で、艦隊はRed Dragonsに襲われたのだからな。オークどもに操られたドラゴンにだ！\n\nあの竜の炎には、まるで歯が立たなかった……艦隊は焼かれ、この海岸の沖に沈んだ。あの哀れな船々の生き残りは、わし一人だけだ……\n\n……ああ、頭ががんがん打ちつけるようだ！この二日酔いをどうにかして話を続けるには、新しい一杯が要るな。", "ああ、喉がからからだ! この哀れで情けない愚か者に一杯おごってくれないか?", "ああ! こいつは効くな、舌の滑りも良くなる。ありがとよ、相棒!", 0xd344ba5e, 0x9f386e77, 0x4f64105d, 0x0916d95e, 0x77f68422, "....." },
  [289] = { "呪われた船員", "Cursed Sailorsを$N1体、Cursed Marinesを$N2体、そしてFirst Mate Snelligを倒す。Snellig's SnuffboxをMenethil HarborのFirst Mate Fitzsimmonsのところへ持って行って下さい。", "<元気を取り戻し、Fitzsimmonsは話を続ける……>\n\nわしは、北の沖で難破した不運なKul TirasのThird Fleetのただ一人の生き残りだ。だが、艦隊でまだ息をしているのはわしだけでも、まだうろついているのはわしだけじゃない！我々の船の一隻に、偉大で恐ろしい財宝が隠されていてな、その不気味な力が、わしの兄弟たちの魂を朽ちかけた船体の中に閉じ込めているのだ。\n\nだが、兄弟たちの何人かを解放できれば、呪いを解けるかもしれん。", "夢の中で、同胞たちの絶望のうめき声が聞こえることがあるのです! どうか、親切なお方、彼らを束縛から解き放ち、その叫びを鎮めてください。", "礼を言う、{name}。呪われた我が同胞たちも、君に感謝している。", 0x0118d790, 0xc4c1a698, 0x35bb2a47, 0x9a98af9c, 0xaaba9d50, ".....", nil, nil, nil, 0xa3fe69e6, nil },
  [290] = { "呪いを解く", "Captain HalyndorからIntrepid Strongbox Keyを手に入れる。\n\nその鍵を使ってIntrepid's Locked Strongboxを開けて下さい。", "呪いを解いて兄弟たち全員を解放するには、わしの船に積まれていた……あれを……取り戻して清めねばならん！それが何だったのかは知らんが、Captain Halyndorが管理していた船の金庫に厳重にしまわれていたのは確かだ。\n\nかつての船長は今もわしの夢に出てくる。あの人は今もわしの呪われた船、Intrepidを歩き回っているはずだ。船長から鍵を奪い、それでIntrepidの金庫を開けてくれ。\n\nそして呪われた品を手に入れたら、町にいるプリーストのGlorin Steelbrowのところへ持っていってくれ。", "この箱にはしっかりと鍵がかかっている。", "鍵は錆びているが、錠にぴったりとはまる。", 0x67d85feb, 0x99644b95, 0x74e1986b, 0x24ee971a, 0xfcdb2cc9, "....." },
  [291] = { "報告書", "IronforgeにいるSenator Barin RedstoneにSenir's reportを届けろ。", "素晴らしい！私の報告書をSenator Barin Redstoneに届けてくれ。気難しい人だから、あの無愛想な態度は気にしないことだ。彼はIronforgeにいる。King Magniが謁見を行う広間だ。\n\nIronforgeへの道がわからない？Kharanosから北へ道を出て、橋を渡り、それから道なりに東へ進むんだ。道の両側には大きな旗が並んでいる。そのまま山腹を登っていけばいい。\n\nところで、君が私を手伝ったことは、できれば黙っていてくれないか？こっちで私がまじめに働いていないと思われては困るからな。", "ふむ……どうやら私の衛兵たちは、陳情者を選り好みしなくなってきたようだな。で、何の用だ? 手短に言え。", "＜素早く報告書に目を通す。＞\n\n王の威光だと！？Magniは完全に正気を失っておるな！それにしても、忌まわしいWhitebeardめ・・・自分の手で事件を解決した？、奴が？元老院はこんな報告では喜ばんぞ、これっぽっちもな。\n\nなんだ、まだそこにいたのか？衛兵を呼ぶ前に消えろ！", 0xdad7b810, 0xaeae0022, 0x237d8c9e, 0x1abc830a, 0xe6cf8786, "....." },
  [292] = { "Eye of Paleth", "Cursed Eye of PalethをGlorin Steelbrowのところへ持って行って下さい。", "箱を開けると、不気味な光を脈打たせる黒ずんだ球が現れた。Fitzsimmonsが話していた財宝、Cursed Eye of Palethだ。\n\nCursed Eye of Palethを、Menethil Harborにいるドワーフのプリースト、Glorin Steelbrowのところへ持っていこう。Eyeの呪いを解く方法を彼に尋ねるのだ。", "あの酔っぱらいのFitzsimmonsがあんたをよこしたって? じゃあ伝えてくれ、余分なエールなんかないってね。よそで物乞いしてもらうしかないよ!", "Eye of Palethだって? すごい! うーん……これはどこかおかしいな。あの難破船のひとつで見つけたのかい? なるほど、それで説明がつく! でも……Third FleetにそんなEyeがあったなんて知らなかったよ……\n\nFitzsimmonsがあんなに怯えていたのも無理はない。Cursed Eye of Palethは笑いごとじゃないからね。", 0xc0c774ae, 0x82ab47a4, 0x610cc5e1, 0xd79890d9, 0x4fe3c3df, "....." },
  [293] = { "瞳の浄化", "Cursed Eye of PalethをArchbishop Benedictusのところへ持って行って下さい。BenedictusはStormwindの街のCathedral of Lightにいます。", "Eye of Palethの呪いは、わしには解けん。Eyesは人間のプリーストたちが作ったものだから、手を貸せる者を探すにはStormwindへ行かねばならんだろう。Archbishop Benedictusと話すといい。彼はStormwindのCathedral of Lightの長だ。彼なら助けてくれる。\n\nそう願っておるよ、お前さんのためにもな。", "その宝珠は何だ? なんだか……汚れているように見えるな。", "Eye of Palethですね。ですが、これは多くの悲しみを見てきたようです……恐ろしい、本当に恐ろしい悲劇を目の当たりにしたに違いありません。\n\n私に清めさせてください。Eyesは明るく輝くために作られたもので、このように穢れてしまうと、その力はとても危険なものになりかねないのです。", 0x2f74c1ea, 0xbdcdebd1, 0x6e4ad21f, 0xed3db153, 0x32563e90, "....." },
  [294] = { "Ormerの復讐", "Whelgar Excavation SiteのOrmer Ironbraidは、Mottled Screechersを$N1体とMottled Raptorsを$N2体倒してほしいと言っています。", "事態は深刻だ、それだけは確かだ。我々がこの骨を掘り出したせいで、Raptorsが寄ってきたんだ。あの汚らわしい獣どもが同胞を殺し、私とMerrinと、気の毒な探鉱者をここに閉じ込めた。\n\nWetlandsからそのRaptorsを一掃するのを手伝ってくれ、{name}。Mottled RaptorsとMottled Screechersは、あの崖のすぐ西にいる。できれば、それぞれ10匹ずつ倒してくれ。\n\n奴らへの復讐の手始めとしては上出来だ。", "Mottled Raptorsを10体とMottled Screechersを10体倒してくれ、{name}。仲間たちがあんな目に遭ういわれはなかった。借りを返す時だ。", "殺しは汚れ仕事だが、君はよく務めを果たした、{name}。探鉱者とMerrinのそばにいる義務がなければ、俺も下で君と並んで血を流していたところだ。", 0x9f3d027d, 0x96bcadfc, 0x5fa2aa4a, 0x3737f909, 0x4931c25a, "....." },
  [295] = { "Ormerの復讐", "Ormer Ironbraidは、Mottled Scytheclaw raptorsを$N1体とMottled Razormaw raptorsを$N2体倒し、Whelgar Excavation Siteの彼のところへ戻ってきてほしいと言っています。", "さあ、あの忌まわしいRaptorsどもに、血に飢えたことを本気で後悔させてやる時だ。すぐ下に、Mottled ScytheclawsとMottled Razormawsがうじゃうじゃいる。それぞれ10匹ずつ倒して、あの腐った獣どもに報いを受けさせてくれ！", "あのMottled ScytheclawsとMottled Razormawsに、奴らのしたことの報いを受けさせてやりたい。それぞれ10体ずつ倒したか?", "あのRaptorsを見事に一掃してくれたな、{name}!", 0x9f3d027d, 0x2f20d043, 0xe2f5b517, 0xedd86ff7, 0x8ba1a22c, "....." },
  [296] = { "Ormerの復讐", "Whelgar Excavation SiteのOrmer Ironbraidは、Sarltoothを倒し、任務を果たしたらその鉤爪を一つ持って戻ってきてほしいと言っています。", "君が下にいる間に、あの獣の中に一匹だけ目立つ奴がいるのに気づいたんだ。ほかより大きくて、凶暴そうだった。きっと、あいつがほかの奴らをここへ率いてきて、発掘現場を荒らさせたに違いない。\n\n最後に一つ頼みがある、{name}。Sarltoothに裁きを受けさせてくれ。奴の罪の重さを考えれば、この場合の裁きとは死だ！奴が死んだ証に、奴の鉤爪を一本持ってきてくれ。", "Sarltoothは死んだか? 倒れた者たちの無念を晴らしてくれたか?", "ありがとう、{name}。ここでの君の働きは忘れられないだろう。この場所では多くの罪なきドワーフが、ただ自分の仕事をしていただけで命を落とした。君があの邪悪な生き物どもに下した報復で、奴らもKing Magniの臣民を再び襲う前に二の足を踏むはずだ。", 0x9f3d027d, 0x55a6e9a9, 0xb18d561a, 0xa3d83fdb, 0xdef3baa5, "....." },
  [297] = { "偶像集め", "Carved Stone Idolを8個、Magmar Fellhewのところへ持って行く。", "つい最近、Troggsが遺跡の中に現れる直前に、私たちは奇妙な彫刻の施された偶像を大量に掘り出していたんだ。だが研究する機会はなかった。見つけてすぐに、Troggsに遺跡から追い払われてしまったからね！ しかもあの偶像はTroggsに奇妙な影響を与えるんだ。奴らを狂暴にしてしまうんだよ！\n\n偶像を8個持ってきてくれ――研究したいし、Troggの手から取り上げたいんだ！ 偶像は遺跡に巣食うTroggsが持っているはずだ。", "あのIdolsは持っているか? それを調べて、分かったことをIronforgeに報告しなければならん!", "やったな! 見事だ、{name}!\n\nしかも、あの狂暴なTroggsがうろついているのに、大して傷ついてもいないようだ。君からは目を離さないでおこう……見込みがありそうだからな。", 0x34178260, 0x0eaf668c, 0xf3ba4390, 0x2fd4cc59, 0xd1d1aa18, "....." },
  [298] = { "発掘経過報告書", "ThelsamarでIronband's Progress ReportをJern Hornhelmに持って来てください。", "Thelsamarへ進捗報告を送らねばならん。進捗報告と、爆薬をもっと寄こせという要請の念押しだ！これが報告書だ。Jern Hornhelmに届けてくれ。Thelsamarでのわしらの窓口だ。\n\n難しい仕事ではないが、やらねばならんことだ。", "おお、現場からの進捗報告か? よくやった!", "ふん！IronbandはTroggsに手を焼いているのか。あの爆破火薬が欲しいのは採掘の助けにするためか、それともTroggの獣どもとの戦いの助けにするためか……\n\nまあ、どっちにしても有効に使われる火薬だ！\n\nだが妙なのは、何週間も前にたっぷり爆破火薬を送ってやったってことだ。一体どこへ行ったんだか……", 0xc9016865, 0x22803ca7, 0x4dd4de52, 0xe37dea91, 0x509d05e4, "....." },
  [299] = { "過去の発掘", "Prospector Whelgarは、発掘現場をくまなく探して、失われた$N1つの石板の欠片、Ados、Modr、Golm、Neruを見つけてほしいと言っています。", "侵攻の直前、私はGoaz Stoneと呼ばれる大きな石板を掘り当てたのです。翻訳した文は4か所で途切れています。文には「神の計画」と「破滅の予言」のことが書かれています。\n\n時間がなくなりつつあるのではと心配です。私は年を取りすぎて、下へ降りてあの獣たちに立ち向かうことはできません。でも、あなたは強い。\n\n発掘現場をくまなく探して、失われた4つの石板の欠片、Ados、Modr、Golm、Neruを見つけてください。古い遺物の中や、土が柔らかいところを探してみてください。私のところへ持ってきてくれれば、謎を解き始められます！", "4つの破片はもう見つけたか、{name}? Ados、Modr、Golm、そしてNeru……", "おお、Goaz Stoneが完成したぞ! 見事な仕事だ、{name}。実に見事だ。これでこのTitanの文字の繊細な解読を続けられる。もう新しい言葉が読み取れるぞ! ふむ……ここにはこう書いてある。「Old Gods……Beneath the Landに鎖で繋がれし」。これは壮大な何かの始まりだ。", 0xd591b8f3, 0xffdaf04c, 0xdce1b81f, 0x1bd68c28, 0x5c615bf5, "....." },
  [301] = { "Ironforgeに報告してください。", "Ironband's Progress ReportをProspector Stormpikeに持って行ってください。", "Ironbandにもっと爆薬を回すには承認が要る。IronforgeにあるExplorers' Leagueの本部へ、彼の報告書を届けてもらわねばならん。\n\nこれが報告書だ。Prospector Stormpikeに渡してくれ。渡したらすぐに身をかがめるのを忘れるなよ。Stormpikeは短気だから、現場でのIronbandの作業が遅れていると聞いたら機嫌を損ねるだろう。\n\nStormpikeならAssembly of Explorersにいる。", "我々Stormpikesは些細な用事で煩わされるのを好まんのだ、{class}。私の貴重な時間を割くに値する知らせを持ってきたのだろうな。", "いまいましいIronbandめ！何週間も前に爆破火薬を山ほど送ってやったのに、この報告書にはそのことがひとことも書かれていない。\n\nで……あの爆破火薬はどこへ行ったんだ？！？", 0x7f3b765a, 0x08c53212, 0xdc3ccebc, 0xd762c5af, 0x79fbe892, "....." },
  [302] = { "Ironbandへの粉", "ThelsamarでJern Hornhelmと話してください。", "Ironbandにまだ爆薬が要るなら、Magniに誓って用意してやる！承認はすでに使者に持たせて、ThelsamarのJern Hornhelmのもとへ先に送った。彼が爆薬やほかの物資を準備して、Ironbandのところへ運ぶ。\n\nそれともう一つ。爆薬の積荷が確実に目的地へ届くよう、君自身で見届けてほしい。前回のは届かなかったからな。気を引き締めて、目を光らせておけ。", nil, "何だと？Stormpikeが、Ironbandへの積荷を君自身に見届けてほしいと？\n\nまあ……それは構わんだろう。ただ一つ問題なのは、もうHuldarを荷運びのMiranとSaeanと一緒に送り出してしまったことだ。ちょうど入れ違いだな、ほんの少し前に出発したところだ。", 0xf6a7639f, 0x990221eb, 0x8208845e, nil, 0xe08e3029, "...m." },
  [303] = { "Dark Iron戦争", "Dun ModrのMotley Garmasonは、Dark Iron Dwarvesを$N1体、Dark Iron Tunnelersを$N2体、Dark Iron Saboteursを$N3体、Dark Iron Demolitionistsを$N4体倒してほしいと言っています。", "戦は故郷でも遠い地でも荒れ狂っている。勇ましいドワーフの兵たちがAllianceの名のもと遠方の地で命を捧げている間に、我らの土地はDark Iron Dwarvesの悪行の餌食となっている。奴らはThandol Spanを破壊した。まもなくDun Modrも陥落した。\n\n君には兵を集めて前線を押し戻してもらいたい。Dark Iron Dwarvesを15人、Tunnelersを5人、Saboteursを5人、Demolitionistsを5人倒せば、進撃をやり遂げる援軍が間に合うかもしれん。\n\nさあ、急げ！", "Roggoは予備部隊と連絡が取れずにいる。あのDark Ironの野営地に攻勢をかけ続けねばならん、{class}。さあ、戦場に戻ってKing Magniへの務めを果たせ!", "命令をよく守ってくれたな、{class}。お前は勇敢な兵士であり、King Magniへの忠実な臣下であることを証明した。そのことに敬礼する! お前がDark Ironの野営地に圧力をかけてくれたおかげで、奴らを我らの土地から永久に追い払える見込みが出てきた……いまいましい援軍さえ来てくれればな……", 0xb421cac2, 0x7d1d2a73, 0x6d3dee8c, 0xbeddfaae, 0xf0eb01de, "....." },
  [304] = { "陰惨な任務", "Balgaras the Foulを倒し、その耳をDun Modrの外にいるLongbraid the Grimのところへ持って行って下さい。", "Dun Modrの戦いで、わしの兵が大勢死んだ。わしの兄弟も、Thandol SpanにかかるWest Bridgeが破壊されたときに命を落とした。そうとも、Dark Ironのドワーフどもは悪魔のような連中だ。Roggoが集めた話では、Wetlandsにいるこのならず者どもの頭は、Balgaras the Foulという名のウォーロックだ。だが奴はとんだ臆病者でな。手下に命令を実行させて、自分は危険を避けて姿をくらましている。\n\nあの腰抜けを見つけ出したら、仕留めて耳を持ってきてくれ。褒美をやろう、{class}。", "Balgaras the Foulはもう見つけたか、{class}? 奴にはずいぶん長いこと逃げられているのだ。", "Balgaras the Foulがついに死んだ。奴の手で無意味に死んでいった多くの罪なきドワーフが戻ってくるわけではないが、生き延びた者たちの心の平穏を取り戻す助けにはなるだろう。Balgarasが死んだ今、残りのDark Ironのクズどもは容易に片付けられるはずだ。さあ、新たな指導者がこの地に送り込まれる前に、奴らを一掃しなければならん。\n\nよくやったぞ、{class}。", 0x0abbedc6, 0x9ddb772b, 0x57aeb2ff, 0xe02c98c7, 0x8ca97064, "....." },
  [305] = { "発掘隊を探して", "Tarrel Rockweaverは、Excavation Siteへ行ってMerrin Rockweaverと接触してほしいと言っています。", "私がどれほど心配していたか、想像もつかないだろう。\n\n妻のMerrinは、この一か月、毎週手紙を送ってきていた。彼女はWhelgar Excavationの隊の一員なんだ。だが、最後の便りからもう2週間近くになる。きっと何かあったに違いない!\n\nLongbraidは、もしすぐに隊から連絡がなければ様子を見に斥候を送ると言っていた。その斥候がお前なんだな、{name}。東の発掘現場でMerrinを見つけてくれ!", nil, "ああ、ありがたい、来てくれたんですね!", 0x1719a646, 0x2d2e1e26, 0x39755cdf, nil, 0xe6062395, "...m." },
  [306] = { "発掘隊を探して", "Merrinのメモを持ってTarrel Rockweaverのところへ戻って下さい。", "恐ろしかったわ！珍しい遺物を掘り出していたら、大きな骨が見つかり始めたの。\n\n何が起きているのか分からないうちに、このMottled Raptorsが発掘現場に押し寄せてきたのよ。大勢の命が失われたわ。\n\nここにいるOrmerが――とても勇敢に――探鉱者と私を救ってくれたの。私たちが避難所へ逃げる間、守ってくれたのよ。今は閉じ込められていて、苦労して進めた仕事も台無し。\n\nほら、このメモを私の愛しいTarrelのところへ持っていって。事情を説明してくれるはずよ。", "Merrinは見つかったか? 彼女から知らせはあったか?", "なんてひどい知らせだ! 少なくとも3人は生き延びたが。だが、殺し合いはいつになったら終わるんだ? King Magniの臣民が恐れずに暮らせる日を待ち望んでいるよ。", 0x1ca7050f, 0x8401118b, 0x88a97402, 0x78ff4985, 0x07626a00, "....." },
  [307] = { "汚らわしい足", "Silver Stream Mineへ行き、Miners' Gearを4荷集める。\n\nMountaineer Stormpikeのところへ戻る。", "東のSilver Stream Mineはずっと前に掘り尽くされた。Miners' Leagueが倉庫に改装したんだが、今ではKoboldsが入り込んで、立派なドワーフの道具に汚い手をかけてやがる！\n\nあの害獣どもはすぐに叩き出してやるが、Leagueは、我々ウォリアーが乗り込んで物を壊す前に、誰かに鉱山から道具を運び出してほしいそうだ。厳しい探索になるぞ――仲間を連れていったほうがいいかもしれん。\n\n道具は鉱山のあちこちにあるMiners' League Cratesにしまってある。幸運を祈る。", "Miners' Gearは持っているか、{name}?", "中でKoboldsをたくさん見たかい? 鉱山から奴らを一掃する命令が待ち遠しいよ。あいつらの汚い手が俺たちの鉱山を引っかき回していると思うと、胸がむかむかする!", 0xe6dfbab1, 0x6239462b, 0x8b70f766, 0x83e3d7a0, 0x6be768cd, "....." },
  [308] = { "Jarvenは集中できない", nil, nil, "ふん! ここには酒がこんなにあるってのに、手を付けるなと厳しく命じられているんだ。うちのThunder Aleを一口でも味わえたらなあ……頭が冴えるのは間違いないんだが!", "俺に？あなたこそ、真の英雄です, {name}!", 0xef7d7727, nil, nil, 0xd7c692ec, 0xe0ee940d, ".mm.." },
  [309] = { "積荷の護衛", "Miranと積荷が無事に発掘現場へ着くよう見届け、それからProspector Ironbandに知らせて下さい。", "出発の準備はいいか、{name}？\n\nまずは、この火薬をIronbandのところへ届けなきゃならない。私一人で運ぶには多すぎるし、このあたりは危険なこともある――それに、Dark Ironsが私に何を仕掛けてくるか分かったもんじゃない。\n\nお前が一緒に来てくれれば、ずっと心強いよ。", "私の粉はどこだ、{name}? 日に日に切羽詰まってきているのだ。", "ああ、光に感謝を、火薬が届いた。だが君が持ってきた知らせは厄介でもある。Dark Ironsが卑劣な計画のためにこの種の材料を調達できる共鳴者を抱えているとはな。\n\nそれは誰か他の者が、いずれ別のときに考えるべきことだ。私はこの火薬を有効に使わねばならん。", 0x086b0483, 0xbcb09af3, 0xaf7d4d4e, 0xcad7bca5, 0x0c439c60, "....." },
  [310] = { "怒れる競争相手", "KharanosのThunderbrew Distilleryの地下室で、barrel of Thunder AleとBarrel of Barleybrew Scalderをすりかえろ。", "認めるしかないが、Thunderbrewsの連中はいい酒を造る。だが、まともな酒は自分たちのだけじゃないってことを思い知らせてやらなきゃな。その教訓を叩き込むのを手伝ってくれないか……\n\nほら、このBarleybrew Scalderの樽を持っていけ。KharanosのThunderbrew Distilleryの地下室に忍び込んで、奴らのThunder Aleの樽の1つとすり替えるんだ。そうすりゃ、客が奴らの酒より俺の酒を気に入るかどうか分かるってもんだ！\n\nそれに樽に見張りがいたら、衛兵の気をそらす必要があるかもしれんぞ……", "この樽の日付からすると、もうすぐ栓が開けられるようだ。", "Thunderbrewの樽の間にMarlethのBarleybrew Scalderの樽を素早く置いてきてくれたようだな。", 0xf6727a81, 0x0eee3138, 0x4aba5129, 0x1e29e7f1, 0x61e614ef, "....." },
  [311] = { "Marlethのもとへ", "Brewnall VillageにいるMarleth Barleybrewにbarrel of Thunder Aleを渡せ。", "Kharanos Distilleryの地下貯蔵庫にMarleth's Scalderの樽を仕込んだあなたは、その行いの証拠としてThunder Aleの樽をつかみ取った……", "すり替えはうまくいったか?", "悪くないな, {name}! ガードをやり過ごすには苦労しただろ？\n\nとにかく、大いに感謝するよ、これからはガツンと来る酒が欲しくなったら、Barleybrewを忘れるなよ！", 0x3a28c9e8, 0xf80b297f, 0x6e9701ee, 0x31a1b899, 0x1b072cf7, "....." },
  [312] = { "Tundra MacGrannの盗まれた隠し財産", "Old Icebeardの洞窟にある盗まれた肉の貯蔵庫から、Tundra MacGrannの干し肉を取り戻す。", "寒い季節に備えて、一か月分の干し肉を塩漬けにしてしまい込んでおいたんだ。熊に取られないよう鍵をかけてな！ ところが俺が鹿を狩りに出ている間に、あの獣、Old Icebeardが肉の保管箱を持ち去りやがった。あのThoriumを叩き壊すことはできないだろうがな。だが肉を取り戻せなけりゃ、俺は飢え死にしちまう。\n\nあんたは俺よりちっとばかり忍び足が得意そうだ。俺の蓄えを取り戻してくれないか？ この悪い脚じゃ、あの洞窟に素早く出入りするなんてとても無理だ。", "私の肉の貯蔵庫には入れたか、{name}?", "なんて親切な人なんだ、{name}! 君の勇敢さのおかげで、寒い季節の吹雪がやってきても飢えずに済むよ。", 0x992959f9, 0x5b0707e1, 0xa3f43510, 0x754c3b09, 0xd5b6ac1e, "....." },
  [313] = { "Grizzled Den", "Wendigo Manesを$N1個集めて、Pilot Stonegearのところへ持って行って下さい。", "Siege Engineの運転は誰にでもできるもんじゃない。鉄の握力と鋼の神経が要る……運よく私には両方ある！ お前はどうだ？ 根性はあるか？ 私に証明してみたいか？\n\nそれでな……私の機体、Trollplowをもう少し居心地よくしたいと思ってるんだ。Kharanosの西にあるGrizzled Denから、Wendigo Manesをどっさり取ってきてくれないか。あのmanesならTrollplowの内側のデッキにぴったりの敷物になる！", "やあ、{name}。Grizzled Denにはもう行ったか? あのWendigosは獰猛だからな。", "ああ、このたてがみなら申し分ない！なかなか根性があるな、{class}——お前からは大きなものが見られると賭けてもいい。", 0x9d1372af, 0x4e894b7e, 0xac88ca21, 0xb2b8b4b1, 0x6f400b46, "....." },
  [314] = { "群れの保護", "Vagashを倒して、その牙をRamの牧場にいる彼女のところまで持ってきてほしいとRudra Amberstillは言っています。", "真夜中に悲鳴が聞こえたんだ。そして今朝、案の定、群れから雄羊が二頭いなくなっていた。Vagashとして知られるあの卑劣な獣が、我々の暮らしの糧を食い物にしている。King Magniの軍の大半はAllianceと共に遠い地で戦っているから、Vagashを寄せつけずにおける者が誰もいないんだ。\n\nお前なら、その獣を探し出して仕留めるだけの勇気があるかもしれない。奴の牙を一本持ってきてくれたら報酬を出そう。Vagashはこの牧場のすぐ上をうろついているが、気をつけろ、奴は命取りになるほど危険だ。", "Vagashは今も群れを脅かしています! どうか、あの忌まわしい獣を倒して私たちを助けてください。", "本当によくやってくれたよ! Veron が聞いたらとっても喜ぶよ。Vagash を殺すのは楽じゃない。いつかあんたは King Magniの兵士と一緒に Alliance の前線で戦うことになるんじゃないかな。", 0xefa031f4, 0x2475a572, 0x9f0339dd, 0xf712a472, 0x3bc82f3e, "....." },
  [315] = { "完全な酒", "Brewnall VillageのRejold BarleybrewにShimmerweed 6本を渡して下さい。", "私は探求の最中なんだ。完璧なスタウトを作るという探求のな。きっとできる――醸造の血が流れてるからな。あとは正しいレシピを見つけるだけだ……\n\nFrostmaneのトロールどもは、東の丘の高いところでshimmerweedという植物を育てている。奴らはそれを奇妙な部族の儀式に使うんだ。我々ドワーフはあまり使い道を見つけていないが、独特の味があってな……それを私の醸造で試してみたいんだ！\n\nFrostmane seersからshimmerweedを手に入れてくるか、トロールどものshimmerweedの籠からくすねてきてくれ。", "shimmerweedは持ってきたか? もうすぐスタウトの仕込みができそうでね、その草をこの混ぜ物に入れてみたいんだ。", "やった! 俺のレシピに使うのが待ちきれないよ。格別うまく効果の出そうなレシピがあるんだ……。", 0xadc5e20f, 0xfc736db3, 0x4c0b4974, 0xc1da3265, 0x068f94a8, "....." },
  [317] = { "Jetsteamの在庫", "Steelgrill's DepotにいるPilot Bellowfizに4枚のChunks of Boar Meatと2枚のThick Bear Fursを届けろ。", "俺はSiege Brigadeの任務を始める準備をしてるんだ。長くかかりそうな任務なので、Jetsteamに１ヶ月分の物資を積んでおく必要があるんだ。Steelgrillが俺のマシンを整備している間に、ちょっとした狩りをしてくれないか？\n\n寝る時に毛皮と食料のイノシシ肉が必要だ。肉はイノシシから、毛皮は熊から取れるぞ、両方ともGrizzled Denの南の雪原にいるよ。", "準備は順調だ。狩りのほうはどうだ?", "Magniの髭にかけて、ずいぶんたくさん狩ってきたな!! ありがとう、{name}。", 0x9298abb1, 0x763455c2, 0x6304c52d, 0xf79f8e14, 0xf15f9d6d, "....." },
  [318] = { "Evershine", "Brewnall VillageにいるRejold BarleybrewからEvershineの樽をもらってきてくれ。", "Rejold Barleybrewは酒の実験をしていてな。うまいのもあれば、まずいのもある。それから……まあ、よほど頑丈なドワーフでもなければぶっ倒れるようなのもある。\n\n彼はKharanosの西、Brewnall Villageに住んでいる。あいつの酒の一つ、Evershineが欲しいんだ。寒い道中で体を温めてくれるからな。\n\nそれに……あのありがたい代物はものすごく熱く燃えるから、Jetsteamのかまどに放り込めば一気に力が出るんだ！この手のおかげで窮地を抜け出したことは、一度や二度じゃない。", nil, "BellowfizがEvershineを欲しがってるって？ふ〜ん・・・いいだろう。", 0xab586d5c, 0xcb9ca884, 0x9b9623a7, nil, 0x0bdd12f0, "...m." },
  [319] = { "Evershineの世話", "Ice Claw Bearを6匹、Elder Crag BoarとSnow Leopardを8匹ずつ殺したら、Brewnall VillageにいるRejold Barleybrewに報告に戻れ。", "おいらはEvershineの樽を重宝してるんだがね・・・でもな、俺の頼みを聞いちゃくれないか？Brewnall villageは近くの雪原をうろつく野生動物に手を焼いてるんだ。ちょくちょく、奴らは近くまで来てうろついてるんだよな。\n\n俺たちは熊や猫や猪なんかを怖がっちゃいないぜ、自尊心のあるドワーフならなおさらだ。−でも俺たちの代わりに奴ら動物の始末をつけてくれるんなら、俺たちが物を作ったり、酒を醸造したりする時間がもっと持てるんだがな。", "あの野生の獣たちは片付けてくれたか?", "ありがとう, {name}. 村の外からのうなり声や鳴き声に悩ませられずに物を作れるなんてうれしいよ。", 0x46ebb913, 0xe3630b84, 0xe551b5b9, 0x8630896b, 0x1e4bad26, "....." },
  [320] = { "Bellowfizへの帰還", "cask of EvershineをSteelgrill's DepotにいるPilot Bellowfizに渡せ。", "君のEvershineの樽だ, {name}. そしてもう一度言おう、さっきは狩りをしてくれて、ありがとう。", "Evershineは手に入ったか?", "そう、これがいいんだ。今すぐ一本開けて、味見してみるとしよう・・・", 0xb3dbad35, 0x289b7cd5, 0x0fbc74dc, 0x8ef21aef, 0xf157f980, "....." },
  [321] = { "Lightforge Iron", "WetlandsでThe Flying Ospreyの漂着物を探して下さい。", "この沖の難破船は、Kul'Tirasの悲運のThird Fleetだ。前のGreat Warのときに、Red Dragonsに焼かれて沈められた。\n\n艦隊はLordaeronから来たものだが、一隻だけ、Elvish DestroyerのFlying Ospreyが同行していた。その船はLightforge Ironを積んでいて、守ってもらうためにThird Fleetに加わっていたんだ。皮肉なことに、同じdragonsに沈められちまったがな……\n\n歴史はこれくらいにしよう。Flying OspreyはMenethil Harborの南で難破している。そこでLightforge Ironを見つけたら、俺のところへ持ってきてくれ。", nil, "この箱は水浸しで、側板が壊れている。内側にも外側にも多くの爪痕が刻まれ……まるでMurlocが中を漁って宝を盗んでいったかのようだ。\n\nだが箱の奥深くに、Lightforge Ingotがただ一つ押し込まれている。残念ながら、武器を作るだけの金属を得るには、さらに多くが必要になるだろう。", 0x2c43f553, 0x90913df9, 0x4f73f4fe, nil, 0x43d7effb, "...m." },
  [322] = { "祝福された武器", "Crate of Lightforge IngotsをStormwindのGrimand Elmoreのところへ運んで下さい。", "StormwindのDwarven Districtに、lightforge ironを扱えるドワーフの武器職人がいる。名前はGrimand Elmoreだ。\n\n君が見つけた鉄は木箱に詰めておいた。それをGrimandのところへ持っていって、君の話を聞かせてやってくれ。君のようなクエストに挑む者なら、きっと快く武器を作ってくれるはずだ。Morbent Felでさえ恐れをなすような武器をな！", "私の技で何をして差し上げましょうか、{class}?", "大した話だな。それにlightforgeの鉄とは！こんな金属を扱うのは何年ぶりだろう。再びこれで鍛えられるのは名誉なことだ。それに、Necromancerとの戦いの話を持って、後でまた私のところへ来てくれ。\n\nだが先走りすぎたな。まずは、Morbent Felに立ち向かうための武器だ……", 0xc00e26ec, 0xfe21b562, 0x8155f944, 0xbc274cdc, 0xcdab21ec, "....." },
  [323] = { "真価の証明", "Skeletal Raider 15体・Skeletal Healer 3体・Skeletal Warder 3体を殺し、Svenのところへ戻って下さい。", "Morbent Felは死霊術師で、dark ridersの味方だ。君をMorbent Felの力に立ち向かわせるつもりではいるが、まず君の力を知らないうちは、あの卑劣な悪鬼のもとへ送り出すわけにはいかない。\n\n君はすでに私に勇気を示してくれた。だが本当にあの死霊術師と対決したいなら、今度は奴の手下を相手に腕前を証明してもらわねばならない。", "激しく戦うのです、{name}。そして絶望してはなりません。絶望こそ悪の最大の武器なのですから。", "{name}、君の戦いの腕前は本物だ。その決意がいずれ、Morbent Felの終わりを見せてくれるかもしれないな!", 0x2b69e0a3, 0xe93db108, 0xa4fe1361, 0x3028a831, 0x850f6fbf, "....." },
  [324] = { "失われた延べ棒", "Lightforge Ingot 5本を集め、WetlandsのGlorin Steelbrowのところへ持ち帰って下さい。", "水浸しの箱からlightforgeの延べ棒1本を手に入れたが、残りはmurlocが盗んだことは明らかだ。失われたlightforge ironを手に入れるため、Flying Ospreyの残骸の近くにいるmurloc raiderを狩らねばならない。", "必要なlightforge ironは見つかったか?", "ああ、見つけたのですね! それではlightforge ironを何か役立つものに変えましょうかね。", 0xbad55a3a, 0x3e3da78f, 0x3c29b98a, 0x0a6e75bf, 0x67c1cb55, "....." },
  [325] = { "武装準備", "DuskwoodにいるSvenのところへMorbent's Baneを持って行って下さい。", "これがあんたの話してた悪魔と戦う武器だ。準備万端だな、{name}。最高の運がありますように。それと、栄光の物語を期待して待ってるぞ!", "こんにちは、{name}。それほど長く離れていたわけではないのに、あなたの目には以前にはなかった炎が見えます。", "おお、これなら悪魔Morbent Felと戦えるよ! よくやったじゃないか!\n\nこれでいける。 Morbent Felを倒せるぞ。", 0x87f2ec41, 0xcc976788, 0xd24c2a78, 0xc11cc698, 0xad511684, "....." },
  [328] = { "隠された鍵", "Small Brass Keyを使ってBookie Herod's Strongboxを開けて下さい。", "この記録にはPrivate Thorsenについての記述は見当たらないが、Herodの帳簿の一冊の綴じ目に、small brass keyが隠されていた。\n\nさらにメモを調べると、いくつかの書類の中に「安全な金庫」についての記述がいくつかある。その箱はStockpile――Kurzen's Compoundの奥にある洞窟群――のどこかにある。\n\nこの安全な金庫を見つけ、small brass keyで開けられれば、Thorsenが見破られた謎が明らかになるかもしれない。", "その金庫は青銅で縁取られていて、とても頑丈で、とても重い。", "金庫を開けると、ここがHerodのより価値のある硬貨や品をしまっている場所だとはっきり分かる。", 0xa8d050ae, 0x27bc2b46, 0xc46230ef, 0x1a43bf0a, 0xe9420d9a, "....." },
  [329] = { "スパイの正体！", "Muddy NoteをRebel CampのLieutenant Dorenのところへ持って行って下さい。", "金庫の貴重品の中に、泥だらけの走り書きのメモがある。ほとんど読めないが、Private Thorsenの行動予定表のようだ。巡回ルート、話す相手、反乱軍の中での過ごし方が細かく書かれている。署名はたった一文字、「-M」だけだ。\n\nだが、このメモを書いた者は、Thorsenのすぐそばにいたに違いない。このメモを書いた者こそ、反乱軍の野営地にいる裏切り者だ。", "Thorsenの秘密を知っていた者は分かったか? 我々の中に裏切り者がいるのか?", "ありがとう、{name}。このメモこそ、裏切り者をあぶり出すのに必要な手がかりだ!", 0x3d1496d3, 0x39422362, 0x1f940b92, 0x2b8070c0, 0x852bd824, "....." },
  [330] = { "巡回の予定表", "Corporal Sethmanと話して下さい。", "君がくれたメモには「-M」と署名されている……それが何を意味するのか、私には分からない。\n\nだが……メモには、この人物が先週Thorsenと巡回ルートを共にしたとも書いてある。つまり、先週Thorsenと巡回を共にした者が裏切り者に違いない！\n\nCorporal Sethmanのところへ行け。彼が巡回の予定を管理しているから、Thorsenと一緒だったのが誰か教えてくれるだろう。", nil, "ああ、それなら調べられるよ。ええと……先週は……\n\n……おや、Private MerleがThorsenと組んでいたね。先週はずっと同じ巡回時間だった。", 0x20635c9f, 0xe0dd4140, 0xf3194e63, nil, 0x8fc4394c, "...m." },
  [331] = { "Dorenへの報告", "Lieutenant Dorenと話して下さい。", "Lieutenant Dorenは、その巡回の情報を持って報告に戻ってこいと君に言ったのか？", nil, "Merleが我々を裏切っていたと知るのはつらい。彼はいつも勇敢な兵士で、真心のある男だと思っていた。だが、奴を見つけ出せたのは大きな安心だ。あんな間者が我々の中にいては……Colonel Kurzen相手に長くはもたなかっただろう。", 0x31f00bd6, 0xe0bc401a, 0x963e63fd, nil, 0x34f838e0, "...m." },
  [332] = { "ワインショップの宣伝", "Gallina WineryにいるSuzetta Gallinaに、無料ワイン一本と交換できるWine Ticketを持っていく。", "お前さんがワインについて語りたいなら、ここStormwindで最高のワインを扱っている、Gallinaワインショップを紹介するぜ。ここからそう遠くないTrade District内の運河沿いにあるワインショップだから、寄ってみるといい。\n\nほらよ、このパンフレットを持っていけ。妹のSuzettaにこれを渡せば、無料で最高のピノノワールワインをもらえるぜ。ウソだと思って飲んでみてくれや！", "ようこそいらっしゃいました、お客様。当店自慢のワインはもうお試しになりましたか?", "あら、Renatoと会ったのね。はい、このワインがそうよ。特別なピノノワールワインだから、Azeroth中駆け回っても、これよりいいワインはないわよ。", 0xbef51e47, 0xa087845e, 0x1a55a490, 0x057eda77, 0xb3727db1, ".....", nil, nil, nil, 0x894606fa, 0xbccda04d },
  [333] = { "追加発注品を待つHarlan", "Canal Tailor Shopに行き、そこにいるRema SchneiderにCloth Requestを持っていく。", "最近本当に忙しいんです。ここの人達みんなが、防具や衣類を買っていってるような忙しさでして、まるでみんながみんな寒い季節対策をしているかのようなんですよ。\n\nでもそんな未来の心配なんて私達には関係なくてですね、問題は売り物の編み物類が不足していることなんです。業者さんからの追加の荷物を待っている状況なんですよ。\n\nもしよろしければ、この発注書を Canal Tailor and Fit ShopにいるRema Schneiderに届けてくれませんか？もちろん報酬はきちんと用意いたします。", "Mr. Bagleyからの伝言を持ってきたのかい?", "Harlanの店が繁盛しているのはとても良いことですね。それにしてもどうしてみんなそんなに防具を欲しがるのでしょう。開戦の話なんて何も聞いていないし…。貴族達が何か隠しているとか？\n\nそれはさておき、発注書を届けて頂き、ありがとうございます。これが報酬です。さてと、Harlanの発注品の準備を始めましょうか。", 0xb45daef4, 0xe2e2a078, 0x90d86eed, 0xacbdeec7, 0x6c92f110, "....." },
  [334] = { "Thurmanへの小包", "StormwindのMage QuarterにあるLarson Clothiersで働いているThurman Schneiderに、Sewing Kitを届ける。", "息子のThurmanはMage's QuarterにあるLarson Clothiersで見習いとして働いているんだ。あいつは今日、急いで出たもんだから、ハサミと針を忘れていったんだよ。あんたのようなすごい{class}なら、常に重要な任務に就いていることは分かるんだが、この道具なしではあいつは仕事はできないんだよ。\n\n{name}さんよ、頼まれてくれないかな。このsewing kitを息子に届けてやってくれないか？Larson ClothiersはMage's Quarterに２つある衣服店の一つで、Mage's Towerの近くにあるんだよ。", "服を買いに来たのかい?", "ああ、しまった！道具一式を忘れれば仕事から逃れられると思ったのに。こうなったら、Larsonsの縫い物を手伝わなきゃならないんだろうな……\n\nまあ、いいか。お楽しみは後回しだな。", 0x2f63edc3, 0x271cf18d, 0xdd0e9c55, 0x50590106, 0x82df6d32, "....." },
  [335] = { "極上の酒", "Wetlands で Musquash Root を手に入れ、Darkshire で Tear of Tilloa を手に入れて持ってくるよう Zardeth the Black Claw は求めています。", "Lord Wishockが House of Nobles に騒動を引き起こしている。我々のささやかな「機関」のことを知り、全面調査を訴えてロビー活動をしているのだ。Lord Wishockを「虜にする」策があるのだが、それには君の協力が必要となろう。\n\nDarkshire 郊外の Garden of Stalvan に生えている花があるのだが、その小さな白い花は Tear of Tilloa として知られている。それから、Wetlands にある Stonewrought Dam の遙か下の滝壺にだけ生える Musquash Root も必要だ。", "Wishockはまもなく、我々を大いに苦しめるだけの支持を集めるだろう。Tear of TilloaかMusquash Rootはもう手に入ったか?", "素晴らしい! 実に上質なサンプルだ!", 0xb74eb85e, 0x62942fae, 0xe7ffff8f, 0xcd7a22de, 0x7e0ff13b, "....." },
  [336] = { "極上の酒", "Hall of Petitioners にいる Lord Wishock に Black Claw Stout を渡す。", "Lord Wishockにも、誰もがそうであるように弱点がある。やつの場合、それは酒好きってことだ。まったく呆れた偽善だよ。あの陳腐な愚か者は、昼間は我々のささやかな「酒場」を潰そうと躍起になっているくせに、夜は二階で過ごして、一度も払ったことのないツケを溜め込んでいるんだ。さて、私がやつのために用意したこの特製の酒、Black Claw stoutをWishockがどう気に入るか見てみようじゃないか。こいつはなかなか効くぞ、{name}。\n\nやつに持って行って、どう気に入るか見てきてくれ。どうせあの老いぼれは、Hall of Petitionersあたりをうろうろしているだろう。", "私が忙しいのが分からんのか? 私の言葉は聞かれねばならんのだ! 私はこの王国の未来にとって非常に重要な人物なのだぞ!\n\nおや……何を持っているのだ? なんと、爽やかな飲み物のようではないか……", "ああ、こんなに素晴らしい黒ビールを持ってきてくれてご苦労だったな。これは駄賃だ。さてと、下がってくれ。酒を楽しむとしようかね!", 0xb74eb85e, 0x53f90ba6, 0xda7b4013, 0x1b629e3f, 0x43acc741, "....." },
  [337] = { "An Old History Book", "この本「The History of Stormwind」をStormwind Libraryに返却して下さい。", "この本の表紙は引っかき傷だらけで泥がこびりついているが、背には「The History of Stormwind」という文字がまだ読み取れる。本を開くと、最初のページにはStormwind Libraryの印がはっきりと押されている。\n\n誰かがこの本を借り出して、そのまま返さなかったようだ……", "わあ! その古い本は何? 見せてもらえる??", "まあ！この本がこの棚に収まっていたのは、何年も前、Stormwindの再建より前のことです。もちろん修復は必要ですし、状態はひどいものですが、稀覯本の蔵書に加えられるなら光栄です。\n\nありがとうございます、貴殿。本を返してくださったお礼として、これをお受け取りください！", 0x71dc094a, 0x1883e731, 0x53cae2d4, 0xf9cb11cb, 0x48ec99b2, ".....", nil, nil, nil, nil, 0x26f2965a },
  [338] = { "Green Hills of Stranglethorn", "The Green Hills of Stranglethornの原稿から失われたページを集める。四つの章がすべて揃ったら、Barnilのところへ持ち帰って下さい。", "Master Nesingwaryに知られたら、ひどく怒られちまう！\n\nあの人の小説、The Green Hills of Stranglethornの原稿の校正を任されてたんだ。順調だったのに、強い風が野営地を吹き抜けて、ページがあちこちに散らばっちまったんだよ！\n\nほとんどのページは集められたけど、まだたくさんジャングルに散らばってる。ページを集めて、四つの章をそれぞれ完成させてくれ。\n\n整理するのは手伝うよ。四つの章が全部そろったら、持ってきてくれ。", "もう章はまとめられたか、{name}?", "ずいぶん手間を省いてもらったよ、{name}! 感謝してもしきれない。もうすぐMaster Nesingwaryの本が世界中の図書館に並ぶはずだ!", 0xc9b44ad6, 0x32ef68a0, 0xb1a2389e, 0x7fdaf3b2, 0x8d566bd0, "....." },
  [339] = { "第I章", "NesingwaryのThe Green Hills of Stranglethornの$N1、$N2、$N3、$N4ページをBarnil Stonepotのところへ持って行き、Chapter Iを完成させて下さい。", "Chapter Iはすごく面白かったよ！Master Nesingwaryは物語の舞台を描いて、狩りの仲間のことにも触れてるんだ。俺のこともね！\n\nでも、それは置いといて。まだ足りないページを確かめさせてくれ。1ページ、4ページ、6ページ、8ページが、まだジャングルのどこかにあるみたいだ！", "1、4、6、8ページはさすがに見つからなかっただろうね? Chapter Iを元どおりにするには、その4ページさえあればいいんだが。", "ついに! Chapter Iが完成した!", 0x2c4d1328, 0x1facd88f, 0x644e06c1, 0xee84687b, 0xc9405d34, "....." },
  [340] = { "第II章", "NesingwaryのThe Green Hills of Stranglethornの$N1、$N2、$N3、$N4ページをBarnil Stonepotのところへ持って行き、Chapter IIを完成させて下さい。", "Chapter IIは、豹と虎の狩りのわくわくする話でいっぱいだったよ。ページを飛ばしちまった自分を蹴飛ばしたいくらいだ！\n\n10ページ、11ページ、14ページ、16ページ以外は、全部取り戻せたみたいだね。", "Chapter IIを完成させるには、まだ10、11、14、16ページが必要だ、{name}。", "Chapter IIがようやく完成した! よくやった!", 0xab70ce2f, 0x2f0a8679, 0xf9ff4802, 0x5ba6f5a9, 0x9b87a1f7, "....." },
  [341] = { "第III章", "NesingwaryのThe Green Hills of Stranglethornの18、20、二十一、24ページをBarnil Stonepotのところへ持って行き、Chapter IIIを完成させる。", "Chapter IIIが一番のお気に入りさ。Sir ErlgadinとLady Rouackが、ドワーフのライフルで初めて獲物を仕留める話なんだ。それにChapter IIIの結末ときたら、そりゃもう、はらはらする終わり方なんだよ！\n\nこの章を仕上げるには、まだ18ページ、20ページ、21ページ、24ページが要るみたいだ。そのページはどこかにあるはずだよ……", "18、20、21、24ページは見つかったかい? Chapter IIIをまとめるのに必要なのはそれだけなんだ。", "ふう! よくやった、{name}。Chapter IIIがまたひとつにまとまった!", 0xbab98409, 0xe953198b, 0x51269746, 0x2095bccb, 0x117ee17a, "....." },
  [342] = { "第IV章", "NesingwaryのThe Green Hills of Stranglethornの$N1、$N2、$N3ページをBarnil Stonepotのところへ持って行き、Chapter IVを完成させて下さい。", "ああ、Chapter IV、大団円だ！なんて結末だったことか！\n\nこの章で足りないのは、あと三ページだけだ。Chapter IVを元どおりにするには、25ページ、26ページ、27ページが要るんだ。", "Chapter IVを仕上げるのにあと3ページあればいいんだ、{name}。25、26、27ページはもう手に入れたかい?", "素晴らしい! これでChapter IVの準備が整った!", 0xab70ce3c, 0x897c0131, 0xea85bb72, 0x4f1f20fc, 0x4037d4e8, "....." },
  [343] = { "Fortitudeについて", "Stormwind KeepのRoyal Libraryへ行き、Milton Sheafと話す。Brother Kristoffの講演に必要な冶金学の本を、彼が見つけてくれる。", "私はFortitude of the Spiritについて講演をするのですが、冶金学に関するある本――「The Stresses of Iron」――の一節を引用したいのです。この本の写本がStormwind Keepの中にあるRoyal Libraryにあるはずです。取ってきていただけますか？ もしそうしてくださるなら、光の祝福があなたと共にありますように！\n\nRoyal Libraryはとても広いのですが、図書館長のMilton Sheafは、どの棚も我が子のようによく知っています。彼に話しかければ、本を取ってきてくれるでしょう。", nil, "冶金学ですか? ええ、その分野の本ならたくさんありますし、Brother Kristoffの講演のお手伝いができるなら喜んで! さて……その善き修道士が必要としていたのは、どの本でしたか?", 0x2aad28e2, 0x5b41f90b, 0xdb30b559, nil, 0xcfbcf25b, "...m." },
  [344] = { "Brother Paxton", "Northshire AbbeyのBrother Paxtonと話す。", "The Stresses of Ironですか？ ええ、その本なら知っていますよ。なかなかの良書で、数十年前にドワーフの鉱夫Margulf Blaggonが書いたものです。彼はほとんどの時間をKhaz Modanの山奥で鉱石を掘って過ごしました。賢い人物ですよ！\n\nええと、何の話でしたっけ？ ああそうそう、Stresses of Ironでした！ 残念ながら、その本はNorthshire Abbeyへ移されてしまいました。Abbeyの図書室の管理人、Brother Paxtonが、自分の書棚用に写本を作りたがったのです。\n\nでも、それはもう何か月も前のことです。どうしてこんなに時間がかかっているのでしょうね……", nil, "Mr. Sheafが本の行方を気にしているのですか? これは少々ばつが悪いですね。本は私が持っているのですが、まだ写本を作っている最中で、原本を手放す準備ができていないんです!", 0x757cdd99, 0xed902b3e, 0x5c81c1f5, nil, 0x65a09975, "...m." },
  [345] = { "インクの補充", "LakeshireのForeman Oslowと話し、Rethban Iron Oreを分けてもらう。", "The Stresses of Ironの写本を仕上げようと思っていたのですが……\n\n実はですね、私は写本に使うインクを自分で作っているんです。私独自の調合で、にじまず、汚れず、とても早く乾くのです。ところが困ったことに、早く乾きすぎるんですよ！ 前回作った分は写本を終える前に乾いてしまい、新しいインクを作る機会もないままなのです！\n\nもっと作るには、Redridge MountainsのRethban Iron Oreが必要です。いつもはLakeshireのForeman Oslowから仕入れています。", nil, "何が要るだと?? 気づいていないかもしれんが、俺たちはLakeshireの防備を固めたり、最近のオークの襲撃でやられた箇所を修理したりで忙しいんだ。Rethban Iron Oreが要るなら、自分で取ってくるんだな!", 0x6436fa89, 0x9f82018f, 0xf8e115c5, nil, 0x6eaa5bf6, "...m." },
  [346] = { "Kristoffのもとへ戻る", "Cathedral SquareのBrother Kristoffのところへ戻り、The Stresses of Ironという本を渡して下さい。", "本の書き写しが終わったから、これがStresses of Ironの原本だよ。辛抱強く待ってくれてありがとう。Miltonに会ったら、長く待たせてすまなかったと伝えておくれ。", "本は見つかったか?", "それです! ありがとうございます、{name}。光があなたの体と魂の両方を明るく照らしますように!", 0x7914bcc7, 0xaffc7d2d, 0xa9d0a831, 0xf44efc87, 0xcfcb4f09, "....." },
  [347] = { "Rethban Ore", "Rethban Oreを5荷集め、Northshire LibraryのBrother Paxtonのところへ持って行く。", "Rethban Oreは、最初に見つけた男、Bart Rethbanにちなんで名付けられた。精錬しても鉄ほどの強度はないが、その鉱石は暗く、くすんだ色をしていて、染料に使う写字生もいる。ここから北のRethban Cavernsで採れる。\n\nいつもならいくらか在庫があるんだが、今はオークの襲撃に備えるのに忙しくて、集める暇がない。それに……今じゃRethban CavernsにはRedridge Gnollsが住みついていて、奴らのDrudgersが自分たちで鉱石を集めているんだ。\n\nだから必要なら、自分で取ってくるしかないな。", "Rethban Oreは持っているか?", "おお、素晴らしい! この鉱石で染料が作れますから、The Stresses of Ironの写本を仕上げられます。\n\nありがとうございます、{name}!", 0x1452bc02, 0x66b7c48d, 0xcc491e42, 0xd2e294d7, 0x1dd5b437, "....." },
  [348] = { "Stranglethorn熱", "Witch Doctor Unbagwaを探し出し、Mokk the Savageを呼び出してもらう。Heart of MokkをFin Fizracketのところへ持って行って下さい。", "苦しい……とても……と、と、とても苦しい……\n\n……Stranglethorn Feverにかかった……死に至るウ、ウ、ウイルスだ……\n\n……唯一の治療法は……は……M-m-m-m-mokk the Savageの心臓を食べること……捕まえにくい白い獣……\n\n……Witch doctor Unbagwa……呼び出せるのは、や、や、彼だけ……\n\n……南の岬の隠れた洞窟でUnbagwaを探せ……\n\n……急げ……死にそうだ……死にそうだ……", "……母さん?\n\n……とても寒い……\n\n……Twisting Netherへ向かっていく……だ、だ、だ、抱きしめて、母さん……", "……力が戻ってくる……\n\nここは、どこだ? Booty Bay? なんと! 奇妙な夢を見ていた……\n\n……衰弱はまだ完全には抜けていない……", 0xb6849cd6, 0xf8db357b, 0x573dcf43, 0x2ca1f7fa, 0x9241c497, "....." },
  [350] = { "旧友を頼りに", "StormwindのElling Triasに話しかけて下さい。", "あのMarzonがDefiasの一員と連絡を取っていて、Lescovarともつながりがあったとは……\n\nVanCleefとThreddを殺してしまった以上、Lescovarに正当な裁きを受けさせるのは難しいだろう。彼らの証言がなければ、君の証拠は無意味だからな。それに、Lescovarが貴族で顔が広いという事実も考えなければならない。事実上、奴は法の上にいるということだ。\n\n他の助けが必要になる。気は進まないが、力を貸してくれる人物を知っている。街のTrade DistrictでTriasを探せ。", nil, "冗談だろう？Shawがまた私の助けを求めているだと？よくもまあ厚かましい……\n\nDefias Brotherhoodだと言うのか？いやはや、実に素晴らしい知らせの運び手だな。次はDeathwingがまだ生きていて街を襲っているとでも言うつもりか。\n\nよし、最初から全部話せ。重要でないと思うことも省くな。すべて知る必要がある。", 0x0a6b7a91, 0x3f1c2d43, 0x75a8e91d, nil, 0x89bbcf8d, "...m." },
  [351] = { "OOX-17/TNを発見せよ!", "損傷した救難信号発信機をOglethorpeの自動追跡ロボットのところへ持っていって下さい。", "金属製の卵型をした奇妙な謎の物体を発見した。卵が動くようつまみを弾いていじり回すと、卵が開いて中からノームのロボットのような奇妙な装置が現れた! 生き返ったロボット卵の中からは、パチパチと割れる声がした。\n\n「名前はOglethorpe、自動誘導ロボットが行方不明になってしまいました! ロボット修復の謝礼はするので、この救難装置をロボットのところへ持って行って下さい。よろしい、今ロボットの座標を算出しました! ロボットはTanarisのGaping Chasmで壊れて動けなくなっています!」", "どうやら……ロボットのニワトリの残骸を掘り当てたようだ。卵の中から再び声がパチパチと響く。\n\n「そう、よくやった! これはまさしく私の帰還用ロボットだ。だがセンサーによると、修理のためにBooty Bayへ飛んで戻る前に、始動の手助けが必要らしい。さあ、ビーコンを探査機の中に入れてくれ。あとはビーコンがやってくれる!」", "あなたは卵……救難装置を、鶏……自動誘導ロボットの中に設置した。\n\nロボットが立ち上がろうとしてもがくと、中からブーンという微かな唸りが聞こえてきた。ロボットが生き返るとOglethorpeの声が再び聞こえてきたが、今度はロボットの中からだった。\n\n「OOX-17/TNがようやく動くようになりました。でも、大がかりな修理が必要なのです! このロボットは運ぶには重たすぎます……が、ひとつ考えがあります。もう少しこのロボットの面倒を見る気はありませんか?」", 0xc307f79c, 0xf8142b0f, 0xdd3c83e8, 0xdb69203d, 0x8de25d71, "....." },
  [353] = { "Stormpikeへのお届け物", "Package for Stormpikeを、Loch ModanにいるMountaineer Stormpikeに届ける。", "Stormpikeは、名が知られたドワーフ一族なんだ。優秀で、洞察力が鋭いことで有名だ。だからこそ、Mountaineer of Ironforgeである、Gringer Stormpikeがワシに武器を製作してくれと依頼してきたのは何の不思議もない。\n\n武器は完成したんだが、Mountaineer Stormpikeは遠くてな…。Loch Modanってとこにあるんだよ。オマエが北に旅する計画があるなら、この武器が入った荷物を奴に届けてくれないか？\n\nMountaineer Stormpikeの手紙によると、奴はLoch Modan地方にある、北のガードタワーに駐在しているらしいな。", "Stormwindからはるばる来たのか? 南の人間の土地じゃ、山賊やオークがうろついて物騒になってきているそうじゃないか。{class}が腕を示すにはうってつけの場所だな!", "それじゃそれじゃ！Grimandめ、ワシの斧を完成させおったわい！troggsやkoboldsの奴らで試し斬りしたくてウズウズするわい！\n\nかたじけない、{name}。ここまで来るのは大変だったじゃろ。これはほんのお礼じゃ。受け取ってくれ。", 0x8e577b92, 0xd5f60077, 0xab2b7ebb, 0xae7f0689, 0x2aedd325, "....." },
  [354] = { "死霊の一族", "Gregor's RemainsとNissa's RemainsとThurman's RemainsをBrillにいるColeman Farthingのもとへ届けてください。", "Agamand一家はTirisfal Gladesで最も栄えた一族であった。私もかつては彼らの製粉所で働いていたのだよ・・・・こんなになっちまう前はな。\n\n初めてScourgeが攻めて来たとき、Agamandたちは家の守りを強化して、雇用人たちに残って防御するのを手伝うよう説得したのだ。わしらは馬鹿だった、が少なくとも忠実ではあったな。\n\nAgamandたち、彼らの誇りのおかげで我らはこの姿になることを運命づけられたのだ。今となっては彼らはScourgeの手先だ！\n\nいまわしきAgamandたちを打ち負かして、Forsakenのためにつくすのだ。やつらの残骸を持ってきてくれれば私の助けになる。", "Agamandsのremainsは持っているか? あの呪われた獣どもはついに滅びたのか?", "復讐とは甘い蜜のようだな。そう思わんか？Agamandたちを倒していたとき、彼らの中に自由な意志の気配を感じたかな？そうであってほしいものだ。やつらがくずれさるその前に、やつらが恐怖を感じていてほしいもんだな。\n\n馬鹿な望みだとはわかっているさ。それでもなお私は望んでやまないのだよ。", 0x1206b2d7, 0x2456ccd8, 0x1a5741cd, 0x9da96eaf, 0x39237f36, "....." },
  [355] = { "Sevrenと話す", "BrillにいるMagistrate Sevrenと話をしてください。", "お前がAgamandたちの残骸を持ってきてくれたので、すっきりしたよ。しかしAgamand Millsは私に限らず全てのForsakenに対して脅威を与えている。\n\nAgamandたちに対するお前の功績をMagistrate Sevrenには話しておいた。彼は話をしたがっている。", nil, "Colemanが褒めちぎっていたよ、{name}。Agamand Millsではよくやったそうじゃないか。\n\nForsakenはお前の腕を再び必要としている。", 0x54128fb3, 0xe10a8192, 0xbcf3fe44, nil, 0x4c5c4fc7, "...m." },
  [356] = { "戦線維持", "Bleeding Horror８体とWandering Spirit８体を殺し、野営地にいるLinneaに報告してください。", "PlaguelandsとTirisfalの境界のBulwarkの守備隊は絶えず警戒しています。だが時々Scourgeたちはすり抜けてきます。\n\nBulwark戦線の維持は一正面作戦の成功にかかっています。-後背からの攻撃は望ましくないし、守備隊の補給線が断たれるのも望ましいことではないです。\n\nBulwarkに助力しなさい。東を巡回し、Scourgeを見つけたら倒してください。特に東のBalnir Farmsteadを重点的に。侵入したScourgeたちの巣窟となっています。", "巡回の報告はあるか?", "よくやりました。あなたの働きによってScourgeたちも簡単には寄り付けないでしょう。私の上官、Executor Zygandに表彰の推薦を送っておきましょう。", 0x889b08c3, 0x17b31481, 0x10a80db8, 0x7f3fa30a, 0xe62772cd, "....." },
  [357] = { "Lichの正体", "UndercityのBethor IceshardにLich's Spellbookを渡してください。", "北にあるBrightwater Lakeに浮かぶ島にlichがいる。彼は自由たるForsakenだけれども、他のすべてのアンデッドがScourgeの奴隷であると思い込み近づくものは手下どもを使って排除しようとしている。\n\nしかし彼はForsakenなのだ。女王は彼を求めておられる。彼が魔法に精通しているなら、彼の知識は・・われらにとって非常に有用であろう。\n\n彼の正体と才能を探るために、彼の呪文書を見る必要がある。彼のもとへ行き、盗んでくるのだ。うまく行ったなら戻ってこい。", "{name}、本は手に入れたか?", "よくやった、{name}。これで彼の正体もわかるだろう。女王陛下も喜んでおられる。\n\n<Bethorは本を開き食い入るように読み始めた・・。>\n\n驚いた！お前が持ってきたこの本はGunther Arcanusのものではないか！\n\nGuntherは人間だったころ熟練の魔法使いだった。彼と私はあの災厄が訪れる前、戦友だったのだ。この本から判断するに、彼は死してなお成長しているようだ。\n\n彼の技能はわれらに大きな恩恵をもたらすであろう。", 0x77f697ac, 0x3216aabc, 0x0c4b7d62, 0x7639f1e5, 0x63fb2df0, "....." },
  [358] = { "墓荒らしたち", "Rot Hide GraverobbersとRot Hide Mongrelsを倒す。\n\nEmbalming Ichorsを$N1個、BrillのMagistrate Sevrenのところへ持って行って下さい。", "Garren's Hauntの南西にあるMass Gravesは、あの災いがはじめてTirisfalの地に訪れたとき命を落とした・・非常に多くの人を埋葬するために作られた。\n\nこの墓に埋葬されたものはこれまでアンデッドになることはなかったが、Scourgeは今軍隊を増強しようとRot Hide Gnollどもを使ってその亡骸を集めようとしている。許しがたい！\n\n任務は二つある。Mass GraveとGarren's HauntにいるRot Hideどもを殺すこと、そして奴らの命の源であるEmbalming Ichorを奴らから集めることだ。", "務めは果たしたか? あの犬もどきどもを倒して、そのichorを搾り取ったか?", "お見事、{name}。Scourgeなんかにあの亡骸を渡すと思ったら大きな間違いだ。そしてRot Hideどもから集めてくれた液体を我らの研究所で調べてみるとしよう。何か秘密がわかるかもしれん。\n\nお見事、と言ったが戦いはまだまだ続く。戦いはお前がForsakenにとってどれだけ価値があるかを証明する機会をより多く与えてくれるだろう。", 0xb5a1b5e8, 0x445d3260, 0xdaef0d93, 0x150b25ca, 0xf3d4d59b, "....." },
  [359] = { "伝令！", "Deathguard Linneaと話をしてください。", "東にあるDeathguard waystationからの最新の報告が必要だ。\n\nどれぐらいのScourgeの部隊がBulwarkをすり抜けTirisfalの中に忍び込んでいるか把握しなければならない。 Plaguelandsとの境界にある警戒線は維持されねばならない。ここにScourgeの強力な橋頭堡を築かせてはならない！\n\n道なりに南へ行け。分かれ道を東へ行けばwaystationだ。Deathguard Linneaと話をしろ。私の知りたい情報を持っているだろう。", nil, "Magistrate Sevrenが報告を求めているの？いいわ。Bulwarkにおける防衛隊はScourge軍のほとんどを抑えているわ。けれどもすべてを抑えきることはできないわ。\n\nここから東、Balnir Farmsteadのあたりで特にScourgeが活動しているのを見受けられるわ。", 0xd084bae8, 0x01a29751, 0x62158f5e, nil, 0x24304d48, "...m." },
  [360] = { "報告！", "BrillのMagistrate Sevrenのもとへ戻ってください。", "この報告を持ってMagistrate Sevrenのところへ戻ってください。急いでいるでしょうからよろしくね。\n\n戻る途中Scourgeを見かけたなら、倒してください。-彼らが我らの土地をあてもなくさまようのを許すことはできません。", nil, "ScourgeがBulwarkの防衛線をすり抜け進入しているとは、聞くのもわずらわしい。Lich Kingと奴の手先の襲撃は絶えることがない。\n\nしかしわれらが降参することはない。再び奴の手先にはならない！", 0x12884385, 0x92c7d7d0, 0x9c00db70, nil, 0x421c5bd4, "...m." },
  [361] = { "届かなかった手紙", "Yvette Farthingを見つけて、Thurman Agamandからの手紙を彼女に届けてください。", "この手紙の差出人はGregor Agamandの長男、Thurman。あて先はYvette Farthing、しかし彼女の元へは届けられてないようだ・・。", "何か？", "ああ・・かわいそうなThurman！私は彼に私たちと一緒にAgamand Millsから逃れるようお願いしたわ。でも彼ら一家の結束はあまりに強かった！私は知っていた！Brandが彼に危害を加えるつもりだって、わかっていたのよ！！ああ、この災いとScourgeが憎らしい！\n\n<Yvetteの顔は無表情に冷たくなっていった。>\n\n後悔は弱いものがすることよ。Forsakenとして私は新たな目標を得たわ。でも愛はその中にはない。手紙を届けてくれてありがとう。私の過ぎ去った愛に何が起きたのか、ずっと気になっていたから。\n\nでももう終わったのよ。永遠に。", 0x5e10b1e4, 0xc4999128, 0xe925a4ce, 0x0c07a888, 0x85cd25fb, "....." },
  [362] = { "幽霊製粉所", "Devlin Agamandを倒し、Devlin's RemainsをBrillにいるColeman Farthingに届けてください。", "Devlin AgamandはAgamand一家の二人いる息子の若い方だった。生きている間二人は大きく異なっていた。弟が弱々しく、辛らつであったのに対し、Thurmanは背が高くて、そして穏やかであった。\n\nAgamand Millsに災厄が降りかかったとき、Devlinが急死したと聞いても別に驚きもしなかった。彼のばかげたおしゃべりはまだAgamand Millsに通じている道の近くから聞こえてくる。\n\n私はAgamands一家の残骸を集めているのだよ。Devlinのものもだ。彼を見つけ、倒し、彼の骨を持ってきてはくれないか。", "Devlinは見つかったか?", "ありがとう。Devlinの骨は私の炉棚に収めておくこととしよう。\n\nAgamand一家が倒されたことを知れば、私の冷え切った心も少しは温まるだろう。災厄が訪れたあの時、奴らは私と家族を見捨てたのだ。私は奴らの残骸をこの足で踏み砕いてやると心に決めているのだ！", 0xa79aec83, 0xffa9100d, 0x1441dcb8, 0x4fefbbb4, 0x9ac1d49a, "....." },
  [363] = { "幻滅", "Shadow Priest Sarvisと話をしてください。", "お目覚めかな。まとめて灰にしようと思っていたが、間に合ったようだな。\n\n私はMordo、Deathknell地下聖堂の世話人だ。そしてお前はもはやLich Kingの奴隷などではない。\n\nこの丘のふもとにある教会にいるShadow Priest Sarvisと話をするとよい。彼はお前が知るべきたくさんのことを話してくれるだろう。", nil, "また一人目覚めたのか、ン？冷たい地下聖堂での目覚めと、Mordoの出迎えはなかなかのショックであったろうな・・・。\n\n混乱しているようだな。お主に我々の・・状況を教えるとしようか。\n\n我々は新しき指導者Lady SylvanasによってLich Kingの支配から逃れることができた。Dark Ladyは、憎きScourgeと、我々の歩みにしつこくつきまとう人間どもの残党との戦いを導いている。", 0xe51cefc8, 0xcd2051a8, 0x4ee64e18, nil, 0x3dd91702, "...m." },
  [364] = { "非情なものたち", "Shadow Priest SarvisはあなたがMindless Zombie８匹とWretched Zombie８匹を殺すことを望んでいます。", "我らForsakenはScourgeのLich Kingの軍隊、すなわち黒魔術に操られたアンデッドども・北の不快な生き物・忌々しい幽霊どもと戦っている。\n\nこの村の北半分は非情なものどもに侵略されつつある。奴らには消えてもらわなければならん。奴らを殺すのだ。たとえ奴らが昔の仲間であろうとも、慈悲など与えるな。「死せるもの｣どもは Lich Kingの奴隷以外の何者でもない。", "最も弱いゾンビすら倒せないようでは、この新たな生で先へは進めんぞ、{name}。成果を報告できるまで戻ってくるな。", "Scourgeどもを仲間に引き入れられないのは残念だな。あの大群は戦いを有利にするのに有効なのだがな。\n\nしかし奴らはわれらに手を貸すことはないだろう。だから奴らを殺す以外選択肢などないのだよ。", 0x662772dd, 0x2c117b14, 0x3bac79ef, 0x22709411, 0x7b9bd914, "....." },
  [365] = { "悲しみの大地", "Deathknellの真北、ここの西の農場からかぼちゃを10個盗み出し、BrillにいるApothecary Johaanに渡してください。", "おや、これは何だ？まだ駆け出しのようだな{class}。Dark Ladyに認めてほしいなら、Forsakenのやり方を知る必要があるな。\n\n西へ行くと農場がある。人間はカビが腐った死体に生えるのと同じように大地を荒らす。さらに悪いことに、Scarlet Crusadeが近くの塔から巡回に回っている。あのかすどもに教訓を与え、奴らの大事なかぼちゃを10個盗んでくるんだ。\n\n10個集まったら、BrillにいるApothecary Johaanに渡してくれるかい。", "Deathguard Simmerから、お前がどうしても必要な試薬を届けてくれると知らせがあった。カボチャ10個はもう集まったか、{name}?", "うまくやったようだな、若き{class}よ。Dark Ladyの軍の中でも有望株だと立証できたようだ。", 0x2932f488, 0xf53c96c2, 0xf89b6106, 0x73105245, 0x0e4e9168, "....." },
  [366] = { "本を返す", "Gunther's Retreatの島にいるGuntherにGunther's Spellbookを返してください。", "かつて私とGunther、そして今はScourgeのNecromancerと成り果てたThule Ravenclawは友であり、Dalaranの魔法学校Kirin Torで共に学んだ仲であった。\n\nGuntherと私は共にあの災いに倒れた。私は彼が死んだか、あるいはLich Kingのしもべとなったかと思っていた。生きていてよかった。\n\n彼を連れ戻したい。彼の本に呪文をかけておいた。彼が手にしたとき私もまたLich Kingの魔手から逃れているということがわかるようにね。それを知れば、彼も私たちと共に戦ってくれるのではないかな。", "お前の主人どもは愚か者だ、お前をここへよこすとはな。我は二度とScourgeの奴隷にはならぬ!", "私の本だ？！？お前が盗んだんだな！\n\nしかし・・新しい呪文が付加されているな・・Bethor？彼はLordaeronにいるのか？\n\n彼が生きているというなら、彼も同じくLich Kingの魔手から逃れたということだな・・。", 0x67addb26, 0x1ef4863d, 0x9d95752a, 0x03c4c134, 0xc9995e3f, "....." },
  [367] = { "新しき災厄", "Brillの町にいるApothecary JohaanはVial of Darkhound Bloodを５つ求めています。", "Lady SylvanasはRoyal Apothecary Societyに指示を下された。Dark Ladyは我らの知識と近頃見つかった魔法を組み合わせればArthasの消滅への鍵が得られると信じておられる。彼女は我らにAzerothにおけるどんな病気よりも命取りになるような新しい災いを生み出すことに挑むように言われた。この新しき災いはArthasのScourge Armyに破滅をもたらすだろう。\n\n研究の結果、野獣の血が鍵になるのではと考えた。vial of darkhound bloodを５つ持ってきてくれたら、私の理論を試すことができる。", "darkhound bloodの小瓶を5本、もう集めたか、{name}? 時間がないぞ!", "よくやった、{name}。感謝するぞ。", 0x4012ba5a, 0x09ffaa51, 0x368f3ad3, 0xef4e8ff0, 0x60911425, "....." },
  [368] = { "新しき災厄", "Brill townのApothecary JohaanはTirisfal GladesのMurlocから採れるVile Fin Scaleを５つ求めています。", "試料を集めてくれている間に実験していたんだが、この新しき災厄を効率よく蔓延させようとすればより多くの試薬がいることがわかった。何人かの不幸な奴を毒殺するなんてことはたやすいことだ。世界中に災厄を撒き散らすということはもう少し手がかかる。\n\n浜辺にいるMurlocから採れるVile Fin Scaleが５ついる。北か西の浜辺に奴らはいるだろう。", "{name}、MurlocsからVile Fin Scalesを5枚手に入れられたか?", "完璧だな、{name}。まさしく私がほしかったものだよ。", 0x4012ba5a, 0x909fd9c6, 0xf43a2021, 0xbd3e5279, 0x795f8256, "....." },
  [369] = { "新しき災厄", "Brill townのApothecary JohaanはVicious Night Web Spiderから採れるsample of venomを４つ求めています。", "お前がいない間に、何千という無実の犠牲者を生んだという古代の災いについて書かれた文書を、私の蔵書の中から見つけ出した。その後Night Web Spiderの毒液の中にその災いの種が保存されているということがわかった。\n\n実験を完成させるために、Vicious Night Web Spiderから採れる毒液を少しばかり採ってきてくれんか？その毒液から採れる伝染性の成分が新しい調合物を作るのに適しているか確かめたい。うわさではTirisfal Gladesの東にクモはいるらしい。", "Vicious Night Web Spiderの毒はもう手に入ったか、{name}? 実験を試すのに必要な最後の材料なんだ。", "おお、完璧だな、{name}。材料がすべてそろったので煮詰めるとしようか。さあ、準備は整った！", 0x4012ba5a, 0x71928e3a, 0x9ecb3ade, 0xf0a5e0b1, 0x20e13a3f, "....." },
  [370] = { "Scarlet Crusadeとの戦争", "BrillのExecutor ZygandはCaptain PerrineとScarlet Zealotを３人、Scarlet Missionariesを３人殺すことを望んでいる。", "Executor Arrenがもたらしたこの戦略上重要な書類は、この国から人間どもを消し去ることに必要な事すべてが書かれている。この情報によると、The Scarlet CrusadeはBrill南西の廃れた塔の守備をCaptain Perrineの隊に命じたようだ。\n\nPerrineとZealot３人、Missionariesを３人殺したなら、報告しに戻ってこい。", "若き{class}よ、同胞がその大義のために戦うお前を必要としているというのに、ここBrillで時間を無駄にしている場合ではないぞ。さあ、武器を取って南西の廃塔へ向かい、Captain Perrineと3人のScarlet Zealots、3人のScarlet Missionariesを討て。Scarlet Crusadeなど家畜のように破滅へと追い立ててやろう。", "Captain Perrineの死を知ったならDark Ladyもお喜びになることだろう。お役目ご苦労、{class}。", 0x5aa72e8b, 0xdbeebcd7, 0xc41776f5, 0xa5c40f43, 0xe3a971de, "....." },
  [371] = { "Scarlet Crusadeとの戦争", "BrillのExecutor ZygandはCaptain Vachonと５人のScarlet Friarを倒すことをあなたに依頼した。", "いまだ戦争は続いており、Scarlet Crusadeはその勢力を増している。Executor Arrenが私にもたらした報告によると、Scarlet CrusaderどもはBalnir Farmstead近くの南東Tirisfalにある廃れた塔からCaptain Vachon指揮下の部隊を繰り出している。\n\nVachonと５人のScarlet Friarを殺せ。Crusadeに壊滅的なダメージを与えるのだ！", "戻ってきたようだが、務めは果たしていないな。ただの人間どもがThe Dark Ladyの計画を邪魔しても平気だというのか? それとも義務の呼び声に応え、Captain Vachonとその一味のScarlet Friarsを討つことができるか!", "Captain Vachonの死は大いにTirisfalにおけるScarlet Crusadeの進軍の歩みを遅くすることであろう。しかし新たなる脅威が迫っている。", 0x5aa72e8b, 0x230145b6, 0x8d2df557, 0xed1a74cc, 0x0d6cd08c, "....." },
  [372] = { "Scarlet Crusadeとの戦争", "BrillタウンのExecutor ZygandはCaptain Melracheと二人のbodyguardを暗殺することを望んでいます。", "Scarlet Crusaderどもは北TirisfalのFaol's Restを過ぎたところにある廃れた塔から繰り返し襲撃を行っている。私の知るところによると、Captain Melracheという名の非情な指揮官がこの悪魔の一味を率いている。\n\nお前に危険で、特別な任務を託す。Melracheと２人のbodyguardを殺せ。Dark Ladyの名の下に。", "お前はまだ務めを果たしていない、{class}。Scarlet Crusadeに兵たちを悩まされていては、The Dark Ladyの計画を遂行することなど望めん。奴らに死をもたらし、Sylvanasへの務めを果たせ!", "実によくやった、{class}。お前のような非情な戦士がForsakenの名の下に制圧していくことは、Arthasを破る日がはっきり一日一日近づいていくのだからな。悪くないぞ、戦友。", 0x5aa72e8b, 0x16e2b772, 0x9d736921, 0x721d38b8, 0x06825bc6, "....." },
  [373] = { "送られなかった手紙", "StormwindのBaros Alexstonに手紙を届けて下さい。", "Edwin VanCleefの身体を調べると、いろいろな物に混じって、出されていない手紙が見つかった。宛先はStormwindの都市建築家、Baros Alexston。City Hall、Cathedral Squareとある。\n\n最近書かれて封をされたもののようだ。", "はい? 何かご用でしょうか?", "Edwin VanCleefだと？死んだ祖母から手紙が来る方がまだありそうだ……では奴を殺したのか？失礼ながら、少々驚いている。若い頃の彼は比類なき戦士だった。これほど年月が経ってから、何を私に書き送る必要があったのか見てみよう。\n\n<Barosは手紙に目を通す。>\n\nEdwinよ……年月は君を少しも変えなかったようだな、相変わらずの理想家で、そしてロマンチストだ。彼は誰を傷つけるかなど気にしない、{name}。復讐が彼を飲み込んでしまった。だが、彼を責められるかどうかは分からん。", 0xaf33b2fe, 0xb7077b54, 0x4d9722a9, 0x5bf43657, 0x5b678cae, "....." },
  [374] = { "殺人証明", "Scarlet Insignia Ringを10個、BrillにいるDeathguard Burgessに渡してください。", "Executor Zygandから聞いたが、お前はScarlet Crusaderどもを倒して回っているそうだな。Tirisfal Gladesにはやつらがうようよしている。\n\nDark Ladyの副官であるVarimathrasが、Azerothのクズである人間という種族を忘却の彼方へ消し去るよう自ら取り計らっている。ここTirisfal Gladesで我々が相手にしているのは、とりわけ厄介な人間どもだ。Scarlet Crusadeだ。\n\n出撃してScarlet Crusadeに攻勢をかけろ、{class}。VarimathrasとDark Ladyへの忠誠の証として、Scarlet Insignia Ringを10個持ち帰るのだ。", "Scarlet Insignia Ringsを10個、もう集めたか、{class}?", "Varimathrasも鼻が高いであろう。忠誠に励むがよい、{class}。", 0x921e8463, 0xb39a505d, 0xed4d1fa3, 0x22053211, 0x6b185a16, "....." },
  [375] = { "死の冷気", "BrillにいるGretchen DedmarにDuskbat Peltを５個とCoarse Threadを渡してください。", "とても寒いの、今は。Plague of Undeathが氷の蛇のように私の血管を這い回っている。もうすぐMindless Stateが私を襲うでしょう。でも、どんな呪われた運命も、私たちのDark Ladyにお仕えすることを妨げはしない。召集がかかったとき、私はSylvanasの強大な軍の戦死した兵士たちのために遺体袋を縫ったの。\n\n今は寒さで手が震えてしまう。Duskbat Peltを5枚とCoarse Threadを少し持ってきてくれれば、自分で毛布を縫えるのだけれど。助けて、{name}。大義に仕え続けられるように。", "Duskbat Pelts 5枚とCoarse Threadはもう手に入れたかい、{name}?", "手伝ってくれてありがとう、{name}。Sylvanas様がいつかあなたを勇者と認めるでしょう・・・。", 0x7e5206c9, 0x896b7787, 0xe96a4151, 0x22b2c2d6, 0x788b9dba, "....." },
  [376] = { "いまわしきもの", "Novice ElrethはScavenger Paw６個とDuskbat Wing６個を必要としています。", "私の務めは、負傷したウォリアーたちの手当て、鎧や衣服の仕立て、そしてShadow Priest Sarvisが求めるそのほかの手伝いだ。\n\n見たところ、君も彼に仕えることになりそうだな……彼の考えはわかっている、Mindless Onesを狩らせるのだろう。さて、五体満足でいたいなら――もちろんそうだろうが――私が力になれるかもしれない。手持ちの前足と翼が尽きかけていてな。持ってきてくれれば、君に合う鎧を見つけてやろう。南へ行けば狼や蝙蝠がたくさんいる。", "防具を用意してやるまで、なるべく怪我をしないよう気をつけてくれ。", "ありがとう、{name}。このよろいはあなたの助けとなるでしょう。\n\n願わくば、前に着ていた者よりは役立ってくれるといいのですが・・・。", 0x0d5c3a64, 0xeac65110, 0x95813e5f, 0xa9195c35, 0x1cb90e7e, "....." },
  [377] = { "罪と罰", "DarkshireのCouncilman Millstipeは、Dextren Wardの手を持ってくるよう求めています。", "Duskwoodの住民がないがしろにされているだけでも十分ひどいというのに、今度はHouse of NoblesがDarkshire Councilの顔に唾を吐きかけた。Lord Ebonlockeの判決どおりにあの悪党の首をはねるのではなく、Dextren WardをStormwindに投獄すると決めたのだ。\n\nWardは墓地の死体をMorbent Felに売っているところを捕まった。死刑に値する罪だ。それなのに、StormwindはWardを自分たちの囚人だと言い張っている。\n\nStormwind StockadeでWardを暗殺しろ。奴の手を持ってこい。そうすれば報酬をやろう。", "Dextren Wardのような死者を冒涜する者が生き永らえている限り、正義は裏切られたままだ。Lord Ebonlockeの死刑宣告があの冒涜者Wardに執行されたら、私のもとへ戻ってこい。死者の遺族に相応しい区切りを与え、さらにはStormwindのHouse of Noblesにはっきりとした警告を送ってやるのだ。", "ではついにDextren Wardは人間らしさに対する犯罪の代償を払ったのだな? あの屑がいなくなってせいせいしたと言わせてもらおう。我が友よ、君に乾杯! 死者の家族に与えられるべき心の平穏をもたらしただけでなく、House of Noblesの腐ったお役人どもに痛烈なメッセージを叩きつけたんだ。StormwindはDuskwoodの人々の求めに対して立ち上がらねばならないのだ。でなければ我々は暴政から逃げ出すだろう。", 0xd8baf022, 0x6846295b, 0x8a0de614, 0xc306418b, 0x3d4fa9be, "....." },
  [378] = { "怒りは根深く", "Dun ModrのMotley Garmasonは、Kam Deepfuryの首を持ってくるよう求めています。", "お前はKing Magniへの忠誠を証明してくれた、{class}。そしてDark Ironのクズどもへの憎しみも、わしに負けず劣らずだ。\n\n自分の手で片付けたい仕事があるのだが、わしは名誉にかけてLongbraidのそばを離れられん。だが、RoggoがKam DeepfuryがThandol Spanへの攻撃の共謀者だったと証明する情報を集めてくれた。Longbraidが身内を失ったのは、Deepfuryの計画によるものだったのだ。\n\nDeepfuryは政治的な理由でStormwind Stockadeに拘留されている。奴の死を望む、{name}。Longbraidのために！奴の首を持ってこい！", "愚かな人間のお役所仕事にドワーフの問題を邪魔させるつもりはないぞ、{name}。Kam DeepfuryはThandol Span襲撃の共謀者だと証明されている。Deepfuryの裏切りのせいで、King Magniの善良な民が命を落としたのだ。人間どもはDeepfuryをThe Stockadeで朽ちさせておけば満足かもしれんが、わしはDeepfuryが討たれるまで夜も安心して眠れん。", "それじゃあKam Deepfuryはついに、死を迎えるとはどういうことかと思い知らされたのだな? よかった。卑怯者のDark Iron族のクズめ自業自得だ。よくやってくれたよ、{class}。Thandol Span攻撃の犠牲者は、動乱と戦火で荒れ果てた世界の犠牲者に過ぎないんだ。犠牲者の家族はDeepfuryが然るべき罰を受けたと知れば、心が安らぐだろう。Longbraidの兄弟の仇は討ったぞ。", 0x1158c5af, 0x54c0df47, 0xcec43aea, 0xfee1b4d9, 0x53eb2770, "....." },
  [379] = { "その渇きを満たせ", "GadgetzanのChief Engineer BilgewhizzleにWastewander Water Pouchを5個渡して下さい。", "動力源が欲しいんだな。それなら力になれるぜ。俺が何を欲しいか分かるか？何か飲むものだよ！Wastewander Water Pouchesを5つ持ってきてくれたら、4711-FTZをやろう。\n\nさて……Wastewander Water Pouchesがどこで手に入るか当ててみな！東にいるWastewanderの遊牧民のところへ歩いていって、1つくれって頼んでみたらどうだ。どうなったか教えてくれよ。", "で、遊牧民どもはそのwater pouchesを「進んで」差し出してくれたかい?", "よし、動力源は君のものだ。さて、これはああいう科学キットで使うように完全に設計されているわけではないから、集めたデータが全部おじゃんになるまでの時間は限られているぞ！\n\nやろうとしていることに必要なものを全部集めたら、私のところへ持ってこい。きちんと停止させてやる。やるべきことを終わらせるのに使える時間は、せいぜい2時間だ。\n\n時間内に終わらなければ、いつでも別の動力源を売ってやるさ、もう一度試せるようにな。聞こえたか——売る、だ！", 0xfb0763f0, 0x27174f10, 0xef0f5cb3, 0xd7dbd34f, 0x706ae8cf, "....." },
  [380] = { "Night Web's Hollow", "Executor ArrenはYoung Night Web Spider10匹とNight Web Spider８匹を倒すことを望んでいます。", "我々がやらねばならない大事なことのひとつが生き残るために必要な天然資材を手に入れることだ。ゴールドはAllianceの全盛期でさえも貴重なものだった。\n\n北西に蜘蛛どもがはびこっている金鉱脈がある。鉱山から金を掘り出さなければならないのだが、蜘蛛どもがいるので掘り出すことができない。人手が足らないので、ちょっとずつしか進めることができん。\n\nあそこへ行き、我々のために何ができるか見てきてくれ、{name}。", "クモの毒には気をつけろ、{name}。鋭い焼けるような痛みを感じたら、診てもらったほうがいい。", "ふむ、よし、始まりだ。完全に駆逐するには数週間から数ヶ月かかるだろう。その後は蜘蛛の巣を焼き払うためにたいまつを何本か用意しておかねばならないな。\n\nそなたはよくやった、{name}。そなたになすべきことを他にも見つけてやれるだろう。", 0xf4d863e7, 0xb5ac7fa7, 0x89530ddc, 0xaad01ead, 0x9c201e46, "....." },
  [381] = { "The Scarlet Crusade", "Scarlet ConvertとScarlet InitiateからScarlet Armbandを12個奪ってExecutor Arrenに渡してください。", "お前の小さくない努力のおかげで我々がこの鉱山で発展していくのはお前も喜ばしいであろう。他の心配事にも目が向けられるようになった。\n\n偵察隊がここの南東にScarlet Crusadeの派遣隊が野営地を構えていると報告してきた。Scarlet Crusadeは我々を倒そうとする卑劣な奴らだ。そして奴らはすべてのアンデッド--Lich King's Scourgeであろうとなかろうと--を倒すまで戦い続けるだろう。奴らを初めにやっつけねばならん！\n\n気をつけろよ。やつらの途方もない熱意は奴らを危険な力へと変えるからな。", "愚か者どもめ……自ら喜んで墓穴へ飛び込んでいくとは。", "話の通じる相手だったかね、ん？、{name}？おそらく戦わねば話など通じまい、は！\n\n光に目のくらんだあほうどもめ。", 0xe44fe888, 0x315fed01, 0x9254889b, 0x7a95f60a, 0xefabbf0e, "....." },
  [382] = { "レッドメッセンジャー", "十字軍キャンプにいるメッセンジャー、Meven Korgalを殺し、そこで手に入れた情報をExecutor Arrenのもとへ持ち帰ってください。", "Brillにいる上官からの連絡によるとScarlet Crusadeの情報員がScarlet Monasteryよりここ、Deathknellにむけ急遽派遣された形跡があるとのことだ。報告によると、メッセンジャーはその件に関して重要な情報を持っているようだ。詳しいことはわからないが、たとえそれが何であれ手に入れねばならん！\n\nお前が適任のようだ、{name}。メッセンジャーを見つけ出し、何か情報を手に入れてくるのだ。", "任務の調子はどうだ、{name}?", "うむむ・・見せてもらおうか・・。\n\n<彼はあなたが見つけた文書をむさぼるように読み始めた。>\n\n単なる報告書か・・・つまらん。索敵報告・・・、新しい指令「廃墟となった都市の近くでの野営地の拡大を続けよ・・」、目新しいものはないな・・。ん？これは何だ？奴らの指揮官と情報員の配置図か！使えるぞ。", 0xcc6b9441, 0xdf601388, 0x24feade3, 0x04bcf357, 0x99d645bd, "....." },
  [383] = { "重要情報", "Scarlet Crusade DocumentsをBrillにいるExecutor Zygandに届けてください。", "これはBrillにいる私の上官Executor Zygandに持っていく必要があるな。これでScarlet Crusadeの奴らに決定打を与えてやることができるな。ここDeathknellでお前はよくやってくれている。しかしZygandに誰かがこれを届けねばならん。それにかれはお前にもっとふさわしい任務を与えてくれるだろう。\n\nDeathknellから北への道を行け。Tirisfalに出るとすぐ、分かれ道に出る。東に分かれた道を行け。そのまま東に進むのだ。途中でCold Hearth Manorを通り越してゆくだろう。", "何だ、何の用だ?", "おお、すばらしい。よくこの情報を手に入れたな、{name}。ううむ、Tirisfal Gladesに配属された士官の名前か・・。\n\n我々が速攻で奴らの指揮官を倒し、血にまみれた狂信者どもの士気に大きな打撃を与えるさまが思い浮かぶではないか。", 0x2ab93219, 0x3476f839, 0x22c8ce98, 0xba88a72c, 0x95a7a867, "....." },
  [384] = { "Beer Basted Boar Ribs", "KharanosのRagnar ThunderbrewはCrag Boar Ribs 6本とRhapsody Malt 一杯を求めています。", "うちの酒場のお得意さんが一番堪能するのは「Beer Basted Boar Ribs」だ! 唯一の問題は、うちへ食材を運んでくれてた地元の罠師がAlliance前線支援のために国王軍に入隊しちゃったことさ。\n\n手伝ってくれないか? crag boarのあばら肉6本とここの酒場のRhapsody Maltを一杯持ってきてくれたら、家に伝わるBeer Basted Boar Ribsのレシピを教えてあげるよ。もちろん試食用の料理もつけてな! 秘密はビールにあるんだ!", "crag boar ribsが6本とRhapsody Maltが一杯必要なんだ、{name}。", "ビールができて、Boars死んで\nすべて終わって何か言う前に\nうまそなBeer Basted Boar Ribs前に\n最初の一口巡って争わにゃ!", 0x56bf3780, 0x848a85be, 0xacc6d110, 0xe5dfc379, 0x3d02ca9a, "....." },
  [385] = { "Crocolisk狩り", "Crocolisk Meatを5切れとCrocolisk Skinを6枚、Farstrider LodgeのMarek Ironheartのために手に入れる。", "多くのハンターが、名物のcrocsを狩りにLoch Modanへ引き寄せられてくる。衣服や鎧のためにcrocolisk skinsを求める商人はいつだっているし、その肉の味を好む者もいる。\n\n我々もこれで少しは商売をしているが、大した量じゃない。crocoliskは獰猛で、Lochの島々に陣取っているからな。だが、やめておけと言うつもりはない。あの獣の顎と取っ組み合うのは、なかなかの体験だぞ。\n\nそうそう、いつだったか……", "ワニに片手を持っていかれそうになった時の話はしたっけか? 嫌な奴でな、歯はナイフみたいだった。だが俺は運が良かった……そいつの顎にナイフを突っ込んで口を開けなくしてやったのさ。そのナイフはまだこの辺のどこかにあるはずだ……", "さて、君が集めてきたのは見事な標本だな、{name}。高品質の素材には良い金を払う、それは間違いない。", 0x08c77bcd, 0x39f97603, 0x43d56489, 0x6cc0be27, 0x469a4235, "....." },
  [386] = { "因果応報……", "Targorr the Dreadの首をLakeshireのGuard Bertonに渡して下さい。", "Targorr the DreadはGath'Ilzoggの下で最高処刑人を務めていた。そのやり口は、汚らわしいオークの基準に照らしても冷酷だった。王国を守るために勇敢に戦った者たちが、奴の気まぐれで拷問にかけられたのだ。今、奴はStormwind Stockadeに捕らえられ、死刑を宣告されている。だが、何かがおかしい。役人貴族の一人が奴の処刑を保留にしたのだ。きっと汚い陰謀が進んでいる。\n\nTargorr the Dreadを始末してくれ、{name}。The Stockadeへ行き、策略が及ぶ前に奴の首をはねるのだ。", "もうStormwindのThe Stockadeには行ったか? Targorr the Dreadをここまで生き永らえさせてきた何らかの策略が、いずれ奴を自由の身にしてしまうのではないかと恐れている。奴は死刑を宣告されたのだ、{name}。貴族の気まぐれで政治の駒になるためではない。", "ついにTargorr the Dreadは死んだのか。死の残酷な手に迎えられるとはどういうことかをあのけだものが思い知ったと聞いて、私個人としては嬉しいよ。よくやってくれたよ、{name}。真の正義ってのは、法廷の外や不透明な政治の向こうにしか見つからないものなんだな。", 0x985b5c1d, 0x0bd13fa2, 0x9d18b187, 0x4b424f22, 0x4701141d, "....." },
  [387] = { "反乱を鎮圧せよ", "StormwindのWarden Thelwaterは、StockadeにいるDefias Prisoner 10人・Defias Convict 8人・Defias Insurgent 8人を殺すよう求めています。", "暴動を鎮めなければならん！君の助けが必要だ。監獄が囚人に占拠されたなんて噂が広まったら、私は職を失ってしまう！これほどの汚い企みは見たことがない。だが今大事なのは、Stormwindの安全のためにこの囚人どもを力ずくで服従させることだ。\n\n反乱の罰は死だ。このならず者どもを何人か殺してくれ！そうすれば事態は収まるはずだ。", "Stockadeはまだ占拠されたままだ！ Defias Ratsどもに、奴らの行いは許されないと思い知らせてやらねばならん。さあ、下へ戻って力を見せつけてこい！", "The Stockadeでの働きは勇敢だったよ、{name}。あれは明らかに俺たち二人じゃ手に負えないほどの大問題だった。それなのにあんたはやり遂げてくれたんで、感謝してるよ。", 0x577b3efe, 0x537853f9, 0xb27b21dc, 0x07128f06, 0x7f65d9bb, "....." },
  [388] = { "血の色", "StormwindのNikova RaskolはRed Wool Bandana 10枚を集めるよう求めています。", "冷たい川のように、苦い思いが私の血管を流れている。孫のMacは本当にいい子だった。まだほんの14歳だった。軍が前線へ送られたとき、Macは街を守るために武器を取った。Defiasのギャングが閉じ込められているStockadeで看守をしていたのだ。囚人たちがギャングの象徴であるスカーフを作ろうと毛布を裂いていたのを、Macが叱った。それが理由で、Macは背中を刺されたのだ。\n\n復讐したい。奴らの大事なWool Bandanasを10枚持ってきてくれ。血の色をしたバンダナだ。", "戻ったようだな、{class}。StockadeにいるDefias Scumどもから、Red Wool Bandanaを10枚集めてきたか？", "では、このバンダナが——腐敗の汚らわしい証が——私のMacが命を落とす理由だったというのか？なんという無駄だ。なんという痛ましい犠牲だ。\n\nだが悲しいかな、過去には戻れない。ただこれだけは知っておいてくれ、{name}。あなたはその行いによって、私の家族に正義をもたらしてくれたのだ。", 0x309b5224, 0x731de4a6, 0x75502eb1, 0x94db022c, 0x3ca7de8a, "....." },
  [389] = { "Bazil Thredd", "StockadeのWarden Thelwaterと話して下さい。", "VanCleefと私はStonemasons Guildの一員だった。我々の主な仕事は、Warの後にStormwindを再建することだった。\n\n務めを終えたとき、我々は騙された。貴族たちは我々の仕事に対する支払いを拒んだのだ。Stonemasonsの中でも古参の者には役人の職が提示されたが、VanCleefはすべてのStonemasonsへの忠義からそれを断った。彼は暴動を率いて街を去り、復讐を誓ったのだ。\n\n彼の副官だったBazil Threddなら、VanCleefの計画についてもっと知っているかもしれない。彼はStockadeに囚人として拘留されている。", nil, "光にかけて、一体何の用だ？ここが危機的状況だと分からんのか？\n\nBazil Thredd？！なぜあんな下衆と話したがる？お前が奴の仲間で、あの忌々しい暴動に加勢しに来たのではないと、どうやって分かる？独房が全部開いていなければ、しばらくお前をぶち込んでいるところだ！", 0x49a42307, 0x9f1dfef8, 0xcad99174, nil, 0x275f421d, "...m." },
  [391] = { "Stockadeの反乱", "Bazil Threddを殺し、その首をStockadeのWarden Thelwaterに渡して下さい。", "1つはっきりさせておこう、{name}。俺はお前を信用していない。だが、この状況じゃ、お前がいようといまいと大して変わらんだろう。\n\nだからこうしよう。下へ行ってThreddと話をしてこい。本当にこっちの味方なら、奴を殺して、仕事が済んだら首を持ってこい。もしお前が奴の側について出てこなかったら……見つけ次第、他のウジ虫どもと一緒に死んでもらう。", "Threddの首を持ってくるか、さもなくば俺がお前の首をいただく。分かったな、{name}？", "Threddが率いる者がいなくなれば、暴動ももっと抑えられるようになるだろう。様子を見よう。\n\n正直に言えば、半時間も経って君が出てくるとはほとんど思っていなかった。だが、どうやら君を見誤っていたようだ。\n\nでは、奴からは大して有益な情報は得られなかったのだろうな？だがThreddの動きについて、君が興味を持ちそうなことを少しばかり知っている。", 0x8d19e31c, 0x1cb86e24, 0xa2b8b189, 0xb08a569e, 0x6178e7e9, "....." },
  [392] = { "奇妙な面会人", "StormwindのBaros AlexstonにSealed Description of Thredd's Visitorを渡して下さい。", "収監されて最初の数年、Threddには面会人が一人も来なかった。Brotherhoodにとって奴はもう用済みで、見捨てられたんだろうと思っていた。\n\nところが数か月前、それがすっかり変わった。定期的に面会人が来るようになったんだ……週に一度、時には二度な。妙な男だった……無口なタイプだ。怪しいとは思ったが、書類はすべて問題なかった。\n\n書類によると奴の名前はMaelikだそうだ。これが奴の人相書きだ。もうThreddに面会に来ることはないだろうがな。", "どうした、{name}？ 何が分かった？", "うーん。Maelikねえ。いや、この名前には聞き覚えがないし、人相書きにも心当たりないな。しかしこれは、誰にだって可能性がある! 元Stonemason、Defias Brotherhoodのメンバー……。だが、Thelwaterが言ったように深く関わりがあるのだとすれば……もしかしたら誰かが覚えてるかもしれない。ちょっと考えさせてくれ。", 0x35a2f6f1, 0xdb51b853, 0x0cbcac0d, 0x2a96cc90, 0x473d9a09, "....." },
  [393] = { "過去の影", "Sealed Description of Thredd's VisitorをStormwindのMaster Mathias Shawに渡して下さい。", "本当に見当もつかないんだ、{name}。助けになりそうな人物が他にいるし、たまたま彼は私に借りがある……まあ、その話はやめておこう。SI:7のMaster Mathias ShawはOld Townの兵舎にいる。Shawは、この街の怪しげな取引や裏取引のほとんどを把握しているんだ。\n\n誰か知っているとすれば、彼だろう。", "ごきげんよう。どのようなご用件でしょうか、{class}？", "何だ？これは何だ？ああ、この男が誰かは分かると思う。だが奴の名はMaelikではない。暗殺者は多くの名と多くの仮面を身につけ、役に立たなくなれば捨てていく。この男が使っていたとされる別名にMarzonというのもあるが、それとて真の名ではあるまい。\n\nいずれにせよ、奴は暗殺者であり、私は奴についてかなりのことを知っている。\n\nMarzonは現在Lord Gregor Lescovarに雇われている。Stormwindの貴族の腐敗ぶりを考えてもなお、評判の怪しい主だ。", 0x57046a0a, 0x20fa1c0c, 0x29c82d75, 0x3a5dbaf1, 0x224c7373, "....." },
  [394] = { "獣の首", "StormwindのMathias Shawに話しかけて下さい。", "Old TownでShawを探せ。Lescovarの脅威は片付いたこと、そして街に対する卿の陰謀に君が関わっていたことを伝えるんだ。Stormwindの市民にまた一人英雄が加わって、彼もきっと誇りに思うだろう。\n\nおそらく彼は君を王子か他の貴族に会いに行かせるだろう。のぼせ上がるなよ、{name}。貴族どもは自分たちが街を治めていると好きなだけ思っていればいいが、奴らの手の届かないこともあるのだ。", nil, "では奴は死んだのか？君の裁きは迅速だったな、{name}。自分が君の獲物にならぬよう、光に祈るとしよう！\n\n<彼は笑い、あなたの肩を叩く。>\n\n批判のつもりはない、{name}。すべての暗殺者の師匠たるこの私が、どうして批判などできよう？だが実のところ、君はStormwindの民に大きな貢献をした。それに感謝する。", 0xe4545c03, 0xad70b6fb, 0x578303cb, nil, 0x2ab8dabc, "...m." },
  [395] = { "Brotherhoodの終わり", "StormwindのBaros Alexstonと話して下さい。", "ああ、忘れるところだった。君の留守中にAlexstonが来て、君と話したがっていた。Defias Brotherhoodの動向を貴族たちに報告したいのだろう。\n\n一つ助言しておこう、{name}。誰かに聞かれたら、詳細はすべて話していいが、Lescovarを倒したのが君の手だということだけは伏せておくといい。信じてくれ。私はこの手のことには……通じて……いるのでね。\n\nそれからTriasについては……誰にも彼のことは話すな……決して……できることならな。", nil, "会えて嬉しい、{name}。Lord Gregor Lescovarが少し前に死体で見つかったと聞いた。\n\n任務は成功したようだな。私を、そして他の多くの者を、VanCleefの復讐から救ってくれたことに感謝する。", 0x321120ba, 0xe768ecd1, 0x6cface0d, nil, 0xf4847567, "...m." },
  [396] = { "王との謁見", "Baros AlexstonのReport on the Defias BrotherhoodをStormwind KeepのKing Varian Wrynnに届けて下さい。", "王への報告書を用意しました。あなたが調べたことの報告と一緒に、あなた自身が届けるべきだと思います。心配はいりません。Stormwindの民への務めを果たしたあなたを、王は必ずお褒めになるでしょう。\n\n謁見の時間はもうすぐですから、急いだほうがいいですよ。Stormwind Keepまでは少し距離がありますから。", "{name}だね？ Baros Alexstonから君が来ると聞いていた。正直に言うと、君の話にとても興味があるのだ。", "Stormwindのために果たした働きは称賛に値する、{name}。VanCleefがその企みを成功させていれば、間違いなく王国に多大な害を及ぼしていただろう——それは当然避けねばならぬことだ。\n\nこれを受け取れ、{class}。王の感謝のしるしだ。王自身の手で渡せないのは残念だが、外交の使命で不在にしており、しばらくは戻らないのだ。", 0x6971d0c2, 0xfe7b374c, 0x8cfc5b31, 0x2434fd41, 0xb23a1117, "....." },
  [397] = { "よく尽くしてくれた", "Zardeth the Blackclawの従者、Zggiと話して報酬を受け取って下さい。", "Lord Wishockは飲み物を楽しんだそうだな。\n\nよく尽くしてくれた、{name}。お前のおかげで、Stormwindのウォーロックたちは邪魔されずに我らの道を修められる。お前の働きに報いるため、特別な贈り物を用意しておいた。私の従者、Zggiと話して、報酬を受け取るがいい。", nil, "主人、{name}に贈り物をやれと言う。Zggi、いい贈り物を自分のものにしたい。でもZggi、主人を裏切らない、よく分かってる。", 0xeaaf884a, 0x441331ba, 0x5147d5ea, nil, 0xa9142260, "...m." },
  [398] = { "指名手配：Maggot Eye", "Maggot Eyeを殺してその手を持ち帰ればBrillのExecutor Zygandが報奨金をくれるでしょう。", "指名手配：Maggot Eye！\n\nGnollということを割り引いてもなお不快な獣、Maggot EyeはForsakenに対する罪により死刑を宣告された。この卑劣な悪党はLich Kingの軍隊に供するために死体を盗んでいたのだ。Maggot EyeがBrillの北、Garren's Hauntの近くで略奪を働いているところを目撃されたのが最後である。\n\nBrillの町はここに、死刑執行をなしえるものに対して報奨金を出す。証拠として悪党の手をExecutor Zygandに渡してほしい。\n\n容赦はいらない。", "何か？", "Maggot Eyeは報いを受けたのだ。お前の勇気ある行動は我らに害なすものどもに明確なメッセージを送ったであろう。Brill市民を代表して感謝するよ、{name}。", 0x655d68ed, 0x0869dc49, 0x04ae2b05, 0x0c07a888, 0xe8743f8e, "....." },
  [399] = { "ささやかな始まり", "WestfallにあるBaros Alexstonの家へ行ってコンパスを探し、StormwindのCathedral Squareにいる彼のところへ返す。", "私がWestfallの農場で働く少年だったのは、もう永遠の昔のことのようです。人は決して昔には戻れないと言いますが、その通りですね。私の場合は二重にそうです。家族の家は焼け落ち、盗賊たちに奪われてしまったのですから。\n\n私の持ち物、その中には初めて持った羅針盤もあるのですが、その行方について父と話しました。父はそれを持ち出すことができなかったそうです。ですが、それは農場のどこかに隠してあるはずだとも言っていました。\n\nAlexston FarmsteadはSentinel Hillの西にあります。行って、取ってきていただけませんか？", "{name}！ うまくいったか？", "ああ、ありがとう、{name}! 実用的な価値はないのですが、思い出の品としての価値は……言うまでもなく、これを持ってきてくれて感謝しています……あなた自身の身を危険にさらし、はるばるWestfallまで行く時間までかけてくれたのですから。心から感謝します。お礼のしるしに、これを受け取ってください。", 0xe3c50bf4, 0xf6990729, 0x3d3b2003, 0x92e1e141, 0x3dfe9061, "....." },
  [400] = { "Steelgrillの道具", "Beldin SteelgrillにSteelgrill's Toolsを届けろ。", "Beldin Steelgrillは地元の整備工場の持ち主で、攻城兵器の技師としては右に出る者がいない！でも道具の扱いが荒くてね。こっちが納められる以上にarclight spannerを壊してるんじゃないかって、本気で思うよ！\n\nちょうど彼が最後に注文した道具をそろえたところなんだ。届けてくれたら、きっと手間に見合うお礼をしてくれるよ。\n\n彼の店、Steelgrill's DepotはKharanosのすぐ北東だ。それにベテランの攻城兵器乗りたちのたまり場だから、行ったら儲け話がないか耳を澄ませておくといい。", "ん？ 攻城兵器の操縦士にしてはちょっと若すぎるように見えるな。まあいい……何か修理が必要なのか？\n\nなら番号札を取って、楽にして待っててくれ。今はエンジンをいくつか手がけてて、少なくともあと数日は次の仕事に取りかかる暇がないんだ。\n\nそれとも、何か別の用だったか……？", "俺の道具を持ってきてくれたのか? よくやった、若いの、よくやった! ちょうど一時間前に最後のfang-ratchetを壊しちまって、Pilot Stonegearの攻城兵器の修理を終えるにはそいつが要るんだ。ここまで道具を運んできてくれて助かったよ、{name}。\n\nほら、手伝ってくれた礼にこの硬貨を受け取ってくれ。", 0x872f52ba, 0xc5e776cd, 0x841b2028, 0x849bd1d2, 0xfbff9b36, ".....", nil, nil, nil, nil, 0x7de665ab },
  [401] = { "Sirraが翻訳を終えるのを待て", "しばらく待ってから、再びSirra Von'Indiと話して下さい。", "手紙の翻訳はほとんど終わってるんだ。数分後に戻ってきてくれれば終わってると思うよ。", nil, "できた。翻訳された……\n\n<空気が重くなる。まるで厚く黒い帳が大地に引かれたかのように……>", 0xec04092d, 0xa17cff08, 0x5bacacc5, nil, 0x16c781dc, "...m." },
  [403] = { "警備されたThunderbrewの樽", nil, nil, nil, "このエールの樽はJarven Thunderbrewが見張っている。彼が地下室にいる限り、樽に手を出すことはできない。", 0xdf09604e, nil, nil, nil, 0x33af4f29, ".mmm." },
  [404] = { "腐敗した任務", "BrillにいるDeathguard DillingerにPutrid Clawを７つ渡してください。", "ScourgeがTirisfal Gladesに徐々に進入しBrillの西の古い橋の辺りを荒らし始めている。\n\nそこへ行き腐敗し、朽ち果てた死体どもを退治するのだ。奴らをばらばらにしてその腐った爪を取ってくるのだ。報酬はやる。", "私が命じた務めは果たしたか？ あのPutrid Clawは持っているか？", "よし。お前が腐り果てたアンデッドを打ち倒すさまを見れなくて残念だよ！", 0x2b4ec308, 0xfb2bd54c, 0x62cd09e5, 0x245a4768, 0x4519c29e, "....." },
  [405] = { "放蕩のLich", "UndercityにいるBethor IceshardにSevren's Ordersを渡してください。", "ここの南にあるUndercityにいる高位の魔法使いBethor Iceshardは、彼のもとへScourgeに対抗できるエージェントを送るよう私に命じておられる。{name}、貴様も資格ありだ。\n\nこの指令書をBethorに渡すのだ。お前の任務はそのとき告げられるだろう。詳しいことは知らんが、気まぐれなLichを雇い入れることに関してだろう。危険な任務だろうな。\n\n準備はいいかな、{class}。失敗は許されんぞ。\n\nUndercityのMagic QuarterにBethorはいるだろう。", "ごきげんよう。私が誰か知らないのか、それとも私への用事が急ぎなのか。\n\nそのどちらでもないなら、私の邪魔をするほど愚かではないはずだからな……", "ああ、お前がMagistrate Sevrenがよこしたエージェントか。そうかよし、お前の任務は重要だぞ。\n\nSevrenが期待はずれの奴をよこすまいからな。お手並み拝見といこうか。", 0xfee82a33, 0x956051d7, 0xf7ee88d1, 0xc24b95f7, 0x878ffdc4, "....." },
  [407] = { "悲しみの大地", "Laced PumpkinをGallow's End Tavernの地下室で拘束されているCaptured Scarlet Zealotのところへ持っていってください。", "かぼちゃに罪はないよな？そう思うんだが。北からのArthasの進軍や、南からの人間どもの横行に対抗しようと思うなら我ら\"死せるもの\"の最大限の可能性を理解しなくてはならん。\n\n少し手を加えたかぼちゃが我らのDark Ladyのための諜報員を生み出す。この最新の調理法で作ったかぼちゃがなかなかのものだとわかるだろう。\n\nさらに一人のScarlet Zealotが捕らえられ、Gallow's End Tavernの地下室に拘束されている。 あのあほうにこれを食わせてやれ。", "近寄るな、汚らわしく不浄なる者め！ 光よ、我を守りたまえ！ Scarlet CrusadeがAzerothから貴様の……\n\n……おや、待てよ。それは私への食べ物か？ 腹が減って仕方ないのだ……", "ありがたい！やっとメシか！甘い、甘いかぼちゃだな・・・。", 0x2932f488, 0x3ae020ed, 0x5fbf4409, 0x590d0a08, 0x95632aa4, "....." },
  [408] = { "家族の聖堂", "Wailing Ancestor８匹とRotting Ancestor８匹を倒してください。\n\nCaptain Dargolを倒して、彼の頭蓋骨をBrillにいるMagistrate Sevrenに渡してください。", "Agamand Mills一帯はScourgeの橋頭堡となりつつある。中でも厄介なのがやつらの方面軍司令官Captain Dargolという名のスケルトンが本部を置いているAgamand Family Cryptであろう。奴は降霊術を以てAgamandsの一族を目覚めさせ、われらに対抗しようと計画している。\n\n看過することはできん。なんとしても止めるのだ。Agamand Family Cryptへ行き、よみがえらせられしAgamandの一族を打ち倒すのだ。\n\nそして、Captain Dargolの頭蓋骨を持ってくるのだ。", "我々に時間の余裕はないのだ、{name}。時が経つごとに、Tirisfal GladesにおけるScourgeの支配はより強固になっていく。", "Scourgeは大ダメージだろう。お前の勝利は敵味方に聞こえ渡るだろう。\n\nこれからも励めよ、{name}。そしていつの日か我らはLich KingをAzerothからたたき出してやる", 0x66f94b22, 0x78a7f290, 0x657d58bb, 0x07b8e1b4, 0xaacae948, "....." },
  [409] = { "お前は味方か", "Candle of Beckoningを入手し、Lillith Nefaraを召喚し倒してください。\n\nそれからGuntherのもとへ戻ってください。", "お前はLich Kingの手下ではないといったが、Bethorが私の呪文書にかけた付与魔法がそのことを証明しているな。しかしそのことを信じる前に、おまえがScourgeの敵であるということを証明してもらわねばならん。\n\nこの島の南にある島に古びた、血まみれの祭壇がある。それは強力なScourgeのエージェント、Lillith Nefaraが使っていたものだ。\n\nここにある箱からCandle of Beckoningをとるのだ。祭壇でろうそくをともせば、Lillithは目覚めるであろう。Lillithを倒すのだ。そうすればお前がLich Kingの敵だと信じるだろう。", "お前の忠誠の証を待っているぞ、{class}。", "Lillith Nefaraを倒したか。Scourgeの敵だと証明できたな。信じられん。\n\n私だけが自由なアンデッドだと思っていたがな。しかしお前はほかにLich Kingの支配から逃れた人がいるということを教えてくれた。", 0xa4c93d97, 0x4be8db40, 0x7384925c, 0x4e450c0a, 0x42a35ea1, "....." },
  [410] = { "眠れるシェード", "古く、朽ち果てた血まみれのテーブルがある。", "なし。", "古びて傷だらけの、血まみれのテーブルだ。", "Candle of Beckoningをテーブルの上に置き火をつけた・・。", 0x860cba69, nil, nil, 0x6926ebe0, 0x9a85d915, "....." },
  [411] = { "放蕩Lichの帰還", "Nether GemをUndercityにいるBethor Iceshardに渡してください。", "このNether Gemを私の古き友、Bethorに渡すのだ。これで話ができる・・。話すことは山ほどあるぞ。", "Guntherに本は返してくれたか？ 彼から返事はあったか？", "成功したか！Forsakenに大きく貢献したぞ、{name}。Dark Ladyも知るところになるだろう。", 0xaea9b7a4, 0xfa36d7fb, 0x4d641943, 0x9d276ad6, 0xa985ef55, "....." },
  [412] = { "作戦復帰", "KharanosのRazzle SprysprocketにRestabilization Cog 8個とGyromechanic Gear 8個を渡して下さい。", "Gnomereganの状況をさらに分析したところ、我々はtroggsを根絶できなかっただけでなく、ノーム種族の大半をおぞましく、心を失い、悪事を働くleper gnomesに変えてしまったようだ。\n\nOzzieと私は、最新の発明品Recombobulatorで、このひどいleperの効果を元に戻そうと計画している。機械はほぼ完成しているが、Restabilization CogsとGyromechanic Gearsがどうしても必要なんだ。Gnomereganの前にいるleper gnomesから取ってきてくれ。", "Restabilization CogとGyromechanic Gearが十分に揃えば、すぐにRecombobulatorを稼働させられるよ。", "このGyromechanic GearsとRestabilization Cogsは、OzzieによるRecombobulation Deviceの設計図と完璧に一致しているよ。内燃ピストンにハイドロ潤滑剤を足して、クランクオラチェットを調整して、エレクトロガムジェルの粘度を上げれば、ノームという種族は元どおりになるさ。", 0xeb51823c, 0x9967013a, 0x65cd1925, 0x5da233c7, 0xc3725696, "....." },
  [413] = { "Shimmer Stout", "Barrel of Shimmer StoutをMountaineer Barleybrewに持って行ってください。", "兄弟のWellartに、わしの新作のShimmer Stoutを味わってもらいたいんだ。あいつはMountaineerで、南の見張り塔に詰めている。Loch Modanとの境にある2つの塔のうちの1つだ。\n\nわしらBarleybrew家のほかの者と違って醸造家ではないが、酒には目がない。これもきっと気に入るはずだ。\n\nこのBarrel of Shimmer Stoutを届けてくれんか？", "やあ、{class}！ こんな所まで何の用で来たんだい？\n\n何か面白いことだといいんだがな。もう何日もまともな喧嘩をしてないし、このエールの樽もほとんど空っぽなんだ……", "<Mountaineer BarleybrewはShimmer Stoutを味見する……>\n\nおお。うわっ！こいつは本当に目が輝くな。暗闇でも見えそうな気がするぞ！", 0xb36fea29, 0x8e29116f, 0xc2c58cab, 0xb59d2e44, 0xe387b846, "....." },
  [414] = { "Kadrellへのスタウト", "Cask of Shimmer StoutをMountaineer Kadrellに持って行ってください。", "兄弟が造ったShimmer Stoutをまた飲んでいるんだが、こいつは最高だ！仲間の山岳兵にも飲ませてやりたい。名前はKadrellで、たいていLoch ModanのThelsamarを通る道を巡回している。\n\nThelsamarへ行くには、トンネルを抜けて南東へ進み、小道が分かれて街道になったところで北東へ曲がる。その街道をまっすぐ行けばThelsamarだ。\n\nMountaineer KadrellにこのCask of Shimmer Stoutを渡して、感想を聞いてきてくれ！", "ようこそ、{class}。Thelsamarへよく来たな！", "さて、ひとつ味見させてもらおう……\n\nMagni's Beard！こいつは頭がくらくらするぞ！それに手足も軽くなる。\n\n空だって飛べそうな気がする！", 0xd20ea02e, 0xeed35031, 0x40ac0d91, 0xffeabd23, 0x91b650e9, "....." },
  [415] = { "Rejoldの新しいビール", "Rejold Barleybrewと話す。", "Brewnall VillageのRejold Barleybrewが、あんたに会いたがってたぞ。\n\n新しく醸造している酒のことで話がしたいそうだ……あんたにそれを手伝ってもらうとか何とか言ってたな。Brewnall Villageに戻って、あいつの話を聞いてみるといい。\n\nただ酒にありつけるかもしれないぞ……", nil, "{name}! 持ってきてくれたShimmerweedを覚えてるかい? 取り組んでいたレシピのいくつかに使ってみたら、ひとつがすごくうまくいったんだ!\n\nほら、試してみて感想を聞かせてくれよ……", 0xe805c4ca, 0x2b9ce38c, 0x1d773d33, nil, 0xb5fafd9a, "...m." },
  [416] = { "ネズミ捕り", "Tunnel Rat Earを12個、ThelsamarのMountaineer Kadrellのところへ持って行く。", "西のほうで本当に厄介な蔓延が起きている。tunnel rat koboldどもが丘陵地帯に入り込み、巣を作っては汚物で我々の土地を汚しているんだ！\n\n奴らを始末してほしい。奴らを狩ってearsを持ってくれば、賞金を出そう。\n\ntunnel rat koboldどもとその巣は、Thelsamarの西、山腹のあちこちに散らばっている。", "やあ、{name}。ネズミ捕りの調子はどうだ？", "うえっ! あの耳を頼んだときは、こんなに臭いとは思わなかった!\n\nこれが報酬だ、{name}。よくやった。", 0x63070b4c, 0x45c146d7, 0x5b4e949e, 0x46cea726, 0x1e9a33db, "....." },
  [417] = { "パイロットの復讐", "Mangeclawを倒す。\n\nMangeclawのMangy ClawとHildelve's JournalをPilot Hammerfootのところへ持って行って下さい。", "Hildelveは日記に、「巨大なIce Claw Bear」のMangeclawに襲われたと書いていた。彼は獣を追い払ったが、その前にひどく傷を負わされていた。\n\nHildelveの遺体の状態からすると、Mangeclawは後で戻ってきて彼を殺したに違いない。\n\nだがHildelveは、日記に最後のただ一つの願いを書き残していた。\n\nMangeclawへの復讐を。", "こんにちは、{name}。私の友Hildelveについて何か知らせはあるか？", "これは痛ましい知らせだ。Hildelveは良き友だった。そしてお前があの獣、Mangeclawを見つけたとき、共にいられたらよかったのに！\n\nありがとう、{name}。お前の行いはIronforge Siege Brigadeの操縦士たちに記憶されるだろう。", 0xc8a157ff, 0xfc8ba3ba, 0x36d8afa5, 0x86e8914d, 0x2e3d6b6c, "....." },
  [418] = { "Thelsamarのブラッドソーセージ", "Bear Meatを3切れ、Boar Intestinesを3個、Spider Ichorを3個、ThelsamarのVidra Hearthstoveのところへ持って行く。", "ここThelsamarじゃ、腹を空かせた連中に事欠かないよ。子供たちは出たり入ったりするし、発掘現場の作業員たちはきつい一日の仕事を終えてやって来る。うちはブラッドソーセージで有名なんだけど、食べたことはないだろうね？\n\nない？ まあ、ここじゃ食事にありつくには働かなきゃならないんだ。ご立派な{class}だからって、自分だけは例外だなんて思わないでおくれよ。\n\nbear meatと、腸詰めの皮にするboar intestinesと、香辛料にするspider ichorが要るんだ。それを持ってきてくれたら、料理はVidraに任せておきな！", "料理を始める準備はすっかりできてるよ。材料は持ってきてくれた？", "本当さ、見た目よりずっと難しいんだが……\n\nおや、ソーセージ作りにそこまで興味を持つ人には会ったことがないが、念のためレシピをあげよう。はい、どうぞ。新鮮なうちに食べるんだよ!", 0xa87d8ad8, 0x3da74c62, 0x0fbff557, 0x6090d9ed, 0x9a0355ae, "....." },
  [419] = { "消えたパイロット", "Pilot Hildelveを見つけろ。", "友人で同じSiege Engine乗りのMori Hildelveが、丘で行方不明になっている。上等なblastpowderに必要な珍しい鉱石を探していたんだが、探している途中で、あいつが自分の機体を急な丘に乗り上げて壊しちまったんだ！\n\nそれでも鉱石はこの山にあると信じていたHildelveは、わしに機体の見張りを任せて、自分は歩いて探しに行った。\n\nもう何日も経つし、夜には丘から獣のうなり声が聞こえる。Moriはタフな奴だが、心配でな。\n\n頼む、{name}。あいつを見つけてくれ。", nil, "ここにドワーフの死体がある——食い荒らされ、凍りつき、山の腐肉喰らいに骨まで漁られている。その手に握られているのは、Mori Hildelveの荒く走り書きされた覚書が記された本だ。そして体には、いまだ極めて良好な状態のBrigadier's Vestが纏われている。\n\nこの凄惨な光景こそ、Siege Engineの操縦士が最期を迎えた場所に違いない。", 0x7f8b701c, 0x19886134, 0x7506a7ac, nil, 0x78eadffd, "...m." },
  [420] = { "Senirの観察", "Grelin's reportをKharanosにいるSenir Whitebeardへ届けろ。", "トンネルのtroggsはひどく凶暴で、トンネルを通る旅人をためらいなく襲ってくる。だが君は十分たくましそうだから、たぶん大丈夫だろう。\n\n道順か？Senirに会いに行くなら、彼はKharanosにいる。\n\nトンネルを抜けて反対側に出たら、あとはひたすら道をたどっていけ。そのままKharanosに着く。", "調子はどうだい？ よかったら一杯付き合わないか？ この寒さじゃ、他にやることもあまりないしな。", "これは何だ？ああ、兄弟の報告書か。ふむ……\n\n王の名を使うのは控えめにしろと言っておいたのに、聞かなかったな。まあ害はあるまい、Senateで何人かの機嫌を損ねるのは確かだろうが。もっとも、損ねられて当然の連中だがな！はっ！\n\nとはいえ、それは私も報告書をIronforgeへ送るべきだということだろう。だが正直に言えば、少し遅れている。ひどい寒さでな。\n\nその気があれば、後で仕事を用意できるはずだ。", 0x034f6959, 0xd1c8fc65, 0x507d5ef4, 0xd802ec21, 0xf5afd554, "....." },
  [421] = { "戦士の証明", "SepulcherのDalar DawnweaverはMoonrage Whitescalpを５体倒すことを望んでいる。", "Lady SylvanasはVarimathrasに南の人間と、ドワーフどもの土地を征服せよと命じた。\n\nしかしあのあほう、Arugal(Dalaranのにせ医者にして、いまはShadowfang Keepののろわれた獣)――奴のむちゃくちゃな魔法によりSilverpine Forestの戦略拠点が破壊された。\n\nこのArugalによる混乱を収めるには熟練の戦士が必要だ。Moonrage Whitescalpを5体倒し、お前こそがそうだと証明して見せろ。醜い獣どもはこの丘の下の道を外れたところ辺りにいるだろう。", "私に実力を証明したいなら、Moonrage Whitescalpを5体倒さねばならない。それを成し遂げれば、君の腕をもっと価値ある任務に生かせるよう取り計らおう。", "よくやってくれたね、{class}。Silverpine ForestからArugalの災いを取り去るのに、お前は立派に役立つだろう。", 0x4165cc3c, 0xa3af291f, 0xc69e0e06, 0x78467694, 0x2fbdf2d6, "....." },
  [422] = { "Arugalの愚行", "Remedy of Arugalを回収し、SepulcherのDalar Dawnweaverに渡してください。", "ArugalがどうやってKirin Torに受け入れられたのか、私には見当もつかない。やつの呪文の知識など、吹きガラスの玉のように透けて見えていたというのに。\n\n今肝心なのは、Arugalが使った魔法が何なのかを正確に突き止めることだ。そうすれば、それをやつ自身に向け、Dark LadyのためにSilverpine Forestを確保できる。\n\nArugalは最初、橋のすぐ北にある小麦農場に滞在していた。Deathstalkerの一人が呪文書を何冊か見たと報告してきたが、確保はできなかった。その書物から、Remedy of Arugalと記された呪文を取ってきてくれ。", "ここで何を相手にしているのかを知るには、{class}、Remedy of Arugalとして知られる呪文を研究する必要がある。今すぐそれを持ってこい。さもなくば、もっとふさわしい下僕を探さねばならなくなるぞ。", "これぞまさしく私が探していたものだよ、{class}。Dark Ladyへの献身が不変のものであるなら、Forsakenにとってお前は希望の星であろう。", 0x93f7323d, 0x13790612, 0x0abc03a5, 0x8be8400a, 0x953bc065, "....." },
  [423] = { "Arugalの愚行", "Glutton Shackleを６個と、Darksoul Shackleを３個SepulcherのDalar Dawnweaverに渡してください。", "Arugalの行為を調べた結果、私の悪い予感は確信に変わった。あの老いぼれはKirin Tor最大の危機のときに代表を務めるどころか、Dalaranの便所掃除にすら向いてなかったろうよ。あほうめが！\n\nArugalは彼の脆弱な魔法を補うのにエンチャントされたアイテムを使った。この手でそのアイテムを調べる必要がある。調査に必要な数のエンチャントされた足かせ(Shackle)をMoonrage GluttonとMoonrage Darksoulを倒して集めてくるのだ。おろかな生き物どもは北か東のほうにいるだろう。", "状況を見極め、Arugalへの最終的な解決策を練るには、Glutton Shackleが6個とDarksoul Shackleが3個必要だ。さあ、命じられた通りにMoonrage GluttonとMoonrage Darksoulを倒し、必要なものを集めてこい。", "この数で十分なエネルギーを得られるだろうかな？もっと取ってきてもらえばよかったよ。\n\nとはいえ、十分な働きだったよ、{class}。", 0x93f7323d, 0xd7d800f3, 0x1e48bc9c, 0x5a525c19, 0x264fea1f, "....." },
  [424] = { "Arugalの愚行", "Grimson the Paleを殺し、彼の首をSepulcherのDalar Dawnweaverに渡してください。", "Arugalの使った魔法の秘密を探るのには思ったより時間がかかりそうだ。\n\nその間にDarkstalkerが見つけたちょっとした問題を片付けてほしい。Arugalは彼の魔法を南東の丘にあるDeep Elem Mineにまき散らしたようだ。\n\nその鉱山にはVarimathrasの進軍のために必要な資源があるのだ。\n\nその鉱山ののろわれた監督官、Grimson the Paleの首を取ってくるのだ。奴がいなければ、あの鉱山は我らのものだ。", "Grimson the Paleは始末したか？ 彼の命令を無視すれば、Varimathrasは喜ばないだろう。", "すばらしい。あの鉱山はわれらがSilverpineそしてAzeroth全域に兵を進めるのに十分な資源を供給するだろう。", 0x93f7323d, 0xa3cab538, 0x20158451, 0x4d00d6bf, 0xabedee59, "....." },
  [425] = { "Ivar the Foul", "Ivar the Foulを殺し、Ivar's HeadをIvar PatchにいるRane Yorickに渡してください。", "私とわが兄弟QuinnはHigh Executor HadrecにSilverpine Forestを偵察し、報告することを命ぜられた。しかし我らはそう遠くまでいけなかった。この農場を移動中にあのghoul、Ivar the Foulの攻撃を受けたのだ。\n\n我らはIvarから逃れた。しかしQuinnはやつにより深手を負った。彼はあなたがくれた薬で治るでしょう。しかしQuinnが回復する前にIvarが戻ってくるかもしれない。\n\nIvarを殺してくれれば、Quinnが回復する時間が稼げる。Ivarはたいてい向こうの納屋の中で、私が弱るのを待っている。", "Ivar the Foulは殺したか？ 私と兄弟のためにやる気がないなら、Forsakenのためにやってくれ。", "ああ、ありがとう。感謝するわ、{name}。\n\n報告書にもあなたのことを書いておくわ。", 0xd4799367, 0x19bd6f46, 0x3025cc30, 0x30e68483, 0x37affe37, "....." },
  [426] = { "死霊あふれしMills", "Notched Rib５個と、Blackened Skull３個を集めて、BrillにいるDeathguard Dillingerの元へ戻ってください。", "ScourgeがAgamand Millsに基地を築こうとしている。そうなったらTirisfal中に更なる攻撃が加えられることになるだろう。\n\n指令が下った。MillsにいるScourgeを倒すのだ。\n\nMillsに行け。RattlecageとCracked Skull SoldierからNotched Ribを、Darkeye BonecasterからBlackened Skullを集めてくるのだ。\n\nMillsに行くには道なりに西へ行け。橋を渡ったら次の分かれ道を北へ行け。そのまま北だ。風車が見えたなら、戦闘開始だ。", "Scourgeとの戦いは続いているのだ、{name}。自分の役目を果たし、あの呪われた、心なきアンデッドどもをPlaguelandsへ押し戻してこい！", "お前の活躍は広まっているよ、{name}。改まって感謝はしないが、TirisfalのDeathguard連中はお前の名を忘れはしない。", 0xf1b26f58, 0x6633a1b4, 0x3c638478, 0xd0a18bbd, 0x4238abe0, "....." },
  [427] = { "Scarlet Crusadeとの戦争", "BrillのExecutor ZygandはScarlet Warriorを10人殺してくることを望んでいます。", "Executor Arrenがもたらしたこの文書は卑劣なScarlet Crusadeに対する戦局を打開するであろう。Tirisfal Gladesにおける奴らの正確な配置を知ることができた。\n\nしかしDeathguardは手一杯だ。Lich Kingの軍隊は夜毎その数を増している。お前のように『実行力』のあるものにScarlet Crusadeを墓に入れてもらわねばならん。\n\n西のSolliden Farmsteadを超えたところにある塔に行きScarlet Warriorを10人殺し、Dark Ladyにとってお前が役立つものだと示すのだ。", "Dark Ladyに己の価値を証明したいなら、Scarlet Warriorを10体倒してこい、{class}。", "なんとも素晴らしい、{class}。戦闘技術はなかなかのもんだ。", 0x5aa72e8b, 0x6e2fd180, 0x4814c47e, 0x8852c390, 0x35635107, "....." },
  [428] = { "行方不明のDeathstalkers", "Deathstalker QuinnとRane Yorickを捜してください。", "２週間前、二人のDeathstalker、RaneとQuinn YorickをSilverpine北方の偵察に送り出した。しかし連絡がない。\n\n彼らはScourgeの犠牲になったかもしれない。だがその確証がほしい。彼らを捜してくれないか。\n\n最初の目的地はSilverpine北の農場だった。そこからはじめてくれ。", nil, "見つけてくれたか！本当にぎりぎりのところだった……", 0x8d08680c, 0xde9b51c9, 0x0e702215, nil, 0x7b7112cf, "...m." },
  [429] = { "ワイルドハート", "discolored worg heartsを３個採取し、SepulcherのApothecary Renferrelに渡してください。", "わが兄弟Quinnはあのグール、Ivar the Foulに手ひどくやられた。錬金術の助けを借りなければ治せないだろう。 しかし私は薬剤師ではない。薬剤師であればWorgの色あせた心臓から治療薬を作ることができるだろう。\n\nそれを採取して、南のSepulcherにいるApothecary Renferrelに渡してください。そして薬を持って戻ってきてください。\n\nWorgは東のMalden's Orchardとここの間一帯にいます。", "私には時間がないのだ、{class}。Dark Ladyから重大な任務を命じられているのでな。", "<Renferrelは心臓を受け取った。>\n\nDeathstalkerたちが任務に失敗していたとは、頭の痛いことだ。\n\nめったにないことと希望しよう。\n\n薬はすぐに用意しよう。・・レシピを渡しておこう。将来Deathstalkerたちが手助けを必要とするときは、君が作ってやるのだ。", 0x46265aa8, 0x468e1442, 0x0b973e29, 0xe2c1ed4b, 0x14750494, "....." },
  [430] = { "Quinnのもとへ", "Sepulcherの北、Ivar PatchにいるQuinn Yorickに薬を持っていってください。", "これがQuinn Yorickの回復を助ける薬だ。\n\nでは失礼するよ。続けねばならない非常に大切な仕事があるのでね……", "私の姉妹から、あなたが私たちを助けに来てくれたと聞いた。本当か？", "<Quinnは薬を手に取り、飲んだ。>\n\nよし、効いてきた。じき動けるようになるだろう。\n\n感謝するよ、{name}。", 0xf0dc2596, 0xed042c3f, 0x57f627f0, 0xf2d24222, 0xc5dd8287, "....." },
  [431] = { "Candles of Beckoning", nil, nil, nil, "ろうそくを1本手に取り、荷物にしまう。", 0xb1929f4a, nil, nil, nil, 0x2a34be75, ".mmm." },
  [432] = { "いまいましいTroggsめ!", "Gol'Bolarの採石場のForeman Stonebrowのために、Rockjaw Skullthumpersを$N1体倒す。", "光に見放されたtroggどもめ、わしの作業場をめちゃくちゃにしおって！見ろ、また爆薬の樽が吹っ飛んだぞ！\n\nああ、あそこへ下りていって、あいつらの痩せっぽちの首を残らずへし折ってやりたい！皆殺しにしてやりたい！\n\nこんなにストレスと怒りばかりでは体に悪い……あいつら、わしに何を残した？何もない！\n\n自分で始末したいところだが、もう狙いが定まらんのだ！石切り場へ行って、あの汚らわしい奴らを何匹か殺してくれ！金は払う！とにかく痛めつけて、殺してくれ！", "本当に腹が立つ！ ぐるるる……", "まあ、それで少しは気が晴れた……\n\nだが奴らが皆死ぬまでは満足できん！一匹残らずだ！", 0xa38a8583, 0x70f60209, 0xd7fa5983, 0xcd9b49ca, 0xda5abbb8, "....." },
  [433] = { "公務員", "Gol'Bolarの採石場のSenator Mehr Stonehallowのために、Rockjaw Bonesnappersを$N1体倒す。", "SenateとExplorers' Leagueの一員として、我らの国土を蝕むtroggの蔓延のうち、この一帯の始末は私が引き受けることにした。\n\n奴らはGol'Bolarの石切り場をすっかり荒らしてしまった。それも何の理由もなくだ。我々が大地を深く掘り進めると、奴らがあふれ出てきて、機材を壊し、鉱夫たちを追い出した。もはや奴らを根こそぎ駆除し、立て直して、仕事に戻るほかない。\n\ntroggの件で力を貸してくれれば、君の時間に喜んで報いよう。", "Gol'Bolarの採石場からtroggを追い払えれば、この脅威を取り除くために我々がやらねばならない多くの段階の、最初の一歩になるだろう。", "これは始まりだ。うまくこれを活かして、Mountaineersを何人か送り込んでこの一帯を確保したい。そうすれば我々の設備の復旧に取りかかり、鉱夫たちを仕事に戻せる。\n\n手を貸してくれて感謝する、{name}。", 0x23152624, 0x52f72970, 0xdd9ed5fb, 0xf528dd76, 0xc92f32fa, "....." },
  [434] = { "攻撃!", "Lord Gregor LescovarとMarzon the Silent Bladeが会話を終えるまで庭に待機して下さい。その後、二人を殺してからStormwindのElling Triasのもとへ戻って下さい。", "Spybotに変装させたら、あいつがLescovarと話しに行く。衛兵は問題なく通すはずだ。\n\n君が材料を集めてくれている間に、私はMarzonに、Lescovarと再会する時が来たと伝えておいた。ついでに偽の情報も流しておいたよ。\n\nLescovarは衛兵を下がらせ、ここの庭でMarzonを待つはずだ。Defiasについての話が聞こえたら、行動に移ってくれ。衛兵が戻る前に二人とも殺さなければならない！終わったらTriasに話してくれ。", "何だい、{name}？ Tyrionとはうまくいってる？ 彼から事情は聞いてるし、Marzonを騙して城へ行かせる手伝いもしておいたよ。\n\nMarzonはStormwindの多くの人々にとって悩みの種でね。その中には私の親しい友も大勢いる。私の友に手を出す奴は許さない……身のためを思うならね。\n\nただ、そのついでに間接的にShawとSI:7に恩を売ることになるのが残念だけど。まあいいさ、完璧な計画なんてそうそうないからね。", "では済んだのか？よろしい。慎重に事を運んでくれて大いに感謝する、{name}。君は一つならず、その価値を証明した。Alliance内での君と君の進展には、目を配っておくとしよう。\n\n身ぎれいにしておけよ。", 0xdc0ceea9, 0x91a3233e, 0x71af2a8a, 0x065d5a10, 0xeeafb6f9, "....." },
  [435] = { "Erlandを護衛せよ", "Erlandを狼の群れの中をRane Yorickのもとまで護衛してください。", "狼どもが外をうろついて立ち去ろうとしない。奴らは私がいつドアの外へ出てくるか四六時中見ている。奴らは私がうまそうだと思うほど、腹をすかせているに違いない。\n\n同僚のDeathstalker Rane Yorickに報告に行かなきゃならない。Raneのもとへ行くには、奴らに対する助けがいる。\n\n私を護衛してくれないかね！外には多くの狼がいる。助けてくれる人手が多ければより安心だがね・・・", "手短に頼みます。辺りは危険に満ちていて、立ち話をしている余裕はありません。", "手助けありがとよ、{name}。ErlandがSilverpineの脅威にやられたんじゃないかと心配していたんだよ。君の助けがなきゃ奴には会えなかっただろうよ。", 0xd56111cc, 0x1d0e5dcf, 0x938665ef, 0xff823412, 0xaae0989d, "....." },
  [436] = { "Ironbandの発掘", "Explorer Fellhewと話す。", "Prospector Ironbandが湖の東で古代遺跡の発掘を指揮している。だが最近は作業の進みが遅い。我々が送った物資の量を考えればなおさらだ。\n\nIronbandは頑健で正直なドワーフで、結果を重んじる男だ。だからこそ、何かの力が彼の邪魔をしているのではないかと心配なのだ。\n\nIronband's Excavationへ行って、Magmar Fellhewと話してくれ。彼が現場の細かいことを取り仕切っているから、作業が遅れている理由を知っているだろう。\n\n発掘現場へ行くには、湖の南端を回ってから東へ向かえ。", nil, "Jernが遅れの理由を知りたがってるって?\n\nIronbandが詳しい最新の進捗報告をまとめているところだが、これだけは言える。\n\nTroggsのせいだ!!", 0x2c4f5a39, 0x18791172, 0x721d5d65, nil, 0x7334fe2a, "...m." },
  [437] = { "The Dead Fields", "Dead FieldsにおいてRot Hide Gnollを倒してください。\n\nNightlashが現れたら、彼女を倒してください。\n\nEssence of Nightlashを入手し、SepulcherのHigh Executor Hadrecに渡してください。", "Silverpineにおける初期の偵察報告に、Dead Fieldsと呼ばれるここから北にある古びた農場にRot Hideどもが拠点を構えている、というのがあった。何回か攻撃を試みたが、いつもやつらは魔法を使うbanshee、Nightlashの援護を受け撃退されてしまう。\n\nNightlashを倒さねばならん。\n\nDead Fieldsへ行きRot Hideどもを蹴散らせ。Nightlashの姿が見えなくてもRot Hideどもを倒していればやがて姿を現すだろう。そのときは彼女を倒せ。\n\n彼女の魂は塵に変化するだろう。証拠としてそいつを持ってきてくれ。", "Nightlashは倒したか、{name}？ rot hideとの戦いに勝てるかどうかは、奴を滅ぼせるかにかかっているのだ！", "うまくいったようだな、{name}。Nightlashの死の証も手に入れたようだな。\n\n今日この日、Scourgeは拠点を失ったのだ。Forsakenは君に期待している。", 0x19a0e0e1, 0x94c5883b, 0xcad784a9, 0x0ae8e887, 0xfa2a4b70, "....." },
  [438] = { "朽ちかけた渡し船", "Decrepit Ferryへ行く。\n\nScourgeがそこにいる理由を探る。", "{name}、Scourgeの新たな巣窟を見つけた。Decrepit Ferryだ。その渡し場はSepulcherの東にあり、rot hideをはじめとするアンデッドどもが厳重に巡回している。\n\nScourgeがあの一帯を占拠しているのには理由があるはずだ。Decrepit Ferryへ行き、Scourgeがそこにいる理由を突き止めろ。", nil, "この舟には布に包まれた死体が山積みになっている。そしてLordamere Lakeの東を見渡すと、向こう岸のFenris Isleに船着き場が見える。\n\n死体の行方はFenris Isleにあるに違いない。", 0x97530730, 0xbfa7d2d4, 0x8d58e9c8, nil, 0xe0ee0465, "...m." },
  [439] = { "Rot Hideの手がかり", "Deliah's RingをSepulcherのHigh Executor Hadrecのところへ持って行く。", "死体の中から、包帯の巻かれていない手が一本突き出している。女の手で、疫病によるあばたがあるが、比較的新しい。\n\nその手には指輪がはまっている。指輪を外して調べてみると、文字が刻まれていた。\n\n「Deliahへ」", "{name}。戻ったということは、調査は実を結んだのだな？", "この指輪は最近殺された女がはめていたというのか?\n\nこの近くでそんな死体が出る場所といえば、Tirisfalの集団墓地しかない。Rot Hide Gnollsがその死体をFenris Isleへ運んでいるに違いない!", 0x289840ab, 0xd59dacd7, 0x784cd106, 0x6fc0f68a, 0xde42ded4, "....." },
  [440] = { "刻印された指輪", "Deliah's RingをBrillのMagistrate Sevrenのところへ持って行く。", "Deliahに指輪を贈った夫か恋人を探したいのなら……BrillにいるMagistrate Sevrenと話すといい。彼なら最近の死者の記録を持っているはずだし、運が良ければDeliahが誰なのか突き止められるだろう。\n\nだが期待はしないことだ。彼女に指輪を贈った者はおそらく死んでいる。あるいはアンデッドになっているなら、もうDeliahのことなど気にもかけていないだろう。", "やあ、{name}。何の用でBrillに戻ってきたんだい？", "確かに、少し前までBrillにDeliahという女が住んでいた。彼女は集団墓地に埋葬されたが、お前の言うことが本当なら、Rot Hide Gnollsが彼女の遺体を盗み、Silverpineへ運んだに違いない。\n\nRot Hidesは、他のScourgeと同様に滅ぼさねばならん。そのための手を打ってくれていると信じているぞ。", 0x9c594b06, 0x3b544afb, 0x37390a55, 0x8f05840a, 0x92cc36a4, "....." },
  [441] = { "RaleighとUndercity", "Deliah's RingをRaleighのところへ持って行く。", "Deliahには夫がいた。Raleighという男で、今はUndercityに住んでいる。Brillに住んでいたDeliahがこの指輪の持ち主なら、Raleighが知っているはずだ。\n\nRaleighはUndercityのTrade Quarterにいる。", "どこかで会ったか？", "ああ、この指輪は妻のものだ。妻の運命は、この過酷な時代に耐えられなかった者すべての運命だ。彼女の死にも、遺体が奪われたというお前の話にも、私は何も感じない。\n\nそうした感情は、とうの昔に私の中で冷え切ってしまった。だが、この死んだ心にはまだ燃える欲望がある、{name}。\n\n復讐への欲望がな。", 0xf2f8becb, 0x2a2120e4, 0x68a8bdd5, 0x879570ca, 0xc3ca1109, "....." },
  [442] = { "Fenris Isleの襲撃", "Thule's HeadをSepulcherにいるHigh Executor Hadrecに持っていく。", "今こそSilverpineのScourgeの力の源Fenris Isleを叩く時だ。\n\nおまえはもう一度島に戻りThule Ravenclawを倒してくるのだ。そして奴の首を取ってこい！\n\nこの任務にはかなりの危険が伴う、{name} 失敗は許されん！", "ScourgeをSilverpineに居座らせておくわけにはいかん、{name}。Thuleが死んだという証を手に入れたら戻ってこい。", "Thule Ravenclawの死は小さな出来事ではなかった、{name}。Renferrelによれば、お前がThuleを滅ぼした時に放たれた力は、遠くSepulcherでさえ感じられたそうだ。\n\nお前の行いはForsakenの隊列に響き渡っている。我々にとってのお前の価値は増すばかりだ。", 0x8c0400d6, 0x90739e69, 0xcc5d4db1, 0xeecb06e8, 0x3df470a5, "....." },
  [443] = { "Rot Hide Ichor", "rot hide ichorを8瓶、SepulcherのApothecary Renferrelのところへ持って行く。", "Fenris Isleへの攻撃を仕掛ける前に、rot hideのgnollどもの背後に誰がいるのか突き止めねばならない。我々の薬剤師たちは、奴らの起源が奴らの体を流れる奇妙な体液にあると考えている。\n\nDecrepit Ferryの東にあるFenris Isleへ行き、そこにいるgnollどもからrot hide ichorを集めろ。それを、Sepulcherの外に駐在しているApothecary Renferrelのもとへ届けるのだ。", "rot hideの体液は持っているか、{name}？", "よろしい。この体液はrot hidesの性質を理解する助けになり、奴らの弱点を明かしてくれるかもしれん……\n\n……弱点があるならばな。", 0x90b269c6, 0xd63f7b63, 0xdc2829eb, 0xac2920ec, 0xf7c5204c, "....." },
  [444] = { "Rot Hideの起源", "Sample IchorをUndercityのBethor Iceshardのところへ持って行く。", "お前が持ってきた体液を煮詰め、基本成分に分離した。結論は出ていないが、その体液の生成にウォーロックの魔法と死霊術が使われたことは突き止めた。\n\n私が体液の研究を続ける間に、サンプルをUndercityのBethor Iceshardへ届けてほしい。Bethorは薬剤師ではないが、彼の魔法の知識がrot hideの謎を解く助けになるかもしれない。\n\n行け。BethorはUndercityのMagic Quarterにいる。", "私の研究には大変な集中力が要るのです。ですから、あなたの訪問がくだらない用事でないことを願いますよ。", "この物質には強力な呪文が織り込まれている。中には、長い、長い間目にしていないものもある……\n\n少し待て――占いの呪文を唱えねばならん……", 0xd15f0da4, 0xdd620190, 0xb0943b84, 0xf5eccafc, 0xa52b889f, "....." },
  [445] = { "調査報告の配送", "Silverpine ForestにいるApothecary RenferrelにApothecary Johaan's findingsを渡してください。", "時間の浪費はLady Sylvanasの旗の下に集う我々にとって許されることではない。お前もすでにわかっているだろう？\n\nRoyal Apothecary Societyの一員として、私と同僚の知識を合わせていつの日かDark Ladyが切望している新しい災いをあの方に贈呈するのは私の義務である。\n\nこの調査結果をSilverpine ForestにあるSepulcherにいるApothecary Renferrelに渡すのだ。Brillから南へ道なりに行け。Undercityから南西に行くのだ。", "私に何の用だ、{class}？", "ああ、Apothecary Johaanが調査結果を送ってきたのかい。ここSilverpineではとても多くの新しい現象が起こるのでLordaeronとTirisfal Gladesを離れてから調査結果のことはほとんど忘れていたよ。思い出したよ。Necropolisにすぐこのサンプルを渡さなければ。\n\nだが、とりとめのない話ですまないね。Silverpineにしばらくいるがいいさ、{name}。あんたのような強壮な{class}がこのあたりでいるんだ。", 0x2e8b0154, 0x1c9b0cbd, 0xb9cda9ec, 0x3e97b540, 0x3ac792af, "....." },
  [446] = { "Thule Ravenclaw", "Bethor's ScrollをSilverpine SepulcherのApothecary Renferrelのところへ持って行く。", "このIchorは、私の古い同僚が作ったものだ。Thule Ravenclawだ。大戦の前、奴は将来有望な若いメイジだった。だがLich Kingが力を得ると、同胞を裏切ってScourgeと手を結んだのだ。\n\n奴がまだ生きていたとは、しかもRot Hidesを率いて我々を襲撃しているとは、思いもしなかった！\n\n私は奴の呪文を数多く知っている。それに対抗する薬の調合を手伝えるだろう。この巻物をApothecary Renferrelのもとへ持ち帰れ。薬に必要な呪文が記してある。", "ごきげんよう、{name}。Bethorは何と言っていた？", "この巻物には強力な魔法が込められている。こんな力を薬に使ったことはない……強力な調合薬になるだろう。Fenris Isleの砦にいるThuleを襲うなら、きっと役に立つはずだ。", 0x57daa6c7, 0x59967169, 0x042f5571, 0x8927eab0, 0x7025b4ee, "....." },
  [447] = { "死のレシピ", "Grizzled Bear Heartを6つ、samples of Skittering Bloodを6つ集めてUndercity内のMaster Apothecary Faranellに届けよ", "Arthasの軍勢は圧倒的だ。だがNew Plagueがあれば、Scourge Armyも人間どもという害虫も、きっぱりと根絶やしにできる。\n\n私の研究で、クモの血とgrizzled bear heartから抽出した毒素を組み合わせると、致死性の霊薬ができることが証明された。北西のSkittering Darkのクモと、Silverpine Forest一帯をうろつく熊から試料を集めてくれ。その試薬をUndercityのRoyal Apothecary SocietyにいるMaster Apothecary Faranellに届けるのだ。", "よう、{class}。Royal Apothecary Societyに何の用だ？", "Apothecary Renferrelが君をよこしてくれるとは気が利いている、{name}。これらの標本は確かに我らの大義の役に立つだろう。すぐにその毒性と汚染性の研究に取りかかるとしよう。", 0x9bd96087, 0x208db28d, 0x5edf7be6, 0x15bc577b, 0x367733d6, "....." },
  [448] = { "Hadrecへの報告", "SepulcherのHigh Executor Hadrecに報告する。", "Fenris Isleへの攻撃を仕掛ける前に、High Executor Hadrecのもとへ報告に行け。お前に必要な追加の情報や装備を持っているかもしれん。", nil, "Bethorの言うことが本当なら、Thule Ravenclawは対処せねばならぬ脅威だ。それも早急にな。\n\nこの任務の助けとして、ここの武器庫から何か持っていくがいい……", 0x844a69cf, 0x65ab3030, 0xbcd0c567, nil, 0x5fbf7280, "...m." },
  [449] = { "Deathstalkersの報告", "Deathstalker ReportをSepulcherにいるHigh Executor Hadrecに渡してください", "Quinnの怪我は回復に向かっているが、できるだけ早く我々の報告書をHigh Executor Hadrecに渡したい。SilverpineにおけるForsakenの占領にとってきわめて重要な情報だ。", "Deathstalkerたちの運命は分かったか？", "Silverpine ForestにおけるScourgeどもの規模、それにわがDeathstalkerたちが偵察任務において直面する困難を把握できていなかった。\n\nDeathstalkerたちはずいぶんと助かるだろう、{name}。賞賛の的だ。", 0x18ffce2e, 0x519228b9, 0xe630f60f, 0xdc68e1b5, 0x036c5730, "....." },
  [450] = { "死のレシピ", "Pyrewood VillageからApothecary Berard's journalを回収し、SepulcherのApothecary Renferrelに持っていきましょう。", "君はRoyal Apothecary Societyの更なる役に立つことが出来るぞ、{name}。\n\nArugalが森に卑劣な魔法をかけた際、前途有望な我らが同士のひとり、Apothecary Berardが呪われた。今やArugalの心無き奴隷になったBerardは我らにとって役立たずだ。しかしあいつの発見は価値あるものかもしれなかった。奴は昔Lake Lordamereで水生生命を全滅させた太古の毒素を研究していたのだ。\n\nPyrewood Village Innの中のBerardの書斎からBerard's Journalを取ってきてApothecary Renferrelに届けてくれ。", "戻ったようだな、{name}。", "Apothecary Berardの日記か！お前はかなり勇敢だな、{name}。よし、Berardの気が狂う前 何を思っていたか今こそ見てみようじゃないか...", 0x9bd96087, 0x995d38e8, 0xd129f3dd, 0x28eec3e3, 0x3b144e17, "....." },
  [451] = { "死のレシピ", "Lake Creeper Mossのサンプル6つと、Lake Skulker Mossのサンプル6つ、Hardened TumorをUndercityのMaster Apothecary Faranellに届けよ。", "Berardの日記によると、Lake SkulkerとCreeperたちから取れるコケは新しい毒素を醸造する我々の探求に役に立つことを証明したかもしれない。この獣たちは東のLake Lordamereの島々に住みついてる。\n\n彼はVile Fin murlocから取れるHardened Tumorがとても貴重だと語っている。その腫瘍は本当にめずらしく、BerardはVile Fin murlocの一匹からようやく手に入れたらしい。\n\nコケのサンプルだけでなくそのめずらしいHardened Tumorも集めてUndercityのMaster Apothecary Faranellに届けてくれ。", "何の用でUndercityに戻ってきた、{name}？", "Berardを失ったことは、Royal Apothecary Societyにとって大きな痛手だ。だが君の尽力とApothecary Renferrelの熱心な研究のおかげで、Berardの研究はなおThe Dark Ladyの苦境のために役立つだろう。\n\n我々はここで何か偉大なことを成し遂げる寸前にいるのだ、{name}。君がこれほど戦いの道に長けていなければ、Societyの一員に誘うところなのだがな。", 0x9bd96087, 0xd477e1df, 0x2254fe23, 0x09a6dc7b, 0x41deeb73, "....." },
  [452] = { "Pyrewoodの待ち伏せ", "Deathstalker Faerleiaに協力してPyrewood Councilを倒す。", "まさに間一髪で来てくれたな、{name}！\n\nPyrewood Councilが今にも戻ってくる。Arugalは砦で他の用事にかかりきりだ。奴は評議会を単なる操り人形として使い、Pyrewoodの心なき手下どもを支配下に置いている。だがPyrewood Councilの導きがなければ、Arugalの息子たちは主に歯向かうだろうと私は考えている。\n\n私一人では奴ら全員を相手にはできない。手を貸してくれ。共にLady Sylvanasのため、評議会を叩き潰そう。", nil, "Dark Ladyの真の信徒のような戦いぶりだったぞ、{name}。評議会が死んだ今、この町をついに我々の支配下に置き、ArugalをShadowfang Keepから追い出せるかもしれん。お前に敬礼する!", 0x2e010a83, 0xc67918a7, 0xf4516ba5, nil, 0x04404ce2, "...m." },
  [453] = { "人影の発見", "Shadowy Figureを見つけ出す。手がかりは次のとおり。\n\n彼はDarkshireの出身ではない。\n\n彼は神経質で、落ち着きのない人物だ。\n\n彼はDarkshireを出て西へ向かった。", "幸運を祈るよ、{name}。その男が見つかるといいね。生きて見つかるといいんだが。\n\nDarkshireの安全な場所を離れてしまったのなら、荒野の獣の餌食になっているかもしれない。", "誰だ？？ 放っておいてくれ！", "<Jittersはため息をつく……>\n\nああ、あの本を書いたのは私だ。とうとう私を見つけたというわけか？\n\nまあ、あの日誌を読んだのなら……知っているのはその半分だけだがな！", 0x2ae0c829, 0xd39bd401, 0x2c24a350, 0x9d47818e, 0x344ae3ba, "....." },
  [454] = { "待ち伏せの後に", "Miranと話してください。", "この……騒ぎが起きる前は、爆薬の樽を何度も往復して運んでいたんだ。今は仕事を分けなきゃならない。Miranが樽を運び、俺は残りの樽の番をしている。\n\nMiranひとりに残りの積荷を運ばせるのは心配でな。あいつの準備ができたら、次の運搬の護衛をしてもらえないか？", nil, "やあ、{class}。\n\n発掘現場まで護衛してくれるのか？それはありがたい……Saeanとその取り巻きの件があった後だ、Dark Ironsが他にどんな企みを隠しているか分かったもんじゃない。\n\nとにかく、最後の点検を済ませておこう。出発の準備ができたらもう一度声をかけてくれ。", 0x2d57ae65, 0xb4a1fd8d, 0x4806532e, nil, 0x7d1ab5fb, "...m." },
  [455] = { "Algazの強行突破", "Dun Algazを越える。\n\nDragonmaw Scoutを8体とDragonmaw Gruntを6体倒す。\n\nMenethil HarborのValstag Ironjawに報告する。", "Dragonmaw氏族のオークどもがWetlandsに拠点を持っている。そして今、奴らはDun Algazにまで勢力を広げてきた！ ここに足掛かりを築かせておくわけにはいかん。さもないとLoch Modanは、Wetlandsにおける我らの港であり要塞であるMenethil Harborから切り離されてしまう。\n\nDun Algazを突破してその先のWetlandsへ抜け、ついでにオークどもを何匹か倒してこい！ Menethil HarborのValstag Ironjawに報告するのだ。\n\nMenethilへは、Dun Algazを抜けて道なりに北へ進み、分かれ道で西へ向かえ。\n\n頼りにしているぞ、{name}。しくじるなよ。", "Loch Modanから来たのか？ Algaz Gateのオークの状況はどうだ？", "お前の報告は悪い知らせばかりだな!\n\nDragonmawsがAlgazへ強く進出しているようだ。普段、Dragonmawsは丘に隠れているだけなんだが。何が奴らをAlgazへ押し寄せさせたのかは、まだ謎だ……\n\nありがとう、{name}。このオークどもの対処にも、お前の手を借りることになりそうだ。", 0x3a6441ba, 0x8925dac0, 0x2bd879fc, 0xadb75063, 0xcd00a06e, "....." },
  [456] = { "自然界のバランス", "Young Nightsaberを7匹、Young Thistle Boarを4匹倒してConservator Ilthalaineのところへ戻る。", "御機嫌よう、{name}。私はConservator Ilthalaine。Shadowglenでの私の仕事は、自然の均衡を保つことなんだ。\n\n今年の春は酷く雨ふりが多くて、そのために森では増えすぎた獣もいる。\n\n不幸なことに、NightsaberとThistle Boarは増えすぎてしまったのだ。Shadowglenではそんなに多くの生き物たちに必要なだけの食料をまかなうことはできない。そこでだ、若き{class}よ、少し足を伸ばしてBoarとSaberを狩り、数を減らしてやって欲しいのだ。そうすれば、自然の調和は保たれるだろう。", "まだやるべき仕事が残っていますよ、{name}。nightsaberとthistle boarの数を減らしたら、私のところへ戻ってきてください。", "よくやってくれた、{name}。", 0x2cefa7e3, 0x57f2ad93, 0x2ca7f2af, 0x1bb3c7c9, 0xb4a95be9, "....." },
  [457] = { "自然界のバランス", "Conservator Ilthalaineはあなたに、Mangy Nightsaber7匹、Thistle Boar7匹を倒すよう依頼した。", "Shadowglenの生き物の数を減らしたことは、幸先の良いスタートだった、{name}。だが、もう少しやってもらわねばならないことがあるのだ。\n\n森の資源は、問題が明らかにされない限り、あっという間に枯渇してしまうだろう。この地を共有するものたちにとって、野生動物たちを殺すことは、必要悪なのだ。森へ分け入り、Mangy nightsaberとThistle boarを、均衡の名において倒して欲しい。", "あなたの務めはまだ終わっていませんよ、{name}。mangy nightsaberを8体とthistle boarを8体倒したら、私のところへ戻ってきてください。", "君は自然への献身を証明したな、{name}。君のような若き{class}の将来は、輝かしいものとなるだろう。", 0x2cefa7e3, 0xc9b080bf, 0x37d9d1de, 0xe2130366, 0x943085ad, "....." },
  [458] = { "森林の守り手", "Tarindrellaとして知られるdryadを探し出せ。", "そなたが居てくれて良かった、{class}よ。木霊達の囁きから奇妙な知らせが届いたのだ。\n\n神秘なる森の守護者、Tarindrellaが、Shadowglenに戻ってきたそうだ。このKalimdorの森では、長きに渡って、dryadの気配は感じられていなかった。その彼女がこの地に舞い戻ってきたという事は、何か不穏な事が起こったからに違いあるまい。\n\nTarindrellaを探し、彼女が我らの森に訪れた意図を確かめてくれ。Sentinelの一人から彼女をAldrassilの南西で見かけたという報告が入っている。", nil, "私に御用かしら、お若い{race}さん。貴方をよこすなんて、Melitharは賢明なドルイドね。でも、貴方にはまだ学ぶことがたくさんあるわ。貴方たちは本が好きなんですってね。この中から一冊持っていって、勉強の足しにしなさい。", 0x89f0da3a, 0x7d2d6e81, 0xa893a5da, nil, 0x8298799d, "...m." },
  [459] = { "森林の守り手", "Fel Mossを8つ集め、Tarindrellaへ持ち込め。", "何か邪悪な事が、このTeldrassilの森で起ころうとしているわ。あの丘を御覧なさい、平和的なfurbolg達が棲家としていたところよ。でも、彼らはその棲家を捨て、今や、Gnarlpine族の名の下に集結しつつあるわ。\n\nこのような変異は、あの邪まなFel Mossの穢れによるものとしか考えられない。grellsとgrellkinが、このShadowglenに現れ、住人達を脅かしだしたの。\n\n彼ら、grellsとgrellkin達と一戦交えて頂戴、{name}。そして、彼らが邪まなFel Mossの魔力に囚われていないか確かめて。", "私の疑念を晴らしてください、{name}。Fel Mossを8個持ってきてください。", "貴方のShadowglenに住まうもの達への貢献は賞賛に値するわ、{name}。\n\nけれど、これで私の恐怖は現実のものとなってしまったわね。grellsがFel Mossによって侵されているのなら、ここに棲んでいたGnarlpine族のfurbolgsについても、言える事は一つだけ。\n\nDolanaarへ向かっては頂けないかしら、腕利きの{class}さん。博識で知られるドルイド、Athridas Bearmantleを探して欲しいの。彼は森を良くする為なら、私達の相談に乗ってくれる筈よ。", 0x89f0da3a, 0x26033e95, 0xd7bf71e4, 0x048ee8f1, 0x503e2cc2, "....." },
  [460] = { "安らかな眠り", "Alaric's Headを、彼の墓へ持って行け。", "お前はrot hideには見えないな。よかった。もう望みを失いかけていた……\n\n私の名はAlaric。かつてはThuleの筆頭召使いで、護衛でもあった。彼は魔法でPlague of Undeathから私を「守った」が、その呪文は逆に、逃れられない不死の命を私に与えた。そして呪われたrot hide gnollsを生み出した後、Thuleは私の首をはね……その首を、gnollsのおもちゃとして与えたのだ！\n\n頼む、私を体のところへ連れていってくれ。gnollsはここFenris Keepの厩舎の近く、印のない墓に私の体を埋めたはずだ。", "この墓は急いで掘られたようだ。", "ありがとう、{name}。Gnollsが私の体を壊してしまったのではと恐れていた。そうではなかったと分かって、よかった。", 0xbaedcb62, 0x793129d1, 0xb3b726d1, 0x8c9b8322, 0x3b9cc0ec, "....." },
  [461] = { "隠された壁龕", "Alaricを隠された壁龕まで連れて行け。", "砦の中に、Thuleとその昔の仲間たちが大事にしていた品が収められた隠し壁龕がある。お前の役に立ちそうなものもそこにある。私をそこへ連れていってくれ！\n\nその壁龕は、砦の南西の塔の、埃をかぶった棚の裏にある。\n\n私の体は持っていっていいが、ブーツは置いていってくれ。どうせ一度も足に合わなかったんだ……", "ここだ！ もっと近くへ連れていってくれ……", "よし、開いた。私をここに置いていってくれ。人生で最良の日々をこの砦で過ごしたのだ。この壁の中で眠ると思えば心が安らぐ。\n\n壁龕はしっかり閉じてくれ——Rot Hidesに見つかりたくはない。\n\nああ、それとこれを持っていけ。お前が稼いだものだ。", 0xa99e0958, 0x096624be, 0x5066a675, 0x42a11c2d, 0xa6ae72db, "....." },
  [463] = { "Greenwarden", "Greenwardenを見つける。", "Greenwardenのことを聞いたのかい？ まさか探してるんじゃないだろうね？ もしそうなら正気じゃないと思うけど、馬鹿が自分から死にに行くのを止める筋合いは私にはないからね。\n\nあの獣を探してるなら、Dun Modrへの分かれ道の東の沼地にいるって話だよ。crocsの間に潜んでるのさ……もっとひどいのもいるけどね！\n\nそれと、金はここに置いていきな。行き先じゃ必要ないし……ol' Greenieがあんたを真っ二つに噛み切る時に、あんたの金貨で歯を欠けさせたくはないだろう？", nil, "根と羊歯が、そなたのことを良く語っておる、小さき者よ。我には多くの名があるが、応えるのはそのうちのわずかのみ。だが、そなたは我をRethielと呼ぶがよい。\n\nそして耳を傾けよ……この地は膿んだ傷から涙を流しておる。そなたにその傷を癒やすことを命じよう。", 0xfb7098bf, 0xbe0cd27c, 0x6f613338, nil, 0xf9cd436c, "...m.", nil, nil, 0x65c7375f, nil, nil },
  [464] = { "軍旗", "Dragonmaw War Bannersを$N1個、Captain Stoutfistのところへ持って行って下さい。", "Dragonmawのオーク氏族は、Second Warの終わりまでにほぼ壊滅した。配下の赤いドラゴンを制御できなくなったからだ。ドラゴンたちはかつての主人を快く思っておらず、Dragonmawsを激しく狩り立てた。わずかに残った者たちはGrim Batolから逃れ、Whelgar's Excavationの東のMountainsへ入った。\n\n今では力を取り戻し、Menethilの北東に野営地を構えている。\n\n君にはその野営地を攻撃してもらいたい。その証として、奴らのwar bannersを集めて持ってきてくれ。", "Dragonmawの野営地は攻撃したか？", "見事な戦いぶりだ、{name}。Dragonmawsはdragonsを従えていた頃ほどの脅威ではないが、今でも手強い相手だ。\n\nDragonmawsを率いているのはNek'roshだ。何年も前にDragonmawsの頭だったNekrosの息子さ。NekrosはRed Dragonsを手なずけるために強力な魔法を使ったが、その魔法が効かなくなると……dragonsは黙っていなかった。\n\nNekrosは殺され、その息子は父を殺したdragonsへの復讐を誓ったんだ。", 0x342e9831, 0x9e413d73, 0x31e6e5db, 0x6eddf078, 0xb005d6c1, "....." },
  [465] = { "Nek'roshの策略", "Dragonmawのカタパルトを破壊する。", "君がDragonmawsと戦っている間に、我々は奴らの計画をさらに突き止めた。\n\nNek'roshは投石機を造り、Menethilを包囲するつもりだ！しかもDun Algazでの戦いのせいで、我々は援軍から事実上遮断されている！\n\nあの投石機を叩き潰してもらわねばならん。Dragonmawの野営地にある。\n\nほら、この火口を持っていけ。投石機のところまで戦い抜いて、この火口で火をつけるんだ。\n\nそれが済んだら、Nek'roshを見つけて倒してくれ。このDragonmawの獣を……首から断ち切らねばならん。", "最初のカタパルトが目の前にある。火を放つか？", "カタパルトに火口を少し置き、火花を散らす。\n\n炎が噴き上がり、瞬く間に広がる!", 0xe486ecaa, 0x3078639a, 0x86c62006, 0xec1a628f, 0x33e28a1a, "....." },
  [466] = { "Incendiciteの捜索", "Incendicite Oreを6荷、Dun MoroghのPilot Stonegearのところへ持って行く。", "Wetlandsの、Algaz Gateの北西にある洞窟で、珍しい鉱石incendiciteが見つかったと聞いたんだ。incendiciteは不安定な代物で、自分を吹き飛ばさずに扱うのは難しい。だがちゃんとした方法で精錬すれば、とんでもない威力の砲弾が作れるはずだ！\n\nincendicite oreを持ってきてくれ。そうしたら、それで実験する度胸のある奴を探すよ。\n\nああそれと、鉱脈からその鉱石を採るにはMiningの技能が要る。持っていないなら……持っている友をその洞窟に連れていくんだな！", "あの鉱石はどこだ、{name}？！", "鉱石を手に入れたんだな! よくやった、{name}! すぐに誰かにこれを扱わせよう。そいつが自分を吹き飛ばさないといいんだが!", 0x469ffcbc, 0x3c97991b, 0x5e710ce5, 0x46a9e54f, 0x6a8505d0, "....." },
  [467] = { "Stonegearの捜索", "Pilot Stonegearと話す。", "Pilot Stonegearは自分の攻城兵器を愛しているのさ。操縦士なら誰だってそうあるべきだがね！ それにあいつは、いつだって自分の戦車の火力を上げる新しい方法を探したがっているんだ！\n\nあいつは珍しい鉱石の噂を聞きつけて、それを探し出してくれる者を探している。足がうずうずしてきたなら、Dun MoroghのSteelgrill's DepotにいるStonegearを訪ねて、何の用か聞いてみるといい。", nil, "やあ、{name}。私の任務の件で来たんだろう? 君のように冒険と聞いて血が騒ぐ若い{race}に会えるのは嬉しいね!", 0xbf72506c, 0x71b54a38, 0x914d3b00, nil, 0x768a05c1, "...m." },
  [468] = { "Mountaineer Rockgarへの報告", "Mountaineer Rockgarと話す。", "Mountaineer Rockgarが、Dun Algazを抜けてWetlandsへ向かう任務の志願者を探している。\n\n北のあのじめじめした土地でブーツを濡らしてみたいなら、Dun AlgazにいるRockgarと話すといい。Dun Algazは道を北へ、見張り塔の先だ。", nil, "やあ、{class}! 偵察任務の件で来たのかい? 結構!\n\n装備の手入れが行き届いているといいんだが。この「偵察」任務は、もっと厄介なものに変わってしまったんでね……", 0xaca33545, 0x25296a5b, 0x8f51853a, nil, 0xf66d3152, "...m." },
  [469] = { "日々の配達", "Bundle of Crocolisk SkinsをMenethil Harborの皮なめし職人James Halloranのところへ届ける。", "やあ、旅の人！\n\nもしかしてMenethilの方へ向かっていたりしないかい？ そうでないなら、ぜひ寄ってみるといい。品物を買うにも、一杯やってくつろぐにもいい所だよ。\n\nで、もしたまたまそっちへ向かっているなら、このcrocolisk skinsの束を皮なめし職人のJames Halloranに届けてもらえないかな？\n\n自分で行きたいところなんだが、女房が最近ひどくご機嫌斜めでね、顔を合わせるのをできるだけ先延ばしにしたいんだよ。", "いらっしゃい、{class}。ブーツを一足いかがかな？ それとも、なめしたての革はどうだい？", "ふむ、これはEinarからだな? もう一週間近く、自分で毛皮を届けに来ていない。きっと奥さんとの揉め事だろう!\n\nそのうち、うちの妻をSidaと話しに行かせてみるか……", 0x4ccc1397, 0x32b2e18d, 0xd17d7bf3, 0x65e51f86, 0xbde24237, "....." },
  [470] = { "Oozeを掘り返す", "Ironbeard's Tombにいるウーズの一体がSidaの鞄を持っている。それを取り戻し、Menethil Harborにいる彼女のところへ持って行く。", "毎週のIronbeard's Tombへのお参りの途中で、恐ろしい、どろどろ滴るoozeに襲われたの！ もちろん、私は慌てふためいたわ。\n\n一匹に鞄を投げつけたんだけど、何の効き目もなかったの！ oozeはそのまま鞄を吸い込んでしまって……幸い、そのおかげで逃げる時間は稼げたけれど。\n\n困ったことに、どうしても鞄の中身を取り戻さなきゃならないの！\n\nどのoozeに鞄を投げたのか分からないのよ。どれも同じに見えたんだもの！ Ironbeard's TombはここからDun Modrの近く、北東にあるわ。本当にありがとう！", "私の鞄は見つかった？", "まあ、ありがとう、{name}! もう永遠に失くしてしまったと思っていたの!\n\n<彼女は粘液まみれの袋の中身を素早く地面に空け、それをすくい上げる。>\n\nうーん、これはもう私にはあまり使い道がないけれど、洗えばきっとあなたの役に立つわ。", 0x775c3dbd, 0xca612179, 0xa1442cd7, 0xffefe4fa, 0xf927327c, "....." },
  [471] = { "見習いの務め", "Giant Crocolisk Skinを6枚集め、Menethil HarborのJames Halloranのところへ持って行く。", "名物の巨大なWetlandsのcrocoliskの皮を剥ぎに、弟子を沼地へ送り出したんだ。戻ってこないんで探しに行ったら……まあ、見られたもんじゃなかったとだけ言っておこう。\n\n産婆の話じゃ持ち直すかもしれないそうだが、その間も皮は必要なんだ！\n\n……あいつらがしでかしたことを思えば、あの獣どもをもう何匹か倒してくれるのは大歓迎だ。crocsは海岸沿いを北へ、murlocの小屋の先にいる。", "弟子は私にとって息子のようなものなんだ。1本の脚だけで生きていくのは、あいつにとってつらいことだろう。\n\nああ、{name}、調子はどうだ？ 皮は持ってきてくれたか？", "ふむ……私の弟子になる気はないだろうね?\n\nハハ! いや、冗談だよ。まず、君は歳を取りすぎている。それに、見たところ君には人生で別の大望があるようだ。とはいえ、なかなか上等な皮を手に入れてくれたね。有効に使わせてもらうよ。", 0x574671c8, 0xeda0e52b, 0xb121762e, 0xfe757fb5, 0x2c27a8df, "....." },
  [472] = { "Dun Modrの陥落", "Dun Modrの町の近くでLongbraidを探す。", "Dun ModrがDark Iron Dwarvesの手に落ちた！\n\n俺の傷は重い、{class}。連隊のほとんどが殺された！Thandol Spanの待ち伏せから態勢を立て直す前に、Dark Ironのならず者どもが襲ってきたんだ。\n\n我らの隊長、Longbraidが退却の角笛を鳴らした。町を離れるとき、俺は流れ弾の斧を背中に受けて、目の前が真っ暗になった。\n\nここMenethilで目を覚ましたが、仲間の兵たちが心配だ。希望はまだ俺の中で燃えている。Longbraidはまだ生きているかもしれない！Dun Modrの近くで彼を見つけられるか確かめてくれ、{race}！", nil, "Menethilから知らせを届けるとは、どこの勇敢な{class}だ? ああ、{name}というのか。\n\n絶望的な状況に希望をもたらしてくれたな。若いHarloが生き延びたとは、実に良い知らせだ。逃げる途中で、あいつはひどい傷を負った。連隊で唯一生き残った馬の背に乗せて送り出すのが精一杯だったのだ。\n\nだが今、我々は危機に直面している。Dun Modrは陥落し、我々はかつての偉大な連隊の影にすぎん。", 0x2480801e, 0x9ccb757d, 0xd17a7577, nil, 0x4bca7f5e, "...m." },
  [473] = { "Captain Stoutfistへの報告", "Captain Stoutfistと話して下さい。", "{name}。Dragonmawのオーク氏族は、Algazだけでなくほかでも力を見せつけている。Captain Stoutfistが、このオークどもに立ち向かう力を貸してくれる者と話したいそうだ。彼は砦の中の作戦室にいる。", nil, "{name}。Dun AlgazでのDragonmaw Orcsに対するお前の戦果は、Valstagから聞いている。お前は価値ある{race}だ。\n\nそして、お前に任せたい仕事がある。", 0x738d103f, 0x4a1d9b30, 0x08a06865, nil, 0x4b813de0, "...m." },
  [474] = { "Nek'roshを倒せ", "Chieftain Nek'roshを倒す。\n\nNek'rosh's HeadをCaptain Stoutfistのところへ持って行って下さい。", "投石機は焼き払った。今度はChieftain Nek'roshを見つけて倒せ。", "Nek'roshは倒したか？", "見事にやってのけたな、{name}。お前はDragonmawのオーク氏族に痛烈な一撃を与えた。奴らはもう立ち直れんかもしれん。それに、あの投石機を破壊したことでMenethil Harborも安全になった。\n\nお前は立派な{race}だ。Ironforge王国は、よく仕える者に報いる。", 0x3c477488, 0x3969c24c, 0xd9531c6b, 0x94b6673f, 0xe065ceac, "....." },
  [475] = { "不穏な風", "Starbreeze Village にいる Gaerolas Talvethren を探し出して下さい。", "不穏な風が森を吹き抜けている。\n\nGaerolas Talvethren は Ban'ethil Barrow Den で眠るDruids of the Talonの偉大なる守り人として仕えている。選ばれし眠りの守護者としての彼の責務は、Ysera との契約を果たし続けるようドルイドたちを守ること。\n\nだが、Gaerolas からの連絡が遅れていて落ち着かないんだ。東の Starbreeze Village に向かい Gaerolas から夢見る同胞の微睡みは守られているとの報告を持ち帰って、安心させてくれ。", nil, "君が来てくれたことを森の精霊に感謝致します! Athridas なら問題が起きたことに気付いて助けを寄越してくれると分かっていた。", 0x42437c5a, 0x464394e4, 0xaf4e302f, nil, 0x78e5478b, "...m." },
  [476] = { "Gnarlpine 族の堕落", "Dolanaar にいる Athridas Bearmantle のところへ戻って下さい。", "Gnarlpineの部族が堕落してしまいました！\n\nかつては穏やかだったfurbolgたちが、森の守り手に牙をむいたのです。私がBan'ethil Barrow Denへ向かおうとしたところを待ち伏せし、そのままStarbreeze Villageを略奪しました。彼らの族長Ursal the Maulerが、Fel Mossの邪悪な力で彼らを狂わせているのです。\n\n私は傷が深く、Athridasのもとへ戻ってこの重大な知らせを伝えることができません。その務めはあなたに託します、若き{class}よ。正気を失ったGnarlpineたちが、まだBan'ethilにたどり着いていないことを祈るばかりです！", nil, "星々にかけて！これは実に不穏なことだ！", 0x333dcbf7, 0xc82e6f6a, 0xda446a65, nil, 0x5e5ae3c1, "...m." },
  [477] = { "境界線", "Dalaran wizardの木箱の一つの中身を探りなさい。Pyrewood Villageは南のほうにあるでしょう。", "知ってのとおり、AmbermillはDalaranの魔法使いの支援を受け人間どもの反抗拠点として存在し続けている。\n\n奴らが何をしてるのかは知らんが、Ambermillのような田舎町にさも大きな重要性があるかのような奴らの行動は気になる。\n\n奴らはHillsbradから馬車で何か運んでいる。その多くはPyrewood Village北の小さなキャンプに運び込まれている。荷物の中身を調べて、そいつを持って帰ってくるのだ。", nil, "<木箱のふたをこじ開けると、入念に封印されたものが詰まっていた。一番上にはSilverpine Forestとその他の西Lordaeronの地域が描かれた古びた地図の束があった。\n\n地図の下には神秘的な輝きを放つペンダントがある。>", 0x2ab2002c, 0x34ecda45, 0x7b469157, nil, 0x18486046, "...m." },
  [478] = { "地図とルーン", "その奇妙なペンダントをSepulcherのShadow Priest Allisterに渡してください。", "<すばやくペンダントを抜き取るとふたを閉めた。>", "何か役に立つことは分かったか、{name}？", "地図とこれは・・・ペンダントか、ん？面白い。\n\nDalaranのWizardたちが何らかの目的でAmbermillに興味を持っているのは明らかだ。 しかしそれが何かわからん。\n\nおそらくDalarはそれが何か知っているだろう。", 0xf6f2bae9, 0xf8e14cc9, 0xd8e2db76, 0x27f9af48, 0xb86a9652, "....." },
  [479] = { "Ambermillを調査せよ", "Dalaran Pendantを８個手に入れ、SepulcherのShadow Priest Allisterに渡してください。", "Dalarは魔術師どもの魔力の源を見つけようとしている。しばらくの間、どんな手を使っても奴らの邪魔をしなければならん。\n\nConjurerやMage、Protectorどもはペンダントを持っているに違いない。奴らからそれを奪うのだ。\n\n街道を南へ行き、東への分かれ道を行けばAmbermillだ。", "急がねばならない。奴らの計画を実らせてはならないのだ。さもなくば、Silverpine Forestの支配を失うことになりかねない。", "Dalarは、妨害があったにもかかわらず、計画がかなり進行していることに気づいた。\n\n強力な魔法使いが魔力を導き出そうとしている。すぐ止めねば。", 0x8bd36624, 0x6146c2b3, 0xd0b38a65, 0x9b61e2ce, 0x2b98fa69, "....." },
  [480] = { "つむぐもの", "Dalaran archmageを殺し、彼のStaffを手に入れSepulcherのShadow Priest Allisterに渡してください。", "偉大な力を持つArchmageが古代のエネルギーノードの再活性化をとりおこなっている。これをとめるには、奴を殺すほかない。彼は多くの魔術師と衛兵に守られているので、それはとても困難であろう。\n\nお前がやるのだ。迅速にな。奴を倒したなら、奴のStaffを手に入れてくるのだ。さあ、行け。", "急げ、時間がないぞ、{name}！", "魔術師たちの力は消え去った。そして古代の力は再び眠りについたのだ。見事な働きであったな、{name}。我らの敵、そしてDalaranの横柄な魔術師どもに大きな打撃を与えることができた。\n\n我々は常に眼を光らせておかねばならん。しかしながら、力の源がごく近くにあるということを知りえた・・。計画は常に先を見据えたものでなくてはならん。", 0xfccb2595, 0x7a833cf6, 0xe5cf22a6, 0x94847aa9, 0x16a486ed, "....." },
  [481] = { "Dalarの分析", "ルーンが刻まれたそのペンダントをSepulcherのDalar Dawnweaverに渡してください。", "そのペンダントをDalar Dawnweaverに渡せ。そうすれば魔法使いの計画がちょっとは明るみに出るだろう。", "何だ、{class}？ どうした？", "面白い。Kirin Torの物のようだな。強力な物だ。神秘的な力を得るのにKirin Torの強力な魔術師がしばしば使っていた。\n\nAmbermillにその手の物が多く運ばれているということは、何らかの計画に基づいて動いているに違いない。\n\n奴らの守りを打ち破れば、奴らの目的も確かめることができよう。", 0xd8838416, 0x06e6855e, 0x728cbfa3, 0xcc36545e, 0x3d8d2712, "....." },
  [482] = { "Dalaranの意図", "SepulcherのShadow Priest Allisterと話をしてください。", "そうだ！思い出した！\n\nAmbermillはKirin Torによって、古代のエネルギーノードが眠っている場所とされていたうちの一つだ。魔術師どもはそいつを復活させ、何かもっと大きな目的のために使おうとしているに違いない。\n\n見過ごしておくことはできまい・・・。\n\nペンダントがその一帯の古代のエネルギーを活性化させるのに大きな力を与えているのなら、魔術師どもからそいつを奪えば時間稼ぎになる。\n\nAllisterにこのことを伝えるんだ。彼が指示を出す。", nil, "嫌な知らせだな、{name}。Dalarの考えが正しいなら−疑う余地などないが−すぐに動かねばならん。\n\n彼と攻撃計画を協議しなければならん。しかしその間にも手をうっておかねばならん。", 0x058d0862, 0x399d30b9, 0xe7b56a1e, nil, 0xb93463a9, "...m." },
  [483] = { "目覚めの遺物", "目覚めの遺物を取り戻し、DolanaarのAthridas Bearmantleに渡して下さい。", "西の Ban'ethil Barrow Den を Gnarlpine 族の侵略者が荒らしているのが確認された。\n\n我々が助けなければ、微睡みにあるドルイドたちは己の運命に気付かぬまま Emerald Dream から永遠に出られなくなってしまう。繊細な冬眠の儀式は「目覚めの遺物」無しでは破れない。\n\nBan'ethil Barrow Den に向かい、Raven Claw Talisman ・ Black Feather Quill ・ Sapphire of Sky ・ Rune of Nesting を取り戻してくれ。遺物はドルイドが神聖な箱にしまった。遺物を持ち帰ってくれたら、目覚めの儀式を行う。", "{name}、西のBan'ethil Barrow DenからRelics of Wakeningを取り戻せなければ、さらわれたDruids of the Talonは永遠にEmerald Dreamに囚われたままになってしまいます。\n\n私たちが一分遅れるごとに、彼らの運命は永遠の破滅へと1歩ずつ近づいていくのです。", "成功したか、若き {class} よ! よくやった。それと、ちょうどよかったと付け加えておこう。", 0x269464e3, 0x956f3a24, 0x3fcb2591, 0xa4a2f2fb, 0x69323857, "....." },
  [484] = { "Young Crocolisk Skins", "Menethil HarborのJames Halloranのために、Young Crocolisk Skinを$N1枚手に入れる。", "私はJames Halloran、皮なめし職人だ。私が仕上げたcrocoliskの皮はあちこちで引っ張りだこでね、船で世界中の港へ出荷されているんだ。\n\nEinarには会ったかい？ 私のところにcrocoliskの皮を持ち込んでくれるハンターの一人だよ。\n\ncrocoliskの子供から取れる柔らかい皮が少し足りなくてね。\n\n在庫が少ないから、皮をひと山持ってきてくれたら最高の値を払うよ。子供のcrocsなら、町のすぐ外の水辺で見つかるはずだ。", "{name}だったな？ 皮は持ってきてくれたか？", "いい仕事をしてくれたね、{name}。この皮の質は最高だ。できるだけ早くなめしの工程に回さないと。おっと、でもその前に、やってほしい別の仕事があるんだ。君なら片付けられると思うよ。", 0xade45334, 0x2f1b74bf, 0xe4e1e7f0, 0x268e2dce, 0x1944bc7f, "....." },
  [485] = { "OOX-09/HL を発見せよ!", "OOX-09/HL Distress Beacon を Oglethorpe's homing robot のところまで持って行く。 homing robot は Hinterlands の Skulk Rock 付近を流れる川の源流部にある。", "金属でできた奇妙な卵形の装置を見つけた。つまみの一つをいじると卵が動き出し、開いてノームのロボット仕掛けのような姿になった！ロボットの卵の中から、雑音混じりの声が聞こえてくる。\n\n「私はOglethorpe Obnoticus。私の帰還用ロボットが墜落してしまった！回収してくれたら礼をしよう。このビーコンをロボットのところへ持っていってくれ！」\n\n「ロボットの座標を計算しておいた。Skulk Rockの近く、川の源流で墜落したんだ！」", "どうやら……ロボットのニワトリの残骸を掘り当てたようだ。卵の中から、再び声がパチパチと響き出す。\n\n「ああ、素晴らしい働きだ！ これこそ私の帰還ロボットだよ。ただ、センサーによると、修理のためにBooty Bayへ飛んで帰るには、まず始動の手助けが必要なようだ。さあ、ビーコンをローバーの中に置いてくれ。あとはビーコンが全部やってくれる！」", "あなたは卵……救難ビーコン……を、ニワトリ……帰還ロボットの中に置いた。\n\nロボットが立ち上がろうともがくと、その中からブーンという音やウィーンという音が聞こえてくる。ロボットが動き出すと、再びOglethorpeの声が聞こえた。今度はロボットの中からだ。\n\n「OOX-09/HLはとりあえず動いているが、大がかりな修理が必要だ！君が運ぶには重すぎる……だが、考えがある。もう少しこいつを見守ってくれるかい？」", 0xea9bf32c, 0x98cf6f92, 0x5e7aa30d, 0xae44575b, 0x251b00f8, "....." },
  [486] = { "Ursal the Mauler", "Ursal the Mauler を殺して、Dolanaar にいる Athridas Bearmantle のところへ戻って下さい。", "今こそDruids of the Talonを救う時が来た。今しくじれば、{name}、彼らは永遠に眠りの中に失われてしまうであろう。\n\n我はRelics of Wakeningを整え、儀式を執り行おう。我が術が効果を現すには、この恐ろしい事態を招いた呪われた獣を討たねばならぬ。そうして初めて、儀式は完成するのだ。\n\n我らが同胞の天命に手を出したのはUrsal the Maulerであり、彼らが解き放たれるために今その報いを受けねばならぬのもUrsal the Maulerだ。南西のGnarlpine Holdへ赴き、やつを討つのだ。", "Ursal the Maulerを倒さない限り、同胞たちを目覚めさせることはできません、{name}。", "{name}、そなたは実に立派で有能な{class}であることを証明した。そなたほど確かに名誉の道を歩む{race}ならば、この世界で大いなる栄光を見出すに違いない。\n\nそなたの旅路がどこへ向かおうとも、森の精霊たちがそなたを守らんことを。", 0xb9e1d498, 0xa1727d4c, 0x3474dc51, 0xd8fc3fa7, 0x6273f6f3, "....." },
  [487] = { "Darnassus への道", "Gnarlpine Ambushersを$N1体倒し、Dolanaarの外にいるSentinel Amara Nightwalkerのところへ戻って下さい。", "Darnassusへの道の安全は守られねばなりません。DolanaarからDarnassusへ向かう旅人たちから、Gnarlpine族の堕落したfurbolgによる容赦ない襲撃の報告が寄せられています。\n\n重要な知らせや商いが、毎日この道を通ってDarnassusを行き来しています。ならず者の異教徒の一団に人々を脅かさせておくわけにはいきません。\n\n聖なる森の名のもとに武器を取りなさい、{class}。彼らの巣はこの見晴らし台の下のどこかにあります。Gnarlpineの伏兵を6体倒し、私に報告しに戻ってきなさい。", "道はまだ安全ではありません、{class}。出向いてGnarlpine Ambusherを6体倒し、私のところへ戻ってきてください。", "Dolanaar と Darnassus の善良な人々のためによく尽くしましたね、勇敢な {class} よ。Teldrassil の Sentinel 部隊の一員として、あなたの働きに敬意を表します。", 0x02e02bee, 0xb208b8c2, 0x0083a597, 0x0910083a, 0x48dc3b9e, "....." },
  [488] = { "Zenn の命令", "Dolanaarの外にいるZenn Foulhoofのところへ、Nightsaber Fangsを$N1個、Strigid Owl Feathersを$N2個、Webwood Spider Silkを$N3枚持って行って下さい。", "仕事を探しているんだろ。命令を実行するのに未熟な {class} なんぞいらんという日が無くて良かったな。\n\nほれ、{name} 。お前をすごく幸せにしてやって、夢にも思わなかったような物をくれてやろう。だがそのためには、俺にある品を持ってこなければならん。\n\nこの森での仕事には、とある……触媒がよく必要になるんだ。Nightsaber Fang 3つ・ Strigid Owl Feather 3つ・ Webwood Spider Silk 3枚を取ってこい。\n\nこれは俺たちだけの小さな秘密だぞ、{race} 。", "小さな蜂みたいにせっせと働いてくれたかい、{name}？ 必要なものを持ってきてくれるのをずっと待ってたんだよ。", "ハッハッ! よくやったな、本当に。この俺、Zenn Foulhoof の命令を実行する {race} がいるなどと誰が考えたろうな? 確かに俺も思ってもなかった! だがそうなった……この愛する世界は驚きに満ちてるのさ。\n\nうぶで担がれやすい奴に万歳三唱!", 0x3c90fdc2, 0x7e3cea34, 0xccae3948, 0xb7e65c4d, 0x8c124f4e, "....." },
  [489] = { "償いを求めろ!", "Fel Cone 3つを集めて、Dolanaar の外にいる Zenn Foulhoof に渡して下さい。", "Council of the Forest はあなたが Zenn Foulhoof に手を貸したという知らせを受けましたよ。あのsatyrは森の敵なのです。{race} として、自然の生き物を殺して森を冒涜するなどという愚かな真似をしてはなりません。\n\nTeldrassil の友であり続けたいのなら、評議会の面前で罪を償うのです。\n\nFoulhoof を懲らしめれば罪は償われます。Fel Cone は木から落ちた穢れた種で、緑色の煙を立ち上らせています。\n\nそれを Foulhoof に与えなさい。無害な食べ物を持ってきたものと思い込むはずです。", "何を持ってきてくれたんだい、{name}？ おいしいおやつかな？", "ああ、なんて親切な {race} だ! お前は役に立つだろうと思ってたぞ!", 0x713743b3, 0x0ce5bdd5, 0x26b28abb, 0x2249cbce, 0x33294b57, "....." },
  [490] = { "賞金首：Gnarlpine Furbolg", "Gnarlpine Fangを$N1個持ってきてほしいと、Darnassusの外の道にいるShayla Nightbreezeは言っています。", "Sentinelsの厳命により、私はGnarlpineに懸賞金をかけています。彼らはもはや森の友ではありません。堕落によって心を失い、我々の民と森の空き地の生き物たちを脅かす存在となってしまったのです。\n\n定められた通り、Teldrassilからfurbolgの脅威を取り除いた者には報酬が与えられます。その働きの証として、彼らのGnarlpine Fangを持ってきてください。\n\nfurbolgは、Dolanaarの西、道の南にあるBan'ethil Hollowと、東のStarbreeze Villageに集まっています。", "堕落が大地を汚している限り、Teldrassilは栄えることができない。Gnarlpineをこの森から追い払ってくれ、今度こそ永遠に。", "よく務めてくれた、{name}。その貢献には報酬を与えよう。", 0x15504232, 0x7d8799e1, 0x356c46a1, 0xe87d5faf, 0xd1d90b14, "....." },
  [491] = { "Bethorの杖", "Woven WandをUndercityのMagic QuarterにいるBethorに持って行け。", "Thuleがかつて話してくれたことがある。ずっと昔、彼と2人の仲間が、それぞれのメイジが持っていた見習いの杖を編み合わせて、魔法の杖を作ったそうだ。この杖は彼らの友情の証だった。Thuleはやがてそれを嫌うようになったが、手放すことも、他の者たちに渡すこともできなかった。だから彼は杖を盗み、Fenris Keepに隠したのだ。\n\nほら。この杖を、Thuleの昔の友人の一人であるBethor Iceshardのところへ持っていってくれ。きっと欲しがるはずだ。", "{name}。Thule Ravenclawは倒したか？", "……これは何だ？ThuleがWoven Wandを持っていたのか？我らの友情が断たれ、奴がLich Kingに与したときに失われたものと思っていた！\n\nその力を呼び起こしてはいなかったに違いない。もし呼び起こしていれば私が感じ取っていたはずだ。そして、奴がそれを使わなかったのは幸いだ……\n\nこれは素晴らしい発見だ。感謝する、{name}。報酬を与えよう。", 0x45c93402, 0xe42d61cc, 0x20d403d4, 0x1b246f8d, 0x117496a2, "....." },
  [492] = { "新しき災厄", "Captured MountaineerにJohaan's Special Drinkを渡してください。", "Deathguardによると、ちょうどもう一人馬鹿なDwarven Mountaineerが捕らえられているそうだ。Deathguardは囚人が\"適切に\"扱われるまで、Gallows End Tavernの地下室を拘置所としてよく使ってるようだ。\n\nCaptured Mountaineerが、私が奴のために作ったこのスペシャルドリンクを楽しむ様を見に行ってはどうだ？ Dark LadyがAzerothの残りの地に企図していることのかすかなヒントが得られるだろう。", "俺に愛用のライフルがあれば、お前なんぞとっくに死んでるところだ、{class}。Steam Tank Brigadeが助けに来るまで待ってろよ！", "ああ、のどが渇いたぜ。Rhapsody Maltじゃないようだが、飲めるなら何でもいいぞ。", 0x4012ba5a, 0x46e5d67b, 0xb19d0a59, 0xe2d8db78, 0x7a7546f8, "....." },
  [493] = { "Hillsbrad Foothillsへの旅", "Apothecary Renferrelの研究結果をHillsbrad FoothillsのTarren Millの街にいる、Apothecary Lydon の元まで届けてくれ。", "Royal Apothecary Societyは、New Plagueを開発するようDark Ladyから強い圧力を受けている。我々は熱心に取り組み、大きな進展を遂げてきた。Society内で情報を共有すれば、成功ははるかに早く達成できると我々は考えている。\n\nそういうわけで、私の最新の研究成果を、Hillsbrad Foothillsに抱かれた小さな町Tarren MillのApothecary Lydonに届けてもらいたい。長い旅になるだろう。\n\n南へ向かい、道から外れるな。標識をよく見て進め！", "何か私に渡すものがあるのか？", "ああ、実に素晴らしい。Apothecary Renferrelのことは心から尊敬している。彼の研究を学ぶのが待ちきれない。", 0x49f62cad, 0x59f23d5b, 0xa20ad1d6, 0xa03be4c2, 0x77090878, "....." },
  [494] = { "攻撃の時", "Tarren Millへ向かい、Deathstalker LeshのメッセージをHigh Executor Darthaliaへ届けてください。", "静かに、注意して、{class}。\n\n私はHillsbradの町を調査するためにここに派遣されました。ある偵察が任務です。Tarren MillのHigh Executor Darthaliaに至急、知らせを送らねばなりません。彼女に私Deathstalker Leshのメッセージを伝えてください。\n\n「西からのワタリガラスの鳴き声が合図です」\n\n東へ向かう道にそって進み、道しるべに注意してください。さあ、急いで！　Tarren Millへ向かってください、それも大急ぎで！", nil, "西より渡鴉の鳴き声が招くというのか？\n\n見事な知らせだ！Hillsbradは攻めるに熟した。今こそ破壊の計画を実行できる。Varimathrasもお喜びになるだろう。", 0x21fbe6c8, 0xdc490290, 0xf2a72a87, nil, 0x6d384f87, "...m." },
  [495] = { "Crown of Will", "Hillsbrad FoothillsのTarren MillにいるMelisaraに報告して下さい。", "Mug'Tholとそのogreの戦闘部隊は、Lady SylvanasのためにCrown of Willを取り戻すべくAlteracへ送られた。ところが残念なことに、あの馬鹿はそれを持ち帰る代わりに、自分でかぶってみることにしたのだ……ogreというのは、きらきら光るものには抗えないのだろうな。\n\nだが、奴の間抜けな行動はいささか厄介な問題になっている。Crown of Willのおかげで、奴はLady Sylvanasに仕えるよう施された憑依に抗えるようになったのだ。\n\nDark Ladyは見せしめを望んでおられる。HillsbradのTarren Millへ向かい、私の副官Melisaraに報告せよ。", nil, "Shalindraがお前を寄越したのだね? よかろう。さて、私が無駄話で時間を費やさないと分かっているだろう。\n\nMug'Tholは実に不愉快な奴だ。我々は奴を迅速に、完全に、つつがなく処分するつもりだ。", 0x8774b387, 0xa83928a6, 0x2104c28c, nil, 0x34ce1b20, "...m." },
  [496] = { "Elixir of Suffering", "Tarren MillのApothecary LydonはGray Bear Tongueを10個と、Creeper Ichorをいくらか欲しがっています。", "ああ、Tarren Millでのまたもやみじめな一日だ。このきれいな空気のせいで、実に不快な気分になるよ、{name}。\n\nここの人間どもに疫病を振りまくのは早ければ早いほどいい。私は調合に使えそうな殺傷剤について念入りな研究を重ねているが、それを全部集める時間がないのだ。\n\n役に立ちたいなら、次の品を手に入れてきてくれ。Gray Bear Tonguesを10個と、とても希少で見つけにくいCreeper Ichorだ。熊もcreeperも、Tarren Millのすぐ外にいる。", "戻ったようだね。必要な材料を集められているといいんだが。死のない日がもう一日続いたら、すっかり陰気な気分になってしまうよ。", "この標本は完璧だ。さて、{name}、またしても惨めな一日の中で、君はほんのわずかな喜びをもたらしてくれた。君の働きに感謝する。", 0x146268e0, 0x3d995aa2, 0x9dac60ff, 0x87a55b6f, 0x524140e5, "....." },
  [498] = { "救出", "Tarren MillのKruskは、Durnholde KeepからDrullとTog'tharを解放するために、あなたを必要としています。", "オレと何人かの戦士が、Durnholdeからある物を取り戻すため、またいわゆるSyndicateを調査するために、Warchiefによって送られたんだ。\n\nオレたちは様子をみるためにDurnholdeに向かったが、大勢の人間に不意打ちされた。勇敢に戦ったが、数が多すぎた。奴らは仲間の何人かを捕らえたが、オレは逃げ出すことができた。\n\nDurnholdeはここのすぐ南東、川を渡ったところだ。DrullとTog'tharがつかまっている、お前は、彼らを救わねばならない。", "急がねばならんぞ、{class}。人間どもがDrullとTog'tharに何をしているかと思うと、身震いがする。", "では人間どもは我らのウォリアーを奴隷にしようとしたのか？思い知らせてやる！\n\n奴らは我らの指導者Gol'dirを別の場所へ連れ去ったようだ。奴を見つけ出して救わねばならん。だが今のところ、居場所の手がかりはない……\n\n手がかりを得たら、必ず知らせる、{name}。", 0x159a2ed8, 0xe459be02, 0x1f8bc674, 0x1fba2d2c, 0x9e396e8f, "....." },
  [499] = { "Elixir of Suffering", "Elixir of SufferingをUmpiに渡して下さい。", "これらの材料を混ぜて、私がElixir of Sufferingと名付けたものにするのは、ほんの一瞬で済む。\n\nほうら、できた！ああ、このみじめな丘陵地の陰気な日を明るくしてくれるものといえば、この世に少しばかりの苦しみをもたらすことに限るな。\n\nさて、我らのささやかな薬が狙いどおりの効き目を上げたか見てみよう。\n\n私の助手のUmpiに、Dark Ladyが人間とScourgeの両方に用意しているものを味見させてやれ。", "ケロッ！", "ゲロッ!", 0x146268e0, 0xa4579478, 0x84f92d8f, 0xcffd874e, 0xb3b43e90, "....." },
  [500] = { "Crushridgeの賞金首", "Alterac MountainsのCrushridge ogresからDirty Knucklebonesを$N1個集める。それをSouthshoreのMarshal Redpathのところへ持って行って下さい。", "Crushridgeのogresが、Alteracの廃墟の街の近く、Alterac Mountainsにogreの塚を掘った。斥候の話では、その廃墟も奴らが占拠したそうだ。\n\n奴らをあそこでくつろがせておくわけにはいかん。今いる場所が安全だと思えば、次は丘陵地へ降りてくる。そうなれば奴らはまさに我らの玄関先だ！\n\n北のAlterac Mountainsへ行ってogresを狩れ。奴らが持っているDirty Knucklebonesを持ってくれば、たっぷり賞金を出そう。", "{name}、まだogreを狩っているのか？ 集めるよう頼んだknucklebonesは持っているか？", "とても良いぞ、{name}。これだけのknucklebonesを集めるには、ogreの群れをまるごと叩き斬ってきたに違いない。\n\nこれで奴らもしばらくはこちらに手を出してこないだろう。少なくとも、しばらくの間はな。", 0xd5997ddd, 0x96fe79c1, 0x38ecbe34, 0x43214dd1, 0x3fa88dba, "....." },
  [501] = { "Elixir of Pain", "Mountain Lion Bloodの小瓶を$N1本、Tarren MillのApothecary Lydonのところへ持って行って下さい。", "ああ、{name}……Hillsbradでは花が咲き、空気はこんなにも爽やかで清々しい。そのすべてのみじめさに浸らずにはいられない。薄汚れた窓から外を眺めては、我らのNew Plagueがこの世界にふさわしい死をもたらす日を待ちわびているのだ。\n\n一日中座ってふさぎ込んでいたいのはやまやまだが、Dark Ladyへの務めが呼んでいる。手を貸してくれるか？私の研究によれば、Mountain Lionの血があれば、実に見事な死の薬が作れるはずなのだ。持ってきてくれれば、ちょっとした楽しみを味わえるぞ。", "覚えているよ、{name}。私の最新の秘薬を調合するのを手伝ってくれるはずだったね。Hillsbradの住人たちに私特製の苦しみをもたらすには、その血が必要なんだ。", "見事な収集ぶりだ、{name}。", 0x5f95556d, 0x11a0f776, 0xb6ac6284, 0x514bdf87, 0xa3c56c40, "....." },
  [502] = { "Elixir of Pain", "Elixir of PainをStanleyに飲ませて下さい。", "ああ、丘陵地に漂う新鮮な血の匂いほどいいものはない！\n\nさて、これを少々とあれを少し混ぜて、本当のお楽しみを始めよう！この血で作ったものを、私はElixir of Painと呼びたい。私の計算が正しければ、この調合薬はLady Sylvanasにとって実に美しい何かの始まりになりうる。だが必要なのは試験だ。\n\nこの薬を、南西のHillsbrad Fieldsにある北の農場へ持っていけ。Farmer Rayの小さな犬、Stanleyがこの「ごちそう」をどう気に入るか見てみようじゃないか。", "ワン？", "あなたは霊薬を少し手に注ぎ、Stanleyの口の前に差し出した。", 0x5f95556d, 0x21d6f5d9, 0x37c4b112, 0x0625e132, 0xa319b98f, "....." },
  [503] = { "Gol'dir", "Gol'dirを解放し、Tarren MillのKruskのところへ戻って下さい。", "あなたが手に入れた書類から分かる限りでは、Gol'dirは北にあるSyndicateの大きな拠点、おそらくAlterac Mountainsに捕らわれている。彼はあまりに長く囚われている。解放しなければならない。", "鍵をよこせ、{class}。錠は俺が自分で外す。", "ありがとう、{name}。私は大族長の命令でDurotarから遠征隊を率いてきたが、見てのとおり、計画はいささか狂ってしまった。奴らは私をこの町に捕らえ、働かせ、荷を運ばせ、穴を掘らせ……\n\nだが、私が受けた苦しみなどどうでもいい。今我々の一行を率いている者に、君が届けなければならない重要な情報がある。", 0x990985e4, 0x124fd1c0, 0x130bc664, 0xc4760db2, 0x1e747f18, "....." },
  [504] = { "Crushridgeの戦争屋", "Crushridge Warmongersを$N1体倒し、SouthshoreのMarshal Redpathのところへ戻って下さい。", "Crushridgeのogresの手ごたえは分かっただろう。今度は奴らの鼻っ柱を本気でへし折ってもらいたい……\n\nRuins of Alteracへ行き、Crushridge Warmongersを探し出せ。かなりの数を斬り倒してほしい。あの野蛮な連中にAllianceの領土から距離を置くことを覚えさせるには、それしかない。", "倒すべきWarmongerがまだ残っているぞ、{name}。武器をしまってこんな所にいないで、山の上で務めを果たしているべきだろう。", "とても良い。これが君の報酬だ。\n\nところで、Warmongersを狩っていたとき、Alteracの街はどんな様子だった? ひどい有様だろうな。ogreはきれい好きで知られているわけではないからな。\n\nありがたいことに、君の働きは奴らをSouthshoreから遠ざける助けになるだろう。", 0x9f73d70b, 0x918038fc, 0xc39d2e2e, 0xb352d2cf, 0x9c185a7e, "....." },
  [505] = { "Syndicateの暗殺者", "Syndicate Footpadsを$N1体とSyndicate Thievesを$N2体倒し、SouthshoreのMagistrate Henry Malebのところへ戻って下さい。", "私はSouthshoreの新しい治安判事で、前任の治安判事が暗殺された後に最近任命された。暗殺者は見つからなかったが、調査の結果、奴らはSyndicateに雇われたのだとほぼ確信している。Syndicateは、今は滅びたAlterac王国の悪辣な貴族たちが率いる盗賊団だ。\n\nSyndicateはHordeに占領されたTarren Millの北に野営地を構えていて、我々の最後の手がかりはその野営地につながっていた。そこで見つけたSyndicateの構成員を倒してくれ。", "あのSyndicateのならず者どもは始末したのだろうな？", "ありがとう、{name}。まだそのあたりに潜んでいるかもしれないが、君が倒した盗賊や追い剥ぎの中に、前の治安判事の死に関わった者がいたことを願っている。たとえそうでなかったとしても、Syndicateはこの地の汚れであり、人間という種族の恥だ。\n\n奴らの死はSouthshoreにとって喜ばしいことだ。", 0xbf89c9ca, 0x300fdfa9, 0xc4b88ed5, 0x7a6d6e71, 0xe4e50f44, "....." },
  [506] = { "Blackmooreの遺産", "Gol'dirが集めた情報をTarren MillのKruskのところへ持ち帰って下さい。", "一日か二日前、このSyndicateの頭目が私を訪ねてきた。名はAliden Perenoldeといい、この地の領主を名乗っていた。奴は、自分に逆らったオークたちを奴隷にするつもりだと打ち明けた。奴の父と、その師である忌まわしいBlackmooreが企てていたのと同じようにな。\n\nさらに重要なのは、奴が愛人を連れてきていたことだ。Elysaという名の、華奢な娘だった。その首に、大族長がお望みのペンダントが掛かっていた。\n\nさあ行け。私はここでの用を済ませてから、自分で道を行く。", nil, "あの横柄な人間どもめ、なんと図々しい! オークは決して奴らの意志に屈しないと思い知らせてやる!\n\nこれからはこれが我々の任務だ。大族長が望む装身具を取り戻すことに加えてな。一方を成し遂げれば、もう一方も成し遂げられるようだ。", 0x01ca1c10, 0xa4309959, 0xa71e8c36, nil, 0xaadf2e21, "...m." },
  [507] = { "Lord Aliden Perenolde", "Lord Aliden Perenoldeを倒し、彼の愛人Elysaに、Tarethaのペンダントについて尋ねて下さい。", "Perenoldeは殺さねばならん。奴の汚れをこの世から取り除くのだ。奴の屋敷はここから北へ少し行った、Lordamere Lakeのほとりにある。務めを果たせ、{name}。そして大族長がお望みのペンダントを取り戻し、ここへ戻ってこい。", "な、何の用だ？", "いや、いや、お願いだ、傷つけないでくれ! お前たちの仲間に危害を加えるつもりなんてなかったんだ、あいつに無理やりやらされていたんだ! お願いだ……見逃してくれ!", 0xe7c398ac, 0x514d939b, 0xeb679a6a, 0xab514ba6, 0xb146fbc3, "....." },
  [508] = { "Tarethaの贈り物", "TarethaのペンダントをTarren MillのKruskのところへ持ち帰って下さい。", "ペンダント？もちろん差し上げます……持っていって！あの人の思い出なんて要らない……ただ、お願い、お願いだから、そっとしておいて……", "戻ったか、{name}。成功の報告か？", "大族長がこれほど小さな物にそれほど多くを費やすとは妙なことだ。私に彼の考えが分かるとは言わないが、どんな命令であろうと彼に従うつもりだ。よくやった、{name}。大族長もきっと君の成功を聞いて喜ばれるだろう。", 0x2553583f, 0x24edf393, 0x90a3f52e, 0x8a184a33, 0xe0b16315, "....." },
  [509] = { "苦悶の霊薬", "Mudsnout Blossomsを$N1個、Tarren MillのApothecary Lydonのところへ持って行って下さい。", "また一日、また作るべき薬が一つ。私に任されるなら、哀れな人間どもとScourgeに勝手に戦わせておくところだ。どうせあいつらは互いに殺し合う気満々なのだから。\n\nだが残念ながら、我らがDark Ladyはその過程を少しばかり早めたいとお望みだ。ならば、この地に少しばかりの死と病を撒き散らして、この陰気な日々を過ごすのも悪くないだろう？\n\n計画はこうだ、{name}。Tarren Millの南、川とSouthshoreの東にあるNethander Steadへ行け。次の薬のために、畑からMudsnout Blossomsを6つ集めてくるのだ。", "Nethander Steadではうまくいったか？", "ああ、Mudsnout Blossomsのひどい悪臭だ。少なくとも、あの汚らわしいgnollどもにも使い道はあるというわけだ。", 0xe2ec6d44, 0x618ce9f5, 0x77bb60d3, 0x593338b4, 0xdc0fce28, "....." },
  [510] = { "Foreboding Plans", "Foreboding PlansをSouthshoreのMagistrate Malebのところへ持って行って下さい。", "これらの書類の中に、要求された補給品の一覧がある。ありふれた品（食料、武器、衣服）に加え、もっと風変わりな装備（仮面、油、毒）も含まれている。\n\nだが最も目を引くのは、その要求の緊急さだ。これらの補給品は、書類の中で「Southshoreに対する重要な任務」と記されているものを実行するため、すぐに必要とされていた。", "{name}、何やら落ち着かない様子だな。私に伝えたいことでもあるのか？", "<Malebは文書を読む。>\n\nこれはひどく気がかりだ、{name}。この文書の情報と、これまでのSyndicateの行動から考えると、あの人殺しの一味はSouthshoreに戦争を仕掛けてきたと見なさねばならない。", 0x3cf33f9f, 0x2f5b2aa8, 0xfd8c373d, 0x5e6d032f, 0xc71e385d, "....." },
  [511] = { "Encrypted Letter", "Encrypted LetterをSouthshoreのLoremaster Dibbsのところへ持って行って下さい。", "この机の上の手紙の一通は暗号化されていて、読み解けない。", "はい、お客様？ 私に何かご用でしょうか？", "これは何だ? ちょっと待ってくれ……よく見せてもらおう。\n\n……\n\nふむ、こういう形の暗号は今まで見たことがないな。もっとも、その分野の私の知識は決して完全ではないと認めざるを得ないが。", 0x5eef0cde, 0x3d22b12c, 0x9592e003, 0x3282ae20, 0x132ef96b, ".....", nil, nil, nil, 0xc3a055e5, nil },
  [512] = { "貴族たちの死", "Alterac Signet Ringsを$N1個、SouthshoreのMagistrate Malebのところへ持って行って下さい。", "Syndicateの背後にいる指導者たちは、Southshoreの破滅を狙っているのではないかと恐れている。奴らの計画が実現する前に、その指導者たちに強烈な一撃を加えねばならない。\n\n北のAlterac Mountainsにある、Strahnbradの廃墟へ入ってくれ。Syndicateはあの一帯を本拠地にしていると我々は見ている。\n\nこの無法者どもの一味は、かつてのAlteracの貴族たちが率いていることが分かっている。普通のSyndicateの工作員に紛れているかもしれないが、身につけているsignet ringで、倒したのが貴族だと分かるはずだ。\n\nそのsignet ringsを持ってきてくれ。", "Syndicateを狩ってきたか？ あの指輪は持っているか？", "Syndicateから貴族を奪えば、奴らは決断力のある行動が取れなくなり、ただのならず者の集まりに成り下がるだろう。\n\n君はAllianceによく尽くしている、{name}。", 0x6efdc3b1, 0xcd077f6c, 0x5eabc548, 0x18c6efdc, 0x8a695cc5, "....." },
  [513] = { "苦悶の霊薬", "Mudsnout CompositeをUndercityのMaster Apothecary Faranellのところへ持って行って下さい。", "また喜びのない一日が過ぎていくのかと思ったちょうどそのとき、君があの素晴らしいMudsnout Blossomsを持ってきてくれた。\n\nまずはこれを混ぜて、上等な合成物にしよう。次に、UndercityのMaster Apothecary Faranellに腐敗のコロイドを加えてもらう必要がある。そうすれば、実に楽しいお遊びの準備が整うのだ！\n\nほら、このMudsnout Compositeを持って、今すぐMaster Faranellのところへ走ってくれ、{name}。", "忙しいのが見て分からんのか、{class}？ NorthrendからのScourgeの侵攻に我々が呑み込まれる前に、Dark Ladyは新たな疫病を求めておられるのだ。しかも南からは人間どもの脅威が迫っている。今や時間こそが私にとって最も貴重なものなのだ。よほど大事な用なのだろうな！", "Apothecary Lydonに言われて来たのか? ああ、なぜそれを早く言わない!\n\n陰気な性格ではあるが、Apothecary Lydonは我々の中でも最も献身的で腕の立つ一員だ。\n\nあの男、Mudsnout Compositeを送ってきたか! Hillsbradの我らが友が今何をしているのか分かったぞ。それに、あの男の考え方は気に入った。新たな疫病に向けての彼の進展には、Dark Ladyもさぞ感心なさるだろう。", 0xe2ec6d44, 0xcaf9ff53, 0xf69b73d7, 0x0e29bf6f, 0xe69dc47d, "....." },
  [514] = { "Stormpikeへの手紙", "Cleverly Encrypted LetterをIronforgeのProspector Stormpikeのところへ持って行って下さい。", "Ironforgeに、この手紙の解読を手伝えそうな同僚がいます。IronforgeのHall of ExplorersにあるLibraryへ行き、Prospector Stormpikeと話してください。私の紹介だと伝えて、手紙を見せてください。Blackrock Spireより北でこれを読める者がいるとすれば、それは彼です。", "SouthshoreのDibbsに言われて来たのか？ あの本の虫のじいさんは元気にしてるかい？", "ああ、暗号か! 私の得意分野だ。どれどれ……", 0x3a29aa39, 0x51d81fad, 0x84ef8753, 0x713c5edf, 0x43030dbb, "....." },
  [515] = { "苦悶の霊薬", "Mudsnout Mixture、Strong Troll's Blood Potion、Daggerspine Scalesを$N1個、Torn Fin Eyesを$N2個、Tarren MillのApothecary Lydonのところへ持って行って下さい。", "mudsnout composite？実に見事だ！なぜ私は思いつかなかったのだろう？\n\nこの悪魔的な調合に、私の腐敗のコロイドを加えさせてもらおう。\n\nこのmudsnout mixtureの汚染成分を活性化させるには、Lydonには強力なトロールの血のポーションと、Hillsbradの南の海岸で取れるdaggerspine scalesとtorn fin eyesが必要になる。材料をすべて集めてやれば、あとは彼がどうすればいいか分かっている。ああ、彼の実験がどうなるか、聞くのが待ち遠しいよ！", "戻ってきてくれて本当にうれしいよ、{name}。ここで退屈でたまらなくなってたんだ。Umpiに毒を盛って病気にして、また蘇らせる……それを何度も何度も繰り返す以外、楽しいことが一つもなくてね。\n\nUndercityへの旅はどうだった？ 途中で人間を殺せるほど運が良かったかい？", "この実験の興奮で、頭がくらくらするほどだ! 君は本当に大きな助けになってくれたよ、{name}。共にこの地に死と病を広めようではないか!", 0xe2ec6d44, 0x4438dbcb, 0x6072444e, 0x3acc338b, 0xd2c3fdb4, "....." },
  [516] = { "Beren's Peril", "Beren's Perilにおいて、Ravenclaw Drudgerを６体、Ravenclaw Guardianを６体倒してください。それからSepulcherのShadow Priest Allisterのところへ戻ってください。", "アンデッドどもが我々を攻撃しようと集結しているとの報告があった。この情報をもとに、先手を打って攻撃し奴らの計画を未然に防ぐことができる。\n\n残念ながら、詳しいことはわからない。奴らはBeren's Perilというところに隠れているようだ。正確な場所は不明だ。しかしDalaran wizardたちがたむろするあたりの、近くの洞窟であると推測される。\n\n君の才覚に頼るしかないな。見つけ出し、やっつけろ。", "奴らの拠点はもう見つけたか、{name}？ 一刻を争うぞ！", "我らの偵察隊と諜報員がこのような重要な情報を入手し続けていけるなら、Lich KingのScourgeを我らの国から追い出す日もすぐであろう。", 0x26401209, 0xd52db9a2, 0x9be2b48b, 0xf891aa7c, 0x98b12fce, "....." },
  [517] = { "苦悶の霊薬", "Shindigger Stoutを一樽、Tarren MillのApothecary Lydonのところへ持って行って下さい。", "この新しい薬が、ようやく試せるようになった。だが、完璧で感染力の強い疫病を、たかが蛙や犬に使って無駄にすることはないだろう？Lady Sylvanasの名のもとに、本当のお楽しみといこうじゃないか。\n\nDun Garokへ向かえ。あの汚らわしいちびのドワーフどもがちょこまか動き回っている兵舎は知っているだろう。そこからShindigger Stoutの樽を一つ盗んできてくれ。その樽が手に入れば、君と私で盛大なパーティーを開けるぞ、{name}。", "Tarren Millにいると退屈でたまらなくて、時々ホルムアルデヒドの瓶を開けて、あの素敵な香りを辺りに漂わせるんだ。Umpiはちょっと落ち着かなくなるけどね。\n\nそれで、ドワーフから樽は手に入れられたかい？ この恐ろしい秘薬を誰にも使わずにもう一日眺めていなきゃならないなら、叫び出しちゃうよ。", "ついにだ! これで行動に移る準備が整ったぞ!", 0xe2ec6d44, 0x1dc458cd, 0x248bb624, 0x765bfcc6, 0x2d05d391, "....." },
  [518] = { "Crown of Will", "Tarren MillのMelisaraのために、Crushridge Maulersを$N1体倒す。", "Mug'Thol率いるCrushridgeのogresが、Alteracの廃墟を制圧した。ogresの数を減らさずに、奴に本気の痛手を負わせるのは難しいだろう。\n\n奴らを弱らせてから、次へ進む。\n\n分かったか？よし。では行け。", "お前の務めはまだ終わっていないようだな、{name}。お前の無能ぶりをSharlindraに知らせてやろうか？", "雪はogreの血で赤く染まっている。だが、Crushridgeの士気と数を叩き潰し、泥と雪の中にすり潰すまで、我々は手を緩めるわけにはいかん。", 0x8774b387, 0x88ddf52c, 0x393342e0, 0x5b69a572, 0xc434f7cd, "....." },
  [519] = { "Crown of Will", "Targ、Muckrake、Glommusを倒し、その首をTarren MillのMelisaraのところへ持って行って下さい。", "Targ、Muckrake、GlommusはMug'Tholの副官だ。奴らはMug'Tholに忠実だが、ogreを忠誠へ駆り立てるものが何なのかは誰にも分からん。\n\n奴らの首を持ってこい、{name}。そうすれば残るは、王冠ごとMug'Tholの首を取ることだけだ。", "俺が欲しいのは奴らの首だ、{name}。言い訳ではない。", "……ただでさえogreはひどい臭いだと思っていたがな。\n\nMug'Tholの首を持ってきたら、4つともAlteracの上に槍で掲げてやろう。Dark Ladyの意志に背く者どもにふさわしい記念碑だ。", 0x8774b387, 0xc2f274a1, 0xf6304ab3, 0xdc6f78ab, 0x1d294603, "....." },
  [520] = { "Crown of Will", "Mug'Tholを倒し、その首をCrown of Willと共にTarren MillのMelisaraのところへ持ち帰って下さい。", "Mug'Tholの副官どもが死んだ今、残るはMug'Tholを倒し、Crown of Willを取り戻すことだけだ。奴がそれを手放したがらないのは間違いない。仲間たちの……退場……を考えれば、おそらく君が来るのも予期しているだろう。\n\nMug'Tholを見つけ出し、奴の首とCrownを私のところへ届けてくれ。それでCrushridgeの抵抗は終わる。", "首は3つ手に入れた。もう一つ要る。それはMug'Tholの首か、さもなくばお前の首だ、{name}。それは約束する。", "よく務めを果たしたな、{name}。Mug'Tholの首はAlterac廃墟の最も高い峰を飾り、DeathguardがCrushridgeの残党を地中へと一掃するだろう。", 0x8774b387, 0xc9d0dc08, 0xb2e36173, 0x82953d7f, 0xacbed561, "....." },
  [521] = { "Crown of Will", "Crown of WillをUndercityのSharlindraに届けて下さい。", "残るは、Crown of WillをUndercityのSharlindraに届けることだけだ。彼女がLady Sylvanasのもとへ届けてくれる。自分の目的のために使おうなどとは考えるなよ、{name}。Mug'Tholの末路を見れば十分に分かるはずだ。", "何だ？ 何か報告することがあるのか？", "つまり、これがあのogreがDark Ladyの意志をかわすのに使っていた遺物か……\n\nこれほど単純なものがこれほど大きな力を振るえるとは奇妙なものだ。しかも、あんな不器用な手に渡るとはな。よくやった、{name}。この王冠はLady Sylvanasに届け、君の功績がお耳に入るようにしよう。", 0x8774b387, 0xdcf42342, 0x97bb0cc0, 0xea23a72f, 0x69388485, "....." },
  [522] = { "Assassin's Contract", "Assassin's ContractをSouthshoreのMagistrate Malebのところへ持って行って下さい。", "これは、Magistrate Henry Malebの暗殺を依頼する契約書だ。独特なsignet ringを使い、赤い封蝋で封印され、印が押されている。", "息を切らしているようだな! 何か報告があるのか?", "<Malebは契約書を調べる。>\n\nそれで先日のSouthshoreへの襲撃の説明がつく。Syndicateは私を狙っているに違いない、前の治安判事を狙ったのと同じようにな!", 0x123667ed, 0xd38982ba, 0x39e886c2, 0xd3e3d94d, 0xba35e005, "....." },
  [523] = { "男爵の最期", "Head of Baron VardusをSouthshoreのMagistrate Malebのところへ持って行って下さい。", "君が取り戻した契約書には、Baron Vardusの署名があった。かつてのAlterac王国の貴族で、冷酷な心と残忍なやり口で知られる男だ。男爵のような者が裏で糸を引いていたとしても驚きはしない。\n\nこの男を見つけてくれ。見つけ出して、裁きを受けさせるのだ。奴はSyndicateのたまり場のどこかにいるはずだ。おそらくStrahnbradの廃墟か、その北の谷の中だろう。", "Baron Vardusめ、手下のならず者どもを我々に差し向けておいて、Southshoreがそれを見逃すとでも思っているのか。奴の首が欲しい！", "ありがとう、{name}。あの悪党が首を失ったと分かって、私も少しは安心して眠れる。", 0xd825af65, 0x58cdb439, 0x25dbeae9, 0xbce9488d, 0xd03bb650, "....." },
  [524] = { "苦悶の霊薬", "捕らわれた農夫たちのために、Tainted Kegを敷物の上に置いて下さい。", "隣の部屋で、Deathguardsが捕らえた農夫たちを何人か人質にしている。High Executor Darthaliaは、Stormwindの軍事戦略家の一人がその中に紛れているのではないかと疑っていた。どうやらその軍人は、昨夜Plaguelandsで死んでいるのが見つかったらしい。いつも私のことを気にかけてくれるDarthaliaは、捕虜たちを私の好きにさせることに決めたのだ。\n\nそろそろあの農夫たちにパーティーを開いてやる頃だと思うね。実に楽しそうじゃないか！\n\nこのtainted kegを、奴らの部屋の敷物の上に置いてこい。疫病入りの酒を皆にふるまってやろう！", "敷物からかび臭い匂いが漂ってくる。", "あなたはtainted kegを埃っぽい敷物の上に置いた。", 0xe2ec6d44, 0x0e0d8bc9, 0xc0bb2da8, 0xed0af003, 0xbb8b8f70, "....." },
  [525] = { "さらなる謎", "Decrypted LetterをSouthshoreのMagistrate Malebのところへ持って行って下さい。", "手紙の暗号は解いたが、どう解釈すればいいのか分からん。これをAlteracの丘陵地の盗賊たちの間で見つけたって？実に奇妙だ……\n\nこれはSouthshoreの治安判事のところへ持っていくといい。この手紙は謎めいているが、彼の町はAlteracに最も近い。脅威が迫っているなら、彼は知っておくべきだ。", "{name}。また丘陵地帯や山々を旅してきたのか? どんな知らせを持ってきた?", "<Malebは手紙を読む。>\n\nこれはSyndicateの野営地で見つけた手紙を訳したものなのか? これは盗賊が書いたものではない。Alteracの貴族でさえない。\n\nどうやらThe Syndicateは別の勢力とつながりがあるようだ。それが何なのか、考えるだけで身震いする。", 0xf60def99, 0x26f021c6, 0x2486fb0d, 0xe5d68c15, 0xdd935eae, "....." },
  [526] = { "Lightforgeのインゴット", "lightforge ingotsを$N1個集め、WetlandsのGlorin Steelbrowのところへ戻って下さい。", "あの箱でlightforge ingotを一つ見つけたのかもしれないが、それじゃまともな物は何も作れないよ！\n\nもう一度あそこへ行って、もっと探してみるといい。あの難破船のまわりのmurlocsが、lightforge ingotsを持っているかもしれないよ。", "必要なlightforge ironは見つかったか?", "おお、見つけてくれたか! さあ、このlightforge ironを叩いて何か役に立つものにしようじゃないか、な?", 0x104fcb9a, 0x3a73e061, 0xa9406e02, 0x0a6e75bf, 0x67c1cb55, "....." },
  [527] = { "Hillsbradの戦い", "Hillsbrad Farmhandを6体、Hillsbrad Farmerを6体、Farmer RayとFarmer Getzを倒し、Tarren MillのDarthaliaに報告する。", "私に話しかける時は気をつけの姿勢を取れ、{class}。\n\n私はVarimathras様の直接の指揮下にある。我々の薬剤師どもが新たな疫病を開発するまで、人間どもの蔓延を鎮めるのが我々の任務だ。\n\n我々の情報によれば、Hillsbradの町は攻撃に弱いと見られる。お前の最初の任務は、奴らの食糧供給と基盤を混乱させることだ。\n\n西へ向かえ。Hillsbrad Fieldsの最も北にある農場を襲撃しろ。地主のFarmer RayとFarmer Getzも必ず処刑するのだ。", "Tarren MillのHigh Executorとして、VarimathrasとDark Ladyの直接の指揮下にある私の命令に、お前は従わねばならん。\n\nお前はAllianceとのこの戦を軽く考えているのか? もしそうなら、今この場でお前の首をはねてやるべきだな。そうでないなら、西のHillsbradの町へ向かい、命令どおり人間どもと戦え。\n\n下がれ。", "楽にしろ、{class}。戦場から戻ったようだな。私の情報筋によれば、Hillsbrad戦線での君の働きは見事だったそうだ。", 0x55e77d88, 0xfc0ccebc, 0x01474ce8, 0x54542e09, 0x60bb143c, "....." },
  [528] = { "Hillsbradの戦い", "Hillsbrad Peasantsを$N1体倒し、Tarren MillのDarthaliaに報告して下さい。", "北の農場が襲われたという知らせで、町の連中は慌てふためいている。実に結構だ。\n\n我らのDeathstalkersの報告によれば、農民どもがHillsbrad南部の畑へ逃げているそうだ。愚か者どもは果樹園に隠れて破滅を逃れられると思っている。\n\n奴らが間違っていることを証明してやれ、{name}。Hillsbrad Fieldsへ戻り、縮こまっている農民どもを探し出せ。我らがDark Ladyの名のもとに、奴らを殲滅するのだ。\n\n下がってよし！", "命令は出したはずだ、{class}。他にやるべき仕事があるというのに、このTarren Millでぐずぐずするな。", "Hillsbradの町を死の手が締め付けつつある。戦いは順調だ。", 0x55e77d88, 0x2aedb0e4, 0x6ef14919, 0xb73cd769, 0x51097f22, "....." },
  [529] = { "Hillsbradの戦い", "Blacksmith VerringtanとHillsbrad Apprentice Blacksmithsを$N1体倒す。\n\n鉄の積み荷を回収し、Tarren MillのDarthaliaに報告して下さい。", "Hillsbradの人間どもが、思いのほか抵抗している。どうやら地元の鍛冶屋が町の連中に武器を与えているのが問題らしい。補給線をすべて断たねばならん。\n\n君の任務は、Blacksmith Verringtanを処刑することだ。弟子たちも始末しろ。ついでに、奴らの備蓄から鉄の積荷を持ち帰ってこい。Hillsbradの征服を終えてSouthshoreを焼き払い始めるとき、その物資が役に立つだろう。", "命令は遂行できたか、{class}? Verringtanとその助手どもは始末したか? それに、あの鉄の積み荷はどこだ?", "任務完了だ、{class}。しかも実に手際よくやってのけたと付け加えておこう。", 0x55e77d88, 0x365ff6e1, 0x8ad21433, 0x0e58073f, 0xf288501a, "....." },
  [530] = { "夫の復讐", "Valdred Morayを殺せ    UndercityのRaleigh Andreanに彼の手を持っていけ", "私の良き友人だったValdredは我が妻を殺した。悲しむことのできない私だが、復讐を切望しているのだ。\n\nもし君がValdredを殺し、奴の呪われた手を持ってきてくれるなら、君に報酬をあげよう。\n\n最後に聞いた話では、奴はGilneasの王国へ逃亡を図って、Silverpineの南Greymane Wallにいるという。", "例の手は持ってきたか、{name}?", "ああ、よし。この手が私の妻、Deliahを殺したのだ。彼女を殺された復讐だけが私の望みだった。そしてお前はその復讐の道具となった。\n\nほら、先ほどお前が返してくれた指輪を持っていけ。Deliahは私にとって長いこと死んだも同然だった。その指輪など、もはや持っていたいとも思わぬ安物だ。代わりに、友の裏切りの形見として、この手を手元に置いておくとしよう。", 0x8a3e9a99, 0xdb158509, 0x99016295, 0x6375afcb, 0x8105cc0e, "....." },
  [531] = { "Vyrinの復讐", "Ol' Sootyの首をFarstrider LodgeのVyrin Swiftwindのところへ持って行く。", "光よ！ そんなものをLodgeに持ち込まないでくれ……不衛生だし、口にするのもおぞましいし、ふ……ふ……不衛生だ！\n\nとにかくここから持ち出してくれないか？ 君の血まみれのちっぽけな戦利品なんて、誰も見たくないんだよ、本当に！", "よくやった、{name}! あいつに思い知らせてやったな! さあ、首をよこせ、あとは俺が始末しておく。", "私のささやかな計画を手伝ってくれてありがとう、{name}。あの気取った高慢ちきな坊やに仕返ししたくて、何か月もうずうずしてたんだ。なかなか上手くやれたと思うよ! ほら、これを取っておいて。君はそれだけの働きをしたからね。", 0xeb8bf51a, 0xcafffbbe, 0x90fd33a0, 0x31f709f1, 0x2e24ea10, "....." },
  [532] = { "Hillsbradの戦い", "Magistrate BurnsideとHillsbrad Councilmenを$N1体倒す。Hillsbrad Proclamationを破棄する。Hillsbrad Town Registryを盗む。その後、Tarren MillのDarthaliaに報告して下さい。", "Hillsbradの町は混乱しており、まもなく陥落すると我々は見ている。だが、人間のクズどもが丘陵地から永遠に消し去られるまで、我々は容赦なく攻め続けねばならん。\n\n圧倒的な損害を受けながらも、人間どもは指導者のもとに結集して戦い続けている。奴らの指導者Magistrate Burnsideと、町の評議会を排除せねばならん。奴らが崇める政治文書、Hillsbrad Proclamationも破棄しろ。ついでに、town registryも盗んでこい。", "どんな知らせだ?", "Hillsbradでの君の栄光の知らせはすぐに伝わってきた。よくやった、{class}。", 0x55e77d88, 0x13acd1a0, 0x7f196303, 0x52f31234, 0xc73dc98a, "....." },
  [533] = { "潜入", "Tarren MillのKruskに、Gol'dirの行方を報せて欲しい。", "とうとう、我々はGol'dirの行方を調べ始めた。人間たちは彼をあちこちに移しているが、我々はすぐ北にあるSyndicateの大きなキャンプが怪しいと睨んでいる。\n\nキャンプへ行き、Gol'dirの行方の手がかりを手に入れるのだ、{name}よ。", "何か見つかりましたか? Gol'dirの見通しは日ごとに悪くなっているのではないかと心配で……", "我々はついにGol'dirの居場所を掴んだ。問題のキャンプはここからそう遠くはないし、上手くいけば我々が最初に捕まったときのような準備はしていないはずだ。", 0x9e97d88c, 0x2527e6b8, 0xe4c35587, 0xd708b4cb, 0x1063d55a, "....." },
  [535] = { "Valik", "Southshore Stoutを一杯、Syndicateの野営地にいるValikのところへ持って行って下さい。", "うぐぐ……傷を負って死にかけているところに、敵とご対面か。\n\nどうせ俺を殺すんだろうが、Southshore stoutを持ってきてくれれば――お前らの種族も酒は飲むんだろ？――知りたいことを教えてやる。", "何か飲み物を持ってきてくれたのか、それとも仕事の片をつけに戻ってきただけか?", "もうすぐ死ぬ身だから、これが今まで味わった中で一番甘美なものだと言い切ってもいいだろう……ほら、これを持っていけ。死んだら何の役にも立たないからな。\n\nさあ、さっさとやってくれ!", 0xf2b724fc, 0x89c4532d, 0x6eb6aeed, 0x2f8d9215, 0xe4b7c7d8, "....." },
  [536] = { "海岸を下って", "SouthshoreのLieutenant Farren Orinelleのために、Torn Fin Tidehuntersを$N1体とTorn Fin Oraclesを$N2体倒す。", "Stormwindの市の衛兵から、見たところ見捨てられてしかるべき町、Southshoreへ異動だ……昼も夜も港の臭いがする。\n\nおまけに、あのRedpathのじいさんときたら……俺にmurlocsを片付けろだとさ。はっ！\n\nWestern Strandにいる、あの育ちすぎた魚どもの群れのところへ出向く気にもなれないんだ。俺の代わりに行って片付けてくれたら、ありがたいんだがな。", "もう一杯エールを頼むよ、さっきのはどこかへ消えちまったみたいでね!\n\n光よ、俺はあとどれだけここで足止めされるんだ?\n\nおや、君か、{name}。もうあのmurlocどもは倒したのか?", "これで、私が――ハッ!――Redpathの命令を実行して、恐るべきmurlocという恐ろしくおぞましい脅威をSouthshoreから取り除いていると、あいつを納得させるのに十分だといいがな! 育ちすぎた魚の暴虐ほど大きな悪など、あるはずがないからな!", 0x89675618, 0xa8a42307, 0x0ee219d7, 0x9449d897, 0x06ffe0e5, "....." },
  [537] = { "闇の評議会", "Argus Shadow Magesを$N1体倒す。\n\nHead of NagazをSouthshoreのMagistrate Malebのところへ持って行って下さい。", "君が持ってきた手紙は、Argus Wakeの一員でNagazと名乗る者が書いたものだ。このArgus Wakeが何なのかは分からないが、Syndicateと手を組んでいるなら脅威に違いない。\n\nNagazと、その手紙に書かれていたArgus Shadow Magesを見つけてほしい。見つけ出して、倒してくれ。\n\nSyndicateが最も強いUplandsを探すんだ。Strahnbradの北にある。\n\n運が良ければ、そこでArgus Wakeの使者たちが見つかるだろう。", "The Argus Wakeの使者たちは見つかったか?", "よくやった、{name}。Argus Wakeは、Syndicateを率いてほしいような集団ではなさそうだ。\n\nそれに、ここで奴らの頭目を倒したとはいえ、Nagazは別の者の手下にすぎなかった。Argus WakeはAzerothの大陸全体に深く根を張っているのかもしれない。\n\nあるいは、世界全体にさえも。", 0xa17f6b61, 0x3aeda780, 0x8e5ad737, 0x79bde192, 0xbb1f9d27, "....." },
  [538] = { "Southshore", "SouthshoreのLoremaster Dibbsと話して下さい。", "{name}。長旅が苦にならないなら、頼みたい仕事がある。またStormwindの図書館の蔵書集めを手伝ってほしいのだ。\n\n古の王国Alteracは大戦の後に滅びたが、そこには膨大な蔵書があった。街が廃墟になったのは悲劇だが、それ以上に悲劇なのは、彼らの知識がすべて失われたことだ！取り戻せるものは取り戻さねばならない。\n\nRuins of Alteracに一番近い町はSouthshoreだ。そこへ行ってLoremaster Dibbsと話してくれ。遺跡への道と、そこでどんな本が見つかるかを教えてくれるだろう。", nil, "ああそうだ、Miltonのことは覚えている。間違いなく本の虫だ。あの人に祝福あれ。\n\nそして彼の言う通りだ。Ruins of Alteracには、失われる危険にある知識の蓄えがまだ眠っている！\n\n今やogreがAlteracに住み着いていて、奴らは高等な学問になど大して関心がない。", 0x5a607a80, 0x7e3967fe, 0x3b3b331d, nil, 0xb82f44b2, "...m." },
  [539] = { "Hillsbradの戦い", "Foreman BondsとHillsbrad Minersを$N1体倒し、Tarren MillのDarthaliaに報告して下さい。", "Hillsbrad Town Registryによれば、Azureload MineはAllianceの支配下にある。しかも、その鉱山はAllianceの武器庫にとって重要な鉄鉱石の供給源だ。\n\nHillsbradの町には決定的な一撃を加えたが、AllianceはいまだにAzureload Mineを熱心に支え、守っている。\n\n鉱山はHillsbradの真南にある。そこへ行き、Bondsという名の人間の現場監督を始末しろ。鉱夫どもも倒せ。そうすればAllianceにはっきりとしたメッセージが伝わるはずだ。", "お前にはAzureload Mineを攻撃せよと直接命令が下っていたはずだ。Tarren Millでぶらぶらしている理由が相当なものでなければ、反逆罪で首をはねてやるぞ。", "兵士たちを武装させるための新たな鉱山を手に入れたと知れば、Dark Ladyもお喜びになるだろう。", 0x55e77d88, 0xec900397, 0x69cc7e83, 0xa393de25, 0x3d6e86cd, "....." },
  [540] = { "知識の保存", "Recovered Tome 5冊とWorn Leather Book 1冊をSouthshoreのLoremaster Dibbsに渡して下さい。", "あの獣のようなogresが今ではAlteracの廃墟に住み着いている。まだそこにある貴重な本を奴らがどうしているか、考えただけでぞっとする。取り戻せるものは取り戻してくれ！\n\nRuins of Alteracに入り、ogresに略奪された書物を探してくれ。見つかったものは何でも持ってきてほしいが、特に1冊の本を探してほしい。The Arm of Gri'lekだ。私が学ばねばならない古代のトロールの伝承が書かれていて、この本の完全な写本が最後に確認された場所がRuins of Alteracなのだ。", "私も遺跡を探索できればいいのですが、この骨では山を登る間もたないでしょう。ところで、知識の探求の方はどうですか、{name}?", "おお、手に入れて下さったのですな! 素晴らしい! すぐにこの本の研究にとりかからねば!", 0x6bc8fd3c, 0x308d0cb3, 0xeffbce9e, 0xba406758, 0xfc6765c2, "....." },
  [541] = { "Hillsbradの戦い", "Dun Garokへ行き、Mountaineersを$N1体、Riflemenを$N2体、Priestsを$N3体、そしてCaptain Ironhillを倒し、Tarren MillのDarthaliaに報告して下さい。", "ドワーフが人間に加勢しているだと？忌々しい、あの汚らわしいちびの獣どもめ。\n\nいわゆるAllianceとやらの力を試してやろう。我らの怒りを味わえば、あのちびのくるぶし叩きどもが人間を助けたがるかどうか見ものだ。この地域での奴らの拠点がどこにあるかは正確に分かっている。\n\n奴らはHillsbrad南東部、Thoradin's Wall沿いに、Dun Garokという兵舎を築いた。この戦いの最後の任務は、Dun Garokを包囲攻撃することだ、{class}。奴らの指導者、Captain Ironhillには死んでもらう。", "Dun Garokはお前にとって手に余る障害だというのか、{class}? Hillsbradで勇敢に名を上げたものと思っていたのだがな。\n\n与えられた任務をこなせないのなら、もっと良い結果を出せる者を探すまでだ。お前はといえば、そうだな、Tirisfal Gladesに戻れば、Dark Ladyはいつでも墓掘りをもっと必要としておられるだろうよ。", "戦場での君の働きは、最高の賞賛に値する。", 0x55e77d88, 0x7d1a5067, 0xe1c4c546, 0xb8469e41, 0x1f838ead, "....." },
  [542] = { "Miltonのもとへ", "StormwindのMilton SheafにTomes of Alteracを渡して下さい。", "持ってきてくれたArm of Gri'lekの本をしばらく研究しなければならない。もっとも、Miltonは他の取り戻した本を早くStormwindの蔵書に加えたくてうずうずしているだろうがね。\n\nこれがRuins of Alteracから集めてくれた本だ。梱包して目録も作っておいた。StormwindにいるMilton Sheafのところへ持ち帰ってくれ。きっと感謝されるだろう。", "{name}、戻ったか! Alteracへの遠征はどうだった? 何か持ち帰ったものはあるか?", "これはこれは！これを見てください！Alteracの崩壊を生き延びたとは信じられません。しかもあれだけのogreがいたというのに！\n\nありがとう、{name}。本当にありがとうございます！あなたは人間の知識を守る手助けをし、Royal Library of Stormwindの威容に彩りを添えてくれました。", 0x8059ffd0, 0x62528f2b, 0xd177e73f, 0x5c8f0d76, 0x5e9286a2, "....." },
  [543] = { "Perenolde Tiara", "Perenolde Tiara をStormwindのRemington Ridgewellに届けて下さい。", "Perenolde Tiara は、Perenolde 「貴族」―― Alterac 王国が崩壊する前まで国を統治していた一族の古い家宝なのだ。Ironforge の至高の宝飾細工師によって作られ、極上のエメラルドが嵌め込まれていると言う。\n\nAlterac が滅んだ時にTiaraも失われたのだが、Grel'borg the Miser というOgre Mageがtiaraを見つけ、他の財宝を求めて Ruins of Alterac をうろついているとの噂だ。\n\nそのtiaraを取り戻してきてもらいたいのだ。", "ごきげんよう、{name}。私のズボンの裾を踏まないよう気をつけてくれたまえ。この服は仕立てたばかりなのでね。", "ああ、これは素晴らしい。無論、これは洗浄せねばなるまいな。しかし君は本当に腕を上げたな、{name} 。誰かにtiaraを整備させ、大急ぎでコレクションに加えるとしよう。\n\n君もきっと同意してくれるだろうが、我々は非常に感謝しているぞ。", 0xf44affa1, 0x291669a4, 0x03800364, 0x83074589, 0x1b1f74bf, "....." },
  [544] = { "監獄への侵入", "裏切り者たちを見つけて彼らの遺物を取り戻し、Tarren MillのMagus Voidglareのところへ戻って下さい。", "私は研究のためにTarren Millへ来たのだが、今は危機を解決せねばならなくなった。実は、数か月前に四人のForsakenがUndercityから逃げ出したのだ。彼らは同胞に背を向けた。だがもっと悪いことに……彼らはDark Ladyから盗みを働いたのだ。\n\nこの盗人どもは厳重な保管庫に押し入り、四つの遺物を盗んだ。我らの薬剤師たちがある研究に必要としていた品々だ。Sylvanasはこの遺物を取り戻すことをお望みだ。\n\n盗人どもはUndercityからDalaranへ逃れ、その魔術師たちが彼らをLordamere Internment Campに隔離した。", "泥棒たちは見つかったか? それに何より、奴らが盗んだ物は見つかったか?", "お前はForsakenに大きな貢献をしてくれた、{name}。これらの遺物がなくて我々はひどく困っていたのだ。\n\nそれに、Keganや他の裏切り者どもが裁きを受けたと聞けて何よりだ。", 0x7baa1829, 0x8c277a8e, 0xcf90dc70, 0x0e74356b, 0x1bc40e66, "....." },
  [545] = { "Dalaranの巡回兵", "Dalaran Summonersを$N1体とElemental Slavesを$N2体倒し、Tarren MillのMagus Voidglareのところへ戻って下さい。", "Dalaranの魔術師たちは、街の中心を囲む巨大な魔法のドームを築いた。この時代の暴力から身を守るためだったと考える者もいれば、ただ研究と策謀のために孤独を求めただけだと言う者もいる。\n\n理由などどうでもいい。私が気にしているのは、ドームの外にある街の荒れ果てた外縁部に、貴重な魔法の財宝が隠されているかもしれないということだ。\n\nだが、その一帯は魔術師たちと、その奴隷であるエレメンタルが巡回している。\n\nだから奴らを狩り、数が十分に減ったら戻ってこい。", "遺跡の周りにいるDalaranの巡回兵は、もう減らしてくれたか?", "とても良い。気をつければ、これであの廃墟も十分安全に探索できるはずだ。\n\nありがとう、{name}。", 0x73a4cf56, 0x29353d62, 0x8ee0e843, 0xa08b0e66, 0x19545ae1, "....." },
  [546] = { "死の土産", "Tarren MillのDeathguard Samsaは、Hillsbrad Human Skullsを$N1個欲しがっています。", "Darthaliaに徴用されて、Hillsbradの人間どもと戦っているそうだな。うらやましいことだ……\n\nお前がお楽しみの真っ最中――人間を倒し、町を略奪し、罪なき人々を恐怖に陥れている――だというのに、私はここTarren Millで見張りに立ちっぱなしだ。\n\n私のような年老いたDeathguardを哀れんでくれないか？実は人間のskullsを集めていてな。お前はこれからかなり長いこと人間と戦うことになるだろう。その長い戦いの間に、skullsを30個持ってきてくれれば、それに見合う礼をしよう。", "幸運な{name}のお帰りか? 今日は人間を何人殺した? 何百人だといいがな!\n\nskullは持ってきたか?", "大事な頭蓋骨! なんて美しい! 約束通り、借りは返すよ、{name}!", 0x91bf9c63, 0x61d010b0, 0xae66bd6b, 0xe44cd7fa, 0xddaefa3e, "....." },
  [547] = { "Humbert's Sword", "Dun GarokからDeathguard Humbertの剣を取り戻し、Tarren Millにいる彼のところへ返して下さい。", "High Executor Darthaliaの命で、私は遠くからDun Garokを見張っていた。見つからない場所に野営を張っていたのだ。だが朝が来て湯を沸かす必要があったので、薪を集めに出かけた。\n\n野営地に戻ると、装備がなくなっていた。\n\nどうやらDun Garokのドワーフの斥候たちが通りかかって、持ち去ったらしい。私の剣が要るのだ！取り戻してくれたら本当にありがたい。あそこにはドワーフがうじゃうじゃいる……盗んだ薄汚いちびの盗人を見つけるのはかなり難しいだろう。", "俺の剣は取り戻せたか、{name}? High Executor Darthaliaにこのへまを知られたら、梁から吊るされちまう。", "見つけてくれたのか!\n\nああ、大事な剣がこの手に戻って、心が満たされるようだ。本当にありがとう!", 0xd3a84f58, 0xb320d0f8, 0x90ba6ec9, 0x4cd630db, 0xe5687dbb, "....." },
  [549] = { "指名手配：Syndicateの構成員", "Syndicate Rogueを10体とSyndicate Watchmenを10体倒す。Tarren MillのHigh Executor Darthaliaのところへ戻って報酬を受け取る。", "Lady Sylvanasの権限により、Syndicateとして知られる組織の全構成員の処刑を命ずる。拘束された者、捕虜となった者は即座に処刑される。現在、奴らはTarren Millの南東、Durnholde Keepの廃墟に集結していることが分かっている。\n\nその働きの証拠をHigh Executor Darthaliaのもとへ届けた者には、たっぷりと報酬が与えられる。", "私の前に突っ立っている以外にすることはないのか、{class}? High Executorである私には、お前の腐った面を眺めているよりも差し迫った用があるのだ。", "見事だ、{class}。この調子なら、Syndicateという害虫もすぐにこの地から駆除されるだろう。", 0x4dfa905a, 0xc376c3eb, 0x3bff7ff9, 0x273b2f3d, 0x5f04d0d8, "....." },
  [550] = { "Hillsbradの戦い", "Darthalia's Sealed CommendationをUndercityのVarimathrasのところへ持って行って下さい。", "Battle of Hillsbradでのお前の勇敢さと粘り強さを讃え、戦いでの英雄的な働きを称える推薦状を書いた。上層部に認めてもらうためだ。\n\nこの封印された推薦状を、UndercityのVarimathrasのところへ持っていけ。誇りを胸に行くがいい、{class}。", "{class}がわざわざ戦場からUndercityまで何の用だ?", "では、お前がHillsbrad FoothillsでAllianceの軍勢にあれほど決定的な一撃を与えたという、悪名高き{class}か? お前の輝かしい功績の噂はすぐにUndercityまで届いたぞ。\n\n戦場でそのような統率力と手腕を示し続ければ、Dark Ladyの軍でお前には大いに将来があるだろう。\n\n我々の最大の脅威は北から迫るLich KingのScourge軍だが、人間という「問題」も我々の作戦を妨げ続けている。だがお前は、人間どもが倒れうるし、必ず倒れることを示してくれた。", 0x55e77d88, 0x7befd0c5, 0x2636f04b, 0x3bb0f0b2, 0x763ab23e, "....." },
  [551] = { "Ensorcelled Parchment", "Ensorcelled ParchmentをSouthshoreのLoremaster Dibbsのところへ持って行って下さい。", "この羊皮紙には呪文がかけられていて、判読できない。だが、紙の一番上にある一語だけは読める。\n\nNagaz", "おや。何か私に見てほしいものがあるのですか? 山の上で集めてきた伝承の切れ端か何かだといいのですが……", "また暗号化された覚え書きか?\n\nAlteracから流れてくる奇妙な書き物をすべて解読できる才能があればいいのだが。残念ながら、私にはその知識が欠けているのだ。", 0x531d0156, 0x50b9c1c2, 0xa92d237b, 0xd1eeba76, 0x14f969f5, "....." },
  [552] = { "Helcularの復讐", "YetiからHelcular's Rodを取り戻し、Tarren MillのNovice Thaivandのところへ持ち帰って下さい。", "Master Helcularは、Lichへの変容をほぼ終えようとしていたところで、人間の暴徒に丘の儀式の隠れ家を見つけられ、無残に殺されたのだ。さらに悪いことに、奴らは師の亡骸をSouthshoreの墓地に葬った。\n\n偉大な魔術師へのそのような侮辱は許せない。弟子として、Southshoreの町に復讐の雨が降り注ぐよう取り計らってやる。\n\nまずはHelcular's Rodが必要だ。Yetiが師の儀式の隠れ家を乗っ取った。間違いなく、その獣のどれかが持っている。", "Helcular's Rodはもう取り戻しましたか? この地域にはYetiがとても多いので、見つけ出すのは非常に難しいでしょう。ですが、先へ進むにはそれがどうしても必要なのです。", "見つけてくれたか! 実に素晴らしい、{name}!", 0xf7e0e7c8, 0x0b714fd9, 0x54cb8d68, 0xd4fe105d, 0x10435154, "....." },
  [553] = { "Helcularの復讐", "Rod of HelcularにFlame of Azel、Flame of Veraz、Flame of Uzelの力を充填する。\n\n充填したロッドをSouthshoreにあるHelcularの墓に突き立てて下さい。", "ほら、Rod of Helcularを持っていけ。必要になる。\n\nHelcularは、最も強力な呪文の一部として3つの儀式の火を作った。Flame of AzelとFlame of VerazはFoothill Cavernsの中にある。Flame of Uzelは、その洞窟群の上、さらに北の山中にある洞窟の中だ。\n\nRod of Helcularに三つの炎それぞれから力を込めねばならない。儀式が済んだら、南にある厳重に守られた人間の町、SouthshoreのHelcularの墓にその杖を突き立てろ。復讐は我らのものだ！", "Helcularの墓は神秘的なエネルギーに満ちている。", "地面から大きな地鳴りが響き渡る。", 0xf7e0e7c8, 0xeb743a89, 0x5ad40c15, 0xa75d2420, 0xf9c57cad, "....." },
  [554] = { "Stormpikeの解読", "Ensorcelled ParchmentをIronforgeのProspector Stormpikeのところへ持って行って下さい。", "Prospector Stormpikeは暗号の解読と判読の名人です。あなたが見つけた羊皮紙を彼のところへ持っていけば、運が良ければ意味を読み解いてくれるでしょう。Stormpikeは今、Ironforgeにある探鉱者の本部で研究しています。\n\nそれと、彼に会ったら私と話したと伝えてください。最近、彼にはずいぶん仕事を回しているんですよ。", "また邪魔が入ったか?\n\nああ、このparchmentには、非常に入り組んだ、精緻に編まれた呪文がかけられている。もちろん解くことはできるが、時間がかかる。そして時間は私にとって非常に貴重なのだ……\n\nいっそ君から買い取ってしまおうか?", "賢明な判断だ。この巻物を解読する技量を持つ学者など、私以外にはおるまい。もしその内容が興味深いものと分かっても、心配は無用だ。君を呼び寄せよう。", 0xa276f0c0, 0x1b2f4bfd, 0x3cd91bcf, 0x12b5e1b2, 0x2ec976df, "....." },
  [555] = { "Soothing Turtle Bisque", "Turtle Meatを$N1切れとSoothing Spicesを少し、SouthshoreのChef Jessenのところへ持って行って下さい。", "Southshoreについて一つ覚えておくといいのは、Stormwindより北では指折りの料理がここにあるってことさ！\n\nたとえば、私の秘伝のレシピのTurtle Bisque。Darkshireほど遠くから、一杯食べるためだけにやってくる人もいるくらいだ。そういえば、最近はまったく作れていないんだ。以前は自分でDalaranの先のLake Lordamereまで行ってSnapjawsを狩っていたんだが、今はとても危なくてね。北のSnapjawsから取ったTurtle Meatと、Soothing Spicesを持ってきてくれたら、さっと作ってあげるよ！", "材料は見つかったかい? 言っておくけど、この辺りはもう昔のような平和な場所じゃないんだ。ああ、こんな騒乱さえ起きなければなあ……", "みんな大喜びするよ。Chef JessenのSoothing Turtle Bisqueがまた出せるんだから!", 0xc8acfcb2, 0xcbb18379, 0x8281c5e6, 0xf16cfe59, 0xe0721028, "....." },
  [556] = { "石の証", "Worn Stone Tokensを$N1個、Tarren MillのKeeper Bel'varilのところへ持って行って下さい。", "Dalaranの魔術師たちの際立った才能の一つが、エレメンタル、つまり別の次元から来た強力な生き物に通じていることだ。魔術師たちは、エレメンタルを操る手段として魔法のtokensを使っている。Magus Voidglareが、研究のためにそのtokensをいくつか欲しがっている。\n\nHillsbradの西にあるDalaranの魔術師たちの縄張りへ入り、tokensを集めてきてくれ。\n\ntokensはDalaranの市民なら誰が持っていてもおかしくないが、狩るなら収容所がいいだろう。Dalaranそのものより安全だ。", "Worn Stone Tokenは持ってきたか、{name}? Magusがその秘密を解き明かしたくてうずうずしている。", "これで十分だ。魔力は薄れているようだが、Magusの最初の実験は、こうした不活性な標本で行うのが一番だろう。\n\nありがとう、{name}。", 0xc0cb7fcb, 0x067e46d1, 0x00001ed1, 0xcbf88af8, 0x164937b1, "....." },
  [557] = { "束縛の腕輪", "Bracers of Earth Bindingを$N1個、Tarren MillのKeeper Bel'varilのところへ持って行って下さい。", "魔導師は君が集めた石のトークンの研究で忙しいだろうが、いずれその対になるもの、束縛の腕輪の見本も欲しがるはずだ。これは本物のエレメンタルの手首にはめられ、彼らをメイジに仕えるよう縛りつけるものだ。\n\nDalaranの廃墟でエレメンタルを狩り、Bracers of Earth Bindingを集めてくれ。そうすれば魔導師は喜ぶだろう。", "やあ、{name}。Elementalは手強い獲物だが、君ならやれると分かっている。bracers of bindingは持ってきたかい?", "見つけてきたか。この腕輪を外された精霊どもは、素直に従ってくれたのかな?\n\nふむ……どうやら死は私の心臓を止めただけでなく、笑いの間の取り方まで奪ってしまったらしい。\n\nまあ、ありがとう、{name}。君はMagusに、ひいてはDark Ladyによく仕えている。", 0xec5198c0, 0xf1d2f129, 0xa4c203b1, 0x6f766f37, 0x784c80bb, "....." },
  [558] = { "Jaina's Autograph", "Theramoreへ行き、孤児のためにLady Jaina Proudmooreのサインをもらう手配をして下さい。", "TheramoreのLady Jaina Proudmooreは、Allianceで最高の英雄の一人なんだって。大きくなったら、わたしもAllianceの英雄になりたいんだ！\n\nJainaのこと知ってる、{name}？お願いがあるんだけど、いい？Jainaのサイン、もらってきてくれないかな？どうやって頼めばいいのか分からないし、きっとわたしみたいな子の相手をするには忙しすぎるよね……でもあなたなら！あなたもJainaと同じ冒険者だもん！きっと簡単にサインをくれるよ！\n\nお願い？", "いつか、Jainaみたいな英雄になりたいな……まあ、男の子の英雄だけどね。", "すごい！Lady Jainaのサインをもらってきてくれたんだ！本当にありがとう！それにすごい……ここに私へのメッセージまで書いてくれてる——私に！絶対にすごい人だって分かってたんだ。いつか自分でお礼を言えるかも……Allianceの英雄になったらね！\n\n最高だよ、{name}。こんなに優しくしてくれてありがとう。", 0x1e971cce, 0x5e4827a4, 0xd8aa58b1, 0xa79669a4, 0x8fa896f4, "....." },
  [559] = { "Farrenの証拠", "SouthshoreのLieutenant Farren Orinelleのために、Western Strandのmurlocから、Murloc Headsを$N1個集めて下さい。", "信じられるか、{name}？Redpathは、俺たちが倒したmurlocsの数じゃ満足しなかったんだ――おっと、謙遜するなよ、お前も一枚噛んでたんだからな。今度は死んだ証拠を持ってこいってさ。冷たくてぬめぬめしたmurloc headsを切り落として、ご承認をいただきに出せってわけだ。", "headは持ってきてくれたか、{name}?", "ああ、光にかけて……地面に滴ってるじゃないか。\n\nそんなもの、自分じゃ触る気にもなれないね。魚はいいもんだが、脚が生えて歩き回るとなると……もう何週間も魚を食べてないよ、ほんとに。Southshoreでそれは、ろくに食べてないってことさ。", 0x45ee0c0c, 0x2d52f901, 0xeee029fe, 0xa398efff, 0x06f12d58, "....." },
  [560] = { "Farrenの証拠", "murlocの首が入った袋をSouthshoreのMarshall Redpathに届けて下さい。", "なあ、{name}、この首はできれば持っていきたくないんだよ……お前はもう扱い慣れてるんだし、俺の代わりにRedpathに届けてくれないか？", "ごきげんよう、市民よ。Southshoreの安全を守るために力を貸しに来てくれたのか?", "Farrenの使い走りか?\n\nFarrenがこの首を手に入れるのを手伝ったのなら、礼を言う。Southshoreを守り続けるには、働き者とその努力が必要なのだ。", 0x45ee0c0c, 0x03a74911, 0xd2edee81, 0xe440eb18, 0x24ca6f34, ".....", nil, nil, nil, nil, 0xd82c0a9f },
  [561] = { "Farrenの証拠", "SouthshoreのLieutenant Farren Orinelleと話して下さい。", "Lieutenant Orinelleに、Eastern Strandにはびこるnagaに力を向け直してほしいと伝えてくれ。成果が出たら、私のところへ直接報告に来るよう言ってくれ。", nil, "nagaだと? Redpathも私と同じ情報を受け取ったばかりに違いない……ハッ! 私の苦労であいつが昇進することはないぞ。説明しよう。", 0x45ee0c0c, 0x6ecedb91, 0xdd4ac0b9, nil, 0x377b18a1, "...m." },
  [562] = { "いざStormwindへ！", "SouthshoreのLieutenant Farren Orinelleのために、Daggerspine Shorehuntersを$N1体とDaggerspine Sirensを$N2体倒す。", "Stormwindの市の衛兵時代の恩師から知らせがあってな、Alliance High Commandがnagaの脅威を懸念し始めているそうだ。聞いた話じゃ、この件で役に立つと証明した者には、昇進――少なくとも配置換え――の見込みが十分あるらしい。\n\nただ、一つだけちょっとした問題があってな……俺じゃnagaの相手は無理なんだ、{name}。そりゃあ、酔っぱらいの酒場の喧嘩を止めたり、喧嘩腰の物乞いを引っ立てたりはできるさ。だがnagaは俺の手に負えない。頼む、手を貸してくれ、{name}！", "StormwindのMajor Samuelson宛ての手紙はもう用意してある。あとは結果さえあればいい。", "Southshoreのnagaを片付けたとなれば、配置換えは確実だ。またStormwindを見られる……光に見放されたこの港から離れられるんだ。", 0x2c3969ea, 0x4492d369, 0xcf1a959e, 0x0faabf4d, 0x6f8fff5d, "....." },
  [563] = { "配置換え", "Farrenの報告書をStormwind KeepのMajor Samuelsonに届けて下さい。", "報告書を見てもらうのは難しくないはずだ。新しい衛兵隊長のMajor Samuelsonは、俺がStormwindに配属されていたときの恩師なんだ。これで、俺を街へ戻す口実としては十分すぎるだろう。ただ、報告書は君に届けてもらわないとな……Redpathのじいさんに感づかれたくないんでね。", "ごきげんよう、市民よ。Stormwind市の衛兵が何かお役に立てるかな?", "これは何だ? ああ……私の熱心な弟子がSouthshoreのnagaの問題に取り組んだというわけか。これを持ってきてくれてありがとう。来月人員配置を見直す際には、必ず考慮に入れよう。", 0x90f1f63b, 0x0b3f5dd6, 0x78c69450, 0xa222ff6a, 0xfb5790a8, "....." },
  [564] = { "高くつく脅威", "SouthshoreのDarren Malvewは、Mountain Lionsを$N1体とHulking Mountain Lionsを$N2体倒してほしいと言っています。", "この見事な馬たちを失うことほど、腹の立つことはねえ。それに信じてくれ、あの厄介なアンデッドのろくでなしども、忌々しいSyndicateの一味、それにこのあたりを嗅ぎ回るほかの役立たずの悪党どものせいで、もうかなりの数をやられちまった。\n\nだが、じいさまの墓に誓って言うが、ここの馬にとって、Alteracの山にいるMountain Lionsほどでかい脅威はねえ。いつも丘から降りてきて、俺の暮らしを厄介にしやがる！\n\n自分を英雄だと思ってるのか？だったら行って、何とかしてこい！", "Mountain Lionどもがうちの馬を次から次へと殺してるってのに、あんたは天気だの何だのとぺちゃくちゃしゃべりたいってわけかい。\n\n本物の英雄を探しに行かなきゃならんな。殺しを増やして、おしゃべりを減らしてくれるやつをな。", "そいつはすげえ知らせだ! 最初の日から、あの獣どもを片付けてくれる正真正銘の戦争の英雄を見つけとくんだったな。親父さんもお前を誇りに思っただろうよ、{name}。", 0xb2ece6a4, 0x461e4d8f, 0x03e26472, 0xd480338a, 0x5d61201c, "....." },
  [565] = { "BartoloのYeti Fur Cloak", "Bolt of Wool、Hillman's Cloak、Fine Thread、Yeti Furを$N1束、SouthshoreのBartolo Ginsettiのところへ持って行って下さい。", "私、偉大なるBartoloが、世界に名高く、Allianceで評判の、Yeti Fur Cloakをあなたのために作って差し上げましょう！\n\n世界を旅して、これより良いクロークを見つけてごらんなさい、できるものならね。おや、何ですかな、小さな{race}さん？「Bartolo、これ以上のクロークはない！」ええ、ええ！それは前にも聞きましたよ。\n\nBartoloに必要なのは、Bolt of Woolと、腕のいい革細工師が作ったHillman's Cloak、Fine Thread、そしてもちろんYeti Furです！これらの品を持ってきてくだされば、あなたは満足のお客様になれますよ！", "さて、偉大なるBartoloのもとへ戻ってきたか。Yeti Fur Cloakに必要な材料はもう集め終わったのかな? それとも、この私、Bartoloの偉大さに浸るのが楽しいだけかな!", "さあ、偉大なるBartoloがその魔法を振るう時だ! 魔法使いの杖も、メイジのロッドも要らぬ。この偉大なるBartoloは、ただの針と糸で魔法を生み出すのだから!", 0x3762718a, 0x007f7b7e, 0x67d80369, 0x82f1db22, 0x9ffce924, "....." },
  [566] = { "指名手配：Baron Vardus", "Baron Vardusを倒し、その首をTarren MillのHigh Executor Darthaliaに届けて下さい。", "High Executor Darthaliaの命により、Baron Vardusとして知られる人間を、Forsakenに対する罪で手配する。VardusはSyndicateとして知られる組織の高位の構成員であることが知られている。\n\n最後に目撃されたのは、Tarren Millの北、Alterac MountainsのUplandsである。\n\n生死は問わず、殺害を求む。報酬を受け取るには、その死の証拠をHigh Executor Darthaliaに届けること。", "ああ、{name}。Baron Vardusの首にかけられた懸賞金を受け取りに来たのかな?", "実りある働きだ、{name}。Baron Vardusが死に、Syndicateの指導者の数は減りつつある。奴らの抵抗や厄介ごとも長くは続かんだろう。", 0x58f55553, 0xf823ffc0, 0xb0ff96e2, 0xbba33e19, 0xf702664d, "....." },
  [567] = { "危険！", "Tarren MillのHigh Executor Darthaliaが、Clerk Horrace Whitesteed、Citizen Wilkes、Miner Hackett、Farmer Kalabaに賞金を懸けている。", "危険人物！\n\n以下のHillsbradの人間は危険であると見なされ、High Executor Darthaliaにより賞金がかけられている。\n\nClerk Horrace Whitesteed。Deathguard Toma殺害の罪で手配中。\n\nCitizen Wilkes。Apothecary Eli殺害の罪で手配中。\n\nMiner Hackett。Deathstalker Fry殺害の罪で手配中。\n\nFarmer Kalaba。Undercityからの補給物資を襲撃した罪で手配中。\n\nこれらの敵は皆身を潜めており、見つけるのは困難であろう。その死が知らされ次第、報酬が与えられる。", "何か？", "なかなかの賞金ハンターだな、{class}。よくやった。", 0x97aa3e60, 0x29cc4353, 0x59dd6751, 0x0c07a888, 0x49ccbea2, "....." },
  [568] = { "Grom'golの防衛", "Grom'gol base campのCommander Aggro'goshは、Lashtail Raptorsを$N1体倒してほしいと言っています。", "Throm'ka、{class}！\n\nGrom'golへの到着は実に時宜を得ている。このジャングルにある大族長の拠点の司令官として、Hordeのすべての者の安全を守ることは私の名誉にかけた務めだ。Stonardへの安全な補給路を確保する我々の任務が、この地の住人の一部に妨げられている。\n\nGrom'golの外のraptorの数を減らす任務を君に任せる。かなり成果が上がったら、次の任務のために報告に戻ってこい。", "我々の補給活動は、いまだにこの地に棲むraptorの群れに妨げられている、{class}。", "お前は名誉をもって務めを果たした、{class}。", 0x5f36e2f9, 0xc8369ffb, 0x9c60fc3b, 0x4443e4e7, 0xa0180172, "....." },
  [569] = { "Grom'golの防衛", "Grom'gol base campのCommander Aggro'goshは、Ogre Brutesを$N1体とOgre Witch Doctorsを$N2体倒してほしいと言っています。", "我々が初めてこのジャングルに来たとき、地元の部族と戦をするつもりはなかった。Stonardへの補給という我々の任務こそが最優先だ。だが面倒なことになった。地元のogresの一団が、Grom'golの南東にあるMizjah Ruinsを占拠したのだ。警告したにもかかわらず、奴らは我々の補給隊を待ち伏せし続けている。\n\nこの非協力的なogresへの対処を君に任せる。\n\n遺跡へ向かい、奴らをその一帯から追い払ってみてくれ。少なくとも、はっきりとした警告にはなるだろう。", "Mizjah Ruinsのogreどもの件は進んだか、{class}?", "よくやった。君は名誉をもって大族長に仕えた。", 0x5f36e2f9, 0x60ef089f, 0x4d0df666, 0x66bf7739, 0x582da09f, "....." },
  [570] = { "Mok'thardinの魔術", "Grom'gol base campのFar Seer Mok'thardinは、Shadowmaw Clawsを$N1個とPristine Tigress Fangを欲しがっています。", "ジャングルの魔力は理解され、そしてHordeによって活用されねばならない。私の儀式はこれまでのところ成功している。とても強力な付呪をかけられるのだ。勇敢な{class}よ、お前のために特別な品を作ってやろう。\n\nShadowmaw Pantherのclawsと、Tigressのfangを持ってこい。どんな牙でもいいわけではない。無傷のものでなければならん。\n\nその獣たちはジャングルのあちこちに潜んでいるが、近くにもいる。南東のMizjah Ruinsから川を渡ってすぐのところだ。", "どんな知らせを持ってきた?", "ジャングルについてのお前の知識は確かだな、{name}。この標本は完璧だ。Hordeの大義のため、これほど見事な獣を捧げてくれた精霊たちに感謝しよう。", 0x622413c0, 0x48af3de7, 0xcf8e0377, 0x2ab6b652, 0x36a0a724, "....." },
  [571] = { "Mok'thardinの魔術", "Aged Gorilla SinewをGrom'golのFar Seer Mok'thardinのところへ持って行って下さい。", "次にお前に頼むものは、手に入れるのがとても難しい。\n\nこれらの羽根や爪、そして無傷の牙をまとめておくには、魔法の結び紐が要る。それに使えるのはaged gorilla sinewだけだ。\n\nそれはElder Mistvale Gorillaからしか手に入らない。奴らはBooty Bayの東で餌をあさっていることで知られている。\n\n腱は完璧なものでなければならん。私が必要とするものを見つけるにはかなりの数を仕留めることになるかもしれんが、狩る価値は十分にある。", "運は味方してくれたか、{name}? aged gorilla sinewは手に入ったか?", "実に理想的な腱だ、{name}。お前の努力はすぐに報われるだろう。", 0x622413c0, 0x4580d54c, 0x458f28be, 0xe5645682, 0xdafb0d07, "....." },
  [572] = { "Mok'thardinの魔術", "Jungle Stalker Feathersを$N1個、Grom'gol base campのFar Seer Mok'thardinのところへ持って行って下さい。", "お前がValeの猫のような獣たちから集めた品は、強力な付呪の品に必要なものの最初の一つにすぎない。このジャングルの装飾品に私のシャーマンの儀式を組み合わせれば、Hordeと大族長を助けるのにとても役立つ道具になる。\n\nだが次は、Jungle Stalker Feathersを集めてきてもらわねばならん。その羽根は、獣たちが伝統的に腕輪につけているものだ。Grom'golのすぐ南、大闘技場からそう遠くないところにそのraptorsの一族がいる。", "採集はうまくいったか?", "実に素晴らしい。すぐにこれを準備しよう。", 0x622413c0, 0x84bd2949, 0xab6fa960, 0x4d019eac, 0xd24bae14, "....." },
  [573] = { "Mok'thardinの魔術", "Grom'golのFar Seer Mok'thardinはHoly Spring Waterを必要としています。さらに、Naga Explorersを$N1体倒してほしいとも言っています。", "付呪を完成させるのに必要な材料は、あと一つだけだ。\n\n南の、西の海岸寄りにある崖の高みに、Holy Springがある。この泉は、宗教や神秘の学者たちの間で大きな争いの種となっている。Azerothのあらゆる種族が、泉の水は自分たちの民のために神聖なものにされたのだと主張しているのだ。\n\nお前への最後の頼みだ。Holy Spring Waterを持ってこい。気をつけろ。nagaの探検隊が泉に迫っている。奴らにも対処せねばならんだろう。", "エンチャントの完成まであと少しだ。私の頼みは果たしてくれたか?", "このHoly Spring Waterで、儀式用の首飾りに魔力を込める準備が整った。\n\n誇りをもってこれを身に着けるがよい、{name}。大族長の名のもとに、そして偉大なるHordeを守るために。", 0x622413c0, 0x9c1bd245, 0x91373b69, 0x573545fc, 0xa094d64c, "....." },
  [574] = { "特殊部隊", "Kurzen Commandoesを$N1体とKurzen Headshrinkersを$N2体倒す。\n\nRebel CampのLieutenant Dorenに報告して下さい。", "奴の正規兵の多くが減った今、君は奴のよく訓練された部隊と戦わねばならない。奴らは荒野で我々の反乱軍兵士を虐殺していない時は、Kurzen Compoundの奥深く、Stockpileと呼ばれる洞窟にいる。\n\n私はKurzenの兵の多くを個人的に知っている。奴らは腕が立ち、忠実で、残酷だ。君に課すこの任務は容易なものではないぞ、{name}。\n\n奴らを倒したら、私の上官であるLieutenant Dorenに報告してくれ。彼は直接報告を聞きたがるだろう。", "Sergeant Yohwaから、君は腕が立ち勇敢だと聞いている、{class}。何か報告はあるか?", "{name}。Sergeant Yohwaは君の力を信頼していたし、私は彼女を信頼している。君がKurzenの軍勢にもたらした敗北は、望むことすらはばかられるほどのものだ。我々反乱者は孤立しているのではないかと恐れていた。孤立したままでは、大佐の才覚に立ち向かうことなど到底できなかっただろう。\n\nもしかすると、我々が生き延びる望みはまだ残っているのかもしれない。", 0x8c1cb402, 0x0e0e0de4, 0xbc940536, 0xdb5640af, 0x20b35e8c, "....." },
  [575] = { "需要と供給", "２枚のLarge River Crocolisk SkinsをBooty BayのDrizzlikに届けてください。", "「今も昔も世界で最もすばらしいSouth Seasの革細工師」そう呼ばれています。私！　このDrizzlikは！　今も昔も・・・えへん、えーと。\n\n私の革細工は広く遠く最も絶妙なものと知られています、違いがわかる人たちに！\n\n私はちょうどTinkers' UnionのDirector Riddlevoxに彼のお気に入りのExcelsior-line boots１ダースの注文を受け取ったところです。私たちのベストセラー商品ですよ、本当に。\n\n基本形に取りかかる前に、北Stranglethornの川沿いにいるcrocからcrocolisk skinsが必要となるでしょう。", "装備はすっかり準備できてるよ、{name}。あとはskinさえあればいいんだ。Riddlevoxを待たせるわけにはいかないからね、それは確かだ。\n\nTinkers' Unionの発明主任を不満にさせておくのは、誰にとってもいい考えじゃないよ。", "この皮で十分だ。ブーツの内張りになるから質はそれほど重要じゃないが、それでも履き心地がいいことは大事なんだ。\n\nちょっと硬すぎたら、虎の血を少し使って柔らかくするよ。商売のコツってやつさ、分かるだろ?", 0xb59aec97, 0x3a85682e, 0x5b23783d, 0x34cb5ea7, 0xbb7e5763, "....." },
  [576] = { "目を光らせて", "Booty BayのDizzy One-Eyeは、Bloodsail Buccaneersから自分の目を取り戻してほしいと言っています。", "おい！ そこにいるのは誰だ？\n\nくそっ、特製の魔法の目がなけりゃ、わしは役立たずだ。そもそも戦で両目を失くしただけでもひどい話だってのに！ だが運のいいことに、Menethilに寄港したとき、旅の魔法使いが特製の義眼に魔法をかけてくれて、また見えるようになったんだ。\n\n昨夜、出かける途中でBloodsail Buccaneersの連中に襲われちまった。わしの目を奪っていきやがったんだ！ どうやら奴らはBooty Bayまで来ているらしい。\n\nこの老いぼれ船乗りのために、目を取り戻してくれんか？", "おう、相棒! 目は見えねえが、港の半分向こうからでもお前の匂いはわかるぜ。\n\n俺の目玉を本当に取り戻してえんだ。俺の目ん玉が薄汚えBloodsail Buccaneersの手にあると知ったら、船長に竜骨くぐりの刑にされちまう。\n\n見えねえ見張りなんぞ何の役に立つ? 見張り台はかつて俺の住処だった……目がなけりゃ、船底の掃除でもさせてもらえりゃ運がいいほうだ。", "こいつはたまげた、たまげたこいつは! わしの美しい目を見つけてくれたか! まだぴったり合うか試してみよう。\n\n{name}、おーい! なんてこった、見える!!", 0x47831f9e, 0xa710bf37, 0x69b6522e, 0xb13bc580, 0x9f9c30ee, "....." },
  [577] = { "組み立てが必要", "Snapjaw Crocolisks Skinsを$N1枚、Booty BayのDrizzlikのところへ持って行って下さい。", "さて、ブーツの基本の形はできあがったし、順調に進んでるんだけど、君が持ってきた皮じゃ内張りにはちょっと足りないんだよね。\n\n「どうするんだい、Drizzlik？」 きっと君はそう聞きたいんだろう。いやあ、話してる相手がDrizzlikで運が良かったね。なにしろ彼がどうするか教えてあげるんだから！\n\n内張りは外からはほとんど見えないから、Lake Nazferiti周辺のcrocsから厚手で安い皮を手に入れて、ブーツを膨らませよう。", "Drizzlik's Excelsiorの革ブーツ、最高の職人技、100パーセント高品質のsaltwater crocoliskの皮で作ったブーツ。これ以上の品はないよ!\n\nこんな輝かしい宣伝文句にはかなわないだろう?\n\nまあ、君があの皮を持ってきてくれたなら、話は別だけどね?", "わしのブーツはな……ソーセージみたいなもんだ、{name}。見た目も最高、味も最高。中身は最高級の材料と肉だけだと言っておこう。それを食べて、大好きになるってわけだ。\n\n本当の中身が何なのかあまり詮索せず、わしを信じてくれるほうが安全だし――楽しいぞ。", 0xeea90331, 0xce256210, 0xa8c3c328, 0xf27c1538, 0x9531ce9c, "....." },
  [578] = { "Stone of the Tides", "Booty BayのBaron Revilgazのために、幽霊の出る島を見つけて下さい。", "もし本当にゴブリンのメイジとwater elementalsがその島に出没しているなら、Stone of the Tidesが私のものになるかもしれないぞ！\n\nその幽霊島を見つけて……何が起きているのか調べてきてくれ。ああ、それから、Stone of the Tidesについてもっと知りたいなら、この書き付けをStormwind Libraryへ持っていくといい。私が最初にその伝説を知った本の写しを見つけてくれるはずだ。\n\nGazbanは本当にStoneを見つけたのだろうか……？", "トロールは実に驚くべき魔法の品々を持っていたんだ、{name}。そして今、ひょっとすると、私の膨大なコレクションにその一つを加える機会が来たのかもしれない。噂の出どころは見つかったかい?", "あの話は本当だったのか! 信じられん!\n\nだが、Stone of the Tidesを取り戻すなら、その呪いを打ち破る方法を見つけねばならん。呪いは魔法の領分だ、魔法使いの誰かに手を貸してもらう必要があるだろう。", 0xff7b0223, 0x62f7970b, 0xdcb4094d, 0x4873e4c4, 0x5e208db9, "....." },
  [579] = { "Stormwind図書館", nil, nil, "King Anduinは学問を大いに重んじておられ、そのため様々な書物や文書の写しを作って民衆が利用できるよう、資金を出してくださった。とても簡単なことだ。図書館の引換券を持ってきてくれれば、用意できる本のうち一冊の写しを渡そう。", "この中に興味を引く題名はあるかな、{name}?", 0x308ed743, nil, nil, 0xccf61e18, 0x71324ab5, ".mm.." },
  [580] = { "Whiskey Slimの失われたグロッグ酒", "Booty BayのWhiskey Slimは、なくしたPupellyverbos Portの瓶を持ってきてほしいと言っています。", "わしらはOverlook Cliffsの沖で派手に酒盛りしてたんだ。遠くにはHinterlandsが見えてた。海に丸ごと飲み込まれるかと思ったぜ。\n\nOl' Slimは酒の勇気のことならよく知ってる！ 船長は、Stormwindへ向かう途中の私掠船から分捕ったPupellyverbos Portを一箱持ってたんだ。\n\nそれで、Hinterlandsの沖であの嵐に遭ったとき、わしは酒に手をつけちまった。でかい波が来て、瓶が船の外に放り出されちまったんだ。あんたが取り戻すのを手伝ってくれなきゃ、船長に鞭をくらわされちまう！", "なんてこった! 酒がもう切れそうだ! 船長が錨を上げちまったら、Ol' SlimはTanaris Desertみたいにからっからで取り残されちまう。それに、自分のportがなくなってると気づかれたら……ちくしょう!", "こいつはたまげた! 船長のグロッグ酒を見つけてくれたか!\n\nでっかい借りができたな、友よ。\n\n外は嵐になりそうだな。過ぎ去るのを待つ間、ここにある瓶の一本で温まっておくとするか……", 0x7df549e7, 0x3a3a9023, 0xb19717ad, 0x8c299697, 0x37b4626f, "....." },
  [581] = { "Yenniku捜索", "9個のBloodscalp TusksをGrom'gol Base CampのNimboyaに届けてください。", "悲劇だ。悲劇が長の末息子Yennikuに降りかかったのだ。我々の習慣で、彼はZul'GurubのGurubashi Troll族に与えられました、しかし、我々の部族、Darkspear族がオークのThrallとともに去った後、かわいそうなYennikuは行方が判らなくなってしまいました。私はStranglethornに戻って長の息子を探すために、遠くOrgrimmarから派遣されてきました。\n\nそして私はBloodscalp族のもとに彼がいると確信しています。\n\n手を貸してくれるなら、Bloodscalp族を狩ってください。彼らは北の方で見つけられるでしょう。彼らの牙を集めて、戻ってきてください。", "{class}。Bloodscalp族を狩ったことを示せ。\n\n戦利品を見せろ。", "良い牙だ、{name}。Bloodscalpを狩る力があることを証明したな。\n\nそれは良いことだ。なぜなら、奴らを狩る仕事はまだ終わっていないからな。", 0xc386a866, 0x71749318, 0xfcc2241c, 0x6bcabc86, 0x4c17928f, "....." },
  [582] = { "ヘッドハンティング", "２０個のShrunken HeadsをGrom'gol Base CampのNimboyaへ届けてください。", "我々はYennikuが死んでいるかどうかを確認しなければなりません。\n\nBloodscalp Headhuntersを殺して、彼らが持っているしなびた頭（Shrunken Heads）を手に入れてください。多くの、本当に多くの頭を集めなくてはなりません。そして、その中にYennikuのものがないかを確認しましょう。\n\nもし、Yennikuが Bloodscalpsに殺されていたら、６００年の呪いが彼らの長Gan'zulahの魂に落ちますように！\n\n行って下さい、{name}。北の海岸沿いにある廃墟、ZuuldaiaとZul'Kundaで多くのHeadhuntersが見つかるでしょう。", "{name}。族長の息子のことが心配だ。私が調べられるよう、shrunken headは持ってきたか?", "ありがとう、{name}。かわいそうなYennikuがHeadhuntersの斧を逃れたことをはっきりさせるため、これらの頭を調べてみましょう。", 0x906665cf, 0xfbfb4b85, 0x8765ef9a, 0x61086e81, 0x17791d99, "....." },
  [583] = { "ジャングルへようこそ", "Hemet Nesingwary と話して下さい。", "Stranglethornへようこそ！\n\n知らないかもしれないが、あそこにいるドワーフこそ、かの有名なHemet Nesingwaryその人だ。Allianceの名高い戦争の英雄にして、大物狩りの名ハンターでもある。見知らぬ者を自分のキャンプに迎え入れるような人ではないが、君はずいぶんと場数を踏んできたように見える、{class}。\n\n自身も数多の戦いをくぐり抜けてきた古強者だから、Master Nesingwaryは同じ英雄仲間には甘いのだ。\n\n行って話してみるといい。狩りのコツを教えてもらえるかもしれない。", nil, "知り合えて本当に嬉しいよ、{name} 。この辺りじゃしばらく {class} は見かけなかったな。\n\nここにいるのにはひとつ目的がある。大きくて珍しい獣を狩ることだ。見たところ、お前さんは狩りに加えたいちょっとした英雄だが、まずは実力を見せてもらわねばならん。\n\n俺がraptorの殺し方を教えてやろう。Ajeck は虎狩りで鍛えてくれる。Sir Erlgadin は豹を追跡する達人だ。\n\n腕前を示せば、大物狩りに入れてやるぞ。", 0x9ad92ef3, 0x56561224, 0x1e3f2560, nil, 0x9f389bf6, "...m." },
  [584] = { "Bloodscalp族の頭", "Gan'zulahの頭とNezzliokの頭をGrom'gol Base Campの泡立つ大釜（bubbling cauldron）にいれてください。", "首の中にYennikuはいなかった。Great Serpentに感謝する。だが、あの子を見つける手がかりには少しも近づいていない。\n\n真実を知らねばならん。それを知っているのは、Bloodscalpの族長とその呪術医だけだろう。奴らはDarkspear族の敵で、素直には話すまい。ならば死んだ唇から真実を引きずり出すまでだ！\n\nGan'zulahとNezzliok the Direの首を持ってきて、この大釜の中に入れてくれ。\n\n奴らはZul'Kundaの奥深くにいる。首を持ってこい……そうすれば奴らに口を割らせてやる。", "大釜の中の緑がかった煮汁が泡立っている。", "あなたは大釜の中にGan'zulahとNezzliokの頭部を入れた……。", 0x0d8aa1cf, 0xd3a3a452, 0x47ec331f, 0xbe66c0ac, 0xcce85cec, "....." },
  [585] = { "Nezzliokと話す", "Balia'mah Trophy、Ziata'jai Trophy、Zul'Mamwe TrophyをGrom'gol Base Campの泡立つ大釜（Bubbling Cauldron）に届けてください。", "<Nezzliokの首が語り出す。>\n\n本当だ。Darkspearsの子がどこへ連れ去られたか、我は知っている。貴様は我を打ち負かし、我が魂を縛った。だが、なだめられぬ限り何も言わぬぞ！\n\nBloodscalpsはSkullsplittersと戦っている。我の歓心を得たければ、Skullsplittersから奴らの戦利品の頭蓋骨を3つ盗み、ここ我らのもとに置け。そうすれば我が魂はNetherで奴隷を得られる。頭蓋骨の一つはBalia'mahの戦利品の山から、もう一つはZiata'jaiから、最後の一つはZul'Mamweから持ってこい。", "頭蓋骨を待っている……", "そうだ。これらは私の役に立つ。我が魂が解き放たれるとき、3人の見事な従者を連れてNetherへ入るのだ！\n\nお前は{race}の氏族の誉れだ。そして私を満足させた。", 0xbe554e4b, 0x9dd76e71, 0x5db49735, 0x0f044a21, 0xe6a18a20, "....." },
  [586] = { "Gan'zulahと話す", "Skullsplitter Huntersを$N1体、Skullsplitter Headhuntersを$N2体、Skullsplitter Berserkersを$N3体倒す。\n\nBroken Armor of Ana'thekをGrom'gol Base CampのBubbling Cauldronへ持って行って下さい。", "<Gan'zulahの首が語り出す。>\n\n呪われろ！貴様の祖先も呪われるがいい！！\n\n我が怒りを冷ませるのは血と復讐のみ。それが貴様の望みなら……こうするがいい。\n\n東のSkullsplittersの本拠に身を投じろ。奴らの中で最も獰猛な者どもを殺し、生き延びたなら……奴らの族長Ana'thek the Cruelに挑んで砕け散るがいい。ハッ！できるものなら、奴の砕けた鎧を持ってこい！\n\n奴に手足を引きちぎられ、腐り果てて屍肉喰らいどもに食われるがいい。", "我が肉が頭蓋から煮え落ちようとも、貴様の恐怖の匂いはまだ嗅ぎ取れるぞ。\n\nハッ! 貴様が我が務めを果たすことなど決してできまい……", "信じたくはないが、お前が成したことを否定することはできぬ。そしてAna'thekが倒された今、我が怒りも和らぐ。\n\nその力はお前を偉大な行いへと駆り立てるだろう、{name}。だがいつの日か……Netherでお前と会い、再び力を競うことになる。\n\n待っているぞ。", 0xa15d8fd0, 0x72e6d486, 0xfac95ca0, 0xd3a0f35e, 0xd4430ad1, "....." },
  [587] = { "申し分ないSnuff", "Booty BayのDeegは、Snuffを$N1個持ってきてほしいと言っています。", "ああ、海の暮らしよ。いい暮らしだとは言わねえが、これが俺の人生だ。\n\n港に入ったら、上等な酒を一本と、質のいいsnuffを手に入れるのが好きでな。悪い癖だが、悪癖のない海賊なんて何だってんだ、なあ？\n\nだから、この町の薬草屋がそいつを売り切らしちまったと知ったときの俺の落胆ぶりは想像がつくだろう。あいつが言うには、仕入れた荷をあの忌々しいBloodsail Raidersに奪われたんだと。\n\nお前みたいな恐れ知らずの{class}なら、奴らを説得して品を分けてもらえるんじゃねえか、え？", "品物は見つかったかい、相棒?", "お見事、{name}! しかもちょうど私が船出しなきゃならない直前に! いくら感謝しても足りないよ、我が旧友。", 0x7102b81b, 0xbfded4d7, 0x8ff9f2d8, 0x81ce3939, 0xbe0a915c, "....." },
  [588] = { "Yennikuの運命", "Kin'weelayと話してください。", "<Nezzliokが語る。>\n\n貴様は我と我が族長をなだめた。ゆえに、貴様が知ろうとしていることを教えてやろう……\n\n幼きYennikuは、もはや一族のもとには戻らぬ。\n\nあの子は呪術医Zanzil the Outcastに連れ去られた。今やZanzilが身も心も支配しており、あの子を解き放てるのは最も強力な魔法だけだ。\n\n貴様には無い魔法だ、{class}。\n\n貴様の味方のDarkspearなら、Yennikuを救う望みを与えられるかもしれぬ。だが、それも疑わしいがな。", nil, "Zanzil the Outcastだと？？\n\nYennikuがあのトロール、邪悪で強力な呪術師に囚われているのなら、残された望みはわずかだと恐れる。わずかだ。そして最も小さな虫ほどにささやかだ。\n\nそれでもなお、それは望みだ。", 0x963bfef7, 0x721300f2, 0x86249769, nil, 0xac54888b, "...m." },
  [589] = { "歌う結晶", "３個のPulsing Blue ShardsをGrom'gol Base CampのKin'weelayに届けてください。", "伝説によれば、Stranglethornの奥深くに宝玉が隠されているという。我々はそれをMind's Eyeと呼んでいる。大いなる力を持つ宝玉だ。このEyeを手に入れれば、失われたYennikuを闇から連れ戻せるかもしれん。\n\n俺はジャングルの精霊たちに伺いを立てて、Mind's Eyeを探す。その間に、お前はここから南東のCrystalvein Mineに入り、Ironjaw BasilisksからPulsing Blue Shardsを集めてくれ。その欠片は珍しいものだが、Mind's Eyeを我々の意のままにするには、その魔力が必要になる。", "shardは持ってきましたか、{name}? Mind's Eyeを手に入れたあと、私の最後の儀式に必要なのです。", "よくやった、{name}。この欠片はよく形を成している。すでに私に向かって歌うのが聞こえる。\n\nそしてお前が留守の間に、私はジャングルの精霊たちと語った。Mind's Eyeがどこに眠っているか分かったぞ……\n\n……そして誰がそれを守っているかもな。", 0x2da0084c, 0x37847b03, 0xf8832602, 0x9af70a3a, 0x62ef5d8d, "....." },
  [590] = { "ローグの取引", "DeathknellのCalvin Montagueを打ち負かしなさい。", "なに？\n\nなんだ！？\n\n金がほしい？てめえに金なんか借りてたっけな。\n\n手紙？何の？ああ、腕試しがしたいのかい？いいぜ、この野郎・・かかってこい！金がほしいならな・・。", nil, "信じられねえ！なんて腕だ！\n\nお前なんか楽な獲物だと思ってたぜ、{name}。見事にやられちまったよ。\n\nほら、約束の金だ……言ってたほどの額じゃねえが、そもそも俺が嘘をついてたんだから仕方ねえ。", 0x824c6911, 0x6ebdfe04, 0xcf0d4d70, nil, 0xfe24a85d, "...m." },
  [591] = { "Mind's Eye", "Mind's EyeをGrom'gol Base CampのKin'weelayに届けてください。", "Mind's Eyeを持っているのはogreのメイジで、ここから東、Mosh'Oggのogreの塚の奥深くにいる。名はMai'Zothだ。DarkspearsがStranglethornに住んでいた頃から奴を知っている。凶暴で、魔法も強力な奴だ。\n\nそして奴がMind's Eyeを持っているなら、その魔法はさらに強くなっているだろう。\n\nMai'Zothと対決し、奴からMind's Eyeを奪い取ってくれ。危険な任務だが、Yennikuを救うにはそれが唯一の望みなのだ。", "ごきげんよう、{name}。精霊たちはあなたの勇敢さを讃えて歌っていますが、Mai'Zothに挑むあなたのクエストについては何も語ってくれません。\n\nEyeは持っていますか?", "Mind's Eyeを取り戻したのだな！お前の力は伝説に語られるほどだ、{name}！\n\nそしてEyeを手に入れたということは、Mai'Zothを倒してNetherへ送ったに違いない。精霊たちが以前に奴のことを口にしなかったのはそのためだ。\n\n奴が肉と骨の世界から去ったのは良いことだ。だが今や霊の領域にいるとなると……奴が新たな支配を始めるのではないかと恐れる。\n\nだがそれは別のときに憂うべきことだ。今は、Mind's Eyeを我らの求めに従わせる儀式を行わねばならん……", 0x4a071d8b, 0x5c712db1, 0xcfd37200, 0x2d4ea819, 0x7b8c1f00, "....." },
  [592] = { "Yennikuの救出", "the Filled Soul GemをNimboyaに届けてください。", "Mind's EyeをSoul Gemに作り変えた。その役目は二つある。まずこれを使ってYennikuを気絶させ、気絶したらあの子の頭の上に置いて魂を封じ込めるのだ。\n\nそれから、その宝石をNimboyaのところへ持っていけ。\n\nYennikuはZanzil the Outcastと共に、遥かCape of StranglethornのCrystal Shore沿いにあるRuins of Aborazに住んでいる。", "{name}。Kin'weelayから、お前がYennikuを捕らえに出発したと聞いた。\n\n本当か? 奴を捕らえたのか?", "やり遂げたのだな！お前はYennikuをZanzilの意志から解き放ち、絶望的だと思っていた任務を成し遂げた。\n\n我らの部族はお前の名を歌に留めるだろう、{name}。そしてお前の物語を石に刻み、永遠に生き続けさせる。", 0x914a1248, 0x3b748f73, 0x19dd1329, 0x9558843d, 0xb9767aca, "....." },
  [594] = { "Message in a Bottle", "瓶に入った手紙の書き主を見つけて下さい。", "手紙にはかなり整った筆跡でこう書かれている：\n\n私を助けてくださる方へ――\n\nどうか、私は助けを切実に必要としています。巨大なSkymaneが、South Seasの島に私を捕らえているのです。\n\n夜の星は見慣れないもので、ジャングルの木々に遮られていますが、よく晴れた日には北西にWild Shoreが、南西には大きな帆船のようなものが見えます。\n\nお願いです、私の救い主となってくださる方、どうか助けてください。", nil, "私を解放しに来てくれたの?", 0xfc040a84, 0x4a0abedb, 0x3f76c6a2, nil, 0x5d3891b1, "...m." },
  [595] = { "The Bloodsail Buccaneers", "First Mate Crazzは、Booty Bayの北にある入り江を調べてくることを望んでいます。", "ずいぶん働く気満々じゃねえか、相棒。陸好きの{race}の{class}がなんでBlackwater Raidersに手を貸そうってのか分からねえが、追い返しはしねえよ。\n\nうちの船はここBooty Bayに着いたばかりなんだが、噂じゃライバルの……あの忌々しい薄汚えBloodsail Buccaneersが、Stranglethorn南部のあちこちで目撃されてるらしい。\n\n野郎どもはみんな、グロッグをあおったり女を探したりで手一杯だ！俺に必要なのは斥候なんだ。\n\nSavage Coast沿い、Booty Bayのすぐ北にある入り江を調べて、何があるか見てきてくれ。", nil, "樽の上に、いくつかのコインと走り書きのある地図を発見する。", 0x510d2515, 0x1ef9a2f7, 0x5c1f42f2, nil, 0x52bfd3e7, "...m." },
  [596] = { "Bloody Bone Necklaces", "Bloody Bone Necklacesを$N1個、Grom'gol Base CampのKin'weelayのところへ持って行って下さい。", "私はNimboyaのクエストを助けるためにGrom'golへ送られてきた。だが……私にもここにいる理由がある。\n\nBloodscalp族は我らの部族の敵だ。敵の戦利品を集めれば、奴らを支配する力が得られる。敵を狩ることで、我らの部族を助けてくれ。\n\n奴らは北に住んでいる。Bloodscalpのトロールを倒し、奴らからbloody bone necklacesを奪え。たくさん集めれば、報酬は大きいぞ。", "BloodscalpどもはいつかDarkspearに打ち砕かれるだろう! 滅びゆく敵のnecklaceは持ってきたか?", "ああ、とても良い。これを煮て、搾り取ってやろう。首飾りをすり潰して練り物にするにつれ、持ち主どもの霊は弱っていくのだ!\n\nほら、{name}。これでお前への借りを返そう。", 0x23dce729, 0x28fe164e, 0x433285e0, 0x68701d9c, 0xe76b8a34, "....." },
  [597] = { "The Bloodsail Buccaneers", "Booty BayのFirst Mate Crazzに見つけたものを報告してください。", "その地図にはBooty Bayが描かれていて、あなたが今まさに立っている場所に赤い「X」が正確に書き込まれている。\n\n走り書きにはこうある。\n\n「お前たちはこの場所に野営地を確保し、静かにしていろ。攻撃の前に、南の指揮所からの合図を待て。誰かが近づいてきたら殺せ。」", nil, "もちろん、覚えてるとも、{class}。偵察から戻ったんだな・・・", 0x510d2515, 0xc8679e80, 0x691f43be, nil, 0x946d2b81, "...m." },
  [598] = { "Split Bone Necklace", "Split Bone Necklacesを$N1個、Grom'gol Base campのKin'weelayのところへ持って行って下さい。", "Bloodscalpの戦利品を集めたなら、次の仕事がある。トロールのSkullsplitter族は南東に住んでおり、我らは何年も奴らと戦ってきた。DarkspearsはもうStranglethornには住んでいないが、我らはSkullsplittersとの争いに縛られているのだ。\n\nだから、奴らを狩れ。奴らのSplit Bone Necklacesを集めて私のもとへ戻ってこい。我らの戦いに力を貸せば、Darkspearsの友情を得られるだろう。", "Skullsplitterどもは我らを戦に引きずり込んだ日を呪うことになるぞ! 任務は果たしたか?", "これらの首飾りを手に入れるとは、お前の力は大したものだ、{name}。Skullsplittersどもは、Basiliskに踏みつけられた若木のようにお前の前に倒れていく!\n\nお前の働きは我々にとって恵みだ。", 0x4cd1eb74, 0xd50dc633, 0xb1821723, 0x73f9783c, 0xbca8dd47, "....." },
  [599] = { "The Bloodsail Buccaneers", "Bloodsailの攻撃計画をFleet Master Seahornに報告してください。", "なんてこった！じゃあBloodsail BuccaneersはBooty Bayに何か攻撃を仕掛けようとしてるってのか？まったく、あのろくでなしどもの図々しさときたら。Booty Bayを仕切るのはいつだってBlackwater Raidersだ！\n\n思ってたよりでかい話だな。分かったことをすぐにFleet Master Seahornに報告してくれ！あの老いぼれの海の男は町のどこかにいるはずだ……", nil, "Bloodsail Buccaneersが Booty Bayを攻撃する？\n\nOverlook Cliffsから飛び込んだほうがマシじゃないのか。それはともかく、情報をもってきてくれたことは、私の海賊艦隊に大きな助けとなった。Blackwater Raidersは感謝するよ。", 0x510d2515, 0xb8104f01, 0xf04a4890, nil, 0xb2fe93fb, "...m." },
  [600] = { "Venture Companyの採掘", "Singing Blue Crystalsを$N1個、Booty BayのCrank Fizzlebubのところへ持って行って下さい。", "Venture CompanyはStranglethornのあちこちで事業をやっていて、おかげで俺みたいな働き者のゴブリンが真っ当に金を稼げないんだ！ 頼む、助けてくれ！\n\nVenture Companyは北のCrystalvein Mineの近くで採掘している。basiliskがうじゃうじゃいるから鉱山には入れないが、周りの丘からSinging Crystalsを掘り出すことはできるんだ。\n\n奴らからクリスタルを奪って、ジャングルは奴らの好き勝手にはならないってことを思い知らせてやれ。\n\nそれから……えっと……証拠としてそのクリスタルを俺のところへ持ってきてくれ！", "あのcrystalは持ってきたかい?? 必要なんだ!!\n\nいや、その……悪のVenture CompanyがStranglethornで劣勢になっていると知る必要があるってことさ。だって、ほら、俺たち正直者は食っていかなきゃならないからね!", "すごい! 素晴らしい! これならひと儲けできるぞ!!\n\nVenture Companyもよりによって採掘するジャングルを間違えたもんだな? 奴らがここから出て行けば、みんなもっと暮らしが良くなるのに。\n\nありがとう、{name}。今日は良いことをしてくれたね。", 0x725c4050, 0xf87741d2, 0x458e0347, 0x263ca8b6, 0x83719a2f, "....." },
  [601] = { "Water Elementals", "Booty BayのBaron Revilgazのために、Water Elemental Bracersを$N1個手に入れて下さい。", "water elementalsは間違いなく、Stone of the Tidesを見つけたと噂されるゴブリンの魔法使い、Gazbanが召喚したものだ。知っているかもしれないが、Stone of the Tidesは持ち主を呪い、その存在を現れたり消えたりさせるのだ……\n\n呪いを打ち消す方法が見つかるかもしれない。Dalaranのメイジに、water elementalのbracersに残った魔力の痕跡を分析してもらえるだろう。島へ戻って、標本をいくつか取ってきてくれ。", "うまくいったか、{name}?", "ふむ、この腕輪のどれかが役に立つかどうか見極める目は私にはないが、少なくとも1つは役に立つはずだ。Dalaranに持って行って、メイジに見てもらいたまえ。\n\n何しろ、あの退屈な年寄りのメイジどもとおしゃべりするためだけに、Booty Bayを離れるわけにはいかんのでな。\n\n誰かが新しい男爵の座に割り込もうとするのを心配しているわけではないぞ。Revilgazに逆らって生きて帰った者はおらんのだ。", 0x3e585255, 0xd48f4a16, 0x1481c0a1, 0x10763147, 0x9b882430, "....." },
  [602] = { "魔法の分析", "water elemental bracersをDalaranのArchmage Ansirem Runeweaverのところへ持って行って下さい。", "聞いたところでは、Dalaranのメイジたちは破壊された都市の再建で忙しいらしいが、bracersを見るために時間を割いてくれる者もきっと見つかるだろう。メイジについて私が知っていることがあるとすれば、それは奴らが魔法の謎には抗えないということだ。\n\nwater elemental bracersの袋を持っていって、Stoneの呪いについて何か分かるか確かめてくれ。特にArchmage Ansirem Runeweaverを探すといい。以前に取引したことがあるが、彼の知識は膨大だ。", "よろしければ、今はかなり忙しいのですが。", "Stone of the Tidesだと? 実に興味深い。驚くかもしれんが、私は数年前、Gurubashi Empireの伝説に関する大著を書いたのだ。Stoneについてはかなりのことを知っている。\n\nこの腕輪のうち少なくとも1つには、分析できそうな魔力の残滓があるようだ。\n\nさて、何が分かるか見てみよう……", 0xaaaa195b, 0x5436bf30, 0xe56db3f9, 0xececebaa, 0x1dcf5c25, "....." },
  [603] = { "Ansiremの鍵", "Booty BayのCatelynと話して下さい。", "Stoneを持っているメイジは、何らかの焦点……ある種の祭壇を通じて、その力を増幅している。それを上回る力で圧倒すれば、妨害できるはずだ。\n\nちょうど打ってつけのものを知っている。古代の短剣、これもトロールの遺物だ。ただ一つ……小さな問題があってな。\n\n実は、その短剣はStranglethornで研究中に見つけたんだが、わがままな娘のCatelynにやってしまったんだ。あの子は海賊になるためにBooty Bayへ飛び出していった。", nil, "短剣だと? お前、お笑い芸人か何かか?\n\n何だ? Booty Bayで一番のナイフ使いだった私が、海賊界の笑い者に落ちぶれた話をもう一度させたいってのか!\n\nBloodsail Buccaneersの一人とのナイフ勝負に負けてな――まったく最低の悪党どもだ!――そいつが戦利品として私の刃を持っていったんだ。\n\n悪口と毒舌だけでナイフ使いとしてやっていけるわけじゃないんだぞ……", 0x9a103ea7, 0xc1e31c39, 0xa3690746, nil, 0x81dceaee, "...m." },
  [604] = { "The Bloodsail Buccaneers", "Booty BayのFleet Master Seahornはあなたが１０人のBloodsail Swashbucklersを殺し、海図（Bloodsail Charts）と指令書（Bloodsail Orders）を持ってくることを望んでいます。", "Crazzがお前のBlackwater Raidersへの献身ぶりを高く評価している。艦隊にとって極めて重要な任務を、お前に任せよう。\n\nBloodsail BuccaneersがWild Shoreに設けた、いわゆる南の指揮所に潜入しろ。野営地を襲撃して、奴らの海図と書面の命令書を持ってこい。あのクズどもが何を企んでいるか、はっきりさせてやる。", "やあ、{name}。南のBloodsailの野営地について、どんな知らせを持ってきた?", "完璧だ、{name}。奴らの計画が分かった以上、あとは時間の問題だ。\n\nそれにしても、あの愚か者どもが岬のすぐ沖に錨を下ろしているとはな……", 0x510d2515, 0x6df83923, 0x494ea837, 0x3378040a, 0xc33bdb34, "....." },
  [605] = { "歌う青い欠片", "10個のSinging Crystal ShardsをCrank Fizzlebubに届けてください。", "歌う結晶（Singing Crystals）はStranglethornの特産で、ある人たちにとても価値があります。私はそれらの結晶を扱うことができますが、いまいましいVenture Companyは私のような誠実な事業家がそれを集めるのを難しくしています！\n\nあなたを雇いたいです。\n\nStranglethornのbasilisksは結晶を食べます。これが彼らに堅い皮を与え、そこから、時々質のよい結晶がとれます。どのBasilisksからでもそれを集めることができますが、北へいってZul'Kundaの南海岸沿いが、それほどひどくないでしょう。", "shardはまだか? 儲けからそれなりの分け前をやるぞ!", "ははあ！これでいい具合になるぞ、{name}。ああ、実にいい具合だ！\n\nこれが取り分だ。それと……取引ができて楽しかったよ。", 0xacede0e8, 0x5ec2f4ef, 0xf9bb4eb8, 0x342643ab, 0x557902cd, "....." },
  [606] = { "Shakyを脅かす", "Booty Bayの”Shaky”Phillipeに５個のMistvale Gibletを持っていってください。", "我慢できないことがあるとしたら、賭けの借金を払わない奴らだ！それに、俺に借りのある奴は大勢いる。取り立てを手伝ってくれるか？\n\nまずは波止場にいる\"Shaky\" Phillipeだ。先週の勝負の後、あいつは俺にたっぷり借りがあるから、取り分はきっちりもらいたい！だが取り立てるには、あいつを脅かしてやらなきゃならない。\n\n町の外へ出て、Elder Mistvale Gorillasを狩ってこい。上等なgibletsを見繕ったら、Shakyのところへ持っていけ。動物のものだとは言うなよ。最悪の想像をさせておけ。", "おい! その目つきは気に入らないな、あんた。", "うわっ！これをどこで手に入れた？いや、言うな。知りたくない！\n\n誰が寄こした？Sea Wolfか？", 0xd2e4865c, 0x2e151262, 0xf84c4f8d, 0xa1b54f0a, 0x19c5bd71, ".....", nil, nil, nil, 0x8096ff85, nil },
  [607] = { "MacKinleyへ戻れ", "Shaky's Paymentを\"Sea Wolf\" MacKinleyのところへ届けてください。", "ほら、この袋を持っていってSea Wolfに渡してくれ。それと、返すつもりだったって伝えてくれよ！本当なんだ！！\n\nちょっと酔っ払って道に迷っちまって、それで……ほら、よくあることだろ。あいつなら分かってくれる。手荒な真似はしなくていいんだ！", "ほらほら、{name}。Shaky's paymentは受け取ってきたか?", "へへ、よくやった！Shakyにあの臓物を見せたとき、奴はどれだけ震えた？\n\nはっ！奴は実に読みやすくてな、カードで勝負すると勝たずにいられん！\n\n助かったよ、{name}。さあ、今度はお前が報酬を受け取る番だ……", 0xfb2b2b27, 0x55c76f49, 0xf2218fb0, 0xa96f862d, 0xf93cb46c, "....." },
  [608] = { "The Bloodsail Buccaneers", "Booty BayのFleet-Master SeahornはあなたがCaptain Stillwater、Captain Keelhaul、Fleet Master Firallonを殺すことを望んでいます。", "Firallonの図太さときたら！あいつはCrystal Lakeで小舟ひとつ操れやしない。ましてや艦隊を丸ごと率いて我々に挑むなど論外だ。\n\nBloodsail Buccaneersには、その軽率さの報いを受けさせてやる。奴らの攻撃計画が分かった今、何が起きたか気づかれる前に反撃できる。\n\nだが、勇敢な冒険者の一団で済む仕事に、なぜ艦隊を丸ごと送る必要がある？{name}、腕利きの仲間を何人か連れてFirallonの上陸地点へ向かい、Bloodsailの指導者たちを暗殺してこい。奴らの艦隊もすぐに沈むだろう……", "どうした、{name}? Bloodsail Buccaneersより先に攻撃しなきゃならないんだぞ!", "ああ、なんてBlackwater Raidersにとって素晴らしい日なんだ！　{name}に、万歳三唱！", 0x510d2515, 0xc1811346, 0xee5f4287, 0x51546d57, 0x5787f719, "....." },
  [609] = { "ブードゥーの取り立て", "Maury's Clubbed Foot、Jon-Jon's Golden Spyglass、Chucky's Huge RingをBooty Bayの\"Sea Wolf\" MacKinleyのところへ持って行って下さい。", "俺のリストも短くなってきたが、まだ借りのある奴らがいる。\n\n次は、Maury \"Club Foot\" Wilkins、Jon-Jon the Crow、それにChucky \"Ten Thumbs\"だ。\n\nこの薄汚い犬どもの借金は何か月も滞ってて、支払いを逃れるために町をずらかったんだと思ってた！ 後になって、奴らは呪われて魔法にかけられ、今はジャングルの遺跡をさまよってると聞いた。だが奴らの運命なんかどうでもいい――俺のものを返してもらいたいんだ！\n\n奴らはここの北東、Ruins of AborazとRuins of Jubuwalにいる。見つけて、取り立ててこい。", "{name}、その3匹の犬どもは見つかったか? 奴らの貴重品は集めてきたか?", "すごい! これならいい値で売れるぞ、特にMauryの足の中身はな! どうもありがとう、{name}!\n\nあの3人も懲りただろう。失って困るものは賭けるな、ってな。\n\nあいつらにはもう手遅れかもしれないが……賭けの相手は慎重に選ぶべきだな。", 0x962a26df, 0xb218e067, 0x255c55ec, 0x9af2c2aa, 0x06cce9fb, "....." },
  [610] = { "\"Pretty Boy\" Duncan", "\"Pretty Boy\" DuncanからCatelynの短剣を取り戻して下さい。", "父があなたをよこしたの？ あの頑固じじいは、もうとっくに私のことなんか諦めてると思ってたわ。\n\n私が飛び出したのは、別に父のせいってわけじゃないの。ただ、私がかび臭い本を読みふけって、白髪頭で背筋のこわばった堅苦しいメイジたちと付き合う退屈な人生を喜んで送るなんて、期待するべきじゃなかったのよ！\n\n私の短剣が必要なら、Bloodsail Buccaneersの一人、\"Pretty Boy\" Duncanから取り戻してもらうしかないわ。あいつの肩の間に何かぶち込んでやれば、きっと手放すわよ。", "俺はそれまで負けたことなんてなかったんだぜ、なあ、{name}? そりゃ切られたことはあるさ、ナイフで喧嘩すりゃそれは避けられねえ。だがあいつは俺の頭の横をぶん殴って、気絶させやがった。気がついたら刃物がなくなってたんだ。\n\n俺のあだ名がどう聞こえようと、喧嘩にはやっぱりナイフがいる。そして俺にとっては、あのナイフじゃなきゃ駄目なんだ。", "Duncanに勝ったって? 見た目ほど青二才じゃないってことか。\n\nってことは、しばらくはお前に勝負を挑まないほうがいいってことだな!", 0x57decda3, 0x6d4acf06, 0xd8a8506c, 0x286b5b9c, 0x6bdc9af0, "....." },
  [611] = { "潮の呪い", "Catelyn's BladeでAltar of the Tidesを破壊し、Gazbanを倒して、Stone of the TidesとCatelyn's BladeをBaron Revilgazのところへ持ち帰って下さい。", "何かの祭壇を探してるの？ そうね、私は父みたいにトロールの遺跡に詳しいわけじゃないけど、あなたが探している島の近くに、沈んだトロールの都市があるって聞いたことがあるわ。そこを当たってみたら？\n\n私のナイフを取り返してくれたんだから、貸してあげてもいいわ……でも、用が済んだら返してね！", "Stone of the Tidesは取り戻してくれたかな、{name}? もう置き場所を空けて、立派な台座も買ってあるんだ。", "素晴らしい! Stone of Tidesだ! 私の古代トロールの遺物コレクションの中でも目立つ場所に飾ろう。その表面の中に潮が閉じ込められているかのように見えるのが分かったかね? 見事だ!", 0x697aba77, 0x4bea2565, 0x1489277b, 0xc3062f81, 0x419535a9, "....." },
  [613] = { "Mauryの足をこじ開ける", "Maury's KeyをBooty Bayの\"Sea Wolf\" Mackinleyのところへ持って行って下さい。", "くそっ！ あの下っ端のMauryめ、自分の足に錠をかけやがって、開けられねえ！ 奴のお宝はその足の中にあって、それが奴の借りなんだ！\n\n錠を開ける鍵を見つけなきゃならねえ。Mauryは北東の塚にいるMosh'Ogg ogresと賭け事をしてたことで知られてる。それに奴は、まだ生きてた頃に俺に言ってたんだ。最後に塚へ行ったとき、勝ちすぎて追い出されたってな。たぶんそこのOgresが奴の鍵を持ってるんだろう。\n\nだが、持ってるとしても、当たりを見つけるまでに山ほど殺す羽目になるかもしれねえな……", "おう、{name}! Maury's Keyはもう見つかったか?", "見つけてくれたか! 本当にありがとう、{name}。大いに助かったよ!\n\nさあ、どうぞ。これは君が手にしたものだ!", 0xe13fb578, 0x644106c2, 0x193abf70, 0xc4a54879, 0xd3d77dcd, "....." },
  [614] = { "船長の宝箱", "Smotts' ChestをBooty BayのHecklebury Smottsのところへ持って行って下さい。", "かつて私はここからKalimdorのRatchetまで船を走らせていた。立派な評判を持つ、成功した船長だったのだ。\n\nそれが……\n\nあの呪われたsea giantsに破滅させられた！ 奴らは私の船を叩き壊し、乗組員を殺し、私を救命ボートに乗せてBooty Bayへ流したのだ。しかもgiantsの一体、Gorlashが私のCaptain's Chestを盗んでいった。嗅ぎタバコ入れにしたいんだとさ。ふざけおって！\n\nGorlashはここの東の海岸をうろついているそうだ。奴を見つけて私の箱を取り戻してくれ！ そうすれば、船長の感謝を得られるぞ。", "おう、{name}! Gorlashは見つかったか? あのchestは俺のお気に入りでな、隠し仕切りがあって、そこに俺の一番のお宝をしまってたんだ!", "見つけてくれたか! なんて幸せな日だ! ありがとう、{name}。宝箱が戻って、胸の炎も少しは収まったよ。\n\nだが、俺の復讐はまだ終わっちゃいない……", 0xba51aa97, 0x91038538, 0x167e029a, 0x06215b45, 0x6b909651, "....." },
  [615] = { "船長のカトラス", "Sproggerと話して下さい。", "最初の船をあのgiantsに奪われた後、私はもう一隻買った。Smotts' Revengeと名付け、物資と乗組員を満載して悪党どもを探しに出た。奴らを見つけはしたが……負けてしまった。奴らはSmotts' Revengeを叩き壊し、二度目の乗組員を殺し、私をまた救命ボートに乗せたのだ。\n\n今度は別のgiant、Negolashが私のカトラスを盗んでいった。\n\nNegolashと対決して、私のカトラスを持ってきてくれ！\n\nSproggerと話すといい。彼はSmotts' Revengeの料理人で、この前の襲撃を生き延びた。giantを見つける手助けをしてくれるだろう。", nil, "やあやあ、{name}。Negolashを追うんだって、船長から聞いたぜ?", 0xb8962084, 0x114316b6, 0xb86aff68, nil, 0x2c14bb44, "...m." },
  [616] = { "呪われた島", "Booty BayのBaron Revilgazと話して下さい。", "Baron Revilgazから、Booty BayとStranglethornで起きる奇妙なことや場違いなことの噂に耳を澄ませておくよう言われているんだ。普段は幽霊話なんてあまり信じないんだが、酒場で船乗りたちが、沖合の幽霊島の話をしているのを聞いてね。water elementalsと、わめき散らすゴブリンの幽霊が出るんだとさ。\n\nRevilgazと話しに行くなら、その話を伝えてくれないか？", nil, "興味深い。以前、ある本を読んだ覚えがあるのだが、それによると……\n\nああ、そうだ、トロールの伝説だった。Krazekの報告が本当なら、じきに私の古代の遺物と聖遺物のコレクションにStone of the Tidesを加えられるかもしれん。", 0xf6fb90c5, 0x92e6dd47, 0x727c3587, nil, 0x49c9ec1c, "...m." },
  [617] = { "Akirisを束で", "Bundles of Akiris Reedを$N1個、Booty BayのPrivateer Bloadsのところへ持って行って下さい。", "仕事を探してるのかい、{name}？ ちょっとした難題に挑む気があるなら、仕事があるかもしれないぜ。\n\nGroyって友達がいてな、nagaがakiris reedと呼んでるものを売ってひと儲けしてるんだ。価値のある海の葦の一種さ。何に使うのかはよく知らないが、束にして持っていけば気前よく払ってくれる。\n\nそいつを十本持ってきてくれたら、取引といこう。nagaが最後に目撃されたのは、ここから北の浜辺沿いだ。", "俺に用がないなら、さっさと行きな、{name}。", "よくやったな、{name}。akiris reedを10本なんて、結局そんなに難しくなかっただろ? nagaには悪いけどさ、まあ、誰だって食っていかなきゃならないからな。", 0xd9e6e473, 0x5e477a00, 0xf3d0a096, 0xdf505042, 0xcbb927e5, "....." },
  [618] = { "Negolashとの対決", "Barbecued Buzzard Wingsを$N1個とJunglevine Wineを$N2本、Captain Smotts' Lifeboatへ持って行って下さい。\n\nNegolashを倒し、Smotts' CutlassをStranglethornのCaptain Smottsのところへ持って行って下さい。", "Negolashは腹を空かせたgiantだ。\n\ngiantsが俺たちの船を壊したとき、Negolashはまっすぐ俺の厨房に向かった。奴は他のgiantsと違って、乗組員を食おうとはしなかった。Negolashが欲しがったのはワイン……それに俺のBarbecued Buzzard Wingsさ。あれは俺の得意料理で、レシピを手に入れるためにわざわざBadlandsまで行ったんだぜ！\n\ngiantをおびき寄せたいなら、ワインとbuzzard wingsを山ほど手に入れてくれ。それを、ここから南東の海岸沿いにある俺たちの古い救命ボートに置くんだ。Negolashがあの食い物の匂いを嗅ぎつけたら、きっとやって来るさ！", "俺のcutlassは手に入れたか、{name}?", "Negolashから俺のカトラスを取り返してくれたのか! この幸運が信じられないよ、{name}! あんたに会ってから運が上向いたんだ、間違いない!\n\nありがとう! もしまた新しい船を手に入れて、あんたが海を渡りたくなったら、名誉ある客人として迎えるよ。", 0x73a04fad, 0xeb22c78b, 0xcd78a826, 0x224ded7e, 0x423de715, "....." },
  [620] = { "名入りの飾り帯", "Monogrammed Sashを持ち主に返して下さい。", "この上等な飾り帯の裾には、「HS」という文字が刺繍されている。", "こんにちは。私に何か用ですか?", "俺の飾り帯を取り戻してくれたのか? ってことは……sea giantのMok'rashを倒したんだな! やったぞ!\n\nあの卑劣な悪党が死んでせいせいした。Mok'rashは、俺の船を叩き壊して乗組員を殺した3体のsea giantの1体だったんだ。\n\nそれも3度もだ。\n\nお前は価値ある{class}だ、{name}。", 0xf25f7e16, 0xaf626a54, 0xd7b275b4, 0x48a14437, 0xd35d9f2e, "....." },
  [621] = { "Zanzilの秘密", "Zanzil's Mixtureのサンプルを$N1個、Booty BayのCrank Fizzlebubのところへ持って行って下さい。", "Zanzil the Outcastは、Booty Bayの北東にあるJubuwai and Aboraz Ruinsで手下とともに暮らしている。奴は部族から追放された。なぜか？ それは……\n\nZanzilには他者の心をねじ曲げる術があり、部族の長たちは奴を恐れている。奴はジャングルの植物を混ぜた調合薬を手下に使い、その意志を抑え込み、肉体を強化しているのだ。\n\n奴の調合薬は、他者を支配したい者にとって大きな価値があるだろう。\n\n奴の調合薬の見本を持ってこい。使い道は私が見つけてやる。", "Zanzil's Mixtureのサンプルは持ってきたか??", "ああ、上出来だ! これが報酬だ。\n\nそれと、ちょっとした心付けも……口止め料としてな。", 0xc7e837c0, 0x61d1e034, 0x429872fb, 0x4aa1f344, 0x0d2b5bc6, "....." },
  [622] = { "Corporal Kalebのもとへ戻る", "Krazek's Fixed PotをRebel CampのCorporal Kalebのところへ持って行って下さい。", "君がいない間に、持ってきてくれた鍋を直しておいたよ。おまけの蒸気の笛まで付けたし、見てくれ！ 底には脚の骨も切れる新しい刻み刃が付いてるんだ！\n\nそうそう、Krazek's Crock Potは$N1%料理人を満足させる逸品さ！ 持ち主もきっと満足するよ。", "こんにちは、{name}。Booty Bayには着けた? ゴブリンのKrazekは私の鍋を直してくれた??", "直ってる! 素晴らしい、これで夕食の支度を始められる! 本当にありがとう、{name}。\n\nBooty Bayで無事だったならいいんだけど。あそこはかなり荒っぽいところだし、それに……噂で聞いたんだ。ゴブリンたちは時々、酔っ払った船乗りを奴隷船に引きずり込んで、どこか分からない場所へ連れて行って……何をさせるのか分からないって……", 0x22e5a683, 0x965ee96d, 0x16dd3fe7, 0xfe60f35b, 0xc3e2394d, "....." },
  [623] = { "Akirisを束で", "Bundle of Akiris ReedsをTheramoreのPrivateer Groyのところへ持って行って下さい。", "{name}、せっかくここにいるんだから言っとくと、君がいない間にGroyから知らせが来たんだ。この前届いた荷に満足してて、今すぐもっと欲しいって客がいるんだとさ。\n\n俺は一週間はTheramoreへ行けないんだが、君がその旅をしてくれるなら、俺の代わりにブツを持っていってくれて構わないぜ。\n\n冒険したい気分かい？ Dustwallow Marshがどこかは知ってるよな？ ただ、気をつけな。Theramoreは、場違いな連中だと危ないことがあるからな。", "何だ?", "何だ?! お前みたいな奴と話すより、ずっとましなやることがたくさんあるんだ、{class}。俺の時間に見合うものを出すか、さっさと目の前から消えな。\n\nん? Bloadsに言われて来ただと? で、何を持ってきた?\n\n<Privateer Groyは束を注意深く調べている。>\n\n悪くない、全然悪くないな。もう一束あれば、依頼人もかなり喜ぶだろう。\n\n次に聞くのは金のことだろう、{class}? もちろんそうだよな!\n\nほら、この金とひとつ忠告を持っていけ。俺の波止場から出ていけ。", 0xd9e6e473, 0x6ca7d107, 0x9c6f02ba, 0x27e69c4e, 0x2f00a790, "....." },
  [624] = { "Cortello's Riddle", "謎を解け！", "飾りのついた、人通りの多い橋  Deadwindの東、Redridgeの南  その下に何かがまってる  それがヒント、それが手がかり  終わりのない明日のために横たわっている  Swamp of Sorrowsでその時を待っている", nil, "ずぶぬれの羊皮紙が次への手がかりだ・・・", 0xb7c95537, 0x2214c47e, 0x2f0eac4b, nil, 0xc681a893, "...m." },
  [625] = { "Cortello's Riddle", "謎を解け！", "Kalimdorの遠い国で待っている  希望と運命が打ち砕かれる危険な場所  Barrensの東は荒れ模様  憂鬱と危険がDustwallow Marshに入り混じる  しかし試練をとくカギはそこにある  南西の洞窟で待っている", nil, "かび臭い巻物を見つけた。", 0xb7c95537, 0x2214c47e, 0x8d10c3b8, nil, 0x1c6b722d, "...m." },
  [626] = { "Cortello's Riddle　最終章", "謎を解け！", "Lordaeronへ！混迷の大地へ！\n\n死せる勇敢な戦士が苦戦する場所  大いなる混乱を抜けて道を見出すのだ  そこで謎かけも終わり  Hinterlandsの海岸沿いの大きな滝の底  宝が君を呼んでいる！", nil, "発見した宝箱を開いた・・・", 0xb7c95537, 0x2214c47e, 0x3f5194d1, nil, 0x5e342f1f, "...m." },
  [627] = { "Krazekへの頼み", "Lesser Bloodstone Oreを$N1荷、Booty BayのKrazekのところへ持って行って下さい。", "Arathi Highlandsのはるか北、Drywhisker Gorgeに山の洞窟がある。その洞窟には珍しい鉱石、bloodstoneがあるんだ。この洞窟のbloodstoneは最高級ではないが、質の低いbloodstoneでも価値がある……使い方を知っている者にとってはね。\n\n少し欲しいんだ。\n\n君の鍋は直してあげるよ。でも、私が作業している間に……bloodstoneの見本を持ってきてくれ。十分に持ってきてくれたら、おまけもあげよう。\n\nああ、それから、自分に採掘の腕がないなら……腕のある者を見つけてくれ！", "こんにちは、{name}。bloodstoneは手に入りましたか?", "ああ、素晴らしい! 大いに助かったよ。\n\nこれが代金だ……", 0x33fb2ce4, 0x5399cea0, 0xbd795a61, 0x7028d3f2, 0x96c8bd23, "....." },
  [628] = { "Excelsior", "Elder Crocolisk SkinをBooty BayのDrizzlikのところへ持って行って下さい。", "内側ができあがったから、あとは外側の層を付けるだけだ。これには最高のelder croc skinsしか使わないんだよ。丈夫だし、Drizzlik's Excelsiorシリーズならではの模様や装飾を施す……言ってみればキャンバスとしても、より優れているんだ。\n\nでも、完璧な皮を見つけるのは難しくてね。僕の計画に合うのは、elder saltwater crocoliskの皮だけなんだ。elderは他のsaltwater crocsを守るときにしか出てこないから、おびき出すには何匹か倒す必要があるかもしれないよ。", "saltwater crocoliskがだんだん数を減らしているとどこかで読んだよ……商売にとっては悪い知らせだよね?\n\nとにかく、elder saltwater crocolisk skinを持ってきてくれているといいんだけど!", "よし! 君のおかげでこの注文を仕上げて、次のUndermine行きの船でDirector Riddlevoxに送れるよ。予定より早いくらいだ!\n\n頑張ってくれたお礼に、ほら、余分に作っておいたから一足持っていきな。Drizzlikのおごりだ。\n\nそれと覚えておいてくれ、DrizzlikのExcelsior lineほど素晴らしいブーツはないってね!", 0xf1b79015, 0x3c34bfeb, 0x45b14635, 0xb145754b, 0x11fc4dc4, "....." },
  [629] = { "The Vile Reef　不愉快な岩礁", "Tablet ShardをGrom'gol Base CampのKin'weelayに届けてください。", "昔々、大きな地震で、北西のSavage Coastの水の下に、古いトロルの街が沈みました。私たちはその場所を不愉快な岩礁（The Vile Reef）と呼んでいます。というのも今はmurlocsが街の廃墟に棲みつき、近づくもの全てに攻撃するからです。\n\nその廃墟に、トロル伝説の英雄 Gri'lekの古代の物語が書かれた古い銘板があります。その話はDarkspear族にとって神聖なものです。銘板は動かすには余りにも大きすぎますが、Orgrimmarにある我々の新しい本拠地に安置するため、私はその破片が欲しいのです。", "Tablet Shardを待っているぞ、{name}。", "これは良い。Orgrimmarに戻ったら、この欠片を聖なる場所に納めよう。Gri'lekの力と誇りを我らに思い起こさせてくれるだろう。\n\nありがとう、{name}。お前の行いはDarkspear部族との深まる友情の証だ。", 0x36f48b37, 0x41e6a6f8, 0x346b4e5c, 0x9689d6b4, 0x766bbf8d, "....." },
  [630] = { "Message in a Bottle", "King Muklaを倒し、Keyを持ってPrincess Poobahのところへ戻り、彼女を解放して下さい。", "{name}、私はあなたと、あなたが集められる限りの仲間に、私の解放を託します。私を捕らえているのは偉大なるSkymane King Muklaです。彼はこの島の獣たちを従え、獣たちはこの鎖で私を意に反してここに留めているのです。彼を倒し、この枷の鍵を見つけてくれたなら、私はあなたに大きな恩を負うことになるでしょう。\n\n彼の声は島の南東側からよく聞こえますが、どうか気をつけてください。彼は侮れる相手ではありません。", "助けに来てくれた者がいることを先祖に感謝する。私を解放する鍵は持っているか?", "{name}、あなたは私を大きな不名誉から救ってくれた。私にその力があれば、私の部族の一員として迎えたいところだ。だが今は、あなたが示した勇気と高潔さに対して、この証を渡すことしかできない。", 0xfc040a84, 0xa51b7d5d, 0xaac9ce97, 0x2646e1f4, 0x4ba656c3, "....." },
  [631] = { "Thandol Span", "Rhag Garmasonは、Ol' Rustlockeを見つけてほしいと言っています。", "凄まじい爆発が丘に轟いたんだ。ひどいもんだったよ、本当に！\n\nThandol Spanを守って、立派な兵士たちが死んだ。Longbraidは、すべてが片付く前にDark Ironsに復讐してやると言っている。\n\nだが、わしらは大変な苦境にあって、援軍が来る気配もない。Longbraidは、東の橋を確保できるかどうか偵察させるために、Ol' Rustlockeを送り出したんだ。\n\nそれが何日も前のことだ。Dun Modrが包囲されている今、彼を捜す人手もない。\n\nもしかしたら、お前さんなら彼を見つけられるかもしれん……", nil, "あなたは小さなドワーフの亡骸を調べた。兜に刻まれた文字がはっきりと読める。Ebenezer Rustlocke。", 0x3e71d80d, 0x65e8a88f, 0xe1ea688d, nil, 0xbdd11f16, "...m." },
  [632] = { "Thandol Span", "Rhag Garmasonのところへ報告に戻り、Rustlockeの死体から見つけた羊皮紙を見せて下さい。", "哀れなOl' RustlockeはDark Ironの待ち伏せに遭ったようだ。握りしめた拳のそばに羊皮紙があるのに気づく。\n\nこの痛ましい知らせをRhag Garmasonに伝え、見つけたものを見せなければ。", "Ol' Rustlockeの手がかりはあったか、{name}?", "なんと、深刻な知らせだ……。", 0x3e71d80d, 0xef615b26, 0xa9d711d2, 0x96040fe2, 0x33bc05e5, "....." },
  [633] = { "Thandol Span", "爆薬の隠し場所を破壊する。", "なんてことだ！ 哀れなRustlocke。まったくの悲劇だ。\n\n彼の死を無駄にしてはならん。お前さんが見つけたこの羊皮紙によれば、最初の攻撃の首謀者であるKam Deepfuryが、Thandol Spanを渡ってすぐのArathi Highlandsに、爆薬の隠し場所を用意させたらしい。\n\nあの爆薬が橋に届けば、北への主要な補給線が断たれてしまう！ その隠し場所を破壊するのだ、{name}！ 任務を終えたら戻ってきてくれ。\n\nお前さんだけが頼みの綱だ。", "爆薬の貯蔵庫を破壊しなければならない!", "残った橋は守られた! あなたはKing MagniとKhaz Modanの民に大きな貢献をしてくれた。\n\nあとは援軍が現れるまで持ちこたえられさえすれば……", 0x3e71d80d, 0xb3f61268, 0xc3ede072, 0x51d8635c, 0x8b545d8f, "....." },
  [634] = { "Allianceへの嘆願", "Refuge PointeのCaptain Nialsを探し出して下さい。", "もう一つだけ小さな頼みがある、{class}。わしらはIronforgeからの予備軍を待っている。だが、Roggoが、北のArathi HighlandsのRefuge PointeにAllianceの野営地があると知っているんだ。\n\nそこへ行って、Captain Nialsを探してくれ。Dun ModrとThandol Spanを取り戻すために、Allianceが兵を割いてくれるかどうか、隊長殿に尋ねてほしい。", nil, "Longbraidと彼の勇敢な兵たちにお悔やみを申し上げる。Thandol Spanの悲劇とDun Modrの陥落の知らせが、私の心に重くのしかかっている。\n\nだが、Stromgardeも陥落したのだ! それゆえ我々はここRefuge Pointeにいる。我々は自らの偉大な都市を奪還しなければならない。\n\n名誉と義務にかけて、Stromgardeが再び王の力強い旗を掲げるまで、我々はHighlandsを離れるわけにはいかない。Longbraidには、自力でやってもらうしかないと伝えよう……", 0x8bc74a92, 0xb6fee4d4, 0x8240441f, nil, 0xa65d819b, "...m." },
  [635] = { "山の中の水晶", "幻視で見た水晶を見つける。", "手に持つと、この欠片は脈打っている……\n\n欠片から懇願するような気配を感じる。まるで誰かが意思を伝えようとしているかのようだ。あなたの助けを切実に必要としている誰かが。\n\n心の中に光景が浮かぶ――Arathiの北の山々と、そこで大地から突き出た輝く水晶の光景が。\n\nその場所に引き寄せられるのを感じる。", nil, "この水晶は、まるで生きた力が中に閉じ込められているかのように脈動している。", 0x349e436e, 0xe28c2428, 0x82f29cd5, nil, 0x196b3ba0, "...m." },
  [636] = { "大地の伝説 <NYI>", "Shards of Myzraelを見つける。", "この本は、元素の王女Myzraelと、Arathi Highlandsの地下深くへの彼女の幽閉の物語を伝えている。\n\nまた、高地にある秘密の水晶の露頭についても記されている。その水晶、Shards of Myzraelは、王女の牢獄への窓なのだ。\n\n勇敢な者がShards of Myzraelを見つければ、おそらくその者は彼女と話せるだろう……", nil, nil, 0x6dc7dc64, 0xd464d7a9, 0xce12c5d2, nil, nil, "...mm", nil, nil, 0xf15dd481, nil, nil },
  [637] = { "Sully Balloo's Letter", "Sully Balloo's LetterをSara Ballooに届けて下さい。", "水浸しで戦火に傷んだ封筒は手の中で崩れ、細心の注意を払って書かれた数枚の手紙だけが残る。\n\n手紙はIronforgeのMrs. Sara Balloo宛てで、「親愛なるSaraへ……」という書き出しで始まっている。", "長い道のりを旅し、これまでに多くの騒乱を目にしてきたようだな、{class}。我々が生きるこの時代は魂にとって試練だ。今度はどんな知らせを持ってきた?", "私のSullyが凍てつく水の底で身動きが取れなくなっているのを見たって? 嘘だと言ってくれ!\n\n彼が何を書いたのか読ませてくれ……", 0x16ea5dcb, 0xe1099d7a, 0x1cae80a2, 0xde03d404, 0x83ce737d, "....." },
  [638] = { "Trollbane", "Arathi HighlandsのHammerfallへ行き、Zenguと話してください。", "Thoras Trollbaneが死にStromgardeが廃墟となると、Vol'jinは人間たちの手にある伝説剣Trol'kalarに我々の全力を向けるように指示しました。来たるZul'Gurubトロルとの戦いのために。\n\nそれで、我々の経験豊かなハンターの１人、Zenguが剣の獲得を監督するために北東のArathi HighlandsにあるHammerfall に緊急派遣されたのです。", nil, "調子はどうだ、{class}？Vol'jinが我らに課した務めは困難なものになる。お前が貸してくれる力はどんなものでもありがたく、そして必要なものだ。", 0x4e0c58be, 0xbfa57060, 0x0f926ec8, nil, 0x826aba35, "...m." },
  [639] = { "Sigil of Strom", "HammerfallのZenguのために、Sigil of Stromを手に入れて下さい。", "古の時代、トロールはArathorian Empireと、我らの最も手強い敵、Trollbaneと呼ばれたLord Ignaeus of Stromと戦った。奴はTrol'kalar――奴らの古の言葉で「トロール殺し」――を振るって戦場に乗り込んだ。\n\nだが今やTrollbaneの子孫は弱り、その砦は廃墟と化した。\n\nその剣はいくつかのsigilsによって守られており、それらはStromgardeの生き残りたちの間で分けられた。我らはそれを取り戻さねばならない。\n\n一つ目はSyndicateに奪われた。Stromgardeにいる奴らの手下の一人が持っているはずだ。", "最初のsigilはもう見つかったか? おそらくStromgardeにいるSyndicateの工作員の誰かが身につけているはずだ。", "上出来だな、おい。Trollbaneの墓からTrol'kalarを取り出すのに必要な印章集めとしては、幸先のいいスタートだ。", 0xba092783, 0xa09b5509, 0xc36e5b99, 0x2ca366cd, 0xc091db47, "....." },
  [640] = { "壊れた印章", "Stromgardeの守備兵から$N1個のSigil Fragmentsを回収し、HammerfallのTor'ganのところへ持って行って下さい。", "Thoras Trollbaneの墓は三つのsigilsで守られている。その一つ目はお前がSyndicateから取り戻したものだ。残りの二つは手に入れるのがもっと難しい。堅く守りを固めたStromgardeの民兵が持っているからな。\n\nThoradinのsigilは、Thorasの息子Galenによって十一個に分けられ、Stromgardeの守備兵たちに分配された。その欠片を取り戻し、トロールのシャーマン、Tor'ganのもとへ持っていけ。奴なら、それを完全なsigilに結び合わせることができる。", "Throm'ka、{class}。Zenguから、お前が私の助けを必要としていると聞いたが?", "ああ、この印章を再構築してほしいのか? それほど難しくはないはずだ……欠片は全部そろっているようだし、魔法の構造も簡単に作り直せるだろう。\n\n目を閉じておいたほうがいいかもしれないな。", 0x30cf3c3c, 0xb520986e, 0xa3b429d2, 0x41d99c35, 0x4ecef875, "....." },
  [641] = { "Sigil of Thoradin", "修復したSigil of ThoradinをHammerfallのZenguのところへ持って行って下さい。", "修復は完璧にうまくいった。これでsigilを使ってTrollbaneの墓の封印を解くことができる。それをZenguのもとへ返すがいい。きっと、お前にやってもらいたい仕事がまだあるはずだ。", "{name}! 二つ目のsigilは手に入れたか?", "Trollbaneの墓からTrol'kalarを取り出せるところまで、半分は来た。三つ目の印章がどこにあるのかははっきりしない。持ち主たちがArathi中をかなり動き回っているようだからな。だが、あなたならきっと見つけられると信じている。", 0xe3fc1aa4, 0xd9f726b0, 0x3d7be40b, 0x9035140e, 0x689de4e4, "....." },
  [642] = { "囚われの王女", "Motes of Myzraelを$N1個集め、Drywhisker GorgeのIridescent Shardsのところへ持って行って下さい。", "我が名はMyzrael。大地の王女です。私を捕らえた者たち、giantsが、私をArathi Highlandsの地下深くに閉じ込めたのです。この水晶の欠片だけが、地上の世界と言葉を交わす唯一の手段なのです。\n\nどうか私を助けてください。giantsの味方であるDrywhisker Koboldsが、東のDrywhisker Gorgeに、これと同じような欠片を持っています。その結晶群に力を与えるには、koboldsからMotes of Myzraelを集め、それに使わねばなりません。\n\nお願いです、{name}、私に力を貸してください！", "この欠片の塊はShards of Myzraelによく似ている。だが、それらから脈打つような安心感は伝わってこない。", "ああ! この欠片を目覚めさせてくれたのだな。すでに本来の自分に戻りつつあるのを感じる!\n\nだが悲しいかな、自由にはまだ程遠い……", 0x5502a3cc, 0x3fd3c157, 0x5d2443d0, 0x73adcf8c, 0xc45376b0, "....." },
  [643] = { "Sigil of Arathor", "Sigil of Arathorを回収し、HammerfallのZenguのところへ持ち帰って下さい。", "Stromgardeを支配しているとはとても言えず、ましてやArathi Highlands全体などなおさらだというのに、人間の王子は騎兵の残党を率いて田舎を駆け回っている。なぜそんなことをするのか理解できんが、人間の考えなど誰に分かる、ん？\n\n奴の理由が何であれ、もっと重要なのは、奴がsigilの一つを騎兵隊長のLieutenant Valorcallに渡したということだ。奴を見つけ、そのsigilを私のもとへ持ってこい。", "Valorcallを追跡するのは容易ではないぞ、{name}。馬に乗っているから、素早く移動できる。それでも、奴のsigilは手に入れねばならん。", "騎兵隊の指揮官を失ったことは、Stromgardeの守備隊にとって大きな痛手となるだろう。さらに良いことに、あと印章1つでTrol'kalarを我々のものにできるということだ。", 0x1a52c8ae, 0x74022d00, 0xf404ad1a, 0x90181e13, 0xfbea8fbf, "....." },
  [644] = { "Sigil of Trollbane", "Prince Galen Trollbaneを倒し、Sigil of TrollbaneをHammerfallのZenguのところへ持って行って下さい。", "Thoras Trollbaneの墓を開くのに必要な最後のsigilは、彼の息子が自ら持っている。奴はStromgardeの奥深く、民兵が押さえている地区の礼拝堂にいる。Prince Galenは厳重に守られており、奴自身もなかなかのウォリアーだ。この仕事はかなり難しいものになるかもしれん。", "戻ったか、{name}。Ignaeus Trollbaneの血筋は絶たれたか?", "今日はたいした日だ、{class}。Trollbaneの血がもう我が民を苦しめることはなく、Trol'kalarを手に入れるのに必要な印章も我々の手にある。もうすぐ、本当にもうすぐ、Zul'Gurubの憎きトロールどもに一撃を加えるのだ。", 0x30271c66, 0xadccbb48, 0x615d8bb1, 0x2a04b305, 0xcdb3e73b, "....." },
  [645] = { "Trol'kalar", "StromgardeにあるTrollbaneの墓からTrol'kalarを回収して下さい。", "これは何だ？ 四つのsigilを合わせたら、一つのsigilになったぞ。これならTrollbaneの墓にかけられた守りの結界を破れるに違いない。\n\nTrollbaneの亡骸は、Stromgardeの礼拝堂の裏にあるSanctumに葬られている。Trol'kalarを取り戻してこい。", "Trollbaneの墓の表面の石に刻まれた模様は、Sigil of Ignaeusの光る線と一致している……", "Trollbaneの墓の表面の線とSigil of Ignaeusの光る線を重ね合わせると、閃光がSigilを包み込み、伝説の剣Trol'kalarが石の手の握りから解き放たれた。", 0xc3a3e914, 0x1f271fa4, 0x98b28205, 0x1e96dc15, 0xf67bc99e, "....." },
  [646] = { "Trol'kalar", "Trol'kalarをHammerfallのZenguに届けて下さい。", "光がゆっくりと消え、石の鞘に収められていた剣Trol'kalarが解き放たれた。", "{name}! 剣は奪ったか?", "何世代にもわたり、StromとArathorの軍勢はトロールを蹂躙してきた。今、その最強の武器が我々の手にある。Zul'Gurubの蒸し暑い森で少しずつしか進めなかった日々も、これで終わりだ。\n\nお前の助力は大きかった、{name}。Darkspearのトロールはお前に恩がある。\n\nこの剣は必ずGrom'golのNimboyaへ届けさせる。", 0xc3a3e914, 0xd38fc618, 0x627aaacc, 0x8f3eb249, 0xf52615f4, "....." },
  [647] = { "MacKreel's Moonshine", "MacKreel's MoonshineをSouthshoreのBrewmeister Bilgerのところへ持って行って下さい。", "昨夜はあのMoonshineをかなり飲んじまった！ 見張りの最中に酔いつぶれたとLongbraidに知られたら、首が飛ぶところだ。\n\n頭がひどく痛む。攻城兵器の一団がまるごと頭の上を通っていったみたいに、ゴロゴロ響いてやがった。\n\nおっと、もうこんな時間か！ SouthshoreのBrewmeister Bilgerに、Moonshineを送って借りを返すと約束してたんだ。\n\nだが、期限まであと$N1分しかない！ この酒を彼に届けてくれないか？ 急いでくれ！", "調子はどうだい、{race}?", "ああ、肌寒い日にはFoggy MacKreel's Moonshineで温まるのが一番だ! あのちび野郎、また支払いを滞らせるんじゃないかと思っていたところだ。ありがとう、友よ! 本当にありがとう!", 0x888fda51, 0x674a14d5, 0x7b668c40, 0x35f07d1b, 0x31b8acb8, "....." },
  [648] = { "OOX-17/TNを救出せよ!", "OOX-17/TNをSteamwheedle Portまで護衛し、Booty BayのOglethorpe Obnoticusに報告して下さい。", "ロボットから、再びノームの声が雑音混じりに聞こえてくる。\n\n「OOX-$N1/TNを開けた安全な場所へ移動させて、長い離陸手順を始めさせなければならない。ステルス機能は内蔵されているが、再び使えるようにするにはこちらで時間が必要なんだ。ロボットを今の場所から、そうだな、Steamwheedle Portまで護衛してくれ！ あそこなら申し分のない場所だし、準備を整えるのに十分な道のりでもある！」\n\n「無事に港まで護衛したら、Booty Bayの私のところへ話しに来てくれ！ Oglethorpe Obnoticus、以上！」", nil, "おお、あなたがOOX-17/TNの救い主ですね! あなたの援助には感謝の申し上げようもございません! 自動誘導ロボットシリーズには更に改良が必要ですが、あなたが回収してくれたおかげで、再構築にかかる膨大な時間と、再結合コストの多額の金貨を節約することができました!\n\nどうぞ、私の持っている品の中からお好きな物を選んで下さい。この中のひとつがあなたのお役に立てるよう願います。手厚い援助に改めてお礼申し上げます。我がロボットたちと私は、あなたに借りができましたね。", 0xff482001, 0x033542cc, 0x51c31797, nil, 0xa7b0886e, "...m." },
  [649] = { "Rippleの回収", "OrgrimmarのMalton Droffersに話しかけて下さい", "回収の仕事を頼みたいんだ。もしあんたが俺みたいな旨いRippleの愛好家なら、この仕事を請け負いたくなるだろうよ。\n\nRippleだ!\n\nこいつぁ酒だよ、このとんま。\n\n打ち棄てられたHordeの前哨には、使われていた時からHinterlands Honey Rippleの隠し場所がある。もうあんな旨いrippleは手に入れられないよ! Maltonのまぬけな友人のひとりがこの計画を知ってる。だからあそこへ行って、梱包されたripple一箱と俺自身のコレクション用にもうひとつ持ってきてくれ! Maltonに話しかけてくれ。詳しく教えてくれるだろう。", nil, "ああもちろん、パパが欲しがってるrippleについてさ! Orgrimmarの酒場にrippleを売りたいんだけど、初代の梱包に入っていればもっとお金が手に入るんだよ。それが出来る奴を知ってる。そいつはrippleのあるHinterlandsにいるんだ。でも……その……high elfなんだ。\n\nまあ、彼はいいhigh elfだよ。Allianceの一員じゃないから。うーん、酔っぱらいのhigh elfだから、それほどいいhigh elfでもないか。彼は愛してるんだ。酒を本当に愛してるって意味だよ。", 0x00678057, 0x1420a577, 0x7f14e526, nil, 0x23513047, "...m." },
  [650] = { "Rippleの回収", "Gilveradin Sunchaserに話しかけて下さい。彼のキャンプはHinterlandsにあります。", "君に話してきてもらいたいのは、Gilveradin Sunchaserというelfだ。どんなワインでも年代物でもすっかり全部、匂いだけで名前を言い当てられるんだ! 彼なら俺たちが必要としてる梱包ができるから、彼と話をしてほしい。必要なのは梱包用の6本と、2本はパパに、それと彼は一体何本欲しがるかな……本当だよ、彼は何本か欲しがると思う。rippleを梱包してパパのボトル2本を手に入れたら、ここへ戻ってきてくれ!\n\nGilveradinのキャンプはHinterlandsのhigh elfの山荘の近くにあるけど、そこのhigh elfたちは良い奴じゃないよ。信じてくれ。", nil, "ああ、なるほど、君はMaltonを知ってるんだね? 彼は私の古い飲み仲間さ。いいかい、人為的な条約や同盟の境界を超越するものを私は発見したんだよ。……それは酒さ。我々皆がその至福の味わいで渇きを癒やせば、皆、精神的にもっとよいところにいられるだろうに。\n\nああ……君の訪問は酒の欠点を相殺する価値を知るためじゃない、と何かが私に伝えているよ。", 0x00678057, 0xd60f28d9, 0xccc5938e, nil, 0x30b00bd2, "...m." },
  [651] = { "束縛の石", "Stone of West Binding、Stone of East Binding、Stone of Outer BindingからBurning Key、Cresting Key、Thundering Keyを集める。\n\nそれらをStone of Inner Bindingへ持って行って下さい。", "四つのStones of BindingがArathi中に散らばっています。これらの石が、私を大地の下に縛りつけているのです。\n\nそれらを解き放つには、最も強いもの、Stone of Inner Bindingを解かねばなりません。そしてそのためには、残りの三つから鍵を集めなければならないのです。\n\nこれらの石は守護者たちに見張られていますが、あなたが賢いか、運が良ければ、彼らを退ける方法が見つかるでしょう。", "これはStone of Inner Bindingだ。封印石の中で最も強力なもので、他の石を開くにはまずこれを解き放たねばならない。", "<Myzraelが石を通して語りかける。>\n\n成し遂げてくれた! Stones of Bindingを開いてくれたのだ! 我を縛る枷が緩み、自由がいよいよ近づいてくるのを感じる。\n\nそなたは高潔な{class}だ、{name}。我が救い主よ!", 0xbe3d4870, 0xe72ebdc6, 0xce4593c0, 0x89b21ce6, 0x28d7b85a, "....." },
  [652] = { "要石の破壊", "Fozrukを見つけて倒す。Rod of OrderをArathi HighlandsのKeystoneへ持って行って下さい。", "Stones of Bindingを開いたことで私の拘束の多くは緩みましたが、まだ錠が私を鎖で縛っています。それは、この環状列石の中に見えるKeystoneです。そしてその鍵は、私を捕らえている者の一人、stone watcherのFozrukが持っています。\n\nstone watchersがRod of Orderと呼ぶその鍵をFozrukから手に入れ、それを使ってKeystoneを開かねばなりません。\n\n{name}、あなたは私のためにこれほど多くのことをしてくれました。あと少しだけ……そうすれば、私の感謝は大地の礎そのものを揺るがすでしょう！", "Keystoneには途方もない地脈の力が満ちている。", "あなたは要石に杖を差し込んだ。すると、足元に震えが走る……", 0x2da564e4, 0xfa1389bb, 0x95f1140d, 0x71d453a3, 0xc0e20234, "....." },
  [653] = { "Myzraelの味方", "IronforgeのForlorn CavernにいるGerrig Bonegripと話して下さい。", "<Myzraelが語る。>\n\n自由！ 私は自由です！ 捕らえていた者たちから身を隠し、力を蓄える自由を得たのです。今彼らと対峙すれば、きっと再び打ち負かされ、囚われてしまうでしょうから。\n\nですが、いずれ私はgiantsと対決し、彼らは私を閉じ込めたことを後悔するでしょう！\n\nあなたは高潔な味方です、{name}。いずれまたあなたの助けが必要になります。準備が整ったら、私を地上へ召喚してもらわねばなりません。\n\nGerrig Bonegripと話してください。彼はIronforgeの、Forlorn Cavernにある店にいます。私を召喚する方法を知っています。", nil, "奥方からお前が来ると聞いている、{class}。我が住まいへようこそ。お前も私と同じく、より崇高な大義に仕えているのだからな。", 0xbcb78ac5, 0x51e66058, 0x3d3eeded, nil, 0x63f2b7b0, "...m." },
  [654] = { "Tanarisの現地採集", "Acceptable Basilisk Sample・Acceptable hyena Sample・Acceptable scorpion Sampleをそれぞれ8つ入手して下さい。電源を使い切る前にGadgetzanのChief Engineer Bilgewhizzleのところへtesting kitを持ち帰って下さい。", "動力源を起動すると、野外検査キットが光り、振動し始めた。計画どおりに動いているようだ。\n\nChief Engineer Bilgewhizzleによると、Tanarisの砂漠で必要なデータを集められるのは、これから2時間だ。2時間以内に集められなければ、データはすべて失われ、彼から動力源をもう一つ買わなければならなくなる。\n\n任務を終えたら彼のところへ戻ること。", "で、必要なものは全部手に入れたかい? もし足りないまま動力が切れたら、中身は全部駄目になって最初からやり直しだよ。\n\nおっと、同情なんて期待しないでくれよ。こっちはGadgetzan Water Companyの儲けが全てなんだ。Dun Moroghの凍てつく泉から水を輸入できるようになるまで君に動力源を売り続けることになるなら、それで結構!", "分かった。じゃ、電源を取り外すのにかかる時間はちょうど一秒。その後は、中のデータが消える心配をすることなく、何でも好きなことができるよ。", 0xf4d6d3fa, 0x93a0aa08, 0xe61acaeb, 0x307a6f8a, 0xdb6f5328, "....." },
  [655] = { "Hammerfall", "HammerfallのTor'ganと話して下さい。", "今でもはっきり覚えている、昨日のことのように…… 希望のない長い年月、木と鋼でこのひどい場所に縛りつけられていた。そしてついに、ついに！ 大族長が現れたのだ。漆黒の板金鎧をまとったDoomhammerが、戦鎚を高く掲げて。\n\nあれは……あまりにもむごかった…… 卑怯者の一撃が、我らの最も偉大な英雄を打ち倒すとは。奴は背後から馬で突進し、その槍が彼を貫いた…… 俺は膝をついた。何の希望があった？ 何の希望があるというのだ……", nil, "ああ、Gor'mulのことか。そうだ、奴の話からすると、Doomhammerの死から一度も立ち直れていないようだ。\n\nThrallとOrgrimがこの収容所を解放しようと戦ったとき、Gor'mulはここに囚われていた。だが大地が揺れ、同胞たちが脱出する中、奴は取り残された。我々がこのHammerfallに拠点を築くために戻ってくるまで、奴は何年もの間、行くあてもなく希望もなく、ひとりさまよっていたのだ。", 0xfc07ba8d, 0xb1a40d05, 0xd17783a2, nil, 0x8f698219, "...m." },
  [656] = { "王女の召喚", "Shards of Myzraelへ行き、彼女を呼び出して倒す。\n\n彼女のEldritch Shacklesを手に入れ、Shards of Myzraelに縛りつけて下さい。", "Myzraelが力をつける前に倒さねばならん。そうしなければ、十分な力を蓄えた彼女は、自分を捕らえた者たちに挑むだろう！ 彼女を操れると考えている者もいるが、もし操れるのなら、なぜgiantsはそもそも彼女を鎖で縛ったんだ？？\n\nおかしな理屈だろう、え？\n\n彼女を倒すには、最初に彼女と話したShards of Myzraelで彼女を召喚しろ。彼女を倒してEldritch Shacklesを集め、それをShards of Myzraelに結びつけるんだ。\n\nそうすれば、彼女は再び閉じ込められる。", "Shards of Myzraelは今、妙に静まり返っている。", "eldritch shacklesがShardsの周りに取り付けられると、はるか下から人ならぬ叫び声が聞こえてきた。その叫びに続いて咆哮が響く。\n\nShards of Myzraelは、もはやかつてのような温もりや安心感を呼び起こさない。今やそれは露骨な脅威を放って脈動している……まるでその下にいる何かが地上に悪意を抱いているかのように。", 0xfb77844a, 0xcae5bfec, 0xfc268925, 0x806f9429, 0x8f883272, "....." },
  [657] = { "新たな疫病の兆し？", "Kineloryと話して下さい。", "<Quaeがフォルダーに目を通し始める。>\n\nこれは確かに興味深い。Apothecary JorellがここGo'Shekで何か危険な実験をしていたらしい。それがHillsbradとどう関係するのかは分からないが、このまま続けさせたらPhinは良く思わないだろう。\n\nあなたがいない間にオークの連中と一悶着あって、私はKineloryを手伝えるほどの状態じゃない。やる気があるなら、JorellがまだTarren Millへ送っていない研究を盗みに彼女が農場へ下りていくとき、護衛が必要になる。", nil, "Phinが安らげるのなら、Forsakenを一人残らず私自身の手で滅ぼしてやる。疫病以来、彼は私たちのためにたくさんのことをしてくれた。友人や家族にまた出会えるなんて思ってもみなかった。\n\n準備ができたら知らせてくれ。すぐに取りかかろう。", 0xf6153188, 0xa7debdee, 0x8f4b7fcf, nil, 0xe1abaa0b, "...m." },
  [658] = { "新たな疫病の兆し？", "Forsaken Courierを見つけ、彼女のSealed FolderをGo'Shek Farm近くのQuaeのところへ持ち帰って下さい。", "それで、Phinが私たちの様子を見にあなたをよこしたと？ 驚かないよ――彼は心配しすぎるんだ。\n\n私たちは何日も農場を見張っていて、Kinは少し前に、南の小さな家から伝令が出てくるのを見たと言っている。\n\n彼女はよくしゃべるが、危険な場所にいるときの彼女の感覚はいつだって信頼できる。\n\nあなたはもしかして腕のいい追跡者だったりしないか？ その伝令はTarren Millへ書類を運んでいるのかもしれない。その書類を手に入れられれば、Hillsbradで何が起きているのか分かるかもしれないんだ。", "あの伝令の捜索に手を貸してくれて感謝している、{name}。\n\n君が出ている間に、Kinがここから南にある例の家から薬剤師が出てくるのを見た。奴らが良からぬことを企んでいるのは間違いない。ただ、早まった真似をする前に証拠が要るんだ。\n\n何か手がかりはつかめたか?", "素晴らしい!\n\nさて、これが何なのか見てみよう……", 0xf6153188, 0x821edb92, 0x0f6c1ae1, 0x719925d3, 0xcaaeecd7, "....." },
  [659] = { "新たな疫病の兆し？", "Arathi HighlandsのGo'Shek Farm近くでQuaeとKineloryを見つけて下さい。", "ようこそ、よく来てくれた、{name}。私はこのあたりで起きている奇妙な出来事を調べている冒険者の一団を率いている。\n\nHillsbradにいる私のいとこが最近、飼い犬のStanleyを処分したんだ。その犬は不思議なことに巨大化して、近づく者を誰彼かまわず獰猛に襲うようになったからだ。\n\nアンデッドが関わっていると私はにらんでいて、それを証明する手がかりを探している。\n\n私の仲間のうち二人、QuaeとKineloryがArathi HighlandsのGo'Shek Farmへ向かったんだが、何日も連絡がない。彼らを探してくれないか？ 心配になってきたんだ。", nil, "できるだけ静かにしているんだ、旅の者よ。\n\nオークは覗き見されるのを嫌うし、この農場には見た目以上の何かがある。", 0xf6153188, 0x43c42cf9, 0x9c68d408, nil, 0x99c14d17, "...m." },
  [660] = { "新たな疫病の兆し？", "KineloryがQuaeのところへ戻るまで彼女を守る。", "よし、{name}。あなたが良ければ、私はいつでも行ける。\n\n行こうか？", "話している場合ではない。Hillsbradの人々を少しでも思うなら、Kineloryを守ってくれ。", "我々のために大きな働きをしてくれた、{name}。ありがとう。\n\nKinが下で手を焼かせていなければいいが。彼女はとても人懐っこいが、敵に回すと同じくらい恐ろしい。", 0xf6153188, 0xcf1d12c7, 0x7fd87079, 0x830121f4, 0xe1ba4ed2, "....." },
  [661] = { "新たな疫病の兆し？", "SouthshoreのPhin Odelicを見つけて下さい。", "酒場で一晩過ごした後のKineloryは、今よりずっとひどい顔をしてたよ。あなたはしっかり彼女を守ってくれたみたいだな。\n\n彼女が農場から持ち帰ったこの品々があれば、少なくともPhinもこのArathiで何が起きているのか見当がつくはずだ。あなたの襲撃への報復がないことを確かめるために、私たちはもう少しここに残る。Southshoreへ戻ってPhinと話してきてくれないか？", nil, "では、あの2人の問題児は結局無事だったのか? ははっ、それを聞いて安心した。彼らの居場所と様子を知らせてくれて感謝する。まだ生きていると分かって本当に嬉しい。あの2人は友としても旅の仲間としてもかけがえのない存在なんだ。\n\nだが……それより、君の助けにきちんと礼をすることが大事だな。ほら。これを受け取ってくれ、仲間たちからの感謝と一緒に。\n\nうまくいけば、Forsakenが何を企んでいるのか突き止めて、それを終わらせられるだろう。", 0xf6153188, 0x2d55a42c, 0xa4460a5c, nil, 0x8ae446dc, "...m." },
  [662] = { "深海のサルベージ", "First Mate Nilzlixは、Maiden's FollyとSpirit of SilverpineからCharts and Logsを回収してほしいと言っています。", "O'Breenは船団を入り江へ導いた。俺たちは、ここにこそ財宝があると確信していた。Harbingerは無事に停泊したが、Maiden's FollyとSpirit of Silverpineが近づくと、潮が引き始めたんだ。あんな奇妙なものは見たことがない！\n\nその二隻は何かに乗り上げた……岩礁の中にある、何かの神殿のようなものに。あっという間に沈んじまって、本当に悲劇だった。\n\n出発する前に、あの船のLogsとChartsを回収しなきゃならない。あの情報を詮索好きな目のために残していくわけにはいかないからな！", "捜索と回収の任務はどうなっている、{name}? Maiden's FollyとSpirit of SilverpineからLogsとChartsをどうしても取り戻さなきゃならないんだ。\n\nそこにある情報が敵の手に渡りでもしたら、Fleet Master Seahornに板歩きの刑にされちまう。\n\nもっとも、この窮地から抜け出せればの話だがな……", "この情報が安全だと分かれば、Booty Bayの司令部も少しは安心するだろう。よくやった、{name}。", 0x10caae6c, 0x5e4e59f8, 0x3f810c95, 0x72518962, 0xef7dce03, "....." },
  [663] = { "Land Ho!", "Faldir's CoveのCaptain O'Breenと話してください。", "Loloには小さな{race}が見える！Loloはいつも見張ってる！\n\nFaldir's Coveへようこそ。Captain O'Breenは、ここには数時間しかいないって言ってた。宝を集めてBooty Bayへ戻るのにちょうどいいくらいの時間だって。\n\nでもLoloは、それよりずっと長くここにいることになると思う。船団の他の2隻を失っちゃったから。かわいそうなSpirit of SilverpineとMaiden's Folly。今は海の底で眠ってる！\n\nここに残るつもりなら、Captain O'Breenと話すといいってLoloは思う。", nil, "よう、相棒。\n\nひでえ有様だったぜ。Seahornに何があったか知られたら、俺の船を取り上げられちまう。\n\n教授の装置の一つが、失われた財宝はこの入り江の近くにあると示したんだ。俺はHarbingerを入港させて、Spirit of SilverpineとMaiden's Follyにも続くよう合図した。\n\nそのとき海が轟いた。潮が引いて、2隻の船が岩礁に突っ込んじまった。\n\nただの岩礁じゃねえ。何かが下にいる……。\n\n船員たちを助けてくれりゃ、たっぷり礼をするぜ。", 0xdff9113b, 0x8df40bc7, 0x98f2e211, nil, 0xf9ac1b56, "...m." },
  [664] = { "溺れた悲しみ", "Faldir's CoveのCaptain Steelgutは、Daggerspine Raidersを$N1体とDaggerspine Sorceressesを$N2体倒してほしいと言っています。", "ああ、ひどい人生だ。本当なら今ごろ水の墓にいるはずで、こんな焚き火のそばで新鮮な空気を吸ってるはずじゃねえんだ。\n\n乗組員たちは、俺の美しいMaiden's Follyを救おうと必死だった。あいつらに祝福を、あいつらの心に祝福を。\n\nO'Breenは無事に岸にたどり着いたが、俺たちはそう運が良くなかった。誓って言うが、海がそのまま俺たちを沈めちまったんだ。\n\nついさっきまで浮いてたかと思えば、次の瞬間には水が流れ込んでくる。それにあの獣ども！ 生き残った者をみんな殺しやがった。おぞましいnagaのクズどもめ。俺は気を失って、気がついたらここで助けられてたんだ。\n\nあの獣どもを皆殺しにしてやりたい。", "ふん、あのnagaのクズどもはわしが自分で片付けたほうがいいかもしれんな。お前さんにやる気がないのは見りゃ分かる。\n\n暇つぶしに編み針でも探してきてやろうか。", "よくやってくれたな、{name}。\n\nあのクズどもは当然の報いを受けたんだ。何をしたって俺の船も船員も戻っちゃこねえが、あのnagaどもが死んだことで少しは慰めになる。", 0x92f7882d, 0x34a0a847, 0x31e64d80, 0xfdc7260b, 0xe43ee675, "....." },
  [665] = { "沈んだ財宝", "Professor Phizzlethorpeを洞窟まで護衛し、連れて戻って下さい。", "私たちも正式なBlackwater Raidersになったのだから、Mr. O'Breenが失われたエルフの財宝を見つけるのを手伝うのが私たちの仕事だ。\n\n助けなしに暗い海で宝石を見つけるのは、ほぼ不可能だ。博士がそれに役立つゴーグルを作った。そのゴーグルに、丘を少し上った洞窟にある魔法の石から引き出したエネルギーを充填する必要があるんだ。\n\nだが、その洞窟は呪われている！ 近づくと待ち伏せされるんだ。私を守ってくれれば、石のエネルギーをゴーグルに取り込める。", "話している暇はない! ゴーグルに石の力を充填しなければならないんだ!", "ゴーグルは完璧に動くようになった! よくやった、{name}。", 0x809f3322, 0xda9b1388, 0x75214d50, 0x4de940ef, 0x728ff3ac, "....." },
  [666] = { "沈んだ財宝", "Faldir's CoveのDoctor Draxlegaugeは、Elven Gemsを$N1個集め、終わったらGoggles of Gem Huntingを返してほしいと言っています。", "財宝はあまりに長く海底にあったせいで、宝石が石灰化して分厚い石になってしまっている。だが、このゴーグルに取り込んだ力があれば、簡単に見つけられるだろう。\n\nノームのちょっとした創意工夫は大いに役立つものさ！\n\nさあ、Goggles of Gem Huntingを借りていくといい、{name}。Captain O'Breenのために、失われた財宝をいくらか集められるか試してみてくれ。\n\n自分で潜りたいところなんだが……えーと……その、安全で乾いた陸の上で片付けなきゃならない重要な科学の仕事があってね……ええ、そうなんだ。", "gogglesの具合はどうだった? ちゃんと全部動いたかい? 必要なら調整できるよ。\n\nああ、それと使い終わったらgogglesは返してもらうよ。Captain O'Breenがこの先いろいろと使い道を見つけてくれるはずだからね。", "実に見事だ、{name}! 隊長もきっと大喜びするぞ! それにFleetmaster Seahornの耳に入ったらどうなるか、楽しみにしていろ!", 0x809f3322, 0x1ed496c4, 0xc2a1f19b, 0x0df4bc18, 0xe3d4dd09, "....." },
  [667] = { "海底からの死", "敵対者の攻撃からShakes O'Breenを守って下さい。", "こいつはまずいな。Daggerspine Naga共が攻撃のために集まっているようだ。\n\nNagaは戦いにおいての無情さで知られている。私が死ぬまで攻撃を続けるだろう。\n\n私自身の命は船員ほどの価値はないが、しかしあなたは私を守る必要がある。私の海の知識無くしてBooty Bayまで船を戻すことはできないのだ。\n\nNagaは海から来るだろう。あなたは攻撃を防ぐために私とここに残ってくれ。大砲を配置してあいつらを追い払うんだ。\n\n{name}、準備はOKか？", nil, "襲撃を生き延びたぞ!\n\nお前がいなけりゃ無理だった、{name}。\n\n潮が満ちたらすぐに出航する。お前がこれほど見込みのある英雄じゃなけりゃ、俺の船員にならないかと誘うところだ。だが、お前にはもっとでかい仕事が待ってるようだな。\n\nたとえちっぽけな{race}だとしてもな……。", 0x5cfea5ba, 0x43eeb91a, 0xdeb211aa, nil, 0x9fa5eca0, "...m." },
  [668] = { "沈んだ財宝", "Elven GemsをCaptain O'Breenのところへ持って行って下さい。", "Captain O'Breenを待たせないようにしよう。彼はこの宝石を直接見たがるはずだ。なにしろ、そのために私たちはここにいるんだからね！\n\nそれに、この海賊たちと何週間か付き合ってみて、教授と私は、奴らの財宝を握っているところを見つかるのが健康にとって最も良くないことだと悟ったんだ。\n\nほら、{name}、これをO'Breenに持っていってくれ。", "よう、{class}。ブリッジに何の用だい?", "つまり、あのちっちゃなノームどもも結局役に立ったってわけか? あのちびどもを置いておいたのには理由があると思ってたんだ!", 0x809f3322, 0x5b6bda67, 0x751006c6, 0x6284468a, 0xbdba0ac2, "....." },
  [669] = { "沈んだ財宝", "Sample Elven GemをBooty BayのFleet Master Seahornのところへ持って行って下さい。", "Fleet Master Seahornは、俺たちの発見をすぐにでも聞きたがるだろう。\n\nだが見てのとおり、俺たちはここから出られるような状況じゃない。潮が低すぎるだけじゃなく、俺たちがかき乱したあの忌々しい生き物どもが、こっちの動きをしっかり見張ってやがる。\n\n財宝を見つけて、さらに引き揚げる作業をしているとBooty BayのFleet Master Seahornに知らせてくれれば、Blackwater Raidersの大きな役に立てるぞ。証拠としてこの見本を持っていけ。", "Booty Bayへは何の用で来たんだい、{class}?", "ああ、さすがは頼れるShakes O'Breenだ! あいつこそこの任務にふさわしい隊長だと分かってたよ!", 0x809f3322, 0xa9e8eb3d, 0xcd2e4a3f, 0xb1cc072b, 0x1f6287d2, "....." },
  [670] = { "沈んだ財宝", "Seahorn's LetterをArathi HighlandsのShakes O'Breenに届けて下さい。", "なあ、{name}、お前は冒険好きなタイプに見えるな。俺の船団は、補給が済むまでBooty Bayで足止めを食ってるんだ。\n\nここでも外でも重大なことが動いていてな、Arathiの沖で身動きが取れないShakes O'Breenに極秘の書簡を届けなきゃならない。\n\nこの伝言を、無事に、内密に届けてくれると信じていいか？", "で、Seahornは感心してたかい? きっと口元がBooty BayからRatchetまで届くくらいの笑顔だったろうね。", "これほど長く危険な旅をしてくれてありがとう。Blackwater Raidersは君に感謝している。", 0x809f3322, 0xbdb3e78c, 0x556a435d, 0x6b6722e7, 0xc1a23172, "....." },
  [671] = { "邪悪な魔法", "HammerfallのTor'ganのために、Bloodstone Amuletsを$N1個手に入れて下さい。", "空気に奇妙なものを感じていた……血の中でふつふつと煮えたぎるような感覚だ。疑いは抱いていた。不安の源を探しに出かけ、西のNorthfold Manorで悪魔召喚の残滓を見つけたのだ。近づくにつれ、血が沸き立ち、内なる怒りが膨れ上がった。\n\n地面に、悪魔召喚を補助するのに使われるbloodstoneの護符を見つけた。だが、私が見つけたものは力を使い果たしていた。調べるにはもう一つ必要だが、あの屋敷へ戻る勇気はない。いくつか持ってきてくれないか？", "かつて呪われていた血が、今も私の血管を流れているのです、{name}。もし誰かが……何かが悪魔を召喚しているのなら、止めなければなりません。", "Syndicateの真の狙いを見極めるには少し時間がかかるだろうが、彼らが闇の悪魔的な魔法と明らかにつながっていることが気がかりだ。もっと分かったら知らせよう。", 0x1f710805, 0x37c3a4df, 0x37ef5539, 0xeed7c659, 0x23b32367, "....." },
  [672] = { "精霊を呼び起こす", "HammerfallのTor'ganのために、Highland StridersとHighland ThrashersからHighland Raptor Eyesを$N1個手に入れて下さい。", "俺たちは彼を落ち着かせ、元気づけようとした。Kalimdorにある我らの強大な都Orgrimmarの話を聞かせたりしたが、何も彼の心を動かさなかった。\n\nOrgrimの鎧と戦鎚を受け継ぐ、我らの若き大族長Thrallの話も……だが、もしかしたら……もしかしたら！ 我らが新たに見出したシャーマンの魔法を見せれば、彼に新たな希望を与えられるかもしれん。試してみる価値はある！\n\n彼のために小さな品を作れるだろう、そうだ……raptor eyesをいくつか持ってこい。何ができるか考えてみよう。", "Gor'mulにraptorの力を少し授けるお守りを作ろう。そうすれば彼の内に何か炎が目覚めるかもしれん……", "素晴らしい。この目を差し出したraptorの霊が、このアミュレットを身につける者に力を貸してくれるだろう。", 0x77ff23c8, 0x20d5a138, 0x2af40c2d, 0x2439bccf, 0xe3fbd900, "....." },
  [673] = { "邪悪な魔法", "Marez CowlのBloodstone Orbを取り戻し、HammerfallのTor'ganのところへ持って行って下さい。", "強力なウォーロックがStromgardeの城壁の中に潜んでいることは疑いようがない。このウォーロックは、秘術の魔法の遺物を使い、時折恐ろしい悪魔を大量に呼び出している。奴の力の源を取り除かねばならない。\n\nそのウォーロックを見つけて殺せ。奴が身につけている魔法の品を何であれ持ってこい。私がそれを破壊する手を打ち、その力がもはやこの地を汚すのに使われないようにしよう。", "血の中の焼けつく感覚が……日に日に強くなっていく。あのウォーロックを止めねばならない。", "この宝珠を破壊すれば、眠れぬ夜も安らかな眠りに変わるだろう。ありがとう、{name}。これは、Hellscreamが呪いから解き放つまで悪魔どもがオークに及ぼしていた恐ろしい力を、身の毛もよだつほど思い出させる。", 0x1f710805, 0x229e6edc, 0xad8d1072, 0xea8a4f43, 0x1a74ceb9, "....." },
  [674] = { "精霊を呼び起こす", "Raptor Talon AmuletをGor'mulに渡して下さい。", "さあ、この護符をGor'mulのもとへ持っていき、raptorsの力が、かつて彼の血管を燃え巡っていたウォリアーの炎を呼び覚ませるか確かめてくれ。", "臆病者の手が最強中の最強を殺せるというのなら、どこに希望があるというのだ? どこに希望があるのか、答えてくれ!", "これは何だ? 磨いた骨か。磨いた骨など何の役に立つ? 装身具ひとつでHordeがかつての栄光を取り戻せるとでもいうのか?", 0x77ff23c8, 0x41618f65, 0x497c8e43, 0xa362b1a0, 0xd12bfb07, "....." },
  [675] = { "精霊を呼び起こす", "Tor'ganと話して下さい。", "<Gor'mulは護符を地面に投げ捨てる。>\n\nTor'ganに言われて来たんだろう？ ふん！ なぜ奴が俺に情けをかけるのか理解できん。大族長と共に戦場で死ぬことを許されなかったとき、俺は情けを拒まれたのだ。運命は俺に残酷な一撃を与えたものだ……", nil, "うまくいかなかったようだな。それでも、シャーマンの力を見せ続ければ、いずれGor'mulもかつての誇り高い姿を取り戻すと私は感じている。あのアミュレットの力では、我々が新たに得た力を奴に示すには足りなかったのだ。", 0x77ff23c8, 0x445ba750, 0xd1121805, nil, 0xffff7811, "...m." },
  [676] = { "鉄槌が下る時", "Boulderfist Ogresを$N1体とBoulderfist Enforcersを$N2体倒し、Arathi HighlandsのHammerfall前哨地にいるDrum Felを見つけて下さい。", "弱虫どもめ……どいつもこいつも。おい、{class}、何を見ている？ 自分が特別だとでも思ってるのか、あ？ だったら証明してみろ。\n\nArathiのHammerfallの前哨地が攻撃を受けている。すぐに援軍を送らなければ、奴らの破滅は目前だ。\n\nだが、慌てて駆けつける前に、まず腕を試しておきたいだろう。ArathiのStromgardeの北東に、Boulderfist族が住むogreの塚がある。そこのogresとenforcersを片付けられるようになったら、HammerfallのDrum Felに報告しろ。", "斧を研ぐ暇すらないのだ。ましてや前哨地を離れて、同胞を殺そうとする獣どもを狩りに行くことなどできん。\n\nお前は一人前の{class}どころか、兵卒ほどの経験もなさそうだが、何の用だ、{name}?", "ほう、Hammerfallを助けられるほど強いと思っているのか? いいだろう。\n\nTallowがお前をあのogreの塚に送ったのは、お前が死ぬのを期待したからか、我々を助けるだけの力があると考えたからか、そのどちらかだ。いずれにせよ、お前は今ここにいる。そして絶え間ない襲撃との戦いに、私はもっと兵が必要なのだ。\n\nHammerfallに留まるつもりなら少し休め。準備ができたらまた話しに来い。戦いには事欠かんぞ。", 0x6813ee44, 0x6d586db7, 0x5fa4e819, 0xb1c96930, 0xb856dd5f, "....." },
  [677] = { "出動命令", "下記のWitherbark Troll達を殺しHammerfallにいるDrum Felに戦果を報告して下さい。　Witherbark Axe Thrower 10体   Headhunter 10体   Witch Doctor 8体", "ここArathiにいるWitherbark trollとBoulderfist ogreは、我々をこの地から排除するために協力して動いている。しかし我々は運命を彼らや他の者に委ねはしない。奴等を殺して我々もこの地に存在するということを教えてやるのだ。\n\nWitherbark troll達は我々を拒絶した。またogre達は我々がそれを許すとすれば、我々を食料や寝床にするつもりだ。だがそうはいかない。\n\n我々はここから南のWitherbark trollキャンプへ攻撃を開始する。次々と奴等を殺し、キャンプを大量の血で染め上げたら戻るがいい。", "まだ私の任務を果たしていないのなら、お前は戦の新米であるばかりか、心まで臆病者なのだろう。", "お前の服には戦いの跡があり、額からは汗が滴っている。いいぞ、実にいい。", 0xb26eb2f8, 0x5d4a6fa6, 0x6a4e04e7, 0xb79372fd, 0x4d187de8, "....." },
  [678] = { "出動命令", "下記のBoulderfist達を殺しHammerfallにいるDrum Felに戦果を報告して下さい。　Boulderfist Brute 10体   Boulderfist Magi 4体", "お前の力は証明された。{name}。では、今からお前が立ち向かうべき本当の敵について教えよう。\n\nここからドワーフの橋に向かって南西に行ったところにBoulderfistがねぐらを持っている。そして私の記憶が正しければ、maulersとmagiがお前を待ち構えているだろう。今まではそうだった。\n\n可能な限り奴等を殺すことに成功したらその体で、もし失敗した場合は魂となって戻ってくるがいい。私はどちらにせよお前の戦いに対する固執を賞賛するだろう。", "ためらっているな。なぜだ? これまでお前は大きな力を示してきた、{name}。今になって私を失望させるな。", "お前はkodoのように強く、その戦いへの渇望はお前の同胞の誇りだ。", 0xb26eb2f8, 0x9898bdec, 0xc6ce5cae, 0x3bce68c3, 0x4558219c, "....." },
  [679] = { "出動命令", "下記のBoulderfist達を殺しHammerfallにいるDrum Felに戦果を報告して下さい。　Boulderfist Shaman 15体  Boulderfist Lord 10体", "野獣の首を取る時が来たようだな...大いなる力によって、{name}。お前は今までの働きにより、この最後の力強い一撃を行うための助けとなることを示した。我々を攻撃していた者のリーダは、人間の儚さを示す象徴Stromgarde跡にねぐらを築いている。\n\n我々をこの地から排除しようと試みたBoulderfist Lordとその従者であるShamanを探し出して殺すのだ。", "ついに勇気が衰えてきたようだな。どうやら私の勘は正しかったらしい。お前の力など、その威勢に比べれば取るに足らん。\n\nあの獣の首を切り落としてから戻ってこい。さもなくば二度と戻ってくるな。", "お前は同胞の誇りだ、{name}。脅威は大きく減った。これで我々もこのHighlandsで栄えていけるだろう。", 0xb26eb2f8, 0x37f4888f, 0xd6bc1e8c, 0xe6384936, 0x112388f8, "....." },
  [680] = { "真の脅威", "Or'Kalarを倒し、彼のHeadをHammerfall前哨地のKorin Felのところへ持って行って下さい。", "あなたは夫によく仕えてくれていますね、{class}。でも、夫はなぜHammerfallが攻撃されているのか知らないのです。\n\nStromgardeにいるMug'tholの手先、Or'Kalarは、夫に激しい憎しみを抱いています。何年も前に夫に打ち負かされたことで、夫の死以外は何も望んでいないのです。\n\n私の占いによれば、Or'Kalarは夫に罠を仕掛けています。だから私は、あのogreがいる気配を夫から隠してきました。\n\nogreの居場所を知れば、夫は愚かにも飛び出していくでしょう。あなたにその怪物を倒す手助けをお願いしたいのです。", "Tower of Arathorの近く――そこでOr'Kalarが見つかるはずよ。奴が死ねばHammerfallへの襲撃は止み、私の夫の命も守られるわ。\n\nあなたの目を見れば分かるわ。黙っている私を弱い――いえ、不名誉だとさえ思っているのでしょう。いつかあなたにも、私のように愛するということが分かる日が来るわ。その時にはきっと、別の形の強さと名誉が理解できるはずよ。\n\nそれまでは、私の頼みどおりにOr'Kalarを討ってちょうだい。", "あなたは私のために大きな働きをしてくれたわ、{name}。あなたの行いのおかげで、夫の命とHammerfallの安全が今日もまた守られたの。どうか勇気へのお礼としてこれを受け取って。", 0x1ada6861, 0x5495cb6a, 0xb4b60fdc, 0xd6229aee, 0x93ea8e02, "....." },
  [681] = { "Northfold Manor", "Syndicate Highwaymenを$N1体とSyndicate Mercenariesを$N2体倒す。\n\nRefuge PointeのCaptain Nialsのところへ戻って下さい。", "我々はStromgardeのために戦争をしているが、負けつつある。ogres、Syndicate、そして我々が、かつて偉大だったこの都市を分け合い、それぞれの勢力が互いに戦って血みどろの膠着状態に陥っているのだ。\n\nだが、我々の兵力は減る一方で、敵は増え続けている。\n\nSouthshoreの町から助けが必要だが、Syndicateが我々の間の土地を押さえている限り、物資を受け取るのは難しい。\n\nNorthfold ManorにあるSyndicateの拠点へ行き、奴らを倒してくれ。そうすれば、我々の補給隊への圧力も弱まり、より多くの物資が届くようになるかもしれない。", "{name}、一時間ごとにStromgardeを守る我々の足場は危うくなっていく。急がなければ、この街はきっと陥落してしまう。", "よくやった、{name}。あのSyndicateの連中が死んだことで、Southshoreからの物資も受け取りやすくなるだろう。\n\n我々の大義にも、まだ望みはあるのかもしれない。", 0x53130e0f, 0xceb6c288, 0x58cdf315, 0xdafa222a, 0x96dc9a3c, "....." },
  [682] = { "Stromgarde Badges", "Stromgarde BadgesをRefuge PointeのCaptain Nialsのところへ持って行って下さい。", "StromgardeのSyndicateは、そこにいる我々の民兵部隊と戦っている。ならず者どもを、より規律ある我々の部隊と戦わせるために、Syndicateの指導者たちは我々の兵士に懸賞金をかけ、殺した民兵から奪ったStromgarde Badgeごとに金を与えているのだ。\n\nそのbadgesを取り戻してほしい。勇敢に散った我々の仲間から、あの悪党どもに戦利品を奪わせるわけにはいかない！\n\nStromgardeのSyndicateが支配する区域に入り、奴らを狩ってbadgesを取り戻せ。", "Stromgarde Badgesは取り戻せたか、{name}? Syndicateの奴らに、我々の死者から利益を得ることなどできないと思い知らせねばならない。", "ありがとう、{name}。この戦死した兵たちの家族には、彼らが戦いの中で命を落としたと伝えよう。\n\nつらい知らせになるだろうが、愛する者が行方知れずのままでいるよりはましだ。", 0x88e40967, 0x16aa063c, 0x2cbc11ff, 0xe694fcd2, 0x1ad1c209, "....." },
  [683] = { "Sara Balloo's Plea", "Sara BallooのメモをIronforgeのKing Magni Bronzebeardのところへ持って行って下さい。", "{name}、ささやかな頼みがあるのだ。\n\n私が用意したこの書状を、我らが偉大なるIronforgeの君主、King Magni Bronzebeardのもとへ届けてくれ。そなたのような者に頼むにはささいな仕事だ。これまでAllianceの大義に大きな勇気を示してきた者なのだからな。\n\n悲しみに打ちひしがれた今の私が王の御前に出ても、私の目的には役立たぬ。きっと分かってくれよう。", "では、あなたが{class}の{name}ですか? Allianceへのあなたの貢献は、ずいぶん遠くまで知れ渡っているのですよ。\n\n今日はどのような用件で私の前に?", "この手紙に目を通すのは、ほんの一瞬で済む……", 0x35db5c7b, 0x521be7bf, 0x77136a52, 0xffa93ce4, 0xbff31da8, "....." },
  [684] = { "指名手配！Marez Cowl", "Marezの首をRefuge PointeのCaptain Nialsのところへ持って行って下さい。", "Syndicateの高位の顧問にして工作員、Marez Cowlの首に懸賞金がかけられた。彼女が最後に目撃されたのは、StromgardeのSyndicate支配地域である。\n\n懸賞金はCaptain Nialsから受け取ることができる。\n\n警告：Marezは腕が立ち狡猾なウォーロックで、悪魔と通じていることで知られている。彼女を狩る際には細心の注意を払うこと。", "ご挨拶申し上げる、{class}。報告があるのか?", "Marez Cowlを倒したのか? よくやった、{name}。本当によくやった!\n\nMarezは我々Stromgardeの守備隊を脅かしていた。噂では、彼女はSyndicateと、ほかの何かもっと邪悪な力との間を取り持つ使者だったらしい。彼女がもう我々にその力を振るうことがないと分かって嬉しい。", 0x673a1ab6, 0xd4e2cda1, 0xa1754dc9, 0x7b907d29, 0xd963f4a4, "....." },
  [685] = { "指名手配！OttoとFalconcrest", "Otto's HeadとFalconcrest's HeadをRefuge PointeのCaptain Nialsのところへ持って行って下さい。", "Stromgarde Militiaは、Lord Falconcrestとその護衛Ottoの首に懸賞金をかけた。FalconcrestはArathi HighlandsにおけるSyndicateの活動を率いており、彼が死ねばその活動に大きな混乱が生じるだろう。\n\n護衛のOttoは戦略上の標的ではないが、獰猛な敵であり、我々の守備兵を何十人も殺している。\n\n彼らの懸賞金はCaptain Nialsから受け取ることができる。", "こんにちは。提出する報告がありますか?", "FalconcrestとOttoだと? 素晴らしい!\n\nこれが報酬だ、{name}。喜んで支払おう。", 0xe992eef2, 0x7d5bc22a, 0x6ce0a9fe, 0x1ca7f78d, 0x1f82f5e1, "....." },
  [686] = { "王への貢ぎ物", "King Magni Bronzebeardは、Grand Mason Marblestenと話してほしいと言っています。", "Mrs. Ballooのような善良なドワーフに、我らの民のより大きな善のために、なぜ戦争の惨禍を耐え忍ばねばならぬのかを理解してもらえるとは思っておらぬ。彼女の夫の死、そしてAllianceの名のもとに戦うすべてのドワーフの死は、我が魂に重くのしかかっておる。\n\n彼女の夫をTwisting Netherから連れ戻すことはできぬが、彼に敬意を表することはできる。\n\nGrand Mason Mablestenに、Sully Ballooの記念碑を建てるよう命じるつもりだ。\n\n今すぐ彼に知らせを送ってくれ、{class}。そなたが我が命を託される者となるのだ。", nil, "つまり、King Magni Bronzebeard自らがお前さんをよこしたってのか?\n\nこりゃあ驚いた! よほど大事な用に違いない!", 0x82e28c92, 0x6fdcb316, 0xbf80acf9, nil, 0x8fe6a7ae, "...m." },
  [687] = { "Theldurin the Lost", "Theldurin the Lostを見つけて下さい。", "Theldurin the Lostは、かつて我らの教団、Twilight's Hammerの一員だった。だが奴は正気を失い、我らの教えを蔑んだ。そして我らのもとから逃げる前に、Myzraelの巻物を盗んでいったのだ！ 捕まえることはできなかったが、噂では奴はBadlandsに隠れ、狂ってわけの分からぬことを口走っているという。\n\nあの御方を我らのもとへ呼び戻すには、巻物を見つけねばならない。そのためには、Theldurinを見つけねばならないのだ。", nil, "やあ。やあ、やあやあやあやあ、ヤアッ!\n\nごめんなさい……いや、待って、悪いなんて思ってない! 失礼なこと言うな!\n\nああ、いや……今のはおかしな話だった。\n\nでも……時々、おかしくなることだけが私の慰めなんだ。", 0xfb09538d, 0x9593d0d7, 0x7da8e2f2, nil, 0xea2b4779, "...m." },
  [688] = { "Myzraelの味方", "HammerfallのZarukと話して下さい。", "<Myzraelが語る。>\n\n自由！ 私は自由です！ 捕らえていた者たちから身を隠し、力を蓄える自由を得たのです。今彼らと対峙すれば、きっと再び打ち負かされ、囚われてしまうでしょうから。\n\nですが、いずれ私はgiantsと対決し、彼らは私を閉じ込めたことを後悔するでしょう！\n\nあなたは高潔な味方です、{name}。いずれまたあなたの助けが必要になります。準備が整ったら、私を地上へ召喚してもらわねばなりません。\n\nHammerfallのZarukと話してください。彼は私を召喚する方法を知っています。", nil, "ようこそ、{class}。奥方からお前が来ると知らされている。奥方を地上へ連れ戻すのなら、話し合うべきことが山ほどある……", 0xbcb78ac5, 0x5af8d2e9, 0xd19484bd, nil, 0xe877cafc, "...m." },
  [689] = { "王への貢ぎ物", "IronforgeのGrand Mason Marblestenは、Alterac Graniteを$N1個欲しがっています。", "では、我らが善き王は、Sully Ballooという兵士を称える記念碑を建てたいとおっしゃるのだな？ そしてその気の毒な男は、Thandol Spanの悲劇で亡くなったと？\n\nやれやれ、Azerothに平和が訪れる日は来るのだろうか？\n\nいずれにせよ、王からの依頼は何よりも重要だ。真に壮大で永く残る作品を作るために、手に入る最上の石の一つを使いたい。HillsbradのDarrow Hillへ行って、Alterac Graniteを集めてきてくれ。", "{name}、{name}、{name}! Sully Ballooに捧げる私の傑作に取りかかれるだけのAlterac Graniteを持ってきたと言ってくれ。", "完璧だ! 想像以上だよ!\n\nしかも、私はかなり想像力が豊かなんだからね……", 0x82e28c92, 0x0d5dee87, 0x470c2087, 0xd98913db, 0x7aa1d388, "....." },
  [690] = { "Malinの依頼", "Arathi HighlandsのRefuge PointeにいるSkuertoを見つけて下さい。", "ごきげんよう、{name}。あなたには冒険者の風格がありますね。ちょうど手をかけてほしい仕事があるのです。\n\n私の元の師匠であるArchmage Trelaneは、少し前にArathi HighlandsのStromgardeから逃れてきました。そして、置いてきた品々を取り戻す手伝いを私に頼んできたのです。\n\n都市は包囲され、彼はTower of Arathorを守ろうとしましたが、無駄に終わりました。すでにHighlandsには手の者を送っていますが、さらなる援助を送ってほしいと言ってきています。興味はありますか？", nil, "で、Malinがお前さんをよこしたって? Muradinが墓からよみがえってdragonに乗せてお前さんをここへ連れてきたって、わしの知ったことか。わしは忙しいんだ! 何か用ならKrytenに話せ。", 0x278d4eda, 0xc5c70302, 0x6378bf3d, nil, 0x49a0c989, "...m." },
  [691] = { "黄金に値する", "Refuge PointeのApprentice Krytenのために、Witherbark Tusksを$N1個、Witherbark Medicine Pouchesを$N2個、Shadow Hunter Knifeを見つけて下さい。", "Archmage Malinは、触媒を集めさせるためにSkuertoと私をここへ送ったんだ。どうやって品物を集めたものか途方に暮れていたが、君が来てくれたからには、問題は解決したと思う。\n\n必要なのは次のものだ：Witherbark tusks、Witherbark medicine pouches、それにshadow hunter knife。\n\n探してきてくれないか？ WitherbarkはArathiの南東に住んでいる。", "ここまでで何か成果はあったかね、{name}?\n\n<Krytenは読みながら日誌に何か書き留めている。>\n\n私の調査が正しければ、tusksはWitherbarkのトロールならどれからでも手に入るはずだ。medicine pouchesはWitherbarkのウィッチドクターが持っている。そしてWitherbarkのシャドウハンターの中でも最も強い者は、通過儀礼を終えた後に授けられる特別なknifeを携えているはずだ。どのシャドウハンターがknifeを持っているかは、戦ってみるまで分からない。", "信じられない! Malinが君をここへ呼んだ理由がよく分かったよ。本当によくやってくれた!\n\nこの調子なら、Skuertoと私はすぐにでもStormwindへ帰れるだろう。\n\nドワーフの相棒がBoulderfist Hallの偵察から戻ってきているはずだ。準備ができたら彼と話してくれ。\n\nどうやらogreとちょっとした小競り合いがあったようだ。でも、そのことは彼には言わないでくれ。偵察の腕をけなされるのにはとても敏感なんだ。", 0xb7129362, 0xc7b775b0, 0xc315ef5a, 0xbe0f5c93, 0xf99993d6, "....." },
  [692] = { "失われた断片", "Torn Scroll Fragment、Crumpled Scroll Fragment、Singed Scroll FragmentをTheldurin the Lostのところへ持って行って下さい。", "Scroll of Myzrael……Scroll of Myzraelだと？！ そんなもの、欲しがるもんじゃない！ その魔法はMyzraelを地上へ引きずり出せるんだ。もしそんなことをしたら、大変なことになるぞ！\n\nいや……もう手遅れかもしれん。もう彼女は自由になっているのかもしれん。我らに襲いかかる前に、力を蓄えているだけなのかもしれん。もしそうなら、巻物がどうしても必要になる！\n\n……残念ながら、壊されてしまった。怒り狂ったelementalsが盗んで引き裂き、今はその欠片を奪い合っている。\n\nだが、その欠片を集められれば、直せるかもしれん……", "fragmentsは見つかったの?!?! 手遅れになる前にもう一度彼女を封じ込めたいなら、Scroll of Myzraelが必要なのよ!", "ああ、見つけてくれたのか! よくやった、{name}! これがMyzraelの邪悪に対抗する唯一の望みかもしれない!\n\nちょっとラチェットを探して、この断片をくっつけ直せるか試してみよう……", 0x3310d134, 0x10c49c45, 0x7c3f4791, 0x49c1ce06, 0xecf713a7, "....." },
  [693] = { "ワンドで大儲け", "Trelane's Wand of Invocationを見つけ、Refuge PointeのSkuertoのところへ持ち帰って下さい。", "よう、{name}。さっきはぶっきらぼうで悪かったな……いや、洒落じゃねえぞ。\n\nTrelaneの一つ目の品の行き先が分かった。Boulderfist HallでKor'greshが持ってる。それに、奴が仲間を従わせるために氷の爆風を浴びせてたところを見ると、そいつの力を全部使いこなす寸前に違いねえ。\n\nBoulderfist Hallはここから南へ行って、それからThandol Spanの東だ。そのogreを見つけて、あの杖を取り返してきてくれ。\n\nお前さんがいない間に、Stromgardeをどうするか考えておく。", "我々の目的はwandだ、{name}。今はそれに集中しろ。", "見事だ、{name}。わしのリストによれば、品物が1つ片付いて、あと3つだ。残りの3つはどれもStromgardeにある。\n\n一休みして体力を取り戻してくれ。わしの計画の次の段階には、もう少し時間と手間がかかる。温かい飯を食って休んだら、また来てくれ。", 0x0a12cb38, 0x3227973b, 0xa26787a1, 0xf39b2744, 0x18e33590, "....." },
  [694] = { "Trelaneの守り", "Azure Agateを見つけ、Refuge PointeのApprentice Krytenのところへ持って行って下さい。", "休めたか？\n\n次の手はこうだ。StromgardeのTower of Arathorの周りにはogresがうようよしてる。奴らに太刀打ちして、生きて品物までたどり着くには、塔の防衛装置を起動する必要がある。そのためには、Boulderfistのシャーマンどもが気に入ってる宝石が要るんだ。奴らは塔から持ち出したんだが、そう長くは手元に置いておかねえだろう。\n\nその宝石を一つ手に入れて、Krytenのところへ持っていけ。あいつなら、鍵として使えるように魔法をかける呪文を知ってる。", "{name}、また会ったね。azure agateはもう見つかったかい?", "驚かされるよ、{name}。またしても見事だ。\n\n宝石に魔力を込める呪文を唱えるから、ちょっと待ってくれ。そうすれば準備完了だ。", 0x7542b825, 0x6ba36e39, 0x5a484df7, 0x7ebd4587, 0xfce7c639, "....." },
  [695] = { "見習いの魔術", "Skuertoと話して下さい。", "さあどうぞ、{name}。この宝石は、塔の土台近くにある台座のどれかに押し当てるだけで、防衛装置を起動できます。塔に入ってTrelaneの残りの品を探す準備ができたら使ってください。\n\n幸運を祈ります。私はここの野営地であなたの帰りを待っています。ああ、それから、出発する前にSkuertoと話してください。必要な残りの詳細を教えてくれるでしょう。", nil, "よし、よし。\n\nほかに遅れがないなら、始めるとしようか?", 0x0c0655e3, 0xa2086ef5, 0xefe451ef, nil, 0xa9bd6c07, "...m." },
  [696] = { "塔への攻撃", "Trelane's Phylactery、Trelane's Orb、Trelane's Ember Agateを見つけ、Refuge PointeのSkuertoのところへ持ち帰って下さい。", "お前さんが探してるのはこれだ：Trelane's phylactery、Trelane's orb、それにTrelane's ember agate。\n\n三つとも塔の中の宝箱に入ってるはずだし、宝箱は自力で問題なく開けられるだろう。ただ、ogresには気をつけな。\n\n塔の防衛装置だけじゃ奴らを片付けられねえ。武器を構えておく必要がある。お前さんが入り込んで盗んでると気づいたら、奴らは必ず痛い目にあわせてくるぞ。\n\n気をつけてな、幸運を祈る。", "これをやってくれりゃ、Malinもきっと大喜びするだろうよ。", "Malinがわしらを助けにここへよこせる者として、お前さん以上にふさわしい者はいなかったろうよ、{name}。見事な仕事ぶりだ!\n\nわしらの任務がこれほどの大成功を収めたと知ったら、あいつも喜ぶだろう。", 0x42233dcb, 0xb94e92fb, 0x7ccebce8, 0x5a83d3e5, 0xe71c6590, "....." },
  [697] = { "Malinの依頼", "Sealed LetterをStormwindのMage QuarterにいるArchmage Malinのところへ持って行って下さい。", "この手紙をStormwindへ持ち帰って、Krytenと俺がもうすぐ帰るとMalinに伝えてくれ。ここで俺たちを助けてくれたんだ、彼はたっぷり礼をしてくれるさ、{name}。それは間違いねえ。\n\n道中気をつけてな。", "はい? どこかでお見かけしたような気がしますね。申し訳ないのですが、以前お会いしましたか? 忙しくてすぐ分からなくなってしまうのです。", "<Archmage Malinは手紙を開き、目を大きく見開いた。>\n\n光にかけて、やり遂げてくれたのですね。なんと素晴らしい。Trelaneもさぞ喜ぶでしょう。KrytenとSkuertoも、Stormwindへの帰路につけることを私と同じくらい喜んでいることでしょう。\n\nありがとう、{name}。どうかこれを受け取って、旅に役立ててください。", 0x278d4eda, 0x516cf4bc, 0xdbdc2c8e, 0x5d1e5a1f, 0x72866d6a, "....." },
  [698] = { "余剰の不足", "Unprepared Sawtooth Flanksを$N1個、Swamp of SorrowsのTok'Karのところへ持って行って下さい。", "東の浜辺近くにある俺たちの前哨地に物資を揃えようとしているところだ――Tok'karもできることはしているが、見張りの交代と兵士たちの食事作りの合間じゃ、一日にほとんど時間が残らないんだ。\n\nあいつらは機会があればsawtoothの肉を料理して楽しんでいるんだが、次の荷を送る暇がなくてな。手を貸してくれないか？\n\n若いsawtoothsは年を取ったものほど旨くないから、そいつらには近づくな。一、二年もすれば十分な大きさに育つからな。", "Lok'tar、{class}。沼地を旅するのは軽い気持ちで冒せる危険じゃない。ここで腕試しをするとは、勇敢だな。", "ああ! 素晴らしい。今夜の焚き火で焼く新鮮な肉だ。ありがとう、{name}。\n\nおかげでこれからの夜が少しは過ごしやすくなる。火は明るく燃え、腹も満たされるだろう。\n\nお前が荷を届けてくれるとは嬉しい驚きだ。Darは誰が見ても見栄えのいいオークとは言えないが、少なくとも奴の態度は奴の臭いほどひどくはない。", 0x3fe51a98, 0xea35dd29, 0xc59badde, 0xaa372f0c, 0x20cd182f, "....." },
  [699] = { "余剰の不足", "Sawtooth Snapper Clawsを$N1個、Swamp of SorrowsのTok'Karのところへ持って行って下さい。", "海岸沿いにmurlocsの脅威があるから、俺たちはここに駐屯して、Stonardに迫る脅威から守っている――数が多すぎるときは警告するんだがな。おかげで休む暇もほとんどない。手を貸してもらえるならありがたい。\n\nsawtooth snappersの爪は、ちゃんと加工すれば立派な武器になる。その爪を持ってきてくれれば、新鮮な肉と楽しいひとときへの礼として、俺たちの武器を一つ褒美にやろう。", "うまい蜂蜜酒に暖かい火、オークの軍勢に武器の山……この海岸沿いじゃ、本当に必要なのはそれだけだ。Stonardを守るこの持ち場に不満はないが、いつの日か穴倉か、せめて塔でも手に入ったらありがたいんだがな。", "無事で何よりだ、{name}。\n\nこの爪なら十分に役に立つだろう。襲撃に備えて手元にある武器は多ければ多いほどいい。\n\nできるだけ早くお前の武器に取りかかろう。さほど時間はかからん。武器作りにはすっかり慣れて、手際もよくなったからな。", 0x3fe51a98, 0x6e6ba4db, 0x5a73776d, 0x72bfd626, 0xdd68198c, "....." },
  [700] = { "王への貢ぎ物", "King Magni Bronzebeardに報告して下さい。", "ああ、Lordaeronからはなんと見事な石が採れることか。あの地がこれほど荒れ果てているのが惜しまれる。\n\nだが、Memorialは実に見事な出来栄えになった！ 王もきっと大いにお喜びになるだろう。\n\nでは、よろしければ、ご依頼どおりMemorialが完成したと陛下にお伝えしてもらえるかな。", nil, "偉大なドワーフの命に比べれば、この花崗岩などささやかな証にすぎん。だが、永遠にこの世に留まれるドワーフなどおらん。\n\nせめてこの記念碑が、未来の偉大なAzerothを歩む者たちへの戒めとして立ち続けることを願おう。Sully Ballooのような勇敢な兵士たちが雄々しく命を捧げたのは、その者たちのためなのだということを、忘れぬように。", 0x82e28c92, 0x8877fcf9, 0xe79d2ded, nil, 0x6ba4dfa2, "...m." },
  [701] = { "Raptorの狡猾さ", "Tor'ganのために、Highland FleshstalkersからRaptor Heartsを$N1個手に入れて下さい。", "いくつか品を足せば、Gor'mulにraptorの狡猾さを吹き込む品を作れるだろう！ raptorの力が体に流れれば、Gor'mulは我らの新たな力を知り、眠っているウォリアーを再び見出すはずだ！\n\nその品と呪文を作るには、raptor heartsが必要だ。", "準備は整った。あとはraptor heartsさえあればいい。", "ああ、これなら完璧だ。これらの力とraptorの霊をこの宝珠に移そう。この宝珠がGor'mulに、raptorの燃えるような強さと知恵を授けるだろう。", 0x185d70c3, 0x827b9016, 0x886cca1d, 0xdac62edd, 0xa7f96e06, "....." },
  [702] = { "Raptorの狡猾さ", "Tor'gan's OrbをGor'mulに渡して下さい。", "このオーブを持っていき、その力を使ってGor'mulにraptorの本質を与えてくれ。きっと彼の魂を奮い立たせ、生きる新たな目的を与えるだろう。彼が元に戻れば、Hordeの現状を説明できるし、終わりなき戦いで偉大なウォリアーの助力を得られる。", "また戻ってきたのか? いやはや、Tor'ganの憐れみをもっと授かること以上に、今の我が望むものなどあろうはずもない。\n\n今度は何を持ってきた? 派手な色の紐切れか? それとも、この惨めさを終わらせるための縄か……", "少なくとも今回は、面白いものを持ってきたようだな。奇妙な力を放っている……", 0x185d70c3, 0x110122a7, 0xc20a0037, 0x7056536d, 0xa5f97668, "....." },
  [703] = { "Barbecued Buzzard Wings", "Buzzard Wingsを$N1個、Rigglefuzzのところへ持って行って下さい。", "ああ、そうとも、俺のbarbecued buzzard wingsは大人気なんだ！ ソースは濃厚で、肉はピリッとしてる。それに匂いを嗅いだら、腹を空かせた連中が何マイルも先から駆けつけてくるぜ！\n\nひと鍋分を料理する材料は全部揃ってる。全部……buzzard wings以外はな！\n\n欲しいなら、buzzard wingsを持ってきてくれ。十分に持ってきてくれたら、レシピを分けてやってもいいぜ！", "こんにちは、{name}。wingsを持ってきてくれた?", "ああ、すぐにその手羽の調理に取りかかるよ。もう味がしてきそうだ!\n\nそれと、自分で作りたいときのためにレシピもあげるよ!", 0x5a29910e, 0x7afb6c8e, 0xf6f3c47b, 0xdcdbbe85, 0x77a2f489, "....." },
  [704] = { "Agmondの宿命", "Carved Stone Urn 4つをLoch ModanのProspector Ironbandに渡して下さい。", "Agmondから受け取った最後の報告が気がかりだ。奴が死んだ今となってはなおさらな！Uldamanの外の発掘現場で、作業員たちが「古代の壺」を掘り出したと書いてあった。わしがここで見つけた偶像と同じように、奴が見つけた壺がtroggsを刺激したんじゃないかと心配なんだ。\n\n研究のためにその壺を手に入れてきてくれ。Uldamanの発掘現場へ行って壺を集め、わしのところへ戻ってこい。", "urnsは見つかったか、{name}? あれとtroggの間のつながりを突き止めねばならん!", "よくやった！運と粘り強さがあれば、troggとこれらの古代の遺物との間にどんな関わりがあるのか突き止められるだろう。\n\n探鉱者たちのために偉大な働きをしてくれた、{name}。その努力は忘れられない。Agmondのこともな。", 0x489c165c, 0xf3b9cc5e, 0x3e07aaf7, 0x50776b5d, 0xd3e7f943, "....." },
  [705] = { "真珠採り", "Blue Pearlsを$N1個、BadlandsのRigglefuzzのところへ持って行って下さい。", "Badlandsは過酷な場所だ。凶暴な捕食者と大胆な腐肉あさりでいっぱいさ。怖いよ、特に背の低いちっぽけなゴブリンにはね。生き延びるには、ずる賢くならなきゃ！\n\n俺は閃光弾のレシピを知ってる。野生動物を追い払うのに使うんだ。でも、材料の一つ、砕いたblue pearlの粉が切れかけてる。持ってきてくれたら、苦労に見合う礼はするよ。\n\nへへ、いいブーツを履いてるといいね。俺が必要なBlue PearlsはVile Reefの貝から採れるんだ。\n\nそう、StranglethornのVile Reefさ！", "pearlsは手に入った? 閃光弾がもうほとんど残ってないんだ!", "これはすごく使えるぞ! あとは粉々に砕いて……こいつとあいつを少し混ぜるだけだ。\n\n覚悟しろ、腐肉あさりども! 閃光を食らわせてやる!", 0x3b1e77f7, 0xdaac42f7, 0xcada0467, 0x386736b2, 0xa129db56, "....." },
  [706] = { "燃え盛る炎の魔術", "Sigrun Ironhewのために、Black Drake's Heartを手に入れて下さい。", "Feranor Steeltoeの弟子として、武器に炎の魔力を込める彼独自の技術を学んだ。最後に聞いた話では、彼はLordaeronのどこかで狩猟隊と一緒に鍛冶場で働いていたそうだ。\n\n工程の詳細はあまり話せないが、まだ脈打っている珍しいblack drake whelpの心臓から採った血が要ることは教えられる。Ironforgeからの知らせを待つ間、たいしてやることもない。Lethlor Ravineのwhelpsから心臓を持ってきてくれれば、わしの腕を見せてやろう！", "狩りの具合はどうだ、{class}?", "ああ、これは申し分ない。これであなたの武器は焼けつく熱で敵を打つことができるだろう!", 0x00ee99c7, 0x78de126c, 0x734161e5, 0x60d53468, 0x2112a5d3, "....." },
  [707] = { "Ironbandは君を求めている!", "Loch ModanのIronband's Excavation SiteにいるProspector Ironbandと話して下さい。", "{name}。Loch Modanの発掘現場にいるProspector Ironbandから報告を受けた。我々の別の発掘作業について、足を使った仕事をしてくれる者が必要だそうだ。\n\nそれ以上の詳細は分からないが、足を伸ばしてみたいなら、Ironbandと話しに行ってくれ。", nil, "Stormpikeがお前を寄こしたのか？よろしい。\n\nお前に大きな仕事がある……", 0xdc23bbdd, 0x917408f3, 0xa0eaa700, nil, 0x672ef3e4, "...m." },
  [708] = { "ブラックボックス", "Corroded Black BoxをIronforgeのHall of Armsへ持って行って下さい。", "この金属製の黒い箱の表面はひどく腐食していて、まるで酸に浸されていたかのようだ――giant condorの胃の中に長いこと入っていたに違いない。\n\n箱をひっくり返すと、底に刻印された紋章が見つかる。紋章の下には次の言葉がある：\n\n「Engine #$N1 - Ironforge Siege Brigade」", nil, nil, 0x92a4b6f7, 0xa1e26151, 0x0ce91279, nil, nil, "...mm" },
  [709] = { "破滅の解決法", "Tablet of Ryun'ehをTheldurin the Lostに渡して下さい。", "ああ！ああ！破滅が迫っている。覚えておけ！破滅だ！\n\nいや、それについては話せない……奴らの名を口にすることはできない、聞かれてしまうかもしれないから！だが知ることができれば、そうだ、奴らについてもっと知ることができれば……奴らを阻む方法も分かるかもしれない！\n\nたぶんな。\n\nUldamanに入れ。しまった！言ってしまった！見つけなければならない……tablet of……Ryun'ehを見つけるんだ。そうだ、見つけろ！それと、二度とその名を口にさせないでくれ！\n\nそれはあの場所の奥深く、古代の箱の中にある。そこに隠されているんだ……どんなドワーフの作品よりも前に作られた箱の中に。", "tabletは見つかった? きっと秘密が隠されているはずだ! 我々を救う秘密が!", "おお、俺たちはついてる! ありがとう! 俺たちはいつか救われるかもしれんぞ!", 0xf37befea, 0x0f7e3ccb, 0x432c1eef, 0x0622ee3e, 0x6de453a4, "....." },
  [710] = { "元素の研究：岩", "Small Stone Shardsを$N1個見つけ、BadlandsのLotwil Veriatusのところへ持って行って下さい。", "このBadlandsで足を止めて、最新の研究に取り組んでいるんだ。元素束縛の枷さ。\n\n完成すれば、メイジはもっと強力なelementalsを召喚して、もっと大きな用途に使えるようになる。手始めに、組み立てたいくつかの小道具と一緒に、最新の攻撃呪文を試すためのsmall stone shardsが必要なんだ。\n\nその欠片は、ここの西にいるlesser rock elementalsから簡単に集められる。持ってきてくれないか？", "この場所はまさにうってつけ―― ちょっとこれを押さえていてくれるかい? そう、そんな感じで、法線ベクトルに沿って。さて、何の話だったか……そうそう。私の最新の研究を試すのにうってつけなんだ。原材料に広々とした空間……知的で啓蒙された術の実践者として、これ以上何を望むというんだい?", "これで十分だ、{name}。ありがとう。ふむ、思っていたより砂が多いな。摩擦係数を調整しないと。いや、待てよ。冷却油があれば、それでも無視できる程度のはずだ。\n\n<Lotwilは何やらつぶやきながら、片方の拳をもう片方の手のひらに押し当て、魅入られたようにそれを見つめている。>", 0x14ae4a05, 0x9ea0b6d1, 0x4c24d635, 0x4b37701d, 0x1f985c21, "....." },
  [711] = { "元素の研究：岩", "Large Stone Slabsを$N1個、BadlandsのLotwil Veriatusのところへ持って行って下さい。", "{name}、君はもう私の弟子全員を合わせたよりも有能だと証明してくれた。\n\n次に必要な部品は、もう少し力が要る。注意深くやれば、large stone slabsはrock elementalsから手に入る。あいつらの体はより強く大きいから、私の実験に十分な大きさの欠片を持っていることが多いんだ。ここのさらに西か、南東の山の縁沿いで見つかるよ。\n\n急がなくていい。君が持ってきてくれた小さい欠片を試すのに、しばらくかかるからね。", "とても満足しているよ、{name}。私の呪文は予測どおり小さな欠片に作用した。この実験が思い描いたとおりに成功すれば、私が操れるようになるelementalは、これまでに召喚されたどんなものも顔負けになるだろう。", "{name}、実に驚きだ! これを全部運んでくるには、トーレンが半ダースは必要だと思っていたよ。", 0x14ae4a05, 0x8e3316e6, 0xe0bf524d, 0xbbaa3bad, 0x1642a153, "....." },
  [712] = { "元素の研究：岩", "Bracers of Rock Bindingを$N1個、BadlandsのLotwil Veriatusのところへ持って行って下さい。", "{name}、このBadlandsのelementalsから必要な部品がもう一つある。greater rock elementalsが持つbracers of rock bindingだ。私の計算では、その腕甲があれば私自身の枷の強さを測るのに十分なはずだ。\n\ngreater rock elementalsを占術で探ってみたら、ここの南西に一群がいた。確か、ogresの近くだったと思う。\n\n予備があるように、その腕甲を$N1個持ってきてくれ。Servoは私の触媒や研究資料をなくすことで悪名高いからね。", "君が見つけてくれた石板は理想的だったよ、{name}。ここでの作業が終わったら、余った分はLucienがKharanosへ持ち帰ることになっている。何しろ、また役に立つかもしれないからね。\n\nたとえば、高威力爆薬への学際的アプローチを研究し始めたら、ちょっとした便利な避難所の土台にちょうどいいだろうし……\n\n<Lotwilの声は次第に小さくなり、彼は実験に戻っていく。>", "{name}、研究助手になろうと考えたことはないかい? ない? 君の力がなくなったら、ここでどうすればいいのか分からないよ。知性、好奇心、そして力――そのすべてが1つにまとまっているんだから。", 0x14ae4a05, 0xd84b3f7d, 0x4e035ba3, 0x9f2fe9a5, 0x53e7ae8c, "....." },
  [713] = { "冷却剤で頭を冷やせ", "Frost Oilを見つけ、BadlandsのLotwil Veriatusのところへ持って行って下さい。", "Frost Oilについて教えてあげよう。エンジンや歯車の過熱を防ぐのに、これに勝るものはない。\n\n冷却性能は並外れているし、潤滑剤としての持ちの良さも比類ない。それだけじゃない。魔法の品に付与した魔力を保つのにも役立つんだ。\n\n私の枷の魔力容量を高めて、召喚した友人が私たちを皆殺しにするのを止められるほど強力にするために、小瓶に入ったそれが必要なんだ。\n\n私の友人のゴブリン、Bro'kinが作り方を教えてくれるよ。彼はAlteracにいる。", "必要なoilは見つかりましたか? 少しでも見つけてもらえたら、本当に助かるのですが。", "素晴らしい! これこそ新しいブレーサーにぴったりの冷却材だ。付与した魔法が一世紀もたなかったら、私の持ち物をすべてServoにくれてやるよ。\n\nこれが完成したら、Assemblyのメイジたちはみんな畏敬の念を抱くだろうね、{name}。まあ見ていてくれ。", 0xf0fc8054, 0xc86ab6d6, 0xa71fe6b0, 0x8c6ff65a, 0x13417f71, "....." },
  [714] = { "Gyro……何だって？", "GyrochronatomをBadlandsのLotwil Veriatusのところへ持って行って下さい。", "{name}、君はあらゆる基準をはるかに超える働きをしてくれた。\n\n<Lotwilは明らかに作業に気を取られている。>\n\nもしKharanosで会うことがあったら、遠慮なく仕事に応募しに来てくれ。\n\nおっと！ 早く、その……そう、それだ。ありがとう。\n\nあとはもう一つだけ必要なものがある。小さな部品だが、かなり重要なんだ。gyrochronatomだよ。\n\nひとつ取ってきてもらえれば、これを完成させる準備が整うはずだ。", "はいはいはい。ちょっと待って。\n\n<Lotwilは何かの装置をいじり続けている。>", "やった!\n\n<Lotwilはあなたの手からgyrochronatomをひったくった。>\n\n完璧だ……もうすぐ完成だ。いや、本当に。今度こそ本当にもうすぐ完成するんだ。このプロジェクトが私の最優先事項なんだ……今のところは。これをはめ込めば、君が一緒に作ってくれたものを自分の目で確かめられるよ。あと数分もあれば……たぶん……もっとかかるかもしれない。いや、ずっとかかるかも。まあ、様子を見よう……", 0x34ce9c06, 0x627c8c95, 0xe13e8bd5, 0x9ca70cff, 0x41304f13, "....." },
  [715] = { "液状の石", "Healing PotionとLesser Invisibility PotionをBadlandsのLucien Tosselwrenchのところへ持って行って下さい。", "君がLotwilのために手に入れた品は、心配事の中でも一番小さなものになりそうだよ、{name}。一方で、君はLotwilが大事にしている科学に十分長けていると証明してくれた。だから、私を手伝ってくれないか？\n\ninvisibility potionとhealing potionが必要なんだ。彼がこれをやり遂げたら、どちらもすぐに役に立つかもしれない。\n\nお返しに、Lotwilから学びながら開発しているポーションのレシピをあげよう。彼がここBadlandsでやっている研究の一部に基づいているんだ。", "彼はもうすぐ完成しそうだよ。君のほうはどうなってる?", "やった!\n\nいや、その、ありがとう、{name}。これはBadlandsを旅するときに役立つよ。", 0xbeb7bb3e, 0x5922ba68, 0xa487bd11, 0xd4547ef4, 0x0ccce1a1, "....." },
  [716] = { "布より石", "Patterned Bronze BracersをBadlandsのLucien Tosselwrenchのところへ持って行って下さい。", "Lotwilがどれだけけちかは知ってるよ、{name}。だから、君の苦労に報いて何か作ってあげよう。Lotwilの最新の発明という、来たるべき惨事から君を守る役にも立つかもしれない。\n\n君が彼のために集めてくれた余分な石を使って作業していてね、君が使いたくなるような良い腕甲を作れるんだ。もちろん、魔法付きさ。\n\n君のために作っている腕甲を完成させるには、鍛冶屋が作ったpatterned bronze bracersが必要なんだ。", "bracerを手に入れるのは、あまり先延ばしにしないほうがいいぞ、{name}。\n\n次に何が起こるか分からんからな。", "さあどうぞ、{name}。つけてみて。", 0xeedc8173, 0x498f738b, 0xb373b478, 0xa6c07646, 0x2adf97f8, "....." },
  [717] = { "大地の震動", "Sign of the Earthを使ってPillars of Amethyst、Opal、Diamondを起動し、Runestonesを手に入れる。\n\nルーンストーンをSeal of the Earthに置き、BlacklashとHematusを解き放つ。\n\n彼らを倒し、Blacklash's Bindings、Chains of Hematus、Sign of the EarthをGarekのところへ持ち帰って下さい。", "BlacklashとHematusがLethlorに幽閉されたままでいることを保証できないのは、もはや明らかです。black dragonsがそこに住み着き、ogresがSignを盗み出したということは、より思い切った手段を取らねばならないことを示しています。\n\ndrakesの牢獄は、Sign of the Earthを使わなければ取り出せない三つのルーンストーンによって維持されています。そのルーンストーンを使えば、彼らを幽閉している封印を破ることができます。\n\n{name}……彼らの眠りを永遠のものにしてください。", "強力な魔法と力が長きにわたってdrakeの牢獄を保ってきた。だが、BlacklashとHematusが解き放たれる可能性など、わずかでも許すわけにはいかない。", "これでKirin TorがLethlorの囚人たちのことを心配する必要はなくなった。私は師匠のもとへ戻り、成功を報告しよう。Krasusもきっと喜ぶだろう。", 0x7d07cc69, 0xbbfb9ece, 0x7d5bf7f6, 0xb145ad09, 0xb9d7d00e, "....." },
  [718] = { "蜃気楼", "Sigrun Ironhewのために、Supply Crateを回収して下さい。", "Uldamanの発掘現場から急いで引き上げる途中で、たくさんの荷車や補給品の木箱を置き去りにせざるを得なかった。Camp Koshの地元のogresどもが、腐った死体に群がるハゲタカみたいに、わしらが捨てた装備にたかっておる。匂いもたいして変わらん。死体とな、という意味だが。\n\nとにかく、奴らはわしらの武器やら何やらを積んだ荷車を持っていきおった……それで――まあ、ちょっと恥ずかしい話なんだが――食料をまったく手に入れられんのだ。\n\nわしらはちょっと困っておってな、手を貸してもらえんか？", "砂漠で腹を空かせるのはまずいぜ、友よ。これだけは言っとく。\n\nおや……あそこにあるのは何だ……", "本当にありがとう、{name}。君がいない間に、その……砂を口いっぱいに飲み込んじゃってね。それが……\n\nまあ、その話はいいや。今夜は外に出て何か食べよう。王のようにたらふくね!", 0x61389337, 0xd95c35bd, 0xfe5d5017, 0x003dbf6c, 0x5e7e63bd, "....." },
  [719] = { "ドワーフとその道具", "Ryedol's Lucky Pickを見つけ、Hammertoe's Dig Siteの南にいるProspector Ryedolのところへ持ち帰って下さい。", "よう、{name}。このあたりじゃ気をつけな。Dark Ironのドワーフがそこら中にいる――Shadowforge氏族みてえだった。\n\n奴らは俺が働いてた発掘現場を襲ったばかりだ――ボスのHammertoeを含めて、ほとんど全員が殺された。俺は命からがら逃げ出したんだ。\n\n現場はここのすぐ北で、物資をいくらか取り戻す方法を考えてるところだ。特に俺の幸運のつるはしをな。\n\n手を貸してくれる気はあるか？ あの忌々しいDark Ironの誰かが俺のつるはしを持ってるに違いねえ！ 奴らの誰でもおかしくねえ。", "Shadowforgeの連中が何を探してたのかは分からねえが、はっきりした目的があったのは確かだ。", "お前さんはわしの救い主だ、{class}。あのShadowforgeどもに誰かが思い知らせてくれて嬉しいよ。助けてくれてありがとうな。", 0xf2f2df17, 0x877e2891, 0xe325cf33, 0x553bfeb3, 0xb08b84c9, "....." },
  [720] = { "希望の兆し", "Prospector Ryedolを探し、Hammertoe Grezは生きていると知らせて下さい。", "<地図にはチョークで乱暴に書き殴られた文字がある。>\n\n「Ryedolへ\n\n奴らは俺をUldamanへ連れていくつもりだ。助けを送ってくれ。\n\n-Hammertoe」", nil, "Hammertoeが生きてる?! そいつはびっくりだ、{name}!", 0xe6cfbcde, 0x13014934, 0x9ca186c6, nil, 0x5183ebf0, "...m." },
  [721] = { "希望の兆し", "UldamanでHammertoe Grezを見つけて下さい。", "{name}、あいつを見つけてくれるか？UldamanでHammertoeを見つけられるか？\n\nあの薄汚いShadowforgeどもが、titanの発掘についてあいつが知っていることを聞き出すために人質にしてるなら、Ironforge全体がとんでもない危機に陥るかもしれん。\n\nDark Ironsの連中は、もっと強力なgolemsを作るための魔法をずっと前から探し回っておる。Hammertoeも同じことをしていたが、もちろん奴らを止めるためだけだ。\n\n奴らは、あいつの知っていることを聞き出すまでは生かしておくだろう。助けるつもりなら急がねばならんぞ！", nil, "うん？すまない…… <咳> ひどく力が出ない。もっと近くに来てくれるか、{class}？\n\nRyedolが寄こしたのか？Muradinに感謝を、あの子は昔思っていたほど頭が鈍いわけではないな。<咳>", 0xe6cfbcde, 0xb1d8d639, 0x06b4a29b, nil, 0x80322ca8, "...m." },
  [722] = { "神秘の護符", "Hammertoe's Amuletを見つけて、Uldamanにいる彼に返して下さい。", "勇敢だな……<咳>……わしのためにUldamanまで来るとは、{class}。\n\n本当に……このHammertoeを助けに来たのなら……<咳>……わしのアミュレットを……見つけてくれ。\n\nDeepshadowが持っておる……Magregan Deepshadowだ。奴はこの……遺跡のどこかにいるはずだ。止めなければ、あのアミュレットが奴らを……<咳>……巻物のところへまっすぐ導いてしまう。お前さん次第だ、{name}。頼む……あのアミュレットを取り戻してくれ。\n\nあの巻物があれば、Dark Ironsはさらに強力なgolemsを作れるに違いない。わしには分かる。骨身にしみて感じるのだ。", "Shadowforge氏族は……<咳> 危険だ。気をつけろ。<咳> amuletを見つけてくれ。", "はっ！<咳 咳>\n\nお前ならわしのアミュレットを見つけると分かっておった、{name}。\n\n<ぜいぜい> 実によくやった、{name}。<咳>", 0xe652e713, 0x071be869, 0x1fdf43a5, 0xb97feb8b, 0xd73cb9e2, "....." },
  [723] = { "信頼の期待", "Hammertoe's AmuletをBadlandsのProspector Ryedolのところへ持って行って下さい。", "<Hammertoeは傷を押さえ、しばらくして落ち着きを取り戻してから、再び口を開いた。>\n\nRyedolを探せ、{name}。わしのアミュレットを届けてくれ。<咳、咳> あいつなら……<咳>どうすればいいか分かる。わしが我らが種族の起源を探していたことも、そして……<咳>……Shadowforge氏族を止めるのもわしの使命だったことも、あいつは知っておる。奴らに巻物を見つけさせてはならん……<咳>", "ひどい一日だったと言いたいところだが、ここはBadlandsだ。毎日がひどい一日さ。", "Hammertoeの護符? あいつが死んだと思った時、俺はもっと元気が出てたと思う。だが確実だと分かったら、苦痛がもっとひどくなっただけだった。この護符はあいつのライフワークだったんだ。あいつの死を無駄にはしない。", 0x49c004dd, 0xec3e3ec3, 0x421a43e5, 0x0dc62f1d, 0x2202d187, "....." },
  [724] = { "信頼の期待", "Hammertoe's AmuletをIronforgeのHistorian Karnikのところへ持って行って下さい。", "よし、よし……誰ならどうすればいいか分かる？\n\nHistorian Karnikだ！そうだ！\n\n彼はIronforgeにいる。きっと力になってくれる。彼とHammertoeは、Uldamanで失われた遺物を探すために協力していたんだ。\n\n二人が表に出している以上のことを知っていると、Shadowforgeに気づかれたんだろう。\n\nHammertoeに何が起きたかをKarnikに伝えて、アミュレットを渡してくれ……次に何をすべきか教えてくれるはずだ。", "ああ、はい。またドワーフに何かを求めてやって来た旅人ですね。\n\nあなた、本当に申し訳ないのですが、今は意味のない質問に答えている暇がないのです。", "おお！いや、これはまったく別の話だ。この件の重大さには、まだ気づいていないだろう？\n\nHammertoeの死は深く悼んでいる。だが彼がこのアミュレットを持たせてお前をここへ寄こしたのなら、何が懸かっているか理解していたということだ。\n\n彼の死を悼む時間は、後で取らねばならん。\n\nこのアミュレットがこれほど貴重である理由の一つを見せよう。", 0x49c004dd, 0x95eca9ba, 0x7fe915a5, 0xd45e3eb2, 0xe506c168, ".....", nil, nil, nil, 0x81d3982e, nil },
  [725] = { "脅威の知らせの連絡", "Advisor Belgrumを探して手紙を渡して下さい。", "{name}、できるだけ急いでAdvisor Belgrumを探しに行ってくれ。君が見たことを伝え、我々がどう動くべきか尋ねるんだ。この書状で彼にもっと詳しく説明できるだろう。\n\nその間に、私はHammertoeの霊と話す時間を取ろう。BadlandsでのあのShadowforgeのろくでなしどもの活動を止めるのに役立つことを、彼が何か知っているかもしれない。祈るしかないな。", "ん? 何だ、{class}。", "おお、Historian Karnikからの便りか。素晴らしい。\n\n彼の用件のためなら、いつでも時間を作る。\n\n<Advisor Belgrumは手紙を開き、読み始めた。>", 0x89ff7c88, 0x790e8df6, 0xf6a9328f, 0xe8f8d678, 0xa9fc87c2, "....." },
  [726] = { "脅威の知らせの連絡", "Historian Karnikに話しかけて下さい。", "<Advisor Belgrumは書状を読み終えると、一瞬目を見開いた。>\n\nおお、これは不吉な知らせだ。\n\n{name}、Historian Karnikのところへ戻り、王の権限において、この情報に基づいて迅速かつ断固として行動するよう伝えてくれ。BadlandsでのShadowforgeの活動を止めねばならん。", nil, "王その人にこそ期待するような切迫さで、君はこの件に当たっているな、{name}。\n\nよろしい。ならばShadowforgeを打ち倒す方法は分かっている。\n\n奴らのUldamanでの動きは、本拠地であるAngor Fortressを叩けば鈍らせられる。", 0x89ff7c88, 0xdd8b2b72, 0xe52ea829, nil, 0x9262fa8d, "...m." },
  [727] = { "Yagyin's Digestを求めてIronforgeへ", "Sigil of the HammerをIronforgeのForlorn CavernにいるGerrig Bonegripに渡して下さい。", "Tabletは多くを語る。だが十分ではない！ まったく足りん！\n\n本があるのだ。Yagyinが遠い昔に書いた要約書が。私が逃げてきた……者たちは……その本をあちこちに置いている。そして奴らの最も博識な者たちがそれを研究しているのだ。そこには膨大な知識がある。我らを守るための知識が！\n\nGerrig Bonegripのところへ行け。奴はIronforgeの、Forlorn Cavernにある店にいる。このsigilを見せれば、奴はお前を仲間だと思うだろう。Yagyin's Digestを頼んで……私のところへ持ってくるのだ！", "こんにちは。私の店へようこそ。でも、触るものには気をつけて。\n\n知識は命取りにもなりますから。", "おや。ごきげんよう、同胞よ。\n\n地の底に棲まう者たちに讃えあれ。", 0x066c5aaf, 0x1e845d88, 0x983f061d, 0xe72adc6f, 0x3bc392a2, ".....", nil, nil, nil, nil, 0x735f8674 },
  [728] = { "Yagyin's DigestのためにUndercityへ", "Sigil of the HammerをUndercityのKeeper Bel'dugurに渡して下さい。", "石板は多くを語る。だが足りない！まったく足りない！\n\n本があるんだ。遥か昔にYagyinが書いた要約書が。私が逃げてきた……人々は……その本をあちこちに保管している。そして彼らの中でも最も学のある者がそれを研究している。そこには膨大な知識がある。我々を守る知識が！\n\nLordaeronのUndercityにいるKeeper Bel'dugurのところへ行け。この印章を見せれば、彼はお前を仲間の一人だと思うだろう。Yagin's Digestを求めて……それを私のところへ持ってくるんだ！", "おや、熱心な{class}のようですね。私のコレクションから学びに来たのですか? 結構!\n\nですが忠告しておきます。知識は強き者には力を与えますが……弱き者は狂わせてしまうのです。", "印は慎重に扱え、{class}。我らの誓いの正しさを信じぬ者もいる。\n\nそして我らのことを知れば、我らの失敗を願う者もいる。\n\n常に用心し、警戒し、そして忍耐せねばならない。", 0x9f7a5f9a, 0x64a7f5df, 0x99b5c268, 0xd9f0cfde, 0x7d2fec01, "....." },
  [729] = { "うっかり者の探鉱者", "南へ向かい、Prospector Remtravelの様子を確かめる。", "Master Greywhiskerから、偉大なProspector Remtravelの指導のもとで働くよう命じられた時は、なんと光栄なことかと思いました。Ironforgeの学院では、Remtravelの偉大な発見を誰もが知っていたのです。\n\nでもその探鉱者は、どうにも……その……周りのことに……無頓着なのです。\n\n私たちは偉大な文明の痕跡を掘り当てていました。恐ろしいゴーレムが地面から飛び出してきて、現場を制圧してしまったのです。Remtravelはまるで気づいていないようでした。私は助けを求めてAuberdineへ走って戻ってきたのです。\n\nどうか南へ行って、探鉱者が無事か確かめてください！", nil, "Hollee、君かい? この石を削るのを手伝ってほしいんだ。石用のブラシを取ってくれ、何か見えた気がする。\n\nおや、君はHolleeじゃないな! 私の石用ブラシを見かけなかったかい?\n\nそれは今はいい! 見つけた謎の化石をLeagueに送ると約束したんだ。Holleeはどこに行った?\n\nやることが山ほどある! さて、あの謎の化石はどこだ……それに私のブラシは……それにHolleeは……\n\nそれで、君は誰だい……まあ、どうでもいいさ。手伝いに来てくれたのならね。\n\n探し始める準備ができたら知らせてくれ。", 0xb9653d3d, 0xfae33a52, 0x15681a9a, nil, 0x1419b23f, "...m." },
  [730] = { "Darkshoreに異変？", "Auberdineへ行き、ドワーフの発掘隊の手がかりを探す。", "{class}が我らの世界の偉大な考古学の驚異に興味を持ってくれるとは、なんと嬉しいことか。\n\n我々の仕事は、Allianceの友人たちからしばしば単なる道楽だと片付けられる。だが多くの者が気づいていないのは、Khaz Modanでの最近の発見によって、LordaeronからKalimdorに至るまで、Azeroth全土を脅かす強大な力の存在が明らかになったということだ。\n\n私が最も案じているのは、Darkshoreへ送り出した調査隊のことだ。もう何週間も便りがない。\n\nAuberdineへ行き、彼らの行方の手がかりを探してくれ。", nil, "Chief Archeologist Greywhiskerが私たちを呼んでくれて本当によかった……。", 0x267580f4, 0x8039f2c6, 0xcf3329d9, nil, 0xa8b5955b, "...m." },
  [731] = { "うっかり者の探鉱者", "謎の化石を探すProspector Remtravelを守り、AuberdineのArchaeologist Holleeのところへ戻る。", "それでだ、Hollee……ああそうだった、お前はHolleeじゃなかったな。Holleeはどこだ？\n\nふん、それはどうでもいい。あの石のブラシを見つけなければ……いや、謎の化石だ！ あの化石を見つけねばならんのだ。DarnassusのExplorers' Leagueは、私が何をしてきたのか何らかの証拠を欲しがるだろうからな。\n\n準備ができたら知らせてくれ。一緒にあのブラシを探し出そう……いや、化石だ！ Leagueを満足させる何か書いたものを見つけるぞ。\n\nで、もう準備はできたか？", "探鉱者は生きているのか?", "Prospector Remtravelが無事でよかった、星々に感謝を! 言ったでしょう、あの人はうっかり者だって。あんな恐ろしい生き物がうろついている場所に残るって言い張るなんて、信じられない。", 0xb9653d3d, 0x700580fd, 0xf5e66d39, 0x7c063599, 0x6e9a29da, "....." },
  [732] = { "大地の震動", "Garekのために、Sign of the Earthを回収して下さい。", "Sigrunから、あなたが彼の大きな助けになったと聞きました。あなたの力をお借りできるかもしれません。私は師匠であるKirin TorのKrasusから、Lethlor Ravineで持ち上がっている問題を終わらせるためにここへ遣わされました。\n\nここでの私の任務の正確な内容や、果たさねばならない仕事については明かせませんが、それが極めて重要であることは確かです。\n\nCamp Boffの近くで時々見かけられる、さまようogresの一団が、Sign of the Earthと呼ばれる品を盗みました。私にはそれが必要なのです。それを持ってきてくれれば、もっと詳しく話しましょう。", "ogreの放浪の一団は、Badlands各地の野営地の間を移動している。乾いた大地から立ち上る熱と渦巻く風のせいで、奴らの足取りを追うのは難しいだろう。時々Camp Boffを通ると聞いた。見失ったら、そこを探してみるといい。", "Signを携えて良い知らせを持ってきてくれたな、{name}。Sign of the Earthは、Angor FortressのDark Ironのドワーフたちが、Deathwingの冷酷な副官2人、双子のBlacklashとHematusを封じるために作ったものだ。", 0x7d07cc69, 0xe26aa1cb, 0x0e0bcc38, 0x2ec936ec, 0xa3e7562a, "....." },
  [733] = { "がらくた漁り", "Sigrunのために、Scrap Metalを$N1個手に入れて下さい。", "防御設備やその他の必需品を作る材料をかき集められなきゃ、ここはきつくなりそうだ。このあたりのogresは、scrap metalを随分と持っているみたいだ。Badlandsの攻城兵器の話も、あながち的外れじゃなかったのかもしれんな……\n\nとにかく、探鉱者が俺たちのささやかな野営地の状態を心配し始めてるから、できればすぐにでも作業に取りかかりたい。\n\nogresの主な野営地は、ここから西へかなり歩いたDustbelch Grottoにある。", "まあ、手元にあるもので何とかやってはみたが……大したことはできなかった。物資はもっと見つかったか?", "まずは手始めだな、{name}。IronforgeかExplorers' Leagueから知らせが来るまでは、これでやりくりするしかない。\n\nさて、焼き入れ用の樽に入れる塩がどこかで見つかればいいんだが……", 0x6556ee93, 0x99f2ec43, 0x458b0c6e, 0x28ba293d, 0xb8136fa5, "....." },
  [734] = { "これは難しくなりそうだ", "BadlandsのLucien Tosselwrenchと話して下さい。", "素晴らしい、素晴らしい。\n\n<Lotwilは一瞬あなたを見上げてから、また枷の作業に戻る。>\n\nLucienと話してくれ、{name}。cog #$N1が必要なんだ。持ってきてくれるかい？", nil, "Cog #5だって? ああ、こいつはまずいことになりそうだ。", 0x37c2bb98, 0xe0210508, 0x483bd8db, nil, 0x14fc3d0b, "...m." },
  [735] = { "星、手、そして心臓", "Bonegrip's Noteに書かれた品をIronforgeのGerrig Bonegripのところへ持ち帰って下さい。", "Yagyin's Digestだと？ どこかで我らの新たな支部でも作るのか？ いや、気にするな、私が尋ねることではない。\n\n手を貸そう。余分な写しがあるのでな。我らは互いに助け合わねばならん、そうだろう？ そうやって我らは栄えるのだ。\n\n力ある品が三つ必要だ。それを持ってくれば、要約書を渡そう。\n\nその名を口にするつもりはない。誰が聞き耳を立てているか分からんからな。だが、ほら、書き留めてやろう。", "頼んでおいた遺物は持っているか?", "君は機転が利くな、{class}。我らの教団の新たな章を始めるのが本当に君の務めなら、君はうまく導いていけるだろう。", 0xd77a12cf, 0xcbb8f8fb, 0xfa1d29c2, 0xd9a08655, 0x40c41e03, "....." },
  [736] = { "星と手と心臓", "Bel'dugur's Noteに書かれた品をUndercityのKeeper Bel'dugurに渡して下さい。", "Yagyin's Digestが必要だと？では、お前の計画は新たな信徒を集めることか？もちろんそうだろう……そしてもちろん、手を貸そう、同志よ。\n\nだが、お前にも私を手伝ってもらわねばならん。\n\n力ある品が3つ必要だ。それを持ってくれば、要約書はお前のものだ。\n\nその品々の名を口にすることはできないが、書き記しておこう。\n\nこのリストにある品を手に入れてこい。それができれば、お前は我らが教団の支部を自ら開くに真にふさわしい。", "任務の具合はどうだ、{class}。", "すごいなあ! 君はすごい腕前を持っている。それでなければ、この遺物を手に入れる強運の持ち主だ。どちらにせよ、君は我々の財産だよ。", 0xd77a12cf, 0x75d8a5e0, 0xc3f2b5e1, 0xa6eb4a83, 0xc6dcd54c, ".....", nil, nil, 0xc77a90a9, nil, nil },
  [737] = { "禁断の知識", "Yagyin's DigestをTheldurinに渡して下さい。", "要約書を用意したぞ、{name}。細心の注意を払って扱えなどと言う必要はあるまい。それと、敵意ある者の手からは遠ざけておけ。\n\nこの本は多くの真実を秘めている……\n\n……そして真実は人を焼くこともある。", "おお! ずいぶん長いこと出かけてたな。digestは手に入ったか?", "手に入れてくれたか! おお、希望が見えてきた!\n\n君の働きが我らを救うかもしれん、{name}。君の像を建てるべきだ! 祠を建てるべきだ! 君の孫の孫の代まで、その名が讃えられんことを!\n\nただし……奴らが解き放たれて地上に現れなければの話だ。もしそうなれば、子孫のことなど忘れるがいい。\n\n奴らが解き放たれたら、我らは皆、虫の餌だ。", 0x9092a094, 0x03e7acf7, 0x9afc528e, 0x272ab73a, 0xe6e8ae9d, "....." },
  [738] = { "Agmondを探せ", "Agmondを探して下さい。", "Prospector Agmondは、南西のBadlandsにある我々の発掘現場の責任者だった。「だった」と言うのは……その、もう何週間も彼から連絡がないからだ。報告を受け取りたいから、Agmondを見つけてほしい。\n\n最後に聞いた話では、AgmondはBadlandsの最南端の発掘現場にいた。Angor Fortressの先にある小さな現場だ。探すなら、まずそこから始めるといい。", nil, "この骸骨は不幸なAgmondの遺体に違いない。彼の体は損傷を受けてぼろぼろになり、骨は綺麗に肉がついばまれていた。", 0xb8f48aab, 0xa522f785, 0x2dd9d0d7, nil, 0xd6cd386b, "...m." },
  [739] = { "Murdaloc", "Agmondを殺したMurdalocを倒す。\n\nStonevault Bonesnappersを$N1体倒す。\n\nLoch ModanのProspector Ironbandに報告して下さい。", "Agmondの足跡は西から続いている。岩や砂の上の血の跡から、このドワーフがかなりの距離を這ってきたことはすぐに分かる。\n\nそして、ここで息絶えたのだ。\n\nよく調べると、Badlandsの砂岩の一角に「Murdaloc」という言葉が乱暴に書き殴られている。\n\nAgmondの死んだ手のすぐ横に書き殴られていた。", "Agmondの安否について何か知らせはあるか? 彼は見つかったのか?", "酔いの醒める知らせだよ、{name}。しかし、Agmondは強い腕力と恐ろしいハンマースイングの腕を持っていたし、石頭だったんだ! 彼は呪われたtroggどもに殺されたけれど、きっとたくさん道連れにしていったと思う。", 0x6c30dcfa, 0x72090f0b, 0x465e79fd, 0xfa0cfef5, 0x02e7d9a0, "....." },
  [741] = { "うっかり者の探鉱者", "謎の化石をDarnassusのChief Archaeologist Greywhiskerのところへ持って行く。", "それで、探鉱者は謎の化石をDarnassusのExplorers' Leagueに送りたいと？ 彼を置いてDarkshoreを離れるのは気が進まないな。\n\nほら、{name}、この謎の化石をDarnassusのChief Archaeologist Greywhiskerに届けてくれ。", "何か用か、{race}?", "まあ! こんな発見をするなんて、さすがはProspector Remtravelだ!", 0xb9653d3d, 0x4673c264, 0x9261fce9, 0x99c037c7, 0x5249d78d, "....." },
  [742] = { "Ashenvaleでの狩り", "AshenvaleのSplintertree PostにいるSenani Thunderheartと話して下さい。", "若き冒険者たちへ! Ashenvaleの荒野が君を待っている!\n\nHordeはBarrensの北の地に強力な駐留軍を配置した。Splintertree PostとZoram Strand Outpost、二つの前哨基地はHordeに栄光をもたらすために戦っている!　自分の力量を示したい者は、そこで指示をあおげ。注意がある。Barrensの真北、Splintertree PostのSenani Thunderheartは、大いなる狩りに参加希望の冒険者たちを探している!", nil, "新しい開拓地へようこそ、{name}。Ashenvaleはチャンスにあふれる土地です。ここでは、あなたのような駆け出しの{class}が勇気を示すのに、限りないチャンスを見つけられますよ。この前哨の周りを探してごらんなさい。それと、Hordeの別の前哨がありますから、必ずZoram Strandへ出かけるのですよ。\n\nあなたがここにいるということは、狩りのことをさらに学びに来たのですね。よくお聞きなさい。さて、あなたが知らねばならないことを分かち合えるのを、とても嬉しく思いますよ。", 0x1bf465b8, 0x0a003978, 0x7489a1c6, nil, 0xedbc036b, "...m." },
  [743] = { "Windfury 族の脅威", "Bloodhoof Village の Ruul Eagletalon に Windfury Talons 8つを渡してください。", "話す時間を取ってくれて感謝する、{name}。私はRuul、ウォリアーであり教師だ。\n\nお前は明らかに、Mulgoreからさらに遠くへ冒険に出るのなら、試練に備えねばならない年齢に達している。\n\n力試しを望むなら、まずは南東にいるWindfury harpiesを探し出すことだ。奴らは道から離れた山の縁に沿って巣を作っている。\n\n奴らはここMulgoreにおける我々の天敵の一つであり、お前の腕を測るよい目安になるだろう。", "Windfuriesは恐ろしい敵だ。戦いでの奴らの強さに匹敵するものといえば、新鮮な肉への渇望くらいのものだ。", "よくやったな、{name}。旅立つ準備は充分できているようだ。旅が順調であるよう祈っているぞ。", 0xd4a11af3, 0x3e4caa58, 0x8d790d6c, 0x82a0757c, 0xdd9e3807, "....." },
  [744] = { "式典の準備", "Azure FeatherとBronze Featherをそれぞれ6枚ずつ集めて、Thunder BluffのEyahn Eagletalonに渡して下さい。", "{name}、俺の兄弟がもうすぐChief Bloodhoofの前に立つ。あいつのために頭飾りを作ってやれるのは光栄だよ。\n\nこの革紐をなめしている間に頼みたい事があるんだ。充分に羽を集めている時間がなくてね、君に羽集めをお願いできないかと。\n\nちょうどいい大きさの羽は、Thunder Bluffの北と北西にいるharpiesから採れる。デザインを完成させるのに必要なのは、あと空色と銅色の羽が6枚ずつだ。", "この頭飾りは、きっと兄への素晴らしい贈り物になるでしょう。", "助けてくれてありがとう、{name}。\n\nあいつの式典に関する俺の役目はほとんど終わったよ。あとは、頭飾りをあいつに渡して、式典の立会人になるだけだ。", 0x4e130e80, 0xf38f39b5, 0xea0f1c58, 0xc2f8f6ff, 0xb9642dba, "....." },
  [745] = { "土地の共有", "Palemane Tannerを10匹、Palemane Skinnerを8匹、Palemane Poacherを5匹殺し、Bloodhoof VillageのBaine Bloodhoofのところへ戻ってください。", "{name}、この地を傷つける多くの対立がある。私がかつて見てきたのと同じように、君がその証人とならないことを願っている。しかし、探し出してほしいものがひとつある。君にも分かるだろうが、もしこのままのさばらせておいては、小さな脅威もこの地の脅威になる。\n\nPalemane gnollがBloodhoofの南と、西の洞窟の中に住んでいる。彼らは、互いに分かり合おうという我々の試みを無視し、Mulgoreの野生動物を手当たり次第に殺している。\n\nもはや実力行使しかあるまい。", "Palemaneがもっと大地とそこに住む者たちを敬っていれば、この争いは決して起こらなかっただろう。", "{name}、私の課した仕事に、真剣に取り組んでくれてよかったよ。この大地とそこに生きるものたちを尊重することは、とても大事なことだ。生と死とは輪になっている……必然的にな。互いに、もう一方の存在なくしては存在できないのだ。このことをよく考え、決して忘れないようにするのだよ。", 0x26ffc744, 0xb5d17a3e, 0x8fb09aaf, 0x31c8332b, 0xe7331b89, "....." },
  [746] = { "ドワーフたちの採掘", "まず、Prospector's Pickを5つ集めてください。\n\n炉でProspector's Pickを壊し、Broken Toolsを作ります。\n\nBloodhoof VillageのBaine BloodhoofにBroken Toolを5つ渡してください。", "北西に採掘場を作ろうとしているドワーフたちがいる。彼らは大地の中に秘密があると考えていて、それは確かにそうなのだが、大地をえぐり冒涜することでその教えを得られるものではない。\n\nドワーフの採掘道具を集めて破壊し、壊れた道具を持ってきてほしい。\n\n採掘道具は炉で壊すことができる。炉はThunder Bluffにひとつあるが、別の炉……ドワーフのキャンプにある同じ炉でも事足りるはずだ。", "こんにちは、{name}。Broken Toolsは持っていますか? ドワーフの採掘はMulgoreのkodoを怒らせてしまいます。この冒涜は止めなければなりません!", "ありがとう、{name}。Mulgoreの獣たちも落ち着くだろうよ。そして精霊が望んでいるように、大地の空洞化が知識へ至るための道ではないことをドワーフたちに教えてやれただろう。", 0x2946e68d, 0x36dfb8c2, 0xa41c26a0, 0x4f307216, 0x360e92d2, "....." },
  [747] = { "狩りの始まり", "Camp NaracheのGrull HawkwindにPlainstrider Featherを7枚、Plainstrider Meatを7つ渡してください。", "君は見込みのありそうな雰囲気だな。部族に己の力量を証明するだろうね。いつの日か、大いなる都市Thunder Bluffで歓迎されるようになると思うよ。でもその前に、我が父Chief Hawkwindに力量を見せなきゃならない。\n\nここRed Cloud Mesaでは皆、鋭い狩りの腕前を誇っているんだ。トーレンの狩りは、必要に迫られて行うものと、運動のために行うものがある。ちょうど肉の供給が不足しているし、衣服に使う羽も必要だ。この近くにいるplainstriderを狩って、村に再供給することで君の力を証明してほしい。", "部族のためにmeatとfeathersを用意することは、族長の前でハンターとしての力を証明する第一歩だ。", "Naracheのトーレンは感謝しているよ、{name}。君は大いに見込みがあるね。", 0xc3235e62, 0x93fdc57c, 0x019bcbf5, 0x30e02e4f, 0x5501c907, "....." },
  [748] = { "汚された水", "Prairie Wolf Paw6つ、Plainstrider Talon4つをBloodhoofのMull Thunderhornに渡してください。", "ゴブリンとその従僕どもが我々の神聖な井戸を汚してしまった!　これを許すわけにはいかない。\n\n井戸を清めるために、私は浄化のトーテムを作らなくてはならん。そうしたら、トーテムを井戸へ持っていって清めの儀式を行ってくれないか。\n\nまず始めに、Winterhoof Water Wellの浄化トーテムを作ろう。そのためには、この地の助けを捧げなくてはならない。prairie wolfとplainstriderを狩って足と鉤爪を集めてくれ。彼らは南西にいる。\n\n足と鉤爪を持って私のところへ戻ってきてくれ、{name}。", "pawsとtalonsは持っているか、{name}?", "よくやってくれた、{name}。この足と鉤爪を使って、彼ら生き物の力を浄化のトーテムに封じ込めよう。", 0xb8a26047, 0x2a8356cb, 0x70184bd0, 0x559f8cc7, 0x89b71023, "....." },
  [749] = { "The Ravaged Caravan", "Ravaged Caravan にある積荷の中身を調べてきてください。", "何日か前、Venture Co. の隊商が護衛されながら Stonebull Lake の北岸を行くのを見つけた。前の戦いで我々は仲間を2人失っていたから、即座に攻撃をしかけて隊商を破壊したんだ。\n\n価値のありそうなものは松明で燃やしたと思って積荷をそのままにしておいたんだが、燃えた荷車の近くに Venture Co. の回収人どもが現れたから、我々の見込みが外れていたんだろう。\n\n隊商のところへ行って、積荷の中身を調べられるはずだ。", nil, "木箱の側面全部に Venture Co. Mining Divisionの印がつけられている。箱の側面に丁寧に刷られた注意書きは、この箱の中身が Venture Co. の中央工場のうちのひとつで処理される予定であることを示している。", 0xa500e769, 0x913fbdf4, 0xb6364b39, nil, 0x336db033, "...m." },
  [750] = { "狩りは続く", "Camp NaracheのGrull HawkwindはMountain Cougar Peltsを10個求めています。", "狩りに精通したトーレンは獲物がただの記念品でないことを知っている。平原の獣たちは我々に生きる糧を与えてくれる。いくつか価値あるMountain Cougar Peltを採って戻ってくれば、先達たちもお気に召すだろう。南の丘に奴らは潜んでいるだろう。\n\n子供たちの服も新調してやらにゃならんし、テントも修理が必要でな。", "部族のためにpeltsを用意してくれたら、あなたの気前の良い行いを父であるChief Hawkwindに伝えておきましょう。", "Naracheのトーレンはこの蓄えに感謝しているよ、{name}殿。狩猟の腕を磨いていけばいつの日かThunder Bluffにおいてあなたが崇拝されることになるでしょう。", 0x841a4863, 0x8102d1fe, 0x243dac7e, 0x6c46fb68, 0xe19931e6, "....." },
  [751] = { "The Ravaged Caravan", "Bloodhoof Village 近くの Morin Cloudstalker に Venture Co. Documents を渡してください。", "蓋をこじ開けてみると、Mulgore における Venture Co. の採掘事業のさらなる証拠である、分類された鉱石や鉱物がぎっしり詰まっているのが見えた。鉱石や鉱物の山の上から、しっかりと封をされた紙束を取り上げた。\n\n丘を東へあがると、何か動いている音がかすかに聞こえ、大きな炎から煙が上がっているのが見えた。", "やあ、{name}。我らの故郷でのVenture Co.の計画や活動について、何か新しいことは分かったか?\n\n奴らが他の土地と同じように我らの土地を搾取するつもりなら、Outrunnersがすぐにでも終わらせてやる。", "確かに Venture Co. は我々から天然資源を強奪しようと試みているようだな。これが本当だと分かってよかった。何か対処しなくちゃならないな。", 0xa500e769, 0x0e721958, 0x275bb1a2, 0xca60a30e, 0xcb7fd24f, "....." },
  [752] = { "雑用", "Chief HawkwindはCamp Narache南東の井戸付近に居る母親を探してくるよう求めています。", "部族の者は皆、命の調和を分かち合っている。我々は共に暮らし、共に働く。\n\n互いへの献身には、大きな責任が伴う。今、君にささやかな務めを頼みたい。\n\n母が今朝、Naracheの南東にある井戸へ水を汲みに出かけた。もうずいぶん時間が経っている。私がここで部族の務めを果たしている間に、様子を見てきてもらえないだろうか？", nil, "わざわざこのおばあちゃんを手伝いにやって来たの? おやおや、なんていい子だろうね?", 0x565c8400, 0xb6c07f5c, 0x22266d02, nil, 0xbaf97464, "...m." },
  [753] = { "雑用", "井戸(water well)からWater Pitcherを持っていき、井戸(water well)の北西のCamp NaracheにいるChief Hawkwindへ返してください。", "私は生涯を通じてたくさんの道を歩き、頑強だった足も老いさらばえた。\n\n我が部族のために務めをこなすことはまだできる。老人のやることだから、しばしば時間はかかるけれどね。\n\nでも、あなたは熱心な{class}のようだね。若い力を少し試させてもらうよ。井戸からwater pitcherを持っていって、Camp Naracheの長……私の息子のところへ運んでちょうだい。\n\n覚えておきなさい。どんな雑用でも、年長者の評価を得ることはできるものだと。", "平原から戻ってきたような顔をしていますね。Greatmother Hawkwindから何か言付けはありますか?", "我が母のお使いでpitcherを運んできたんだね。\n\nCamp Naracheのトーレンの助けとなり、他人にも手を差し伸べる君の意志は、いつの日かThunder Bluffの部族の誇りになるだろう。\n\n私はそう信じている。", 0x565c8400, 0x6368490a, 0xf72e32dd, 0xeb66c85e, 0x2178cc89, "....." },
  [754] = { "Winterhoofの浄化", "Winterhoof Water WellでWinterhoof Cleansing Totemを使い、Mull Thunderhornのところへ戻ってください。", "Winterhoof Water Wellを浄化するトーテムを作りましたよ。さあ、これを持って井戸へ行き、浄化の儀式を行ってください。汚らわしいゴブリンたちに守られた井戸が南東にあります。\n\nこれは簡単な仕事ではないでしょう、しかし再びこれまでのように水を使いたいのならば、やるしかありません。\n\n幸運を祈ります、{name}。", "ぐずぐずするな、{name}。Winterhoof Wellの穢れを取り除かねばならん!", "あなたが成し遂げたという知らせは、つい先ほど私のところにも届きました。井戸の近くにいる獣たちはすでに、ごくごくと水を飲んでいますよ。\n\nこの地のために素晴らしい事を成し遂げたのです、{name}。そして、トーレンの人々にとっても素晴らしい事をしたのですよ。", 0xcc5edaf5, 0x89a6b62d, 0x3c9c3742, 0x5c381be6, 0xc389e962, "....." },
  [755] = { "Earthmotherの儀式", "Camp Naracheの南の丘に住むSeer Graytongueのもとを訪ねなさい。", "Naracheのトーレンのために働きたいというあなたの意志と、学ぼうとする意欲は立派なことであります、{name}。私はいつの日かあなたがThunder Bluffに偉大な{class}として知れ渡るであろうと信じています。\n\nその前にあなたは３つのEarthmotherの儀式を終えなければなりません。\n\nはじめはStrengthの儀式です。Seer Graytongueのもとを訪れ、彼にChief Hawkwindが訪れるように言ったと告げなさい。\n\nCamp Naracheの南の丘の隠れた所に予言者の住まいはあるだろう。", nil, "Chief Hawkwindがあなたを送ってきたのか？Earthmotherの儀式をはじめるのはたやすいことではない・・。", 0x7df8fef9, 0xe288069f, 0x91bed61c, nil, 0x4cd10b4a, "...m." },
  [756] = { "Thunderhorn Totem", "Stalker Claw・Cougar Clawをそれぞれ6つMull Thunderhornに渡してください。", "Thunderhorn Cleansing Totemを作るには、Mulgore平原にいる肉食動物の爪を集めなくてはなりません。prairie stalkerを狩ってstalker clawを、flatland cougarを狩ってcougar clawを集め、私のところへ戻ってきてください。\n\n東と西にprairie stalkerとflatland cougarを見つけることができるでしょう。", "{name}、集めてくるよう頼んだclawsは持っているか? Thunderhorn Water Wellは一時間ごとに穢れを増しているのだぞ!", "ありがとう、{name}。獣たちが狩りをする純粋さが、次の浄化トーテムの創造にはとても重要なのです。\n\nこの土地で争いあうことと、調和を保って生きていくことの間にある違いを、ゴブリンたちは決して学びはしないでしょう。", 0xe8309f4d, 0xbc8ba1fb, 0x53c6b880, 0xe827177e, 0x710f55bc, "....." },
  [757] = { "力の儀式", "Brambleblade RavineにいるBristlebackを倒し、Bristleback Beltを12個集めCamp NaracheにいるChief Hawkwindに渡してください。", "Earthmotherの儀式は若きトーレンがThunder Bluffにおける敬意を得るために必要なステップだ。\n\nまずは力のテストに合格しなければならん。このテストにおいて、一族の敵を倒すことで勇敢さを証明するのだ。\n\n東のBrambleblade RavineにいるBristlebackどもは我らの土地に侵害をしている。奴らは我々が狩りをしているところを待ち伏せたり、闇にまぎれこの村から盗みを働く。\n\n悪党どもを打ち倒す勇気を見せよ。そしてその証拠として奴らのベルトをCamp NaracheにいるChiefのもとへ持ち帰るのだ。", "Rite of Strengthは果たしたか、{name}? 我が部族の敵、Bristlebackを相手にしたそなたの武勇の証が必要なのだ。", "Earthmotherの最初の儀式には合格だ。仲間も誇りに思うだろう。", 0xf671573e, 0xfccb1ae7, 0x910b75e2, 0x9c7434f5, 0x73f2fc7f, "....." },
  [758] = { "Thunderhornの浄化", "Thunderhorn Water WellでThunderhorn Cleansing Totemを使い、Mullのところへ戻ってください。", "トーテムが出来ましたよ、{name}。そしてもう一度、浄化の儀式を行ってもらいましょう。\n\n村の北にあるThunderhorn Water Wellへ行って、儀式にThunderhorn Cleansing Totemを使ってください。それが終わったら、私のところへ戻ってくるのですよ。\n\n精霊のお導きのあらんことを。", "Thunderhorn Water Wellはまだ穢れたままです、{name}。どうか、儀式を行ってください!", "夢の中で、Thunderhorn一族の祖先が私に語りかけ、井戸でのあなたの行いを賞賛していました。\n\n感謝の気持ちを表すために、祖先たちはこれをあなたに贈りたいそうです……", 0x58669439, 0xdd2b0e6c, 0x3a75f7e9, 0x4f9e2854, 0x1f3f8b27, "....." },
  [759] = { "Wildmaneのトーテム", "Bloodhoof VillageのMull ThunderhornにPrairie Alpha Teeth 8個を渡して下さい。", "清めるべき井戸は、あと一つだけ残っています。Wildmane氏族の名を冠した井戸です。この井戸を清らかにするには、大地に獰猛な捕食者、prairie wolf alphaの牙を捧げねばなりません。北にいるalphasを見つけ、狩りを終えたら私のもとへ戻ってきてください。\n\nalphasは、私たちの偉大な都、Thunder Bluffのふもとをよくうろついています。", "{name}。頼んでおいた牙は持っているか?", "とても良いですよ、{name}。この捧げ物には、この地が払った犠牲を感じ取れます。それで私の魂は悲しみと誇りとで溢れているのです。", 0x31b3fafd, 0xc6a6a863, 0xd7b8ed1e, 0x8617acfb, 0xb1d9bbda, "....." },
  [760] = { "Wildmaneの浄化", "Wildmane Water WellでWildmane Cleansing Totemを使い、Mull Thunderhornのところへ戻ってください。", "WinterhoofとThunderhornの井戸での浄化は、精霊たちのあいだで話題になっていますよ。若き{name}。Wildmane Totemが出来ましたから、あなたの最後の仕事はもう目の前です。\n\nWildmane Water WellはThunder Bluffの北にあります。儀式を行い、ゴブリンの毒で汚された土地を癒すのです! 再び清らかな流れを取り戻してください!", "最後の井戸は今も腐って毒に満ちている、{name}。ぐずぐずしてはならん!", "やってくれましたね。井戸を清め、我々の土地を癒してくれました。Bloodhoof villageは感謝していますよ、{name}。\n\n風があなたの行いを百の季節が巡るまで語り続けますように、そして、Mulgoreの水がいつまでも清らかでありますように。", 0xef853d46, 0xe1ef1416, 0xe826c668, 0xf89fe265, 0x2756872c, "....." },
  [761] = { "Swoop 狩り", "Trophy Swoop Quill 8枚を Bloodhoof Village の Harken Windtotem に渡してください。", "swoop はずる賢い鳥で、見つけて狩るのは難しい。Swoop の羽の収集は、狩人にとって決断力と賢さの印なのだ。\n\nもしこの仕事にとりかかりたいのなら、平原に行き、swoop を狩るんだ。\n\n羽を持ってきて、君の一族に名誉をもたらすのだ。\n\nswoop は Mulgore のあちこちで見つけられるだろうが、奴らを見つけるには目を鋭く光らせろ。そして、捕まえるには俊足でなくてはならん。", "swoopは見つけたか、{name}。quillsは持っているか?", "この羽を集めるのが簡単な事じゃないのは分かってるよ、{name}。これで、君は賞賛に値する{class}だと証明されたんだ。Bloodhoof Village に君を受け入れるのは、結構なことだ。", 0x94bab1f1, 0x29a14ae0, 0x91563b63, 0xa8ba17e3, 0x1264b4dd, "....." },
  [762] = { "邪悪の使者", "Angor FortressのAmbassador Infernusを殺し、その証拠をIronforgeのAdvisor Belgrumに渡して下さい。", "Ambassador Infernusは、Uldamanで失われた遺物を探すShadowforgeを見張るため、Ragnaros自らの命によってAngor Fortressへ送り込まれた。\n\nすでに我らの民に甚大な犠牲をもたらしているが、事態は明らかに悪化している。奴らがどれほどの遺物を見つけ出し、Ironforgeに向けて使えるのか、推し量るのもためらわれるほどだ。\n\n我々の目的は単純だ、{class}。Badlandsへ戻り、Ambassador Infernusを倒せ。脅威を排除したら、勝利の証を持ってAdvisor Belgrumのもとへ戻るのだ。\n\nあとは君の手にかかっている。", "一刻を争うのだ、{name}。Ragnarosは我らの準備が整うのを待ってはくれぬ。", "{name}、Ironforgeとドワーフの民への君の献身は、誰にも否定できん。この件での助力に感謝する。\n\n君が成し遂げたことをHistorian Karnikに知らせよう。それに、発掘現場を取り戻す助けとなるよう、できる限り早くBadlandsへ援助を送らせる。重ねて礼を言う。\n\n行く前に、King Bronzebeardの名において、もう一つ頼みたいことがある。", 0x902feb49, 0xe760c0e4, 0xb93e4bb5, 0xd934d645, 0xe043779f, "....." },
  [763] = { "地母神(the Earthmother)の儀式", "Camp Naracheから道なりに進んで、Bloodhoof VillageのBaine BloodhoofにTotem of Hawkwindを渡してください。", "そなたがRites of the Earthmotherを続けるには、あと2つの試練を越えねばならぬ。{name}、そなたが経験を広げる時が来た。\n\nBloodhoof Villageへ赴き、族長であるCairneの息子、Baine Bloodhoofを訪ねよ。そこでそなたは旅を続け、Thunder Bluffの長老たちに認められることができよう。\n\nこのトーテムをBaineのもとへ持って行くがよい。彼は我が彫り物に気づき、そなたの道を助けてくれるであろう。\n\nCamp Naracheから道をたどり、急いで旅をせよ。道を外れるでないぞ、さもなくば迷うことになる。", "私の村へ何の用で来た、{class}?", "や、これは良き友Chief Hawkwindからの便りだな! ああ、この彫刻で君が特別だと分かったよ。", 0x7df8fef9, 0x03e6da03, 0xfd5f3bae, 0x4f49dc5c, 0xf9a3f2f5, "....." },
  [764] = { "Venture Co.", "Bloodhoof VillageのMorin Cloudstalkerのために、Venture Co. Workerを14人、Venture Co. Supervisorを6人殺してください。", "これで、Mulgoreで見かけたVenture Co.の社員や機材が増えている理由がわかった。あのゴブリンども……やつらの会社は身の丈に合わないほど急速に拡大している。よく言うだろう、ゴブリンに何かを見せれば、背後で天秤の音が聞こえる、とな。\n\n強欲な小物どもだ。やつらの商売にとっては不運なことに、我々トーレンは、やつらが我々の土地で事業を行うことを許すわけにはいかない。荒らされたキャラバンの北東にあるやつらの鉱山へ行き、思い知らせてやれ。", "Venture Co.はここMulgoreでの採掘権を拒まれたが、どうやら断られても引き下がるつもりはないらしい。だが我らトーレンは言葉を濁す者ではないし、こちらの意思を伝える方法は他にもある。", "ふむ、この警告を誤解したり無視したりなんて出来なかろうよ。傲慢にもVenture Co.は抗議活動もなく天然資源をかすめ盗れるとでも信じていたんだろうが、トーレンを甘く見られないと分かっただろう。", 0xf2993d30, 0xd5d4a54b, 0xf3734121, 0x13728f08, 0xfaa63db1, "....." },
  [765] = { "Supervisor Fizsprocket", "Supervisor Fizsprocketを殺し、彼のクリップボードをBloodhoof VillageのMorin Cloudstalkerに渡してください。", "君があのキャラバンから持ち出してきてくれた文書によると、Venture Co.は我々を追い出すためにたくさんの策を練っているようだ。\n\nこの土地でやりたい放題に略奪できるようにな。\n\n奴らが目的を果たすために深く沈んでいくあの深みってのは、どうも気持ち悪いしゾッとする。奴らの計画を後ろで操ってる奴を殺してほしい。そいつの名前はSupervisor Fizsprocketだ。ravaged caravanの東にあるVenture Co. mineにいると思う。奴のクリップボードを持ってきてくれ。何か役に立つものが見つけられるだろう。", "Venture Co.が利益の名のもとに我らに対して平気で行おうとしている残虐な行為を思うと、怒りが煮えたぎる。", "悪党のFizsprocketが死んだって知らせで、少し溜飲が下がったよ。Venture Co.がこれから計画してることについて何か追加情報が見つけられないか、奴の私物を調べてみるよ。君の尽力には感謝するよ、{name}。", 0x189f219c, 0x173e8cc7, 0x334998bc, 0x10cf1ff1, 0x9ad50194, "....." },
  [766] = { "巨鳥Mazzranache", "Prairie Wolf Heart・Flatland Cougar Femur・Plainstrider Scale・Swoop GizzardをBloodhoof VillageのMaur Raincallerに持ってきてください。", "祖父は、Mazzranacheという名のstriderとの戦いの話をしてくれた。Mazzranacheは悪魔のような赤い目をし、剃刀のような鋭い鉤爪を持ち、汚い口で噛みついたそうだ。\n\n巡り合わせのおかげで、平原を旅しているあいだに私はそいつに出会ったのだが、肩をひどく噛まれたよ。\n\n祖父が言っていたとおりの恐ろしい奴だった。この傷の消毒をするのに、動物の稀少な部位がいくつか必要なんだ。\n\n狼の心臓とクーガーの大腿骨、plainstriderの鱗、それにswoopの砂嚢だな。\n\n急いでくれ、一刻を争うことなんだ。", "熱はひどくなる一方で、意識がうわ言のような悪夢の中へさまよい出てしまう……祖父にも倒せなかった獣を、私が相手にできるはずがないと分かっているべきだった……\n\n治療薬の材料は持っているか? すぐに感染した傷を清めなければ、これが命取りになるだろう。", "ああ、どうもありがとう、{name}。君が持ってきてくれたこいつで、治療薬が作れるよ。これで感染が広がるのを止められるし、いずれは完全に治せる。君は命の恩人だな。\n\nそれにしても、Mazzranacheが私に向かってきたときの、振り下ろされるあの真っ赤なくちばしと金切り声……二度と忘れられないだろうな。\n\n君も充分に気をつけろよ。", 0xc53484ac, 0xc072894f, 0x179b5a29, 0x03b0363b, 0x1f60bcdb, "....." },
  [767] = { "幻影の儀式", "Bloodhoof VillageのZarlman Two-Moonsと話してください。", "Earthmotherの儀式のうちのひとつ、幻影の儀式は、Thunder Bluffの長老たちの関心を得るのに役立つでしょう。\n\n最も神聖な養い手がこの大地であることを、我らの民は学びました。この儀式に参加するためには、この村の祭司長であるZarlman Two-Moonsと話さなくてはなりません。", nil, "{class}、あなたが私の元へ来ることを予見していましたよ。Earthmotherの儀式に挑戦しようという者は、いつでも受け入れています。", 0x41285dc9, 0x38d9ca06, 0x991d2c64, nil, 0xb19dcd8c, "...m." },
  [768] = { "皮集め", "Thunder BluffのVeren TallstriderにLight Leatherを12枚渡して下さい。", "ごきげんよう、お若いの。君の目には輝きがある、平原へ狩りに戻りたくてうずうずしてるだろ。\n\n君が一族に名誉をもたらさんことを!\n\n俺はThunder Bluffのみんなのために、獣の皮を衣類や鎧に加工して働いているんだ。\n\n獣を狩って皮を持ってきてくれたら、何か作ってあげるよ。", "また会ったね。狩りはしてきたかい? 私に皮を持ってきてくれた?", "おお、とてもいい皮だね。これは良質の革製品になるよ。\n\nさあ、{name}。交換でこれを持っていってくれ……", 0x20df24d4, 0xf2d8885d, 0x1d87caf8, 0xa3f0a992, 0xec223580, "....." },
  [769] = { "Kodo Hide Bag", "Thunder BluffのVeren TallstriderにLight Leather4枚とCoarse Thread4つを渡して下さい。", "Mulgoreのkodoは強くて逞しい、その特徴は俺たちの間ではとても尊重されているんだ。君がLeatherworkingの技術を持っていて、Kodo Hide Bagの作り方を知りたいのなら、俺が商売に使ってる物を持ってきてくれ。\n\nそしたら君に知識を分けてあげよう。", "私の物資は持っているか、{name}?", "ああ、いいね。ありがとう、{name}。若者がLeatherworkingの技術に興味を持ってくれるとは、誇りで胸がいっぱいだ。", 0x2a31f358, 0x65e5965b, 0xd979157c, 0x934db7b4, 0x4f7e5b87, "....." },
  [770] = { "Demon Scarred Cloak", "Ghost Howlについて知っている人を探してください。", "Ghost Howlのぼろぼろの皮は、Burning Legionとの戦いで受けたひどい傷をとどめている。\n\nBloodhoof Villageの誰かが、Ghost Howlの死について知っているかもしれない……", nil, "信じられない! あの偉大な狼Ghost Howlを倒したというのか?　見直したぞ、若き{class}よ。君は並外れた腕の狩人だ。\n\n君に何かあげたい。私の狩人人生は終わってしまったが、この武器のどれかを使ってもらえたら光栄だ。\n\nこれが狙いを外さず、名声をもたらすように祈っている。\n\nそして、Ghost Howlの魂が安らぎを見いだしたことを願おう。", 0x2d2eee90, 0x9ee101a3, 0x7f4824a7, nil, 0x1cb5a6d0, "...m." },
  [771] = { "幻影の儀式", "Well Stoneを2つ、Ambercornを2つ集めてBloodhoof VillageのZarlman Two-Moonsに渡してください。", "幻影の儀式に通るためには、Water of the Seersを作る材料を集めなくてはなりません。\n\nまず必要となるwell stoneは、Mulgoreの井戸の周囲で見つけられます。そしてwell stoneと混ぜ合わせるAmbercornは、この地の巨木のそばに落ちています。\n\nこの材料は魔力を含んでいて、醸造して部族の炎の前で飲むと、幻影と会うことができるのです。幻影が現れたならば、それを追ってください。その幻影は神聖な旅の次の段階へあなたを導くことでしょう。", "水の井戸の周りからwell stonesを、木々の下からAmbercornを十分に集めてくれたら、あなたのためにWater of the Seersを用意しましょう。", "神聖な土地から収穫することを覚えましたね、{name}。Water of the Seersを醸造するために、ほんの少し時間をください。", 0x41285dc9, 0x59131882, 0x498db071, 0x381db944, 0x0d3c4b06, "....." },
  [772] = { "幻影の儀式", "Bloodhoof Villageにある部族の炎(tribal fire)の前でWater of the Seersを飲み、幻影が現れたらその後を追ってください。", "さあ、Water of the Seersを差し上げましょう。\n\n用意ができたら、部族の炎(tribal fire)の近くでこの水を飲んでください。この神聖な水を飲めば、間もなく炎の前に幻影が姿を現すでしょう。\n\nその時、自分の運命に従っていくかはあなた次第です。", nil, "恐れてはなりません、{name}。あなたは幻影の儀式を無事通過したのです。", 0x41285dc9, 0x703cb80a, 0x5c9c801d, nil, 0x1330e907, "...m." },
  [773] = { "知恵の儀式", "Thunder Bluffの東にあるRed Rocksへ行き、Ancestral Spiritと話してください。", "Thunder Bluffの長老たちに認められるためには、あなたは知恵の儀式を終えなくてはなりません。\n\nいまやあなたは幻影の儀式を終えたのだから、Red Rocksの祖先の霊も祝福してくださることでしょう。Water of Seersを飲んだ者だけが、その祝福を得られるのです。\n\n{name}、Thunder Bluffの東、Red Rocksへ赴き、Ancestral Spiritを探してください。", nil, "Earthmotherの儀式に通るため、そなたは不断の努力を示してくれた、{name}。\n\n我々祖霊は、我らの偉大なる都Thunder Bluffを守り礎を築くために勇敢な命を捧げた、大いなるトーレンの者たちの象徴なのだ。\n\n私はこれをもって、その守護の務めをそなたに託す。\n\nそなたは知恵の儀式を無事に終えたのだ、若き{class}。誇りをもってThunder Bluffへ入るがよい。", 0x3cab5a3b, 0xba53b13d, 0xeee894d8, nil, 0x6d5525a9, "...m." },
  [775] = { "Thunder Bluffへの旅", "Thunder BluffのCairne Bloodhoofと話してください。", "我々の偉大な都市で、あなたは今や尊敬される存在になっていよう。Earthmotherの儀式を終えた{race}の者は誰でも、栄誉を獲得するのだ。\n\n最後の試練のために、我々の高貴なる指導者Cairne Bloodhoofを探すがよい。彼はThunder Bluffの中で最も高い台地に住んでいる。", nil, "ごきげんよう、若き{class}。ようやく私の前に姿を現したな。", 0xdcd33962, 0x0ea57d96, 0x9394ae56, nil, 0xc4ed687f, "...m." },
  [776] = { "Earthmotherの儀式", "Thunder BluffのCairne BloodhoofはHorn of Arra'cheaを所望しています。", "君はEarthmotherの儀式に通り、Thunder Bluffでの地位を獲得した。\n\nだが、懸命になって達成したその地位を維持するためには、一族皆に価値を証さなくてはならない。\n\n{name}、我々は狩人だ。Mulgoreに下ると、そこにArra'cheaという名前の強いkodoがいる。Horn of Arra'cheaを持ってきて、追跡と狩りの腕前を見せてくれ。", "Arra'cheaはもう追い詰めたか?", "よくやった! 素晴らしい狩りの腕じゃないか。\n\n皮と肉を取るために、Arra'cheaの死骸を回収する者たちを送ろう。\n\n{name}、君は一族のためにとても役立つことをしたのだよ。", 0x7df8fef9, 0x661646b6, 0x721576c2, 0xc2995de7, 0x6d0429c3, "....." },
  [777] = { "これは難しくなりそうだ", "Cog #5をLotwil Veriatusのところへ持って行って下さい。", "よし、ほら。\n\n私はあっちの……物陰にいるよ。\n\n遠慮なく一緒にどうぞ。", "<Lotwilは枷から目を離さないまま、片手を差し出してもどかしそうに指を動かしている。>\n\n歯車だよ、{name}、歯車!", "ああ、完璧だ。下がっていてくれ、また新たな歴史を作る準備をするから!\n\n<Lotwilは熱に浮かされたように作業を続けている。>", 0x37c2bb98, 0x339155d8, 0x6d53b219, 0x1fb7c537, 0x0601f2f8, "....." },
  [778] = { "これは難しくなりそうだ", "Fam'retor Guardianを倒し、Lotwil's Shackles of Elemental BindingをLotwil Veriatusのところへ持ち帰って下さい。", "ははっ！ できた！ 枷が完成したぞ！\n\n時が来たぞ、Lucien。時が来たぞ、Servo！\n\n錬金術と工学と秘術の完璧な融合を目撃する準備はいいかい、{name}？\n\nこれから強力なelementalを召喚する。今日は私たち全員にとって画期的な日だ。", "思っていた結果とはちょっと違ったな。shacklesを取り戻してきてくれないか?", "ありがとう、{name}。なかなかの試練だったね?\n\n何がまずかったのか、よく分からない。私の魔法がその場にあって、あの生き物を故郷の次元へ送り返せたのは幸いだった。\n\n君の頑張りに、ちょっとした感謝の印を……", 0x37c2bb98, 0x8dcf7764, 0xc4035997, 0xead0334f, 0x4d93f8b5, "....." },
  [780] = { "Battleboars", "Camp NaracheのGrull HawkwindはBattleboarを倒しBattleboar Snoutを８つと、Battleboar Flankを８つ採ってきてほしいようだ。", "東のBrambleblade RavineのBattleboarどもは、我らの狩猟地を荒らしている。やつらはわれらと戦争状態にあるBristleback Quilboarどもに飼いならされているようだ。\n\n行け。そしてあの下劣な生き物どもを殺すのだ。いくつかSnoutとFlankを持ってきてくれれば子供たちにシチューを作ってやれる。", "Battleboarの凶暴さが増している。奴らにはっきりと思い知らせて、snoutsとflanksを持ち帰ってくれたか?", "なんとも素晴らしい。いいシチューができそうだ。猪どもの数を減らすことは下劣なBristlebackどもに対する正義の鉄槌だよ。", 0x378fb934, 0xee3fc884, 0xa5153aa4, 0xd39bd801, 0x1977a494, "....." },
  [781] = { "Camp Narache襲撃計画", "Camp NaracheのChief HawkwindにBristleback Attack Plansを渡してください。", "地図を丹念に調べた結果、それがBristleback warchiefのCamp Naracheに対する広範囲な襲撃計画書であることがわかった。\n\nChief Hawkwindに知らせねば！", "心配そうな顔をしているな、{name}。どんな知らせを持ってきた?", "こいつは実にびっくり仰天だ! しかし、この情報のおかげでBloodhoof Villageの同胞の助けを求めて、攻撃を食い止めることができる。多くのトーレンの命を救ってくれたね、{name}。", 0xb52d084e, 0xe65805d4, 0xe823abd6, 0x979a42f3, 0xe5c852a9, "....." },
  [782] = { "破れた同盟", "Boss Tho'grunを倒し、Sign of the EarthをKargathのGornのところへ持って行って下さい。", "Second Warの間にHordeが竜Deathwingと同盟を結んでいたことから、我々は彼の副官のうち二体、BlacklashとHematusが、はるか東のLethlor Ravineに幽閉されていることを知っている。Hordeの名誉を取り戻すために、かつての堕落した同盟者どもを黙らせねばならん！\n\n我々はdrakesの牢獄を開けるのに必要な鍵、Sign of the Earthを手に入れるため、Tho'grunと奴のogreの傭兵団を雇った。だがTho'grunは我々を裏切り、我々を圧倒して、それを自分のものにしてしまった。Camp Boffへ行って、取り返してこい！", "Tho'grunの裏切り……ogreがもはやHordeの一員でないのも不思議ではなかろう? 奴が死に、Sign of the Earthが戻ってくれば喜ばしい。\n\nまだ奴を始末していないなら、一刻も無駄にせずCamp Boffへ向かえ。Kargathの南東にある。", "Tho'grunが死に、その亡骸が砂漠の風と腐肉をあさるbuzzardにきれいについばまれた今、ogreどもは混乱に陥るだろう。小さな勝利だが、これがはるかに大きな勝利へとつながるのだ。\n\nSign of the Earthは今や我々の手にあり、Lethlorにあるblack drakeの牢獄を開くことができる。果てしない幽閉から奴らを解き放ってやろう。もっとも、その先に待つのは破滅だがな!", 0xa89be601, 0x02004cad, 0x29117d84, 0x0e0aa5d0, 0x3ca9207f, "....." },
  [783] = { "身近な脅威", "Marshal McBrideに話しかけてください。", "ベルトをしっかり閉めてくれ、新米{class}よ。ここNorthshireに君にふさわしい仕事がある。\n\n仕事とは農業ではない。\n\nStormwindの守備隊(guards)は付近の平和を守るために極度の緊張下にいる。我々の多くは外国におり、 その上多くの脅威が迫っているのだ。そこでわれらは故郷を、そして同朋(alliance)を守る勇気のある義勇兵を募集している。\n\nもし君がこの募集に応じてここに来たのなら、私の上官である Marshal McBride にその意思を伝えてくれ。彼はこの後ろの修道院(abbey)を入ってすぐのところにいるはずだ。", nil, "義勇兵への参加、感謝する。他にも志願者が来ている。ここ数日で君達のような義勇兵が何人か集まった。\n\nそろそろ人数は十分だろう。\n\nこの人間の国は外からの脅威に晒されており、わが軍のほとんどが外国に出兵している。そのため国内でも治安が悪化し、不心得な無法者の集団が増えている。\n\n今は国内外のあちこちで戦闘が頻発している状態なのだ、{name}。長い戦争になることを覚悟してくれ。", 0x5dfca6f5, 0x4ec936be, 0x0ab5d4f4, nil, 0x031c7505, "...m." },
  [784] = { "裏切り者に死を", "Kul Tiras Sailorを10人、Kul Tiras Marineを８人とLieutenant Benedictを殺してからRazor HillのGar'Thokのもとへ戻ってください。", "Admiral Proudmooreに率いられたKul Tirasの人間どもが何年も前にArchimondeを倒すために、WarchiefとJaina Proudmooreとの間で結ばれていた協定を破りDurotarに侵入してきた。\n\n撃退することに成功し、Tiragarde Keepも陥落した。だが最近Lieutenant Benedictに率いられたAdmiralの予備軍が城を取り戻し、再び我ら母なる大地の脅威となっている。奴らは外交というものに敬意を示さない。\n\n南へ行きTiragarde Keepから侵略者どもを追い払い、名誉を証明するのだ。", "命令は下したぞ、{name}。Durotarの安全が危ぶまれている。目の前の任務を果たすか、恥じて首を垂れるかだ。\n\nお前の名誉を示し、Tiragarde Keepの人間どもを倒してこい。", "お前の勇敢さはあっという間に広まるであろう、{class}。Tiragarde Keepでの勝利の冒険譚はOrgrimmar中に知れ渡るだろう。", 0x61203c69, 0x154583f4, 0x582379ba, 0x9292d6eb, 0xd22b726e, "....." },
  [785] = { "戦略的同盟", "Sen'jin Villageの西の外れにいるLar Prowltuskを探し出して下さい。", "Thrallは実に賢明で高潔な指導者だ。戦場での粘り強さに匹敵するのは、その外交の手腕だけだ。\n\nDarkspear Trollsは、オーク族にとってかけがえのない盟友であることを示してきた。忠誠と名誉から、我々は彼らを守る盟約を結んだのだ。\n\n大族長は、Sen'jin VillageにいるDarkspearの友が直接の脅威にさらされていないか確かめるよう命令を出された。彼らの最も信頼される斥候の一人、Lar Prowltuskが西の側面を厳重に見張っている。\n\nLarを探し出し、必要に応じて手を貸してやれ。", nil, nil, 0xf723c36b, 0xf3d70985, 0x1c00d4e5, nil, nil, "...mm" },
  [786] = { "Kolkarの侵略の阻止", "Sen'jin Villageの外にいるLar ProwltuskはKolkar Cragの持つ３つのAttack Plansを処分することを望んでいます。", "声を落とせ、{class}殿。Kolkar centaurどもはKolkar Cragという西にある峰のすぐ向こうにたむろしている。\n\n昨夜やつらが襲撃に出た隙に、奴らの村に忍び込んだ。そしてあの薄汚れた野獣どもがDurotarのオークやトロールに対して３段階にわたる襲撃を計画していることを知った。\n\nそんなことをさせるわけにはいかん。たぶんあんたはKolkar Cragに潜入する能力はもってるだろう。奴らの計画書を処分してくれ。\n\n見たところ、そいつは３人のリーダーの下に別々に置かれていたようだ。", "centaurはHordeにとって絶えず厄介な存在であることが分かった。我らの故郷を包囲しようという奴らの企みは、断じて許せん。", "もしKolkar centaursが攻め寄せたとしてもHordeは必ず勝つ。しかし未然に防ぐことによっていらぬ血を流すことは防げた。\n\nそしてTanaris砂漠に砂があるのと同じくらい確かに、この厳しい時代の中で流される血があることをわれらは知っている。\n\nよくやったよ、{class}殿。", 0xb1c3cfee, 0x456bae15, 0x42ae48a2, 0x6f511eae, 0xe654120a, "....." },
  [787] = { "新たなるHorde", "DenのGornekに報告する。", "Throm'ka、{class}。私はEitrigg、Thrallより新兵の訓練を監督する任を受けている。\n\nHordeはかつての姿から変わった。私がHordeを去った時期もあった。Burning Legionの権力に飢えた手先どもの影響が強まっていくのに幻滅したのだ。追放の身の間に、私は人間の一団に捕らえられたが、大族長に救い出された。シャーマンに導かれ、悪魔の影響から解き放たれたHordeという彼の構想を聞いて、私は戻ったのだ。\n\nこの先の指示はGornekが出してくれるだろう。", nil, "またEitriggが連れてきた新兵か、ん?\n\nこれがHordeの生み出せる精一杯だというなら、情けないありさまだ。まあいい。お前がValleyを出る準備ができたと我々が認める頃には、誇り高きHordeのウォリアーになっているだろう。", 0x1b8f33fb, 0xfeeb0bec, 0x360ecd22, nil, 0x73610f14, "...m." },
  [788] = { "カッティングティース", "Mottled Boarを10匹倒してから、DenにいるGornekの元へ戻ってください。", "最初の仕事はお前の精神に少しばかり力を与えてくれるだろう。Barrensに行ってKodoを狩ってこいと言う事もできるが、しかし、アー、正直なところ死んでしまっては元も子もないからな。\n\nここの北にいるMottled Boarどもあたりが適当だろう。", "まさか任務を終えたと言いくるめに戻ってきたのではあるまいな、{name}? いや、もちろん違うだろう。君のことはもっと買っている。", "ウウム、悪くない、{name}。しかし浮かれてはならんぞ。お前はこれから猪どもよりもっと強いものと戦っていくのだからな・・。\n\nしかしまあ、申し分ないことはわかった。次の試練はよりいっそう危険なもの共に対するものだから、少しばかり防御を固める必要があるな。", 0xd952680c, 0xe879ed8f, 0xbc4c97b2, 0x33c5034a, 0x0851ec59, "....." },
  [789] = { "Scorpidの針", "Scorpid Worker Tailを10個DenにいるGornekのために手に入れてください。", "力強い戦士だろうと駆け出しの初心者だろうと、scorpidの毒針は等しく襲ってくる。ここの北西に数多くのscorpidがいる。お前が優れた戦士であるということを証明するために、やつらのtailを10個持ってくるのだ。\n\nscorpidの毒の解毒剤は奴らの針から抽出する。お前のような血気盛んな若者を治療するために、数多くの解毒剤を所持していなければならん・・・。\n\nしかしお前には解毒剤は必要ないと思うがね？", "scorpidの甲殻は、決意あるウォリアーの力を阻むほど厚くはない。迷わず力強く打て。そうすればscorpidなど容易い獲物だ。", "scorpidとの戦いでお前は重要なことを学ばねばならん。どんなに小さな敵でも大きな敵でも、お前の命取りになりうる。激しい戦闘の中では、数多くの事がお前を破滅に追いやるだろう。\n\nもう教えることはない、{name}。よくやった。興味深くお前の成長を眺めさせてもらうよ。", 0xa7461cce, 0x3563df4d, 0x9f27737c, 0xe82bc356, 0xd139b0d4, "....." },
  [790] = { "Sarkoth", "Sarkothを倒してそのカギ爪をHana'zuaのもとへ持ってきてください。", "{class}！こんなとこで誰にも知られずに死ぬと思ったよ。scorpidを退治していると、とても邪悪そうな一匹に出会った。奴に突進して、大打撃を与えることができたんだが同時に奴のカギ爪も私の足にからみついた。\n\n心の準備をするまもなく、それは振り下ろされ胸に刺さった。肉が切れ、血が噴き出した。たのむ、あのscorpidを殺してくれ！死んでも死にきれん！南の坂を上がった草原に奴はいる。", "ああ……父はいつも、俺は大した者にはなれないと言っていた。こうして命が流れ出していく中で木の下に横たわっていると、どうやら父の言う通りだったようだ。\n\nせめて、生涯最後の敵が死んだと知って死にたい。", "私の一撃では奴は死ななかったようだ。しかし私の与えたダメージを見るのは少しは誇りを満たしてくれる。死んだらそれっきりだがな。そう考えると腹立たしくてならないな。", 0xc29f8f29, 0xed33aa8a, 0xabbb648b, 0x3647febb, 0x59471209, "....." },
  [791] = { "背負うもの", "Razor Hill watchtowerにいるFurl ScornbrowはCanvas Scrapを８つ求めています。", "年をとると戦うことがきつくなる。だが、ほかのやり方で役立てることもあると思う。\n\nここから侵略者がいないか見張っている。我々の勢力が拡大するにつれ、警笛を鳴らすことも少なくなりつつある。\n\n若い者たちが我らの大地を守る有能な戦士になるためのものを作って時を過ごしている。\n\nお前のために、所持品を入れるバッグを作ることもできる。ご入用なら、人間やcentaurどもが持っているキャンバス生地をいくつか持ってきてくれ。", "この地が切り拓かれたとき、私は誇りを胸に大族長と肩を並べて戦った。戦いの傷跡がこの肌に刻まれている。\n\nArchimondeを打ち倒した折には、必要に迫られて人間やエルフと不浄な同盟が結ばれたが、Hordeの名誉は私の斧と鬨の声によって守られたのだ。\n\nだが、見張りと食料調達の役目を得て、私は自分の新たな価値を見出した。", "実にいいね、{name}。あらゆる本物の{class}は戦場でのこのバッグの使い方を知ってるものさ。\n\nHordeの名の下に戦わんとするお前の意志に敬礼！", 0xf3916378, 0xacb97dc1, 0x620d5ba2, 0xca1b14ce, 0x6227d388, "....." },
  [792] = { "Vile Familiars", "Vile Familiarを12匹倒してから、Denの外にいるZureetha Fargazeのところに戻ってください。", "Valley of Trialsであなたは多くのことを学ぶであろう、若き{class}よ。\n\nあなたを導くためにこの谷に私は送られた。しかしここで腐敗が広がりつつあることに気づいた。\n\nBurning Bladeと名乗る集団がここValley of Trialsで怪しげな集会を行っている。彼らは北東にある洞窟でこそこそ何かをやっている。奴らのVile Familiarが破壊をもたらすためにそこからわきでている。\n\nBurning Bladeに対する最初の仕事として、申し渡す。そのしもべどもを倒せ。たくさん殺せ。生き残れたら戻ってこい。", "Burning Bladeに対して力を示すには、まずそのVile Familiarsを倒さねばならない。それを成し遂げたら戻ってこい。", "よくやった、{name}。\n\nVile FamiliarはBurning Bladeの暗黒の力を持つただのペットに過ぎないが、この成功は更なる大きな行為を予告している。", 0x8ce65439, 0xcd4c8281, 0x88673f1b, 0xa51a267d, 0x83d0b880, "....." },
  [793] = { "破れた同盟", "Sign of the Earthを使ってPillars of Diamond、Opal、Amethystを起動し、Runestonesを手に入れる。\n\nルーンストーンをSeal of the Earthに置き、BlacklashとHematusを解き放つ。\n\n彼らを倒し、Blacklash's Bindings、Chains of Hematus、Sign of the EarthをGornのところへ持ち帰って下さい。", "Seal of the Earthは三つのルーンストーンによって封じられている。それらはLethlor RavineのPillars of Diamond, Opal, and Amethystに収められている。Sign of the Earthを使えば、ルーンストーンを取り外してSeal of the Earthを解くことができるだろう。\n\nだが気をつけろ、{name}。黒いdrakesであるBlacklashとHematusは侮れない相手だ。奴らを始末し、その拘束具を私のもとへ持ち帰ってくれ。\n\n峡谷へ行くには、Badlandsのはるか東部へ向かえ。だが用心しろ、あの峡谷には無数のdrakesが棲んでいるからな。", "竜族ほど恐ろしい敵はそうはいない。そして、BlacklashとHematusほど獰猛に戦った竜もそうはいなかった。", "black dragonflightは離反したBlackrockのオークと手を組み続けている。両者とも従わせるか、排除しなければならない。BlacklashとHematusが死んだ今、我々は西のBlackrock Spireへと目を向けることができる。", 0xa89be601, 0x06a8e74d, 0x770a314d, 0x15504fe8, 0x33da6391, "....." },
  [794] = { "Burning Blade Medallion", "Burning Blade MedallionをDenの外にいるZureetha Fargazeに渡してください。", "予言を通して、獣と黒き術に守られたBurning Blade Covenの奥深くに力のアイテムが隠されているのが見えた。\n\nBurning Blade Medallionと呼ばれるものだ。それを見つけ、洞窟から取り除くのが次の仕事だ。\n\nしかし用心しろよ。MedallionはBurning Bladeのエージェントが持っているかもしれん。そうだとしたらそいつの力は今までの敵とは比べ物にならんだろう。\n\nゆけ、{name}。北西にある洞窟の中にその儀式場はあるだろう。", "任務は終わったか、{name}? Burning Blade Medallionは持っているか?", "持ってきたか！よくやった！\n\nBurning Blade Covenに対するお前の努力は、Valley of Trialsからあの狂信者どもを根絶やしにする重要なものである。しかし奴らはもっと大きな狙いを持っているのではないだろうか。\n\n奴らの最後は誰も見ていない。", 0xd7a9ded1, 0x0d382153, 0xb70542ce, 0x8771c5c2, 0x7c8c1f1c, "....." },
  [804] = { "Sarkoth", "Hana'zuaが苦境に陥っていることをDenにいるGornekに伝えてください。", "あんたがしてくれたことを見て、心が奮い立ったよ。たやすくやられるわけにはいかん！耐えねば！\n\nしかし手助けなしにDenに戻るのは不可能だということにかわりはない。たのむ、{name}。Denに戻って、私の置かれた状況をGornekに伝えてくれ。たぶん彼が助けてくれる。", nil, "お前の話からすると、そいつはSarkothだな！Hana'zuaがやられたって無理はない。すぐに助けを送ろう。Hana'zuaのことはもう心配するな。\n\nしかし、Sarkothを倒したと聞いて感動したことを言わずにはおれんな。誇りに思っていい、{name}。見知らぬ誰かのために戦い、時間を費やすことはおまえ自身の名誉を高めるだろう。", 0xc29f8f29, 0xafd8ceaf, 0x6faf13ea, nil, 0xc5de3e04, "...m." },
  [805] = { "Sen'jin Villageへの報告", "Sen'jin VillageにいるMaster Gadrinに話しかけてください。", "Burning Bladeに対するお前の試練は終わった・・ここではな。しかしお前が見たものを報告してきてほしいのだよ。\n\nSen'jinというトロールの村へ行き、Master Gadrinを探してくれ。Sen'jin Villageはここの東にある。分かれ道を右だ。\n\nGadrinにBurning BladeがValley of Trialsに手を伸ばしてきたことを伝えるのだ。やつらがSen'jinにも手を伸ばしているか確かめるのだ。\n\nゆけ、{name}、急ぐのだ。Burning Blade Covenで見出された悪が、更なる脅威の前触れでしかないのではと恐れているのだ・・・。", nil, "ウウム・・、悪いときに報告に来たな。Burning BladeはここSen'jinでは見かけない。しかし奴らの害悪は海岸の向こう、Echo Islesで種まかれているようだ。\n\nオークたちはDarkspear Trollの尊敬すべき友人だ。オークたちを助けたい。しかし・・われらも助けを必要としている。", 0x3a372a4c, 0x0c77979e, 0x0bbd2c9e, nil, 0xda50f16d, "...m." },
  [806] = { "暗き嵐", "Razor HillのOrgnil SoulscarにFizzle's Clawを渡してください。", "DurotarにBurning Bladeの橋頭堡を築かせてはならん！ひどくなる前に手を打たねばならん！\n\n調べたところBurning Bladeのウォーロック、ゴブリンのFizzle Darkstormが北西のThunder Ridgeの中で宿営していることがわかった。奴とその手下はそこから混迷を広めている。\n\nFizzleを見つけ出して、殺せ。そして彼のつめを取ってくるのだ。", "Fizzleは見つけたか、{name}? 奴もBurning Bladeの残りの者どもも、我らの地から一掃せねばならん!", "おお！やったか！\n\n一族の誇りだな、{name}。君のおかげで、Durotarは悪の組織の手から守られたわけだ。", 0x2402e200, 0x7fa60fc3, 0x7cc19661, 0x20286f9c, 0x3cc1d2bc, "....." },
  [808] = { "Minshina's Skull", "Echo Islesにある力の輪からMinshinaの頭蓋骨を回収する。\n\nそれをSen'jin VillageのMaster Gadrinのところへ持って行って下さい。", "わが兄弟、Minshinaが私を呼ぶ声が夢の中で聞こえてくる。\n\n彼は東のEcho Isleにすむウォーロック、Zalazaneに捕らえられ、殺された。\n\nしかし死してなおわが兄弟は自由の身となったわけではない。Minshinaの魂はZalazaneの魔術により彼の頭蓋骨の中に閉じ込められたままだ。夢の中で、Echo Isleのもっとも大きな島にあるcircle of powerに置かれた無数の頭蓋骨の中に彼のものもあるのが見えた。そこにおかれている限りわが兄弟の魂は成仏できまい。\n\nたのむ、{name}。circleを見つけ出してMinshina's skullを取り戻してはくれまいか。私のもとへ持ってきてはくれまいか。\n\n彼を自由にしてやってほしいのだ！", "兄の頭蓋骨は持っているか、{name}? 兄はようやく解き放たれたのか?", "ありがとう、{name}。Minshinaは救われたよ。わが兄弟の魂は今解放されたのだ！", 0xdcd76bb7, 0x55625a18, 0xd5b48458, 0xbf95ade1, 0x4cdebc60, "....." },
  [809] = { "Ak'Zeloth", "BarrensにいるAk'Zelothに話しかけてください。", "Burning Legionを打ち負かした先の大戦以来、オークのあいだにおける悪魔的な堕落の源を捜し続けてきた。君が持ってきたCollarが私の恐れていたことを確信させた。\n\nそれはBurning Blade、悪魔の力を持つものの周りに集まる教団が所有する。Demon Seedと呼ばれているそれはBarrensのDreadmist Peakの頂上に存在する。破壊しなければならん！\n\nここから西のBarrensの境界にあるFar Watch Postに行くのだ。そこで私の助手Ak'Zelothと話をするのだ。彼が更なる指示をくれるだろう。", nil, "NeeruがDemon Seedを破壊してほしいって？変だな・・・。\n\nまあいい。彼の望みならその方法をお教えしよう。", 0xc03c9820, 0xc0c2c1e8, 0x8b606564, nil, 0x8f364e63, "...m." },
  [812] = { "このままじゃやばい", "OrgrimmarにいるKor'ghanを見つけ出して、Venomtail Antidoteを手に入れてください。手に入れたならDurotarの北西の境界線近くにいるRhinagに渡してください。", "{name}・・・ちょうどいいところにきてくれたよ。急いでくれるといいんだが。\n\n近くのVenomtailと戦っているときちょっと油断しちまったんだ。一匹にグッサリやられちまった。しゃべるたんびに毒が回っていくのを感じるよ。このままじゃあと一時間と持たないだろう。もしそうならちょっと助けてほしいんだが・・・\n\nOrgrimmarにいるKor'ghanなら解毒剤の作り方を知っているよ。彼を見つけてくれ・・なるべく早く、{name}。あんまり持ちそうにない。彼はCleft of Shadowにいるだろう。", "今のこの姿でSen'jinに戻れないのが、むしろありがたいくらいだ。俺の弱さと愚かさは、きっと嘲笑われるだろうからな。", "{name}、助かったよ。ありがとう。\n\nこれを持ってってくれ。手持ちが少ないなら何かの足しにはなるだろう。あなたの言うとおり直に私には必要なくなるだろう。Kor'ghanは私が一人前と認められるまで、もっと儀式をやらせるだろう。もっと猪を殺さねば、もっとscorpidの尾を集めねば・・・＜ため息＞", 0xac00d112, 0x6effbb1f, 0x4c6dedad, 0x018eb78e, 0x5fe8b88a, "....." },
  [813] = { "解毒剤を探し出せ", "OrgrimmarにいるKor'ghanにVenomtail Poison Sacを４つ届けてください。", "venomtailはDurotarで最も危険なscorpidの一種だ。Rhinagが解毒剤も持たずにやつらを狩りに行ったのは愚かだったが、今のあいつに一番必要ないのは説教だ。\n\nOrgrimmarの入り口近くにいるvenomtailから、venomtail poison sacをいくつか取ってきてくれ。そうすれば、あいつのために解毒剤を作ってやる。\n\n急げ、{name}。仲間の一人がお前の助けを必要としている。", "覚えておけ。どんな生き物を狩るにせよ、よく観察してその習性を理解することだ。その知識が命を救うこともある。", "できたよ、{name}。これを持ってできるだけ早くRhinagのとこへいってやんな。気をつけてな。", 0xf085941f, 0xbfb9abac, 0x76075c6a, 0xf792b3ad, 0x5339c8f3, "....." },
  [815] = { "Razor Hillで朝食を", "Razor HillのCook TorkaにTaillasher Eggを３つ渡してください。", "わお！朝飯の支度をするのを忘れてたぜ。\n\n{name}、ひとっ走り行って何個かTaillasher eggをとってきてくれないか。明日のことも考えたら最低３つはほしいとこだな。\n\nBloodtalon taillasherは凶暴だし、死んでも卵を守ろうとするだろう。奴らは用心して卵を地中深くに埋めることもある。だがSen'jin Villageの南東にあるEcho Islesに行きゃあ見つかるだろう。", "朝食、昼食、夕食! どの食事だろうと誰が気にする? どのみち誰かが作らなきゃならない――つまり俺がな!", "君は弱いかもしれんが不器用ではないな、{name}。\n\nほらこれを持ってどいてくれ。料理しちまうからよ。", 0x5872ab42, 0x6e4abc1b, 0xb26fb94f, 0x9f710600, 0x85e91f1f, "....." },
  [816] = { "受け入れがたい現実", "Kronの死の証をRazor Hillの北西の農場にいるMisha Tor'krenに渡してください。", "{name}、お願いです、手を貸してくれませんか？私の息子Kronは数日前狩りに出かけました。それからまだ戻らないのです。彼はBarrensとの境界のSouthfury River沿いにいるcrocoliskを狩りに西に向かいました。いやな予感がするのです。\n\nあの子はたくましいのですが、かたくななプライドが常に災いを引き寄せていたのです。私はあの子にcrocoliskは力強く、獰猛であると注意しました。彼は腹を立て、怒って出て行きました。\n\nあの子を見つけることができなかったら、せめてあの子の手がかりだけでも見つけてもらえないでしょうか・・。あなたにSouthfury's bank沿いのすべてのcrocoliskの腹を切り裂く手間をおかけするとしても。", "Kronが私のもとへ戻ってくるよう祈っていますが、彼の運命はもう分かっているような気がしてなりません。", "ああ、私の・・私の自慢の息子よ。\n\nあの子が出て行ってからずっと、行方がわからなくてずっと苦しんできたの。何が起こったか知った今、おそらく悲しみがわいてくるでしょう。\n\nありがとう、{name}。これを持っていってください。あの子が無事戻ってきたとき、あの子に渡そうと思っていたものです。あの子の死を知った今、これを見ているだけでもつらいのです。", 0xdc0dedea, 0xcc865ae2, 0xb2b27950, 0xe760bb38, 0xf0b43d80, "....." },
  [817] = { "素材が足らない", "Sen'jin VillageのVel'rin FangにDurotar Tiger Furを４つ渡してください。", "我々が使う皮のほとんどはDurotar tigerのものだ、{name}。毛布、防具、テント。われらが獣を狩り、同時に繁栄させるのには多くのわけがある。\n\nいわば、ある群れを狩るときがきたのだ。我らの勢力が拡大しつつあるので在庫が底をつきかけている。適切な数をそろえようと思ったら、もっと多くの皮がいる。\n\nDurotar tiger furを４つ持ってきてくれたら、礼をしよう。奴らは南の島にいるよ。", "初めての虎狩りを覚えているぞ、{name}。私はEcho Islesで一番大きな島で狩ることに決め、その茂みの影でほぼ丸一日じっと座っていた……見張り……待ちながら。\n\n筋肉は張り詰め、いつでも飛びかかれる構えだった。あの虎がついに餌に食いついた時は、私の最大の勝利の一つとなった。", "うれしいぞ、{name}。我らの民が守られるのも、寒さに震えなくてすむのもあんたのおかげだ。\n\nありがとよ。", 0xe98eb762, 0xc04aa178, 0x87d30384, 0x79595368, 0x849219dc, "....." },
  [818] = { "魂の溶剤", "4つのIntact Makrura Eyesと8つのvials of Crawler MucusをSen'jin VillageのMaster Vornalに持ってきてください。", "わしの両目が衰えたとはいえ、まだ十分にはっきりと見ることができる。以前よりも頻繁に、わしはかつて容易く行えた魔法でわしを助けるために錬金術の腕前に頼らねばならなくなった。しかしわしは見習いは雇わんぞ。見習いに十分に値するトロル、オークはこれまでやってこなかった。\n\nお前にはその値打ちがあるか？ああ、勿論・・・勿論お前さんは自分がそうだと思ってるだろうな。\n\nわしはいくつかの物を必要としている。お前さんそれを取ってきてくれるか？\n\nわしは、無傷のmakruraの目とCrawlerの粘液の小瓶を必要としている。Durotarにいるどんなmakrura、Crawlerからも見つけることができるぞ。まもなくわしらは再び話をするだろうな。", "時こそが、お前の力と意志を真に試すものだ。忍耐を失うか弱さに屈すれば、お前の本性が露わになる。", "よくやった、若者よ・・・でかしたぞ本当に。", 0x0560be8b, 0x00d040ad, 0x16d40dbf, 0xc4a472af, 0xd20355b6, "....." },
  [819] = { "Chen's Empty Keg", "Chen's Empty Kegについて知っている人を見つけて下さい。", "樽の片方の端にある札にこう書いてある。\n\n「Chen Stormstout　あなたの心がうきうきしますように、そしていつも心をうきうきさせますように」", "何か？", "えーと、これは……\n\nChen Stormstoutの樽のひとつだ。Chenは昔、Rexxarと旅をしていた。ずいぶん長いこと、見聞きしてないよ。これを持ってきてくれてありがとう、{name}。", 0xc395691b, 0x99cbd4a8, 0xab7a0060, 0x0c07a888, 0x7257e695, "....." },
  [821] = { "Chen's Empty Keg", "Savannah Lion Tusk5つ、Plainstrider Kidney5つ、Thunder Lizard Horn1つをRatchetのBrewmaster Drohnに渡して下さい。", "Chenと同じ名前の味はいかがかな?　ああー、stormstoutは強い酒だよ。Chenは俺の師匠にレシピを教え、師匠は俺にそれを伝えてくれたんだ。いくつか物を届けてもらう必要があるんだが、「その興奮は苦労するに値する」って言えるよ。\n\nサバンナライオンの牙を5つと、plainstriderの腎臓を5つ、Thunder Lizardの角1つを持ってきてくれ。どのライオンだろうが、どのPlainstriderだろうが、どのThunder Lizardだろうが、種類はこだわらないよ。これが、うまいのを作る秘訣なんだ。\n\n素材はBarrens中で見つかるよ。", "探し物の具合はどうだい?", "ははは……またこれを作ることになると思わなかったよ。\n\n本当に懐かしい思いを呼び起こしてくれたもんだな、{name}。前にtroggビールを仕込んだときのことを思い出すよ。ありがとう。思い出が腹ん中をあっためてくれたよ。", 0xc395691b, 0x7c727806, 0x88214860, 0xdbae01bb, 0x59d50b70, "....." },
  [822] = { "Chen's Empty Keg", "Lightning Glandを5つ、Thunderhawk Saliva Glandを1つ、Kodo Liverを1つ、RatchetのBrewmaster Drohnに渡して下さい。", "stormstout、いい酒だったろ?\n\nChenから習ったレシピはもうひとつあるんだ。興味あるかい? 作るのに時間はかからないし、まだ旅する計画を立ててるなら、役に立つはずだよ。\n\nstormhideからlightning glandを5つと、greater thunderhawkからthunderhawk saliva glandを1つ、Barrensにいるkodoから肝臓を1つ持ってきてくれ。\n\n俺が言ったように、この酒は興奮モノなんだ。前に言ったtroggビールだよ。", "その材料探しに精を出してるかい、{name}?", "ははは! こういう酒に弱いのは知ってるよ。もっと欲しかったら、またいつでも来てくれよ{name}。集めてもらったのと同じ材料を持ってきてくれな。", 0xc395691b, 0xb481c111, 0xeda85af3, 0x3344caba, 0xa4ba152c, "....." },
  [823] = { "Orgnilへの報告", "Razor HillにいるOrgnil Soulscarと話をしてください。", "Sen'jin Villageにも我々なりの問題がある。手助けしてくれてありがとう。しかしあなたが持ってきたBurning Bladeに関する報告は皆にとって悩みの種となるだろう。\n\nBurning Bladeのような邪悪なものをDurotarから締め出す役目を負ったOrgnil Soulscarという名のオークがRazor Hillに配属している！Orgnilのところへ行き、Valley of Trialsからの知らせと共に我らの苦境を彼に報告するのです。彼も知りたがっているでしょう。\n\nRazor Hillはここの北にあります。", nil, "ん？何か報告があるのか？よし、聴こうではないか！", 0x8fb77557, 0xf5ac1ba5, 0xef556d0f, nil, 0xf17219be, "...m." },
  [824] = { "Earthen RingのJe'neu", "AshenvaleのZoram'gar OutpostにいるJe'neu Sancreaに、Befouled Water Globeを渡して下さい。", "Earthen Ringは、元素の研究と保護に身を捧げるシャーマンの集団だ。いかれた古の神々や古代の伝説、伝承について、やつらが忘れてしまったことの方が、たいていの学者が一生かけて知ることよりも多い。\n\n運のいいことに、ここAshenvaleのEarthen Ringに知り合いがいる。Zoram Strandの海岸にあるZoram'gar Outpostへ行って、見つけたものをJe'neu Sancreaに見せてくれ。あの球の意味を解き明かせる者がいるとしたら、あいつだろう。", "ああ、こんにちは。私は水の研究――というより、あらゆるエレメントの研究に多くの時間を費やしていまして、時には周りの人に気づかないほどなのです。\n\n何かお手伝いできることはありますか?", "この玉……これはかなり物騒だ。より強力な精霊が、この装置を通じて力とエネルギーを受けている。この玉がほぼ無傷なのが分かるのと……あまりにも穢されているのが分かるのでは大違いだ。\n\nこの玉はEarthen Ringによってきっちりと研究されるだろう。我々は精霊の腐敗を食い止めることができるだろう。Earthen Ringのために玉を持ってきてくれたことに対する対等な取引として、どうかこれを受け取ってくれ。", 0x6802f11f, 0xaff53a21, 0x31e82842, 0x21696c42, 0xc008b860, "....." },
  [825] = { "残骸より・・・", "Razor HillのGar'Thokは海岸近くにある残骸からGnomish Toolを３つ回収するようあなたに求めています。", "ある優秀な偵察員が、Tiragarde Keepの東の海岸にProudmooreの艦隊の残骸がまだ残っているとの報告をもたらした。\n\n不快な小さき生物ノームと同盟を組んでいる人間どもが最先端の機械工学の知識を持っていることは秘密でもなんでもない。仮想敵どものことをよく理解しておかなくてはならない。新しい知識は我々にも利益をもたらす。\n\n泳いでそこまで行くのだ、{name}。そしてAllianceの工具を回収してくるのだ。", "人間どもがあの奇妙な機械をどう動かしているのか分かれば、今後の戦いで奴らを打ち負かせる見込みが高まる。\n\n新たに得た知識によって、Hordeはますます強くなるばかりだ。", "回収できたようだな、{class}。次のキャラバンにこの工具をOrgrimmarまで運ばせよう。\n\nよくやった。", 0x181930de, 0x5b5b3e7f, 0xfad72992, 0x11689c03, 0xdacdadb7, "....." },
  [826] = { "Zalazane", "Zalazaneを倒してください。\n\nVoodoo Trollを８人と、Hexed Trollを８人殺してください。\n\nZalazane's HeadをGadrinに渡してください。", "祈祷師Zalazaneは東のEcho Islesにいる。かつては故郷と呼んでいたところだ。\n\nそこから彼は手下をこの大陸に送って、我らの民を苦しめ自らの支配下に置こうとしている。\n\n止めねばならん。\n\nZalazaneと彼の手下−もとはわれらと同じDarkspear trollであったものたち−を倒すのだ。彼の邪悪な統治が終わった証に、彼の首を持ってきてくれ。", "Zalazaneは倒したか、{name}?", "Zalazaneがいなくなったことで、再び平和が訪れたよ。\n\nありがとう、{name}。Darkspear tribeはあんたに借りができたな。具合が悪くなったら、後ろにいる助手のBom'bayをたずねるといい。彼の呪術は強力だからな・・・。", 0x489251bd, 0xe01a8eac, 0x24710aa2, 0xb7a847c3, 0xd30e272c, "....." },
  [827] = { "Skull Rock", "Skull Rockにいるカルト信者からSearing Collarを集め、野営地にいるMargozに渡してください。", "{name}。Burning BladeはSkull Rockとして知られるOrgrimmarの東の洞窟を荒らしている。その中で奴らは下劣な儀式を行いSearing Collarと共にその身を焦がしている。\n\nそのCollarを身に着けることで、彼らは悪魔的な力を手に入れるのだろう。確認したいので、そのCollarを手に入れ研究したい。\n\nSkull Rockへ行き、そこにいるカルト信者どもからSearing Collarを回収するのだ。持ってくるのだ。奴らの秘密を暴いてやる。", "Skull Rockにはもう入ったか、{name}? Searing Collarsは持っているか?", "よろしい。Burning Bladeの秘密はこのCollarの中に隠されている。では暴いてやるとするか・・。", 0x729f9f48, 0x54e6be8b, 0xff788f72, 0x6798c34d, 0x0a7d203c, "....." },
  [828] = { "Margoz", "Margozに話しかけてください。", "我らシャーマンの一人、MargozはBurning Bladeの腐敗についてより多くのことを知っているだろう。彼はBurning Bladeのカルト信者の大集団が隠れているSkull Rockと呼ばれるOrgrimmarのすぐそばにある洞窟について話をしてくれるだろう。\n\nSkull Rockへ行く前にMargozと話をするといい。彼は賢明であり、彼の助言は高く評価されている。\n\n彼はここから北東の海岸とDrygulch Ravineの間で野営している。\n\n彼の助言に従え。しかしMargozがなんと言おうとも{name}、あのカルト信者どもを打ちのめしてほしい！", nil, "歓迎するよ、{name}。君の来訪とDurotarにおける偉業は聞き及んでいるよ。\n\n君は技術も名声も伸び盛りの{class}だね。\n\nまっすぐ行きなさい。君の未来は限りなく広がっている。", 0x5cde94d6, 0x93909fb0, 0xb5d1aee2, nil, 0x6bc52b40, "...m." },
  [829] = { "Neeru Fireblade", "Example CollarをOrgrimmarにいるNeeru Firebladeに届けてください。", "君が持ってきたSearing Collarは強力な、悪魔的な道具だ。これの素性を見抜くには私のシャーマンとしての技能は足りぬようだ。ウォーロックに調べてもらう必要があるだろう。\n\nSearing collarをNeeru Firebladeのところへ持ってゆけ。彼は熟練のウォーロックだが、その力を悪魔に対するものに使うふりをしており、オカルティックな研究も無害なものだと主張している。それが本当かうそかはさておき、Durotarの悪魔的な教団に対抗するには彼の助けが必要だろう。\n\nNeeruはOrgrimmarのCleft of Shadowにいるだろう。", "謹んでご挨拶申し上げます、{class}。今日は我が{race}の同胞に、どのようなお手伝いができましょう?", "おお、これをどこで見つけたんだね？Razor HillのGood Margozが君をよこしてきたのかね？\n\nようし、ちょっと見せてもらえるかね・・・。", 0x868b3608, 0x613e9f65, 0x05a32b33, 0x4968d4eb, 0x71421289, ".....", nil, nil, nil, 0xec476d59, nil },
  [830] = { "提督の命令書", "Admiral Proudmoore's OrdersをRazor HillにいるGar'Thokに渡してください。", "古びてぼろぼろになった封筒を開けると、公式文書のようなものが入っているのを見つけた。Admiral Proudmooreの印章がついているのがわかった。\n\nとても重要に思えた。おそらくRazor Hillの司令官、Gar'Thokはこの書類に興味を示すであろう。", "顔に不安の色が見えるな、{class}。そこに何を持っている?", "なんとも悪い知らせだな。ここに持ってきたのは賢明だな。", 0x4748be45, 0xfca39656, 0x9476be3c, 0x74d48d62, 0x44e2b5b8, "....." },
  [831] = { "提督の命令書", "Admiral Proudmoore's OrdersをOrgrimmarのThrall's chamberにいるNazgrelに届けてください。", "人間を信用することはできん。奴らはいつか裏切ると思っていたから、一緒に戦っていてもうんざりしていたよ。\n\nAdmiral Proudmooreが死んでも彼の策略は止まらなかった。クズ人間どもは彼が死んでも計画が滞りなく進むようにしていた。\n\n彼の支配はBenedictが死んだくらいでは終わるまい。我らの国にProudmooreの軍勢が次にいつ押し寄せるのかは誰も知るまい。\n\nOrgrimmarにいるNazgrelにこれをすぐに届けねばならん！彼はThrall's chamberにいるだろう。", "私が忙しいのが分からないのか? よほど急ぎの用なのだろうな……", "Warchiefに人間どもを信用するなとしつこく言っているのだが、個人的な誇りが問題なのではない。\n\nお勤めご苦労、若き{class}。\n\nでは失礼。Thrallに今一度苦言を呈するとするよ。", 0x4748be45, 0xc9e47975, 0xe1d3b368, 0xe626e031, 0xb4d9dc76, "....." },
  [832] = { "Burning Shadows", "Neeru Firebladeにこの目を届けてください。", "<ペンダントから言葉があふれ出し、あなたの心に流れ込んでくる。>\n\nGazz'uz？\n\nGazz'uz……報告しろ！\n\nSkull Rockでお前が見つかったという知らせが入った。攻撃に備えねばならん！\n\nGazz'uz、話せと命じているのだ！ 話せ、さもなくばNeeru Firebladeにお前の存在を知らせてやる。そうなればやつは容赦なく素早くお前に襲いかかるだろう。\n\nNeeruに腕比べを挑むのはよせ……\n\n……Gazz'uz、そこにいるのか……？", "何か重要な報告があるのだな。お前の目の奥にそれを感じるぞ。", "<Eye of Burning Shadowを調べだした。>\n\n面白い。私の名を呼ぶ声を聞いたのか？私は我らのウォーチーフの敵を追い詰め捕らえるものとして知られている。しかし・・私が選ばれたとは不思議だな。さらに奇妙なのは、このペンダントを持っていたBurning Blade cultistsの名が私の名にこれほど似ていることだ。\n\nこのペンダントを調べねばならん。調べて、そのメッセージの意味を考えねばならん。\n\n届けてくれてありがとう、{name}。大いなる貢献だよ。", 0xa1f132b7, 0x04253717, 0x935523ac, 0x8ddce38f, 0xb049c8c8, "....." },
  [833] = { "神聖な墓所", "Red RocksにいるBristleback Interloper 8頭を殺して下さい。", "最も勇敢なトーレンだけが、神聖な墓地Red Rocksで眠ることができる。それは、己の部族と族長への至高の美徳に命を捧げ、Thunder Bluffをよく助け、守った偉大な戦士に授けられる栄誉なのだ。\n\nところが、汚らわしい厄介者どもが我らの神聖な土地に住み着いてしまった。Bristleback Interlopersの群れが墓所を荒らし回っている。奴らを追い払いたいが、若く力に満ちあふれていた時期もとうに過ぎ、年をとりすぎてしまった。\n\n奴らを力尽くで追い払わなくてはならない、{name}。", "Bristleback Interlopersを、我らの神聖な埋葬地から追い払わねばならない、{name}。", "よくやった。君はBristlebackたちに明確な意志を叩きつけたのだ。奴らが聖なる場所へ干渉しようなどと考えることは、もう二度とないだろう。", 0xfa1ec33f, 0x980ab5b3, 0xaa8194d7, 0xf565f7ef, 0x00b23859, "....." },
  [834] = { "砂漠の風", "Sacks of Suppliesを５つ回収してOrgrimmarの近くにいるRezlakに渡してください。", "俺はRezlak、Gazloweのとこの若いもんだ。ボスに言われて、ここDurotarのオークたちを手伝いに来たんだ。キャラバン以外は順調だったんだけどな。キャラバンだけはどうしても守りきれないんだよ！ おかげで俺の仕事がちょっと大変になってるってわけさ。\n\n前回の荷は――絶対に届くって約束されてたのに！――Dustwind harpiesにかっさらわれちまった。場所は……どこだったっけ……Razorwind Canyonだったか？\n\nあの物資がないと何も片付かないんだよ！ 大きな峡谷を南へたどっていけば、壁の西側と東側に切り込んだ谷間が見つかるはずだ。", "俺は自分の仕事にかけちゃ一流だよ、勘違いしないでくれ。でもこれはばかげてる! どうしろってんだ、砂のお城でも作れってのか?", "おう、まさしくそいつじゃないか！取り戻してくれたんだね。すごいや。この袋を運んでくれる奴が見つかり次第、すぐにでも仕事に戻れるよ。", 0x59e6f1e4, 0xd2235b13, 0xa26d70ed, 0x46f47b9e, 0x61a2af2d, "....." },
  [835] = { "キャラバンの安全確保", "Drygulch Ravineの近くにいるRezlakのためにDustwind Savageを12匹とDustwind Storm Witchを８匹殺してください。", "Gazloweはかつてこう言ったよ、『Rezlak。生きてく上で大事なことが一つある。首尾よくやりたきゃ自分ですることだ』\n\nすべてのキャラバンを守り抜くのは難しいね。だからこっちでできることをしようと思うんだ。Drygulch RavineはRazorwind Canyonの東側にある。そこのharpiesを皆殺しにしたら、そのルートは安全になると思うな。\n\nもちろんも一つGazloweは言ってたよ、『人はただでは動かない』。さてそういうことで助けてくんない、{name}？", "うちのボスのGazloweみたいな奴からは想像できないだろうけど、あの人はいつも事情をよく分かってたみたいでね。「大きな一歩を踏み出すのを恐れるな」ってさ。\n\nこっちが何か手を打たなきゃ、Harpiesは俺たちにちょっかいを出し続けるし、隊商も襲われ続ける、だろ?", "これでharpiesどもがキャラバンの邪魔をしなくなると思うと、やっと一息つけるよ。ちょうどいいタイミングだよ。次の荷と一緒に何か面白いおもちゃが送られてくるって耳にしたんだ！\n\nなかなか腕が立つね、{name}。Ratchetにいるボスに会いに行くべきだよ。仕事を回してくれるよ。\n\nああ、心配しないでよ。御礼を渡すのを忘れてはないからね。", 0xe6fd4a95, 0x888daed9, 0xd1d3c2b0, 0x27250f04, 0x8c848b09, "....." },
  [836] = { "OOX-09/HL を救出せよ!", "OOX-09/HL を Overlook Cliff の先の海岸線まで護衛し、Booty Bay にいる Oglethorpe Obnoticus に報告する。", "ノームの声が再びロボットから聞こえてくる。\n\n「OOX-09/HLを開けた安全な場所へ移さなければならない。そこで長い離陸手順を始められる。光学迷彩は内蔵されているが、再び動かせるようにするには、こちらで時間が必要だ。ロボットを今の場所から……そうだな、Overlook Cliffの向こうの海岸まで護衛してくれ！そこなら準備を整えるのに申し分なく、時間も十分だ！」\n\n「無事に海岸まで護衛したら、Booty Bayで私に話しかけてくれ！Oglethorpe Obnoticus、以上！」", nil, "おお、あなた様は OOX-09/HL の救い主です! あなた様のご支援には感謝の申し上げようもございません! 自動誘導ロボットシリーズには更に改良が必要ですが、修理していただいたおかげで、高額な製造コストにも等しい、余計な再構築をする膨大な時間を節約することができました!どうぞ、この中からお好きな物を選んで下さい。寛大なご支援に改めてお礼申し上げます、{name}。あなた様は我がロボットたちと私の恩人です!", 0x26dc1b96, 0xe5aa06ff, 0x1af73e68, nil, 0xfeab8db8, "...m." },
  [837] = { "侵害", "Razor HillのGar'ThokのためにRazormane Quilboarを４匹と、Razormane Scoutを４匹、Razormane Dustrunnerを４匹、Razormane Battleguardを４匹倒してください。", "われらがここについたとき、Razormane quilboarは多くの土地を占有しわれらにとって厄介な存在であった。努力の末に多くの地域から奴らを追い払った。しかしいくつかの場所ではそのままとなっている。\n\nしかしながらもはや時間切れだ。自衛のためには、我らの国にRazormaneが存在することは許されない。奴らの宿営地がここの西にある。大きないばらを探せば奴らもそこにいるだろう。今Durotarから奴らを追い払う。いずれはKalimdor大陸からもな。", "奴らにある程度の知性と組織力があるとはいえ、quilboarがKalimdorでこれほど多くの土地を奪い、保持できたことには、いつも驚かされる。私が思っているより狡猾な敵なのかもしれんな……", "Quilboarどもがねぐらから追い出され、建物も火に包まれたとの知らせを伝えるとしよう。RazormaneのDurotarからの除去が我らの新しい母国の境界の防衛を完全に近づけるだろう。", 0x53e8500c, 0x68b41137, 0x0b4e1318, 0x86c351c6, 0xca60d2cb, "....." },
  [838] = { "屍術師の学舎Scholomance", "Western PlaguelandsのBulwarkにいるApothecary Dithersと話して下さい。", "Caer Darrowの島にはScholomanceがある。Scourgeの拠点となっている学び舎だ。我らの敵はその中に棲み、力を強める研究を思うままに続けている。扉が行く手を阻み、どれほど試みても、正しい鍵なしには中へ入れないのだ。\n\nApothecary DithersはScholomanceに詳しく、鍵を手に入れる考えを持っている。君は物事をやり遂げられる者として、私にその価値を示してくれた。この任務を君に託そう。この件について彼と話してくれ。", nil, "そうだ、{class}、鍵の件で信頼できるのは君かもしれんとHigh Executorが言っていた。私は最近の研究のかなりの部分をScholomanceに費やしてきた。正面の扉を好きなときに通れるものを手に入れる方法を、私は知っていると思う。\n\nこの務めは容易ではないが、この手の務めが容易であることなど滅多にない。君はそれを事実として承知している手合いに、間違いなく見える。", 0xae1cd677, 0x52ffab65, 0x1b9ad892, nil, 0xd57607b0, "...m." },
  [840] = { "Horde軍は兵士を求む", "Razor Hillから西に伸びる道を行き橋を越えるとBarrensです。\n\n橋の向こうにあるオークの前哨基地へ行ってください。\n\nBarrens outpostのKargal Battlescarに入隊申請書を渡してください。", "ふむ、ちょっとは成長したようだな。\n\n聞け、わが友KargalがBarrensにおける任務を行うため何人かの新兵を募集している。お前はHordeの役に立ちたがっているそうだな。よし、好機到来だ。\n\nこのRecruitment letterをKargalに渡して、サインをしてもらうといい。", "何の用だ、若造? 新兵の志願で来たのでないなら、お前に構っている暇はない。", "ああ、Takrinの紹介か？彼は優秀なスカウトだよ。彼なしでは確実な仕事はできん。\n\n入隊申請書にサインするとしよう。しかし人手を必要としてたのはCrossroadsだよ。", 0x78c37e48, 0xd392b70b, 0xd4cb8337, 0xe87fe0e8, 0x6ab997b5, "....." },
  [842] = { "Crossroadsは兵士を求む", "KargalのいるFar Watch Outpostから西に伸びる道を進んでください。\n\nＴ字路に着いたら、左に曲がり南へ進んでください。\n\nCrossroadsの中の交差点にいるSergra Darkthornを見つけ出してください。", "この署名入りの募集状をCrossroadsへ持って行け。\n\nあそこの責任者はSergra Darkthornだ、忌々しい女め。口うるさいシャーマンで、何か役に立つことをやらせる前に、さんざん言いくるめて頭をぐるぐるにさせてくる。Thrallはあいつが特別な存在だと信じ込んでいるが、俺はどうだかな。\n\nまあ、自分で判断するしかないな、小僧……", "おやおや、これは何だ? Kargalは俺にもう一人新兵をよこすに値すると判断したのか?", "よし、{name}。Hordeで食い扶持を稼ぎたいのか？ここにはやることが山ほどある。よく聞いて、言われたとおりにやれ。\n\nHordeでは女も男と対等だと定められている。私を少しでも軽んじる者には本当の痛みを教えてやるが、自ら先頭に立って前へ進む者なら歓迎だ。そういう者が増えるのは喜ばしいことだ。", 0x0bacb2c9, 0x8da991ec, 0xc91cd247, 0x843fd0d3, 0xd77c8ad8, ".....", nil, nil, nil, nil, 0xbdf06a0d },
  [843] = { "Gannの奪還", "Gann Stonespireは、Bael'dun Excavator15人とBael'dun Foremen5人を殺すよう望んでいます。\n\nKhazgorm's JournalをGann Stonespireに渡して下さい。", "私はこの道を一人寂しく歩き回っている。\n\nBael Modanのドワーフどもはこの地に敬意を払わないんだ。うるさい機械が丘を切り崩すにつれて、恐ろしい爆発が地面の奥深くまで穴を穿っている。ここはかつて我が部族の故郷で、生活の糧を得られる場所だった。そんな故郷も、今では壊し屋のドワーフどもでいっぱいになってしまった。\n\n外交で解決しようという試みも、失敗に終わった。もう、思い切った手段に訴える時がきたんだ。\n\nBael Modan掘削地からドワーフを力尽くで追い払って、奴らのリーダー、Prospector Khazgormの日誌を持ってきて欲しい。", "Bael Modanのドワーフどもがやって来た時、多くの罪なきトーレンが命を落とすか、先祖代々の生まれ故郷を追われた。我が土地を取り戻さねばならん!", "Khazgormの奴は自業自得だ。あの馬鹿には、悪いことをしただなんて思わないね。あいつはここの不届き者だったんだ。\n\nあいつの死は、我々の暮らしを崩壊させ脅かす者すべてに対する警告になるだろうよ。\n\nちょっと待っててくれ。ドワーフの日誌を調べるから……", 0x5bec56d0, 0x794de9e0, 0x0fe7d066, 0xb020102d, 0x98de05b4, "....." },
  [844] = { "Plainstriderの脅威", "Plainstrider Beak 7つを集めて、CrossroadsのSergra Darkthornに渡して下さい。", "最初の獲物は簡単だ。\n\n東にいるplainstridersは、我々の食物供給を侵略していて、迷惑になっている。\n\nplainstridersを打ち負かして、彼らのくちばしを私に持ってきてくれ。", "plainstrider beaksは集めたか?", "上出来だ、{name}。plainstriderがいなくなれば、補給線を保つのもずっと楽になる。Barrensで少しは技を覚えたことを願うぞ。次の獲物は、plainstriderよりもう少し血の気が多いからな……", 0x683b72cb, 0xd1edb7af, 0x64402915, 0x2b051ab1, 0xa5c89360, "....." },
  [845] = { "Zhevra", "Zhevra Runnerを殺してZhevra Hooves 4つを集め、CrossroadsのSergra Darkthornに渡して下さい。", "zhevraはBarrensで最も獰猛な獣というわけではないが、plainstriderよりは少しばかり手ごわい。心配するな――いずれもっと大きな獲物に向かわせてやるが、今のところは、もう少し牙を磨いたほうがいいだろう。\n\n北と南でzhevraを狩って、そのひづめを集めてこい。それを持ってきたら、次はもっと手ごわい相手に向かわせてやるかもしれん。", "zhevraはどれだけ仕留めた?", "悪くない、{name}。zhevraは脚に強い力を秘めている。奴らの鋭い蹴りを食らえば、トーレンでさえ尻もちをつくほどだ！\n\nお前にもなかなかの力があるようだな。本物の試練に挑む覚悟はできているか？", 0x248a686f, 0x39699e5e, 0x936818e8, 0xbd0060bc, 0xa3a56f4f, "....." },
  [846] = { "Gannの復讐", "Gann Stonespireは、vial of Nitroglycerin・bundle of Wood Pulp・sample of Sodium Nitrateをそれぞれ6つずつ持ってくるよう求めています。", "あの探鉱者が爆薬に頼り、うるさい乗り物で地面を切り崩しているのは明らかだ。すぐにも新しい現場監督が引き継ぎに来るだろうね。\n\nドワーフどもには、自分自身で使っている薬を味わってもらいたいんだ。この設計図によると、nitroglycerinとwood pulpとsodium nitrateを混ぜ合わせれば、爆薬が作れるみたいだ。あの砦にいるライフル銃兵と兵士と将校が材料を持っているよ。\n\n材料を集めて、私のところへ持ってきてくれ。ドワーフ連中が忘れられないような爆薬を作ってやるぞ!", "戻ったようだな、{name}。\n\nKhazgormの死で我が先祖の地での発掘は多少遅れるかもしれんが、破壊が完全に終わるわけでは決してない。\n\nKeep at Bael Modanは増大する軍事的脅威だ。発掘現場を守るために建てられたが、今や攻撃に出る構えも整っている。\n\n頼んだ材料を持ってきたのなら、Barrensでの行いを性急なドワーフどもに考え直させるだけの爆薬を作ってやれる。", "{class}、君が本当に熱心だってことが分かるよ。\n\nきっと、すぐにでもドワーフどもにお似合いの驚くようなことができるぞ。", 0x66412c95, 0x0d3d68a3, 0x01ba4a8d, 0x1b49cb26, 0x588a2555, "....." },
  [847] = { "Raptorの狡猾さ", "Tor'ganと話して下さい。", "この……この力は……。これがTor'ganが私に見せようとしたシャーマンの力なのか？ 正直、興味深い。Tor'ganに伝えてくれ、私を納得させたとな……今のところは。彼の言い分に耳を傾けるとしよう。", nil, "魔法の効果が切れたら、Gor'mulと話をしよう。Gor'mulを生者の世界へ連れ戻す手助けをしてくれて、感謝する。きっと彼もお前に深く感謝していることだろう。", 0x185d70c3, 0x445ba750, 0xa30328b8, nil, 0x1bbe67d4, "...m." },
  [848] = { "Fungal Spores", "CrossroadsのApothecary HelbrimにFungal Spores4つを持っていきましょう。", "Barrensのオアシスには、神秘がある。その水からは、生命エネルギーが流れ出し、それを飲んだ獣や植物に活力を与える。\n\n活力を与え、変化する。\n\nオアシスの近くに育つキノコの胞子は、我々Lordaeronの薬剤師が注目する特徴をもつらしい。\n\nその胞子を持ってきてくれれば、感謝するよ。", "sporesは持っているか、{name}? Thunder Bluffにいる仲間に送らねばならない調合薬があって、それにsporesが必要なのだ……", "ああ、いいね。良い標本だな。効力が強い。\n\n私はForsakenだ。我々Forsakenは契約を重んじる。これは君への報酬だ、{name}。", 0xc3123519, 0x2e68d5c7, 0x797cda26, 0xd31a5bcf, 0xd9b9e642, "....." },
  [849] = { "Gannの復讐", "Bael Modanの飛行機を破壊して、Gann Stonespireのところへ戻って下さい。", "Khazgormの設計通りなら、爆薬の作り方に問題はないはずだ。\n\nああ、やってやろうじゃないか。\n\nさて{name}、君に大切な仕事を任せようと思ってる。この爆薬を持っていって、Bael Modanの飛行機を吹っ飛ばしてくれ。\n\nあの飛行機はこの掘削地の基幹施設の重要な一部であるだけじゃなく、兵器としても機能してるんだ。何より、あれは力の象徴であり、我が部族の思い出に対する侮辱だ。\n\nこの勇敢な仕事をやり遂げて、誇りにしたい。君も報われるだろうよ。", "ドワーフの飛行機械が破壊されれば、復讐の甘美な満足を味わえるだろう。", "よくやってくれた、{name}! トーレンの神聖な土地を守った者として、そして失われた部族の戦士として、君がThunder Bluffで尊敬されますように。", 0x66412c95, 0xbaa793c0, 0xa58e30a0, 0x28d6b809, 0x1f40bd4d, "....." },
  [850] = { "Kolkar族の指導者たち", "Barak's HeadをCrossroadsの西にいるRegthar Deathgateに渡して下さい。", "centaurどもは長年トーレンを悩ませてきた。最近じゃ、BarrensのKolkar centaurは真の脅威となるほど増大した。本来なら各地のcentaurはまとまりのある奴らではないんだが、新しい指導者が現れてな。まとめあげたんだ。\n\n我々の領地を保つには、centaurの指導者たちを殺さなくてはならん。\n\nBarak Kodobaneの首を持ってきてくれ。奴は北のForgotten Poolsの近くで野営している。\n\n奴を倒したら、戻ってくるんだぞ。", "やあ、{name}。Barak's Headは持ってきてくれたか?", "よくやってくれた、{name}。centaurは粗野で粗暴な生物だが、知恵を持ち、人を率いるだけの先見の明を持ち合わせているのがいくらかいる。そいつらが一番危険なんだ。\n\nBarakもそういったcentaurだった。こいつが死んだのは良いことだぞ。", 0x998b165b, 0x6a15fed3, 0x01ef16f2, 0x12beec59, 0xd9616ab0, "....." },
  [851] = { "Verog the Dervish", "Verog's HeadをCrossroadsの西にいるRegthar Deathgateに渡して下さい。", "Verog the DervishというcentaurはBarrensを歩き回っていてな、見つけるのは難しいだろう。だが、奴は南東のStagnant Oasisにある指揮用天幕を拠点にしている。そこから奴を引きずり出すことは出来よう。\n\n南東のStagnant Oasisに行き、指揮用天幕の近くにいるcentaurを攻撃するんだ。危険だろうけれども、充分殺せば奴らは危険を知らせるはずだ。そうすれば、Verogはやって来る。\n\n奴の首を持ってきてくれ。Barak Kodobaneのと一緒に並べてやるんだ。", "Verogは見つけたか、{name}?", "素晴らしい。君のおかげでcentaurどもは大混乱を起こしているに違いない。……Stagnant Oasis近くでの活動に我々のガードが気が付いたんだが、それも恐らく君のおかげだ。\n\nこの行いを誇るべきだ、{name}。君には大変な勇気がある。", 0x93dab5dc, 0xa038b95d, 0x215b556f, 0x4d4ec67a, 0x8f442ada, "....." },
  [852] = { "Hezrul Bloodmark", "Hezrul's HeadをCrossroadsの西にいるRegthar Deathgateに渡して下さい。", "Hezrul BloodmarkはBarrensにいるKolkar centaurの族長だ。Hezrulは気性が荒く、残忍で狡猾なんだ。奴を打ち倒せば、Kolkar族は分裂してバラバラになり、脅威も激減するだろう。\n\nだから、Hezrulを殺してくれ。BarakやVerogと同じように、Hezrul's Headを持ってきてくれ。\n\n奴は南のLushwater Oasisにいる一族を率いている。", "Hezrulは倒したか、{name}?", "素晴らしい、{name}。centaurは訓練されてもいないし、我々オークのように怒りを集約するなんてこともできないのだが、それでも凄まじくてな。あいつらを倒したことで、君の武勇は証明されたんだ。", 0xd41b7348, 0x1861eeb5, 0x752c7855, 0x0df82dda, 0x60d7374e, "....." },
  [853] = { "Apothecary Zamah", "制限時間内に、Thunder BluffのApothecary ZamahのところへRendered Sporesを持って行って下さい。", "君が持ってきてくれた胞子を乳剤に加工したんだ。これを仲間のApothecary Zamahへすぐ送らなきゃならない。もし運んでくれたら、彼女が大量の薬剤の中から何か品をくれると思う。\n\nThunder Bluffにいるシャーマンたちの真下にある洞窟、Pools of Visionに彼女はいるよ。その洞窟へ行く道はうまく隠れているけど、Spirit Riseにあるから見つけられるはずだ。\n\n急いでくれよ。この乳剤の効果は少しの時間しかもたない。だから、効果が切れる前にまた封をして処理しなきゃならないんだ。", "Apothecary Helbrimから何か預かってきたのか?", "あら、Helbrimが集めてたBarrensの胞子。これを届けるのにあなたの助けを得たのですね。いいことだわ。\n\nそれに乳剤もまだ効果をたもってる。あなたは大急ぎで届けてくれたに違いないわ。さすがですね、{class}。", 0xe9931e98, 0xadbbfb8e, 0xb9f2e008, 0xfa8cd725, 0xba92a449, "....." },
  [854] = { "Crossroadsへの旅", "BarrensのCrossroadsにいるThorkと話してください。", "若き{class}、あなたが来るのを予感していました。でも、もう駆け出しなどではありません。\n\nこの地の奥深くへと分け入っていく時なのだと思います。あなたは大きな事をする運命にあるのが感じられます。\n\nCrossroadsへ行ってください。\n\n私たちの生活に深く関わり始めたオークたちは、助けを必要としています。\n\nこの道をまっすぐ東へ進んで、分かれ道で北へ向かうとCrossroadsに着きます。Thorkはその壁の中にいます。彼はEarthmotherの祝福を持つ者です。", nil, "はるばるThunder Bluffから、我らを助けるためにより多くの{race}の協力者が来てくれてよかった。今一度、歓迎するよ。", 0xeac1fba3, 0xb2e3771c, 0xeb69f905, nil, 0xb15720f1, "...m." },
  [855] = { "Centaur Bracers", "Crossroadsの西にいるRegthar DeathgateにCentaur Bracerを15個渡して下さい。", "Barrensを領土だと主張するHordeにとって、Kolkar族は脅威だ。奴らの群れを減らさなくてはならん。そんなわけで、あんたにうってつけの賞金稼ぎの仕事がある。\n\nKolkarの縄張りの中で、戦士を殺してcentaur bracersを集めてほしい。小手を山ほど持ってきたら、Hordeからたんまり褒賞をやろう。", "狩りの具合はどうだ、{name}?", "見事だ。生き残りのcentaurどもに恐怖を叩き込んだはずだ、{name}。もし奴らに分別があるなら、これからは大人しくして、進攻もやめることだろうよ。\n\nだが奴らはそうしないだろうし、不幸なことだな。\n\n不幸だな……彼らにとっては。", 0x10ccc226, 0x914779ba, 0x96c4ff46, 0xcc975615, 0x9b2672c0, "....." },
  [857] = { "Tear of the Moons", "Feegly the ExiledはTear of the Moonsを取り戻すよう求めています。", "あの力は俺のもんだ! まさしくこの手にあった! だから返してくれ! 返せ!\n\n汚い穴掘り人どもめが、あれを掘り当てた……あれはとても美しい。Tear of the Moonsこそ、Bael Modanで成し遂げた初めての大発見なんだ。\n\nあれは俺が持つべきものだ! 俺のもんだ!\n\nあれがもたらす力に、General Twinbraidが嫉妬しやがったんだ。あいつ、砦にあれをしまい込みやがった。あれを呪われた物だと言いやがったんだ、あいつ!　馬鹿野郎が!\n\n他の奴らもあれを欲しがってた、だから止めなきゃなんねえ! 鬼畜野郎Twinbraidが俺を追い払ったんだ。\n\n今返してくれ! 返せと言ってるんだ!", "Tear of the Moonsはどこだ? 今すぐ必要なんだ! 言うまでもないだろう!", "ついに、力がまた俺のもんになった!　俺のもんだ!", 0xd61e6da0, 0xece78ab3, 0x5ea4911b, 0x03264142, 0x659e8bb7, "....." },
  [858] = { "起動", "Ignition Keyを入手し、Wizzlecrankに渡して下さい。", "Sputtervalveが君を寄越してくれたんじゃないのか? 今困ってるんだよ。シュレッダーの輸送柱を解除するのに鍵が必要だって知らないまま、乗り込んじゃったんだよ。別のシュレッダー運転手が大丈夫かって聞いてきたんで、パニックなんだ! 鍵を無くしたって伝えるかわりに、何かの機械の問題だって言っといた。\n\nオレたち、大急ぎでここから逃げ出さなきゃ! やぐらのてっぺんにある制御室にあがってくれ。監督者が、このシュレッダーを動かす鍵を持ってるはずだよ。\n\n手を貸してくれ!", "急げ、誰かに怪しまれる前にここから逃げ出さないと!", "おう、まさしくオレの求めてた鍵だな。オレの知ってる動かし方でいいか確認させてくれ……\n\nうーん……回転制御……この制御装置は速度と安定性……細かいアーム動作の調整、と。これ見ろよ! Venture Companyがオレたちよりもずっと優れた設計ができるなんて信じられない。これはRatchetへ持って帰らなきゃ!", 0x18e364df, 0xfd656f2e, 0xc1e7e3e9, 0xb25128ee, 0xa8725124, "....." },
  [860] = { "Sergra Darkthorn", "CrossroadsにいるSergra Darkthornと話して下さい。", "もし狩人の道を歩みたいと望むなら、君の旅はBarrensへ向かっていく。Barrensの獣は意志が強く、獰猛だ。あそこでは狩りについて多くを学べることだろうし、君の魂も成長する。\n\nSergra Darkthornと話をするんだ。Barrensでの初めての指導者となってくれるはずだよ。\n\nSergraはCrossroadsにいる。彼女の所へ行くには、Bloodhoof Villageを出て東へ向かい、Barrensに入って、分かれ道で北上するんだ。旅のあいだは気をつけるんだぞ。準備不足だったり、不用心だったりするとBarrensは非常に危険なところだからな。", nil, "Barrensで狩りをしたいですって?\n\nあなたの目は熱心で、そして若い。この乾いた平原に獲物を追って目を凝らしたりは、まだしていない。\n\nでも心配しなくていいわ。私たちがあなたの体と心を強靱にしてあげる。そして、獲物を見つけたり殺したりするだけでない狩りというものを教えてあげる。\n\n準備しなさい。旅は始まったわ、今。", 0x3c4cd152, 0x9d903e4b, 0x2ca0b448, nil, 0xd7d00470, "...m." },
  [861] = { "ハンターの道", "Flatland Prowler Clawを4つ集め、Thunder BluffのMelor Stonehoofに渡して下さい。", "君は探検したくてたまらなそうだね。私もかつては君と同じように、あちこち歩き回りたいと強く思っていたものだ……\n\n放浪し、狩りをする。狩りとは、Taurenにとって最も大きな名誉なんだ。\n\nもし本当に狩人の道を歩んでいきたいと望むなら、Melor Stonehoofがその道を示してくれる。彼は、Thunder BluffのHunter's Riseにいるよ。\n\nMulgoreにいるflatland prowlerの爪を彼に持って行き、その腕前と強い意志を見せろ。奴らはしぶとく、狡猾な生き物だ……狩人の道を歩む駆け出しの{class}にはぴったりの獲物だ。", "ごきげんよう。そなたの纏う気配が多くを物語っている。我らの間に用件があるのかな、そなたと我に?", "Skorn Whitecloudは賢明なトーレンだ。彼は何年も何年も狩りをして、体は衰えてはいるが、魂は炎のように燃えさかっている。我々は、彼がいることを誇りに思っているよ。\n\nもしSkornが君を私の元へよこしたのなら、君も同じ狩人の魂を持っているのだろう。それに、この爪を集めてきたことが、めきめきと上達している腕前を示している。\n\nこの道を歩む準備が出来ているね。", 0xccff1f61, 0xec804e9e, 0x79313340, 0x0d1a0780, 0xbc9792ef, "....." },
  [862] = { "Dig Rat Stew", "Crossroads東のGrubにDig Rats8匹を持っていってください。", "あんたみたいな{class}は、Barrensの方じゃえらく腹が減るに違いないね。俺もだ。俺は一日中ハラペコだよ。\n\nじゃあこうしよう、素晴らしいシチューを作ってやろう。それには何匹かdig ratsが必要なんだ。\n\nBael Modanの不潔なドワーフどもが、みんなの好きなごちそうにたかってるようだ。Bael Modanへ南下して、dig ratsを何匹か持ち帰ってきてくれ。\n\nネズミどもを始末してくるまでは、熟練の冒険者とは呼べないよ。ほら行け!", "dig ratsはもう十分ぶっ叩いたかい、{name}?", "このネズミ、まだすごく……すごく……臭いから、まだ食べたくないんだよね。本当の香りを引き出すのには、何週間か腐らせるのがいいんだよねえ。でも、あんたは待ち切れなさそうだな。\n\nDig Rat Stewを作ってやるよ。ああ、そうしよう。\n\nお待ちどお!", 0xbca7d0f0, 0x58ffc2c1, 0x785ad009, 0xc5376bbd, 0xae431bb6, "....." },
  [863] = { "脱出", "RatchetにいるSputtervalveのところへ行く道の途中まで、Wizzlecrankとstolen goblin shredderを護衛して下さい。", "行けば分かると思う……そんなに難しくはないさ。ここにボタンが数個、それとレバーなどなど……さて、準備はいいかい?", "何かご用ですか?", "壊れたシュレッダーの試作機から、何か価値のあるものが回収できるといいんだが……もう時間がないんだ！すぐにWizzlecrankのいる場所へ回収班を送り出すよ。\n\nおっと、手間をかけさせたお礼に、何か渡しておこう。", 0x437cedda, 0x71ada0fe, 0x646e9b5d, 0xf30770a2, 0x6d0bbb0f, "....." },
  [864] = { "Apothecary Zingeの元へ", "Sealed Field Testing KitをUndercityのApothecary Zingeのところへ持って行って下さい。", "「ほらよ、動力源は無事に外したし、データも保存してある。じゃ、気をつけて帰りな。その怪しげな科学実験とやらがうまくいったならいいけどね」\n\nゴブリンはあなたに背を向け、Gadgetzan Water Companyの要求への対応に戻った。あなたは帰りの旅に備えて、封をされた検査キットをしっかりと固定する。Undercityへ戻るのだ。そこではApothecary Zingeが、あなたと封印された野外検査キットを待っている。", "おかえり。少なくとも、sealed testing kitを持って戻ってきたのならおかえりと言おう。そうでないなら、お前のまったくの無能さには気づかないふりをして、命じられた通りに私の任務を果たすまで、怒りをぶつけるのは控えてやる。", "このデータはすぐに解析しよう。Keeverの狂気も、結局は私の天才の証となるかもしれん。\n\nさて君だが……君は私にとって有用だ。有用であり続ける者には、私は十分に報いる。この品と、この金、そして何より私の感謝を受け取ってくれ。\n\n時々また顔を出してくれ――この計画での我々の協力は、まだ終わりではないと踏んでいる。", 0xd3e176c3, 0x70cfd192, 0x6c402776, 0x2721c6a4, 0x632bd805, "....." },
  [865] = { "Raptorの角", "Sunscale ScytheclawからIntact Raptor Hornを5つ集め、RatchetのMebok Mizzyrixに渡して下さい。", "Barrensのraptorは他の土地にいるのより賢いんだ。知能のすべては奴らの角に隠されてるんじゃないかと思うんだ!\n\nもしそうなら、角を磨り潰して粉にして、「頭の良くなる飲み物」を作るのに使えるよ。そいつは高値で売れるんだ!!!\n\nで、手伝ってくれるよね。sunscale scytheclawから綺麗な角を取ってきてほしいんだ。raptorたちは南Barrensをうろうろしてるよ。それとAshenvale Forestの境界に近い北Barrensにもいるよ。", "hornsは手に入れたか、{name}? あれで俺は大儲けできるぞ!", "すごいな、手に入ったんだ! じゃあ磨り潰してワインと混ぜて……。", 0x1c567a17, 0x3fc5f7ab, 0x7d0b4af6, 0x849a25eb, 0xa8f3ad03, "....." },
  [866] = { "根のサンプル", "Root Samplesを$N1個、RatchetのMebok Mizzyrixのところへ持って行って下さい。", "Barrensの薬草は他の土地のものとは少し違う。Barrensの薬草の効能はほぼ同じだが、ここのオアシスの水が植物を変化させたおかげで、ほんの僅かに違っているんだ。\n\nオレはその違いを研究したいんだ……利用価値があるかどうか調べるためにな!\n\nもしHerbalismの腕があるなら、Barrensで見つかる薬草から根っこのサンプルをとってきてくれ。他の地域の薬草と比較できるように、持ってきてほしいんだ。", "やあ、{name}。root samplesは手に入れたかい?", "いいねいいね、すごくいいよ! この根っこで検査サンプルを増やして、研究するんだ。この根っこから新しい効能を見つけたいねえ。隠された、価値ある効能をね……!\n\nそれとご心配無く……もし発見したら、あんたにゃ最初に知らせるよ。もっと集めてくれる奴が必要だからな!", 0x70eb75ac, 0x03b25054, 0x8786eff9, 0x068cbe55, 0xf9891d3a, "....." },
  [867] = { "Harpy襲撃者", "Witchwing talonsを8個集め、CrossroadsのDarsok Swiftdaggerに渡して下さい。", "忌々しいharpyどもは、我々の補給部隊を長いこと侵略してきた。いまこそ、やつらの喉を切り裂いて数を減らしてやるときだ。\n\n俺はやつらの巣に探りを入れ、誰が指揮を取ってるのか調べた。我々のできる最良の作戦は、やつらの指揮系統を破壊することだ。\n\n慎重にはじめよう。北西に住むWitchwing HarpiesとWitchwing RoguefeathersからWitchwing talonsを８つ手に入れてきてくれ。良い出だしになるだろう……", "もう十分切り刻んだか? どんどん切り刻んで戦利品を取ってこい。Witchwingの鉤爪が8本欲しい。", "おお、こりゃいい。本当にいい……よくやった、{name}。これからの働きを見るのが楽しみだ。", 0x663d72ca, 0x5cbdce59, 0x4d1ddd7f, 0x89ddc918, 0x3b507229, "....." },
  [868] = { "卵狩り", "Silithid Egg12個とDigging ClawをCrossroadsのKorranに渡して下さい。", "やあ、{name}。私はOrgrimmarにいる主から、この土地を見張って、ここの出来事に注意するよう仰せつかってきたんだ。\n\n研究対象のひとつは、南にあるField of Giantsに見られる昆虫のような生物だ。我々はその生物のことをほとんど知らない。だから、できるだけ多くの発見をしたいんだ。どうも彼らは、通常の動物より頭脳を働かせているようなんだ。\n\nこのDigging Clawを持っていって、塚からいくつか卵を集めてきてくれ。でも、気をつけてくれよ。気が付かれたら、彼らは君を攻撃してくるだろうからね。", "見つけたeggsは慎重に扱ってくれ、{name}。割れちまったら、俺には何の役にも立たねえ。", "嬉しいよ、{name}。卵と、道具ね。よくやってくれた。\n\nそれから、報酬に……", 0x53341892, 0xe0f09771, 0x770df496, 0x0869f62f, 0xaad56485, "....." },
  [869] = { "Raptorの泥棒", "12個のRaptor HeadsをCrossroadsのGazrogに渡してください。", "最近、我々のガードタワーから積荷の銀貨が盗み出された・・・Crossroadsの警備隊のためのものだ。なんとしても取り戻したい。\n\n不思議なことに・・我々はある晩、盗みに入った泥棒の一人を捕まえたんだが・・・・raptorだったんだ！信じられるか？？\n\nなぜraptorが銀を欲しがるかわからんが・・そんなことはどうでもいい！\n\nやつらがまた、盗みを働かないように、始末したい・・。\n\nBarrensでやつらを狩ってくれ、そしてやつらの首を持ってきてくれ。", "headsは持ってるか、{name}?", "君はraptorたちを駆逐したようだな！\n\nありがとう、{name}。君は立派な{class}だな。", 0x99919f6b, 0x5dd97461, 0x697ca8ba, 0x1354c782, 0x69f68898, "....." },
  [870] = { "忘れられた泉", "調査結果をTonga Runetotemに報告してください。", "遠い昔、Barrensは命にあふれた緑豊かな地でした。しかし戦争と大災厄がこの地を荒れ狂い、大地を焦がして干からびた抜け殻を残したのです。それが物事の定めというものですが、私の心は悲しみに沈みます。\n\nしかしここ数年のうちに、Barrensには新たなオアシスが生まれ、命が息づき始めています。そして、我々ドルイドは、地の奥深くから何らかの力が地表へ漏れ出しているのを感じているのです。\n\nその源を見つけなければなりません。Crossroadsの北西にあるForgotten Poolsへ行き、その水の中に力の源を探して、ここへ戻ってきてください。", "Forgotten Poolsには行ってきたか、{name}? 何か見つかったか?", "ガスが湧き出している大地の裂け目を見つけたと？奇妙だ。これが我々の疑問への答えかもしれんが、まだ確かなことは言えん。\n\nだが、手がかりには違いない。それを見つけてくれたことに感謝する。", 0x050d62e3, 0x165ddbb2, 0x9c76fc51, 0x88633845, 0x18730fb7, "....." },
  [871] = { "崩壊させよ", "Razormane族のWater Seekersを8匹、Thornweaversを8匹、Huntersを3匹倒し、CrossroadsのThorkに報告しましょう。", "すべてのQuilboarsは、我々の敵だ、{name}。やつらは災いしかもたらさない。\n\nRazormane族は、我々の補給線を攻撃した。我々の不快感は終わるところを知らない。俺はやつらのリーダーを探している。しかし、そのときまでお前が不潔な豚男どもの力を削いでくれるのなら、それは我々の手助けになるだろう。\n\nDurotarに向かって北東に、大地から芽吹いた巨大なつるに囲まれた集落を見つけることができる。探せ、そして殺せ。", "この襲撃を止めるのに時間がかかればかかるほど、Crossroadsの人々に物資を届けるのが難しくなる。", "よくやったぞ、{name}。生意気なquilboarどもめ、Hordeの力を無視するべきでないとこれでようやく思い知ったろう。", 0xe58a1b32, 0xbcd27522, 0xf215e1d9, 0xe55301e3, 0x80850757, "....." },
  [872] = { "The Disruption Ends", "Razormane Geomancersを8匹、Razormane Defendersを8匹、そしてKreenig Snarlsnoutを殺して下さい。\n\nそしてKreenig Snarlsnout's TuskをCrossroadsのThorkに渡して下さい。", "偵察の一人が、Durotarから来たキャラバンへの攻撃を目撃したのだ、{name}。犯人は、quilboarsのRazormaneという部族だ。quilboarsの中の一匹Kreenig Snarlsnoutが襲撃の指揮を取っている。ここから北東、Durotarの南で見かけたようだ。危険な兆候が続くようなら、Kreenigに死んでもらうしかない。\n\n攻撃を確実にやめさせるため、追い討ちをかけようと思う。Kreenigを殺し、同じように奴らももっと殺してほしい。そして、奴の牙を手に入れたら、持って帰ってきてくれ。", "頭目の首を落とせば、混乱が起きるものだ、{name}。この教訓をよく覚えておけ。いずれ役に立つだろう。\n\n指揮を失ったboarsはうろたえ、我らはBarrensを取り戻せる。", "よくやった、{name}。Kreenigの死により、我々のキャラバンへの攻撃は確実に減るだろう。\n\n君らの一族は、君がいることを誇らしく思うだろうね。", 0x2dfad677, 0x86bafe37, 0x6671b2df, 0x8cf286c6, 0x981f6e19, "....." },
  [873] = { "Isha Awak", "Heart of Isha AwakをMahren Skyseerに渡して下さい。", "雄大なるIsha Awakはこの海の君主。偉大なのは、その力と厳かな誇り。この海岸にいる人間は、たくさんの仲間を食べられたせいで、Isha Awakを恐れているのよ。\n\nでも私は恐れていない。ここにIsha Awakがいることに感謝しているのよ。彼は挑むに値する、名誉ある獲物だからね。\n\nもし準備がよければ、泳ぎ出て、深海にIsha Awakを探しなさい。\n\n彼の魂は心臓に宿っている。その鼓動を聞くことは、あなたの運命を知ることなのよ。", "水を恐れるな、{race}。", "今あなたはIsha Awakとひとつになっているわ、{name}。魂はあなたとともにある。彼は目に宿っているのね……\n\nその目は、いつか、物を見抜くようになるでしょう。", 0x75825093, 0x9e928276, 0xd7808914, 0x038b0db1, 0xac941e2b, "....." },
  [874] = { "Mahren Skyseer", "Mahren Skyseerと話して下さい。", "君はBarrensの獣たちを狩ってきた。君の魂は強い。だが、狩人というものは常に準備していなくてはならん。真の狩人はどんな道でも獲物に忍び寄っていけるんだ。山々も沼地も、真の狩人を揺らがすことはできないだろう。\n\n海でさえも。\n\n私の家族、Mahrenを見つけるんだ。海岸沿いで強い海の獣を狩っている。道を進む君の師となるだろう。\n\nだが、彼女を探す時は気をつけるんだぞ。Barrensの海岸は人間に占領されているからな。", nil, "Jornがあなたを寄越したのね、そうでしょう? それじゃ、力量を示さなくてはならなかったのね。Jornの敬意を得られたのなら、私の敬意も同じように得られるわ。\n\n狩人の道をさらに踏みしめる準備はできた?", 0x7d6a1f65, 0x89e7019b, 0x773a4fa6, nil, 0x7b19f815, "...m.", nil, nil, 0xfbb5ad85, nil, nil },
  [875] = { "Harpyの副官", "Witchwing SlayerからHarpy Lieutenant Ringを6個集め、CrossroadsのDarsok Swiftdaggerに渡して下さい。", "ははは、{name}だ。また戻ってきたか。いいね、そうこなくちゃ。\n\n今度はDry Hillsでharpyの副官を暗殺してほしいんだ。副官になれるのはWitchwing Slayerだけだ。奴らが持ってる指輪で区別できる。嫌な連中だが、あの地域の下っ端を率いているんだ。副官を6人殺せば、奴らの一族に対する決定的な一撃になるはず。\n\n奴らが苦しみながら死ぬようにしてくれよ、{name}。Hordeに喧嘩を売った愚かさを、あの鳥女どもに思い知らせてやりたい。", "Harpy Lieutenant Ringsは6個手に入れたか? Hordeへの残忍な襲撃の報いとして、奴らに裁きを下さねばならん。", "上出来だ、友よ。君はHordeで出世すると思うよ。", 0x12f29ef9, 0xab320515, 0x35e1ffee, 0x96dfd3a4, 0xd390ae4e, "....." },
  [876] = { "Serena Bloodfeather", "Serena Bloodfeatherを討ち取り、首をCrossroadsのDarsok Swiftdaggerに渡して下さい。", "副官と下っ端相手によくやってくれたから、最後にもうひとつ頼まれてくれないか。\n\nSerena Bloodfeatherは、かなり前にRexxarが討伐したBloodfeatherというharpyの姉妹なんだ。どうやら、Hordeの隊商への攻撃は姉妹の死の復讐らしい。\n\nSerena Bloodfeatherの喉笛を掻き切って、首を持ってきてほしい。次に送り出す隊商にそれを取り付けたいんだ……harpyどもに色々考えさせてやるためにな。", "Serenaの首を見るまでは、何もやらんぞ。", "ハ! よくやった、{name}! とてもよくやってくれた……まさかこの仕事をやり遂げると思ってなかったが、君は素晴らしい喉切り魔だってことを証明したんだ。Harpyがはびこるのを抑える手助けをしてくれたことに、改めて礼を言うよ。これは君への報酬だ、大事に使ってくれ。", 0x3d86ef8c, 0xbeb8b687, 0xb8e4b9ee, 0x298feb2a, 0x2279a868, "....." },
  [877] = { "Stagnant Oasis", "Stagnant Oasisを調査した後、The CrossroadsにいるTongaのところへ戻ってください。", "君がForgotten Poolsで見つけたような亀裂は、Barrensの別のオアシスにもあるかもしれない。もしそうなら、亀裂はオアシスの命の源なんだと思う。\n\nこれを試さなくては。\n\nさ、この種を持って。この種は死んでいて成長できないんだけれど、南東にあるStagnant Oasisへ持って行ってほしい。そこに亀裂があったら、そこに種を置いて……観察するんだ。", "Stagnant Oasisには行ってきたか? その水の下に裂け目はあったか?", "君の発見はすごいよ!　君にあげた種は乾いて、死んでいたんだ。オアシスは無から生命を作り出すんだ!\n\nもっと研究しなきゃならないな……", 0xc199d9a2, 0x9257370a, 0x03931b18, 0x169e62dc, 0xcf16b2bb, "....." },
  [878] = { "部族抗争", "６体のBristleback Water Seekers、１２体のBristleback Thornweavers、１２体のBristleback Geomancersを殺し、BarrensのCamp TaurajoにいるMangletoothのところに戻ってください。", "お前はオレの敵を討たねばならん。<鼻を鳴らす>お前はBristlebackを弱らせて、MangletoothとRazormaneを助けねばならん。どちらの部族もとても霊的だ――大地とその力に結びついている。<鼻を鳴らす>それはあらゆることでオレたちに力を与える……とりわけ戦でな。\n\nThork<鼻を鳴らす>とHordeにこれほどの苦しみを与えているのが本当は誰なのか知りたければ、Mangletoothを助けろ！北にいるBristlebackの霊的指導者たちを襲え。奴らを弱らせ、Razormaneが奴らを倒してBarrensを支配できるようにしろ。", "Bristlebackの賢者どもを殺したら、Hordeのために<鼻を鳴らす>もっと情報をやろう、{race}。<鼻を鳴らす> それより一瞬たりとも早くはならん! Mangletoothは馬鹿ではない。", "そうだ、そうだ……喜びでいっぱいだ。やっと<鼻を鳴らす>Bristlebackがオレの部族の痛みを知ったのだからな、{race}。そう感じるべきなんだが、そう<鼻を鳴らす>はいかない。\n\nお前は自分の民を助け、民はお前を敬う。Mangletoothも自分の民を助けた。なのに奴らはどうする？ 背を向けるんだ。Mangletoothのことを忘れ、檻の中で朽ちるままにしておく！\n\n鉄格子の中に閉じ込められていても奴らを助けてやっているのに、誰一人オレを助けに寄こさない！", 0x836aed9c, 0x94f3701b, 0x53c0b5ba, 0xd1b70764, 0xb6191585, "....." },
  [879] = { "内部の裏切り者", "Nak・Kuz・Lok Orcbaneを殺し、その頭蓋骨をBarrensのCamp TaurajoにいるMangletoothに渡して下さい。", "私の部族の三人が、Hordeへの襲撃を率いるためにKraulから出てきた、{race}。<鼻を鳴らす> 奴らは冷酷で狡猾だ。奴らを倒せば、お前たちのCrossroads、いやBarrensのほとんどが平和を知ることになるだろう……<鼻を鳴らす> 少なくともRazormane族からはな。<鼻を鳴らす>\n\nお前が探すべきはNak、Kuz、そしてLok Orcbaneだ。奴らはBarrensのはるか南にいる。一人は呪文の使い手、もう一人は追跡者、そして奴らの頭目、Orcbaneと呼ばれる者は、<鼻を鳴らす> ウォリアーだ。奴らを殺せ、{race}。奴らが私を殺したように。", "狩りの具合はどうだ、{race}? <鼻を鳴らす>\n\nThorkは自分の民への襲撃を率いているのが誰か、真実を知っていると思っている。<鼻を鳴らす> だがお前が成功すれば、自分がどれほど間違っていたか思い知るだろう。\n\n我が死は避けられぬ。だがお前は我が敵に大きな痛手を与えた。だからMangletoothは何も悔いはない。<鼻を鳴らす>", "これでおしまいだな。「こんな風に終わればいい」とMangletoothは言いましたとさ。フン。あいつらめ、捨てられた檻の中のオレを、フン、置き去りにして立ち去るときに、フン、オレを確実に殺していくべきだったんだ。\n\nだが{race}、終わりにする前にもうひとつ仕事がある。", 0xabe2f634, 0xda62738d, 0xf3b992ae, 0x27a878f0, 0xa569522d, "....." },
  [880] = { "変異した存在", "Altered Snapjaw Shellを8つ、CrossroadsのTonga Runetotemに渡して下さい。", "君の発見は驚きだよ、{name}。オアシスは別のものに由来する性質を持っているに違いない。そうでなかったら、多分泉そのものの性質だ。\n\nオアシスの水を飲んでいる獣たちが、亀裂からどんな影響を受けているか知りたい。\n\nLushwaterとStagnant Oasesにいるoasis snapjawを狩ってくれ。調べたいから、甲羅を持ってきてほしいんだ。", "収集の具合はどうだ? shellsは手に入れたか?", "ありがとう、{name}。この地域の獣の研究をすると、地域そのもののことが分かってくるね。この甲羅が教えてくれることを調べてみようじゃないか。\n\n手助けへの感謝を受け取ってくれ……このお金は使えると思うよ。お金は自分には必要ないって分かったんだ。", 0x3ce01f92, 0x0767e054, 0x731ae9c5, 0x0218c1d5, 0x4a48aedf, "....." },
  [881] = { "Echeyakee", "Echeyakee's HideをCrossroadsにいるSergra Darkthornのところへ持って行ってください。", "Whitemist、トーレンの言葉ではEcheyakeeと呼ばれるそいつは、サバンナの猫どもの王だ。あまりに気配を殺して狩りをするので、大地に漂う薄く白い霧のようだと言われている。しかも獲物を仕留めるのがあまりに速く、獲物は恐れも痛みも感じる暇がない。\n\nトーレンは、やつは慈悲であり死でもあると言う。\n\nそれが本当かどうか、お前は知ることになる。今こそお前をEcheyakee狩りの道へ送り出すからだ。やつのねぐらはCrossroadsの北東、巨大なKodoの骨が散らばる中にある。\n\n行け。ねぐらに着いたらこの角笛を吹け。角笛を吹けば、やつは現れる。", "偉大なる猫がそなたを呼んでいる、{name}。", "お前はEcheyakeeを打ち倒した。奴の狩りの日々は終わったが……その魂はお前と共にある。奴はお前に、繊細さの中にある強さと、慈悲の中にある名誉を示してくれるだろう。\n\nお前の道はまだ長い、{class}。しっかりと歩んでいけることを願おう。", 0x8eaea284, 0x0758978b, 0x0689f2cb, 0xe0526099, 0x1b8589ca, "....." },
  [882] = { "Ishamuhale", "Ishamuhale's FangをCamp TaurajoにいるJornに渡して下さい。", "Ishamuhale、SpeartoothはBarrensのsunscale raptorの中で最も獰猛だ。Ishamuhaleは食べるための狩りも、運動のための狩りも決してしない。その狩りは、本能的な激情に基づくものなのだ。殺すことが本分だから、殺すんだ。\n\n君はIshamuhaleの本分を知るだろう、{name}。君の道は今、Ishamuhaleの鉤爪状の足跡を追っているからな。\n\n狩りを始めよう。まずは彼の好物の獲物、zhevraを殺して、Ratchetの北西にある枯れ木に死骸を持って行くんだ。Ishamuhaleはその死骸の臭いを嗅いで、つられてくるだろう。\n\nIshamuhaleがやって来るまでに準備しておくんだぞ。", "{name}、Ishamuhaleを打ち負かしたか?", "この牙など単なる証拠に過ぎない。だが、これは深い物を象徴しているんだ。\n\nIshamuhaleの力は君の中にある、{name}。節度をもってこれを使うことを祈る。これは君の義務だ。\n\nそして、君の名誉なんだ。", 0x574078d6, 0xdcecca63, 0x4339b639, 0xd7a1f327, 0x0249d5ae, "....." },
  [883] = { "Lakota'mani", "Hoof of Lakota'maniをCamp TaurajoのJornに渡して下さい。", "Hoof of Lakota'maniは、偉大なるkodoの強さの象徴です。", "{name}、そなたが近づいてきた時、その足取りに新たな力が見えた。教えてくれ――そなたの魂は偉大なるLakota'maniと出会ったのか?", "Lakota'maniは、我々の言葉で「Earthshaker」と呼ばれているんだ。彼の足音は雷鳴が集まったような音なんだ。今、彼は君とともにある。そしてその勇敢さも、君のものと混ざり合っているんだ。彼と共にあれば、君が立ち向かうことのできない争いなどありはしない。\n\n堂々と歩め、{name}。堂々と歩め、Earthshakerよ。", 0x8a0292b4, 0x154db736, 0x9c5704ae, 0x252b2af4, 0x5e74ae0d, "....." },
  [884] = { "Owatanka", "Owatanka's TailspikeをCamp TaurajoにいるJornに渡して下さい。", "触れると、Owatankaの尖った尾から火花が飛び散った。", "{name}、そなたの目の奥に新たな力がある! 力強きOwatankaと出会ったのであろう?", "thunder lizard Owatankaはトーレンに「Bluebolt」と呼ばれているんだ。体の大きさとは裏腹に、速さを備えているからね。昔稲妻がBlueboltを打ったとも、空の怒りから与えられたからとも言われていて、あの偉大なる獣の活力には限りが無い。\n\n彼の活力が{name}に流れますように。今や君はOwatankaと共に歩んでいるのだから。", 0x298c2ba2, 0xb83ea4ee, 0x9858e87a, 0x51bfdd6e, 0x82017096, "....." },
  [885] = { "Washte Pawne", "Washte Pawne's FeatherをCamp TaurajoのJorn Skyseerに渡して下さい。", "feather of Washte Pawneに触れるには、痛みが伴う。", "そなたの内に新たな決意がある、{name}。痛みから生まれた決意が……\n\nWashte Pawneの死という重荷を背負っているのか?", "あのthunderhawkはBarrensの珍しい獣なんだ。そして、その死は大いなる幸運か、大いなる災厄の前兆となることがある。\n\nだが、Taurahe語で「Spirit Biter」と呼ばれるWashte Pawneは、どちらも招かないかもしれないし……どちらも招くかもしれない。\n\n「Spirit Biter」を狩った時に感じた痛みは、大きな代償を元に大きな利益を得る者すべてが感じる痛み。君が感じた刺すような痛みは、後悔の痛みだ。\n\nだけど、分かるんだ。君ならこれを乗り越える。君は後悔が英知へ変わることを知っている。そして、英知は痛みを通り越え、力を与えてくれる。\n\n君は多くを学んできたんだ、{name}。", 0xcfbb9a34, 0x82aa0f1b, 0xe555fb49, 0x46451e74, 0xe53f8aad, "....." },
  [886] = { "Barrensのオアシス", "CrossroadsのTonga Runetotemと話して下さい。", "Thunder Bluffのドルイドたちは、Mulgoreの東、Barrensから奇妙な力が漏れ出しているのを感じている。\n\nその力の源を探るためにTonga Runetotemを遣わしたが、恐らく手助けを必要としていよう。\n\nBarrensへ行き、Tongaと話してほしい。Crossroadsにいるはずだ。Crossroadsへ行くには、Bloodhoof villageを出て、道を東に進む。Barrensに入ったら、分かれ道を北へ。そのまま北へ行けば、Crossroadsに着くだろう。\n\n道を外れないように気をつけるのだ、{name}。Barrensは過酷な土地だからな。", nil, "Thunder Bluffの同胞は賢明だ、若き{class}、君を寄越してくるとはね。Barrensの謎は私だけでは解けないんだ。\n\n君の助けがあれば、謎の答えも見つけられそうだよ。", 0x96d3bc63, 0xcc4a44bb, 0x754621de, nil, 0xe0891962, "...m." },
  [887] = { "Southsea Freebooters", "RatchetのGazloweのために、Southsea Brigand12人、Southsea Cannoneer6人を殺して下さい。", "Vice Admiral Grezzlikが、うちの交易船のためにもうちょっとまともに海の安全を守ってくれたらいいんだけどな。交易王たちがTrade Fleetsにあれだけの金を注ぎ込んでるってのに、海賊どもが好き勝手に暴れ回って、俺の船を襲っちゃ荷を盗んでいくのを見るとムカつくんだよ！\n\nSouthsea Freebootersがここのすぐ南にキャンプを張ったって聞いたんだ。あいつらには本当に手を焼いてるんだよ。Grezzlikが片付けてくれないなら、まあ、あんたがあいつらを追っ払うのを手伝ってくれるかもな。", "海賊の襲撃で失った儲けのことなんて考えたくもないのに、今度はうちの目の前に野営地を作りやがった? 手に負えなくなってきてるよ。Undermineが何とかしなきゃな。", "やあ君、お疲れ様。もう少し同じように働いてくれたら、心配しなきゃならない事がひとつ減るんだ。活動場所をどこかへ移すべきだと、奴らが確信してくれるといいんだが。\n\nところでさ、盗まれた積荷を取り戻すっていうちょっとした仕事があるんだ!", 0x66c9c41c, 0x69ce9e05, 0x7623fe2d, 0xd3e5fc1b, 0x9a1f5c52, "....." },
  [888] = { "盗まれた品", "RatchetのGazloweのために、Shipment of BootsとTelescopic Lensを取り戻して下さい。", "積荷を全部取り戻したいけど、そんなのできっこないって分かってる。でもまだ、持ってなきゃならない物がいくつかあるんだ!\n\n見ての通り、オレの観測所は準備万端だ。でも、2つのレンズのうち小さい方が必要なんだよ。Durotarからの隊商で第一便は届いたんだけど、第二便は船で運ばれるはずが、届かなかった。また、Booty BayのDrizzlikからの荷物を受け取ってないんだ!\n\n南の海賊野営地へ行って、もし出来たら積荷を見つけてきてくれ。", "俺の荷物は見つかったかい、{name}?", "この品が戻ってきてホッとしてるよ、{name}、君の助けには本当に感謝してる。知っての通り、オレの活動を手伝ってくれる、君みたいな{race}が必要なんだ。もし仕事を探しているなら、このGazloweがどれほど良く謝礼を支払ったか、忘れないでくれよな!", 0x64d599c7, 0x739fc2b0, 0x0b53afc7, 0x23319024, 0xe9cacd44, "....." },
  [889] = { "風の精霊", nil, nil, "Mangletoothに血の欠片を10個持ってこい。そうすれば大いなる速さの祝福を授けてやろう。お前はzhevraと共に駆け、風すらお前を妬むだろう。\n\n長くは続かんが、Barrens中を旅する助けには十分なはずだ。", "いいぞ。導き手である猪神Agamagganと共に行け、{race}。Agamagganの魔法をもっと欲するなら、俺のところへ戻ってこい。", 0x379dc9e6, nil, nil, 0x8c28d61d, 0x2b6a6a7c, ".mm.." },
  [890] = { "消えた積荷", "Gazlowe's LedgerをWharfmaster Dizzywigに渡して下さい。", "Booty Bayから最後の積荷がやってくるのをすごく待ってたんだ! その積荷、Freebootersに盗まれたに違いないと思うんだけど、確認のために、波止場へ降りてって、オレの積荷が知らないうちに倉庫へ運び込まれてるかどうかDizzywigに聞いて欲しいんだ。\n\nほら、この台帳をDizzywigのところへ持ってって、彼の記録とオレの在庫の記録を突き合わせて、再確認させるんだ。", "次の船で送る品かい、{name}?", "ああ、Gazloweが君を寄越したんだね? ちょっと待ってな、この台帳を調べさせてくれ。記録と照合して、Gazloweの積荷を間違った場所へ送ってないか確認するから。\n\n彼はDrizzlekのブーツを待ってるに違いない……", 0x6e986c05, 0xb6778f93, 0x3b8b55c6, 0x0751d23b, 0x749eab9a, "....." },
  [891] = { "Northwatchの大砲", "RatchetのCaptain Thalo'thas Brightsunは、Theramore Medalを10個集め、Captain Fairmount・Cannoneer Whessan ・Cannoneer Smytheを殺害するよう望んでいます。", "またしても俺の船団の船が、Northwatch Holdにいるあの行き過ぎた人間どものせいで失われた！\n\nあの野郎どもは始末しなきゃならん。奴らは疑心暗鬼のあまり狂乱状態だ。すぐ撃ちたがる無鉄砲なろくでなしどもが、目に入るものを片っ端から撃ってやがる。\n\nMerchant Coast沿いに南へ進んでHoldへ向かい、奴らの軍勢を包囲攻撃してくれ。証拠として兵士どものメダルを持ってこい。それと、俺の船団のためにも、Captain Fairmountとその行き過ぎた砲手どもを始末してくれ！", "Captain Fairmountとあの忌々しい砲手どもがNorthwatch Holdから砲撃してくるせいで、俺の船団は危機にさらされてる。あの女の兵士どもにも償わせてやりたい。奴らの死体から取ったmedalsで俺の手をいっぱいにしてくれ。そうすりゃ、倒れた私掠船員たちの復讐が果たされたと分かる。", "なんともはや、高潔なるAllianceの大砲は沈黙したか。{name}、君の助力に報いねばなるまい。\n\nさてと、死者の骸を収容する気の滅入る任務へ向かわねば……", 0xe43eab3d, 0xf4eee744, 0xa8fff6eb, 0x7d3aa2a3, 0x84df7b53, "....." },
  [892] = { "消えた積荷", "Gazlowe's LedgerをRatchetのGazloweに返して下さい。", "記録から判断すると、すべてちゃんとしてるようだよ、{name}。戻って、Gazloweに「君はついてなかったんだ」と伝えてくれ。積荷が海賊どもに掻っさらわれてたとしても、おかしくない。\n\n彼にしてやれるのはそれだけだ。ああ……そうそう。彼に伝えてくれ。Undermineからいくつか物が送られてきたから、時間のあるときに取りに来てくれ、とね。", "で、Dizzywigは何て言ってた?", "駄目だったって? あれはFreebootersにやられたんだと思ってる……Dizzywigは誠実だから、こんな風にオレをだますはずがない。なんだかんだで結局、あいつも雇われ者だなあ。\n\n積荷を取り戻さなきゃならないようだ、{name}。君はどう思う?", 0x6e986c05, 0xccb10e11, 0xd2dbc272, 0xf6aa07eb, 0xfba18b3c, "....." },
  [893] = { "選りすぐりの武器", "Razormane Backstabber・Charred Razormane Wand・Razormane War ShieldをBarrensのCamp TaurajoにいるTatternack Steelforgeに渡してください。", "南に向かってField of Giantsを越えたところにいるRazormane quilboarsは、見たところ鍛冶技術を持っていない。だが、奴らは頑丈な武器を開発し始めたらしい。できたら、その技術を学ぶために数種類の武器を手に入れたいんだ。\n\nHordeの栄誉のために手助けをしてくれるのなら、奴らの武器のサンプルを持ってきてくれないか。\n\nstalkersからは短剣、seersからは杖、warfrenzyからは盾を見つけてきてくれ。うまくやってくれよな!", "私も、あの哀れなquilboarどもが鍛冶の腕を少しでも身につけられるとは思えん。だが大族長の命には従う。Razormane族について知れることはすべて調べるつもりだ。\n\nもっと卑しい仕事もしてきた。オークの民の役に立つなら、喜んでやるさ。", "素晴らしい、素晴らしい標本だよまったく。\n\nquilboarは思ってたよりも遙かに優れてる。\n\nほら{class}、これを持って出ていきな。俺はこの武器をもっとつぶさに観察しなきゃならん。我々は敵を見くびりすぎていたが、もうそんな失敗をしている余裕はないんだ。", 0x8d432675, 0x3e90d600, 0xc757cbc5, 0xced914b6, 0xc7bff642, "....." },
  [894] = { "Samophlange", "Venture Company研究所の制御盤(control console)にアクセスして下さい。", "ここから遠く北の地にあるSludge Fenの南西に、Venture Companyが小さな研究施設を建設したんだ。オレは奴らが何をしてるかさっぱり知らないんだけど、でも「samophlange」と呼ばれる何かの試みをしていることは、どうにか突き止めた。\n\nsamophlangeってのは一体何なんだ? よし、それが一体何だろうが突き止めてやる。で、調べてくれる人が必要なんだ。\n\n奴らのコントロールシステム操作マニュアルのコピーを入手したから、君はこのマニュアルでsamophlangeの停止方法を解読できるだろう。", nil, "制御盤の表面には、さまざまなボタンやレバー、点滅するライトが、やや不規則に並んでいる。小さな計器は、装置が現在最適な範囲内で作動していることを示しており、1番から3番の制御バルブが現在開いていることも示している。制御盤の右下には小さな鍵穴がある。", 0x59bd049c, 0x4672c678, 0x2862ca26, nil, 0x663259ed, "...m." },
  [895] = { "WANTED: Baron Longshore", "RatchetのGazloweにBaron Longshoreの首を渡して下さい。", "お尋ね者！\n\nHeedlessの船長、Baron Longshore\n\nGilneas出身のCaptain Longshoreは、Southsea Freebootersの船団を率いており、海賊行為の罪で指名手配されている。遺体は身元が確認できる状態であること！\n\n-- Gazlowe", "どうしたんだい? 何か手伝えることでも? 送る荷物か、それとも工学の仕事かい?", "あぁぁぁぁ! こらご苦労だったね。ほら、オレはHeedlessを外海で見たことがあるんだ。そりゃあ恐ろしい船、それともボートだったけ……　あの船乗りたちは特別だよ!\n\nとにかく、あの船の航海は本当に見ものだった。悪名高い船長がオレの船を煩わせることがなくなって、ホッとしてるよ。", 0x491ae825, 0xd4870698, 0xa3d7e5a0, 0x053eeee1, 0x55a4e1a1, "....." },
  [896] = { "鉱夫の財産", "RatchetのWharfmaster Dizzywigのために、Venture Co. OverseerかEnforcerのどちらかからCats Eye Emeraldを回収してください。", "Ratchetみたいな忙しい港の波止場管理人ってのは、情報の動きを正確に把握しているんだ。こことBooty Bayのモノとカネのやりとり全てを知ってるよ。\n\n最近、Sludge Fenの北東にあるVenture CompanyのBoulder Lode鉱山についてちょっとしたニュースを聞いたな。鉱夫のひとりが、あんたの拳ほどもあるエメラルドを見つけたんだと。オレはそういうのに興味がありそうな買い手を何人か知ってるんだ。で、売り上げを山分けしようと思うんだけど、どうかな。", "鉱夫のうち誰がemeraldを見つけたのか分かってりゃ、楽勝なんだけどな……", "この大きさを見ろよ、{name}! オレたち金持ちになれるぜ! ええと、今までに見た宝石のレートから、あんたの分け前を算出できるはず……って、50%だよ、心配すんな!\n\nさてと……これで確かに。あんたと仕事ができてよかったよ、{name}。", 0xf0a4978e, 0xb7148907, 0x65b6bf5c, 0x6508ab66, 0x517d57ef, "....." },
  [897] = { "収穫者", "Harvester's HeadをJorn Skyseerに渡して下さい。", "奇妙な、昆虫のような生物は自然秩序から外れているように見える。まるで、Barrensに住む生物ではないかのようだ。", "悩んでいるようだな、{name}。Barrensでの修行はどうだ? 何か心を乱すものを見つけたのか?", "魂が抜けてて、この獣の種類がまったく分からない。だが、君が思ったように、こいつはBarrensのものではない。私たちみんなにとって、これは恐ろしい未来の先触れなんじゃないかと危ぶんでいるんだ……\n\nでもまあ今は、覚悟だけしておいてくれ。時がこの生物の謎を解明してくれることを願おう。", 0x77d10133, 0x1420fa8f, 0x50e3911d, 0x4b2110ea, 0x2728ef86, "....." },
  [898] = { "拘束からの解放", "Gilthares FireboughをRatchetにいるCaptain Brightsunのところまで護衛して下さい。", "ついに来た! 俺を助けてくれる人が!\n\nあのガードどもをやり過ごしてきたなんて、信じられないよ。Theramoreから来たあいつら、頭がおかしいんだ。あいつらは船を沈めて、ただひとり生き残った俺を監禁したんだ。俺はAllianceの脅威であり敵だとか呼ばれてた。\n\nこの俺が! あいつらのご大層なまがい物のAllianceにとっての脅威だって?　俺はRatchetとBooty Bayを行き来する\"moonshine transport\"の甲板員だぜ。\n\nおしゃべりが過ぎたな。Ratchetへ戻るのを助けてくれないか? 準備できたら知らせてくれ。そうしたら、脱出しようじゃないか。", "何か？", "Fireboughはずっと前に死んだとばかり思ってたのに!\n\n{name}、君はその勇敢な行為によって、Thalo'dan Privateersの名誉の座を手に入れたのだ。", 0x8b0a35e2, 0xa3ee7f7a, 0x63cf73fd, 0x0c07a888, 0x8a761a12, "....." },
  [899] = { "憎悪にかられて", "CrossroadsのMankrikにBristleback Quilboar Tuskを60個渡して下さい。", "不確かさの苦しみを、お前は知っているかもしれないし、知らないかもしれないな、{class}。だが、これだけは知っておけ。私は毎日ここに立ち、日の出から日の入りまで、あの怪物どもがまた現れないかと地平線を見張っている。あれ以来、出会った豚男はみな殺してきたが、奴らの血への渇きはまだまったく癒えていない。Crossroadsへ北上するのではなく、Taurajoへ向かうべきだったのかもしれない。\n\nお前だ、{class}――お前なら私に力を貸せる。\n\n奴らを殺せ。できるだけ多く殺すのだ。奴らの牙を持ってくれば、共に奴らの死を祝おう。", "quilboarにはこの報いを受けさせる、{name}。誓うぞ。", "{class}、あんたはこの仕事を真剣に引き受けてくれた。感謝するよ。\n\n復讐の気持ちは変わらず残ってるけど、quilboarが苦痛を感じているのが見られたから、少なくとも笑うことはできるよ。", 0x6638a92b, 0x0ad06ad9, 0x504d3397, 0xe87e6a53, 0x3c792229, "....." },
  [900] = { "Samophlange", "Fuel Control Valve・Regulator Valve・Main Control Valveを閉め、もう一度制御盤を操作して下さい。", "現在、3つのバルブが開いている。制御盤にある様々な注意書きによると、装置を作動停止させる前にバルブを閉じなければならないようだ。", "制御盤の点滅するランプが、主制御弁がまだ閉じられていないことを示している。", "3つのコントロールバルブを表すライトが、バルブが閉じられたことを示すように消灯した。緑色のライトがゆっくり黄色へと変わり、装置を稼働するスイッチが動かせるようになった。バルブを閉じたことで、スイッチが切れるようになった。", 0x59bd049c, 0xc702a51e, 0x84fa6910, 0x016095ec, 0xd54462d9, "....." },
  [901] = { "Samophlange", "制御盤に使うため、Tinkerer SnigglesからConsole Keyを入手して下さい。", "装置の動作が停止し、コントロールパネルを開けることができた。samophlangeは制御盤から外れた。準備は万端、あとは制御盤を解錠するキーを手に入れるだけだ。", "制御盤のランプは暗くなり、計器とダイヤルはすべて0を指していて、すべてがアイドリング状態だ。", "キーを差し込んで回すと、制御盤は解錠された。制御盤の一番上にある赤いライトが消え、端末からすべてのパワーがひいた。", 0x59bd049c, 0x3bc295f6, 0xdda2316f, 0x90e09488, 0xec181a95, "....." },
  [902] = { "Samophlange", "RatchetのSputtervalveのところへSamophlangeを持ち帰って下さい。", "制御盤の蓋を開くと、ごちゃごちゃのワイヤや管、その他の部品が現れた。そのほとんどは非実用的な用途に使われているようだ。それを脇へどけ、制御盤の奥深くを探ると、samophlangeが見つかった。筐体からsamophlangeを引き抜いた。", "おお、戻ったな、{name}! samophlangeは持ってきたかい?", "これは……　うーん……　興味深いね……うん。これはUndermineのTinkers' Unionの本部へ送ることにするよ。精密な解体調査をすれば、彼らならこの装置の意図が理解出来ると思うよ。\n\nでも、出来たら最初に自分の目でちょっと見てみたいな……", 0x59bd049c, 0xc6a03d7b, 0x6dc9a2ce, 0x2213d644, 0x020e9774, "....." },
  [903] = { "BarrensのProwler", "Savannah ProwlerからProwler Clawを7つ集め、CrossroadsのSergra Darkthornに渡して下さい。", "さあ、本当に手強い獲物を追う時よ。Barrensのprowlerは強靱な種族なの。強靱で、賢くて、狡猾で……そして非常に危険。背の高い草の中に彼らはいるわ。Crossroadsの南西に多く見つけられるはず。\n\n狩る時は気をつけなさい、{name}。でなければ、あなたはもう捕食者ではなく、獲物になってしまうからね。", "狩りの具合はどうだ、{name}? prowlersは見つけたか?", "ほう、忙しくしていたようだな。草むらに潜んで、うろつく獣たちを狩っていたのか。では、そろそろ奴らの王者に立ち向かう時だと思うか？", 0x4a3e1d81, 0xdcd78944, 0x922f66c4, 0xaec05ded, 0x3e6426e0, "....." },
  [905] = { "怒れるScytheclaw", "Sunscale raptorを殺して羽毛を集め、Scytheclawの巣3ヶ所でその羽毛を使って下さい。CrossroadsのSergra Darkthornのところへ戻って下さい。", "さあ、{name}、狩りはいよいよ深まる。今度は獲物を倒し、それからその巣への道を見つけねばならない。\n\n南にいるsunscale raptorを狩るのだ。奴らを倒して、身につけている羽根を取れ。その羽根をStagnant Oasisの南西にあるscytheclawの巣に置くのだ。奴らの同胞に、お前が恐れていないことを示してやれ！", "巣には行ってきたか、{name}?", "じゃあ巣へ行って、羽を置いてきたんだね。それにはかなりの勇気が必要だよ、間違いなく。\n\n{name}、少し強くなったように感じない? 初めてここへ来た時より、ずっと強く見えるよ。Barrensはうってつけのようだね。", 0x4d73067a, 0x8199dcd2, 0x2a21e74d, 0x8b091b50, 0xd4047437, "....." },
  [906] = { "内部の裏切り者", "BarrensのCrossroadsにいるThorkにLok's Skullを渡して下さい。", "Lokの頭を持ってCrossroadsのThorkのところへ行け、{race}。フン。何も言わなくてもオレの部族で何が起きたか分かるはず……はは、そんなことで助けられたからといって、フン、Mangletoothを信じやしないだろうがな。でも、こんなすごいことをやったお前には、見返りをくれるはずだ。フン。\n\nこの檻の中にオレがいる間はずっと、Agamagganの力を授けてやるよ、{race}。それまでは、さらばだ。", "ああ、何だ?", "{name}、Razormaneの指導者を見つけて殺したのか?　信じられん。\n\n何も言えない、が、感謝していないということではないぞ。Crossroadsの者たちは君の力に心から敬意を払うだろう。\n\n過ちは認めねばならんな。補給路を襲撃している指導者を別のquilboarだと思っていたのだ。もう一度礼を言うぞ、{name}。", 0xabe2f634, 0x4c355197, 0x5127491a, 0xb4a62c76, 0x6332f935, "....." },
  [907] = { "怒り狂うThunder Lizardたち", "Thunder Lizard Bloodを3つ、Camp TaurajoのJorn Skyseerに渡して下さい。", "さてと{name}、強いthunder lizardに立ち向かわなくてはならんぞ。彼らはあまりにも巨大すぎて、平原をのし歩くたびに地面が揺れる。戦うときには気をつけろ。たった一歩の過ちで、下敷きになるんだからな。\n\nBarrens南部にthunder lizardたちを見つけられるはずだ。彼らはStormsnouts・Stormhides・Thunderheadsとして知られている。\n\n彼らに勝ったら、私のところへ戻ってくるんだぞ。", "thunder lizardsは倒したか、{name}?", "勝利の証を持ち帰ってきた君に会えてよかった。それと、君の体の骨が粉々にされてなくてよかったよ。", 0xd908cdb9, 0xa9e2d30c, 0xb2ff357e, 0x288aa9eb, 0xeeed6543, "....." },
  [908] = { "廃墟の中で", "Fathom CoreをAshenvaleのZoram'gar OutpostにいるJe'neu Sancreaのところへ持って行って下さい。", "Twilight's HammerがBlackfathom DeepsのMoonshrine Ruinsに入り込んだ。奴らがいれば、エレメンタルは我々に背くよう強いられるばかりだ。放っておけば、この地は永遠に奴らのものになってしまう。\n\n{name}、Blackfathomへ入り、遺跡のfathom stoneを見つけてくれ。水の中のどこか近くにあるはずだ。その中にfathom coreがある。正しく読み取れば、あらゆるエレメンタルの活動の歴史を語ってくれる装置だ。それが手に入れば、私とEarthen Ringで奴らを止められるかもしれない!", "fathom coreは見つかりましたか? それがなければ、Twilight's Hammerがあそこで一体何を企んでいるのか見当もつきません。", "まさにこれが必要だったのだ！ fathom coreは驚くほど豊かな情報の泉で、我々はそこから多くの有益なものを引き出せるだろう。Twilight's Hammerがあの中で何を企んでいるにせよ――信じてくれ、ろくなことではない――私と仲間たちがこれで暴いてみせる。\n\n今日はよくやってくれた。我々を助けてくれたことで、Earthen Ringはお前に温かい目を向けている。Horde全体の助けにもなったのだ。そのことを誇りに思うといい。", 0x09596e4f, 0xedf98535, 0x8b83bfb4, 0x55331311, 0x22dfd3c7, "....." },
  [909] = { "Baron Aquanis", "Strange Water GlobeをAshenvaleのZoram'gar OutpostにいるJe'neu Sancreaのところへ持って行って下さい。", "倒された水のエレメンタルが、strange water globeを残していった。この物体がどういうわけか怪物にエネルギーを与えていたのだろうと、あなたは推測する。球体の中では、腐ったような見た目の水が揺れ動いている。球体そのものは、いかなる物理的な力も受け付けないようだ。\n\nこの品を理解できる者がいるとすれば、それはEarthen RingのJe'neu Sancreaだろう。彼はAshenvaleにあるHordeのZoram'gar Outpostにいる。", "ああ、また会いましたね、{name}。ちょうどいつものように海の波を読んでいたところです。この前哨地へは何の用で?", "これは……これは大した発見ですね、{name}。\n\nBlackfathomのBaron Aquanisから手に入れたと言うのですか？ Baron Aquanisは長らく堕落した精霊の力だと考えられてきました。この球を調べれば、何が彼を堕落させたのかがはっきりするでしょう。それがTwilight's Hammerだったとしても驚きはしませんが、我々の研究で彼らがどうやってそれを成したのかも明らかになるはずです。\n\nこれを私のもとへ持ってきてくれたのは見事でした。どうぞ――これを受け取ってください。Earthen Ringからの心からの感謝とともに。", 0x6317c3fa, 0x5afab460, 0xeafedd21, 0xd1397112, 0x5fa18944, "....." },
  [910] = { "桟橋へ降りる", "BarrensにあるRatchetの桟橋に孤児を連れて行って下さい。", "RatchetとBooty Bayの間を行き来する大きな船の話を聞いたんだ!海を航海して、大きな海戦をいっぱい戦えたら、すっごくかっこいいだろうな。大きくなったら、強いHordeの船乗りになれるかも!やった!\n\nRatchetの波止場を見に連れてってくれない?お願い!水には入らないし、迷惑もかけないって約束するよ。大きな船を見て、しょっぱい海の匂いをかぎたいだけなんだ!やった!", "まだ着かないの?", "わあ、海ってすっごく大きい! カモメとかもいっぱいいたね――思ってた通り、にぎやかで騒がしかったよ。近くには海賊もいた――かっこいい!\n\nRatchetに連れていってくれてありがとう、{name}。すごく楽しかった!", 0xc24e64c7, 0xcdecb9f4, 0x4572c0ed, 0x63e6b64c, 0xceb51122, "....." },
  [911] = { "開拓地への入り口", "孤児をMor'shan Rampartへ連れて行って下さい。Mor'shan RampartはBarrens北部、Ashenvaleのすぐ手前です。", "Ashenvaleは新しい開拓地で、BarrensのMor'shan Rampartはそこへの入り口なんだって。開拓者になって、手つかずの荒野から必要なものを全部切り開いていけたら、すっごくかっこいいだろうな!これから先、HordeとAllianceが一番ぶつかり合うのはそこなんだって。そこに行ってみたいんだよ、{name}!\n\n開拓地がどんなところか見られるように、Mor'shan Rampartへ連れてってくれない?お願い!Hordeがあのくさいナイトエルフたちを追い払ってるところを見たいんだ!", "まだ着かないの?", "わあ、Ashenvaleこそ本物の冒険がある場所だね! {name}はAshenvaleで戦ったことある? 大きくなって英雄になったら、僕もAshenvaleに来て、Hordeの栄光のために戦うんだ!\n\n辺境に連れていってくれてありがとう、{name}。最高だよ!", 0x4d1e5154, 0xfdb10b6f, 0xb2a749fd, 0x63e6b64c, 0x9959eaf3, "....." },
  [912] = { "Stonesplinter Troggの変装", nil, nil, nil, nil, 0x7c1e89d9, nil, nil, nil, nil, ".mmmm" },
  [913] = { "Thunderhawkの咆吼", "Thunderhawkを見つけて討ち取り、その翼をCamp TaurajoのJorn Skyseerのところへ持ち帰って下さい。", "Thunderhawkというのはな、{name}、それは獰猛な獣なんだ。彼らに立ち向かう時だ。うろついているThunderhawkを見つけ、その翼を狩りの成功の証として私に渡してくれ。\n\nそうしたら、私とともにいる時間も終わりが近づいている。", "終わったか? thunderhawkを仕留めたか?", "誇らしくするんだ、Thunderhawkのように。君は我々が課したすべての障害に打ち勝った。力と勇気と名誉でもって勝利したのだ。\n\nしかし君の道はな、{name}、続いていく。事実、真の狩人とは永遠に努力し、君が見せてくれたのと同じ誇りをもって永遠に己が道を歩むものだと分かるだろう。\n\nさあ、前へ進む時がきた。", 0x168add81, 0x2e50c35a, 0x7c0fdf40, 0x1ce663e1, 0x12313ad2, "....." },
  [914] = { "Fangの指導者たち", "Gems of Cobrahn・Anacondra・Pythas・SerpentisをThunder BluffのNara Wildmaneに渡して下さい。", "Wailing CavernsにいるDruids of the Fangは、異常な者たちなのです。彼らはBarrensを癒すことを計画した崇高なドルイド集団の一部でした。ですが、今は自分たちに都合のよい歪んだ夢へと、Barrensを変えようと目論んでいるのです。\n\nDruids of the Fangには4人の指導者がいて、それぞれが夢の宝石を所持しています。今でも彼らの顔が頭にこびりついていますよ!　指導者たちを打ち倒し、宝石を私に渡して下さい。Barrensは再び平和を取り戻すはずです。\n\n行って下さい、{name}。Wailing Cavernsの奥深くに潜む彼らを見つけなくてはなりません。", "悪夢の記憶が私を苦しめるのです、{name}。牙の指導者たちを倒し、彼らの宝石を手に入れましたか?", "やってくれたのですね、{name}。Druids of the Fangの指導者たちを殺したのですね。私の夢も、彼らの不快な顔から解放されます。そして、あなたはBarrensを呪われた未来から救ったのです。\n\n感謝します、{name}。私から、Thunder Bluffのドルイドから、そしてこの大地から、あなたに感謝を捧げます。", 0xe577280d, 0x4f7a87a2, 0x8280e4ae, 0x40d9e1ec, 0xbcdaf980, "....." },
  [915] = { "ユースクリーム、アイスクリーム……", "Strawberry Ice Creamを孤児に買ってあげて下さい。その子はTigule and Foror's brand ice creamが好きなようです。", "アイスクリーム!ねえお願いお願いお願い、アイスクリームを買ってきてくれない?!イチゴが一番好きな味で、Tigule and Foror's Strawberry Ice Creamより美味しいイチゴのアイスクリームなんて世界中どこにもないんだ!世界で一番大好きなアイスクリームなんだよ!\n\nずっと前にShimmering Flatsのレース場で一度だけ食べたんだけど、今は町でも売ってるかもしれないって聞いたんだ!お願い!ほんとにお願い!Tigule and Foror's Strawberry Ice Creamをのっけてさ??!?!", "いちご以外のアイスクリームの味も作ってくれたらいいのに。でも、いちごが一番好きだから、ラッキーだったのかな!", "んんーっ! ここのイチゴのアイスクリーム大好き! TiguleとFororに得意なことが一つあるとしたら、それはアイスクリーム作りだね!\n\n本当にありがとう{name}――こんなに素敵なおやつは初めてだよ!", 0xa1977492, 0xc5729738, 0x10fb94e9, 0xf1f00363, 0x51094ed8, "....." },
  [916] = { "Webwoodの毒", "AldrassilにいるGilshalan Windwalkerに、Webwood Venom sacを10個届ける。", "私はShadowthread Caveに住み着いているWebwood spiderの様子を見るために、Shadowglenに来たんだ。Webwood spiderは、とても小さなクモ達と類似した種のはずなんだが…私は世界樹が、Webwood spiderたちに多大な影響を及ぼしたのではないかと思っている。できればこれを確認、研究するために標本がほしい。\n\nまずは、幾つかあのクモの毒がいる。北にあるShadowthread Caveの傍や中にいるクモから、Webwood venom sacを集めてきて欲しい。そうすればWebwood spiderの毒と、小さなクモの毒に類似性があるかどうかを、調べることができるからね。", "venom sacsは集めましたか、{name}?", "有難う{name}。Darnassusに戻ったら、これらの毒を他のクモの毒と比較することにしよう。近頃の世界樹の成長に関連する、なんらかの特性がみつかるに違いない。", 0x5ef3699f, 0xcd2d6c5d, 0x328f2ab5, 0x0d16764a, 0x93e71cf8, "....." },
  [917] = { "Webwood Egg", "Webwood EggをAldrassilのGilshalanに渡せ。", "蜘蛛の毒は手に入ったので、今度は研究のために生きた標本がほしいのです。とはいえ、生きた巨大な蜘蛛を捕らえてほしいとまでは頼めません、若き{class}よ。それに巨大な蜘蛛なんて、私自身の手にも負えませんから!\n\nですが、孵化していない卵を見つけてもらえれば、標本を届けるのはずっと楽になりますし、孵る前の蜘蛛を閉じ込めておく手はずも整えられます。\n\nShadowthread Caveの奥深くに巣があるはずです。どうか巣の中で卵を探して、私のところへ持ってきてください。", "Shadowthread Caveの中には入りましたか、{name}? spider eggは見つかりましたか?", "あぁ、よくやった！この卵と毒をDarnassusに送ろう。ここでの研究が終わったら、あそこへ戻らなければならないからな。私はこの標本からかなりの成果があるんじゃないかと期待しているんだ, {name}. 君は大いに助けになったよ。", 0x45dca847, 0xe3b29d22, 0x81a464b0, 0x04406a66, 0x2017b57d, "....." },
  [918] = { "Timberling の種", "Timberling Seedsを$N1個、Lake Al'AmethのDenelanのところへ持って行って下さい。", "Teldrassilのtimberlingは自然のエレメンタルです。ある意味で、彼らは私たちの偉大なる樹に生きる植物や動物の自然の秩序を映し出しているのです。\n\nですから、timberlingたちがこれほど怒りを募らせているのを見るのは気がかりです。\n\n原因は土にあるのだと私は考えています。私は植物を育てるさまざまな方法を研究してきたので、それをtimberlingの種で試してみたいのです。どうか、Lake Al'Ameth周辺のtimberlingから種を集めて、私のところへ持ってきてくれませんか？", "seedsは持っていますか? 早く植えたいのです。", "手に入ったか。良かった!\n\nあらかじめ用意しておいた特別な土にこの種を植えるつもりなのだよ。もっと大人しい timberling に育つはずだ。\n\n結果は後で分かるだろう!", 0xc2c5c9a3, 0xc6ed298e, 0x6bd8e4d3, 0x0e19807b, 0xe481e8bb, "....." },
  [919] = { "Timberling の芽", "Timberling Sproutsを$N1個、Lake Al'AmethのDenalanのところへ持って行って下さい。", "小さな timberling が Lake Al'Ameth のほとりに芽を出している。残念だがその芽も手遅れだ――厄介事を起こすほど大きくなる前に、ここから一掃した方がいい。\n\n湖を歩き回っている時に timberling の芽を見かけたら引っこ抜いて欲しい。この地を清らかに保つのを手伝ってくれ!", "こんにちは、{name}。水辺の近くでsproutsは見つかりましたか?", "こんなにたくさん! 危険な速度で広がっているようだな。何が穢しているのかという謎を解ければいいが。\n\n協力に感謝するよ、{name} 。君のお陰でここは綺麗な場所になった。", 0x51165847, 0x4f95eccd, 0x3ae4085a, 0xe4c0ddfe, 0xf442a65d, "....." },
  [920] = { "Tenaronよりの召喚", "ShadowglenにあるAldrassilの最上階にいるTenaron Stormgripと話してください。", "{name}だな？　Tenaronが探していたらしいぞ。あの人はAldrassilの最上部にある部屋にいるはずだ。\n\n確かに俺たちは長命ではあるが、あの人はそう長く待たせないほうがいい。", nil, "ああ、{name}だな。私の召喚に応じて欲しく思っていたのだ。おまえに重要な仕事を任せたい。", 0xde22b969, 0x7548d88d, 0x92b7f833, nil, 0x7330b9e5, "...m." },
  [921] = { "地上の王冠", "Crystal Phialに水を汲み、Aldrassilの最上階にいるTenaron Stormgripまで持ち帰ってください。", "宿命を見出す旅立ちのときが来たようだな、{name}。この魔法の森の向こうにある世界へと足を踏み出す前に、おまえには知っておくべき歴史がある。\n\nBattle of Mount Hyjalにより、我が民にも大きな変化があった。Archimondeを倒しBurning Legionを追い払うために力を使ったNordrassilも今はかつての見る影もない…。\n\nおまえに頼みたいことがあるのだ。Aldrassilの北にあるmoonwellで水を汲み、持って帰ってきてくれ。", "月の泉にはWell of Eternityの水が湛えられています。私たちの世界に数多くの恐怖をもたらしてきた、古の魔力の源です。\n\nドルイドはその性質を活用し、Sentinelsは泉をEluneの祠として崇めていますが、魔術は誰にも禁じられているのです。", "Battle of Mount Hyjalの結果について、さわりは分かったな。だが知るべきことはたくさん残っているし、ここから始まった仕事はTeldrassilからDarnassusまで、まだまだ終わらないのだぞ。", 0x6a9c354f, 0x6f20ec86, 0x63729cf0, 0x92295015, 0x4972e13e, "....." },
  [922] = { "Rellian Greenspyre", "Darnassus にいる Rellian Greenspyre に Timberling Seed を渡して下さい。", "{name}、持ってきてくれた種の一つを、私の友人Rellian Greenspyreのところへ届けてもらえませんか？ 彼はDarnassusにいるドルイドで、前に話したとき、私のTimberlingsの研究に興味があると明かしてくれました。彼自身にも考えがあるようで、研究に使える見本の種があれば喜ぶでしょう。\n\nありがとう、{name}。本当に助かりました。いつの日か、私の努力が実を結ぶところをあなたに見てもらえたらと思います。\n\nRellianはたいてい、DarnassusのCenarian Enclaveの小道を歩いています。", "こんにちは……\n\nそれで、どのようなご用件でしょう?", "あ、timberling の種? Denalan の研究を手伝うのにひとつ育ててみたかったんだ。\n\nしかし残念ながら、多くの timberling の中に穢れが育っていて、そういった生物からとれる種には親の穢れが受け継がれていることが分かった。これはもう私の手には負えない。\n\nDenalan は植物に精通しているから、これから育つ timberling の治療法を発見するかもしれん。彼は唯一の希望かもしれないな。", 0x57fb1b20, 0x0cd55696, 0xaed4fa67, 0x36a1f94a, 0x61b8489f, "....." },
  [923] = { "腫瘍", "Mossy Tumorを5つ回収し、DarnassusのRellian Greenspyreに渡して下さい。", "timberling の中に悪意が育ちつつある。その根源を突き止めようとはしているのだが、まだなんだ…… Teldrassil を守り続けるためには、手に負えなくなった timberling を殺さねばならない。北の Wellspring Lake をうろついているものは最も汚染されている。駆除しなくては!\n\nあそこで見つけた Timberling を殺して、体表面に生えているmossy tumorsを集めてくれ。集めた腫瘍は燃やしてしまえるよう、ここへ持ってきて欲しい。", "Wellspring Lakeへは行きましたか、{name}? そこでtimberlingを狩ってきましたか?", "よくやった! この腫瘍は timberling の病変部でね、新天地から取り除かなくてはならない毒でいっぱいなんだ。\n\nこれは私が処理する。ありがとう、{name} 。", 0x9be57a52, 0xd33dba21, 0x8c75928f, 0x75561cf5, 0xab86b70c, "....." },
  [924] = { "Demon Seed", "Flawed Power Stoneを取りましょう。石が効果を失う前にAltar of Fireへ運んでください。それからAk'Zelothのところへ戻ってください。", "Demon SeedはBurning Legionにとって重要なものだ。あれはDreadmist Peakにある洞窟の悪魔の火の祭壇の上で眠っている。\n\nSeedの近くに置くとLegionとのやり取りを妨害することのできるパワーストーンを用意した。\n\nテーブルの上の石を持って、Dreadmist Peakの頂上にある火の祭壇へ行け。西へ行け。分かれ道に着いたら北だ。左に目指す山がある。北側から上るのが安全だな。\n\n急ぐのだ。石のパワーは長くは持たない。", "Demon Seedはまだ存在している。その力を感じるのだ……", "任務完了だね。Neeruの望みどおりDemon Seedは破壊されたようだ。しかしこれで終わりではないよ・・。\n\nDemon Seedの破壊はエーテルを通して驚くほど強力な波動を送った。私も感じたよ。ほかにも気づいたものがいるだろう。自分たちのおもちゃがなぜ壊れたのか不思議に思うものもいるだろうね・・・。\n\nまあそれはさておき、渡すものがある。Neeruからだ。感謝してると伝えてくれともね。\n\nまあ、ありがとう。", 0x07a08d0b, 0xc93af534, 0xbe65b854, 0x7f1f8d44, 0xf41f35c3, "....." },
  [925] = { "Cairne's Hoofprint", "Thunder Bluffへ行き、孤児のためにCairne Bloodhoofの手形をもらう手配をして下さい。", "Cairne BloodhoofはHordeがこれまでに見た中で一番偉大な英雄の一人なんだって。大きくなったら、Hordeの英雄になりたいんだ!\n\nCairneのこと知ってる、{name}?お願いがあるんだけど、いいかな?Cairneの蹄の跡をもらってきてくれない?どうやって頼めばいいか分からないし、Cairneはきっと忙しすぎてこんな子供の相手なんかしてくれないよ……でもあなたなら!Cairneと同じ冒険者だもん!きっとすぐに蹄の跡をくれるよ!\n\nお願い!", "オークたちが孤独で友もいなかった時、トーレンは見知らぬ地で彼らを迎え入れ、見返りを何も求めずに分かち合った。それこそが名誉というものだ、{name}。", "わあ! Cairneのひづめの跡をもらってきてくれたんだ! 本当にありがとう! それに……僕あてに直筆のメッセージまで書いてくれてる! あの人は最高だって分かってたんだ、絶対そうだって! いつか自分でお礼を言えるかな……僕がHordeの英雄になったら!\n\n{name}は最高だよ。こんなに優しくしてくれてありがとう。", 0x055a9a75, 0xd01bc90b, 0x6c7aaa83, 0x89707112, 0x80448280, "....." },
  [926] = { "Flawed Power Stone", "なし", "なし", nil, "石には神秘的なエネルギーが満たされているが、意図的に傷つけられているようである。非常に扱いづらそうで、テーブルから取り上げるとどんどん力が失われていくようである。", 0xbfd0ccf1, nil, nil, nil, 0x79072959, "...m." },
  [927] = { "Moss-twined Heart", "Lake Al'Ameth にいる Denalan に Moss-twined Heart を渡して下さい。", "Blackmoss the Fetid の心臓は、黒く油っぽい苔で覆われていた。実際、これが心臓であることを示しているのは、緩く規則的な拍動だけである……今もまだ拍動は続いている。\n\nDenalan が見たがるかもしれない。", "{name}! 私に何か持ってきてくれたのか?", "……何だこれ? timberling の心臓?? 汚い苔に覆われてるぞ!\n\n持ち込んでくれて感謝するよ、{name} 。これを調べてみて、運が良ければ苔の性質を明らかにできるだろう。", 0x8ab57346, 0x174962f9, 0x3bdb0906, 0xdfd947e9, 0x5c540383, "....." },
  [928] = { "地上の王冠", "Partially Filled VesselをDolanaarにいるCorithras Moonrageに届けてください。", "MoonwellやTeldrassilについて話すことはたくさんあるのだが、おまえを遣いにださねばならない。Corithras Moonrageがおまえを待っているのだ。持って来てくれた瓶の水はこっちの入れ物に入れたから、渡してやってくれ。\n\nCorithrasを訪ねるのだ。Dolanaarのmoonwellにいるはずだ。Shadowglenを出てAldrassilから南に伸びる道をたどり、舗装された街道を道なりに西へと行くといいだろう。\n\n街道からはずれるなよ、{name}。この頃は森にも凶暴な動物がいるからな。", "ごきげんよう、{class}。いかなる用向きで、この出会いの喜びを賜ったのかな?", "ああ、わかったぞ。Tenaronの遣いだな。どうやら、話すこともやることも山とあるが、時間はほとんど無いってことらしいな。\n\nすぐに取り掛かったほうがよさそうだ。", 0x6a9c354f, 0x519e561b, 0x69be4dda, 0xa03c786d, 0xd5848e6f, "....." },
  [929] = { "大地の冠", "Jade Phialに水を汲み、DolanaarのCorithras Moonrageのところへ持ち帰って下さい。", "まずは、あなたが果たすべき務めについてもっと話しましょう。Darnassusのドルイドたちは、Teldrassilの月の泉の水を使っています。そして月の泉は時おり満たし直さなければなりません。この特別に作られた小瓶を使えば、月の泉の水を汲むことができます。\n\nこの器を持って東のStarbreeze Villageの外にある月の泉へ行き、その水で満たしてから、私のもとへ戻ってきてください。務めを果たしたら、Tenaronが話し終えたところから物語の続きを聞かせましょう……", "また会いましたね、{name}。務めは果たしましたか?", "Mount Hyjalの戦いが終わってから我々は方向を見失った。Nordrassilは炎を解き放って燃え尽き、そして我らの永遠の命も -- 我らが種の根源も -- 失われたのだ。\n\nBetrayerが牢獄から抜け出し、Shan'do Stormrageの行方も知れぬ今は試練のとき。まさに闇だ。", 0x6a9c354f, 0x188ad811, 0x725fcab1, 0xd7878828, 0x95ab8c86, "....." },
  [930] = { "Glowing Fruit", "Lake Al'Ameth にいる Denalan に glowing fruit を渡して下さい。", "輝いている植物の葉からぶら下がっているのは、大きく丸い果実だった。\n\nDenalan が研究したがるだろうと確信した。", "{name}、何か話したいことがありそうな顔ですね。timberlingについて知らせがあるのですか?", "Teldrassil でこれを見つけた? 興味深いね……外来種の果実だな。恐らくこの種は遠いところから運ばれてきたのだろう。もしかすると Azeroth からかもしれん! この実には何かあるぞ…… Teldrassil の土に対してかなり奇妙な反応をしているようだ。\n\nありがとう、{name} 。では失礼、もっとこれを調べねば……。", 0xa2834fd5, 0x29dd07f4, 0x84397c8e, 0x2532fbc0, 0x2ea98bd6, "....." },
  [931] = { "Shimmering Frond", "Shimmering FrondをLake Al'AmethのDenalanのところへ持って行って下さい。", "植物の葉は森の明かりで輝き、螺旋状に脈打つオーラを放っている。\n\nDenalan がこの標本を欲しがるだろうと確信した。", "何か私に渡すものがあるのか？", "どこで手に入れたんだい? Swamp of Sorrows に滞在していたのは……何十年も前だったが、あれ以来こんな植物にはお目にかからなかったよ! こんなものが Teldrassil へはるばるやって来たとは面白い。しかもこんなサイズに成長して!\n\nありがとう、{name} 。無愛想なことで申し訳ないが、この葉で試してみたい実験があるんだ……。", 0x3dda56af, 0xe2d17f64, 0xd3966077, 0xa03be4c2, 0xa5f2249f, "....." },
  [932] = { "歪んだ憎悪", "Lord Melenas の首を取って Dolanaar の Tallonkai Swiftroot に持ってきて下さい。", "言っておくことがある、{name} 。このことは我々二人の間だけに留めておかねばならない。あのsatyrは既に障害となっているし、ここに近すぎる。\n\n奴は Lord Melenas と呼ばれており、北の Fel Rock という洞窟に棲んでいる。そこで奴はgrell戦士の大集団を集めている。奴の心臓は夜のように黒く、何か汚らわしいことを企んでいるのだ。\n\nちょうど北にある近くの洞窟で奴を見つけ、首を持ってきてくれ。", "Lord Melenasはもう始末したか? 奴は速やかに、そして密かに片付けねばならないのだ、{name}。奴が生き永らえていること自体、我々全員の恥だ。", "Melenas が葬られたお陰でようやく別の問題に取りかかれる。ありがとう、{name} 。", 0x10738b8e, 0xa49ba15f, 0xbc655ff9, 0x7bab7e42, 0x4a8d372b, "....." },
  [933] = { "大地の冠", "Tourmaline Phialに水を汲み、DolanaarのCorithras Moonrageのところへ持ち帰って下さい。", "Darnassusの入り口南東、Pools of Arlithrienのそばにもmoonwellがある。あの付近では、勢力を伸ばしているGnarlpine furbolgの襲撃に、Sentinelも警備に手を焼いているようだ。\n\n気をつけてMoonwellを探せよ。けっして武器を手放すな。", "当初、正気を失ったfurbolgが襲ってくるという報告は相手にされなかった。平和を愛する熊の民が我を忘れた怒りに身を任せるなど、誰が思っただろうか? これもまた、この新たな故郷で私たちを苦しめる問題の一つなのだ。", "Shan'do Stormrageは二度と戻らず、ドルイドたちは混乱に陥った。彼の身に何が起きたのか、今日に至るまで我々には分からない。Malfurionが行方不明となると、Arch Druid Fandral Staghelmがドルイドたちの指導者の座を引き継ぎ、今こそ我らの民が再建すべき時であり、不死を取り戻すべき時であると、DarkshoreのCircle of Ancientsを説き伏せたのだ。\n\nCircleの承認を得て、Staghelmと最も力あるドルイドたちが新たなWorld Tree、Teldrassilを育てたのだ。", 0x6a9c354f, 0x3d0857d5, 0x4d68f2e0, 0x531af2f0, 0x63415c4c, "....." },
  [934] = { "大地の冠", "Amethyst Phialを満たし、DolanaarのCorithras Moonrageのところへ持ち帰って下さい。", "とはいえ、Teldrassilのすべてが順調だったわけではありません。新たなWorld Treeに向けたStaghelmの綿密な計画は彼の望み通りに実を結びましたが、一つだけ小さな問題がありました。Teldrassilの多くの災いは、その問題に起因しているのかもしれません。\n\nですが、その話はまだしないでおきましょう。あなたは最後の月の泉を訪れなければなりません。北西のOracle Gladeにあります。Oracle Treeの枝の下に、我らの泉の中で最初にして最も力強い泉があるのです。その水を小瓶に汲んで、私のもとへ戻ってきてください。", "ドルイドたちと共に、Oracle Treeと大ドルイドはTeldrassilの成長を注意深く見守ってきました。けれども、新たな故郷を得たとはいえ、私たちの不死の命は戻っていないのです。", "Oracle Treeのそばにいると……知恵が形を成すのを感じるかのようです。語りの続きをさせてください……\n\nTeldrassilが育つと、大ドルイドはdragonたちに祝福を求めました。いにしえの時代にdragonたちがNordrassilに授けたのと同じ祝福です。けれども、Lord of TimeであるNozdormuは祝福を拒み、そのドルイドの傲慢さを戒めました。Nozdormuに同意して、AlexstraszaもStaghelmを拒みました。彼女の祝福がなかったために、Teldrassilの成長には欠陥があり、予測のつかないものとなっているのです……", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [935] = { "大地の冠", "Filled Vesselを、DarnassusにいるArch DruidのFandral Staghelmに届けてください。", "Life-BinderのAlexstraszaとTimelessのNozdormuの祝福を無くして成長したTeldrassilには問題が無いとはいえなかった。奇怪な生き物が世界樹のまさに足元で発見されたという報告があがってるし、狂ったfurbolgが旅人を襲撃してる。\n\nArch Druidが一刻も早く解決方法を見つけてくれるのを祈るしか俺にはできん。持ってきてくれた水をこの瓶に詰めるから、Darnassusへ届けてくれ。\n\nこれをFandral Staghelmに渡してくれ。Druid groveにいるはずだ。", "あなたを呼んだ覚えはありませんから、なぜ私と話しに来たのか、不思議に思わずにはいられません。\n\n何であれ、手短にお願いします。", "ああ、頼んでおいた水ですね。TenaronとCorithrasも届けるのにずいぶん時間をかけたものです……あまり信頼できる使者を選ばなかったのかもしれませんね……ふむ。\n\nともあれ、これでようやく仕事に戻れます。Teldrassilの問題の重みは、この肩にのしかかっているのです。早く下ろしてしまいたい軛ですよ。\n\nこれを取っておきなさい。何かの役に立つでしょう。", 0x6a9c354f, 0x1325e4e5, 0x54cda088, 0xaf4b925e, 0xf477d1e8, "....." },
  [936] = { "Arch Druid Runetotemの手伝い", "Thunder BluffのArch Druid Hamuul Runetotemと話してください。", "すみません、{class}。ちょっとお時間をいただけませんか。\n\nThunder BluffのCenarion Circleは、重大な研究計画への助けが必要で、あなたのような手練れの冒険者に非常に関心を持っています。私は詳しく知りませんが、他ならぬHamuul Runetotemがこの研究を指揮していることはお教えできます。\n\nどうか、もし興味がおありならばElder Riseにいる彼と直接話してください。", nil, "ごきげんよう、{class}。我々の研究の手助けに興味を持ってくれて嬉しく思う。やることが多すぎるんだ。この仕事が危険でないと言ったら、君の気分を害するかもしれないな。願わくば、嫌気がさして帰ったりしないで欲しいが……しかし、君の顔を見れば分かるよ。前にも同じような危険な仕事を捌いてきたってね。", 0xba8dc721, 0xaac27949, 0x6fcc5bd2, nil, 0x93151f63, "...m." },
  [937] = { "魔力を秘めた草地", "Bloodfeather Belt 6つを手に入れ、Oracle Glade の Sentinel Arynia Cloudsbreak に持ってきて下さい。", "この草地一帯に巣を作っているharpiesから Oracle Tree を守るべく、私は Sentinels の小隊と共に派遣されてきました。少しずつですがharpiesを押し戻しています。\n\nOracle Tree が Darnassus へ報告書を携えた使者を送りだそうとした時、その使者がharpiesの集団に襲われ殺害されたのです。\n\nもし良かったら、巣に行ってharpiesを殺し、その証拠にベルトを持ち帰ってきて下さい。", "奴らの切り裂く鉤爪と突き刺す嘴は、あなたの力にとって手強い相手となるかもしれません、{name}。ですが、あなたがこの務めをしくじることはないと信じています。", "これほど短い間にここで成し遂げたことには感心しています、{name}。ここに残って私の務めを手伝ってほしいと頼めたらよいのですが……あなたにはもっと大きな務めが待っていることを、私は心の中で分かっています。\n\nOracle Treeがたった今、樹皮の一片を落としたことに気づきました。きっと果たしてほしい務めがあるのでしょう。話しかけてみてください。", 0xc112d404, 0x3f1ffacf, 0x6aee024a, 0x465cb007, 0x5c5a347c, "....." },
  [938] = { "Mist", "Oracle Tree 付近の月の泉にいる Sentinel Arynia Cloudsbreak のところまで Mist を護衛して下さい。", "sabercatの体毛は周囲の森に溶け込む独特な灰色だった。sabercatがうずくまると、背から腹にまたがるほどの深い裂傷を負い、酷く傷ついていることに気が付いた。\n\nsabercatは頭をもたげ、知性的な光を放つ青い目で見つめてきた。ついてくるよう求めているようだ。", "Mist……私のせいだ! 魔女たちに不意を突かれて……お前を連れて行かせるべきではなかった……", "ああ、ありがとうございます {name}! Mist の死ばかりが頭によぎり、忠実な相棒ともう二度と一緒になれないんじゃないか、もう二度と会えないんじゃないかと恐れていたのです。あなたがお思いになる以上にご恩を感じていますよ、ずっとずっと感謝致します。", 0x0a6d119d, 0x87fed568, 0x72d756dc, 0xeca87270, 0x849d34d3, "....." },
  [939] = { "Flute of Xavaric", "Flute of XavaricとJadefire Felbindのサンプルを$N1個、Felwood南部のEridan Bluewindのところへ持って行って下さい。", "倒したXavaricから拾った素朴な木の笛を、あなたはじっくりと調べる。\n\n節くれだった木はしっかりしているが、手の中で裏返すと、表面の渦巻きや模様が回り、動き始めるように思える。突然、あなたは恐怖に襲われる……\n\n気のせいに違いないと、あなたは頭を振る。\n\n他のsatyrsがあなたの見つけた物の手がかりを持っているかもしれない。見つけた物を、Felwood南部に住むドルイド、Eridan Bluewindのもとへ届けよう。", "どうしたのですか、{class}? 心配そうな顔をしていますね。", "いにしえの者たちの苦しみを感じます、{name}……\n\nこの品々を手にしていると、ほとんど耐えられないほどです……", 0x2912f414, 0x34540c3c, 0x5f5d80e9, 0xd5b84048, 0xed90c54b, "....." },
  [940] = { "Teldrassil", "Inscribed BarkをDarnassusのArch Druid Fandral Staghelmのところへ届ける。", "森があなたの勇敢な功績をささやいていますよ、{name}。harpiesが巣を追われるのを感じると、森にはより大きな静けさが広がり、そこに住む生き物たちは再び安心できるようになりました。大ドルイドのもとへ別の使者を送ることを恐れていましたが、あなたなら私の伝言を無事に届けてくれると分かっています。\n\nこれを彼に届けてください。そして、森がその小道を通って、石の森まであなたを無事に導いてくれることを知っておいてください。", "ふむ……あなたは森の霊を強く宿してやって来ましたね、{class}。Kaldoreiの大ドルイドにどのようなご用ですか？", "なぜOracle Treeがこれほど長く私に語りかけてこなかったのか、不思議に思っていました……ある問題は和らいでも、別の問題がより大きな懸念へと育っているようですね。\n\nTeldrassilでの私の務めは決して終わらず、私たちの不死も二度と戻らないのではないかと恐れています。\n\nそれでも、あなたはOracle Treeの務めを見事に果たしてくれました。その勤勉さには報いがあってしかるべきです。", 0x26414cf4, 0x3d134466, 0xd95bd925, 0xba14a37c, 0x4699ba60, "....." },
  [941] = { "心臓の植え付け", "Denalan のプランターに Tainted Heart を植えて下さい。", "心臓から不潔な苔を取り除いたものの、汚染されたままだ……。\n\nプランターに心臓を植えてみてくれ。心臓を清め癒す、滋養のある土が入っているんだ。", "この植木鉢には、Denalanが特別に用意した土が詰められている。", "プランターに心臓を置くと、なんと自ら土を掘って潜り込んだ!\n\n数秒後、心臓は清められてのたうち回りながら出てきた。手に取れと手招きし……微かに鼓動している。", 0x65f8fb52, 0xe00d7701, 0x54612342, 0xda090df6, 0x4660d6c8, "....." },
  [942] = { "うっかり者の探鉱者", "謎の化石をMenethil HarborのArchaeologist Flagongutのところへ持って行く。", "この化石は、私がかつてIronforgeで見たものに驚くほどよく似ている。Flagongutという名の考古学者が、毎年開かれるExplorers' Leagueの会合に持ってきたものだ。彼は、その化石には何らかの方法で解き放てる力が秘められていると信じていた。\n\n最後に聞いた話では、FlagongutはMenethil HarborのDeepwater Tavernにこもって、Whelgar Excavation Siteへの護衛を待っているそうだ。彼を探し出して、Remtravelの化石を見せてやってくれ。彼なら過去の秘密を明らかにしてくれるかもしれん。\n\nMenethilへ行く船はAuberdineから出ている。", "何を持ってるんだい、友よ?", "まあ！ これが遠いKalimdorの地から来たと言うのかい？\n\n驚いた！ 本当に驚いたよ！", 0xb9653d3d, 0xfc29c252, 0x961f86d3, 0x8fb7e5ca, 0xd1acd945, "....." },
  [943] = { "うっかり者の探鉱者", "Stone of ReluとFlagongut's Fossilを持ってきてほしいと、Menethil HarborのArchaeologist Flagongutは言っています。", "Prospector Whelgarは今、Wetlandsにある彼の発掘現場で元の化石を保管している。私がStone of Reluを見つけた時、これこそ化石の謎を解く鍵だと思ったんだ。\n\nWhelgarに会いに道を旅している途中、raptorに襲われて、その遺物をなくしてしまった。まだら模様の獣のどれが遺物を飲み込んだのか分からないが、取り戻してくれれば、これらの遺物の力を解き放てる。\n\nStone of Reluと、彼が持っている元の化石の両方を持ってきてくれ。", "Stone of Reluがあれば、私のfossilと、DarkshoreにあるRemtravelのfossilに隠された秘密を解き明かせるんだ、{name}。", "実に素晴らしい、{name}！\n\nさて、このstoneを使ってfossilの力を解き明かせるか確かめてみよう。", 0xb9653d3d, 0x2f21bebd, 0x53989e47, 0x7833064e, 0xa4671511, "....." },
  [944] = { "Master's Glaive", "情報を集め、Phial of Scryingを使ってScrying Bowlを作る。そのボウルを使ってOnuと話す。", "nagaがここDarkshoreにいるのは奇妙なことだ。だがもっと奇妙なのは……Twilight's Hammerだ。あの教団は、大地の太古の、太古の主たちを崇めている。遠い昔に打ち倒された主たちを。\n\n南にあるMaster's Glaiveは、そうした太古の主の一人が倒れた場所だ。\n\nそこへ行って、さらにTwilight's Hammerの信者どもを探してくれ。\n\nこのphial of scryingを持っていけ。Master's Glaiveを調べた後、これを使って占いの鉢を作るのだ。それから、その鉢を通じて私に話しかけてくれ。", "Master's Glaiveだ、{name}。\n\nそこへ行き、それからまた私と話してくれ。", "Twilight's HammerがMaster's Glaiveにいるだと？\n\n困ったことだ。\n\nあのグレイブに貫かれた古き王はとうに死んでいる。だが、だからといってその力のかけらがまだ残っていないとは限らない。\n\nTwilight's Hammerはその力を求めているに違いない。", 0xabfa3b4e, 0x950cae03, 0x671bb4a4, 0x27463bf7, 0xdb98b446, "....." },
  [945] = { "Theryluneの脱出", "Theryluneの脱出を助け、Shrine of AessinaのTherysilに妹が無事だと伝える。", "助けて！\n\nMaster's Glaiveの辺りを歩き回っていたら、この汚らしい信者たちに囲まれちゃったんだ。隠れるのが得意でよかったよ！！\n\nここから出るのを手伝ってくれない？ それと、姉のTherysilに無事だって知らせを送らなきゃ。姉は南のAshenvaleの、Shrine of Aessinaにいるんだ。", nil, "妹がどこにいたですって？？ Theryluneは体が汚れるのなんて気にしない子だけど、それにしても！ ずいぶん遠くまでさまよったものだわ。それにMaster's Glaiveは不健全な場所なのに……\n\nとにかくありがとう、{name}。あの子が無事だと知らせてくれて、本当に親切ね。", 0x108df69c, 0x3b1c1761, 0xed177776, nil, 0x2b7ac90f, "...m." },
  [947] = { "洞窟のキノコ", "Scaber Stalkを5本とDeath Capを1個、AuberdineのBarithras Moonshadeのところへ持って行く。", "珍しいキノコが必要な薬を考案しているのですが、そのキノコはある洞窟にしか生えないのです。その洞窟はCliffspring Fallsの裏にあり、山沿いに東へ、少し北へ行ったところです。\n\n自分で行きたいところですが、Grove of the Ancientsから、あの場所には近づかないよう忠告されているのです。我らの尊き盟友たちは、あの洞窟がDarkshoreに現れた新たな悪の隠れ家だと感じ取っています。\n\nどうか、{name}、私の代わりにキノコを集めてきてください。そしてその間に洞窟を偵察して、Ancientsの懸念が正しいか確かめてください。", "私のキノコは持ってきてくれたかい、{name}? 洞窟には行ってきたかい?", "本当にありがとうございます、{name}。見事なキノコですね！\n\nそれで、Cliffspring Fallsにいたとき、Ancientsの警告を裏付けるようなものは何か見つかりましたか？\n\nAncientsは賢明ですが、今回ばかりは間違っていてほしいと願っていたのです。", 0xe674f448, 0xe01d023c, 0x2758e8e4, 0xcf4d0564, 0x4ed87853, "....." },
  [948] = { "Onu", "Grove of the AncientsのOnuと話す。", "Grove of the AncientsのAncient of LoreであるOnuが、あなたのCliffwater Fallsへの旅のことを知っていて、あなたと話したがっています。その森は南の、山々のそばにひっそりとあります。\n\nAncientsは忍耐強く賢明です、{name}。ですが、もしOnuが滝であなたが見たものについて助言を求めているのなら、急を要することなのではないかと心配です。", nil, "{name}。来たか。\n\nよい。\n\n話し合うべき……ことがある。そなたと我とでな。", 0x0014e886, 0xed0d7f6a, 0xf32fed85, nil, 0x8d028ef5, "...m." },
  [949] = { "Twilightの野営地", "Master's GlaiveにあるTwilight's Hammerの野営地で手がかりを見つける。", "Master's GlaiveにおけるTwilight's Hammerの目的は分かっていない。だが邪悪なものに違いない。\n\nGlaiveにある奴らの野営地を探ってくれ……奴らの狙いを知る手がかりになりそうなものを探すのだ。\n\n計画を立てる前に、奴らの狙いを知らねばならないのだから。", nil, "この本は古代の言語で手刷りされており、名匠の手による挿絵が添えられている。", 0x08317362, 0x27ef0e95, 0x330bad56, nil, 0x76b4c2ab, "...m." },
  [950] = { "Onuのもとへ", "取り戻したInsane ScribblesをOnuのところへ持って行く。", "Twilight Tomeを覗き込むと気が狂いそうになる。ほんの一瞬目をやっただけで文字が泳ぎ、踊り始め、かつては美しかった渦巻き模様がグロテスクな形にねじれていく。\n\nめまいに襲われる前にできたのは、insane scribblesのページを一枚破り取ることだけだった。", "{name}。戻ったか。", "混沌とした原始の魔力が、scribblesの書き付けられたこの紙片を包んでいます。この中に古き者たちの業を感じます。\n\nこれがDarkshoreにおけるTwilight's Hammerの目的を明かしてくれることを願いましょう……", 0xcaaab2e6, 0xf6b0f093, 0x4cbe9339, 0x6065f49a, 0x508596c3, "....." },
  [951] = { "Mathystra Relics", "Mathystra Relicを6個、Grove of the AncientsのOnuのところへ持って行く。", "あなたがMaster's Glaiveで見つけた羊皮紙は、古い文書の一ページです……エルフが書いたものです！ ひどく呪われ、Twilight's Hammerの堕落に汚されていますが、あの教団は古のエルフの魔法を使って、かつての主たちを私たちの世界に呼び戻そうとしているようです。\n\n北東にあるMathystraの遺跡へ行き、草むらや崩れた石の間から古の遺物を探してください。それを研究すれば、Twilight's Hammerがエルフの魔法をどう悪用しようとしているのか見抜けるかもしれません。", "{name}。Ruins of Mathystraでの探索は実りあるものだったか?", "ありがとうございます。このrelicはMathystraが輝いていた時代のものです。かつて偉大だったエルフの砦は色あせてしまいましたが、その魔力のかけらはまだ残っています。敵より先にあの地の秘密を解き明かせることを願いましょう……\n\n用心を怠らないでください、{name}。", 0x522689ce, 0x1bae28a2, 0x8ad041ac, 0xf6dded2e, 0xdf4141bd, "....." },
  [952] = { "Grove of the Ancients", "Fandralの伝言を、Auberdineの南、DarkshoreのGrove of the AncientsにいるOnuへ届ける。", "Oracle Treeのために伝言を運ぶ時間があったのなら、Auberdineの真南、DarkshoreにあるGrove of the Ancientsへ伝言を届ける役目もきっと引き受けてもらえるでしょう。\n\nおそらくヒッポグリフに乗せてもらう手配が必要になるでしょうが、あなたならきっとうまくやれると信じています。これをAncient of LoreのOnuに届けてください。私がOracle Gladeからの知らせを待っていたように、彼も私からの便りを待っていたのです。", "ああ。{class}よ。Onuはそなたをいかに手助けできようか?", "ああ。ありがとうございます、{name}。それにしても不思議なものです。大ドルイドはいつもひどく急いでおられるようです。森は、すべてが定められた時に訪れることを知っています。Shan'do Stormrageはそれを分かっておられました。", 0x44207422, 0x8512a341, 0x323a6b71, 0xee3400fd, 0xe747f116, "....." },
  [953] = { "Ameth'Aranの陥落", "Ameth'Aranとその滅亡について記された石板を調べ、DarkshoreのSentinel Tysha Moonbladeのところへ戻る。", "東にはAmeth'Aranの遺跡がある。今ではかつてその城壁の内に住んでいたHighborneの安らがぬ霊たちが棲みついているが、かつてはAzsharaの従者たちが強大な魔法を自由に操っていた場所だった。\n\n私は遺跡の調査に送られ、Ameth'Aranとその滅亡の物語が刻まれた2枚の大きな石板に出くわした。ルーン文字を読んでいると霊たちに襲われ、逃げ出してきたのだ。\n\nどうか、できるなら、私の代わりに遺跡へ赴いて石板を解読してほしい。", "あなたが石板を調べ、Ameth'Aranの陥落について知ったなら、私はその知識をAuberdineへ持ち帰り、Circle of Ancientsに伝えます。", "War of the Ancientsの頃、とりわけWell of Eternityが崩壊した時期の記録はほとんど残っていません。当時起きていた激変と破局的な出来事を考えれば、それほど驚くことではありませんが。\n\nありがとうございます、{name}。あなたのおかげで、ここでの私の仕事は終わりました。Circleに完全な報告を届けることができます。", 0x6ea45cc6, 0x4162f8d3, 0x979f8038, 0x149e3567, 0xdcc1007d, "....." },
  [954] = { "Bashal'Aran", "Bashal'Aranの遺跡にある奇妙な青いオーラの源を見つける。", "東にあるBashal'Aranの遺跡は、悪魔の手下どもに占拠されている。その一帯に住みついたspriteやsatyrどもは、あの地の魔力を糧としており、それに触れ続けることで力を増しているのだ。\n\nそれでも、奴らが近づこうとしない祠が一つあることに私は気づいた。遺跡の西側、小さな崖の上に、奇妙な青いオーラが満ちている……悪魔どもがそこを嫌がるのには、何か理由があるはずだ。\n\nそれを調べてもらいたい。", nil, "ほう……そなたのような{race}を客として迎えるという、この上なく特別な栄誉にあずかるとは、一体何の縁であろうか。今の我の連れがどんなものか、よく分かるというもの――我をもてなしてくれる高貴なるgrellやsatyrどもには失礼ながら――そなたの来訪が改善と見なせるのだからな。\n\nだが、どうか我の無礼な物言いに追い払われぬよう。礼をわきまえた相手と過ごすのは、実に何年ぶり、いや何十年ぶりのことなのだ。", 0x58cdf8a1, 0x3c376bcf, 0xaff407b3, nil, 0xb1c6dbd5, "...m." },
  [955] = { "Bashal'Aran", "Grell Earringを8個、Bashal'AranのAsterionのために手に入れる。", "我が生涯の物語を語ろうものなら、そなたの忍耐の限界をも超えてしまうに違いない。長く苦しい生涯であった、とだけ言っておこう。そして、この霊の姿こそがおそらく何よりもひどい責め苦なのだ。\n\n我は魔法によってここに縛られている。我が言葉は不誠実に聞こえるやもしれぬが、我が囚われている仕組みを突き止める手助けをしてくれるなら、言葉にできぬほど感謝すると誓おう。我を縛っているのは一つの封印だ。spriteとgrellの耳飾りを調べれば、その痕跡が見つかるやもしれぬ。", "earringsが手に入ったら、私を縛る封印の在り処を探す呪文を唱えよう。何世紀もの間、封印を破壊することで得られる自由について考え続けてきた……もしかすると、その幾世紀もが私の心を蝕み、二度と元には戻れないのかもしれない……", "いかにも……Bashal'Aranのgrellどもは我が探し求めるものを持ってはおらぬ……だが最近、それに触れたのだ。最近……とはいえ、それはそなたの時間での話で、我の時間ではない。我にとっての最近とは過去の帳の奥にまで及ぶ。ほとんど別のAgeと言ってよいほどにな……", 0x58cdf8a1, 0xb1b08f05, 0x302949d5, 0xd4d00e5b, 0x1c6e13cb, "....." },
  [956] = { "Bashal'Aran", "Ancient Moonstone Sealを手に入れ、Bashal'AranのAsterionのところへ持って行く。", "grellどもが我が永遠の牢獄を縛る封印に間近に触れていたのなら、その原因には心当たりがある。封印は、奴らを率いるsatyrの手に渡ったに違いない。\n\nそうに違いないと強く感じるのだ、{name}。satyrのうちの誰かが、きっとそれを持っている。それを手に入れてくれれば、我は牢獄の格子を抜け出す寸前にまで至り、涙を流すことであろう。", "この祠の柱は、私にとって牢獄の格子のようなものなのだ、{name}。今の私に残るどんな力でもそれを破ることはできず、私が操るどんな魔法でもそれを壊すことはできない……\n\n1000年以上もの間、私はそれを見つめ続け、考えてきた。もしついに石よりも長く生き延びたなら、自由になれるのだろうか? それとも、その時は目に見えない格子に囚われているのだろうか……", "今この手にしているのが、これほど長く我を縛ってきたものだとは……信じることさえ難しい。一刻も無駄にはすまいぞ、{name}。このsealが破壊されれば、我は再びこの世の森を自由に歩けるやもしれぬ。", 0x58cdf8a1, 0xfb2c025d, 0x0c0b89e8, 0x0eba01db, 0xc00d95ea, "....." },
  [957] = { "Bashal'Aran", "Ameth'Aranの古の炎でAncient Moonstone Sealを破壊し、Bashal'AranのAsterionのところへ戻る。", "我が牢獄を成す封印を作り出したのは、Highborneの中でも最も強大な者の一人の技であった。南にある、この地と対をなす遺跡Ameth'Aranには、今もなお青い色をした古の炎が燃え続けている。その炎の中でなら、この封印を破壊できるであろう。\n\n遺跡では用心するのだぞ、{name}……", "正直に言おう、{name}、私は恐ろしいのだ……あなたが来たことが――このすべてが――狂った心の生み出した幻にすぎないのではないかと。これがどれほどの苦しみか、分かるだろうか? 私は……頼む、急いで行ってくれ。", "我は解き放たれたぞ、{name}！ 我らの世界に訪れた変化を、今やこの目で見ることができる……我が知っていたのは断片にすぎぬ。思えば、我が最後に自由に歩いた時には、Wellはまだ健在で、Highborneは我らが愛する女王Azsharaのもとに宮廷を開いていたのだ。\n\n我が看守、かつての主人Athrikusがまだ生きているのを感じる……早くも我が絶望は、復讐の思いへと変わりつつあるぞ。", 0x58cdf8a1, 0x77a1d7fa, 0x7a4ea159, 0xfa5255d4, 0x0a963c92, "....." },
  [958] = { "Highborneの道具", "Highborne Relicを7個、AuberdineのThundris Windweaverのために取り戻す。", "{class}。頼みたいことがある。\n\nAmeth'Aranの遺跡を見たことはあるか？ まだなら、大通りの東側、少し南へ行ったところにある。かつてはそこに強大なHighborneが大勢住んでいたが、今ではその者たちの手慰みが招いた破滅の証となっている。\n\nSentinelsから聞いた話では、Highborneの霊たちは今も居残り、古の魔法の道具を振るっているという。我々が破壊できるよう、その遺物を奪い取らねばならない。", "彼らの破滅をもたらした道具も、我らの世界を滅ぼした大災厄の中で一緒に消えていればよかったのだが……それでも、過去の恐怖が未来に繰り返されぬよう、我々はできる限りのことをせねばならない。", "きっと私の気のせいなのだろうが、これらに汚らわしいHighborneの魔法の穢れがほとんど感じ取れるような気がする。これらは破壊させよう。長く眠っていたその邪悪が二度と解き放たれることのないように。", 0xf1c555fe, 0x1bf755d6, 0xc1d7eb43, 0xc63c0c84, 0x53b1da4b, "....." },
  [959] = { "波止場の厄介事", "Ratchet の Crane Operator Bigglefuzz は、Wailing Caverns に隠れ住む Mad Magglish から 99-Year-Old Port のボトルを取り戻すよう求めています。", "おおっと!\n\nご覧の通り、ちょっとした不幸な出来事があったんだ! Booty Bayから来た朝の輸送貨物が大量だったのさ。大量だったのよ! あんな大量の箱見たことない。でさ、効率よく処理しようと思って、いつもよりほんのちょびっと多めに荷降ろしを始めたわけ。その時さ。荷物が全部なだれ落ちちゃったんだ。\n\n何が起きたか把握する前に、あの厄介者……Mad Magglish が99-Year-Old Portを持ち逃げして走ってくのを見たんだ。Wailing Cavernsまでずっと追いかけたよ。でも、あそこへ入る気はさらさら無い。\n\n君なら勇敢だからあいつを見つけられるよね。", "Mad Magglishがあの99-year-old portを持ち逃げしてから、港湾長にずっと文句を言われっぱなしなんだ。どうやらあのボトルは、他でもないBaron Revilgaz本人からGazloweへの贈り物だったらしい。\n\nMad Magglishを探し出してそのportを取り戻す度胸と根気があるなら、たっぷり報酬を出すよう取り計らうよ。", "最高! しかも今ちょうど職まで失いかけてたとこだったんだよ! 今すぐ Gazlowe にこの贈り物を渡すよう手配しなきゃ。\n\nありがとう、{name}。お見事だよ!", 0x6013131a, 0x90fc1932, 0x0388702e, 0x5b209d4d, 0x2b9e98ad, "....." },
  [960] = { "Onuは瞑想中", nil, nil, nil, "あなたの務めについて瞑想しています、{name}。Twilight's Hammerとnagaがなぜここにいるのか、その理由について瞑想しているのです。\n\n準備ができたら、phial of scryingを使って占いの鉢を作ってください。そして、その鉢を通して私に連絡してください。\n\nphial of scryingをなくしてしまったのなら、もう一つ差し上げましょう。", 0x0ff81326, nil, nil, nil, 0xbfcb1ba3, ".mmm." },
  [961] = { "Onuは瞑想中", nil, nil, nil, "Twilight's Hammerの教団員が見つかったというのは気がかりです。彼らの意図について瞑想しなければなりません……\n\nさらに情報を得たら、占いの鉢を通して私に話しかけてください。鉢を作るのにphial of scryingが必要なら……もう一つ差し上げましょう。", 0x0ff81326, nil, nil, nil, 0x10632bc8, ".mmm." },
  [962] = { "Serpentbloom", "Thunder BluffのApothecary Zamahは、Serpentbloom 10株を集めるよう求めています。", "Lordaeronの偉大なるUndercityに本部を置くRoyal Apothecary Societyは、極めて特別な務めのために私をここへ送り込んだのだ、{name}。君も私に手を貸し、ひいてはForsakenの発展を目指す我らの取り組みにおいて、Dark Ladyに力を貸したいのではないかね。\n\n最近、私はSerpentbloomという珍しい植物の標本を研究した。この薬草は、量さえあれば大いなる可能性を秘めていると私は考えている。\n\nあいにく、SerpentbloomはWailing Cavernsの最も暗い奥底にしか生えていない。Barrensにある危険な洞窟だ。", "Wailing CavernsからSerpentbloomを十分に集められるか、楽しみにしている。多くの者に命じて行かせたが、誰一人戻ってこなかったのだ。", "ああ、素晴らしい標本です。よくやって下さいましたね、{name}。", 0xea89f502, 0x5cf671d6, 0xd4d08318, 0xb23d9d2a, 0x898d5dc4, "....." },
  [963] = { "かくも永き愛のため", "Anaya Dawnrunnerの魂を解放し、彼女の首飾りをAuberdineにいるCerellean Whiteclawに届けてください。", "Well of Eternityの戦いによりAmeth'Aranが滅ぼされ、住人も死に絶えたと聞き及ぶ。我が恋人Anayaもまた。\n\nだが数千年を経た今になってAnayaのことを夢にみるとは、私自身思いもしなかった。Darkshoreの森をあてもなく歩き、そしてこの目で見たのだ…我が最愛の人の魂が、幽霊となり未だAmeth'Aranの廃墟をさまよっているのを。\n\n彼女を解放してやりたいのだが、私にはとてもできない。そのためには魂を滅ぼさねばならないのだ。", "深い悲しみを胸に、私はShan'do Stormrageに従って眠りにつき、その悲しみを夢へと携えて、何千年もの時が過ぎるあいだ眠り続けた。", "礼を言う、{name}。私自身が為せればもっと良かったのだろうが…。そんな状態で何千年も過ごさせてしまった最愛の人に手を下すなど、できようはずもなかったのだ。\n\n頼む。一人にしてくれないか。", 0xeea4b9a0, 0x229907e1, 0x038cd4bb, 0x18987e92, 0x1a264e3b, "....." },
  [964] = { "Skeletal Fragments", "Western PlaguelandsのBulwarkにいるApothecary Dithersに、Skeletal Fragment 15個を渡して下さい。", "Scholomanceの鍵はSkeleton Keyと呼ばれている。骸骨の遺骸から――実のところ、いくつもの骸骨からだが――鍛え上げ、ふさわしい型の中で、最も強い金属だけを使って硬化させねばならない。そして、生まれつきScholomanceへの門を開くことのできる存在の力の印章があれば、鍵はついにその働きを果たすのだ。\n\nだがまずは第一歩からだ、{name}。鍵を鍛えるにはskeletal fragmentsが必要だ。Andorhalの中の骸骨から必要なものが手に入るはずだが、壁の外にいる骸骨でも役に立つかもしれん。", "とにかくたくさん、何度も倒すんだ、{class}。鍵の外層を作るには、ちょうどいいskeletal fragmentsがたっぷり必要になる。伊達にSkeleton Keyって呼ばれてるわけじゃないんだぜ。", "これで使えるぞ、{name}! 今度は私の番だ。これにふさわしい焼き入れを施して、いずれ通ることになる激しい鍛造の工程に耐えられるようにしよう。\n\n次の段階は、鍵に合った鋳型を手に入れることだ。Tanarisに、以前にも同じように不気味な品の鋳型を作ったことのあるゴブリンの鍛冶屋を知っている。彼はゴブリンがたいてい仕える相手のために働いている。つまり、一番高い値をつけた者のためにな。", 0x9baabfac, 0x652fec8d, 0x83a68ed3, 0x11131417, 0x9f83db8b, "....." },
  [965] = { "Tower of Althalaxx", "DarkshoreのTower of Althalaxxの近くにいるBalthule Shadowstrikeを見つける。", "ごきげんよう、若き{race}よ。私はElissa Starbreeze。Auberdineを災いから守るのが私の務めです。\n\nそのために、北東のTower of Althalaxxの周辺で起きている奇妙な出来事を見張るよう、Balthule Shadowstrikeを送り出しました。\n\n彼はとうに戻っているはずの頃です。森で思いもよらぬ危険に遭ったのではないかと心配しています。彼を見つけて、無事かどうか確かめてきていただけると大変ありがたいのですが。", nil, "Elissaが君を寄こしたのか？ それなら良い知らせを持ってきてくれたのだな。彼女に報告すべき気がかりな知らせがあったのだが、それを届ける手段がなかったのだ。", 0x6dbe45ec, 0xdb947d32, 0xf74bdde2, nil, 0x7808df32, "...m." },
  [966] = { "Tower of Althalaxx", "Worn Parchmentを4枚、Tower of Althalaxxの近くにいるBalthule Shadowstrikeのために集める。", "ウォーロックの一団が塔の周りと中に住みついている。もっと早くAuberdineに戻ってElissaに報告したかったのだが、離れている間に何か見逃してしまうのではないかと恐れたのだ。\n\nDelgrenは、そうした一団が塔に集まっているのではないかと疑っていたが、その理由は分かっていなかった。\n\nウォーロックどもが持ち歩いている羊皮紙の切れ端が何枚か私の手に入ったが、パズルを完成させるにはもっと必要だ。ただし、塔の中には入るなと忠告しておく。あそこにいるウォーロックどもははるかに強力だ！", "奴らの巻物をもっと見つけたか? 見つけてくれれば、教団の全体像をもっと組み立てられるはずだ。", "本当にありがとう、{name}。これでこのウォーロックの集まりについて何か分かるはずだ……\n\nふむ……Cult of the Dark Strandか……聞いたことのない集団だ。その来歴が分からない以上、奴らが何を企んでいるのか言い当てるのはほとんど不可能だ。\n\nもう一刻の猶予もない。すぐにDelgrenへ警告を届けなければ。", 0x6dbe45ec, 0x50a2d0dd, 0x43621fad, 0xc078402c, 0xc22bb9fd, "....." },
  [967] = { "Tower of Althalaxx", "Balthuleの手紙を、Ashenvale ForestのDelgren the Purifierへ届ける。", "私の師匠、Delgren the Purifierはパラディンで、悪魔やアンデッドの軍勢から我らの森を守るため、寛大にも力を貸してくださっています。彼は聖なる光と戦いの技について、私に多くを教えてくださいました。\n\nDelgrenは教団の活動についてすぐに知る必要があります。\n\n彼はここからずっと南、Ashenvale ForestのMaestra's Postにいます。急いでください。時が経つごとにDark Strandの脅威が増しているのではないかと心配なのです。", "私に何か用か、{class}?", "こう言ってはなんだが、使者にしてはずいぶんと装備が整っているようだね？ Balthuleは手紙が確実に私の手に届くようにしたかったのだろう。何と書いてあるか見てみよう……\n\nこれは穏やかではない知らせだ。アンデッドや悪魔の勢力が見つかれば、私はSentinelsがそれを討つのを手伝っている。\n\n最初はナイトエルフの流儀に慣れなかったが、今では同盟者として彼らを大いに尊敬するようになった。", 0x6dbe45ec, 0x6d6be3b8, 0xa0f446d1, 0xba59c4d3, 0xec7f73c4, "....." },
  [968] = { "地下に潜む力", "Book: The Powers Belowを、IronforgeのForlorn CavernにいるGerrig Bonegripのところへ持って行く。", "ひどく擦り切れて傷だらけだが、表紙に書かれたこの本の題名はまだ読める。\n\nThe Powers Below\n\n本の中には、発音できない名前が不吉な肩書き、崇拝の方法、好まれる生贄とともに列挙されている……その多くには、生きた人型の生き物が含まれている。\n\n本の表紙の裏には、こう書かれている。「Bonegrip's Runes and Dooms、The Forlorn Cavern、Ironforge。店主：Gerrig Bonegrip」\n\nBonegripがこういう本を売っているのなら、この本も買い取ってくれるかもしれない。", "いらっしゃいませ、お客様。\n\n私の書物を一冊いかがですか？", "おや、The Powers Belowの写本じゃないか。興味深い書物だよ、これは。役に立つと思う者もいるだろうね……\n\nでも、これはひどい状態だ。それにほら！ ほとんどすべてのページの余白に書き込みがある！\n\nふむ……この写本には見覚えがある。去年Bolgarに売ったものだ。君は……彼の友なのかい？ そうだろうと思ったよ。君の目の奥にも同じ炎が宿っているからね！\n\nまあ、当然ながら、Bolgarの友は私の友だ。仲間の面倒は見る、そうだろう？", 0x8858c96d, 0x4d442245, 0x931dde4e, 0x94f07e78, 0x6c99ccde, ".....", nil, nil, nil, 0xbcd83266, nil },
  [969] = { "幸運は共に", "EverlookのWitch Doctor Mau'ariのためにFrostmaul Shard 10個を集めて下さい。", "ああ、見ただけで分かるぜ。あんた、幸運のお守りを作りてえんだろ。Mau'ariには何でもお見通しさ!\n\n南へ行くと谷があって、硬い氷でできた巨人どもがいる。巨人どもが持ってることもあるが、谷で欠片を自分で集めることもいつだってできるぜ。この欠片には強い反射の力があるんだ。\n\nfrostmaul shardsを$N1個持ってきな。そしたらこの幸運のお守りはあんたのもんだ。", "shardsを持ってきたら、もっと教えてやるぜ!", "あああ、うん……御守りを作ってやろう。見てな!", 0x38a05c5d, 0xa20cc201, 0x39109701, 0x5beb497b, 0xa040c3e9, "....." },
  [970] = { "Tower of Althalaxx", "Glowing Soul Gemを手に入れ、Maestra's PostのDelgren the Purifierのところへ持ち帰る。", "Balthuleの手紙は深刻です。このCult of the Dark Strandは、取り除かねばならない私の悩みの種なのです。私はここから北東のOrdil'Aranで、Dark Strandのくずどもの一部を相手にしてきました。彼らの一人が、教団の力の秘密を宿していると思われるソウルジェムを持っています。\n\nそれを私のもとへ持ってきてください。そうすれば、中に秘められた秘密を解き明かせるでしょう。", "あのsoul gemは手に入れたか?", "ふむ、何やら闇の魔法がこの魂の石にかけられているな。中に何が閉じ込められているか、見てみようじゃないか。", 0x6dbe45ec, 0xdf5dcec0, 0xf639e0e6, 0x74cacd19, 0x0a139b17, "....." },
  [971] = { "深淵に沈む知識", "IronforgeのForlorn CavernにいるGerrig Bonegripに、Lorgalis Manuscriptを渡して下さい。", "知っての通り、私は伝承を集めている。古き伝承、強大な伝承。扉を開く伝承、そしてThose Who Sleepを目覚めさせうる伝承をな。\n\nAshenvaleのBlackfathom Deepsの底に、ある古い伝承、Lorgalis Manuscriptが眠っているという噂がある。あの場所は、とうの昔に死に絶えたエルフたちのかつての住まいだ。都が廃墟と化す前に、大いなる知識を持っていたエルフたちのな。\n\nBlackfathom Deepsでその写本を探せ。これを成し遂げれば、私は忘れはしない。たとえ……終末の日を迎えようともな。", "Ashenvaleへの旅は長く、あなたの務めは簡単ではありません。ですが、manuscriptを持ってきてくれたなら、{name}……報酬は大きなものになるでしょう。", "写本を見つけてくれたのか! 何と喜ばしい日だ! 写しを作って配れば、Lorgalisの古の知識がついに我が兄弟姉妹たちにも知られることになる!\n\n君の働きは君が思う以上のものだ、{name}。だがこの贈り物が、我らが同盟者に寄せる感謝を示してくれることを願う。", 0xadae7c9f, 0xed9d394b, 0x9d5e75c2, 0xfb9b685b, 0x2cf50e42, "....." },
  [972] = { "Water Sapta", nil, nil, nil, "水のsaptaを持って、Silverpineにある穢れた水たまりを見つけなさい、{name}。あなたの力を大いに信じていますよ。", 0xcd2fb34a, nil, nil, nil, 0x5beca969, ".mmm." },
  [973] = { "Tower of Althalaxx", "Ilkrud Magthrull's TomeをMaestra's PostのDelgren the Purifierのところへ持って行く。", "Ilkrud Magthrull。ええ、彼のことなら知っています。Ashenvale南西部の大いなる悪の地、Fire Scar Shrineを住処とする強力なオークのウォーロックです。\n\nこれまでは厄介者程度にすぎず、私も相手にしてこなかったのですが、どうやら彼の最期の時が来たようです。", "少し動揺しているようだな、{name}。大丈夫か?", "今日の君の働きは実に見事だった、{name}。あれほどの力を持つウォーロックに立ち向かったのだから、大いに誇りに思っていい。\n\nさて、Ilkrudの書き物から何が分かるか見てみよう。", 0x6dbe45ec, 0xbec21fbf, 0xa5e7b8bb, 0x3e2447c6, 0xca5719ec, "....." },
  [974] = { "源の発見", "Un'Goro CraterのKrakleは、Fire Plume Ridgeで一番熱い場所を見つけてほしいと言っています。\n\n熱い場所を見つけたら、温度計を右クリックして温度を調べて下さい。一番熱い場所が見つかるまで探し続けて下さい。", "ここの温泉は、私にとって謎なんです。この熱はどこから来るのでしょう?\n\n泉がFire Plume Ridgeにとても近いことを考えると、あの火山が何か関係しているんじゃないかと思えてなりません。火山の温度を測るために温度計を作ったので、一番熱い場所を見つけたいんです。測定値はKraklenheit度で表示されますよ!\n\nさあ、これを持っていって、あの尾根で熱い場所を見つけたら、そのたびに温度を測ってください!", "自分で行きたいところなんだけど……そこのfire elementalがちょっと怖くてさ!", "ええ、火山の温度と温泉との間には確かに相関関係が見られます。計算式が正確かどうか見直さなければなりませんが、どうやら距離と熱が伝わる速さは……ふむ……", 0x2732aee4, 0x6f4976aa, 0xd65ac961, 0x790f3ead, 0xdc7bf6c7, "....." },
  [975] = { "Cache of Mau'ari", "幸運の御守りを受け取るには、すぐにWitch Doctor Mau'ariに話しかけて下さい。", "さて、このお守りを渡す前に、使い方を説明しとかなきゃな。\n\nお守りを持ち歩いてりゃ、戦った相手から特別な品が落ちるようになる。お守りを持ってなけりゃ、そいつは見つからねえ。分かったか?\n\nその特別な品は名前で分かる――E'koって呼ばれてるんだ。そいつを見つけたら、このMau'ariのとこに持ってきな。力になってやるよ。\n\nお守りの支度をするから、ここで待ってな。", nil, "さあこれだよ、{name}。覚えておきな、あんたこれを持ち歩くんだよ。荒野に戻って、物が見つけられるか試してみたらどうだね?", 0x77f0c3b3, 0xd32cef85, 0x1d7b538f, nil, 0x0e25b44d, "...m." },
  [976] = { "Auberdineへの補給物資", "FeeroをAshenvale Forestの中で無事に送り届けた後、Maestra's PostのDelgren the Purifierと話す。", "Delgrenに、AuberdineのSentinel Starbreezeへ伝言と物資を届けるよう頼まれたのですが、一人で出発するのは気が進まないのです。森では危険な敵が動いていますし、この物資と情報が悪しき者の手に渡る危険は冒したくありません。\n\nあなたや他の方々が護衛を務めてくださるなら、今すぐ出発できます。あなたに守っていただければ、きっとこの品々を無事にAuberdineまで届けられるでしょう。", "Sentinelsは、Darkshoreで守りを固めるための物資を大いに必要としています。", "今日はよくやってくれた、{class}。Auberdineを助けるために送った品々は、森にはびこる闇の脅威に対処するのにすぐ役立つだろう。\n\n心からの感謝とともに、これを受け取ってくれ。", 0xcbd0f669, 0x33bf359a, 0x88ce1007, 0x30b8fa32, 0xde942b67, "....." },
  [977] = { "イエティ、いるの?", "EverlookのUmi Rumplesnickerに、Pristine Yeti Horn 2本を集めてあげて下さい。", "機械の可動部分を覆うのに必要なものはそろったから、あとは一つだけ。いや、実は2つだな。2本の角だ!\n\nice thistle patriarchsとmatriarchsの角が一番大きいから、もちろん欲しいのはそいつらのだ。その種類のyetiは南東の洞窟に棲んでる。たくさんいるから、見つけるのに苦労はしないはずだよ。\n\nいいかい、一番見栄えのいいやつだけだぞ――傷だらけの角や折れた角はごめんだからな!", "毛皮の取り付けはもうすぐ終わるよ、{name}。お願いだから、hornsを持って急いで戻ってきて!", "友達に見せるのが待ちきれないよ! さあ、これを取り付ける間、少し待っててね……\n\n完璧!", 0xf5c82ef5, 0xf00629ec, 0xf794f4a6, 0x9e4eebca, 0x3f5a2d85, "....." },
  [978] = { "月に触れたWildkin", "WinterspringでMoontouched Feathersを$N1個集め、Rut'theran VillageのErelas Amberskyのところへ戻って下さい。", "HinterlandsのWildkinの羽根には、魔法的な性質の痕跡があるようです。この力は……生き物たちが振るっているものではないようです。むしろ、その種族に本来備わっているもの――その本質そのものの一部のようなのです。\n\n研究の最中に、Winterspringの雪深い地に大勢のwildkinが棲んでいると聞きました。その生き物たちも同じ力を持っているのでしょうか？ 答えを見つける手助けをしてください、{name}。Winterspringへ行き、地面に落ちた羽根を集めてから、私のもとへ戻ってきてください。", "この力は一体どこから来たのでしょう? 答えを見つけるための正しい道筋に私たちはいると思います、{name}。", "これでfeatherを比べられる……どれどれ……", 0x93346eb5, 0xe317b8ad, 0x4fe449ae, 0x1f50ef1c, 0x23f29c32, "....." },
  [979] = { "Ranshallaを探せ", "Winterspring東部でRanshallaを見つけて下さい。", "ええ、ええ、この羽根には以前に気づいたのと同じ魔法の力が宿っているようです……何が見つかるかは分かりませんが、答えを探し続けるよう強くお勧めします、{name}。\n\n私の同僚が最近、wildkinを本来の生息地で観察するためにWinterspringへ向かいました。彼女に追いついて、何を見つけたか聞いてみてはいかがですか？", nil, "やあ！ Erelasに言われて来たの？ よかった、ちょうど洞窟まで出かける支度をしていたところなんだ。一緒に来てくれるなら大歓迎だよ。", 0x71e9e89f, 0x355d3f50, 0x3382ee83, nil, 0x40a10506, "...m." },
  [980] = { "新たな泉", "Winterspringへ行き、Donova Snowdenと話して下さい。", "さて、ここからずっと北のWinterspringという場所にも温泉があると聞きました。不思議なことに、その近くには火山がどこにもないんです。興味深いでしょう。\n\nもっと知りたければ、Winterspringへ行って私の友人と話してみてください。名前はDonova Snowdenで、今はそこの温泉のそばに滞在しています。\n\n温度計のこと、手伝ってくれて本当にありがとう!それじゃ、また!", nil, "あら、{name}。ええ、Krakleがあなたに言ったことは本当よ……", 0x3283b829, 0x672db423, 0x34c712d3, nil, 0xda6a4eef, "...m." },
  [981] = { "Althalaxxの塔", "Maestra's PostのDelgren the Purifierと話して下さい。", "これだけの働きをしたのだから、あなたは十分な報酬を受けるに値します。Delgrenのもとへ戻り、Athrikus Narassinがあなたの手で息絶え、Cult of the Dark Strandが打ち負かされ散り散りになったと伝えてください。", nil, "あなたならこの務めを果たせると分かっていました、{name}。\n\nあなたの前には偉大な功績が待っているのを感じます。あなたはこの地を苦しめる多くの過ちを正すことでしょう。私の祝福と、この贈り物をお持ちなさい、{name}。", 0x6dbe45ec, 0x01697167, 0xd28e1f05, nil, 0xda5abf55, "...m." },
  [982] = { "深き海、広き海", "AuberdineのGorbold Steelhandのために、Silver Dawning's LockboxとMist Veil's Lockboxを回収する。どちらも村の北にある難破船の残骸の中で見つかるはずだ。", "ここから北、Darkshoreの沖に、2隻の難破船がある――Silver DawningとMist Veilだ。少し前、どちらの船も広い海を渡ってAuberdineへ向かう途中、忌々しいmurlocどもにやられてしまった。今では奴らの戦利品として海の底に沈んでいる。\n\n両船の船長はあの夜助からなかった。航海日誌や他の遺品は、今も海の底のlockboxに入ったままだ。それを回収してきてほしい。この辺りにまだ残っている乗組員たちにとって、大きな意味があるだろうからな。", "あの船の船長たちは立派なナイトエルフで、与えられた運命よりもましな結末を迎えるべきだった。彼らの遺品を弔うことが、その魂を安らかに眠らせる一番の方法かもしれない。", "ここAuberdineの我々に大きな貢献をしてくれたな、若いの。彼らの遺品はきちんと扱うようにしよう。\n\nそしてお前には、これを受け取ってほしい。物事を正す勇気を持った者に、せめてこれくらいはさせてくれ。", 0x7355073d, 0xcfdd6269, 0x145f3c4e, 0x2b87f83b, 0x1cb94298, ".....", nil, nil, nil, nil, 0xbe9c2983 },
  [983] = { "Buzzbox 827", "Crawler Legを6本集め、Buzzbox 827に入れる。", "やあ！ 僕の最新の発明、buzzboxを手伝ってよ。遠くにいる人と話せるんだ！\n\nもう見かけたかもしれないね、レバーのついた箱だよ。唯一の問題は、しょっちゅう手入れが必要なことなんだ。\n\n一つ一つ違う不具合を抱えてるんだけど、僕はすごく賢い決断をしたんだ。それぞれの機械を直すのにちょうどいい部品を持った生き物の近くに、一つずつ置いておいたのさ。今はBuzzbox 827が調子悪いんだ。Auberdineのすぐ南、本当に近くだよ。直すにはCrawler Legsが6本要るんだ。お礼はするからさ……", "Buzzbox 827は不気味なほど静まり返っている。ひとつだけ点滅するランプが、収納箱に6本のCrawler Legsを入れる必要があることを示している。", "Crawler Legsを機械の中に入れると、歯車がきしみ始める音が聞こえる。Buzzboxから響くガンガンという音からすると、Crawler Legsはあるべき場所に収まっているようだ。やがて機械はうなりを上げ始め、中から小さな声が呼びかけてくるのが聞こえる。\n\n「もしもし？ ええと……もしもし！ 直してくれたんだね！ ところでこちらはWizbangだよ！ 本当にありがとう……ねえ、もう一つ直してくれる気はないかい？」", 0xed396ee3, 0xe5d8e072, 0xe3959d90, 0xd3d4bf05, 0xb8705f2d, "....." },
  [984] = { "敵の規模は", "Darkshoreにある堕落したfurbolgの集落を探し出し、AuberdineのTerenthisのところへ戻ってきてください。", "俺は誓ったんだ。Teldrassilの邪悪なfurbolgの集落から兄弟たちが救出されたとき、これ以上残虐な行為は許さないってな。もう俺たちの誰にも、怪我ひとつさせはしない。\n\nDarkshoreで奴らの痕跡を幾つか見つけたんだが、拡大する兆しはまだない。だがfurbolgについては調査を続けたほうがいいと思うんだ。あいつらの集落を探して、怪しい動きが無いかどうか教えてくれないか。", "探索の調子はどうだ、{name}?", "悪い知らせだな、{name}。\n\nAuberdineにこんなに近いところにfurbolgが居るとなると、先のための準備をしなくてはいけないな。\n\n{name}、助かったよ。", 0xbceca2f9, 0xdbec2402, 0xe0cddc5b, 0xb0630bc5, 0x6c96ba7c, "....." },
  [985] = { "敵の規模は", "Blackwood Pathfinderを8体とWindtalkerを5体倒し、AuberdineのTerenthisのところへ戻ってきてください。", "{name}、お前は斥候の腕前を証明して見せた。その腕で奴らと戦えるか？\n\n正攻法を選ぶばかりが冒険者じゃない、隠密行動だって立派な戦法だぜ。\n\nこの仕事に乗ってくれるのなら、民衆にとっていま一番の脅威がこのAuberdineのすぐ南にあるfurbolgの集落なんだ。Blackwoodの一族がいる。Pathfinderを8匹とWindtalkerを5匹倒したら、俺のところへ帰ってきてくれ。", "なすべきことから手を引いてはなりません、子よ。森の生き物を殺すという考えがどれほど忌まわしいかは分かっています。けれども、今回はそれが必要なのです。森に解き放たれた穢れを癒す方法はまだ見つかっていません。見つかるまで、その進行を食い止めるために、私たちはできる限りのことをしなければならないのです。", "服についた返り血を落とせ、{name}。嘆くことなんかない。むしろ感謝するんだ。依然としてFel mossの脅威に晒されているDarkshoreで、お前はこのAuberdineの人々に降りかかる危険を減らしてくれたんだから。", 0xbceca2f9, 0x5ededd64, 0x44114385, 0xe43d21de, 0x467213bb, "....." },
  [986] = { "行方の知れぬ飼い主", "Fine Moonstalker Peltを5つ集め、AuberdineのTerenthisのところへ持ち帰ってください。", "{name}、俺の活動はお前の腕に何度も助けられた。もう一つ頼まれてくれないだろうか、Grimclawと飼い主のVolcorを助けてやって欲しいんだ。彼を捜索する間Darkshoreの生き物から見つからずに歩けるように、魔法のマントを作ってやるから。\n\nマントを作るのに、Moonstalker sireやmatriarchから取れるFine moonstalker peltが5つ要るんだ。猫どもは南のほうのWildbend Riverの近くか、もっと南のAshenvaleの近くにいるぜ。", "あのマントを作ってあげるまでは、良心にかけてVolcorを探しに行かせるわけにはいかないよ。", "これはいいものが出来そうだぜ、{name}。すぐにマントを作る準備に掛かるとしよう。\n\n少し時間をくれ。しばらくしたら取りに来てくれ。\n\nそうそう、忘れてた。マントに掛かってる魔法だが、使うと外部とのやり取りが制限される。何かするにしても喋る以上のことはするなよ。魔法が解けちまうからな。", 0x9437ffb8, 0xca85525c, 0x7310ed86, 0x249ed804, 0xbdb74a95, "....." },
  [990] = { "Ashenvaleへの旅路", "AshenvaleのRaene Wolfrunnerを見つける。", "{name}、私の主人Raene Wolfrunnerが、Ashenvaleの中にあるAstranaarの町であなたを待っています。あなたの助けがあれば、あの地に根を張った堕落を少しでも和らげられるかもしれません。\n\nここから南へ向かい、道から離れないように――その通りに進めば、迷わずたどり着けるでしょう。", nil, "ああ、Darkshoreから来た{class}だな。Selarinはよくぞこれほど早くあなたをここへ寄こしてくれた、{name}。このような切迫した状況での訪問でなければよかったのだが。あなたの助けがあれば、事態を好転させられるかもしれない。\n\nまずはAstranaarのほかの住人たちと話すことから始めるといい。あなたの助けを必要としている者がきっといるはずだ。", 0x2a43ad8f, 0x98ade4fe, 0x4a28ff7a, nil, 0x275f06e9, "...m." },
  [991] = { "Raeneの浄化", "AshenvaleのTeronisを見つける。", "{name}、私の古くからの友も、ここAshenvaleでSentinelsに力を貸しているのですが、まだ戻ってこないのです。\n\n彼は、我々の民へのfurbolgの襲撃を鈍らせることができると考えた品を見つける手がかりをつかんでいました――今は亡き邪悪な魔法使いが作った杖です。\n\nここを発つ前に、彼はその杖のための宝石を探しに行くと言っていました。\n\n宝石は、西の山のふもとにあるLake Falathimの祠に隠されているかもしれないと言っていました。あの祠が占拠される前、宝石はそこに保管されていたのです。\n\nどうか私の友を見つけてください、{name}。", nil, "Teronisの遺体は島の頂上で無残な姿で横たわっている。どういうわけか、murlocたちはそれに手を出していない。\n\n遺体に刻まれた深い切り傷は、明らかにmurlocの武器と爪によるものだ。", 0x30e3be54, 0xc6c80ccb, 0x536c2270, nil, 0xe5bfb046, "...m." },
  [992] = { "Gadgetzan水調査", "Sandsorrow Watch付近の泉で未使用のダウジング装置を使って下さい。サンプルを集めたら、使用済みのダウジング装置をGadgetzanのSenior Surveyor Fizzledowserに返却して下さい。", "興味があるなら、Gadgetzan Water Companyで臨時の下級測量士のポストが一つ空いてるよ!\n\n遊牧民どもがうちの井戸を全部押さえちまったから、もっと自由に使える水源を開拓しなきゃならないんだ!砂漠にだって水はある。ただし、先に測量するだけの賢さがあるやつにだけね。\n\nこのダウジング装置を持って、Sandsorrow Watchの近くの池で水のサンプルを採ってきてくれ。あのあたりのトロールから丸見えの場所だけどね。済んだら、サンプルを採った装置を持って帰ってきてくれよ!", "おかえり、Junior Surveyor {name}! 任務はもう終わったかい?", "何だって? 何か気味の悪い虫みたいなやつに待ち伏せされた? おやおや、こいつはGadgetzan Water Companyにとって良い兆しじゃないな、まったく……\n\n砂漠の水を全部吸い上げているらしい、おかしな虫のような生き物の報告が届いていたことを、話しておくべきだったな。最初はただのでたらめだと思ったんだ。ただでさえ遊牧民どもに手を焼いているからな。奴らのいつもの悪ふざけだろうと思っていた。まあ、これで少なくとも分かったわけだ!", 0xd226ae66, 0x7df15c8f, 0x9c584e05, 0xfc79222a, 0x05840d0e, "....." },
  [993] = { "行方の知れぬ飼い主", "DarkshoreにいるVolcorを捜し出し、Enchanted Moonstalker Cloakを渡してください。", "{name}、マントが完成したぞ。さあ、Volcorを見つけてやってくれ。俺に出来るのは間に合ってくれと祈ることだけだ。\n\nマントに込めた魔法は、使った後それほど長くはもたない。５分がいいところだろう。いつ使うかはお前次第だ。俺はGrimclawを見つけるまで待つのを勧めるぜ。\n\nあいつの言ったのが正しければ、飼い主のVolcorはここから南にある洞窟にいる。Grimclawはその近くの街道でお前を待ってる。手を振って合図してやれば、飼い主のいる場所を示してくれるはずだ。", nil, "ありがたい！　Terenthisが助けを遣してくれたんだね。\n\nそれにこれはMoonstalker cloakだね…（げほっ）　うっ…痛い。ありがとう、{name}。\n\nよけようとしたんだが、Furbolgの攻撃が当たっちまってね。少し時間をくれ、回復したらもう少し話せるようになるから。", 0x9437ffb8, 0x900ee79d, 0x246b1676, nil, 0x47b3ad53, "...m." },
  [994] = { "力づくで脱出", "街道に出るまでVolcorを護衛し、AuberdineのTerenthisに報告してください。", "そうだな、{name}、強行突破だ。お前の準備ができ次第、脱出するとしよう。街道に着くまで戦闘だ。Grimclawはまだそこで待ってるはずだ。そこからは別行動にしよう。\n\nTerenthisがお前から話を聞きたがってると思うから、脱出したらまっすぐAuberdineを目指してくれ。", nil, "{name}！　やり遂げてくれたんだな。お前がVolcorを助け出してくれたことで、俺はこのDarkshoreをはじめとした地域が瀕している危機も乗り越えられると確信できたぜ。", 0x2fba7967, 0x3c185ef0, 0x1806fdc3, nil, 0xcbf7190d, "...m." },
  [995] = { "こっそり脱出", "Furbolgの洞窟から脱出し、AuberdineのTerenthisに会ってください。", "そうだな、そうしようか…。お前がそういうなら、見つからないようにそっと抜け出そう。準備が出来たら出発しよう。\n\nいいか、脱出したらAuberdineへ戻ってTerenthisに会ってくれ。お前より早く動けるから、俺は先に行ってるよ。", "何かな、{name}？", "{name}！　やり遂げてくれたんだな。お前がVolcorを助け出してくれたことで、俺はこのDarkshoreをはじめとした地域が瀕している危機も乗り越えられると確信できたぜ。", 0xad883aaf, 0x9dd2b11a, 0x65c47290, 0xabfc0333, 0xcbf7190d, "....." },
  [997] = { "Denalan の土", "Lake Al'Ameth にいる Denalan に Rare Earth の包みを渡して下さい。", "南へ向かわれるのですか? Lake Al'Amethへ? でしたら、お願いしたいことがあるのです……。\n\n同僚の Denalan が湖の一番東でキャンプしていて、そこで Teldrassil の植物の研究や実験を行っているのです。彼に Darnassus からの貴重な土の包みを頼まれていたのですが、最近になってようやく届いたので遅くなってしまいました。\n\n包みを渡しに行ってもらえますか?", "何か私に渡すものがあるのか？", "ああ、来た来た! だいぶ待ったよ。まだ新鮮だといいが……。\n\n持ってきてくれてありがとう、{name} 。君は時間を惜しまない {race} だね。", 0xa42c6191, 0x11448aaa, 0xcc1b2d88, 0xa03be4c2, 0x1cee6b9e, ".....", nil, nil, nil, nil, 0x8a75adc2 },
  [999] = { "夢が悪夢に変わる時", nil, nil, nil, nil, 0x70340b99, nil, nil, nil, nil, ".mmmm" },
})
